window.__BOOK__['p08'].push([{"id":"b182-1","bab":"الجزء 15","sec":"نسب عدي بن نوفل وخبره","page":"ج15 ص70","text":"هو عدي بن نوفل بن أسد بن عبد العزى بن قصي بن كلاب بن مرة بن كعب بن لؤي وأمه آمنة بنت جابر بن سفيان أخت تأبط شرا وكان عمر بن الخطاب رضوان الله عليه استعمله أو عثمان بن عفان رضي الله عنه فيما أخبرنا به الطوسي عن الزبير بن بكار على حضرموت قال الزبير ودار عدي بن نوفل بين المسجد والسوق معروفة وفيها يقول إسماعيل بن يسار النسائي - خفيف -\n(إن ممشاك نحو دار عدي ... كان للقلب شقوة وفتونا)\n(إذ تراءت على البلاط فلما ... واجهتها كالشمس تعشي العيونا)\n(قال هارون قف فيا ليت أني ... كنت طاوعت ساعة هارونا)\nقد قيل إن هذه الأبيات لعمر بن أبي ربيعة\nقال الزبير كان تحت عدي بن نوفل أم عبد الله بنت أبي البختري بن هاشم بن الحارث بن أسد بن عبد العزى فغاب مدة وكتب إليها أن تشخص إليه فلم تفعل فكتب إليها قوله - مجزوء الوافر -\n(إذا ما أم عبد الله ... لم تحلل بواديه)\nذكر البيتين فقط فقال لها أخوها الأسود بن أبي البختري وهما لأب وأم أمهما عاتكة بنت أمية بن الحارث بن أسد بن عبد العزى قد بلغ الأمر هذا من ابن عمك فاشخصي إليه","topic":"نسب عدي بن نوفل وخبره","topicNo":182,"sp":0,"spl":"نسب عدي بن نوفل وخبره"},
{"id":"b183-1","bab":"الجزء 15","sec":"صوت متقارب","page":"ج15 ص71","text":"(أعيني جودا ولا تجمدا ... ألا تبكيان لصخر الندى)\n(ألا تبكيان الجري الجميل ... ألا تبكيان الفتى السيدا)\nلشعر للخنساء بنت عمرو بن الشريد ترثي أخاها صخرا والغناء لإبراهيم الموصلي ثقيل أول مطلق في مجرى البنصر عن إسحاق وفيه لابن سريج خفيف رمل بالوسطى عن عمرو والهشامي وحبش","topic":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","topicNo":183,"sp":0,"spl":"صوت متقارب"},
{"id":"b183-2","bab":"الجزء 15","sec":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","page":"ج15 ص72","text":"هي الخنساء بنت عمرو بن الحارث بن الشريد بن رياح بن يقظة بن عصية بن خفاف بن امرئ القيس بن بهثة بن سليم بن منصور بن عكرمة بن خصفة بن قيس بن عيلان بن مضر واسمها تماضر والخنساء لقب غلب عليها وفيها يقول دريد بن الصمة وكان خطبها فردته وكان رآها تهنأ بعيرا - كامل -\n(حيوا تماضر واربعوا صحبي ... وقفوا فإن وقوفكم حسبي)\n(أخناس قد هام الفؤاد بكم ... وأصابه تبل من الحب)\n(ما إن رايت ولا سمعت به ... كاليوم طالي أينق جرب)\n(متبذلا تبدو محاسنه ... يضع الهناء مواضع النقب)\nال أبو عبيدة ومحمد بن سلام لما خطبها دريد بعثت خادما لها وقالت انظري إليه إذا بال فإن كان بوله يخرق الأرض ويخد فيها ففيه بقية وإن كان بوله يسيح على وجهها فلا بقية فيه فرجعت إليها وأخبرتها فقالت لا بقية في هذا فأرسلت إليه ما كنت لأدع بني عمي وهم مثل عوالي الرماح وأتزوج شيخا فقال - وافر -\n(وقاك الله يا ابنة آل عمرو ... من الفتيان أشباهي ونفسي)\n(وقالت إنني شيخ كبير ... وما نبأتها أني ابن أمس)\n(فلا تلدي ولا ينكحك مثلي ... إذا ما ليلة طرقت بنحس)\n(تريد شرنبث القدمين شثنا ... يباشر بالعشية كل كرس)\nقالت الخنساء تجيبه - وافر\n(معاذ الله ينكحني حبركى ... يقال أبوه من جشم بن بكر)\n(ولو أصبحت في جشم هديا ... إذا أصبحت في دنس وفقر)\nهذا الشعر ترثي به أخاها صخرا وقتله زيد بن ثور الأسدي يوم ذي الأثل أخبرنا بالسبب في ذلك محمد بن الحسن بن دريد عن أبي حاتم عن أبي عبيدة وأضفت إليه رواية الأثرم عن أبي عبيدة قال غزا صخر بن عمرو وأنس ابن عباس الرعلي في بني سليم بني أسد بن خزيمة قال أبو عبيدة وزعم السلمي أن هذا اليوم يقال له يوم الكلاب ويوم ذي الأثل في بني عوف وبني خفاف وكانا متساندين وعلى بني خفاف صخر بن عمرو الشريدي وعلى بني عوف أنس بن عباس قال فأصابوا في بني أسد بن خزيمة غنائم وسبيا وأخذ صخر يومئذ بديلة امرأة قال وأصابت صخرا يومئذ طعنة طعنه رجل يقال له ربيعة بن ثور ويكنى أبا ثور فأدخل جوفه حلقا من الدرع فاندمل عليه حتى شق عنه بعد سنين وكان سبب موته قال أبو عبيدة وقال غيره بل ورد هو وبلعاء بن قيس الكناني قال وكانا\nأجمل رجلين في العرب قال فشربا عند يهودي خمار كان بالمدينة قال فحسدهما لما رأى من جمالهما وهيئتهما وقال إني لأحسد العرب أن يكون فيهم مثل هذين فسقاهما شربة جويا منها قال فمر بصخر طبيب بعد ما طال مرضه فأراه ما به فقال أشق عنك فتفيق قال فعمد إلى شفار فجعل يحميها ثم يشق بها عنه فلم ينشب أن مات قال أبو عبيدة وأما أبو بلال بن سهم فإنه قال اكتسح صخر أموال بني أسد وسبي نساءهم فأتاهم الصريخ فتبعوه فتلاحقوا بذات الأثل فاقتتلوا قتالا شديدا فطعن ربيعة بن ثور الأسدي صخرا في جنبه وفات القوم فلم يقعص وجوي منها ومرض قريبا من حول حتى مله أهله قال فسمع صخر امرأة وهي تسأل سلمى امرأة صخر كيف بعلك فقالت سلمى لا حي فيرجى ولا ميت فينعى لقينا منه الأمرين قال وزعم آخر أن التي قالت هذه المقالة بديلة الأسدية التي كان سباها من بني أسد فاتخذها لنفسه فأنشد هذا البيت - طويل -\n(ألا تلكم عرسي بديلة أوجست ... فراقي وملت مضجعي ومكاني)\nأما أبو بلال بن سهم فزعم أن صخرا حين سمع مقالة سلمى امرأته قال - طويل -\n(أرى أم صخر لا تمل عيادتي ... وملت سليمى مضجعي ومكاني)\n(وما كنت أخشى أن أكون جنازة ... عليك ومن يغتر بالحدثان)\n(أهم بأمر الحزم لو أستطيعه ... وقد حيل بين العير والنزوان)\n(لعمري لقد نبهت من كان نائما ... وأسمعت من كانت له أذنان)\n(وللموت خير من حياة كأنها ... محلة يعسوب برأس سنان)\n(وأي امرىء ساوى بأم حليلة ... فلا عاش إلا في شقا وهوان)\nلما طال عليه البلاء وقد نتأت قطعة مثل اللبد في جنبه في موضع الطعنة قالوا له لو قطعتها لرجونا أن تبرأ فقال شأنكم فأشفق عليه بعضهم فنهاهم فأبى وقال الموت أهون علي مما أنا فيه فأحموا له شفرة ثم قطعوها فيئس من نفسه قال وسمع صخر أخته الخنساء تقول كيف كان صبره فقال صخر في ذلك - طويل -\n(أجارتنا إن الخطوب تنوب ... على الناس كل المخطئين تصيب)\n(فإن تسأليني هل صبرت فإنني ... صبور على ريب الزمان صليب)\n(كأني وقد أدنوا إلي شفارهم ... من الصبر دامي الصفحتين ركوب)\n(أجارتنا لست الغداة بظاعن ... ولكن مقيم ما أقام عسيب)","topic":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","topicNo":183,"sp":1,"spl":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية"},
{"id":"b183-3","bab":"الجزء 15","sec":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","page":"ج15 ص72","text":"ن أبي عبيدة عسيب جبل بأرض بني سليم إلى جنب المدينة فقبره هناك معلم وقال أبو عبيدة فمات فدفن هناك فقبره قريب من عسيب فقالت الخنساء ترثيه - متقارب -\n(ألا ما لعينك أم ما لها ... لقد أخضل الدمع سربالها)\n(أبعد ابن عمرو من آل الشريد ... حلت به الأرض أثقالها)\n(فإن تك مرة أودت به ... فقد كان يكثر تقتالها)\n(سأحمل نفسي على خطة ... فإما عليها وإما لها)\n(فإن تصبر النفس تلق السرور ... وإن تجزع النفس أشقى لها)\nنى فيه ابن سريج خفيف رمل بالبنصر قال السلمي ليست هذه في صخر هذه إنما رثت بها معاوية أخاها وبنو مرة قتلته ولكنها قالت في صخر - بسيط\n(قذى بعينك أم بالعين عوار ... أم أقفرت إذ خلت من أهلها الدار)\n(تبكي لصخر هي العبرى وقد ثكلت ... ودونه من جديد الترب أستار)\n(لا بد من ميتة في صرفها غير ... والدهر في صرفه حول وأطوار)\n(يا صخر وراد ماء قد تناذره ... أهل الموارد ما في ورده عار)\n(مشي السبنتى إلى هيجاء معضلة ... له سلاحان أنياب وأظفار)\n(فما عجول على بو تطيف به ... لها حنينان إصغار وإكبار)\n(ترتع ما رتعت حتى إذا ادكرت ... فإنما هي إقبال وإدبار)\n(لا تسمن الدهر في أرض وإن رتعت ... فإنما هي تحنان وتسجار)\n(يوما بأوجد مني يوم فارقني ... صخر وللدهر إحلاء وإمرار)\n(فإن صخرا لوالينا وسيدنا ... وإن صخرا إذا نشتو لنحار)\n(وإن صخرا لتأتم الهداة به ... كأنه علم في رأسه نار)\nنى في هذين البيتين الأولين ابن سريج من رواية يونس\n(لم ترأه جارة يمشي بساحتها ... لريبة حين يخلي بيته الجار)\n(ولا تراه وما في البيت يأكله ... لكنه بارز بالصحن مهمار)\n(مثل الرديني لم تنفد شبيبته ... كأنه تحت طي البرد أسوار)\n(في جوف رمس مقيم قد تضمنه ... في رمسه مقمطرات وأحجار)\n(طلق اليدين بفعل الخير ذو فجر ... ضخم الدسيعة بالخيرات أمار)\n(ورفقة حار هاديهم بمهلكة ... كأن ظلمتها في الطخية القار)\nروضه ثان من البسيط العوار والعائر وجع وهو مثل الرمد وذرفت قطرت قطرا متتابعا لا يبلغ أن يكون سيلا والعبرى يقال امرأة عبرى وعابر والعبرة سخنة العين والوله ما يصيب الرجل والمرأة من شدة الجزع على الولد حول وأطوار أي تحول وتقلب وتصرف قد تناذره أي أنذر بعضهم بعضا هوله وصعوبته ويروى تبادره وقولها ما في ورده عار أرادت ما في ترك ورده عار أي لا يعير أحد إن عجز عنه من صعوبة ورده العجول الثكول والبو أن ينحر ولد الناقة ويؤخذ جلده فيحشى ويدنى من أمه فترأمه إحلاء وإمرار يقال ما أحلى ولا أمر أي ما أتى بحلوة ولا مرة والمعنى أن الدهر يأتي بالمشقة والمحبة كأنه علم في رأسه نار أي إنه مشهور والعلم الجبل وجمعه أعلام كأنه تحت طي البرد أسوار أي من لطافة بطنه وهيفه شبيه أسوار من ذهب والرديني الرمح منسوب إلى ردينة امرأة كانت تقوم الرماح أي هو معصوب البدن ليس بمهبج منحل وهذا كله من انتفاخ الجلد والسمن والاسترخاء وقال أبو عمرو مقمطرات صخور عظام والأحجار صغار ذو فجر يتفجر\nبالمعروف والدسيعة العطاء الطخية من الطخاء وهو الغيم الرقيق الذي يواري النجوم فيتحير الهادي وقالت الخنساء أيضا ترثي صخرا - وافر -\n(بكت عيني وعاودها قذاها ... بعوار فما تقضي كراها)\n(على صخر وأي فتى كصخر ... إذا ما الناب لم ترأم طلاها)\nلطلا الولد أي لم تعطف عليه من الجدب\n(فتى الفتيان ما بلغوا مداها ... ولا يكدي إذا بلغت كداها)\n(لئن جزعت بنو عمرو عليه ... لقد رزئت بنو عمرو فتاها)\nنى في هذه الأبيات ابن جامع ثاني ثقيل بإطلاق الوتر في مجرى الوسطى وذكر حبش أن له أيضا فيه خفيف رمل بالبنصر\n(ترى الشم الجحاجح من سليم ... وقد بلت مدامعها لحاها)\nذا وصف السيد بالشمم فإنه لا يدنو لدناءة ولا يضع لها أنفه\n(وخيل قد كففت بجول خيل ... فدارت بين كبشيها رحاها)\nوجول خيل جولان ويقال قطعة خيل تجول أي تذهب وتجيء\n(ترفع فضل سابغة دلاص ... على خيفانة خفق حشاها)\n(وتسعى حين تشتجر العوالي ... بكأس الموت ساعة مصطلاها)\n(محافظة ومحمية إذا ما ... نبا بالقوم من جزع لظاها)\n(فتتركها قد اشتجرت بطعن ... تضمنه إذا اختلفت كلاها)\n(هنالك لو نزلت بآل صخر ... قرى الأضياف سخنا من ذراها)\n(فمن للضيف إن هبت شمال ... مزعزعة يجاوبها صداها)\n(وألجأ بردها الأشوال حدبا ... إلى الحجرات بارزة كلاها)","topic":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","topicNo":183,"sp":2,"spl":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية"},
{"id":"b183-4","bab":"الجزء 15","sec":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","page":"ج15 ص72","text":"(أمطعمكم وحاملكم تركتم ... لدى غبراء منهدم رجاها)\n(ليبك عليك قومك للمعالي ... وللهيجاء إنك ما فتاها)\n(وقد فوزت طلعة فاستراحت ... فليت الخيل فارسها يراها)\nقال خفاف بن عمير يرثي صخرا ومعاوية ابني عمرو ورجالا منهم أصيبوا - وافر\n(تطاول همه ببراق سعر ... لذكراهم وأي أوان ذكر)\n(كأن النار تخرجها ثيابي ... وتدخل بعد نوم الناس صدري)\n(لباتت تضرب الأمثال عندي ... على ناب شربت بها وبكر)\n(وتنسى من أفارق غير قال ... وأصبر عنهم من آل عمرو)\n(وهل تدرين أن ما رب خرق ... رزئت مبرأ بقصاص وتر)\n(أخي ثقة إذا الضراء نابت ... وأهل حباء أضياف ونحر)\n(كصخر للسرية غادروه ... بذروة أو معاوية بن عمرو)\n(وميت بالجناب أثل عرشي ... كصخر أو كعمرو أو كبشر)\n(وآخر بالنواصف من هدام ... فقد أودى ورب أبيك صبري)\n(فلم أر مثلهم حيا لقاحا ... أقاموا بين قاصية وحجر)\n(أشد على صروف الدهر إدا ... وآمر منهم فيها بصبر)\n(وأكرم حين ضن الناس خيما ... وأحمد شيمة ونشيل قدر)\n(إذا الحسناء لم ترحض يديها ... ولم يقصر لها بصر بستر)\n(قروا أضيافهم ربحا ببح ... تجيء بعبقري الودق سمر)\n(رماح مثقف حملت نصالا ... يلحن كأنهن نجوم فجر)\n(جلاها الصيقلون فأخلصوها ... مواضي كلها يفري ببتر)\n(هم الأيسار إن فحطت جمادى ... بكل صبير سارية وقطر)\n(يصدون المغيرة عن هواها ... بطعن يفلق الهامات شزر)\n(تعلم أن خير الناس طرا ... لولدان غداة الريح غبر)\n(وأرملة ومعتر مسيف ... عديم المال عجزة أم صخر)\nمما رثت به الخنساء صخرا وغني فيه - متقارب -\n(أعيني جودا ولا تجمدا ... ألا تبكيان لصخر الندى)\n(ألا تبكيان الجريء الجميل ... ألا تبكيان الفتى السيدا)\n(طويل النجاد رفيع العماد ... ساد عشيرته أمردا)\n(إذا القوم مدوا بأيديهم ... إلى المجد مد إليه يدا)\n(فنال الذي فوق أيديهم ... من المجد ثم مضى مصعدا)\n(يحمله القوم ما عالهم ... وإن كان أصغرهم مولدا)\n(ترى المجد يهوي إلى بيته ... يرى أفضل المجد أن يحمدا)\n(وإن ذكر المجد ألفيته ... تأزر بالمجد ثم ارتدى)\nونذكر الآن هاهنا خبر مقتل معاوية بن عمرو أخيهما إذ كانت أخبارهما وأخبارها يدعو بعضها إلى بعض قال أبو عبيدة حدثني أبو بلال بن سهم بن عباس بن مرداس بن أبي عامر بن حارثة بن عبد بن عبس بن رفاعة بن الحارث بن بهثة بن سليم بن منصور قال غزا معاوية بن عمرو أخو خنساء بني مرة بن سعد بن ذبيان وبني فزارة ومعه خفاف بن عمير بن الحارث وأمه ندبة سوداء وإليها ينسب فاعتوره هاشم ودريد ابنا حرملة المريان قال ابن الكلبي وحرملة هو حرملة بن الأسعر ابن إياس بن مريطة بن ضمرة بن مرة بن عوف بن سعد بن ذبيان قال أبو عبيدة فاستطرد له أحدهما ثم وقف وشد عليه الآخر فقتله فلما تنادوا قتل معاوية قال\nخفاف قتلني الله إن رمت حتى أثأر به فشد على مالك بن حمار الشمخي وكان سيد بني شمخ بن فزارة فقتله قال وهو مالك بن حمار بن حزن بن عمرو بن جابر بن عقيل بن هلال بن مازن بن فزارة فقال خفاف في ذلك - طويل -\n(فإن تك خيلي قد أصيب صميمها ... فعمدا على عين تيممت مالكا)\nعني مالك بن حمار الشمخي قال أبو عبيدة فأجمل أبو بلال الحديث قال وأما غيره فذكر أن معاوية وافى عكاظ في موسم من مواسم العرب فبينا هو يمشي بسوق عكاظ إذ لقي أسماء المرية وكانت جميلة وزعم أنها كانت بغيا فدعاها إلى نفسه فامتنعت عليه وقالت أما علمت أني عند سيد العرب هاشم بن حرملة فقال أما والله لأقارعنه عنك قالت شأنك وشأنه فرجعت إلى هاشم فأخبرته بما قال معاوية وما قالت له فقال هاشم فلعمري لا يريم أبياتنا حتى ننظر ما يكون من جهده قال فلما خرج الشهر الحرام وتراجع الناس عن عكاظ خرج معاوية بن عمرو غازيا يريد بني مرة وبني فزارة في فرسان أصحابه من بني سليم حتى إذا كان بمكان يدعى الحوزة أو الجوزة والشك من أبي عبيدة دومت عليه طير وسنح له ظبي فتطير منهما ورجع في أصحابه وبلغ ذلك هاشم بن حرملة فقال ما منعه من الإقدام إلا الجبن قال فلما كانت السنة المقبلة غزاهم حتى إذا كان في ذلك المكان سنح له ظبي وغراب فتطير فرجع ومضى أصحابه وتخلف في تسعة عشر فارسا منهم لا يريدون قتالا إنما تخلف عن عظم الجيش راجعا إلى بلاده فوردوا ماء وإذا عليه بيت","topic":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","topicNo":183,"sp":3,"spl":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","song":1},
{"id":"b183-5","bab":"الجزء 15","sec":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","page":"ج15 ص72","text":"شعر فصاحوا بأهله فخرجت إليهم امرأة فقالوا ما أنت ممن أنت قالت امرأة من جهينة أحلاف لبني سهم بن مرة بن غطفان فوردوا الماء يسقون فانسلت فأتت هاشم بن حرملة فأخبرته أنهم غير بعيد وعرفته عدتهم وقالت لا أرى إلا معاوية في القوم فقال يا لكاع أمعاوية في تسعة عشر رجلا شبهت أو أبطلت قالت بل قلت الحق ولئن شئت لأصفنهم لك رجلا رجلا قال هاتي قالت رأيت فيهم شابا عظيم الجمة جبهته قد خرجت من تحت مغفره صبيح الوجه عظيم البطن على فرس غراء قال نعم هذه صفته يعني معاوية وفرسه الشماء قالت ورأيت رجلا شديد الأدمة شاعرا ينشدهم قال ذلك خفاف بن عمير قالت ورأيت رجلا ليس يبرح وسطهم إذا نادوه رفعوا أصواتهم قال ذاك عباس الأصم قالت ورأيت رجلا طويلا يكنونه أبا حبيب ورأيتهم أشد شيء له توقيرا قال ذاك نبيشة بن حبيب قالت ورأيت شابا جميلا له وفرة حسنة قال ذاك العباس بن مرداس السلمي\nقالت ورأيت شيخا له ضفيرتان فسمعته يقول لمعاوية بأبي أنت أطلت الوقوف قال ذاك عبد العزى زوج الخنساء أخت معاوية قال فنادى هاشم في قومه وخرج وزعم المري أنه لم يخرج إليهم إلا في مثل عدتهم من بني مرة قال فلم يشعر السلميون حتى طلعوا عليهم فثاروا إليهم فلقوهم فقال لهم خفاف لا تنازلوهم رجلا رجلا فإن خيلهم تثبت للطراد وتحمل ثقل السلاح وخيلكم قد أمنها الغزو وأصابها الحفا قال فاقتتلوا ساعة وانفرد هاشم ودريد ابنا حرملة المريان لمعاوية فاستطرد له أحدهما فشد عليه معاوية وشغله واغتره الآخر فطعنه فقتله واختلفوا أيهما استطرد له وأيهما قتله وكانت بالذي استطرد له طعنة طعنه إياها معاوية ويقال هو هاشم وقال آخرون بل دريد أخو هاشم قال وشد خفاف بن عمير بن الحارث بن الشريد على مالك بن حمار سيد بني شمخ بن فزارة فقتله وقال خفاف في ذلك وهو ابن ندبة وهي أمة سوداء كانت سباها الحارث بن الشريد حين أغار على بني الحارث بن كعب فوهبها لابنه عمير فولدت له خفافا ويقال في ندبة إنها ابنة الشيطان بن بنان من بني الحارث ابن كعب فقال - طويل -\n(أقول له والرمح يأطر متنه ... تأمل خفافا إنني أنا ذلكا)\n(وقفت له جلوى وقد خام صحبتي لأبني مجدا أو لأثأر هالكا ... )\n(لدن ذر قرن الشمس حين رأيتهم ... سراعا على خيل تؤم المسالكا)\n(فلما رأيت القوم لا ود بينهم ... شريجين شتى طالبا ومواشكا)\n(تيممت كبش القوم حتى عرفته ... وجانبت شبان الرجال الصعالكا)\n(فجادت له يمنى يدي بطعنة ... كست متنه من أسود اللون حالكا)\n(أنا الفارس الحامي الحقيقة والذي ... به أدرك الأبطال قدما كذلكا)\n(فإن ينج منها هاشم فبطعنة ... كسته نجيعا من دم الجوف صائكا)\nفحقق خفاف في شعره أن الذي طعن معاوية هو هاشم بن حرملة وقالت الخنساء ترثي أخاها معاوية - طويل -\n(ألا لا أرى في الناس مثل معاوية ... إذا طرقت إحدى الليالي بداهيه)\n(بداهية يصغي الكلاب حسيسها ... وتخرج من سر النجي علانيه)\n(ألا لا أرى كفارس الورد فارسا ... إذا ما علته جرأة وغلابيه)\n(وكان لزاز الحرب عند شبوبها ... إذا شمرت عن ساقها وهي ذاكيه)\n(وقواد خيل نحو أخرى كأنها ... سعال وعقبان عليها زبانيه)\n(بلينا وما تبلى تعار وما ترى ... على حدث الأيام إلا كما هيه)\n(فأقسمت لا ينفك دمعي وعولتي ... عليك بحزن ما دعا الله داعيه)\nوقالت الخنساء في كلمة أخرى ترثيه أيضا - متقارب -\n(ألا ما لعينيك أم ما لها ... لقد أخضل الدمع سربالها)\n(أبعد ابن عمرو من آل الشريد ... حلت به الأرض أثقالها)\n(وأقسمت آسى على هالك ... وأسأل نائحة ما لها)\n(سأحمل نفسي على آلة ... فإما عليها وإما لها)\n(نهين النفوس وهون النفوس ... يوم الكريهة أبقى لها)\n(ورجراجة فوقها بيضها ... عليها المضاعف زفنا لها)\n(ككرفئة الغيث ذات الصبير ... ترمي السحاب ويرمي لها)\n(وقافية مثل حد السنان ... تبقى ويهلك من قالها)\n(نطقت ابن عمرو فسهلتها ... ولم ينطق الناس أمثالها)\n(فإن تك مرة أودت به ... فقد كان يكثر تقتالها)\n(فزال الكواكب من فقده ... وجللت الشمس أجلالها)\n(وداهية جرها جارم ... تبيل الحواصن أحبالها)\n(كفاها ابن عمرو ولم يستعن ... ولو كان غيرك أدنى لها)\n(وليس بأولى ولكنه ... سيكفي العشيرة ما عالها)\n(بمعترك ضيق بينه ... تجر المنية أذيالها)\n(وبيض منعت غداة الصباح ... تكشف للروع أذيالها)","topic":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","topicNo":183,"sp":4,"spl":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","partial":1},
{"id":"b183-6","bab":"الجزء 15","sec":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","page":"ج15 ص72","text":"(ومعملة سقتها قاعدا ... فأعلمت بالسيف أغفالها)\n(وناجية كأتان الثميل ... غادرت بالخل أوصالها)\n(إلى ملك لا إلى سوقة ... وذلك ما كان إعمالها)\n(وتمنح خيلك أرض العدو ... وتنبذ بالغزو أطفالها)\n(ونوح بعثت كمثل الإراخ ... آنست العين أسبالها)\nالتفسير عن أبي عبيدة قوله حلت به الأرض قال بعضهم حلت من الحلية أي زينت به الأرض موتاها حين دفن بها وقال بعضهم حلت من حللت الشيء والمعنى ألقت مراسيها كأنه كان ثقلا عليها قال اللفظ لفظ الاستفهام والمعنى خبر كما قال جرير - وافر -\n(ألستم خير من ركب المطايا ... وأندى العالمين بطون راح)\nال جواب أبعد في آسى أي أبعد ابن عمرو آسى وأسأل نائحة ما لها وقال أبو عبيدة هذا البيت لمية بنت ضرار بن عمرو الضبية ترثي أخاها قال أبو الحسن\nالأثرم سمعت أبا عمرو الشيباني يقول أمور الناس جارية على أذلالها أي على مسالكها واحدها ذل آلة حالة تقول فإما أن أموت وإما أن أنجو ولو قالت على ألة لم تنج لأن الألة هي الحربة هممت بنفسي قال أبو عبيدة هذا توعد قال الأصمعي كل الهموم قال الأثرم كأنها أرادت أن تقتل نفسها أبو عبيدة التكدس التتابع يتبع بعضها بعضا أي يغزو ويجاهد في الغزو كما تتوقل الوعول في الجبال عن أبي عبيدة قال الأصمعي التكدس أن تحرك مناكبها إذا مشت وكأنها تنصب إلى بين يديها وإنما وصفتها بهذا تقول لا تسرع إلى الحرب ولكن تمشي إليها رويدا وهذا أثبت له من أن يلقاها وهو يركض ويقال جاء فلان يتكدس وهي مشية من مشي الغلاظ القصار وقال أبو زياد الكلابي الكداس عطاس الضأن قال السلمي التكدس تكدس الأوعال وهو التقحم والتكدس هو أن يرمي بنفسه رميا شديدا في جريه نهين النفوس تريد غداة الكريهة وقولها أبقى لها لأنها إذا تذامرت وغشيت القتال كان أسلم لها من الانهزام كقول بشر بن أبي خازم - وافر\n(ولا ينجي من الغمرات إلا ... براكاء القتال أو الفرار)\nال بعضهم أبقى لها في الذكر وحسن القول والرجراجة التي تتمخض من كثرتها وقال الأصمعي الكرفئة وجمعها كرفىء قطع من السحاب بعضها فوق بعض وقوله ترمي السحاب أي تنضم إليه وتتصل به ويرمي لها أي ينضم إليها السحاب حتى يستوي مثل حد السنان لأنها ماضية سهلتها جئت بها سهلة وجللت الشمس أي كسفت الشمس وصار عليها مثل الجل تبيل الحواصن وهي الحوامل من النساء أولادها من شدة الفزع أي ما كان وليها ولا دنا إليها ولكنه يكفي القريب والبعيد ما عالها قال أبو عمرو عالها غلبها وقال أبو عبيدة يقال إنه ليعولني ما عالك أي يغمني ما غمك ويقال افعل كذا وكذا لا يعلك أن تأتي غيره أي لا يعجزك ويقال قد يعولك أن تفعل كذا أي قد دنا لك أن تفعل وأنشد - مخلع البسيط -\n(ضربا كما تكدس الوعول ... يعول أن أنبطها يعول)\nأي قد دنا ذلك ويقال عال كذا وكذا منك أي دنا منك ويروى وليس بأدنى ولكنه وقولها معملة إبل وقولها قاعدا أي على فرسك قال النابغة - طويل -\n(قعودا على آل الوجيه ولا حق ... )\nالأغفال ما لا سمة عليها واحدها غفل والأتان الصخرة والثميل\nبقية الماء في الصخرة والخل الطريق في الرمل يقول أعيت فتركتها هنالك ويروى\n(غادرت بالنخل أوصالها ... )\nال الأصمعي ناجية سريعة ويروى إلى ملك وإلى شأنىء تقول تقود خيلك إلى ملك أو عدو ويروى ما كان إكلالها ما صلة الإراخ بقر الوحش تقول خرجت من بيوتهن كما خرجت هذه البقر من كنسها فرحا بالمطر ومثله في الفرح بالمطر لابن الأحمر قوله - بسيط -\n(مارية لؤلؤان اللون أوردها ... طل وبنس عنها فرقد خصر)\nي قوى أنفسها المطر لما رأته ومثله - وافر -\n(ألا هلك امرؤ قامت عليه ... بجنب عنيزة البقر الهجود)\nي لم يقرن في البيوت فتسترهن البيوت بل هن ظواهر وإنما شبه اجتماع هؤلاء النساء باجتماع العين وخروجهن للمطر قال وبقر الوحش تفرح بالمطر وقال دريد يرثي معاوية أخا الخنساء لما قتلته بنو مرة - وافر -\n(ألا بكرت تلوم بغير قدر ... فقد أحفيتني ودخلت ستري)\n(فإن لم تتركي عذلي سفاها ... تلمك علي نفسك أي عصر)\n(أسرك أن يكون الدهر هذا ... علي بشره يغدو ويسري)\n(وألا ترزئي نفسا ومالا ... يضرك هلكه في طول عمري)\n(فقد كذبتك نفسك فاكذبيها ... فإن جزع وإن إجمال صبر)\n(وإن الرزء يوم وقفت أدعو ... فلم أسمع معاوية بن عمرو)\n(رأيت مكانه فعرضت بدءا ... وأي مقيل رزء يا ابن بكر)","topic":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","topicNo":183,"sp":5,"spl":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","partial":1},
{"id":"b183-7","bab":"الجزء 15","sec":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","page":"ج15 ص72","text":"(إلى إرم وأحجار وصير ... وأغصان من السلمات سمر)\nير الواحدة صيرة وهي حظيرة الغنم وقوله وأغصان من السلمات أي ألقيت على قبره\n(وبنيان القبور أتى عليها ... طوال الدهر من سنة وشهر)\n(ولو أسمعته لسرى حثيثا ... سريع السعي أو لأتاك يجري)\n(بشكة حازم لا عيب فيه ... إذا لبس الكماة جلود نمر)\nي كأن ألوانهم ألوان النمور سواد وبياض من السلاح عن أبي عبيدة\n(فإما تمس في جدث مقيما ... بمسهكة من الأرواح قفر)\n(فعز علي هلكك يا ابن عمرو ... وما لي عنك من عزم وصبر)\nال أبو الحسن الأثرم فلما دخل الشهر الحرام فيما ذكر أبو عبيدة عن أبي بلال بن سهم من السنة المقبلة خرج صخر بن عمرو حتى أتى بني مرة بن عوف ابن ذبيان فوقف على ابني حرملة فإذا أحدهما به طعنة في عضده قال لم يسمه أبو بلال بن سهم فأما خفاف بن عمير فزعم في كلمته تلك أن المطعون هاشم فقال أيكما قتل أخي معاوية فسكتا فلم يحيرا إليه شيئا فقال\nالصحيح للجريح ما لك لا تجيبه فقال وقفت له فطعنني هذه الطعنة في عضدي وشد أخي عليه فقتله فأينا قتلت أدركت ثأرك إلا أنا لم نسلب أخاك قال فما فعلت فرسه الشماء قال ها هي تلك خذها فردها عليه فأخذها ورجع فلما أتى صخر قومه قالوا له اهجهم قال إن ما بيننا أجل من القذع ولو لم أكفف نفسي إلا رغبة عن الخنا لفعلت وقال صخر في ذلك - طويل -\n(وعاذلة هبت بليل تلومني ... ألا لا تلوميني كفى اللوم ما بيا)\nال أراد تباكره باللوم ولم يرد الليل نفسه إنما أراد عجلتها عليه باللوم كما قال النمر بن تولب العكلي - مديد -\n(بكرت باللوم تلحانا ... )\nقال غيره تلومه بالليل لشغله بالنهار عنها بفعل المكارم والأضياف والنظر في الحمالات وأمور قومه لأنه قوامهم - طويل -\n(تقول ألا تهجو فوارس هاشم ... وما لي إذ أهجوهم ثم ما ليا)\n(أبى الشتم أني قد أصابوا كريمتي ... وأن ليس إهداء الخنا من شماليا)\nي من شمائلي ويروى من فعاليا\n(إذا ذكر الإخوان رقرقت عبرة ... وحييت رمسا عند لية ثاويا)\n(إذا ما امرؤ أهدى لميت تحية ... فحياك رب الناس عني معاويا)\n(وهون وجدي أنني لم أقل له ... كذبت ولم أبخل عليه بماليا)\n(فنعم الفتى أدى ابن صرمة بزه ... إذا الفحل أضحى أحدب الظهر عاريا)\nال أبو عبيدة ثم زاد فيها بيتا بعد أن أوقع بهم فقال\n(وذي أخوة قطعت أقران بينهم ... كما تركوني واحدا لا أخاليا)\nال أبو عبيدة فلما كان في العام المقبل غزاهم وهو على فرسه الشماء فقال إني أخاف أن يعرفوني ويعرفوا غرة الشماء فيتأهبوا قال فحمم غرتها قال فلما أشرفت على أدنى الحي رأوها فقالت فتاة منهم هذه والله الشماء فنظروا فقالوا الشماء غراء وهذه بهيم فلم يشعروا إلا والخيل دوائس فاقتتلوا فقتل صخر دريدا وأصاب بني مرة فقال - كامل -\n(ولقد قتلتكم ثناء وموحدا ... وتركت مرة مثل أمس المدبر)\nال الأثرم مثنى وثناء لا ينونان قال ابن عنمة الضبي - طويل -\n(يباعون بالنغران مثنى وموحدا ... )\nا ينونان لأنهما مما صرف عن جهته والوجه أن يقول اثنين اثنين وكذلك ثلاث ورباع قال صخر الغي - وافر -\n(منت لك أن تلاقيني المنايا ... أحاد أحاد في الشهر الحلال)\nقال ولا تجاوز العرب الرباع غير أن الكميت قال - متقارب\n(فلم يستريثوك حتى رميت ... فوق الرجال خصالا عشارا)\nكامل -\n(ولقد دفعت إلى دريد بطعنة ... نجلاء تزغل مثل عط المنحر)\nزغل تخرج الدم قطعا قطعا قال والزغلة الدفعة الواحدة من الدم والبول قال - سريع -\n(فأزغلت في الحلق إزغالة ... )\nقال صخر أيضا فيمن قتل من بني مرة - وافر -\n(قتلت الخالدين به وبشرا ... وعمرا يوم حوزة وابن بشر)\n(ومن شمخ قتلت رجال صدق ... ومن بدر فقد أوفيت نذري)\n(ومرة قد صبحناها المنايا ... فروينا الأسنة غير فخر)\n(ومن أفناء ثعلبة بن سعد ... قتلت وما أبيئهم بوتر)\n(ولكنا نريد هلاك قوم ... فنقتلهم ونشريهم بكسر)\nوقال صخر أيضا - طويل -\n(ألا لا أرى مستعتب الدهر معتبا ... ولا آخذ منه الرضا إن تغضبا)\n(وذي إخوة قطعت أقران بينهم ... إذا ما النفوس صرن حسرى ولغبا)\n(أقول لرمس بين أجراع بيشة ... سقاك الغوادي الوابل المتحلبا)\n(لنعم الفتى أدى ابن صرمة بزه ... إذا الفحل أمسى عاري الظهر أحدبا)","topic":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","topicNo":183,"sp":6,"spl":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","partial":1},
{"id":"b183-8","bab":"الجزء 15","sec":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","page":"ج15 ص72","text":"ال أبو عبيدة ثم إن هاشم بن حرملة خرج غازيا فلما كان ببلاد جشم بن بكر بن هوازن نزل منزلا وأخذ صفنا وخلا لحاجته بين شجر ورأى غفلته قيس ابن الأصور الجشمي فتبعه وقال هذا قاتل معاوية لا وألت نفسي إن وأل فلما قعد على حاجته تقتر له بين الشجر حتى إذا كان خلفه أرسل إليه معبلة فقتله فقالت الخنساء في ذلك قال ابن الكلبي وهي الخنساء بنت عمرو بن الحارث بن شريد بن رياح بن يقظة بن عصية بن خفاف بن امرئ القيس بن بهثة بن سليم - وافر -\n(فدى للفارس الجشمي نفسي ... وأفديه بمن لي من حميم)\n(أفديه بجل بني سليم ... بظاعنهم وبالأنس المقيم)\n(كما من هاشم أقررت عيني ... وكانت لا تنام ولا تنيم)\nال أبو عبيدة وكان هاشم بن حرملة بن صرمة بن مرة أسود العرب وأشدهم وله يقول الشاعر - رجز -\n(أحيا أباه هاشم بن حرمله ... يوم الهباتين ويوم اليعمله)\n(يقتل ذا الذنب ومن لا ذنب له ... إذ الملوك حوله مغربله)\n(وسيفه للوالدات مثكله ... )\nدثني علي بن سليمان الأخفش قال حدثني محمد بن الحسن بن الحرون قال حدثنا الكسروي عن الأصمعي قال مررت بأعرابي وهو يخضد شجرة وقد أعجبته سماحتها وهو يرتجز ويقول - رجز -\n(لو كنت إنسانا لكنت حاتما ... أو الغلام الجشمي هاشما)\nقلت من هاشم هذا قال أو لا تعرفه قلت لا قال هو الذي يقول - طويل -\n(وعاذلة هبت بليل تلومني ... كأني إذا أنفقت مالي أضيمها)\n(دعيني فإن الجود لن يتلف الفتى ... ولن يخلد النفس اللئيمة لومها)\n(وتذكر أخلاق الفتى وعظامه ... مفرقة في القبر باد رميمها)\n(سلي كل قيس هل أباري خيارها ... ويعرض عني وغدها ولئيمها)\n(وتذكر فتيانيتي وتكرمي ... إذا ذم فتيانيها وكريمها)\nقلت لا أعرفه قال لا عرفت هو الذي يقول فيه الشاعر - رجز -\n(أحيا أباه هاشم بن حرمله ... يقتل ذا الذنب ومن لا ذنب له)\n(ترى الملوك حوله مغربله ... )\nوت بسيط\n(تأبد الربع من سلمى بأحفار ... وأقفرت من سليمى دمنة الدار)\n(وقد تحل بها سلمى تحدثني ... تساقط الحلي حاجاتي وأسراري)\nلشعر للأخطل والغناء لعمر الوادي هزج بالسبابة في مجرى الوسطى وفيهما رمل بالبنصر يقال إنه لابن جامع ويقال إنه لغيره وفيهما خفيف رمل بالوسطى ذكر الهشامي أنه لحكم وذكر حبش أن فيهما لإبراهيم خفيف ثقيل أول بالوسطى ومما يغنى فيه من هذه القصيدة\n(وشارب مربح بالكأس نادمني ... لا بالحصور ولا فيها بسأر)\n(نازعته طيب الراح الشمول وقد ... صاح الدجاج وحانت وقعة الساري)\n(لما أتوها بمصباح ومبزلهم ... سمت إليهم سمو الأبجل الضاري)\nلغناء في هذه الأبيات لابن سريج خفيف رمل بالبنصر عن الهشامي وذكر غيره أنها للدلال ومنها\n(فرد تغنيه ذبان الرياض كما ... غنى الغواة بصنج عند أسوار)\n(كأنه من ندى القراص مغتمر ... بالورس أو خارج من بيت عطار)\nناه ابن سريج ولحنه من القدر الأوسط من الثقيل الأول بإطلاق الوتر في مجرى الوسطى عن إسحاق وذكر الهشامي أن لمالك فيه ثقيلا أولا ووافقه يونس في نسبته إلى مالك ولحكم في قوله - بسيط -\n(فرد تغنيه ذبان الرياض كما ... )\nبعده قوله\n(صهباء قد عنست من طول ما حبست ... في مخدع بين جنات وأنهار)\nفيف ثقيل بالبنصر ومنها\n(لسكنتني قريش في ظلالهم ... ومولتني قريش بعد إقتار)\n(قوم إذا حاربوا شدوا مآزرهم ... عن النساء ولو باتت بأطهار)\nيونس فيها لحن من كتابه ولم يجنسه وهذه القصيدة مدح بها الأخطل يزيد بن معاوية لما منع من قطع لسانه حين هجا الأنصار وكان يزيد هو الذي أمره بهجائهم فقيل إن السبب في ذلك كان تشبب عبد الرحمن بن حسان برملة بنت معاوية وقيل بل حمي لعبد الرحمن بن الحكم أخبرني الجوهري قال حدثنا عمر بن شبة قال حدثني أبو يحيى الزهري قال حدثني ابن أبي زريق قال شبب عبد الرحمن بن حسان برملة بنت معاوية فقال - خفيف -\n(رمل هل تذكرين يوم غزال ... إذ قطعنا مسيرنا بالتمني)\n(إذ تقولين عمرك الله هل شيء ... وإن جل سوف يسليك عني)\n(أم هل اطمعت منكم بابن حسان ... كما قد أراك أطمعت مني)","topic":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","topicNo":183,"sp":7,"spl":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","partial":1},
{"id":"b183-9","bab":"الجزء 15","sec":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","page":"ج15 ص72","text":"ال فبلغ ذلك يزيد بن معاوية فغضب فدخل على معاوية فقال يا أمير المؤمنين ألا ترى إلى هذا العلج من أهل يثرب يتهكم بأعراضنا ويشبب بنسائنا قال ومن هو قال عبد الرحمن بن حسان وأنشده ما قال فقال يا يزيد ليست العقوبة من أحد أقبح منها من ذوي القدرة ولكن أمهل حتى يقدم وفد الأنصار ثم ذكرني قال فلما قدموا أذكره به فلما دخلوا عليه قال يا عبد الرحمن ألم يبلغني أنك تشبب برملة بنت أمير المؤمنين قال بلى ولو علمت\nأن أحدا أشرف به شعري أشرف منها لذكرته قال وأين أنت عن أختها هند قال وإن لها لأختا قال نعم قال وإنما أراد معاوية أن يشبب بهما جميعا فيكذب نفسه قال فلم يرض يزيد ما كان من معاوية في ذلك أن يشبب بهما جميعا فأرسل إلى كعب بن جعيل فقال أهج الأنصار فقال أفرق من أمير المؤمنين ولكن أدلك على الشاعر الكافر الماهر قال من هو قال الأخطل قال فدعا به فقال أهج الأنصار قال أفرق من أمير المؤمنين فقال لا تخف شيئا أنا لك بذلك قال فهجاهم فقال - كامل -\n(وإذا نسبت ابن الفريعة خلته ... كالجحش بين حمارة وحمار)\n(لعن الإله من اليهود عصابة ... بالجزع بين صليصل وصرار)\n(قوم إذا هدر العصير رأيتهم ... حمرا عيونهم من المصطار)\n(خلوا المكارم لستم من أهلها ... وخذوا مساحيكم بني النجار)\n(إن الفوارس يعلمون ظهوركم ... أولاد كل مقبح أكار)\n(ذهبت قريش بالمكارم والعلا ... واللؤم تحت عمائم الأنصار)\nبلغ ذلك النعمان بن بشير فدخل على معاوية فحسر عن رأسه عمامته وقال يا أمير المؤمنين أترى لؤما قال لا بل أرى كرما وخيرا ما ذاك قال زعم الأخطل أن اللؤم تحت عمائمنا قال أو فعل قال نعم قال لك لسانه\nوكتب فيه أن يؤتى به فلما أتي به سأل الرسول ليدخل إلى يزيد أولا فأدخله عليه فقال هذا الذي كنت أخاف قال لا تخف شيئا ودخل على معاوية فقال علام أرسل إلى هذا الرجل وهو يرمي من وراء جمرتنا قال هجا الأنصار قال ومن زعم ذلك قال النعمان بن بشير قال لا تقبل قوله عليه وهو يدعي لنفسه ولكن تدعوه بالبينة فإن ثبت شيئا أخذته به له فدعاه بالبينة فلم يأت بها فخلى سبيله فقال الأخطل - طويل -\n(وإني غداة استعبرت أم مالك ... لراض من السلطان أن يتهددا)\n(ولولا يزيد ابن الملوك وسعيه ... تجللت حدبارا من الشر أنكدا)\n(فكم أنقذتني من خطوب حباله ... وخرساء لو يرمى بها الفيل بلدا)\n(ودافع عني يوم جلق غمرة ... وهما ينسيني السلاف المبردا)\n(وبات نجيا في دمشق لحية ... إذا هم لم ينم السليم فأقصدا)\n(يخافته طورا وطورا إذا رأى ... من الوجه إقبالا ألح وأجهدا)\n(وأطفأت عني نار نعمان بعدما ... أعد لأمر فاجر وتجردا)\n(ولما رأى النعمان دوني ابن حرة ... طوى الكشح إذ لم يستطعني وعردا)\nدثنا محمد بن العباس اليزيدي قال حدثنا أحمد بن الحارث الخراز قال حدثنا المدائني عن أبي عبد الرحمن بن المبارك قال شبب عبد الرحمن\nابن حسان بأخت معاوية فغضب يزيد فدخل على معاوية فقال يا أمير المؤمنين اقتل عبد الرحمن بن حسان قال ولم قال شبب بعمتي قال وما قال قال قال - خفيف -\n(طال ليلي وبت كالمحزون ... ومللت الثواء في جيرون)\nال معاوية يا بني وما علينا من طول ليله وحزنه أبعده الله قال إنه يقول\n(فلذاك اغتربت بالشام حتى ... ظن أهلي مرجمات الظنون)\nال يا بني وما علينا من ظن أهله قال إنه يقول\n(هي زهراء مثل لؤلؤة الغوواص ... ميزت من جوهر مكنون)\nال صدق يا بني قال إنه يقول\n(وإذا ما نسبتها لم تجدها ... في سناء من المكارم دون)\nال صدق يا بني هي هكذا قال إنه يقول\n(ثم خاصرتها إلى القبة الخضراء ... تمشي في مرمر مسنون)\nاصرتها أخذت بخصرها وأخذت بخصري قال ولا كل هذا يا بني ثم ضحك وقال أنشدني ما قال أيضا فأنشده قوله\n(قبة من مراجل نصبوها ... عند حد الشتاء في قيطون)\n(عن يساري إذا دخلت من الباب ... وإن كنت خارجا فيميني)\n(تجعل الند والألوة والعود ... صلاء لها على الكانون)\n(وقباب قد أشرجت وبيوت ... نطقت بالريحان والزرجون)\nال يا بني ليس يجب القتل في هذا والعقوبة دون القتل ولكنا نكفه بالصلة له والتجاوز","topic":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","topicNo":183,"sp":8,"spl":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية"},
{"id":"b183-10","bab":"الجزء 15","sec":"صوت خفيف","page":"ج15 ص107","text":"(هي زهراء مثل لؤلؤة الغوواص ... ميزت من جوهر مكنون)\n(وإذا ما نسبتها لم تجدها ... في سناء من المكارم دون)\nسخت من كتاب ابن النطاح وذكر الهيثم بن عدي عن ابن دأب قال حدثنا شعيب بن صفوان أن عبد الرحمن بن حسان بن ثابت كان يشبب بابنة معاوية ويذكرها في شعره فقال الناس لمعاوية لو جعلته نكالا فقال لا ولكن أداويه بغير ذلك فأذن له وكان يدخل عليه في أخريات الناس ثم أجلسه\nعلى سريره معه وأقبل عليه بوجهه وحديثه ثم قال ابنتي الأخرى عاتبة عليك قال في أي شيء قال في مدحتك أختها وتركك إياها قال فلها العتبى وكرامة أنا ذاكرها وممتدحها فلما فعل وبلغ ذلك الناس قالوا قد كنا نرى أن نسيب ابن حسان بابنة معاوية لشيء فإذا هو عن رأي معاوية وأمره وعلم من كان يعرف أنه ليس له بنت أخرى أنه إنما خدعه ليشبب بها ولا أصل لها فيعلم الناس أنه كذب على الأولى لما ذكر الثانية وقد قيل في حمل يزيد بن معاوية الأخطل على هجاء الأنصار إنه فعل ذلك تعصبا لعبد الرحمن بن الحكم بن العاص بن أمية أخي مروان بن الحكم في مهاجاته عبد الرحمن وغضبا له لما استعلاه ابن حسان في الهجاء","topic":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","topicNo":183,"sp":9,"spl":"صوت خفيف"},
{"id":"b183-11","bab":"الجزء 15","sec":"ذكر خبرهما في التهاجي والسبب في ذلك","page":"ج15 ص109","text":"أخبرني علي بن سليمان الأخفش قال حدثنا أبو سعيد السكري قال حدثنا أبو غسان دماذ عن أبي عبيدة قال أخبرني أبو الخطاب الأنصاري قال كان عبد الرحمن بن حسان خليلا لعبد الرحمن بن الحكم بن العاص مخالطا له فقيل له إن ابن حسان يخلفك في أهلك فراسل امرأة ابن حسان فأخبرت بذلك زوجها وقالت أرسل إلي إني أحبك حبا أراه قاتلي فأرسل ابن حسان إلى امرأة ابن الحكم وكانت تواصله وقال للرسول اذهب إليها وقل لها إن امرأتي تزور أهلها اليوم فزوريني حتى نخلو فزارته فقعد معها ساعة ثم قال لها قد والله جاءت امرأتي فأدخلها بيتا إلى جنبه وأمر امرأته فأرسلت إلى عبد الرحمن بن الحكم إنك ذكرت حبك إياي وقد وقع ذلك في قلبي وإن ابن حسان قد خرج اليوم إلى ضيعته فهلم فتهيأ ثم أقبل فإنه لقاعد معها إذ قالت له قد جاء ابن حسان فادخل هذا البيت فإنه لا يشعر بك فأدخلته البيت الذي فيه امرأته فلما رآها أيقن بالسوأة ووقع الشر بينهما وهجا كل واحد منهما صاحبه قال أبو عبيدة هذه رواية أبي الخطاب الأنصاري وأما قريش فإنهم يزعمون أن امرأة ابن حسان كانت تحب عبد الرحمن وتدعوه إلى نفسها فيأبى\nذلك حفظا لما بينه وبين زوجها وبلغ ذلك ابن حسان فراسل امرأة ابن الحكم حتى فضحها وبلغ ذلك ابن الحكم وقيل له إنك إذا أتيت ضيعتك أرسلت إلى ابن حسان فكان معها فأمر ابن الحكم أهله فقال عالجوا سفرة حتى أطالع مالي بمكان كذا وكذا فخرج وبعثت امرأته إلى ابن حسان فجاء كما كان يفعل ورجع ابن الحكم حين ظن أن ابن حسان قد صار عندها فاستفتح فقالت ابن الحكم والله وخبأته خلفها في بيت ودخل عبد الرحمن فبعث إلى امرأة ابن حسان إنه قد وقعت لك في قلبي مقة فأقبلي إلي الساعة فتهيأت وأقبلت حتى دخلت عليه فوضعت ثيابها وزوجها ينظر فقال لها قد كنت أكثرت الإرسال إلي فما شأنك قالت إني والله هالكة من حبك قال وزوجها يسمع وإنما أراد أن يعلمه أنها قد كانت ترسل إليه ويأبى عليها وزعم أنها هي التي قالت لابن الحكم إن ابن حسان يخلفك في أهلك فلما فرغ من كلامه وأسمعه زوجها قال لها قد جاءت امرأتي وأدخلها البيت الذي فيه ابن حسان فلما جمعهما في مكان واحد خرج عنهما فخرجا وطلق امرأته أخبرني ابن دريد قال أخبرني الرياشي قال حدثنا ابن بكير عن هشام ابن الكلبي عن خالد بن سعيد عن أبيه قال رأيت مروان بن الحكم يطوف بالبيت ويقول اللهم أذهب عني الشعر وأخوه عبد الرحمن يقول اللهم إني أسألك ما استعاذ منه فذهب الشعر عن مروان وقاله عبد الرحمن وأما هشام بن الكلبي فإنه حدث عن خالد وإسحاق ابني سعيد بن العاصي أن سبب التهاجي بينهما أنهما خرجا إلى الصيد بأكلب لهما في إمارة مروان فقال ابن الحكم لابن حسان - كامل -\n(أزجر كلابك إنها قلطية ... بقع ومثل كلابكم لم تصطد)\nفرد عليه ابن حسان\n(من كان يأكل من فريسة صيده ... فالتمر يغنينا عن المتصيد)\n(إنا أناس ريقون وأمكم ... ككلابكم في الولغ والمتردد)\n(حزناكم للضب تحترشونه ... والريف نمنعكم بكل مهند)\nم رجعا إلى المدينة فجعلا يتقارضان فقال عبد الرحمن بن الحكم في قصيدة - بسيط -\n(ومثل أمك أم العبد قد ضربت ... عندي ولي بفنائي مزهر جرم)\n(وأنت عند ذناباها تعاونها ... على القدور تحسى خاثر البرم)\nنقضها عبد الرحمن بن حسان عليه بقصيدته التي يقول فيها - بسيط -\n(يا أيها الراكب المزجي مطيته ... إذا عرضت فسائل عن بني الحكم)\n(القائلين إذا لاقوا عدوهم ... فروا فكروا على النسوان والنعم)\n(كم من أمين نصيح الجيب قال لكم ... ألا نهيتم أخاكم يا بني الحكم)\n(عن رجل لا بغيض في عشيرته ... ولا ذليل قصير الباع معتصم)\nوقال ابن حسان بسيط\n(صار الذليل عزيزا والعزيز به ... ذل وصار فروع الناس أذنابا)\n(إني لملتمس حتى يبين لكم ... فيكم متى كنتم للناس أربابا)\n(فارقوا على ظلعكم ثم انظروا وسلوا ... عنا وعنكم قديم العلم نسابا)\n(فسوف يضحك أو تعتاده ذكر ... يا بؤس للدهر للإنسان ريابا)","topic":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","topicNo":183,"sp":10,"spl":"ذكر خبرهما في التهاجي والسبب في ذلك"},
{"id":"b183-12","bab":"الجزء 15","sec":"ذكر خبرهما في التهاجي والسبب في ذلك","page":"ج15 ص109","text":"لهما نقائض كثيرة لا معنى لذكر جميعها ههنا قال دماذ وحدثني أبو عبيدة عن أبي الخطاب قال لما كثر التهاجي بينهما وأفحشا كتب معاوية يومئذ وهو الخليفة إلى سعيد بن العاص وهو عامله على المدينة أن يجلد كل واحد منهما مائة سوط قال وكان ابن حسان صديقا لسعيد وما مدح أحدا قط غيره فكره أن يضربه أو يضرب ابن عمه فأمسك عنهما ثم ولي مروان فلما قدم أخذ ابن حسان فضربه مائة سوط ولم يضرب أخاه فكتب ابن حسان إلى النعمان بن بشير وهو بالشأم وكان كبيرا مكينا عند معاوية - خفيف -\n(ليت شعري أغائب أنت بالشام ... خليلي أم راقد نعمان)\n(أية ما يكن فقد يرجع الغائب ... يوما ويوقظ الوسنان)\n(إن عمرا وعامرا أبوينا ... وحراما قدما على العهد كانوا)\n(أفهم مانعوك أم قلة الكتتاب ... أم أنت عاتب غضبان)\n(أم جفاء أم أعوزتك القراطيس ... أم أمري به عليك هوان)\n(يوم أنبئت أن ساقي رضت ... وأتاكم بذلك الركبان)\n(ثم قالوا إن ابن عمك في بلوى ... أمور أتى بها الحدثان)\n(فتئط الأرحام والود والصحبة ... فيما أتى به الحدثان)\n(إنما الرمح فاعلمن قناة ... أو كبعض العيدان لولا السنان)\nهي قصيدة طويلة فدخل النعمان على معاوية فقال له يا أمير المؤمنين إنك أمرت سعيدا أن يضرب ابن حسان وابن الحكم مائة مائة فلم يفعل ثم وليت مروان فضرب ابن حسان ولم يضرب أخاه قال فتريد ماذا قال أن تكتب إليه بمثل ما كتبت إلى سعيد فكتب إلى معاوية يعزم عليه أن يضرب أخاه مائة وبعث إلى ابن حسان بحلة فلما قدم الكتاب على مروان بعث إلى ابن حسان إني مخرجك وإنما أنا مثل والدك وما كان ما كان مني إليك إلا على سبيل التأديب لك واعتذر إليه فقال حسان ما بدا له في هذا إلا لشيء قد جاءه وأبى أن يقبل منه فأبلغ الرسول ذلك مروان فوجهه إليه بالحلة فرمى بها في الحش فقيل له حلة أمير المؤمنين وترمي بها في الحش قال نعم وما أصنع بها وجاءه قومه فأخبروه الخبر فقال قد علمت أنه لم يفعل ما فعل إلا لأمر قد حدث فقال الرسول لمروان ما تصنع بهذا قد أبى أن يعفو فهلم أخاك فبعث مروان إلى الأنصار وطلب إليهم أن يطلبوا إليه أن يضربه خمسين فإنه ضعيف فطلبوا إليه فأجابهم فأخرجه فضربه خمسين فلقي ابن حسان بعض من كان لا يهوى ما ترك من ذلك فقال له أضربك مائة ويضربه خمسين بئس ما صنعت إذ وهبتها له قال إنه عبد وإنما ضربه ما يضرب العبد نصف ما يضرب الحر فحمل هذا الكلام حتى شاع بالمدينة وبلغ ابن الحكم فشق عليه فأتى أخاه مروان فخبره الخبر وقال فضحتني لا حاجة لي فيما تركت فهلم فاقتص فضرب ابن الحكم خمسين أخرى فقال عبد الرحمن يهجو ابن الحكم - كامل\n(دع ذا وعد قريض شعرك في امرىء ... يهذي وينشد شعره كالفاخر)\n(عثمان عمكم ولستم مثله ... وبنو أمية منكم كالآمر)\n(وبنو أبيه سخيفة أحلامهم ... فحش النفوس لدى الجليس الزائر)\n(أحياؤهم عار على أمواتهم ... والميتون مسبة للغابر)\n(هم ينظرون إذا مددت إليهم ... نظر التيوس إلى شفار الجازر)\n(خزر العيون منكسي أذقانهم ... نظر الذليل إلى العزيز القاهر)\nقال ابن الحكم - وافر -\n(لقد أبقى بنو مروان حزنا ... مبينا عاره لبني سواد)\n(أطاف به صبيح في مشيد ... ونادى دعوة يابني سعاد)\n(لقد أسمعت لو ناديت حيا ... ولكن لا حياة لمن تنادي)\nقال أبو عبيدة فاعتن أبو واسع أحد بني الأسعر من بني أسد بن خزيمة لابن حسان دون ابن الحكم فهجاه وعيره بضرب ابن المعطل أباه حسان على رأسه وعيرهم بأكل الخصى فقال - وافر -\n(إن ابن المعطل من سليم ... أذل قياد رأسك بالخطام)\n(عمدت إلى الخصى فأكلت منها ... لقد أخطأت فاكهة الطعام)\n(وما للجار حين يحل فيكم ... لديكم يا بني النجار حام)\n(يظل الجار مفترشا يديه ... مخافتكم لدى ملث الظلام)\n(وينظر نظرة في مذرويه ... وأخرى في استه والطرف سام)\nال فلما عم بني النجار بالهجاء ولا ذنب لهم دعوا الله عز و جل عليه فخرج من المدينة يريد أهله فعرض له الأسد فقضقضه فقال ابن حسان في ذلك - سريع -\n(أبلغ بني الأسعر إن جئتهم ... ما بال أبناء بني واسع)\n(والليث يعلوه بأنيابه ... معتفرا في دمه الناقع)\n(إذ تركوه وهو يدعوهم ... بالنسب الداني وبالشاسع)\n(لا يرفع الرحمن مصروعكم ... ولا يوهي قوة الصارع)","topic":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","topicNo":183,"sp":11,"spl":"ذكر خبرهما في التهاجي والسبب في ذلك"},
{"id":"b183-13","bab":"الجزء 15","sec":"ذكر خبرهما في التهاجي والسبب في ذلك","page":"ج15 ص109","text":"قالت له امرأته ما دعا أحد قبلك للأسد بخير قط قال ولا نصر أحدا كما نصرني وقال ابن الكلبي كان الأخطل ومسكين الدارمي صديقين لابن الحكم فاستعان بهما على ابن حسان فهجاه الأخطل وقال له مسكين ما كنت لأهجو أحدا أو أعذر إليه فكتب إليه مسكين بقصيدته اللامية يدعوه إلى المفاخرة والمنافرة فقال في أولها - وافر -\n(ألا إن الشباب ثياب لبس ... وما الأموال إلا كالظلال)\n(فإن يبل الشباب فكل شيء ... سمعت به سوى الرحمن بال)\nهي طويلة جدا يفخر فيها بمآثر بني تميم فأجابه ابن حسان فقال - وافر -\n(أتاني عنك يا مسكين قول ... بذلت النصف فيه غير آل)\n(دعوت إلى التناضل غير قحم ... ولا غمر يطير لدى النضال)\nهي أطول من قصيدة مسكين ثم انقطع التناضل بينهما قال دماذ فحدثني أبو عبيدة قال حدثني أبو حية النميري قال حدثني الفرزدق قال كنا في ضيافة معاوية ومعنا كعب بن جعيل التغلبي فحدثني أن يزيد بن معاوية قال له إن ابن حسان فضح عبد الرحمن بن الحكم وغلبه وفضحنا فاهج الأنصار قال فقلت له أرادي أنت في الشرك أأهجو قوما نصروا رسول الله وآله وآووه ولكني أدلك على غلام منا نصراني لا يبالي أن يهجوهم كأن لسانه لسان ثور قال من هو قلت الأخطل فدعاه وأمره بهجائهم فقال على أن تمنعني قال نعم قال أبو عبيدة إن معاوية دس إلى كعب وأمره بهجائهم فدله على الأخطل فقال الأخطل قصيدته التي هجا فيها الأنصار وقد مضت ومضى خبرها وخبر النعمان بن بشير وزاد أبو عبيدة عمن روينا ذلك عنه أن النعمان بن بشير رد على الأخطل فقال - كامل\n(أبلغ قبائل تغلب ابنة وائل ... من بالفرات وجانب الثرثار)\n(فاللؤم بين أنوف تغلب بين ... كالرقم فوق ذراع كل حمار)\nال فخافه الأخطل أن يهجوه فقال فيه - وافر -\n(عذرت بني الفريعة أن هجوني ... فما بالي وبال بني بشير)\n(أفيحج من بني النجار شثن ... شديد القصريين من السحور)\nلم يرد على هذين البيتين شيئا في ذكره قال أبو عبيدة في خبره أيضا إن الأنصار لما استعدوا عليه معاوية قال لهم لكم لسانه إلا أن يكون ابني يزيد قد أجاره ودس إلى يزيد من وقته إني قد قلت للقوم كيت وكيت فأجره فأجاره فقال يزيد بن معاوية في إجارته إياه - طويل -\n(دعا الأخطل الملهوف بالشر دعوة ... فأي مجيب كنت لما دعانيا)\n(ففرج عنه مشهد القوم مشهدي ... وألسنة الواشين عنه لسانيا)","topic":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","topicNo":183,"sp":12,"spl":"ذكر خبرهما في التهاجي والسبب في ذلك — صوت خفيف"},
{"id":"b183-14","bab":"الجزء 15","sec":"صوت خفيف","page":"ج15 ص117","text":"(كان لي يا شقير حبك حينا ... كاد يقضي علي لما التقينا)\n(يعلم الله أنكم لو نأيتم ... أو قربتم أحب شيء إلينا)\nلشعر لعمر بن أبي ربيعة والغناء لحبابة جارية يزيد بن عبد الملك ولحنها ثاني ثقيل بالوسطى وجعلت مكان يا شقير يا يزيد وفي هذا\nالشعر للهذلي خفيف ثقيل أول مطلق بالوسطى وزعم عمرو بن بانة أنه للأبجر وقال الهشامي لحن الأبجر ثقيل أول بالبنصر وفيه للدارمي وابن فروخ خفيف ثقيل ولحن الدارمي فيهما مطلق في مجرى الوسطى عن إسحاق","topic":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","topicNo":183,"sp":12,"spl":"ذكر خبرهما في التهاجي والسبب في ذلك — صوت خفيف"},
{"id":"b183-15","bab":"الجزء 15","sec":"أخبار حبابة","page":"ج15 ص119","text":"كانت حبابة مولدة من مولدات المدينة لرجل من أهلها يعرف بابن رمانة وقيل ابن مينا وهو خرجها وأدبها وقيل كانت لآل لاحق المكيين وكانت حلوة جميلة الوجه ظريفة حسنة الغناء طيبة الصوت ضاربة بالعود وأخذت الغناء عن ابن سريج وابن محرز ومالك ومعبد وعن جميلة وعزة الميلاء وكانت تسمى العالية فسماها يزيد لما اشتراها حبابة وقيل إنها كانت لرجل يعرف بابن مينا أخبرني أحمد بن عبيد الله بن عمار قال حدثنا عمر بن شبة قال حدثني إسحاق بن إبراهيم الموصلي قال حدثني حاتم بن قبيصة قال وكانت حبابة لرجل يدعى ابن مينا فأدخلت على يزيد بن عبد الملك في إزار له ذنبان وبيدها دف ترمي به وتتلقاه وتتغنى - منسرح -\n(ما أحسن الجيد من مليكة والللبات ... إذ زانها ترائبها)\n(يا ليتني ليلة إذا هجع النناس ... ونام الكلاب صاحبها)\n(في ليلة لا يرى بها أحد ... يسعى علينا إلا كواكبها)\nثم خرج بها مولاها إلى إفريقية فلما كان بعد ما ولي يزيد اشتراها وروى حماد عن أبيه عن المدائني عن جرير المديني ورواه الزبير بن بكار عن إسماعيل بن أبي أويس عن أبيه قال قال لي يزيد بن عبد الملك ما تقر عيني بما أوتيت من الخلافة حتى أشتري سلامة جارية مصعب بن سهيل الزهري وحبابة جارية لاحق المكية فأرسل فاشتريتا له فلما اجتمعتا عنده قال أنا الآن كما قال القائل - طويل -\n(فألقت عصاها واستقرت بها النوى ... كما قر عينا بالإياب المسافر)\nال إسحاق وحدثني أبو أيوب عن عباية قال كانت حبابة لآل رمانة ومنهم ابتيعت ليزيد أخبرني الحسن بن علي قال حدثنا هارون بن محمد بن عبد الملك الزيات قال حدثني الزبير بن بكار قال أخبرني محمد بن سلمة عن ابن مافنه عن شيخ من أهل ذي خشب قال خرجنا نريد ذا خشب ونحن مشاة فإذا قبة فيها جارية وإذا هي تغني - مجزوء الرمل -\n(سلكوا بطن محيص ... ثم ولوا راجعينا)\n(أورثوني حين ولوا ... طول حزن وأنينا)\nال فسرنا معها حتى أتينا ذا خشب فخرج رجل معها فسألناه وإذا هي\nحبابة جارية يزيد فلما صارت إلى يزيد أخبرته بنا فكتب إلى والي المدينة يعطي كل واحد ألف درهم ألف درهم أخبرني أحمد بن عبيد الله بن عمار قال حدثنا عمر بن شبة قال حدثني إسحاق عن المدائني وروى هذا الخبر حماد بن إسحاق عن أبيه عن المدائني وخبره أتم أن حبابة كانت تسمى العالية وكانت لرجل من الموالي بالمدينة فقدم يزيد بن عبد الملك في خلافة سليمان فتزوج سعدة بنت عبد الله بن عمرو ابن عثمان على عشرين ألف دينار وربيحة بنت محمد بن علي بن عبد الله بن جعفر على مثل ذلك واشترى العالية بأربعة آلاف دينار فبلغ ذلك سليمان فقال لأحجرن عليه فبلغ يزيد قول سليمان فاستقال مولى حبابة ثم اشتراها بعد ذلك رجل من أهل إفريقية فلما ولي يزيد اشترتها سعدة امرأته وعلمت أنه لا بد طالبها ومشتريها فلما حصلت عندها قالت له هل بقي عليك من الدنيا شيء لم تنله فقال نعم العالية فقالت هذه هي وهي لك فسماها حبابة وعظم قدر سعدة عنده ويقال إنها أخذت عليها قبل أن تهبها له أن توطئ لابنها عنده في ولاية العهد وتحضرها ما تحب إذا حضرت وقيل إن أم الحجاج أم الوليد بن يزيد هي التي ابتاعتها له وأخذت عليها ذلك فوفت لها بذلك هكذا ذكر الزبير فيما أخبرنا به الحسن بن علي بن هارون ابن محمد عنه عن عمه قال ومن زعم أن سعدة اشترتها فقد أخطأ قال المدائني ثم خطب يزيد إلى أخيها خالد بنت أخ له فقال أما يكفيه أن سعدة عنده حتى يخطب إلى بنات أخي وبلغ يزيد فغضب فقدم عليه خالد يسترضيه فبينا هو في فسطاطه إذ أتته جارية لحبابة في خدمها فقالت له أم","topic":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","topicNo":183,"sp":13,"spl":"أخبار حبابة"},
{"id":"b183-16","bab":"الجزء 15","sec":"أخبار حبابة","page":"ج15 ص119","text":"داود تقرأ عليك السلام وتقول لك قد كلمت أمير المؤمنين فرضي عنك فالتفت فقال من أم داود فأخبره من معه أنها حبابة وذكر له قدرها ومكانها من يزيد فرفع رأسه إلى الجارية فقال قولي لها إن الرضا عني بسبب لست به فشكت ذاك إلى يزيد فغضب وأرسل إلى خالد فلم يعلم بشيء حتى أتاه رسول حبابة به فيمن معه من الأعوان فاقتلعوا فسطاطه وقلعوا أطنابه حتى سقط عليه وعلى أصحابه فقال ويلكم ما هذا قالوا رسل حبابة هذا ما صنعت بنفسك فقال ما لها أخزاها الله ما أشبه رضاها بغضبها قال إسحاق وحدثني محمد بن سلام عن يونس بن حبيب أن يزيد بن عبد الملك اشترى حبابة وكان اسمها العالية بأربعة آلاف دينار فلما خرج بها قال الحارث بن خالد فيها - كامل -\n(ظعن الأمير بأحسن الخلق ... وغدوا بلبك مطلع الشرق)\n(مرت على قرن يقاد بها ... تعدو أمام براذن زرق)\n(فظللت كالمقمور مهجته ... هذا الجنون وليس بالعشق)\n(يا ظبية عبق العبير بها ... عبق الدهان بجانب الحق)\nغنته حبابة في الشعر وبلغ يزيد فسألها عنه فأخبرته فقال لها غنيني به\nفغنته فأجادت وأطربته فقال إسحاق ولعمري إنه من جيد غنائها قال أبو الفرج الأصبهاني هذا غلط ممن رواه في أبيات الحارث بن خالد لأنه قالها في عائشة بنت طلحة لما تزوجها مصعب بن الزبير وخرج بها وفي أبياته يقول\n(في البيت ذي الحسب الرفيع ومن ... أهل التقى والبر والصدق)\nقد شرح ذلك في أخبار عائشة بنت طلحة قال إسحاق وأخبرني الزبيري أن يزيد اشتراها وهو أمير فلما أراد الخروج بها قال الحارث بن خالد فيها - بسيط -\n(قد سل جسمي وقد أودى به سقم ... من أجل حي جلوا من بلدة الحرم)\n(يحن قلبي إليها حين أذكرها ... وما تذكرت شوقا آب من أمم)\n(إلا حنينا إليها إنها رشأ ... كالشمس رود ثقال سهلة الشيم)\n(فضلها الله رب الناس إذ خلقت ... على النساء من أهل الحزم والكرم)\nقال فيها الشعراء فأكثروا وغنى في أشعارهم المغنون من أهل مكة والمدينة وبلغ ذلك يزيد فاستشنعه فقال هذا قبل رحلتنا وقد هممنا فكيف لو ارتحلنا وتذكر القوم شدة الفراق وبلغه أيضا أن سليمان قد تكلم في ذلك فردها ولم تزل في قلبه حتى ملك فاشترتها سعدة امرأته العثمانية ووهبتها له أخبرني ابن عمار قال حدثنا عمر بن شبة قال حدثني إسحاق قال حدثني أبو ذفافة المنهال بن عبد الملك عن مروان بن بشر بن أبي سارة مولى الوليد بن يزيد قال أول ما ارتفعت به منزلة حبابة عند يزيد أنه أقبل يوما إلى البيت الذي هي فيه فقام من وراء الستر فسمعها تترنم وتغني وتقول - خفيف\n(كان لي يا يزيد حبك حينا ... كاد يقضي علي لما التقينا)\nالشعر كان يا شقير فرفع الستر فوجدها مضطجعة مقبلة على الجدار فعلم أنها لم تعلم به ولم يكن ذاك لمكانه فألقى نفسه عليها وحركت منه قال المدائني غلبت حبابة على يزيد وتبنى بها عمر بن هبيرة فعلت منزلته حتى كان يدخل على يزيد في أي وقت شاء وحسد ناس من بني أمية مسلمة بن عبد الملك على ولايته وقدموا فيه عند يزيد وقالوا إن مسلمة إن اقتطع الخراج لم يحسن يا أمير المؤمنين أن تفتشه أو تكشفه عن شيء لسنه وحقه وقد علمت أن أمير المؤمنين لم يدخل أحدا من أهل بيته في الخراج فوقر ذلك في قلب يزيد وعزم على عزله وعمل ابن هبيرة في ولاية العراق من قبل حبابة فعملت له في ذلك وكان بين ابن هبيرة وبين القعقاع بن خالد عداوة وكانا يتنازعان ويتحاسدان فقيل للقعقاع لقد نزل ابن هبيرة من أمير المؤمنين منزلة إنه لصاحب العراق غدا فقال ومن يطيق ابن هبيرة حبابة بالليل وهداياه بالنهار مع أنه وإن بلغ فإنه رجل من بني سكين فلم تزل حبابة تعمل له حتى وليها حدثنا أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال سمعت إسحاق بن إبراهيم يحدث بهذا الحديث فحفظته ولم أحفظ إسناده وحدثنا محمد بن خلف وكيع قال حدثني أحمد بن زهير قال حدثنا مصعب الزبيري عن مصعب بن عثمان وقد جمعت روايتيهما قالا أراد يزيد بن عبد الملك أن","topic":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","topicNo":183,"sp":14,"spl":"أخبار حبابة"},
{"id":"b183-17","bab":"الجزء 15","sec":"أخبار حبابة","page":"ج15 ص119","text":"يشبه بعمر بن عبد العزيز وقال بماذا صار عمر أرجى لربه جل وعز مني فشق ذلك على حبابة فأرسلت إلى الأحوص هكذا في رواية وكيع وأما عمر بن شبة فإنه ذكر أن مسلمة أقبل على يزيد يلومه في الإلحاح على الغناء والشرب وقال له إنك وليت بعقب عمر بن عبد العزيز وعدله وقد تشاغلت بهذه الأمة عن النظر في الأمور والوفود ببابك وأصحاب الظلامات يصيحون وأنت غافل عنهم فقال صدقت والله وأعتبه وهم بترك الشرب ولم يدخل على حبابة أماما فدست حبابة إلى الأحوص أن يقول أبياتا في ذلك وقالت له إن رددته عن رأيه فلك ألف دينار فدخل الأحوص إلى يزيد فاستأذن في الإنشاد فأذن له قال إسحاق في خبره فقال الأحوص - طويل -\n(ألا لا تلمه اليوم أن يتبلدا ... فقد غلب المحزون أن يتجلدا)\n(بكيت الصبا جهدي فمن شاء لامني ... ومن شاء آسى في البكاء وأسعدا)\n(وإني وإن فندت في طلب الغنى ... لأعلم أني لست في الحب أوحدا)\n(إذا أنت لم تعشق ولم تدر ما الهوى ... فكن حجرا من يابس الصخر جلمدا)\n(فما العيش إلا ما تلذ وتشتهي ... وإن لام فيه ذو الشنان وفندا)\nالغناء لمعبد - خفيف ثقيل أول - بالبنصر وفيه رمل للغريض ويقال إنه لحبابة قال ومكث جمعة لا يرى حبابة ولا يدعو بها فلما كان يوم الجمعة قالت لبعض جواريها إذا خرج أمير المؤمنين إلى الصلاة فأعلميني فلما أراد الخروج أعلمتها فتلقته والعود في يدها فغنت البيت الأول فغطى وجهه وقال مه لا تفعلي ثم غنت\n(وما العيش إلا ما تلذ وتشتهي ... )\nعدل إليها وقال صدقت والله فقبح الله من لامني فيك يا غلام مر مسلمة أن يصلي بالناس وأقام معها يشرب وتغنيه وعاد إلى حاله وقال عمر بن شبة في حديثه فقال يزيد صدقت والله فعلى مسلمة لعنة الله وعاود ما كان فيه ثم قال لها من يقول هذا الشعر قالت الأحوص فأحضره ثم أنشده قصيدة مدحه فيها وأولها قوله - بسيط -\n(يا موقد النار بالعلياء من إضم ... أوقد فقد هجت شوقا غير منصرم)\nوهي طويلة فقال له يزيد ارفع حوائجك فكتب إليه في نحو من أربعين ألف درهم من دين وغيره فأمر له بها وقال مصعب في خبره بل استأذن الأحوص على يزيد فأذن له فاستأذن في الإنشاد فقال ليس هذا وقتك فلم يزل به حتى أذن له فأنشده هذه الأبيات فلما سمعها وثب حتى دخل على حبابة وهو يتمثل - طويل -\n(وما العيش إلا ما تلذ وتشتهي ... وإن لام فيه ذو الشنان وفندا)\nقالت له ما ردك يا أمير المؤمنين فقال أبيات أنشدنيها الأحوص فسلي ما شئت قالت ألف دينار تعطيها الأحوص فأعطاه ألف دينار","topic":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","topicNo":183,"sp":15,"spl":"أخبار حبابة","song":1,"partialRef":{"sid":"b133-14","gi":7,"vi":0,"side":0},"partial":1},
{"id":"b183-18","bab":"الجزء 15","sec":"نسبة ما في هذا الخبر من الغناء صوت بسيط","page":"ج15 ص127","text":"(يا موقد النار بالعلياء من إضم ... أوقد فقد هجت شوقا غير منصرم)\n(يا موقد النار أوقدها فإن لها ... سنا يهيج فؤاد العاشق السدم)\nلشعر للأحوص والغناء لمعبد - خفيف ثقيل أول - بالوسطى عن يونس وإسحاق وعمرو وذكر حبش أن فيه خفيف ثقيل آخر لابن جامع أخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثني علي بن القاسم بن بشير قال لما غلب يزيد بن عبد الملك أهله وأبى أن يسمع منهم كلموا مولى له خراسانيا ذا قدر عندهم وكانت فيه لكنة فأقبل على يزيد يعظه وينهاه عما قد ألح عليه من السماع للغناء والشراب فقال له يزيد فإني أحضرك هذا الأمر الذي تنهى عنه فإن نهيتني عنه بعد ما تبلوه وتحضره انتهيت وإني مخبر جواري أنك عم من عمومتي فإياك أن تتكلم فيعلمن أني كاذب وأنك لست\nبعمي ثم أدخله عليهن فغنين والشيخ يسمع ولا يقول شيئا حتى غنين - طويل -\n(وقد كنت آتيكم بعلة غيركم ... فأفنيت علاتي فكيف أقول)\nفطرب الشيخ وقال لا قيف جعلني الله فداكن يريد لا كيف فعلمن أنه ليس عمه وقمن إليه بعيدانهن ليضربنه بها حتى حجزهن يزيد عنه ثم قال له بعدما انقضى أمرهن ما تقول الآن أدع هذا أم لا قال لا تدعه أخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة قال حدثني خالد بن يزيد بن بحر الخزاعي الأسلمي عن محمد بن سلمة عن أبيه عن حماد الراوية قال كانت حبابة فائقة في الجمال والحسن وكان يزيد لها عاشقا فقال لها يوما قد استخلفتك على ما ورد علي ونصبت لذلك مولاي فلانا فاستخلفيه لأقيم معك أياما وأستمتع بك قالت فإني قد عزلته فغضب عليها وقال قد استعملته وتعزلينه وخرج من عندها مغضبا فلما ارتفع النهار وطال عليه هجرها دعا خصيا له وقال انطلق فانظر أي شيء تصنع حبابة فانطلق الخادم ثم أتاه فقال رأيتها مؤتزرة بإزار خلوقي قد جعلت له ذنبين وهي تلعب بلعبها فقال ويحك احتل لها حتى تمر بها علي فانطلق الخادم إليها فلاعبها ساعة ثم استلب لعبة من لعبها وخرج فجعلت تحضر في أثره فمرت بيزيد فوثب وهو يقول قد عزلته وهي تقول قد استعملته فعزل مولاه وولاه وهو لا يدري فمكث معها خاليا أياما حتى دخل عليه أخوه مسلمة فلامه وقال ضيعت حوائج الناس واحتجبت عنهم أترى هذا مستقيما لك وهي تسمع مقالته فغنت لما خرج طويل\n(ألا لا تلمه اليوم أن يتبلدا ... )\nفذكرت الأبيات فطرب وقال قاتلك الله أبيت إلا أن ترديني إليك وعاد إلى ما كان عليه أخبرني إسماعيل قال حدثني عمي قال حدثني إسحاق قال حدثني الهيثم بن عدي عن صالح بن حسان قال قال مسلمة ليزيد تركت الظهور وشهود الجمعة الجامعة وقعدت في منزلك مع هذه الإماء وبلغ ذلك حبابة وسلامة فقالتا للأحوص قل في ذلك شعرا فقال - طويل -\n(وما العيش إلا ما تلذ وتشتهي ... وإن لام فيه ذو الشنان وفندا)\n(بكيت الصبا جهدي فمن شاء لامني ... ومن شاء آسى في البكاء وأسعدا)\n(وإني وإن أغرقت في طلب الصبا ... لأعلم أني لست في الحب أوحدا)\n(إذا كنت عزهاة عن اللهو والصبا ... فكن حجرا من يابس الصخر جلمدا)\nال فغنتا يزيد فيه فلما فرغتا ضرب بخيزرانته الأرض وقال صدقتما صدقتما فعلى مسلمة لعنة الله وعلى ما جاء به قال وطرب يزيد فقال هاتيا فغنتاه من هذه القصيدة\n(وعهدي بها صفراء رودا كأنما ... نضا عرق منها على اللون مجسدا)\n(مهفهفة الأعلى وأسفل خلقها ... جرى لحمه ما دون أن يتخددا)\n(من المدمجات اللحم جدلا كأنها ... عنان صناع مدمج الفتل محصدا)\n(كأن ذكي المسك باد وقد بدت ... وريح خزامى طلة تنفح الندى)\nفطرب يزيد وأخذ فيه من الشراب قدره الذي كان يطرب منه ويسره ولم تره أظهر شيئا مما كان يفعله عند طربه فغنته\n(ألا لا تلمه اليوم أن يتبلدا ... فقد غلب المحزون أن يتجلدا)\n(نظرت رجاء بالموقر أن أرى ... أكاريس يحتلون خاخا فمنشدا)\n(فأوفيت في نشز من الأرض يافع ... وقد تسعف الأيفاع من كان مقصدا)\nلما غنته بهذا طرب طربه الذي تعهده وجعل يدور ويصيح الدخن بالنوى والسمك في بيطار جنان وشق حلته وقال لها أتأذنين أن أطير قالت وإلى من تدع الناس قال إليك قال وغنته سلامة من هذه القصيدة\n(فقلت ألا يا ليت أسماء أصقبت ... وهل قول ليت جامع ما تبددا)\n(وإني لأهواها وأهوى لقاءها ... كما يشتهي الصادي الشراب المبردا)\n(علاقة حب لج في سنن الصبا ... فأبلى وما يزداد إلا تجددا)","topic":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","topicNo":183,"sp":16,"spl":"نسبة ما في هذا الخبر من الغناء صوت بسيط","partialRef":{"sid":"b183-17","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b183-19","bab":"الجزء 15","sec":"نسبة ما في هذا الخبر من الغناء صوت بسيط","page":"ج15 ص127","text":"(سهوب وأعلام تخال سرابها ... إذا استن في القيظ الملاء المعضدا)\nقال وغنته حبابة منها أيضا\n(كريم قريش حين ينسب والذي ... أقرت له بالملك كهلا وأمردا)\n(وليس عطاء كان منه بمانع ... وإن جل من أضعاف أضعافه غدا)\n(أهان تلاد المال في الحمد إنه ... إمام هدى يجري على ما تعودا)\n(تردى بمجد من أبيه وأمه ... وقد أورثا بنيان مجد مشيدا)\nقال لها يزيد ويحك يا حبابة ومن من قريش هذا قالت أنت قال ومن يقول هذا الشعر قالت الأحوص يا أمير المؤمنين وقالت سلامة فليسمع أمير المؤمنين باقي ثنائه عليه فيها ثم اندفعت فغنته\n(ولو كان بذل الجود والمال مخلدا ... من الناس إنسانا لكنت المخلدا)\n(فأقسم لا أنفك ما عشت شاكرا ... لنعماك ما طار الحمام وغردا)\nأخبرني إسماعيل قال حدثنا عمر بن شبة قال علي بن الجعد قال حدثني أبو يعقوب الخريمي عن أبي بكر بن عياش أن حبابة وسلامة اختلفتا في صوت معبد - وافر -\n(ألا حي الديار بسعد إني ... أحب لحب فاطمة الديارا)\nفبعث يزيد إلى معبد فأتى به فسأل لم بعث إليه فأخبر فقال لأيتهما المنزلة عند أمير المؤمنين فقيل لحبابة فلما عرضتا عليه الصوت قضى لحبابة فقالت سلامة والله ما قضى إلا للمنزلة وإنه ليعلم أن الصواب ما غنيت ولكن ائذن لي يا أمير المؤمنين في صلته لأن له علي حقا قال قد أذنت فكان ما وصلته به أكثر من حبابة نسبة هذا الصوت - وافر -\n(ألا حي الديار بسعد إني ... أحل لحب فاطمة الديارا)\n(إذا ما حل أهلك يا سليمى ... بدارة صلصل شحطوا مزارا)\nلشعر لجرير والغناء لابن محرز خفيف ثقيل أول بالسبابة في مجرى البنصر أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال نزل الفرزدق على الأحوص حين قدم المدينة فقال له الأحوص ما تشتهي قال شواء وطلاء وغناء قال ذلك لك ومضى به إلى قينة بالمدينة فغنته\n(ألا حي الديار بسعد إني ... أحب لحب فاطمة الديارا)\n(أراد الظاعنون ليحزنوني ... فهاجوا صدع قلبي فاستطارا)\nقال الفرزدق ما أرق أشعاركم يا أهل الحجاز وأملحها قال أو ما تدري لمن هذا الشعر فقال لا والله قال هو لجرير يهجوك به فقال ويل ابن المراغة ما كان أحوجه مع عفافه إلى صلابة شعري وأحوجني مع شهواتي إلى رقة شعره\nوقد روى صالح بن حسان أن الصوت الذي اختلفت فيه حبابة وسلامة هو - كامل -\n(وترى لها دلا إذا نطقت به ... تركت بنات فؤاده صعرا)\nكر ذلك حماد عن أبيه عن الهيثم بن عدي أنهما اختلفتا في هذا الصوت بين يدي يزيد فقال لهما من أين جاء اختلافكما والصوت لمعبد ومنه أخذتماه فقالت هذه هكذا أخذته وقالت الأخرى هكذا أخذته فقال يزيد قد اختلفتما ومعبد حي بعد فكتب إلى عامله بالمدينة يأمره بحمله إليه ثم ذكر باقي الخبر مثل ما ذكره أبو بكر بن عياش قال صالح بن حسان فلما دخل معبد إليه لم يسأله عن الصوت ولكنه أمره أن يغني فغناه فقال - طويل -\n(فيا عز إن واش وشى بي عندكم ... فلا تكرميه أن تقولي له مهلا)\nاستحسنه وطرب ثم قال إن هاتين اختلفتا في صوت لك فاقض بينهما فقال لحبابة غني فغنت وقال لسلامة غني فغنت وقال الصواب ما قالت حبابة فقالت سلامة والله يا ابن الفاعلة إنك لتعلم أن الصواب ما قلت ولكنك سألت أيتهما آثر عند أمير المؤمنين فقيل لك حبابة فاتبعت هواه ورضاه فضحك يزيد وطرب وأخذ وسادة فصيرها على رأسه وقام يدور في الدار ويرقص ويصيح السمك الطري أربعة أرطال عند بيطار جنان حتى دار الدار كلها ثم رجع فجلس مجلسه وقال شعرا وأمر معبدا أن يغني فيه فغنى فيه وهو - بسيط\n(أبلغ حبابة أسقى ربعها المطر ... ما للفؤاد سوى ذكراكم وطر)\n(إن سار صحبي لم أملك تذكركم ... أو عرسوا فهموم النفس والسهر)\nاستحسنه وطرب هكذا ذكر إسحاق في الخبر وغيره يذكر أن الصنعة فيه لحبابة ويزعم ابن خرداذبه أن الصنعة فيه ليزيد وليس كما مر وإنما أراد أن يوالي بين الخلفاء في الصنعة فذكره على غير تحصيل والصحيح أنه لمعبد قال معبد فسر يزيد لما غنيته في هذين البيتين وكساني ووصلني ثم لما انصرم مجلسه انصرفت إلى منزلي الذي أنزلته فإذا ألطاف سلامة قد سبقت ألطاف حبابة وبعثت إلي إني قد عذرتك فيما فعلت ولكن كان الحق أولى بك فلم أزل في ألطافهما جميعا حتى أذن لي يزيد فرجعت إلى المدينة","topic":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","topicNo":183,"sp":17,"spl":"نسبة ما في هذا الخبر من الغناء صوت بسيط"},
{"id":"b183-20","bab":"الجزء 15","sec":"نسبة الصوت الذي غناه معبد الذي أوله طويل","page":"ج15 ص134","text":"(فيا عز إن واش وشى بي عندكم ... )\nوت\n(ألم يأن لي يا قلب أن أترك الجهلا ... وأن يحدث الشيب الملم لي العقلا)\n(على حين صار الرأس مني كأنما ... علت فوقه ندافة العطب الغزلا)\n(فيا عز إن واش وشى بي عندكم ... فلا تكرميه أن تقولي له مهلا)\n(كما لو وشى واش بودك عندنا ... لقلنا تزحزح لا قريبا ولا سهلا)\n(فأهلا وسهلا بالذي شد وصلنا ... ولا مرحبا بالقائل اصرم لها حبلا)\nالشعر لكثير والغناء لحنين ثقيل أول بالسبابة في مجرى الوسطى عن إسحاق وذكر ابن المكي وعمرو والهشامي أنه لمعبد وفيه ثاني ثقيل ينسب إلى\nابن سريج وليس بصحيح أخبرني الحرمي بن أبي العلاء قال حدثني الزبير قال حدثتني ظبية قالت أنشدت حبابة يوما يزيد بن عبد الملك - وافر -\n(لعمرك إنني لأحب سلعا ... لرؤيتها ومن بجنوب سلع)\nم تنفست تنفسا شديدا فقال لها ما لك أنت في ذمة أبي لئن شئت لأنقلنه إليك حجرا حجرا قالت وما أصنع به ليس إياه أردتإنما أردت صاحبه وربما قالت ساكنه","topic":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","topicNo":183,"sp":18,"spl":"نسبة الصوت الذي غناه معبد الذي أوله طويل — نسبة هذا الصوت خفيف","partialRef":{"sid":"b135-5","gi":1,"vi":1,"side":0},"partial":1},
{"id":"b183-21","bab":"الجزء 15","sec":"نسبة هذا الصوت","page":"ج15 ص135","text":"(لعمرك إنني لأحب سلعا ... لرؤيتها ومن بجنوب سلع)\n(تقر بقربها عيني وإني ... لأخشى أن تكون تريد فجعي)\n(حلفت برب مكة والهدايا ... وأيدي السابحات غداة جمع)\n(لأنت على التنائي فاعلميه ... أحب إلي من بصري وسمعي)\nلغناء لمعبد خفيف ثقيل بالوسطى مما لا يشك فيه من غنائه قال الزبير وحدثني ظبية أن يزيد قال لحبابة وسلامة أيتكما غنتني ما في نفسي فلها حكمها فغنت سلامة فلم تصب ما في نفسه وغنته حبابة - خفيف -\n(حلق من بني كنانة حولي ... بفلسطين يسرعون الركوبا)\nفأصابت ما في نفسه فقال احتكمي فقالت سلامة تهبها لي ومالها قال اطلبي غيرها فأبت فقال أنت أولى بها ومالها فلقيت سلامة من ذلك أمرا عظيما فقالت لها حبابة لا ترين إلا خيرا فجاء يزيد فسألها أن تبيعه إياها بحكمها فقالت أشهدك أنها حرة واخطبها إلي الآن حتى أزوجك مولاتي أخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثني إسحاق عن المدائني بنحو هذه القصة وقال فيها فجزعت سلامة فقالت لها لا تجزعي فإنما ألاعبه","topic":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","topicNo":183,"sp":18,"spl":"نسبة الصوت الذي غناه معبد الذي أوله طويل — نسبة هذا الصوت خفيف"},
{"id":"b183-22","bab":"الجزء 15","sec":"نسبة هذا الصوت خفيف","page":"ج15 ص136","text":"(حلق من بني كنانة حولي ... بفلسطين يسرعون الركوبا)\n(هزئت أن رأت مشيبي عرسي ... لا تلومي ذوائبي أن تشيبا)\nلشعر لابن قيس الرقيات والغناء لابن سريج ثاني ثقيل بالخنصر في مجرى البنصر عن إسحاق قال حماد بن إسحاق حدثني أبي عن المدائني وأيوب بن عباية قالا كانت سلامة المتقدمة منهما في الغناء وكانت حبابة تنظر إليها بتلك العين فلما حظيت عند يزيد ترفعت عليها فقالت لها سلامة ويحك أين تأديب الغناء وحق التعليم أنسيت قول جميلة لك خذي أحكام ما أطارحك إياه من سلامة فلن تزالي بخير ما بقيت لك وكان أمركما مؤتلفا قالت صدقت يا خليلتي والله لا عدت إلى شيء تكرهينه فما عادت بعد ذلك لها إلى مكروه وماتت حبابة وعاشت سلامة بعدها دهرا قال المدائني فرأى يزيد يوما حبابة جالسة فقال ما لك فقالت أنتظر سلامة قال تحبين أن أهبها لك قالت لا والله ما أحب أن تهب لي أختي\nقال المدائني وكانت حبابة إذا غنت وطرب يزيد قال لها أطير فتقول له فإلى من تدع الناس فيقول إليك والله تعالى أعلم أخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة قال حدثني أيوب بن عباية أن البيذق الأنصاري القارئ كان يعرف حبابة ويدخل عليها بالحجاز فلما صارت إلى يزيد بن عبد الملك وارتفع أمرها عنده خرج إليها يتعرض لمعروفها ويستميحها فذكرته ليزيد وأخبرته بحسن صوته قال فدعاني يزيد ليلة فدخلت عليه وهو على فرش مشرفة قد ذهب فيها إلى قريب من ثدييه وإذا حبابة على فرش أخر مرتفعة وهي دونه فسلمت فرد السلام وقالت حبابة يا أمير المؤمنين هذا أبي وأشارت إلي بالجلوس فجلست وقالت لي حبابة اقرأ يا أبت فقرأت فنظرت إلى دموعه تنحدر ثم قالت إيه يا أبت حدث أمير المؤمنين وأشارت إلي أن غنه فاندفعت في صوت ابن سريج - مجزوء الخفيف -\n(من لصب مفند ... هائم القلب مقصد)\nطرب والله يزيد فحذفني بمدهن فيه فصوص من ياقوت وزبرجد فضرب صدري فأشارت إلي حبابة أن خذه فأخذته فأدخلته كمي فقال يا حبابة ألا ترين ما صنع بنا أبوك أخذ مدهننا فأدخله في كمه فقالت يا أمير المؤمنين ما أحوجه والله إليه ثم خرجت من عنده فأمر لي بمائة دينار","topic":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","topicNo":183,"sp":18,"spl":"نسبة الصوت الذي غناه معبد الذي أوله طويل — نسبة هذا الصوت خفيف"},
{"id":"b183-23","bab":"الجزء 15","sec":"نسبة هذا الصوت","page":"ج15 ص137","text":"(من لصب مفند ... هائم القلب مقصد)\n(أنت زودته الضنى ... بئس زاد المزود)\n(ولو اني لا أرتجيك لقد خف عودي ... )\n(ثاويا تحت تربة ... رهن رمس بفدفد)\n(غير أني أعلل النفس باليوم أو غد ... )\nلشعر لسعيد بن عبد الرحمن بن حسان وذكر الزبير بن بكار أنه لجعفر بن الزبير والغناء لابن سريج خفيف ثقيل بالسبابة في مجرى الوسطى وقال حماد حدثني أبي عن مخلد بن خداش وغيره أن حبابة غنت يزيد صوتا لابن سريج وهو قوله - منسرح -\n(ما أحسن الجيد من مليكة واللبات ... إذ زانها ترائبها)\nطرب يزيد وقال هل رأيت أحدا أطرب مني قلت نعم ابن الطيار معاوية بن عبد الله بن جعفر فكتب فيه إلى عبد الرحمن بن الضحاك فحمل إليه فلما قدم أرسلت إليه حبابة إنما بعث إليك لكذا وكذا وأخبرته فإذا دخلت عليه فلا تظهرن طربا حتى أغنيه الصوت الذي غنيته فقال سوأة على كبر سني فدعا به يزيد وهو على طنفسة خز ووضع لمعاوية مثلها فجاؤوا بجامين فيهما مسك فوضعت إحداهما بين يدي يزيد والأخرى بين يدي معاوية فقال فلم أدر كيف أصنع فقلت انظر كيف يصنع فاصنع مثله فكان يقلبه فيفوح ريحه وأفعل مثل ذلك فدعا بحبابة فغنت فلما غنت ذلك الصوت أخذ معاوية الوسادة فوضعها على رأسه وقام يدور وينادي الدخن بالنوى يعني اللوبيا قال فأمر له بصلات عدة دفعات إلى أن خرج فكان مبلغها ثمانية آلاف دينار أخبرني إسماعيل بن يونس قال أخبرني الزبير بن أبي بكر عن ظبية\nأن حبابة غنت يوما بين يدي يزيد فطرب ثم قال لها هل رأيت قط أطرب مني قالت نعم مولاي الذي باعني فغاظه ذلك فكتب في حمله مقيدا فلما عرف خبره أمر بإدخاله إليه فأدخل يرسف في قيده وأمرها فغنت بغتة - متقارب -\n(تشط غدا دار جيراننا ... وللدار بعد غد أبعد)\nوثب حتى ألقى نفسه على الشمعة فأحرق لحيته وجعل يصيح الحريق يا أولاد الزنا فضحك يزيد وقال لعمري إن هذا لأطرب الناس فأمر بحل قيوده ووصله بألف دينار ووصلته حبابة ورده إلى المدينة أخبرني إسماعيل بن يونس قال حدثنا عمربن شبة قال قال إسحاق كان يزيد بن عبد الملك قبل أن تفضي إليه الخلافة تختلف إليه مغنية طاعنة في السن تدعى أم عوف وكانت محسنة فكان يختار عليها - بسيط -\n(متى أجر خائفا تسرح مطيته ... وإن أخف آمنا تنبو به الدار)\n(سيروا إلي وأرخوا من أعنتكم ... إني لكل امرىء من وتره جار)\nفذكرها يزيد يوما لحبابة وقد كانت أخذت عنها فلم تقدر أن تطعن عليها إلا بالسن فغنت - طويل -\n(أبى القلب إلا أم عوف وحبها ... عجوزا ومن يحبب عجوزا يفند)\nضحك وقال لمن هذا الغناء فقالت لمالك فكان إذا جلس معها للشرب يقول غنيني صوت مالك في أم عوف أخبرني أحمد بن عبيد الله بن عمار قال حدثني عمر بن شبة قال حدثني\nعبد الله بن أحمد بن الحارث العدوي قال حدثني عمر بن أبي بكر المؤملي قال حدثني أبو غانم الأزدي قال نزل يزيد بن عبد الملك ببيت رأس بالشام ومعه حبابة فقال زعموا أنه لا تصفو لأحد عيشة يوما إلى الليل إلا يكدرها شيء عليه وسأجرب ذلك ثم قال لمن معه إذا كان غدا فلا تخبروني بشيء ولا تأتوني بكتاب وخلا هو وحبابة فأتيا بما يأكلان فأكلت رمانة فشرقت بحبة منها فماتت فأقام لا يدفنها ثلاثا حتى تغيرت وأنتنت وهو يشمها ويرشفها فعاتبه على ذلك ذوو قرابته وصديقه وعابوا عليه ما يصنع وقالوا قد صارت جيفة بين يديك حتى أذن لهم في غسلها ودفنها وأمر فأخرجت في نطع وخرج معها لا يتكلم حتى جلس على قبرها فلما دفنت قال أصبحت والله كما قال كثير - طويل -\n(فإن يسل عنك القلب أو يدع الصبا ... فباليأس يسلو عنك لا بالتجلد)\n(وكل خليل راءني فهو قائل ... من اجلك هذا هامة اليوم أو غد)\nفما أقام إلا خمس عشرة ليلة حتى دفن إلى جنبها أخبرني أحمد قال حدثني عمر قال حدثني إسحاق الموصلي قال حدثني الفضل بن الربيع عن أبيه عن إبراهيم بن جبلة بن مخرمة عن أبيه أن مسلمة بن عبد الملك قال ماتت حبابة فجزع عليها يزيد فجعلت أؤسيه وأعزيه وهو ضارب بذقنه على صدره ما يكلمني حتى دفنها ورجع فلما بلغ إلى بابه التفت إلي وقال\n(فإن تسل عنك النفس أو تدع الصبا ... فباليأس تسلو عنك لا بالتجلد)","topic":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","topicNo":183,"sp":19,"spl":"نسبة هذا الصوت","partial":1},
{"id":"b183-24","bab":"الجزء 15","sec":"نسبة هذا الصوت","page":"ج15 ص137","text":"ثم دخل بيته فمكث أربعين يوما ثم هلك قال وجزع عليها في بعض أيامه فقال انبشوها حتى أنظر إليها فقيل تصير حديثا فرجع فلم ينبشها وقد روى المدائني أنه اشتاق إليها بعد ثلاثة أيام من دفنه إياها فقال لا بد من أن تنبش فنبشت وكشف له عن وجهها وقد تغير تغيرا قبيحا فقيل له يا أمير المؤمنين اتق الله ألا ترى كيف قد صارت فقال ما رأيتها قط أحسن منها اليوم أخرجوها فجاء مسلمة ووجوه أهله فلم يزالوا به حتى أزالوه عن ذلك ودفنوها وانصرف فكمد كمدا شديدا حتى مات فدفن إلى جانبها قال إسحاق وحدثني عبد الرحمن بن عبد الله الشفافي عن العباس بن محمد أن يزيد بن عبد الملك أراد الصلاة على حبابة فكلمه مسلمة في أن لا يخرج وقال أنا أكفيك الصلاة عليها فتخلف يزيد ومضى مسلمة حتى إذا مضى الناس انصرف مسلمة وأمر من صلى عليها وروى الزبير عن مصعب بن عثمان عن عبد الله بن عروة بن الزبير قال خرجت مع أبي إلى الشأم في زمن يزيد بن عبد الملك فلما ماتت حبابة وأخرجت لم يستطع يزيد الركوب من الجزع ولا المشي فحمل على منبر على رقاب الرجال فلما دفنت قال لم أصل عليها انبشوا عنها فقال له مسلمة نشدتك الله يا أمير المؤمنين إنما هي أمة من الإماء وقد واراها الثرى فلم يأذن للناس بعد حبابة إلا مرة واحدة قال فوالله ما استتم دخول الناس حتى قال الحاجب أجيزوا رحمكم الله ولم ينشب يزيد أن مات كمدا أخبرني أحمد بن عبيد الله بن عمار قال حدثنا عمر بن شبة قال حدثني إسحاق قال حدثني ابن أبي الحويرث الثقفي قال لما ماتت حبابة جزع عليها\nيزيد جزعا شديدا فضم جويرية لها كانت تخدمها إليه فكانت تحدثه وتؤنسه فبينا هو يوما يدور في قصره إذ قال لها هذا الموضع الذي كنا فيه فتمثلت - طويل -\n(كفى حزنا للهائم الصب أن يرى ... منازل من يهوى معطلة قفرا)\nبكى حتى كاد يموت ثم لم تزل تلك الجويرية معه يتذكر بها حبابة حتى مات","topic":"نسب الخنساء وخبرها وخبر مقتل أخويها صخر ومعاوية","topicNo":183,"sp":20,"spl":"نسبة هذا الصوت"},
{"id":"b184-1","bab":"الجزء 15","sec":"صوت طويل","page":"ج15 ص142","text":"(أيدعونني شيخا وقد عشت حقبة ... وهن من الأزواج نحوي نوازع)\n(وما شاب رأسي من سنين تتابعت ... علي ولكن شيبته الوقائع)\nلشعر لأبي الطفيل صاحب رسول الله والغناء لإبراهيم خفيف ثقيل أول بالوسطى عن عمرو وغيره\n10 -","topic":"أخبار أبي الطفيل ونسبه","topicNo":184,"sp":0,"spl":"صوت طويل — أخبار أبي الطفيل ونسبه"},
{"id":"b184-2","bab":"الجزء 15","sec":"أخبار أبي الطفيل ونسبه","page":"ج15 ص143","text":"هو عامر بن واثلة بن عبد الله بن عمير بن جابر بن حميس بن جدي بن سعد بن ليث بن بكر بن عبد مناة بن كنانة بن خزيمة بن مدركة بن الياس بن مضر ابن نزار وله صحبة برسول الله ورواية عنه وعمر بعده عمرا طويلا وكان مع أمير المؤمنين علي بن أبي طالب عليه السلام وروى عنه أيضا وكان من وجوه شيعته وله منه محل خاص يستغنى بشهرته عن ذكره ثم خرج طالبا بدم الحسين بن علي عليهما السلام مع المختار بن أبي عبيد وكان معه حتى قتل وأفلت هو وعمر أيضا بعد ذلك حدثني أحمد بن الجعد قال حدثنا محمد بن يوسف بن أسوار الجمحي بمكة قال حدثنا يزيد بن أبي حكيم قال حدثني يزيد بن مليل عن أبي الطفيل أنه رأى النبي في حجة الوداع يطوف بالبيت الحرام على ناقته ويستلم الركن بمحجنه\nأخبرنا محمد بن العباس اليزيدي قال حدثنا الرياشي قال حدثنا أبو عاصم عن معروف بن خربوذ عن أبي الطفيل بمثله وزاد فيه ثم يقبل المحجن حدثني أبو عبيد الله الصيرفي قال حدثنا الفضل بن الحسن المصري قال حدثنا أبو نعيم عن بسام الصيرفي عن أبي الطفيل قال سمعت عليا عليه السلام يخطب فقال سلوني قبل أن تفقدوني فقام إليه ابن الكواء فقال ما ( الذاريات ذروا\nقال الرياح قال ( فالجاريات يسرا\nقال السفن قال ( فالحاملات وقرا\nقال السحاب قال ( فالمقسمات أمرا\nقال الملائكة قال فمن ( الذين بدلوا نعمة الله كفرا\nقال الأفجران من قريش بنو أمية وبنو مخزوم قال فما كان ذو القرنين أنبيا أم ملكا قال كان عبدا مؤمنا أو قال صالحا أحب الله وأحبه ضرب ضربة على قرنه الأيمن فمات ثم بعث وضرب ضربة على قرنه الأيسر فمات وفيكم مثله وكتب إلي إسماعيل بن محمد المري الكوفي يذكر أن أبا نعيم حدثه بذلك عن بسام وذكر مثله أخبرني الحسين بن يحيى عن حماد عن أبيه قال بلغني أن بشر بن مروان حين كان على العراق قال لأنس بن زنيم أنشدني أفضل شعر قالته كنانة فأنشده قصيدة أبي الطفيل - طويل -\n(أيدعونني شيخا وقد عشت برهة ... وهن من الأزواج نحوي نوازع)\nفقال له بشر صدقت هذا أشعر شعرائكم قال وقال له الحجاج أيضا أنشدني قول شاعركم أيدعونني شيخا فأنشده إياه فقال قاتله الله منافقا ما أشعره حدثني أحمد بن عيسى العجلي الكوفي المعروف بابن أبي موسى قال حدثنا الحسين بن نصر بن مزاحم قال حدثني أبي قال حدثني عمرو بن شمر عن جابر الجعفي قال سمعت ابن حذيم الناجي يقول لما استقام لمعاوية أمره لم يكن شيء أحب إليه من لقاء أبي الطفيل عامر بن واثلة فلم يزل يكاتبه ويلطف له حتى أتاه فلما قدم عليه جعل يسائله عن أمر الجاهلية ودخل عليه عمرو بن العاص ونفر معه فقال لهم معاوية أما تعرفون هذا هذا خليل أبي الحسن ثم قال يا أبا الطفيل ما بلغ من حبك لعلي قال حب أم موسى لموسى قال فما بلغ من بكائك عليه قال بكاء العجوز الثكلى والشيخ الرقوب وإلى الله أشكو التقصير قال معاوية إن أصحابي هؤلاء لو سئلوا عني ما قالوا في ما قلت في صاحبك قالوا إذا والله ما نقول الباطل قال لهم معاوية لا والله ولا الحق تقولون ثم قال معاوية وهو الذي يقول - طويل -\n(إلى رجب السبعين تعترفونني ... مع السيف في حواء جم عديدها)\n(رجوف كمتن الطود فيها معاشر ... كغلب السباع نمرها وأسودها)\n(كهول وشبان وسادات معشر ... على الخيل فرسان قليل صدودها)\n(كأن شعاع الشمس تحت لوائها ... إذا طلعت أعشى العيون حديدها)\n(يمورون مور الريح إما ذهلتم ... وزلت بأكفال الرجال لبودها)\n(شعارهم سيما النبي وراية ... بها انتقم الرحمن ممن يكيدها)\n(تخطفهم إياكم عند ذكرهم ... كخطف ضواري الطير طيرا تصيدها)\nقال معاوية لجلسائه أعرفمتوه قالوا نعم هذا أفحش شاعر وألأم جليس فقال معاوية يا أبا الطفيل أتعرفهم فقال ما أعرفهم بخير ولا أبعدهم من شر قال وقام خزيمة الأسدي فأجابه فقال - طويل -\n(إلى رجب أو غرة الشهر بعده ... تصبحكم حمر المنايا وسودها)\n(ثمانون ألفا دين عثمان دينهم ... كتائب فيها جبرئيل يقودها)\n(فمن عاش منكم عاش عبدا ومن يمت ... ففي النار سقياه هناك صديدها)","topic":"أخبار أبي الطفيل ونسبه","topicNo":184,"sp":0,"spl":"صوت طويل — أخبار أبي الطفيل ونسبه"},
{"id":"b184-3","bab":"الجزء 15","sec":"أخبار أبي الطفيل ونسبه","page":"ج15 ص143","text":"أخبرني عبد الله بن محمد الرازي قال حدثنا أحمد بن الحارث قال حدثنا المدائني عن أبي مخنف عن عبد الملك بن نوفل بن مساحق قال لما رجع محمد بن الحنفية من الشام حبسه ابن الزبير في سجن عارم فخرج إليه جيش من الكوفة عليهم أبو الطفيل عامر بن واثلة حتى أتوا سجن عارم فكسروه وأخرجوه فكتب ابن الزبير إلى أخيه مصعب أن يسير نساء كل من خرج لذلك فأخرج مصعب نساءهم وأخرج فيهن أم الطفيل امرأة أبي الطفيل وابنا له صغيرا يقال له يحيى فقال أبو الطفيل في ذلك - متقارب -\n(إن يك سيرها مصعب ... فإني إلى مصعب مذنب)\n(أقود الكتيبة مستلئما ... كأني أخو عرة أجرب)\n(علي دلاص تخيرتها ... وفي الكف ذو رونق مقضب)\nخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثنا محمد بن حميد الرازي قال حدثنا سلمة بن الفضل عن فطر بن خليفة قال سمعت أبا الطفيل يقول لم يبق من الشيعة غيري ثم تمثل - طويل -\n(وخلفت سهما في الكنانة واحدا ... سيرمى به أو يكسر السهم كاسره)\nخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثني أبو عاصم قال حدثني شيخ من بني تيم اللات قال كان أبو الطفيل مع المختار في القصر فرمى بنفسه قبل أن يؤخذ وقال - طويل -\n(ولما رأيت الباب قد حيل دونه ... تكسرت باسم الله فيمن تكسرا)\nخبرني محمد بن خلف وكيع قال حدثنا أحمد بن عبد الله بن شداد النشابي قال حدثني المفضل بن غسان قال حدثني عيسى بن واضح عن سليم ابن مسلم المكي عن ابن جريج عن عطاء قال دخل عبد الله بن صفوان على عبد الله بن الزبير وهو يومئذ بمكة فقال أصبحت كما قال الشاعر - بسيط -\n(فإن تصبك من الأيام جائحة ... لا أبك منك على دنيا ولا دين)\nال وما ذاك يا أعرج قال هذا عبد الله بن عباس يفقه الناس وعبيد الله أخوه يطعم الناس فما بقيا لك فأحفظه ذلك فأرسل صاحب شرطته عبد الله بن مطيع\nفقال له انطلق إلى ابني عباس فقل لهما أعمدتما إلى راية ترابية قد وضعها الله فنصبتماها بددا عني جمعكما ومن ضوى إليكما من ضلال أهل العراق وإلا فعلت وفعلت فقال ابن عباس قل لابن الزبير يقول لك ابن عباس ثكلتك أمك والله ما يأتينا من الناس غير رجلين طالب فقه أو طالب فضل فأي هذين تمنع فأنشأ أبو الطفيل عامر بن واثلة - بسيط -\n(لا در در الليالي كيف تضحكنا ... منها خطوب أعاجيب وتبكينا)\n(ومثل ما تحدث الأيام من غير ... يا ابن الزبير عن الدنيا يسلينا)\n(كنا نجيء ابن عباس فيقبسنا ... علما ويكسبنا أجرا ويهدينا)\n(ولا يزال عبيد الله مترعة ... جفانه مطعما ضيفا ومسكينا)\n(فالبر والدين والدنيا بدارهما ... ننال منها الذي نبغي إذا شينا)\n(إن النبي هو النور الذي كشفت ... به عمايات باقينا وماضينا)\n(ورهطه عصمة في ديننا ولهم ... فضل علينا وحق واجب فينا)\n(ولست فاعلمه أولى منهم رحما ... يا ابن الزبير ولا أولى به دينا)\n(ففيم تمنعهم عنا وتمنعنا ... منهم وتؤذيهم فينا وتؤذينا)\n(لن يؤتي الله من أخزى ببغضهم ... في الدين عزا ولا في الأرض تمكينا)\nخبرني الحسن بن علي قال حدثني هارون بن محمد بن عبد الملك الزيات قال حدثني الزبير بن بكار قال حدثني بعض أصحابنا أن أبا الطفيل عامر بن واثلة دعي في مأدبة فغنت فيها قينة قوله يرثي ابنه - بسيط -\n(خلى طفيل علي الهم وانشعبا ... وهد ذلك ركني هدة عجبا)\nبكى حتى كاد يموت\nوقد أخبرني بهذا الخبر عمي عن طلحة بن عبد الله الطلحي عن أحمد بن إبراهيم أن أبا الطفيل دعي إلى وليمة فغنت قينة عندهم - بسيط -\n(خلى علي طفيل الهم وانشعبا ... وهد ذلك ركني هدة عجبا)\n(وابني سمية لا أنساهما أبدا ... فيمن نسيت وكل كان لي وصبا)\nفجعل ينشج ويقول هاه هاه طفيل ويبكي حتى سقط على وجهه ميتا وأخبرني محمد بن مزيد قال حدثنا حماد عن أبيه بخبر أبي الطفيل هذا فذكر مثل ما مضى وزاد في الأبيات\n(فاملك عزاءك إن رزء بليت به ... فلن يرد بكاء المرء ما ذهبا)\n(وليس يشفي حزينا من تذكره ... إلا البكاء إذا ما ناح وانتحبا)\n(فإذ سلكت سبيلا كنت سالكها ... ولا محالة أن يأتي الذي كتبا)\n(فما لبطنك من ري ولا شبع ... ولا ظللت بباقي العيش مرتغبا)","topic":"أخبار أبي الطفيل ونسبه","topicNo":184,"sp":1,"spl":"أخبار أبي الطفيل ونسبه"},
{"id":"b184-4","bab":"الجزء 15","sec":"أخبار أبي الطفيل ونسبه","page":"ج15 ص143","text":"قال حماد بن إسحاق حدثني أبي قال حدثني أبو عبد الله الجمحي عن أبيه قال بينا فتية من قريش ببطن محسر يتذاكرون الأحاديث ويتناشدون الأشعار إذ أقبل طويس وعليه قميص قوهي وحبرة قد ارتدى بها وهو يخطر في مشيته فسلم ثم جلس فقال له القوم يا أبا عبد المنعم لو غنيتنا قال نعم وكرامة أغنيكم بشعر شيخ من أصحاب رسول الله من شيعة علي بن أبي طالب عليه السلام وصاحب رايته أدرك الجاهلية والإسلام وكان سيد قومه\nوشاعرهم قالوا ومن ذاك يا أبا عبد المنعم فدتك أنفسنا قال ذلك أبو الطفيل عامر بن واثلة ثم اندفع فغنى - طويل -\n(أيدعونني شيخا وقد عشت حقبة ... وهن من الأزواج نحوي نوازع)\nطرب القوم وقالوا ما سمعنا قط غناء أحسن من هذا وهذا الخبر يدل على أن فيه لحنا قديما ولكنه ليس يعرف","topic":"أخبار أبي الطفيل ونسبه","topicNo":184,"sp":2,"spl":"أخبار أبي الطفيل ونسبه — صوت خفيف"},
{"id":"b184-5","bab":"الجزء 15","sec":"صوت خفيف","page":"ج15 ص150","text":"(لمن الدار أقفرت بمعان ... بين شاطي اليرموك فالصمان)\n(فالقريات من بلاس فداريا ... فسكاء فالقصور الدواني)\n(ذاك مغنى لآل جفنة في الدهر ... وحق تصرف الأزمان)\n(صلوات المسيح في ذلك الدير ... دعاء القسيس والرهبان)\nلشعر لحسان بن ثابت والغناء لحنين بن بلوع خفيف ثقيل أول بالسبابة في مجرى الوسطى\nوهذا الصوت من صدور الأغاني ومختارها وكان إسحاق يقدمه ويفضله ووجدت في بعض كتبه بخطه قال الصيحة التي في لحن حنين - خفيف -\n(لمن الدار أقفرت بمعان ... )\nخرجت من الصدر ثم من الحلق ثم من الأنف ثم من الجبهة ثم نبرت فأخرجت من القحف ثم نونت مردودة إلى الأنف ثم قطعت وفي هذه الأبيات وأبيات غيرها من القصيدة ألحان لجماعة اشتركوا فيها واختلف أيضا مؤلفو الأغاني في ترتيبها ونسبة بعضها مع بعض إلى صاحبها الذي صنعها فذكرت هاهنا على ذلك وشرح ما قالوه فيها فمنها - خفيف -\n(قد عفا جاسم إلى بيت رأس ... فالحواني فجانب الجولان)\n(فحمى جاسم فأبنية الصفر ... مغنى قنابل وهجان)\n(فالقريات من بلاس فداريا ... فسكاء فالقصور الدواني)\n(قد دنا الفصح فالولائد ينظمن ... سراعا أكلة المرجان)\n(يتبارين في الدعاء إلى الله ... وكل الدعاء للشيطان)\n(ذاك مغنى لآل جفنة في الدهر ... وحق تصرف الأزمان)\n(صلوات المسيح في ذلك الدير ... دعاء القسيس والرهبان)\n(قد أراني هناك حق مكين ... عند ذي التاج مقعدي ومكاني)\nكر عمرو بن بانة أن لابن محرز في الأول من هذه الأبيات والرابع خفيف ثقيل أول بالبنصر وذكر علي بن يحيى أن لابن سريج في الرابع والخامس رملا بالوسطى وأن لمعبد فيهما وفيما بعدهما من الأبيات خفيف ثقيل ولمحمد بن إسحاق بن برثع ثقيل أول في الرابع والثامن وذكر الهشامي أن في الأول لمالك خفيف ثقيل ووافقه حبش وذكر حبش أن لمعبد في الأول والثاني والرابع ثقيلا أول بالبنصر","topic":"أخبار أبي الطفيل ونسبه","topicNo":184,"sp":2,"spl":"أخبار أبي الطفيل ونسبه — صوت خفيف","song":1,"partial":1},
{"id":"b184-6","bab":"الجزء 15","sec":"أخبار حسان وجبلة بن الأيهم","page":"ج15 ص153","text":"أخبرني أحمد بن عبد العزيز الجوهري وحبيب بن نصر المهلبي قالا حدثنا عمر بن شبة قال حدثني هارون بن عبد الله الزهري قال حدثني يوسف بن الماجشون عن أبيه قال قال حسان بن ثابت أتيت جبلة بن الأيهم الغساني وقد مدحته فأذن لي فجلست بين يديه وعن يمينه رجل له ضفيرتان وعن يساره رجل لا أعرفه فقال أتعرف هذين فقلت أما هذا فأعرفه وهو النابغة وأما هذا فلا أعرفه قال فهو علقمة بن عبدة فإن شئت أن تسكت سكت قلت فذاك قال فأنشده النابغة - طويل -\n(كليني لهم يا أميمة ناصب ... وليل أقاسيه بطيء الكواكب)\nقال فذهب نصفي ثم قال لعلقمة أنشد فأنشد - طويل -\n(طحا بك قلب في الحسان طروب ... بعيد الشباب عصر حان مشيب)\nذهب نصفي الآخر فقال لي أنت أعلم الآن إن شئت أن تنشد بعدهما أنشدت وإن شئت أن تسكت سكت فتشددت ثم قلت لا بل أنشد قال هات فأنشدته - كامل -\n(لله در عصابة نادمتها ... يوما بجلق في الزمان الأول)\n(أولاد جفنة عند قبر أبيهم ... قبر ابن مارية الكريم المفضل)\n(يسقون من ورد البريص عليهم ... كأسا تصفق بالرحيق السلسل)\n(يغشون حتى ما تهر كلابهم ... لا يسألون عن السواد المقبل)\n(بيض الوجوه كريمة أحسابهم ... شم الأنوف من الطراز الأول)\nقال لي أدنه أدنه لعمري ما أنت بدونهما ثم أمر لي بثلاثمائة دينار وعشرة أقمصة لها جيب واحد وقال هذا لك عندنا في كل عام وقد ذكر أبو عمرو الشيباني هذه القصة لحسان ووصفها وقال إنما فضله عمرو بن الحارث الأعرج ومدحه بالقصيدة اللامية وأتى بالقصة أتم من هذه الرواية\nقال أبو عمرو قال حسان بن ثابت قدمت على عمرو بن الحارث فاعتاص الوصول علي إليه فقلت للحاجب بعد مدة إن أذنت لي عليه وإلا هجوت اليمن كلها ثم انقلبت عنكم فأذن لي فدخلت عليه فوجدت عنده النابغة وهو جالس عن يمينه وعلقمة بن عبدة وهو جالس عن يساره فقال لي يا ابن الفريعة قد عرفت عيصك ونسبك في غسان فارجع فإني باعث إليك بصلة سنية ولا أحتاج إلى الشعر فإني أخاف عليك هذين السبعين النابغة وعلقمة أن يفضحاك وفضيحتك فضيحتي وأنت والله لا تحسن أن تقول - طويل -\n(رقاق النعال طيب حجزاتهم ... يحيون بالريحان يوم السباسب)\nأبيت وقلت لا بد منه فقال ذاك إلى عميك فقلت لهما بحق الملك إلا قدمتماني عليكما فقالا قد فعلنا فقال عمرو بن الحارث هات يا ابن الفريعة فأنشأت - كامل -\n(أسألت رسم الدار أم لم تسأل ... بين الحواني فالبضيع فحومل)\nقال فلم يزل عمرو بن الحارث يزحل عن موضعه سرورا حتى شاطر البيت وهو يقول هذا وأبيك الشعر لا ما تعللاني به منذ اليوم هذه والله البتارة التي قد\nبترت المدائح أحسنت يا ابن الفريعة هات له يا غلام ألف دينار مرجوحة وهي التي في كل دينار عشرة دنانير فأعطيت ذلك ثم قال لك علي في كل سنة مثلها ثم أقبل على النابغة فقال قم يا زياد فهات الثناء المسجوع فقام النابغة فقال ألا أنعم صباحا أيها الملك المبارك السماء غطاؤك والأرض وطاؤك ووالداي فداؤك والعرب وقاؤك والعجم حماؤك والحكماء جلساؤك والمداره سمارك والمقاول إخوانك والعقل شعارك والحلم دثارك والسكينة مهادك والوقار غشاؤك والبر وسادك والصدق رداؤك واليمن حذاؤك والسخاء ظهارتك والحمية بطانتك والعلاء علايتك وأكرم الأحياء أحياؤك وأشرف الأجداد أجدادك وخير الآباء آباؤك وأفضل الأعمام أعمامك وأسرى الأخوال أخوالك وأعف النساء حلائلك وأفخر الشبان أبناؤك وأطهر الأمهات أمهاتك وأعلى البنيان بنيانك وأعذب المياه أمواهك وأفيح الدارات داراتك وأنزه الحدائق حدائقك وأرفع اللباس لباسك قد حالف الإضريج عاتقيك ولاءم المسك مسكك وجاور العنبر ترائبك وصاحب","topic":"أخبار أبي الطفيل ونسبه","topicNo":184,"sp":3,"spl":"أخبار حسان وجبلة بن الأيهم"},
{"id":"b184-7","bab":"الجزء 15","sec":"أخبار حسان وجبلة بن الأيهم","page":"ج15 ص153","text":"النعيم جسدك العسجد آنيتك واللجين صحافك والعصب مناديلك والحوارى طعامك والشهد إدامك واللذات غذاؤك والخرطوم شرابك والأبكار مستراحك والأشراف مناصفك والخير بفنائك والشر بساحة أعدائك والنصر منوط بلوائك والخذلان مع ألوية حسادك والبر فعلك قد طحطح عدوك غضبك وهزم مغايبهم مشهدك وسار في الناس عدلك وشسع بالنصر ذكرك وسكن قوارع الأعداء ظفرك الذهب عطاؤك والدواة رمزك والأوراق لحظك وإطراقك وألف دينار مرجوحة إنماؤك أيفاخرك المنذر اللخمي فوالله لقفاك خير من وجهه ولشمالك خير من يمينه ولأخمصك خير من رأسه ولخطاؤك خير من صوابه ولصمتك خير من كلامه ولأمك خير من أبيه ولخدمك خير من قومه فهب لي أسارى قومي واسترهن بذلك شكري فإنك من أشراف قحطان وأنا من سروات عدنان\nفرفع عمرو رأسه إلى جارية كانت قائمة على رأسه وقال بمثل هذا فليثن على الملوك ومثل ابن الفريعة فليمدحهم وأطلق له أسرى قومه وذكر ابن الكلبي هذه القصة نحو هذا وقال فقال له عمرو اجعل المفاضلة بيني وبين المنذر شعرا فإنه أسير فقال - متقارب -\n(ونبئت أن أبا منذر ... يساميك للحدث الأكبر)\n(قذالك أحسن من وجهه ... وأمك خير من المنذر)\n(ويسراك أجود من كفه اليمين فقولا له أخر ... )\nقد ذكر المدائني أن هذه الأبيات والسجع الذي قبلها لحسان وهذا أصح قال أبو عمرو الشيباني لما أسلم جبلة بن الأيهم الغساني وكان من ملوك آل جفنة كتب إلى عمر رضي الله عنه يستأذنه في القدوم عليه فأذن له عمر فخرج إليه في خمسمائة من أهل بيته من عك وغسان حتى إذا كان على مرحلتين كتب إلى عمر يعلمه بقدومه فسر عمر رضوان الله عليه وأمر الناس باستقباله وبعث إليه بأنزال وأمر جبلة مائتي رجل من أصحابه فلبسوا الديباج والحرير وركبوا الخيول معقودة أذنابها وألبسوها قلائد الذهب والفضة ولبس جبلة تاجه وفيه قرطا مارية وهي جدته ودخل المدينة فلم يبق بها بكر ولا عانس إلا تبرجت وخرجت تنظر إليه وإلى زيه فلما انتهى إلى عمر رحب به وألطفه وأدنى مجلسه ثم أراد عمر الحج فخرج معه جبلة فبينا هو يطوف بالبيت وكان مشهورا بالموسم إذ وطئ إزاره رجل من بني فزارة فانحل فرفع جبلة يده فهشم أنف الفزاري فاستعدى عليه عمر رضوان الله عليه فبعث إلى جبلة فأتاه\nفقال ما هذا قال نعم يا أمير المؤمنين إنه تعمد حل إزاري ولولا حرمة الكعبة لضربت بين عينيه بالسيف فقال له عمر قد أقررت فإما أن رضي الرجل وإما أن أقيده منك قال جبلة ماذا تصنع بي قال آمر بهشم أنفك كما فعلت قال وكيف ذاك يا أمير المؤمنين وهو سوقة وأنا ملك قال إن الإسلام جمعك وإياه فلست تفضله بشيء إلا بالتقى والعافية قال جبلة قد ظننت يا أمير المؤمنين أني أكون في الإسلام أعز مني في الجاهلية قال عمر دع عنك هذا فإنك إن لم ترض الرجل أقدته منك قال إذا أتنصر قال إن تنصرت ضربت عنقك لأنك قد أسلمت فإن ارتددت قتلتك فلما رأى جبلة الصدق من عمر قال أنا ناظر في هذا ليلتي هذه وقد اجتمع بباب عمر من حي هذا وحي هذا خلق كثير حتى كادت تكون بينهم فتنة فلما أمسوا أذن له عمر في الانصراف حتى إذا نام الناس وهدؤوا تحمل جبلة بخيله ورواحله إلى الشأم فأصبحت مكة وهي منهم بلاقع فلما انتهى إلى الشأم تحمل في خمسمائة رجل من قومه حتى أتى القسطنطينية فدخل إلى هرقل فتنصر هو وقومه فسر هرقل بذلك جدا وظن أنه فتح من الفتوح عظيم وأقطعه حيث شاء وأجرى عليه من النزل ما شاء وجعله من محدثيه وسماره هكذا ذكر أبو عمرو وذكر ابن الكلبي أن الفزاري لما وطئ إزار جبلة لطم جبلة كما لطمه فوثبت غسان فهشموا أنفه وأتوا به عمر ثم ذكر باقي الخبر نحو ما ذكرناه وذكر الزبير بن بكار فيما أخبرنا به الحرمي بن أبي العلاء عنه أن محمد بن الضحاك حدثه عن أبيه أن جبلة قدم على عمر رضي الله عنه في ألف من أهل بيته فأسلم قال وجرى بينه وبين رجل من أهل المدينة كلام فسب المديني فرد عليه فلطمه جبلة فلطمه المديني فوثب عليه أصحابه فقال دعوه حتى أسأل صاحبه وأنظر ما عنده فجاء إلى عمر فأخبره فقال إنك فعلت به فعلا ففعل بك مثله قال أو ليس عندك من الأمر إلا ما أرى قال لا فما الأمر عندك يا جبلة\nقال من سبنا ضربناه ومن ضربنا قتلناه قال إنما أنزل القرآن بالقصاص فغضب وخرج بمن معه ودخل أرض الروم فتنصر ثم ندم وقال - طويل -","topic":"أخبار أبي الطفيل ونسبه","topicNo":184,"sp":4,"spl":"أخبار حسان وجبلة بن الأيهم","partial":1},
{"id":"b184-8","bab":"الجزء 15","sec":"أخبار حسان وجبلة بن الأيهم","page":"ج15 ص153","text":"(تنصرت الأشراف من عار لطمة ... )\nذكر الأبيات وزاد فيها بعد طويل\n(ويا ليت لي بالشأم أدنى معيشة ... أجالس قومي ذاهب السمع والبصر)\n(أدين بما دانوا به من شريعة ... وقد يحبس العود الضجور على الدبر)\nوذكر باقي خبره فيما وجه به إلى حسان مثله وزاد فيه أن معاوية لما ولي بعث إليه فدعاه إلى الرجوع إلى الإسلام ووعده إقطاع الغوطة بأسرها فأبى ولم يقبل ثم إن عمر رضي الله عنه بدا له أن يكتب إلى هرقل يدعوه إلى الله جل وعز وإلى الإسلام ووجه إليه رجلا من أصحابه وهو جثامة بن مساحق الكناني فلما انتهى إليه الرجل بكتاب عمر أجاب إلى كل شيء سوى الإسلام فلما أراد الرسول الانصراف قال له هرقل هل رأيت ابن عمك هذا الذي جاءنا راغبا في ديننا قال لا قال فالقه قال الرجل فتوجهت إليه فلما انتهيت إلى بابه رأيت من البهجة والحسن والسرور ما لم أر بباب هرقل مثله فلما أدخلت عليه إذا هو في بهو عظيم وفيه من التصاوير ما لا أحسن وصفه وإذا هو جالس على سرير من قوارير قوائمه أربعة أسد من ذهب وإذا هو رجل أصهب سبال وعثنون وقد أمر بمجلسه فاستقبل به وجه الشمس فما بين يديه من آنية الذهب والفضة يلوح فما رأيت أحسن منه فلما سلمت رد السلام ورحب بي وألطفني ولامني على تركي النزول عنده ثم أقعدني على شيء لم أثبته فإذا هو كرسي من ذهب فانحدرت عنه فقال مالك فقلت إن رسول الله نهى عن هذا فقال جبلة\nأيضا مثل قولي في النبي حين ذكرته وصلى عليه ثم قال يا هذا إنك إذا طهرت قلبك لم يضرك ما لبسته ولا ما جلست عليه ثم سألني عن الناس وألحف في السؤال عن عمر ثم جعل يفكر حتى رأيت الحزن في وجهه فقلت ما يمنعك من الرجوع إلى قومك والإسلام قال أبعد الذي قد كان قلت قد ارتد الأشعث بن قيس ومنعهم الزكاة وضربهم بالسيف ثم رجع إلى الإسلام فتحدثنا مليا ثم أومأ إلى غلام على رأسه فولى يحضر فما كان إلا هنيهة حتى أقبلت الأخونة يحملها الرجال فوضعت وجيء بخوان من ذهب فوضع أمامي فاستعفيت منه فوضع أمامي خوان خلنج وجامات قوارير وأديرت الخمر فاستعفيت منها فلما فرغنا دعا بكأس من ذهب فشرب به خمسا عددا ثم أومأ إلى غلام فولى يحضر فما شعرت إلا بعشر جوار يتكسرن في الحلي فقعد خمس عن يمينه وخمس عن شماله ثم سمعت وسوسة من ورائي فإذا أنا بعشر أفضل من الأول عليهن الوشي والحلي فقعد خمس عن يمينه وخمس عن شماله وأقبلت جارية على رأسها طائر أبيض كأنه لؤلؤة مؤدب وفي يدها اليمنى جام فيه مسك وعنبر قد خلطا وأنعم سحقهما وفي اليسرى جام وفيه ماء ورد فألقت الطائر في ماء الورد فتمعك بين جناحيه وظهره وبطنه ثم أخرجته فألقته في جام المسك والعنبر فتمعك فيها حتى لم يدع فيها شيئا ثم نفرته فطار فسقط على تاج جبلة ثم رفرف ونفض ريشه فما بقي عليه شيء إلا سقط على رأس جبلة ثم قال للجواري أطربنني فخفقن بعيدانهن يغنين - كامل -\n(لله در عصابة نادمتهم ... يوما بجلق في الزمان الأول)\n(بيض الوجوه كريمة أحسابهم ... شم الأنوف من الطراز الأول)\n(يغشون حتى ما تهر كلابهم ... لا يسألون عن السواد المقبل)\nاستهل واستبشر وطرب ثم قال زدنني فاندفعن يغنين خفيف\n(لمن الدار أقفرت بمعان ... بين شاطي اليرموك فالصمان)\n(فحمى جاسم فأبنية الصفر ... مغنى قنابل وهجان)\n(فالقريات من بلاس فدار ... يا فسكاء فالقصور الدواني)\n(ذاك مغنى لآل جفنة في الدار ... وحق تعاقب الأزمان)\n(قد دنا الفصح فالولائد ينظمن ... سراعا أكلة المرجان)\n(لم يعللن بالمغافير والصمغ ... ولا نقف حنظل الشريان)\n(قد أراني هناك حقا مكينا ... عند ذي التاج مقعدي ومكاني)\nقال أتعرف هذه المنازل قلت لا قال هذه منازلنا في ملكنا بأكناف دمشق وهذا شعر ابن الفريعة حسان بن ثابت شاعر رسول الله قلت أما إنه مضرور البصر كبير السن قال يا جارية هاتي فأتته بخمسمائة دينار وخمسة أثواب من الديباج فقال ادفع هذا إلى حسان وأقرئه مني السلام ثم أرادني على مثلها فأبيت فبكى ثم قال لجواريه أبكينني فوضعن عيدانهن وأنشأن يقلن - طويل -\n(تنصرت الأشراف من عار لطمة ... وما كان فيها لو صبرت لها ضرر)\n(تكنفني فيها لجاج ونخوة ... وبعت بها العين الصحيحة بالعور)\n(فيا ليت أمي لم تلدني وليتني ... رجعت إلى القول الذي قال لي عمر)\n(ويا ليتني أرعى المخاض بقفرة ... وكنت أسيرا في ربيعة أو مضر)","topic":"أخبار أبي الطفيل ونسبه","topicNo":184,"sp":5,"spl":"أخبار حسان وجبلة بن الأيهم","partial":1},
{"id":"b184-9","bab":"الجزء 15","sec":"أخبار حسان وجبلة بن الأيهم","page":"ج15 ص153","text":"(ويا ليت لي بالشأم أدنى معيشة ... أجالس قومي ذاهب السمع والبصر)\nم بكى وبكيت معه حتى رأيت دموعه تجول على لحيته كأنها اللؤلؤ ثم سلمت عليه وانصرفت فلما قدمت على عمر سألني عن هرقل وجبلة فقصصت عليه القصة من أولها إلى آخرها فقال أورأيت جبلة يشرب الخمر قلت نعم قال أبعده الله تعجل فانية اشتراها بباقية فما ربحت تجارته فهل سرح معك شيئا قلت سرح إلى حسان خمسمائة دينار وخمسة أثواب ديباج فقال هاتها وبعث إلى حسان فأقبل يقوده قائده حتى دنا فسلم وقال يا أمير المؤمنين إني لأجد أرواح آل جفنة فقال عمر رضي الله عنه قد نزع الله تبارك وتعالى لك منه على رغم أنفه وأتاك بمعونة فانصرف عنه وهو يقول 6 - كامل -\n(إن ابن جفنة من بقية معشر ... لم يغذهم آباؤهم باللوم)\n(لم ينسني بالشأم إذ هو ربها ... كلا ولا متنصرا بالروم)\n(يعطي الجزيل ولا يراه عنده ... إلا كبعض عطية المذموم)\n(وأتيته يوما فقرب مجلسي ... وسقى فرواني من الخرطوم)\nقال له رجل في مجلس عمر أتذكر قوما كانوا ملوكا فأبادهم الله وأفناهم فقال ممن الرجل قال مزني قال أما والله لولا سوابق قومك مع رسول الله لطوقتك طوق الحمامة وقال ما كان خليلي ليخل بي فما قال لك قال قال إن وجدته حيا فادفعها إليه وإن وجدته ميتا فاطرح الثياب على قبره وابتع بهذه الدنانير بدنا فانحرها على قبره فقال حسان ليتك وجدتني\nميتا ففعلت ذلك بي أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير قال قال لي عبد الرحمن بن عبد الله الزبيري قال الرسول الذي بعث به إلى جبلة ثم ذكر قصته مع الجارية التي جاءت بالجامين والطائر الذي تمعك فيهما وذكر قول حسان\n(إن ابن جفنة من بقية معشر ... )\n- كامل - ولم يذكر غير ذلك هكذا روى أبو عمرو في هذا الخبر وقد أخبرني به أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال قال عبد الله بن مسعدة الفزاري وجهني معاوية إلى ملك الروم فدخلت عليه فإذا عنده رجل على سرير من ذهب دون مجلسه فكلمني بالعربية فقلت من أنت يا عبد الله قال أنا رجل غلب عليه الشقاء أنا جبلة بن الأيهم إذا صرت إلى منزلي فالقني فلما انصرف وانصرفت أتيته في داره فألفيته على شرابه وعنده قينتان تغنيانه بشعر حسان بن ثابت - خفيف -\n(قد عفا جاسم إلى بيت رأس ... فالحواني فجانب الجولان)\nوذكر الأبيات فلما فرغتا من غنائهما أقبل علي ثم قال ما فعل حسان بن ثابت قلت شيخ كبير قد عمي فدعا بألف دينار فدفعها إلي وأمرني أن أدفعها إليه ثم قال أترى صاحبك يفي لي إن خرجت إليه قال قلت قل ما شئت أعرضه عليه قال يعطيني الثنية فإنها كانت منازلنا وعشرين قرية من الغوطة منها داريا وسكاء ويفرض بجماعتنا ويحسن جوائزنا قال قلت أبلغه فلما قدمت على معاوية قال وددت أنك أجبته إلى ما سأل فأجزته له وكتب إليه معاوية يعطيه\nذلك فوجده قد مات قال وقدمت المدينة فدخلت مسجد رسول الله فلقيت حسان فقلت يا أبا الوليد صديقك جبلة يقرأ عليك السلام فقال هات ما معك قلت وما علمك أن معي شيئا قال ما أرسل إلي بالسلام قط إلا ومعه شيء قال فدفعت إليه المال أخبرني إبراهيم بن محمد بن أيوب قال حدثنا عبد الله بن مسلم قال حدثني عبد الرحمن ابن أخي الأصمعي عن عمه عن أهل المدينة قالوا بعث جبلة إلى حسان بخمسمائة دينار وكسى وقال للرسول إن وجدته قد مات فابسط هذه الثياب على قبره فجاء فوجده حيا فأخبره فقال لوددت أنك وجدتني ميتا","topic":"أخبار أبي الطفيل ونسبه","topicNo":184,"sp":6,"spl":"أخبار حسان وجبلة بن الأيهم","partial":1},
{"id":"b184-10","bab":"الجزء 15","sec":"نسبة ما في هذه الأخبار من الأغاني صوت طويل","page":"ج15 ص165","text":"(تنصرت الأشراف من عار لطمة ... وما كان فيها لو صبرت لها ضرر)\nالأبيات الخمسة الشعر لجبلة بن الأيهم والغناء لعريب نصب خفيف وبسيط رمل بالوسطى ومنها - كامل -\n(إن ابن جفنة من بقية معشر ... لم يغذهم آباؤهم باللوم)\nلأبيات الأربعة الشعر لحسان بن ثابت والغناء لعريب هزج بالبنصر أخبرني محمد بن العباس اليزيدي قال حدثنا عمي يوسف بن محمد قال\nحدثني عمي إسماعيل بن أبي محمد قال قال الواقدي حدثني محمد بن صالح قال كان حسان بن ثابت يغدو على جبلة بن الأيهم سنة ويقيم سنة في أهله فقال لو وفدت على الحارث بن أبي شمر الغساني فإن له قرابة ورحما بصاحبي وهو أبذل الناس للمعروف وقد يئس مني أن أفد عليه لما يعرف من انقطاعي إلى جبلة قال فخرجت في السنة التي كنت أقيم فيها بالمدينة حتى قدمت على الحارث وقد هيأت له مديحا فقال لي حاجبه وكان لي ناصحا إن الملك قد سر بقدومك عليه وهو لا يدعك حتى تذكر جبلة فإياك أن تقع فيه فإنه إنما يختبرك وإن رآك قد وقعت فيه زهد فيك وإن رآك تذكر محاسنه ثقل عليه فلا تبتدئ بذكره وإن سألك عنه فلا تطنب في الثناء عليه ولا تعبه امسح ذكره مسحا وجاوزه إلى غيره فإن صاحبك يعني جبلة أشد إغضاء عن هذا من هذا أي أشد تغافلا وأقل حفلا به وذلك أن صاحبك أعقل من هذا وأبين وليس لهذا بيان فإذا دخلت عليه فسوف يدعوك إلى الطعام وهو رجل يثقل عليه أن يؤكل طعامه ولا يبالي الدرهم والدينار ويثقل عليه أن يشرب شرابه أيضا فإذا وضع طعامه فلا تضع يدك حتى يدعوك وإذا دعاك فأصب من طعامه بعض الإصابة قال فشكرت لحاجبه ما أمرني به قال ثم دخلت عليه فسألني عن البلاد وعن الناس وعن عيشنا بالحجاز وعن رجال يهود وكيف ما بيننا من تلك الحروب فكل ذلك أخبره حتى انتهى إلى ذكر جبلة فقال كيف تجد جبلة فقد انقطعت إليه وتركتنا فقلت إنما جبلة منك وأنت منه فلم أجر إلى مدح ولا عيب وجاز ذلك إلى غيره ثم قال الغداء فأتي بالغداء ووضع الطعام فوضع يده فأكل أكلا شديدا وإذا رجل جبار فقال بعد ساعة ادن فأصب من هذا فدنوت فخططت تخطيطا فأتي بطعام كثير ثم رفع الطعام وجاء وصفاء كثير عددهم معهم الأباريق فيها ألوان\nالأشربة ومعهم مناديل اللين فقاموا على رؤوسنا ودعا أصحاب برابط من الروم فأجلسهم وشرب فألهوه وقام الساقي على رأسي فقال اشرب فأبيت حتى قال هو اشرب فشربت فلما أخذ فينا الشراب أنشدته شعرا فأعجبه ولذ به فأقمت عنده أياما فقال لي حاجبه إن له صديقا هو أخف الناس عليه وهو جاء فإذا هو جاء جفاك وخلص به وقد ذكر قدومه فاستأذنه قبل أن يقدم عليه فإنه قبيح أن يجفوك بعد الإكرام والإذن اليوم أحسن قلت ومن هو قال نابغة بني ذبيان فقلت للحارث إن رأى الملك أن يأذن لي في الانصراف إلى أهلي فعل قال قد أذنت لك وأمرت لك بخمسمائة دينار وكسى وحملان فقبضتها وقدم النابغة وخرجت إلى أهلي","topic":"أخبار أبي الطفيل ونسبه","topicNo":184,"sp":7,"spl":"نسبة ما في هذه الأخبار من الأغاني صوت طويل — صوت طويل","song":1},
{"id":"b184-11","bab":"الجزء 15","sec":"صوت طويل","page":"ج15 ص167","text":"(ألا إن ليلى العامرية أصبحت ... على النأي مني ذنب غيري تنقم)\n(وما ذاك من شيء أكون اجترمته ... إليها فتجزيني به حيث أعلم)\n(ولكن إنسانا إذا مل صاحبا ... وحاول صرما لم يزل يتجرم)\n(وما زال بي ما يحدث النأي والذي ... أعالج حتى كدت بالعيش أبرم)\n(وما زال بي الكتمان حتى كأنني ... برجع جواب السائلي عنك أعجم)\n(لأسلم من قول الوشاة وتسلمي ... سلمت وهل حي من الناس يسلم)\nروضه من الطويل الشعر لنصيب ومن الناس من يروي الثلاثة الأبيات الأول\nللمجنون والغناء لبديح مولى عبد الله بن جعفر رحمهما الله وفي الأبيات الأول منها ثاني ثقيل بالوسطى عن الهشامي وحبش وذكر حماد بن إسحاق ولم يجنسه وفيه لابن سريج هزج خفيف بالبنصر في مجراها عن إسحاق في البيتين الأخيرين وفيه لمعبد في البيتين الأولين خفيف ثقيل أول بالخنصر في مجرى البنصر عن إسحاق","topic":"أخبار أبي الطفيل ونسبه","topicNo":184,"sp":7,"spl":"نسبة ما في هذه الأخبار من الأغاني صوت طويل — صوت طويل"},
{"id":"b184-12","bab":"الجزء 15","sec":"خبر بديح في هذا الصوت وغيره","page":"ج15 ص169","text":"بديح مولى عبد الله بن جعفر وكان يقال له بديح المليح وله صنعة يسيرة وإنما كان يغني أغاني غيره مثل سائب خاثر ونشيط وطويس وهذه الطبقة وقد روى بديح الحديث عن عبد الله بن جعفر أخبرني محمد بن خلف وكيع قال حدثنا العباس بن محمد الدوري قال حدثنا أبو عاصم النبيل عن جويرية بن أسماء عن عيسى بن عمر بن موسى عن بديح مولى عبد الله بن جعفر قال لما قدم يحيى بن الحكم المدينة دخل إليه عبد الله بن جعفر في جماعة فقال له يحيى جئتني بأوباش من أوباش خبثة فقال عبد الله سماها رسول الله طيبة وتسميها أنت خبثة أخبرني أحمد بن عبيد الله بن عمار قال قال داود بن جميل حدثني من سمع هذا الحديث من ابن العتبي يذكره عن أبيه قال دخل عبد الله بن جعفر على عبد الملك بن مروان وهو يتأوه فقال يا أمير المؤمنين لو أدخلت عليك من يؤنسك بأحاديث العرب وفنون الأسمار قال لست صاحب هزل والجد مع\nعلتي أحجى بي قال وما علتك يا أمير المؤمنين قال هاج بي عرق النسا في ليلتي هذه فبلغ مني قال فإن بديحا مولاي أرقى الناس منه فوجه إليه عبد الملك فلما مضى الرسول سقط في يدي ابن جعفر وقال كذبة قبيحة عند خليفة فما كان بأسرع من أن طلع بديح فقال كيف رقيتك من عرق النسا قال أرقى الخلق يا أمير المؤمنين قال فسري عن عبد الله لأن بديحا كان صاحب فكاهة يعرف بها فمد رجله فتفل عليها ورقاها مرارا فقال عبد الملك الله أكبر وجدت والله خفا يا غلام ادع فلانة حتى تكتب الرقية فإنا لا نأمن هيجها بالليل فلا نذعر بديحا فلما جاءت الجارية قال بديح يا أمير المؤمنين امرأته الطلاق إن كتبتها حتى تعجل حبائي فأمر له بأربعة آلاف درهم فلما صار المال بين يديه قال وامرأته الطلاق إن كتبتها أو يصير المال إلى منزلي فأمر به فحمل إلى منزله فلما أحرزه قال يا أمير المؤمنين امرأته الطلاق إن كنت قرأت على رجلك إلا أبيات نصيب - طويل -\n(ألا إن ليلى العامرية أصبحت ... على النأي مني ذنب غيري تنقم)\nذكر الأبيات وزاد فيها\n(وما زلت أستصفي لك الود أبتغي ... محاسنة حتى كأني مجرم)\nال ويلك ما تقول قال امرأته الطلاق إن كان رقاك إلا بما قال قال فاكتمها علي قال وكيف ذاك وقد سارت بها البرد إلى أخيك بمصر فطفق عبد الملك ضاحكا يفحص برجليه\nأخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة قال حدثني الأصمعي عن المنتجع النبهاني عن أبيه بهذا الخبر مثل الذي قبله وزاد في الشعر - طويل -\n(فلا تصرميني حين لا لي مرجع ... ورائي ولا لي عنكم متقدم)\nقال فيه فسكن ما كان يجده عبد الملك وأمر لبديح بأربعة آلاف درهم فقال ابن جعفر لبديح ما سمعت هذا الغناء منك مذ ملكتك فقال هذا من نتف سائب خاثر أخبرني إسماعيل قال حدثنا عمر قال حدثني القاسم بن محمد بن عباد عن الأصمعي عن ابن أبي الزناد عن نافع أراه نافع الخير مولى ابن جعفر بهذا الخبر مثله وزاد فيه أن بديحا رفع صوته يغنيه به لما قال له أن يكتب الرقية وزاد فيه فجعل عبد الملك يقول مهلا يا بديح فقال إنما رقيتك كما علمت يا أمير المؤمنين أخبرني إسماعيل قال حدثنا عمر بن شبة قال حدثني أبو سلمة الغفاري عن عبد الله بن عمران بن أبي فروة قال كان ابن جعفر يحب أن يسمع عبد الملك غناء بديح فدخل إليه يوما فشكا إليه عبد الملك ركبته فقال له ابن جعفر يا أمير المؤمنين إن لي مولى كانت أمه بربرية وكانت ترقي من هذه العلة وقد أخذ ذلك عنها قال فادع به فدعي بديح فجعل يتفل على ركبة عبد الملك ويهمهم ثم قال قم يا أمير المؤمنين جعلني الله فداك فقام عبد الملك لا يجد شيئا فقال عبد الله يا أمير المؤمنين مولاك لا بد له من صلة قال حتى تكتب رقيته ثم أمر جارية له فكتبت بسم الله الرحمن الرحيم فقال ليس فيها بسم الله الرحمن الرحيم قال كيف تكون ويلك رقية ليس فيها بسم الله الرحمن الرحيم قال فهو ذاك قال فاكتبيها على ما فيها فأملى عليها - طويل\n(ديار سليمى بين عيقة فالمهدي ... سقيت وإن لم تنطقي سبل الرعد)","topic":"أخبار أبي الطفيل ونسبه","topicNo":184,"sp":8,"spl":"خبر بديح في هذا الصوت وغيره"},
{"id":"b184-13","bab":"الجزء 15","sec":"خبر بديح في هذا الصوت وغيره","page":"ج15 ص169","text":"م قال له ابن جعفر لو سمعته منه قال أويجيد قال نعم قال هات فما برح والله حتى أفرغها في مسامعه أخبرني محمد بن العباس اليزيدي قال حدثني عمي عبيد الله قال حدثني سليمان بن أبي شيخ قال كنا عند أبي نعيم الفضل بن دكين فجاءه رجل فقال يا أبا نعيم إن الناس يزعمون أنك رافضي قال فأطرق ساعة ثم رفع رأسه وهو يبكي وقال يا هذا أصبحت فيكم كما قال نصيب - طويل -\n(وما زال بي الكتمان حتى كأنني ... برجع جواب السائلي عنك أعجم)\n(لأسلم من قول الوشاة وتسلمي ... سلمت وهل حي من الناس يسلم)","topic":"أخبار أبي الطفيل ونسبه","topicNo":184,"sp":9,"spl":"خبر بديح في هذا الصوت وغيره"},
{"id":"b185-1","bab":"الجزء 15","sec":"صوت رمل","page":"ج15 ص172","text":"(يا غراب البين أسمعت فقل ... إنما تنطق شيئا قد فعل)\n(إن للخير وللشر مدى ... لكلا ذينك وقت وأجل)\n(كل بؤس ونعيم زائل ... وبنات الدهر يلعبن بكل)\n(والعطيات خساس بينهم ... وسواء قبر مثر ومقل)\nالشعر لعبد الله بن الزبعرى السهمي يقوله في غزاة أحد وهو يومئذ مشرك والغناء لابن سريج خفيف ثقيل أول بالبنصر عن عمرو على مذهب إسحاق وفيه لحن لابن مسجح من رواية حماد عن أبيه في كتاب ابن مسحج","topic":"نسب ابن الزبعرى وأخباره وقصة غزوة أحد","topicNo":185,"sp":0,"spl":"صوت رمل"},
{"id":"b185-2","bab":"الجزء 15","sec":"نسب ابن الزبعرى وأخباره وقصة غزوة أحد","page":"ج15 ص174","text":"هو عبد الله بن الزبعرى بن قيس بن عدي بن سعد بن سهم بن عمرو بن هصيص بن كعب بن لؤي بن غالب بن فهر بن مالك بن النضر بن كنانة بن خزيمة ابن مدركة بن الياس بن مضر بن نزار\nوهو أحد شعراء قريش المعدودين\nوكان يهجو المسلمين ويحرض عليهم كفار قريش في شعره ثم أسلم بعد ذلك فقبل النبي إسلامه وأمنه يوم الفتح\nوهذه الأبيات يقولها ابن الزبعرى في غزوة أحد\nحدثنا بالخبر في ذلك محمد بن جرير الطبري قال حدثنا ابن حميد قال حدثنا سلمة عن محمد بن إسحاق قال حدثني محمد بن مسلم بن عبد الله بن شهاب الزهري ومحمد بن يحيى بن حبان وعاصم بن عمرو بن قتادة والحصين بن عبد الرحمن بن عمرو بن سعد بن معاذ وغيرهم من علمائنا كلهم قد حدث ببعض هذا الحديث فقد اجتمع حديثهم كلهم فيما سقت من الحديث عن يوم أحد\nقالوا لما أصيبت قريش أو من قاله منهم يوم بدر من كفار قريش من أصحاب\nالقليب فرجع فلهم إلى مكة ورجع أبو سفيان بن حرب بعيره مشى عبد الله بن أبي ربيعة وعكرمة بن أبي جهل وصفوان بن أمية في رجال من قريش ممن أصيب آباؤهم وأبناؤهم وإخوانهم ببدر فكلموا أبا سفيان بن حرب ومن كان له في تلك العير من قريش تجارة فقال أبو سفيان يا معشر قريش إن محمدا قد وتركم وقتل خياركم فأعينونا بهذا المال على حربه لعلنا أن ندرك ثأرا ممن أصيب منا ففعلوا فاجتمعت قريش لحرب رسول الله حين فعل ذلك أبو سفيان وأصحاب العير بأحابيشها ومن أطاعها من قبائل كنانة وأهل تهامة وكل أولئك قد استغووا على حرب رسول الله وكان أبو عزة عمرو ابن عبد الله الجمحي قد من عليه رسول الله يوم بدر وكان في الأسارى فقال يا رسول الله إني فقير ذو عيال وحاجة قد عرفتها فامنن علي صلى الله عليك فمن عليه رسول الله فقال صفوان بن أمية يا أبا عزة إنك امرؤ شاعر فاخرج معنا فأعنا بنفسك فقال إن محمدا قد من علي فلا أريد أن أظاهر عليه فقال بلى فأعنا بنفسك ولك الله إن رجعت أن أعينك وإن أصبت أن أجعل بناتك مع بناتي يصيبهن ما أصابهن من عسر أو يسر فخرج أبو عزة يسير في تهامة ويدعو بني كنانة وخرج مسافع بن عبدة بن وهب بن حذافة بن جمح إلى بني مالك بن كنانة يحرضهم ويدعوهم إلى حرب رسول الله ودعا جبير بن مطعم غلاما يقال له وحشي وكان حبشيا يقذف بحربة له قذف الحبشة قلما يخطئ بها فقال اخرج مع الناس فإن أنت قتلت عم محمد بعمي طعيمة بن عدي فأنت عتيق وخرجت قريش بحدها وأحابيشها ومن معها من بني كنانة وأهل تهامة\nوخرجوا بالظعن التماس الحفيظة ولئلا يفروا وخرج أبو سفيان بن حرب وهو قائد الناس معه هند بنت عتبة بن ربيعة وخرج عكرمة بن أبي جهل بن هشام ابن المغيرة وخرج صفوان بن أمية بن خلف ببرزة وقيل ببرة من قول أبي جعفر بنت مسعود بن عمرو بن عمير الثقفية وهي أم عبد الله بن صفوان وخرج عمرو ابن العاص وخرج طلحة بن أبي طلحة وأبو طلحة عبد الله بن عبد العزى بن عثمان بن عبد الدار بسلافة بنت سعد بن سهيل وهي أم بني طلحة مسافع والجلاس وكلاب قتلوا يومئذ وأبوهم وخرجت خناس بنت مالك بن المضرب إحدى نساء بني مالك بن حسل مع ابنها أبي عزة بن عمير وهي أم مصعب بن عمير وخرجت عمرة بنت علقمة إحدى نساء بني الحارث بن عبد مناة ابن كنانة وكانت هند بنت عتبة بن ربيعة إذا مرت بوحشي أو مر بها قالت إيه أبا دسمة اشتف فنزلوا ببطن السبخة من قناة على شفير الوادي مما يلي المدينة فلما سمع بهم رسول الله والمسلمون قد نزلوا حيث نزلوا قال رسول الله للمسلمين ( إني قد رأيت بقرا تذبح فأولتها خيرا ورأيت في ذباب سيفي ثلما ورأيت أني أدخلت يدي في درع حصينة وهي المدينة فإن رأيتم أن تقيموا بالمدينة وتدعوهم حيث نزلوا فإن أقاموا أقاموا بشر مقام وإن هم دخلوا علينا فيها قاتلناهم\nونزلت قريش منزلها من أحد يوم الأربعاء فأقاموا به ذلك اليوم ويوم الخميس ويوم الجمعة وراح رسول الله حين صلى الجمعة فأصبح بالشعب من أحد فالتقوا يوم السبت للنصف من شوال وكان رأي عبد الله بن","topic":"نسب ابن الزبعرى وأخباره وقصة غزوة أحد","topicNo":185,"sp":1,"spl":"نسب ابن الزبعرى وأخباره وقصة غزوة أحد"},
{"id":"b185-3","bab":"الجزء 15","sec":"نسب ابن الزبعرى وأخباره وقصة غزوة أحد","page":"ج15 ص174","text":"أبي بن سلول مع رأي رسول الله يرى رأيه في ذلك أن لا يخرج إليهم وكان رسول الله يكره الخروج من المدينة فقال رجال من المسلمين ممن أكرم الله جل ثناؤه بالشهادة يوم أحد وغيرهم ممن فاته بدر وحضوره يا رسول الله اخرج بنا إلى أعدائنا لا يرون أنا جبنا عنهم وضعفنا فقال عبد الله بن أبي ابن سلول يا رسول الله أقم بالمدينة ولا تخرج إليهم فوالله ما خرجنا منها إلى عدو قط إلا أصاب منا ولا يدخلها علينا إلا أصبنا منهم فدعهم يا رسول الله فإن أقاموا أقاموا بشر مجلس وإن دخلوا قاتلهم الرجال في وجوههم ورماهم النساء والصبيان بالحجارة من فوق رؤوسهم وإن رجعوا رجعوا خائبين كما جاؤوا فلم يزل برسول الله الذين كان من أمرهم حب لقاء العدو حتى دخل رسول الله فلبس لأمته وذلك يوم الجمعة حين فرغ رسول الله من الصلاة وقد مات في ذلك اليوم رجل من الأنصار يقال له مالك بن عمرو أحد بني النجار فصلى عليه رسول الله ثم خرج عليهم وقد ندم الناس وقالوا استكرهنا رسول الله ولم يكن ذلك لنا فخرج رسول الله عليهم فقالوا يا رسول الله استكرهناك ولم يكن ذلك لنا فإن شئت فاقعد صلى الله عليك فقال عليه السلام ( ما ينبغي لنبي لبس لأمته أن يضعها حتى يقاتل\nقال فخرج رسول الله في ألف رجل من أصحابه حتى إذا كانوا بالشوط بين أحد والمدينة انخزل عنه عبد الله بن أبي ابن سلول بثلث الناس وقال أطاعهم فخرج وعصاني والله ما ندري علام نقتل أنفسنا هاهنا أيها الناس فرجع بمن اتبعه من الناس من قومه من أهل النفاق والريب واتبعهم عبد الله بن عمرو بن حرام أحد بني سلمة يقول يا قوم أذكركم الله أن تخذلوا نبيكم وقومكم عندما حضر من عدوهم فقالوا لو نعلم أنكم تقاتلون ما أسلمناكم ولكنا لا نرى أنه\nيكون قتال فلما استعصوا عليه وأبوا إلا الانصراف قال أبعدكم الله أعداء الله فسيغني الله عز و جل عنكم وقال محمد بن عمر الواقدي انخزل عبد الله بن أبي عن رسول الله من لشيخين بثلاثمائة فبقي رسول الله في سبعمائة وكان المشركون في ثلاثة آلاف والخيل مائتا فارس والظعن خمس عشرة امرأة قال وكان في المشركين سبعمائة دارع ولم يكن معهم من الخيل إلا فرسان فرس لرسول الله وفرس لأبي بردة بن نيار الحارثي فادلج رسول الله من الشيخين حتى طلع الحمراء وهما أطمان كان يهودي ويهودية أعميان يقومان عليهما فيتحدثان فلذلك سميا الشيخين وهما في طرف المدينة قال وعرض رسول الله المقاتلة بعد المغرب فأجاز من أجاز ورد من رد قال وكان فيمن رد زيد بن ثابت وأبو عمرو أسيد بن ظهير والبراء بن عازب وعرابة بن أوس قال وهو عرابة الذي قال فيه الشماخ - وافر -\n(إذا ما راية رفعت لمجد ... تلقاها عرابة باليمين)\nال ورد أبا سعيد الخدري وأجاز سمرة بن جندب ورافع بن خديج وكان رسول الله قد استصغر رافعا فقام على خفين له فيهما رقاع وتطاول على أطراف أصابعه فلما رآه رسول الله أجازه قال محمد بن جرير فحدثني الحارث قال حدثنا ابن سعد قال أخبرنا محمد بن عمر قال كانت أم سمرة تحت مري بن سنان بن ثعلبة عم أبي سعيد\nالخدري وكان ربيبه فلما خرج رسول الله إلى أحد وعرض أصحابه فرد من استصغر رد سمرة بن جندب وأجاز رافع بن خديج فقال سمرة لربيبه مري ابن سنان أجاز رافعا وردني وأنا أصرعه فقال يا رسول الله رددت ابني وأجزت رافع بن خديج وابني يصرعه فقال النبي لرافع وسمرة اصطرعا فصرع سمرة رافعا فأجازه رسول الله فشهدها مع المسلمين وكان دليل النبي أبو خيثمة الحارثي","topic":"نسب ابن الزبعرى وأخباره وقصة غزوة أحد","topicNo":185,"sp":2,"spl":"نسب ابن الزبعرى وأخباره وقصة غزوة أحد"},
{"id":"b185-4","bab":"الجزء 15","sec":"رجع الحديث إلى حديث ابن إسحاق","page":"ج15 ص180","text":"ومضى رسول الله حتى سلك في حرة بني حارثة فذب فرس بذنبه فأصاب كلاب سيف فاستله فقال رسول الله وكان يحب الفأل ولا يعتاف لصاحب السيف ( شم سيفك فإني أرى السيوف ستستل اليوم\nثم قال رسول الله لأصحابه ( من رجل يخرج بنا على القوم من كثب من طريق لا يمر بنا عليهم\nفقال أبو خيثمة أخو بني حارثة بن الحارث أنا يا رسول الله فقدمه فنفذ به في حرة بني حارثة وبين أموالهم حتى سلك به في مال المربع بن قيظي وكان رجلا منافقا ضرير البصر فلما سمع حس رسول الله ومن معه من المسلمين قام يحثي التراب في وجوههم ويقول إن كنت رسول الله فلا أحل لك أن تدخل حائطي قال وقد ذكر لي أنه أخذ حفنة من تراب في يده ثم قال لو أني أعلم أني لا أصيب بها غيرك لضربت بها وجهك فابتدره القوم ليقتلوه فقال رسول الله ( لا تفعلوا بهذا الأعمى البصر الأعمى القلب\nوقد بدر إليه سعد بن زيد أخو بني عبد الأشهل حين نهى رسول الله عنه فضربه بالقوس في رأسه فشجه ومضى رسول الله على وجهه حتى نزل الشعب من أحد في عدوة الوادي إلى الجبل فجعل ظهره وعسكره إلى أحد\nوقال لا يقاتلن أحد أحدا حتى نأمره بالقتال وقد سرحت قريش الظهر والكراع في زروع كانت بالصمغة من قناة للمسلمين فقال رجل من المسلمين حين نهى رسول الله عن القتال أترعى زروع بني قيلة ولما نضارب وتعبى رسول الله وهو في سبعمائة رجل وتعبأت قريش وهم ثلاثة آلاف ومعهم مائتا فارس قد جنبوا خيولهم فجعلوا على ميمنة الخيل خالد بن الوليد وعلى ميسرتها عكرمة بن أبي جهل وأمر رسول الله على الرماة عبد الله بن جبير أخا بني عمرو بن عوف وهو يومئذ معلم بثياب بيض والرماة خمسون رجلا وقال انضح عنا الخيل بالنبل لا يأتونا من خلفنا إن كانت لنا أو علينا فاثبت بمكانك لا نؤتين من قبلك وظاهر رسول الله بين درعين قال محمد بن جرير فحدثنا هارون بن إسحاق قال حدثنا مصعب بن المقدام قال حدثنا أبو إسحاق عن البراء قال لما كان يوم أحد ولقي رسول الله المشركين أجلس رسول الله رجالا بإزاء الرماة وأمر عليهم عبد الله بن جبير وقال لهم ( لا تبرحوا مكانكم وإن رأيتمونا ظهرنا عليهم وإن رأيتموهم ظهروا علينا فلا تعينونا\nلما لقي القوم هزم المشركين حتى رأيت النساء قد رفعن عن سوقهن وبدت خلاخيلهن فجعلوا يقولون الغنيمة الغنيمة فقال عبد الله مهلا أما علمتم ما عهد إليكم رسول الله فأبوا فانطلقوا فلما أتوهم صرفت وجوههم فأصيب من المسلمين سبعون رجلا قال محمد بن جرير حدثني محمد بن سعد قال حدثني أبي قال حدثني عمي قال حدثني أبي عن أبيه عن ابن عباس قال أقبل أبو سفيان في ثلاث ليال خلون من شوال حتى نزل أحدا وخرج رسول الله فأذن في الناس فاجتمعوا\nوأمر الزبير على الخيل ومعه يومئذ المقداد الكندي وأعطى رسول الله الراية رجلا من قريش يقال له مصعب بن عمير وخرج حمزة بن عبد المطلب رضي الله عنه بالجيش وبعث حمزة بين يديه وأقبل خالد بن الوليد على خيل المشركين ومعه عكرمة بن أبي جهل فبعث رسول الله الزبير وقال استقبل خالد بن الوليد فكن بإزائه حتى أوذنك وأمر بخيل أخرى فكانوا من جانب آخر فقال لا تبرحن حتى أوذنكم وأقبل أبو سفيان يحمل اللات والعزى فأرسل رسول الله إلى الزبير أن يحمل فحمل على خالد بن الوليد فهزمه الله تعالى ومن معه فقال جل وعز ( ولقد صدقكم الله وعده إذ تحسونهم بإذنه\nإلى قوله تبارك اسمه وتعالى ( من بعد ما أراكم ما تحبون\nوإن الله تعالى وعد المؤمنين النصر وأنه معهم وإن رسول الله بعث ناسا من الناس فكانوا من ورائهم فقال رسول الله كونوا هاهنا فردوا وجه من فر منا وكونوا حرسا لنا من قبل ظهورنا وإنه عليه السلام لما هزم القوم هو وأصحابه قال الذين كانوا جعلوا من ورائهم بعضهم لبعض ورأوا النساء مصعدات في الجبل ورأوا الغنائم انطلقوا إلى رسول الله وأدركوا الغنائم قبل أن تسبقوا إليها وقالت طائفة أخرى بل نطيع رسول الله فنثبت مكاننا فقال ابن مسعود ما شعرت أن أحدا من أصحاب رسول الله كان يريد الدنيا وعرضها حتى كان يومئذ قال محمد بن جرير حدثني محمد بن الحسين قال حدثنا أحمد بن الفضل قال حدثنا أسباط عن السدي قال لما برز رسول الله بأحد إلى المشركين أمر الرماة فقاموا بأصل الجبل في وجوه خيل المشركين وقال لهم لا","topic":"نسب ابن الزبعرى وأخباره وقصة غزوة أحد","topicNo":185,"sp":3,"spl":"رجع الحديث إلى حديث ابن إسحاق"},
{"id":"b185-5","bab":"الجزء 15","sec":"رجع الحديث إلى حديث ابن إسحاق","page":"ج15 ص180","text":"تبرحوا مكانكم إن رأيتم قد هزمناهم فإنا لا نزال غالبين ما ثبتم مكانكم وأمر عليهم عبد الله بن جبير أخا خوات بن جبير ثم إن طلحة بن عثمان صاحب لواء المشركين قام فقال يا معاشر أصحاب محمد إنكم تزعمون أن الله عز و جل تعجلنا بسيوفكم إلى النار وتعجلكم بسيوفنا إلى الجنة فهل منكم أحد يعجله الله بسيفي إلى الجنة أو يعجلني بسيفه إلى النار فقام إليه علي بن أبي طالب عليه السلام فقال والذي نفسي بيده لا أفارقك حتى يعجلك الله عز و جل بسيفي إلى النار أو يعجلني بسيفك إلى الجنة فضربه علي فقطع رجله فبدت عورته فقال أنشدك الله والرحم يا ابن عم فتركه فكبر رسول الله وقال لعلي وأصحابه ما منعك أن تجهز عليه قال إن ابن عمي ناشدني حين انكشفت عورته فاستحييت منه ثم شد الزبير بن العوام والمقداد بن الأسود على المشركين فهزماهم وحمل النبي وأصحابه فهزموا أبا سفيان فلما رأى ذلك خالد بن الوليد وهو على خيل المشركين حمل فرمته الرماة فانقمع فلما نظر الرماة إلى رسول الله وأصحابه في جوف عسكر المشركين ينتهبونه بادروا الغنيمة فقال بعضهم لا نترك أمر رسول الله وانطلق عامتهم فلحقوا بالعسكر فلما رأى خالد قلة الرماة صاح في خيله ثم حمل فقتل الرماة وحمل على أصحاب رسول الله فلما رأى المشركون أن خيلهم تقاتل تبادروا فشدوا على المسلمين فهزموهم وقتلوهم","topic":"نسب ابن الزبعرى وأخباره وقصة غزوة أحد","topicNo":185,"sp":4,"spl":"رجع الحديث إلى حديث ابن إسحاق"},
{"id":"b185-6","bab":"الجزء 15","sec":"رجع إلى حديث ابن إسحاق","page":"ج15 ص184","text":"فقال رسول الله من يأخذ هذا السيف بحقه فقام إليه رجال فأمسكه بينهم حتى قام إليه أبو دجانة سماك بن خرشة أخو بني ساعدة فقال ما حقه يا رسول الله قال أن تضرب به في العدو حتى ينحني فقال أنا آخذه بحقه يا رسول الله فأعطاه إياه وكان أبو دجانة رجلا شجاعا يختال عند الحرب إذا كانت وكان إذا أعلم على رأسه بعصابة له حمراء علم الناس أنه سيقاتل فلما أخذ السيف من يد رسول الله أخذ عصابته تلك فعصب بها رأسه ثم جعل يتبختر بين الصفين قال محمد بن إسحاق حدثني جعفر بن عبد الله بن أسلم مولى عمر بن الخطاب رضي الله عنه عن رجل من الأنصار من بني سلمة قال قال رسول الله حين رأى أبا دجانة يتبختر إنها مشية يبغضها الله إلا في هذا الموطن وقد أرسل أبو سفيان رسولا فقال يا معشر الأوس والخزرج خلوا بيننا وبين ابن عمنا ننصرف عنكم فإنه لا حاجة بنا إلى قتالكم فردوه بما يكره وعن محمد بن إسحاق عن عاصم بن عمر بن قتادة أن أبا عامر عمرو بن صيفي بن النعمان بن مالك بن أمية أحد بني ضبيعة وقد خرج إلى مكة مباعدا لرسول الله ومعه خمسون غلاما من الأوس منهم عثمان بن حنيف وبعض الناس يقول كانوا خمسة عشر فكان يعد قريشا أن لو قد لقي محمدا لم يختلف عليه منهم رجلان فلما التقى الناس كان أول من لقيهم أبو عامر في الأحابيش\nوعبدان أهل مكة فنادى يا معشر الأوس أنا أبو عامر قالوا فلا أنعم الله بك عينا يا فاسق وكان أبو عامر يسمى في الجاهلية الراهب فسماه رسول الله الفاسق فلما سمع ردهم عليه قال لقد أصاب قومي بعدي شر ثم قاتلهم قتالا شديدا ثم راضخهم بالحجارة وقد قال أبو سفيان لأصحاب اللواء من بني عبد الدار يحرضهم بذلك على القتال يا بني عبد الدار إنكم وليتم لواءنا يوم بدر فأصابنا ما قد رأيتم وإنما يؤتى الناس من قبل راياتهم إذا زالت زالوا فإما أن تكفونا لواءنا وإما أن تخلوا بيننا وبينه فسنكفيكموه فهموا به وتوعدوه وقالوا نحن نسلم إليك لواءنا ستعلم غدا إذا التقينا كيف نصنع وذلك الذي أراد أبو سفيان فلما التقى الناس ودنا بعضهم من بعض قامت هند بنت عتبة في النسوة اللواتي معها وأخذن الدفوف يضربن خلف الرجال ويحرضنهم فقالت هند فيما تقول - مجزوء الرجز -\n(إن تقبلوا نعانق ... ونفرش النمارق)\n(أو تدبروا نفارق ... فراق غير وامق)\nتقول - مجزوء الرجز -\n(إيها بني عبد الدار ... إيها حماة الأدبار)\n(ضربا بكل بتار ... )\nاقتتل الناس حتى حميت الحرب وقاتل أبو دجانة حتى أمعن في الناس وحمزة ابن عبد المطلب وعلي بن أبي طالب عليهما السلام في رجال من المسلمين فأنزل الله نصره وصدقهم وعده فحسوهم بالسيف حتى كشفوهم وكانت الهزيمة\nوعن محمد بن إسحاق عن يحيى بن عباد بن عبد الله بن الزبير عن أبيه عن جده قال قال الزبير والله لقد رأيتني أنظر إلى هند بنت عتبة وصواحبها مشمرات هوارب ما دون أخذهن قليل ولا كثير إذ مالت الرماة إلى الكر حتى كشفنا القوم عنه يريدون النهب وخلوا ظهورنا للخيل فأتينا من أدبارنا وصرخ صارخ ألا إن محمدا قد قتل فانكفأنا وانكفأ علينا القوم بعد أن أصبنا أصحاب اللواء حتى ما يدنو إليه أحد من القوم وعن محمد بن إسحاق عن بعض أهل العلم أن اللواء لم يزل صريعا حتى أخذته عمرة بنت علقمة الحارثية فرفعته لقريش فلاذوا بها وكان اللواء مع صواب غلام لبني أبي طلحة حبشي فكان آخر من أخذه منهم فقاتل حتى قطعت يداه فبرك عليه وأخذ اللواء بصدره وعنقه حتى قتل عليه وهو يقول اللهم قد أعذرت فقال حسان بن ثابت في قطع يد صواب حين تقاذفوا بالشعر وافر\n(فخرتم باللواء وشر فخر ... لواء حين رد إلى صواب)\n(جعلتم فخركم فيها لعبد ... من الأم من وطي عفر التراب)\n(ظننتم والسفيه له ظنون ... وما إن ذاك من أمر الصواب)\n(بأن جلادنا يوم التقينا ... بمكة بيعكم حمر العياب)\n(أقر العين إن عصبت يداه ... وما أن يعصبان على خضاب)\nقال محمد بن جرير وحدثنا أبو كريب قال حدثنا عثمان بن سعيد قال حدثنا حبان بن علي عن محمد بن عبيد الله بن أبي رافع عن أبيه عن جده قال لما قتل أصحاب الألوية يوم أحد قتلهم علي بن أبي طالب عليه السلام أبصر رسول الله جماعة من مشركي قريش فقال لعلي احمل عليهم فحمل علي ففرق جمعهم وقتل عمرو بن عبد الله بن الجمحي ثم أبصر جماعة من","topic":"نسب ابن الزبعرى وأخباره وقصة غزوة أحد","topicNo":185,"sp":5,"spl":"رجع إلى حديث ابن إسحاق","partial":1},
{"id":"b185-7","bab":"الجزء 15","sec":"رجع إلى حديث ابن إسحاق","page":"ج15 ص184","text":"مشركي قريش فقال لعلي احمل فحمل علي ففرق جمعهم وقتل شيبة بن مالك أحد بني عامر بن لؤي فقال جبريل عليه السلام يا رسول الله إن هذه للمواساة فقال رسول الله ( هو مني وأنا منه\nفقال جبريل عليه السلام وأنا منكم قال فسمعوا صوتا - مجزوء الكامل -\n(لا سيف إلا ذو الفقار ... ولا فتى إلا علي)\nلما أتي المسلمون من خلفهم انكشفوا وأصاب منهم المشركون وكان المسلمون لما أصابهم ما أصابهم من البلاء أثلاثا ثلث قتيل وثلث جريح وثلث منهزم وقد جهدته الحرب حتى ما يدري ما يصنع وأصيبت رباعية رسول الله السفلى وشقت شفته وكلم في وجنته وجبهته في أصول شعره وعلاه ابن قمئة بالسيف على شقه الأيمن وكان الذي أصابه عتبة بن أبي وقاص قال محمد بن جرير وحدثنا ابن يسار قال حدثنا ابن أبي عدي عن حميد عن أنس بن مالك قال لما كان يوم أحد كسرت رباعية رسول الله وشج فجعل الدم يسيل على وجهه وجعل يمسح الدم عن وجهه ويقول ( كيف يفلح قوم خضبوا وجه نبيهم بالدم وهو يدعوهم إلى الله تعالى\nفأنزل الله عز و جل ( ليس لك من الأمر شيء أو يتوب عليهم\nلآية وقد قال رسول الله حين غشيه القوم ( من رجل يشري لي نفسه\nال محمد فحدثني ابن حميد قال حدثنا سلمة قال حدثني محمد بن إسحاق قال حدثني الحصين بن عبد الرحمن بن عمرو بن سعد بن معاذ عن محمود بن عمرو بن يزيد بن السكن قال فقام زياد بن السكن في نفر خمسة من الأنصار وبعض الناس يقول إنما هو عمارة بن زياد بن السكن فقاتلوا دون\nرسول الله رجلا ثم رجلا يقتلون دونه حتى كان آخرهم زياد بن عمارة بن زياد بن السكن فقاتل حتى أثبتته الجراحة ثم فاءت من المسلمين فئة حتى أجهضوهم عنه فقال رسول الله أدنوه مني فأدنوه منه فوسده قدمه فمات وخده على قدم رسول الله وترس من دون النبي أبو دجانة بنفسه يقع النبل في ظهره وهو منحن عليه حتى كثرت فيه النبل ورمى سعد بن أبي وقاص دون رسول الله قال سعد فلقد رأيته يناولني ويقول فداك أبي وأمي حتى إنه ليناولني السهم ما فيه نصل فيقول ارم به وعن محمد بن إسحاق قال حدثني عاصم بن عمر بن قتادة أن رسول الله رمى عن قوسه حتى اندقت سيتها فأخذها قتادة بن النعمان فكانت عنده وأصيبت يومئذ عين قتادة حتى وقعت على وجنته وعن محمد بن إسحاق قال حدثني عاصم بن عمر بن قتادة أن رسول الله ردها بيده فكانت أحسن عينيه وأحدهما وقاتل مصعب بن عمير دون رسول الله ومعه لواؤه حتى قتل وكان الذي أصابه ابن قمئة الليثي وهو يظن أنه رسول الله فرجع إلى قريش فقال قد قتلت محمدا فلما قتل مصعب بن عمير أعطى رسول الله اللواء علي بن أبي طالب عليه السلام وقاتل حمزة بن عبد المطلب رضي الله عنه حتى قتل أرطاة بن شرحبيل بن هاشم بن عبد مناف بن عبد الدار بن قصي وكان أحد النفر الذين يحملون اللواء ثم مر به سباع بن عبد العزى الغبشاني وكان يكنى أبا نيار فقال له حمزة هلم إلي يا ابن مقطعة البظور وكانت أمه ختانة بمكة مولاة شريق بن عمرو بن وهب الثقفي فلما التقيا ضربه حمزة عليه السلام فقتله فقال وحشي غلام جبير بن مطعم إني لأنظر إلى","topic":"نسب ابن الزبعرى وأخباره وقصة غزوة أحد","topicNo":185,"sp":6,"spl":"رجع إلى حديث ابن إسحاق"},
{"id":"b185-8","bab":"الجزء 15","sec":"رجع إلى حديث ابن إسحاق","page":"ج15 ص184","text":"حمزة يهذ الناس بسيفه ما يليق شيئا يمر به مثل الجمل الأورق إذ تقدمني إليه سباع بن عبد العزى فقال له حمزة هلم إلي يا ابن مقطعة البظور فضربه فما أخطأ رأسه وهززت حربتي حتى إذا ما رضيت دفعتها عليه فوقعت عليه في لبته حتى خرجت من بين رجليه وأقبل نحوي فغلب فوقع فأمهلته حتى إذا مات جئت فأخذت حربتي ثم تنحيت إلى العسكر ولم يكن لي بشيء حاجة غيره وقد قتل عاصم بن ثابت بن أبي الأقلح أحد بني عمرو بن عوف مسافع ابن طلحة وأخاه كلاب بن طلحة كلاهما يشعره سهما فيأتي أمه فيضع رأسه في حجرها فتقول يا بني من أصابك فيقول سمعت رجلا يقول حين رماني خذها إليك وأنا ابن أبي الأقلح فتقول أقلحي فنذرت لله إن الله أمكنها من رأس عاصم أن تشرب فيه الخمر وكان عاصم قد عاهد الله عز و جل أن لا يمس مشركا ولا يمسه عن ابن إسحاق قال حدثني القاسم بن عبد الرحمن بن رافع أخو بني عدي بن النجار قال انتهى أنس بن النضر عم أنس بن مالك إلى عمر بن الخطاب وطلحة بن عبيد الله في رجال من المهاجرين والأنصار وقد ألقوا بأيديهم فقال ما يجلسكم ههنا فقالوا قتل رسول الله قال فما تصنعون بالحياة بعده قوموا فموتوا كراما على ما مات عليه ثم استقبل القوم فقاتل حتى قتل وبه سميى أنس بن مالك عن ابن إسحاق قال حدثني حميد الطويل عن أنس بن مالك قال لقد وجدنا بأنس بن النضر يومئذ سبعين ضربة وطعنة فما عرفته إلا أخته عرفته بحسن بنانه\nعن ابن إسحاق قال كان أول من عرف رسول الله بعد الهزيمة وقول الناس قتل رسول الله كما حدثني ابن شهاب الزهري كعب بن مالك أخو بني سلمة قال عرفت عينيه تزهران تحت المغفر فناديت بأعلى صوتي يا معشر المسلمين أبشروا هذا رسول الله فأشار إلي أن أنصت فلما عرف المسلمون رسول الله نهضوا به ونهض نحو الشعب معه أبو بكر بن أبي قحافة وعمر بن الخطاب وعلي بن أبي طالب وطلحة بن عبيد الله والزبير بن العوام والحارث بن الصمة في رهط من المسلمين رضي الله عنهم أجمعين فلما أسند رسول الله في الشعب أدركه أبي بن خلف وهو يقول يا محمد لا نجوت إن نجوت فقال القوم يا رسول الله أيعطف عليه رجل منا فقال دعوه فلما دنا تناول رسول الله الحربة من الحارث بن الصمة قال يقول بعض الناس فيما ذكر لي فلما أخذها رسول الله انتفض بها انتفاضة تطايرنا عنه تطاير الشعراء عن ظهر البعير إذا انتفض ثم استقبله فطعنه في عنقه طعنة تدأدأ بها عن فرسه مرارا وكان أبي بن خلف كما حدثنا ابن حميد قال حدثنا سلمة عن ابن إسحاق عن صالح عن إبراهيم بن عبد الرحمن بن عوف يلقى رسول الله بمكة فيقول يا محمد إن عندي العود أعلفه كل يوم فرقا من ذرة أقتلك عليه فيقول رسول الله بل أنا أقتلك إن شاء الله تعالى فلما رجع إلى قريش وقد خدشه في حلقه خدشا غير كبير فاحتقن الدم قال قتلني والله محمد قالوا ذهب والله فؤادك والله ما بك بأس قال إنه\nكان بمكة قال لي أنا أقتلك فوالله لو بصق علي لقتلني فمات عدو الله بسرف وهم قافلون به إلى مكة فلما انتهى رسول الله إلى فم الشعب خرج علي بن أبي طالب حتى ملأ درقته من المهراس ثم جاء به إلى رسول الله فشرب منه وغسل عن وجهه الدم وصب على رأسه وهو يقول ( اشتد غضب الله على من دمى وجه نبيه\nال محمد بن إسحاق حدثني صالح بن كيسان عمن حدثه عن سعد بن أبي وقاص أنه كان يقول والله ما حرصت على قتل رجل قط ما حرصت على قتل عتبة ابن أبي وقاص وإن كان ما علمت لسيئ الخلق مبغضا في قومه ولقد كفاني منه قول رسول الله ( اشتد غضب الله عز و جل على من دمى وجه رسول الله\nال حدثنا محمد بن إسحاق قال حدثني صالح بن كيسان قال خرجت هند والنسوة اللواتي معها يمثلن بالقتلى من أصحاب رسول الله يجدعن الآذان والآنف حتى اتخذت هند من آذان الرجال وآنفهم خدما وقلائد وأعطت خدمها وقلائدها وقرطها وحشيا غلام جبير بن مطعم وبقرت عن كبد حمزة عليه السلام فأخرجت كبده فلاكتها فلم تستطع أن تسيغها فلفظتها ثم علت على صخرة مشرفة فصاحت بأعلى صوتها بما قالت من الشعر حين ظفروا بما أصابوا من أصحاب رسول الله قال حدثني صالح بن كيسان أنه حدث أن عمر بن الخطاب رضوان الله عليه قال لحسان يا ابن الفريعة لو سمعت ما تقول هند ورأيت أشرها قائمة على","topic":"نسب ابن الزبعرى وأخباره وقصة غزوة أحد","topicNo":185,"sp":7,"spl":"رجع إلى حديث ابن إسحاق"},
{"id":"b185-9","bab":"الجزء 15","sec":"رجع إلى حديث ابن إسحاق","page":"ج15 ص184","text":"صخرة ترتجز بنا وتذكر ما صنعت بحمزة قال له حسان والله إني لأنظر إلى الحربة تهوي وإني على رأس فارع يعني أطمه فقلت والله إن هذه لسلاح ما هي بسلاح العرب وكأنها إنما تهوي إلى حمزة ولا أدري أسمعني بعض قولها أكفكموها قال فأنشده عمر بعض ما قالت فقال حسان يهجو هندا - كامل -\n(أشرت لكاع وكان عادتها ... لؤما إذا أشرت من الكفر)\n(لعن الإله وزوجها معها ... هند الهنود طويلة البظر)\n(أخرجت مرقصة إلى أحد ... في القوم مقتبة على بكر)\n(بكر ثفال لا حراك به ... لا عن معاتبة ولا زجر)\n(وعصاك استك تتقين بها ... دقي العجاية منك بالفهر)\n(قرحت عجيزتها ومشرجها ... من دأبها نصا على القتر)\n(ظلت تداويها زميلتها ... بالماء تنضحه وبالسدر)\n(أخرجت ثائرة مبادرة ... بأبيك فاتك يوم ذي بدر)\n(وبعمك المستوه في ردع ... وأخيك منعفرين في الجفر)\n(ونسيت فاحشة أتيت بها ... يا هند ويحك سيئة الذكر)\n(فرجعت صاغرة بلا تره ... منا ظفرت بها ولا نصر)\n(زعم الولائد أنها ولدت ... ولدا صغيرا كان من عهر)\nقال محمد بن جرير ثم إن أبا سفيان بن حرب أشرف على القوم فيما حدثنا هارون بن إسحاق قال حدثنا مصعب بن المقدام قال حدثنا إسرائيل وحدثنا ابن وكيع قال حدثنا أبي عن إسرائيل قال حدثنا ابن إسحاق عن البراء قال ثم إن أبا سفيان أشرف علينا فقال أفي القوم محمد فقال رسول الله لا تجيبوه مرتين ثم قال أفي القوم ابن أبي قحافة ثلاثا فقال رسول الله لا تجيبوه ثم التفت إلى أصحابه فقال أما هؤلاء فقد قتلوا لو كانوا في الأحياء لأجابوا فلم يملك عمر بن الخطاب رضي الله عنه نفسه أن قال كذبت يا عدو الله قد أبقى الله لك ما يخزيك فقال أعل هبل أعل هبل فقال رسول الله أجيبوه قالوا ما نقول قال قالوا ( الله أعلى وأجل\nقال أبو سفيان لنا العزى ولا عزى لكم فقال رسول الله أجيبوه قالوا ما نقول قال قولوا الله مولانا ولا مولى لكم قال أبو سفيان يوم بيوم بدر والحرب سجال أما إنكم ستجدون في القوم مثلا لم آمر بها ولم تسؤني قال ابن إسحاق في حديثه لما أجاب عمر رضي الله عنه أبا سفيان قال له أبو سفيان هلم يا عمر فقال رسول الله ايته فانظر ما شأنه فجاءه فقال له أبو\nسفيان أنشدك الله يا عمر أقتلنا محمدا فقال عمر اللهم لا وإنه ليسمع كلامك الآن قال أنت أصدق عندي من ابن قمئة وأبر لقول ابن قمئة لهم إني قتلت محمدا ثم نادى أبو سفيان فقال إنه قد كان مثل والله ما رضيت ولا سخطت ولا أمرت ولا نهيت وقد كان الحليس بن زبان أخو بني الحارث بن عبد مناة وهو يومئذ سيد الأحابيش قد مر بأبي سفيان بن حرب وهو يضرب في شدق حمزة عليه السلام وهو يقول ذق عقق فقال الحليس يا بني كنانة هذا سيد قريش يصنع بابن عمه كما ترون لحما فقال اكتمها علي فإنها كانت زلة قال فلما انصرف أبو سفيان ومن معه نادى أن موعدكم بدر العام المقبل فقال رسول الله لرجل من أصحابه ( قل نعم هي بيننا وبينك موعد\nم بعث رسول الله علي بن أبي طالب عليه السلام فقال اخرج في آثار القوم فانظر ماذا يصنعون فإن كانوا قد جنبوا وامتطوا الإبل فإنهم يريدون مكة وإن ركبوا الخيل وساقوا الإبل فهم يريدون المدينة فوالذي نفسي بيده لئن أرادوها لأسيرن إليهم ثم لأناجزنهم قال علي فخرجت في آثارهم أنظر ما يصنعون فلما جنبوا الخيل وامتطوا الإبل توجهوا إلى مكة وكان رسول الله قال لي أي ذلك كان فأخفه حتى يأتيني قال علي فلما رأيتهم قد توجهوا إلى مكة أقبلت أصيح ما أستطيع أن أكتم الذي أمرني به رسول الله لما بي من الفرح إذ رأيتهم انصرفوا إلى مكة عن المدينة وفرغ الناس لقتلاهم فقال رسول الله كما حدثنا ابن حميد قال حدثنا سلمة قال حدثني محمد بن إسحاق عن محمد بن عبد الله بن عبد الرحمن بن أبي صعصعة المازني أخي بني النجار أن رسول الله قال ( من رجل ينظر لي ما فعل سعد بن الربيع وسعد أخو بني الحارث بن الخزرج أفي الأحياء هو أم في الأموات\nفقال رجل من الأنصار أنا أنظر لك يا رسول الله ما فعل فنظر فوجده جريحا في القتلى به رمق قال فقلت له إن رسول الله أمرني أن أنظر له أفي الأحياء أنت أم في","topic":"نسب ابن الزبعرى وأخباره وقصة غزوة أحد","topicNo":185,"sp":8,"spl":"رجع إلى حديث ابن إسحاق"},
{"id":"b185-10","bab":"الجزء 15","sec":"رجع إلى حديث ابن إسحاق","page":"ج15 ص184","text":"الأموات قال فأنا في الأموات أبلغ رسول الله وقل له إن سعد بن الربيع يقول لك جزاك الله خير ما جزى نبيا عن أمته وأبلغ قومك عني السلام وقل لهم إن سعد بن الربيع يقول لا عذر لكم عند الله جل وعز إن خلص إلى نبيكم وفيكم عين تطرف ثم لم أبرح حتى مات رحمه الله فجئت رسول الله وأخبرته وخرج رسول الله فيما بلغني يلتمس حمزة بن عبد المطلب عليه السلام فوجده ببطن الوادي قد بقر بطنه عن كبده ومثل به فجدع أنفه وأذناه وعن ابن إسحاق قال فحدثني محمد بن جعفر بن الزبير أن رسول الله قال حين رأى بحمزة ما رأى ( لولا أن تحزن صفية أو تكون سنة من بعدي لتركته حتى يكون في أجواف السباع وحواصل الطير ولئن أنا أظهرني الله على قريش في موطن من المواطن لأمثلن بثلاثين رجلا منهم\nلما رأى المسلمون حزن رسول الله وغيظه على ما فعل بعمه قالوا والله لئن أظهرنا الله عليهم يوما من الدهر لنمثلن بهم مثلة لم يمثلها أحد من العرب بأحد قط وعن محمد بن إسحاق قال حدثني بريدة بن سفيان بن فروة الأسلمي عن محمد بن كعب القرظي عن ابن عباس قال ابن حميد قال سلمة وحدثني محمد بن إسحاق قال فحدثنا الحسن بن عمارة عن الحكم بن عتيبة عن مقسم عن ابن عباس أن الله عز و جل أنزل في ذلك من قول رسول الله ( وإن عاقبتم فعاقبوا بمثل ما عوقبتم به ولئن صبرتم لهو خير للصابرين\nإلى آخر السورة فعفا رسول الله وصبر ونهى عن المثلة قال ابن إسحاق فيما بلغني خرجت صفية بنت عبد المطلب لتنظر إلى حمزة وكان أخاها لأمها فقال رسول الله لابنها الزبير القها فأرجعها لا ترى ما\nبأخيها فلقيها الزبير فقال يا أمه إن رسول الله يأمرك أن ترجعي فقالت ولم فقد بلغني أنه مثل بأخي وذلك في الله جل وعز قليل فما أرضانا بما كان من ذلك لأحتسبن ولأصبرن إن شاء الله تعالى فلما جاء الزبير رسول الله فأخبره بذلك قال خل سبيلها فأتته فنظرت إليه وصلت عليه واسترجعت واستغفرت له ثم أمر رسول الله به فدفن قال حدثني محمد بن إسحاق قال حدثني عاصم بن عمر بن قتادة عن محمود بن لبيد قال لما خرج رسول الله إلى أحد رجع حسيل بن جابر وهو اليمان أبو حذيفة بن اليمان وثابت بن وقش بن زعورا في الآطام مع النساء والصبيان فقال أحدهما لصاحبه وهما شيخان كبيران لا أبا لك ما تنتظر فوالله إن بقي لواحد منا من عمره إلا ظمء حمار إنما نحن هامة اليوم أو غد أفلا نأخذ أسيافنا ثم نلحق برسول الله لعل الله يرزقنا شهادة معه فأخذا أسيافهما ثم خرجا حتى دخلا في الناس ولم يعلم أحد بهما فأما ثابت بن وقش فقتله المشركون وأما حسيل بن جابر اليمان فاختلفت عليه أسياف المسلمين فقتلوه ولم يعرفوه فقال حذيفة أبي قالوا والله إن عرفناه وصدقوا قال حذيفة يغفر الله لكم وهو أرحم الراحمين فأراد رسول الله أن يديه فتصدق حذيفة بديته على المسلمين فزادته عند رسول الله خيرا قال حدثني محمد بن إسحاق عن عاصم بن عمر بن قتادة قال كان فينا رجل أتي لا ندري من أين هو يقال له قزمان فكان رسول الله يقول إذا ذكره ( إنه لمن أهل النار\nفلما كان يوم أحد قاتل قتالا شديدا فقتل هو وحده","topic":"نسب ابن الزبعرى وأخباره وقصة غزوة أحد","topicNo":185,"sp":9,"spl":"رجع إلى حديث ابن إسحاق"},
{"id":"b185-11","bab":"الجزء 15","sec":"رجع إلى حديث ابن إسحاق","page":"ج15 ص184","text":"ثمانية من المشركين أو تسعة وكان شهما شجاعا ذا بأس فأثبتته الجراحة فاحتمل إلى دار بني ظفر قال فجعل رجال من المسلمين يقولون والله لقد أبليت اليوم يا قزمان فأبشر قال بم أبشر فوالله إن قاتلت إلا على أحساب قومي ولولا ذلك ما قاتلت فلما اشتدت عليه جراحته أخذ سهما من كنانته فقطع رواهشه فنزفه الدم فمات فأخبر رسول الله بذلك فقال إني رسول الله حقا وعن محمد بن إسحاق قال حدثني حسين بن عبد الله عن عكرمة قال كان يوم أحد يوم السبت للنصف من شوال فلما كان الغد من يوم أحد وذلك يوم الأحد لست عشرة ليلة خلت من شوال أذن مؤذن رسول الله في الناس بطلب العدو وأذن مؤذنه أن لا يخرجن معنا إلا من حضر يومنا بالأمس فكلمه جابر بن عبد الله بن عمرو بن حرام الأنصاري فقال يا رسول الله إن أبي كان خلفني على أخوات لي سبع وقال لي يا بني إنه لا ينبغي لي ولا لك أن نترك هؤلاء النسوة بلا رجل فيهن ولست بالذي أوثرك بالجهاد مع رسول الله على نفسي فتخلف على أخواتك فتخلفت عليهن فأذن له رسول الله فخرج معه وإنما خرج رسول الله مرهبا للعدو وأنهم خرجوا في طلبهم فيظنون أن بهم قوة وأن الذي أصابهم لم يوهنهم عن عدوهم عن محمد بن إسحاق قال فحدثني عبد الله بن خارجة بن زيد بن ثابت عن أبي السائب مولى عائشة بنت عثمان بن عفان أن رجلا من أصحاب رسول الله من بني عبد الأشهل كان شهد أحدا قال فشهدت رسول الله أنا وأخ لي فرجعنا جريحين فلما أذن مؤذن رسول الله بالخروج في طلب العدو قلت لأخي وقال لي أتفوتنا غزوة مع رسول الله والله ما لنا من دابة نركبها وما منا إلا جريح ثقيل فخرجنا مع رسول الله وكنت أيسر جرحا منه فكنت إذا غلب عليه حملته عقبة حتى انتهينا إلى ما انتهى إليه المسلمون فخرج إليه\nرسول الله حتى انتهينا إلى حمراء الأسد وهي من المدينة على ثمانية أميال فأقام بها ثلاثا الاثنين والثلاثاء والأربعاء ثم رجع إلى المدينة قال ابن إسحاق عن عبد الله بن أبي بكر بن محمد بن عمرو بن حزم أنه مر برسول الله معبد الخزاعي وكانت خزاعة مسلمهم ومشركهم عيبة رسول الله لا يخفون عليه شيئا كان بها ومعبد يومئذ مشرك فقال يا محمد لقد عز علينا ما أصابك في أصحابك ولوددت أن الله قد أعفاك منهم ثم خرج من عند رسول الله بحمراء الأسد حتى لقي أبا سفيان بن حرب بالروحاء ومن معه وقد أجمعوا الرجعة إلى رسول الله وقالوا أصبنا جد أصحابه وقادتهم وأشرافهم ثم رجعنا قبل أن نستأصلهم لنكرن على بقيتهم فلنفرغن منهم فلما رأى أبو سفيان معبدا قال ما وراءك يا معبد قال محمد قد خرج في أصحابه يطلبكم في جمع لم أر مثله قط يتحرقون عليكم تحرقا قد اجتمع معه من كان تخلف عنه في يومكم وندموا على ما صنعوا فيهم من الحنق عليكم شيء لم أر مثله قط قال ويلك ما تقول قال والله ما أراك ترتحل حتى ترى نواصي الخيل قال فوالله لقد أجمعنا الكرة لنستأصل شأفتهم قال فإني أنهاك عن ذلك فوالله لقد حملني ما رأيت على أن قلت فيه أبياتا من شعر قال وماذا قلت قال قلت - بسيط -\n(كادت تهد من الأصوات راحلتي ... إذ سالت الأرض بالجرد الأبابيل)\n(فظلت عدوا أظن الأرض مائلة ... لما سموا برئيس غير مخذول)\n(فقلت ويل بن حرب من لقائكم ... إذا تغطمطت البطحاء بالجيل)\n(إني نذير لأهل السيل ضاحية ... لكل ذي إربة منهم ومعقول)\n(من جيش أحمد لا وخش تنابلة ... وليس يوصف ما أنذرت بالقيل)\nال فثنى ذلك أبا سفيان ومن معه ومر به ركب من عبد القيس فقال أين تريدون قالوا نريد المدينة قال فلم قالوا نريد الميرة قال فهل أنتم مبلغون عني محمدا رسالة أرسلكم بها إليه وأحمل لكم إبلكم هذه غدا زبيبا بعكاظ إذا وافيتموها قالوا نعم قال فإذا جئتموه فأخبروه أن قد أجمعنا السير إليه وإلى أصحابه لنستأصل شأفتهم فمر الركب برسول الله فأخبروه بالذي قال أبو سفيان فقال رسول الله وأصحابه ( حسبنا الله ونعم الوكيل\nوت - وافر -\n(أمن ريحانة الداعي السميع ... يؤرقني وأصحابي هجوع)\n(براني حب من لا أستطيع ... ومن هو للذي أهوى منوع)\n(إذا لم تستطع شيئا فدعه ... وجاوزه إلى ما تستطيع)","topic":"نسب ابن الزبعرى وأخباره وقصة غزوة أحد","topicNo":185,"sp":10,"spl":"رجع إلى حديث ابن إسحاق"},
{"id":"b185-12","bab":"الجزء 15","sec":"رجع إلى حديث ابن إسحاق","page":"ج15 ص184","text":"لشعر لعمرو بن معد يكرب الزبيدي والغناء للهذلي ثقيل أول بإطلاق الوتر في مجرى الوسطى من رواية إسحاق وفيه ثقيل أول على مذهب إسحاق من رواية عمرو بن بانة وفيه لابن سريج رمل بالوسطى من رواية حماد عن أبيه","topic":"نسب ابن الزبعرى وأخباره وقصة غزوة أحد","topicNo":185,"sp":11,"spl":"رجع إلى حديث ابن إسحاق"},
{"id":"b186-1","bab":"الجزء 15","sec":"ذكر عمرو بن معديكرب وأخباره","page":"ج15 ص200","text":"هو عمرو بن معديكرب بن عبد الله بن عمرو بن عصم بن عمرو بن زبيد وهو منبه هكذا ذكر محمد بن سلام فيما أخبرنا به أبو خليفة عنه وذكر عمر بن شبة عن أبي عبيدة أنه عمرو بن معديكرب بن ربيعة بن عبد الله بن عمرو بن عصم بن زبيد بن منبه بن سلمة بن مازن بن ربيعة بن منبه بن صعب بن سعد العشيرة بن مذحج بن أدد بن زيد بن يشجب بن عريب بن زيد بن كهلان بن سبأ بن يشجب بن يعرب بن قحطان ويكنى أبا ثور وأمه وأم أخيه عبد الله امرأة من جرم فيما ذكر وهي معدودة من المنجبات أخبرنا محمد بن دريد قال أخبرنا أبو حاتم عن أبي عبيدة قال عمرو بن معديكرب فارس اليمن وهو مقدم على زيد الخيل في الشدة والبأس\nوروى علي بن محمد المدائني عن زيد بن قحيف الكلابي قال سمعت أشياخنا يزعمون أن عمرو بن معديكرب كان يقال له مائق بني زبيد فبلغهم أن خثعم تريدهم فتأهبوا لهم وجمع معديكرب بني زبيد فدخل عمرو على أخته فقال أشبعيني إني غدا لكتيبة قال فجاء معديكرب فأخبرته ابنته فقال هذا المائق يقول ذاك قالت نعم قال فسليه ما يشبعه فسألته فقال فرق من ذرة وعنز رباعية قال وكان الفرق يومئذ ثلاثة أصوع فصنع له ذلك وذبح العنز وهيأ له الطعام قال فجلس عليه فسلته جميعا وأتتهم خثعم الصباح فلقوهم وجاء عمرو فرمى بنفسه ثم رفع رأسه فإذا لواء أبيه قائم فوضع رأسه فإذا لواء أبيه قد زال فقام كأنه سرحة محرقة فتلقى أباه وقد انهزموا فقال انزل عنها فاليوم ظلم فقال له إليك يا مائق فقال له بنو زبيد خله أيها الرجل وما يريد فإن قتل كفيت مؤنته وإن ظهر فهو لك فألقى إليه سلاحه فركب ثم رمى خثعم بنفسه حتى خرج من بين أظهرهم ثم كر عليهم وفعل ذلك مرارا وحملت عليهم بنو زبيد فانهزمت خثعم وقهروا فقيل له يومئذ فارس زبيد قال أبو عمرو الشيباني كان من حديث عمرو بن معديكرب بن ربيعة بن عبد الله بن زبيد بن منبه بن سلمة بن مازن بن ربيعة بن منبه بن صعب بن سعد العشيرة بن مالك وهو مذحج بن أدد بن زيد بن يشجب بن عريب بن زيد بن\nكهلان بن سبأ بن يشجب بن يعرب بن قحطان أنه قال لقيس بن مكشوح المرادي وهو ابن أخت عمرو حين انتهى إليهم أمر رسول الله يا قيس إنك سيد قومك وقد ذكر لنا أن رجلا من قريش يقال له محمد قد خرج بالحجاز يقال له نبي فانطلق بنا حتى نعلم علمه وبادر فروة لا يغلبك على الأمر فأبى قيس ذلك وسفه رأيه وعصاه فركب عمرو متوجها إلى النبي وقال خالفتني يا قيس وقال عمرو في ذلك - مجزوء الوافر -\n(أمرتك يوم ذي صنعاء ... أمرا بينا رشده)\n(أمرتك باتقاء الله ... تأتيه وتتعده)\n(فكنت كذي الحمير غره ... من أيره وتده)\nال أبو عبيدة حدثنا غير واحد من مذحج قالوا قدم علينا وفد مذحج مع فروة بن مسيك المرادي على النبي فأسلموا وبعث فروة صدقات من أسلم منهم وقال له ادع الناس وتألفهم فإذا وجدت الغفلة فاهتبلها واغز قال أبو عمرو الشيباني وإنما رحل فروة مفارقا لملوك كندة مباعدا لهم إلى رسول الله وقد كانت قبل الإسلام بين مراد وهمدان وقعة أصابت فيها همدان من مراد حتى أثخنوهم في يوم يقال له يوم الرزم وكان الذي قاد همدان إلى مراد الأجدع بن مالك بن حريم الشاعر الهمداني بن مسروق بن الأجدع ففضحهم يومئذ وفي ذلك يقول فروة بن مسيك المرادي - وافر\n(فإن نغلب فغلابون قدما ... وإن نهزم فغير مهزمينا)\nلما توجه فروة إلى النبي أنشأ يقول - كامل -\n(لما رأيت ملوك كندة أعرضت ... كالرجل خان الرجل عرق نساها)\n(يممت راحلتي أمام محمد ... أرجو فواضلها وحسن ثراها)\nلما انتهى إلى رسول الله قال له فيما بلغنا هل ساءك ما أصاب قومك يوم الرزم قال يا رسول الله من ذا الذي يصيب قومه مثل الذي أصاب قومي ولا يسوؤه فقال له أما إن ذلك لم يزد قومك في الإسلام إلا خيرا واستعمله على مراد وزبيد ومذحج كلها قال أبو عبيدة فلم يلبث عمرو أن ارتد عن الإسلام فقال حين ارتد - وافر -\n(وجدنا ملك فروة شر ملك ... حمار ساف منخره بقذر)\n(وإنك لو رأيت أبا عمير ... ملأت يديك من غدر وختر)","topic":"ذكر عمرو بن معديكرب وأخباره","topicNo":186,"sp":0,"spl":"ذكر عمرو بن معديكرب وأخباره"},
{"id":"b186-2","bab":"الجزء 15","sec":"ذكر عمرو بن معديكرب وأخباره","page":"ج15 ص200","text":"ال أبو عبيدة فلما ارتد عمرو مع من ارتد عن الإسلام من مذحج استجاش فروة النبي فوجه إليهم خالد بن سعيد بن العاص وخالد بن الوليد وقال لهما إذا اجتمعتم فعلي بن أبي طالب أميركم وهو على الناس ووجه عليا عليه السلام فاجتمعوا بكسر من أرض اليمن فاقتتلوا وقتل بعضهم ونجا بعض فلم يزل جعفر وزبيد وأود بنو سعد العشيرة بعدها قليلة وفي هذا الوجه وقعت\nالصمصامة إلى آل سعيد وكان سبب وقوعها إليهم أن ريحانة بنت معديكرب سبيت يومئذ ففداها خالد وأثابه عمرو الصمصامة فصار إلى أخيه سعيد فوجد سعيد جريحا يوم عثمان بن عفان رضي الله عنه حين حصر وقد ذهب السيف والغمد ثم وجد الغمد فلما قام معاوية جاءه أعرابي بالسيف بغير غمد وسعيد حاضر فقال سعيد هذا سيفي فجحد أعرابي مقالته فقال سعيد الدليل على أنه سيفي أن تبعث إلى غمده فتغمده فيكون كفافه فبعث معاوية إلى الغمد فأتى به من منزل سعيد فإذا هو عليه فأقر الأعرابي أنه أصابه يوم الدار فأخذه سعيد منه وأثابه فلم يزل عنده حتى أصعد المهدي من البصرة فلما كان بواسط بعث إلى سعيد فيه فقال إنه للسبيل فقال خمسون سيفا قاطعا أغنى من سيف واحد فأعطاهم خمسين ألف درهم وأخذه وذكر ابن النطاح أن المدائني حكى عن أبي اليقظان عن جويرية بن أسماء قال أقبل النبي من غزاة تبوك يريد المدينة فأدركه عمرو بن معديكرب الزبيدي في رجال من زبيد فتقدم عمرو ليلحق برسول الله فأمسك حتى أوذن به فلما تقدم رسول الله يسير قال حياك الله إلهك أبيت اللعن فقال رسول الله ( إن لعنة الله وملائكته والناس أجمعين على الذين لا يؤمنون بالله ولا باليوم الآخر فآمن بالله يؤمنك يوم الفزع الأكبر\nقال عمرو بن معديكرب وما الفزع الأكبر قال رسول الله ( إنه فزع ليس كما تحسب وتظن إنه يصاح بالناس صيحة لا يبقى حي إلا مات إلا ما شاء الله من ذلك ثم يصاح بالناس صيحة لا يبقى ميت إلا نشر ثم تلج تلك الأرض بدوي تنهد منه الأرض وتخر منه الجبال وتنشق السماء انشقاق القبطية الجديد ما شاء الله في ذلك\nثم تبرز النار فينظر إليها حمراء مظلمة قد صار لها لسان في السماء ترمي بمثل رؤوس الجبال من شرر النار فلا يبقى ذو روح إلا انخلع قلبه وذكر ذنبه أين أنت يا عمرو\nقال إني أسمع أمرا عظيما فقال رسول الله ( يا عمرو أسلم تسلم\nأسلم وبايع لقومه على الإسلام وذلك منصرف رسول الله من غزاة تبوك وكانت في رجب من سنة تسع وقال أبو هارون السكسكي البصري حدثني أبو عمرو المديني أن عمر بن الخطاب رضي الله عنه كان إذا نظر إلى عمرو قال الحمد لله الذي خلقنا وخلق عمرا تعجبا من عظم خلقه أخبرنا أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة عن خالد بن خداش عن أبي نميلة قال أخبرني رميح عن أبيه قال رأيت عمرو بن معديكرب في خلافة معاوية شيخا أعظم ما يكون من الرجال أجش الصوت إذا التفت التفت بجميع جسده وهذا خطأ من الرواية والصحيح أنه مات في آخر خلافة عمر رضي الله عنه ودفن بروذة بين قم والري ومن الناس من يقول إنه قتل في وقعة نهاوند قبره في ظاهرها موضع يعرف بقبديشجان وأنه دفن هناك يومئذ هو والنعمان بن مقرن وروي أيضا من وجه ليس بالموثوق به أنه أدرك خلافة عثمان رضي الله عنه روى ذلك ابن النطاح عن مروان ابن ضرار عن أبي إياس البصري عن أبيه عن جويرية الهذلي في حديث طويل قال رأيت عمرو بن معديكرب وأنا في","topic":"ذكر عمرو بن معديكرب وأخباره","topicNo":186,"sp":1,"spl":"ذكر عمرو بن معديكرب وأخباره"},
{"id":"b186-3","bab":"الجزء 15","sec":"ذكر عمرو بن معديكرب وأخباره","page":"ج15 ص200","text":"مسجد الكوفة في خلافة عثمان حين وجهه إلى الري كأنه بعير مهنوء وقال ابن الكلبي حدثني أسعر عن عمرو بن جرير الجعفي قال سمعت خالد بن قطن يقول خرج عمرو بن معد يكرب في خلافة عثمان رضي الله عنه إلى الري ودستبى فضربه الفالج في طريقه فمات بروذة أخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال أخبرني خالد بن خداش قال حدثنا حماد بن زيد عن مجالد عن الشعبي أن عمر بن الخطاب رضي الله عنه فرض لعمرو بن معد يكرب في ألفين فقال له يا أمير المؤمنين ألف ههنا وأومأ إلى شق بطنه الأيمن وألف ههنا وأومأ إلى شق بطنه الأيسر فما يكون هاهنا وأومأ إلى وسط بطنه فضحك عمر رضوان الله عليه وزاده خمسمائة قال علي بن محمد قال أبو اليقظان قال عمرو بن معد يكرب لو سرت بظعينة وحدي على مياه معد كلها ما خفت أن أغلب عليها ما لم يلقني حراها أو عبداها فأما الحران فعامر بن الطفيل وعتيبة بن الحارث بن شهاب وأما العبدان فأسود بني عبس يعني عنترة والسليك بن السلكة وكلهم قد لقيت فأما عامر بن الطفيل فسريع الطعن على الصوت وأما عتيبة فأول الخيل إذا غارت وآخرها إذا آبت وأما عنترة فقليل الكبوة شديد الكلب وأما السليك فبعيد الغارة كالليث الضاري قالوا فما تقول في العباس بن مرداس قال أقول فيه ما قال في - طويل -\n(إذا مات عمرو قلت للخيل أوطئوا ... زبيدا فقد أودى بنجدتها عمرو)\nوقام مغضبا وعلم أنهم أرادوا توبيخه بالعباس قال علي وقال أبو اليقظان أحسب في اللفظ غلطا وأنه إنما قال هجينا مضر لأن عنترة استرق والعباس لم يسترق قط أخبرني أبو خليفة قال حدثنا أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثنا أحمد بن جناب عن عيسى ابن يونس عن اسماعيل عن قيس أن عمر رضي الله عنه كتب إلى سعد بن أبي وقاص إني قد أمددتك بألفي رجل عمرو بن معد يكرب وطليحة بن خويلد وهو طليحة الأسدي فشاورهما في الحرب ولا تولهما شيئا أخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثنا أحمد بن جناب قال حدثنا عيسى بن يونس عن إسماعيل عن قيس قال شهدت القادسية وكان سعد على الناس فجاء رستم فجعل يمر بنا وعمرو بن معد يكرب الزبيدي يمر على الصفوف يحض الناس ويقول يا معشر المهاجرين كونوا أسدا أغنى شأنه فإنما الفارسي تيس بعد أن يلقي نيزكه قال وكان مع رستم أسوار لا تسقط له نشابة فقال له يا أبا ثور اتق ذاك فإنا لنقول له ذلك إذ رماه رمية فأصاب فرسه وحمل عليه عمرو فاعتنقه ثم ذبحه وسلبه سواري ذهب كانا عليه وقباء ديباج قال أبو زيد فذكر أبو عبيدة أن عمرا حمل يومئذ على رجل فقتله ثم\nصاح يا معشر بني زبيد دونكم فإن القوم يموتون وقال علي بن محمد المدائني وأخبرنا محمد بن الفضل وعبد ربه بن نافع عن إسماعيل عن قيس بن أبي حازم قال حضر عمرو الناس وهم يقاتلون فرماه رجل من العجم بنشابة فوقعت في كتفه وكانت عليه درع حصينة فلم تنفذ وحمل على العلج فعانقه فسقطا إلى الأرض فقتله عمرو وسلبه ورجع بسلبه وهو يقول - سريع -\n(أنا أبو ثور وسيفي ذو النون ... أضربهم ضرب غلام مجنون)\n(يال زبيد إنهم يموتون ... )\nال أبو عبيدة وقال في ذلك عمرو بن معد يكرب - سريع -\n(ألمم بسلمى قبل أن تظعنا ... إن لنا من حبها ديدنا)\n(قد علمت سلمى وجاراتها ... ما قطر الفارس إلا أنا)\n(شككت بالرمح حيازيمه ... والخيل تعدو زيما بيننا)\nنى فيه الغريض ثاني ثقيل بالسبابة في مجرى البنصر وفيه رمل بالبنصر يقال إنه لمعبد ويقال إنه من منحول يحيى المكي قال أبو عبيدة في رواية أبي زيد عمر بن شبة شهد عمرو بن معد يكرب القادسية وهو ابن مائة وست سنين وقال بعضهم بل ابن مائة وعشر قال ولما قتل العلج عبر نهر القادسية هو وقيس بن مكشوح المرادي ومالك بن الحارث الأشتر","topic":"ذكر عمرو بن معديكرب وأخباره","topicNo":186,"sp":2,"spl":"ذكر عمرو بن معديكرب وأخباره","song":1,"partial":1},
{"id":"b186-4","bab":"الجزء 15","sec":"ذكر عمرو بن معديكرب وأخباره","page":"ج15 ص200","text":"قال فحدثني يونس أن عمرو بن معد يكرب كان آخرهم وكانت فرسه ضعيفة فطلب غيرها فأتي بفرس فأخذ بعكوة ذنبه وأخلد به إلى الأرض فأقعى الفرس فرده وأتي بآخر ففعل به مثل ذلك فتحلحل ولم يقع فقال هذا على كل حال أقوى من تلك وقال لأصحابه إني حامل وعابر الجسر فإن أسرعتم بمقدار جزر الجزور وجدتموني وسيفي بيدي أقاتل به تلقاء وجهي وقد عقر بي القوم وأنا قائم بينهم وقد قتلت وجردت وإن أبطأتم وجدتموني قتيلا بينهم وقد قتلت وجردت ثم انغمس فحمل في القوم فقال بعضهم يا بني زبيد تدعون صاحبكم والله ما نرى أن تدركوه حيا فحملوا فانتهوا إليه وقد صرع عن فرسه وقد أخذ برجل فرس رجل من العجم فأمسكها وإن الفارس ليضرب الفرس فما تقدر أن تتحرك من يده فلما غشيناه رمى الأعجمي بنفسه وخلى فرسه فركبه عمرو وقال أنا أبو ثور كدتم والله تفقدونني قالوا أين فرسك قال رمي بنشابة فشب فصرعني وعار وروى هذا الخبر محمد بن عمر الواقدي عن ابن أبي سبرة عن أبي عيسى الخياط ورواه علي بن محمد أيضا عن مرة عن أبي إسماعيل الهمذاني عن طلحة بن مصرف فذكرا مثل هذا قال الواقدي وحدثني أسامة بن زيد عن أبان بن صالح قال قال عمرو بن معد يكرب يوم القادسية ألزموا خراطيم الفيلة السيوف فإنه ليس لها مقتل إلا خراطيمها ثم شد على رستم وهو على الفيل فضرب فيله فجذم عرقوبيه فسقط وحمل رستم على فرس وسقط من تحته خرج فيه أربعون ألف دينار فحازه\nالمسلمون وسقط رستم بعد ذلك عن فرسه فقتله قال علي بن محمد المدائني حدثني علي بن مجاهد عن ابن إسحاق قال لما ضرب عمرو الفيل وسقط رستم سقط على رستم خرج كان على ظهر الفيل فيه أربعون ألف دينار فمات رستم من ذلك وانهزم المشركون وقال الواقدي حدثني ابن أبي سبرة عن موسى بن عقبة عن أبي حبيبة مولى آل الزبير قال حدثنا نيار بن مكرم الأسلمي قال شهدت القادسية فرأيت يوما اشتد فيه القتال بيننا وبين الفرس ورأيت رجلا يفعل يومئذ بالعدو أفاعيل يقاتل فارسا ثم يقتحم عن فرسه ويربط مقوده في حقوه فيقاتل فقلت من هذا جزاه الله خيرا قالوا هذا عمرو بن معد يكرب أخبرني محمد بن الحسن بن دريد قال أخبرنا السكن بن سعيد عن محمد بن عباد عن ابن الكلبي عن خالد بن سعيد عن أبي محمد المرهبي قال كان شيخ يجالس عبد الملك بن عمير فسمعته يحدث قال قدم عيينة بن حصن الكوفة فأقام بها أياما ثم قال والله ما لي بأبي ثور عهد منذ قدمنا هذا الغائط يعني عمرو بن معد يكرب أسرج لي يا غلام فأسرج له فرسا أنثى من خيله فلما قربها إليه قال له ويحك أرأيتني ركبت أنثى في الجاهلية فأركبها في الإسلام فأسرج له حصانا فركبه وأقبل إلى محلة بني زبيد فسأل عن محلة عمرو فأرشد إليها فوقف ببابه ونادى أي أبا ثور اخرج إلينا فخرج إليه مؤتزرا كأنما كسر وجبر فقال أنعم صباحا أبا مالك فقال أوليس قد أبدلنا الله تعالى بهذا السلام عليكم قال دعنا مما لا نعرف انزل فإن عندي كبشا ساحا فنزل\n211 - فعمد إلى الكبش فذبحه ثم كشط عنه وعضاه وألقاه في قدر جماع وطبخه حتى إذا أدرك جاء بجفنة عظيمة فثرد فيها فأكفأ القدر عليها فقعدا فأكلاه ثم قال له أي الشراب أحب إليك أللبن أم ما كنا نتنادم عليه في الجاهلية قال أو ليس قد حرمها الله جل وعز علينا في الإسلام قال أنت أكبر سنا أم أنا قال أنت قال فأنت أقدم إسلاما أم أنا قال أنت قال فإني قد قرأت ما بين دفتي المصحف فوالله ما وجدت لها تحريما إلا أنه قال ( فهل أنتم منتهون\nفقلنا لا فسكت وسكتنا فقال له أنت أكبر سنا وأقدم إسلاما فجاءا فجلسا يتناشدان ويشربان ويذكران أيام الجاهلية حتى أمسيا فلما أراد عيينة الانصراف قال عمرو لئن انصرف أبو مالك بغير حباء إنه لوصمة علي فأمر بناقة له أرحبية كأنها جبيرة لجين فارتحلها وحمله عليها ثم قال يا غلام هات المزود فجاء بمزود فيه أربعة آلاف درهم فوضعها بين يديه فقال أما المال فوالله لا قبلته قال والله إنه لمن حباء عمر بن الخطاب رضي الله عنه فلم يقبله عيينة وانصرف وهو يقول - طويل -\n(جزيت أبا ثور جزاء كرامة ... فنعم الفتى المزدار والمتضيف)\n(قريت فأكرمت القرى وأفدتنا ... نخيلة علم لم يكن قط يعرف)\n(وقلت حلال أن تدير مدامة ... كلون انعقاق البرق والليل مسدف)\n(وقدمت فيها حجة عربية ... ترد إلى الإنصاف من ليس ينصف)","topic":"ذكر عمرو بن معديكرب وأخباره","topicNo":186,"sp":3,"spl":"ذكر عمرو بن معديكرب وأخباره"},
{"id":"b186-5","bab":"الجزء 15","sec":"ذكر عمرو بن معديكرب وأخباره","page":"ج15 ص200","text":"(وأنت لنا والله ذي العرش قدوة ... إذا صدنا عن شربها المتكلف)\n(نقول أبو ثور أحل حرامها ... وقول أبي ثور أسد وأعرف)\nقال علي بن محمد حدثني عبد الله بن محمد الثقفي عن أبيه والهذلي عن الشعبي قال جاءت زيادة من عند عمر بعد القادسية فقال عمرو بن معد يكرب لطليحة أما ترى أن هذه الزعانف تزاد ولا نزاد انطلق بنا إلى هذا الرجل حتى نكلمه فقال هيهات كلا والله لا ألقاه في هذا أبدا فلقد لقيني في بعض فجاج مكة فقال يا طليحة أقتلت عكاشة فتوعدني وعيدا ظننت أنه قاتلي ولا آمنه قال عمرو لكني ألقاه قال أنت وذاك فخرج إلى المدينة فقدم على عمر رضي الله عنه وهو يغدي الناس وقد جفن لعشرة عشرة فأقعده عمر مع عشرة فأكلوا ونهضوا ولم يقم عمرو فأقعد معه تكملة عشرة فأكلوا ونهضوا ولم يقم عمرو فأقعده مع عشرة حتى أكل مع ثلاثين ثم قام فقال يا أمير المؤمنين إنه كانت لي مآكل في الجاهلية منعني منها الإسلام وقد صررت في بطني صرتين وتركت بينهما هواء فسده قال عليك حجارة من حجارة الحرة فسده به يا عمرو إنه بلغني أنك تقول إن لي سيفا يقال له الصمصامة وعندي سيف أسميه المصمم وإني إن وضعته بين أذنيك لم أرفعه حتى يخالط أضراسك وذكر ابن الكلبي ومحمد بن كناسة أن جبيلة بن سويد بن ربيعة بن رباب لقي عمرو بن معد يكرب وهو يسوق ظعنا له فقال عمرو لأصحابه قفوا حتى آتيكم بهذه الظعن فقرب نحوه حتى إذا دنا منه قال خل سبيل الظعن قال فلم\nإذا ولدتني ثم شد على عمرو فطعنه فأذراه عن فرسه وأخذ فرسه فرجع إلى أصحابه فقالوا ما وراءك قال كأني رأيت منيتي في سنانه وبنو كنانة يذكرون أن ربيعة بن مكدم الفراسي طعن عمرو بن معد يكرب فأذراه عن فرسه وأخذ فرسه وأنه لقيه مرة أخرى فضربه فوقعت الضربة في قربوس السرج فقطعه حتى عض السيف بكاثبة الفرس فسالمه عمرو وانصرف قال المدائني حدثني مسلمة بن محارب عن داود بن أبي هند قال حمل عمرو بن معد يكرب حمالة فأتى مجاشع بن مسعود يسأله فيها وقال خالد بن خداش حدثني أبو عوانة عن حصين بن عبد الرحمن قال بلغني أن عمرا أتى مجاشع بن مسعود فقال له أسألك حملان مثلي وسلاح مثلي قال إن شئت أعطيتك ذاك من مالي ثم أعطاه حكمه وكان الأحنف أمر له بعشرين ألف درهم وفرس جواد عتيق وسيف صارم وجارية نفيسة فمر ببني حنظلة فقالوا له يا أبا ثور كيف رأيت صاحبك فقال لله بنو مجاشع ما أشد في الحرب لقاءها وأجزل في اللزبات عطاءها وأحسن في المكرمات ثناءها لقد قاتلتها فما أقللتها وسألتها فما أبخلتها وهاجيتها فما أفحمتها وقال أبو المنهال عيينة بن المنهال سمعت أبي يحدث قال جاء رجل\nوعمرو بن معد يكرب واقف بالكناسة على فرس له فقال لأنظرن ما بقي من قوة أبي ثور فأدخل يده بين ساقيه وبين السرج وفطن عمرو فضمها عليه وحرك فرسه فجعل الرجل يعدو مع الفرس لا يقدر أن ينزع يده حتى إذا بلغ منه قال يا ابن أخي ما لك قال يدي تحت ساقك فخلى عنه وقال يا ابن أخي إن في عمك لبقية وكان عمرو مع ما ذكرنا من محله مشهورا بالكذب أخبرني علي بن سليمان الأخفش قال حدثنا محمد بن يزيد النحوي المبرد ولم يتجاوزه وذكر ابن النطاح هذا الخبر بعينه عن محمد بن سلام وخبر المبرد أتم قال كانت الأشراف بالكوفة يخرجون إلى ظاهرها يتناشدون الأشعار ويتحدثون ويتذاكرون أيام الناس فوقف عمرو إلى جانب خالد بن الصقعب النهدي فأقبل عليه يحدثه ويقول أغرت على بني نهد فخرجوا إلي مسترعفين بخالد بن الصقعب يقدمهم فطعنته طعنة فوقع وضربته بالصمصامة حتى فاضت نفسه فقال له الرجل يا أبا ثور إن مقتولك الذي تحدثه فقال اللهم غفرا إنما أنت محدث فاسمع إنما نتحدث بمثل هذا وأشباهه لنرهب هذه المعدية قال محمد بن سلام وقال يونس أبت العرب إلا أن عمرا كان يكذب قال وقلت لخلف الأحمر وكان مولى الأشعريين وكان يتعصب لليمانية أكان عمرو يكذب قال كان يكذب باللسان ويصدق بالفعال","topic":"ذكر عمرو بن معديكرب وأخباره","topicNo":186,"sp":4,"spl":"ذكر عمرو بن معديكرب وأخباره"},
{"id":"b186-6","bab":"الجزء 15","sec":"ذكر عمرو بن معديكرب وأخباره","page":"ج15 ص200","text":"أخبرني إبراهيم بن أيوب عن ابن قتيبة أن سعدا كتب إلى عمر رضي الله عنه يثني على عمرو بن معد يكرب فسأله عمر عن سعد فقال هو لنا كالأب أعرابي في نمرته أسد في تامورته يقسم بالسوية ويعدل في القضية وينفر في السرية وينقل إلينا حقنا كما تنقل الذرة فقال عمر رضوان الله عليه لشد ما تقارضتما الثناء أخبرني الحسن بن علي قال حدثنا الحارث عن ابن سعد عن الواقدي عن بكير بن مسمار عن زياد مولى سعد قال سمعت سعدا يقول وبلغه أن عمرو بن معد يكرب وقع في الخمر وأنه قد دله فقال لقد كان له موطن صالح يوم القادسية عظيم الغناء شديد النكاية للعدو فقيل له فقيس بن مكشوح فقال هذا أبذل لنفسه من قيس وإن قيسا لشجاع أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة وأخبرني إبراهيم بن أيوب عن ابن قتيبة ونسخت هذا الخبر من رواية ابن الكلبي خاصة حدثني أسعر بن عمرو بن جرير عن خالد بن قطن قال حدثني من شهد موت عمرو بن معد يكرب والرواية قريبة وحكايتا عمر بن شبة وابن قتيبة عن أنفسهما ولم يتجاوزاها قالا كانت مغازي العرب إذ ذاك الري ودستبى فخرج عمرو مع شباب من مذحج حتى نزل الخان الذي دون روذة فتغدى القوم ثم ناموا وقام كل رجل منهم لقضاء حاجته وكان عمرو إذا أراد الحاجة لم يجترئ أحد أن\nيدعوه وإن أبطأ فقام الناس للرحيل وترحلوا إلا من كان في الخان الذي فيه عمرو فلما أبطأ صحنا به يا أبا ثور فلم يجبنا وسمعنا علزا شديدا ومراسا في الموضع الذي دخله وقصدناه فإذا به حمرة عيناه مائلا شدقه مفلوجا فحملناه على فرس وأمرنا غلاما شديد الذراع فارتدفه ليعدل ميله فمات بروذة ودفن على قارعة الطريق فقالت امرأته الجعفية ترثيه - طويل -\n(لقد غادر الركب الذين تحملوا ... بروذة شخصا لا ضعيفا ولا غمرا)\n(فقل لزبيد بل لمذحج كلها ... فقدتم أبا ثور سنانكم عمرا)\n(فإن تجزعوا لا يغن ذلك عنكم ... ولكن سلوا الرحمن يعقبكم صبرا)\nالأبيات العينية التي فيها الغناء وبها افتتح ذكر عمرو يقولها في أخته ريحانة بنت معد يكرب لما سباها الصمة بن بكر وكان أغار على بني زبيد في قيس فاستاق أموالهم وسبى ريحانة وانهزمت زبيد بين يديه وتبعه عمرو وأخوه عبد الله ابنا معد يكرب ثم رجع عبد الله واتبعه عمرو فأخبرنا أبو خليفة عن محمد بن سلام أن عمرا اتبعه يناشده أن يخلي عنها فلم يفعل فلما يئس منها ولى وهي تناديه بأعلى صوتها يا عمرو فلم يقدر على انتزاعها وقال - وافر -\n(أمن ريحانة الداعي السميع ... يؤرقني وأصحابي هجوع)\n(سباها الصمة الجشمي غصبا ... كأن بياض غرتها صديع)\n(وحالت دونها فرسان قيس ... تكشف عن سواعدها الدروع)\n(إذا لم تستطع شيئا فدعه ... وجاوزه إلى ما تستطيع)\nوزاد الناس في هذا الشعر وغنى فيه\n(وكيف أحب من لا أستطيع ... ومن هو للذي أهوى منوع)\n(ومن قد لامني فيه صديقي ... وأهلي ثم كلا لا أطيع)\n(ومن لو أظهر البغضاء نحوي ... أتاني قابض الموت السريع)\n(فدى لهم معا عمي وخالي ... وشرخ شبابهم إن لم يطيعوا)\nقد أخبرني الحسين بن يحيى قال قال حماد قرأت على أبي وأما قصة ريحانة فإن عمرو بن معد يكرب تزوج امرأة من مراد وذهب مغيرا قبل أن يدخل بها فلما قدم أخبر أنه قد ظهر بها وضح وهو داء تحذره العرب فطلقها وتزوجها رجل آخر من بني مازن بن ربيعة وبلغ ذلك عمرا وأن الذي قيل فيها باطل فأخذ يشبب بها فقال قصيدته وهي طويلة - وافر -\n(أمن ريحانة الداعي السميع ... يؤرقني وأصحابي هجوع)\nكان عبد الله بن معد يكرب أخو عمرو رئيس بني زبيد فجلس مع بني مازن في شرب منهم فتغنى عنده حبشي عبد للمخزم أحد بني مازن في امرأة من بني زبيد فلطمه عبد الله وقال له أما كفاك أن تشرب معنا حتى تشبب بالنساء فنادى الحبشي يا آل بني مازن فقاموا إلى عبد الله فقتلوه وكان الحبشي عبدا للمخزم فرئس عمرو مكان أخيه وكان عمرو غزا هو وأبي المرادي فأصابوا غنائم فادعى أبي أنه قد كان مساندا فأبى عمرو أن يعطيه شيئا وكره أبي أن يكون بينهما شر لحداثة قتل أبيه فأمسك عنه وبلغ عمرا أنه توعده فقال عمرو في ذلك قصيدة له أولها - وافر\n\n(أعاذل شكتي بدني ورمحي ... وكل مقلص سلس القياد)\n(أعاذل إنما أفنى شبابي ... وأقرح عاتقي ثقل النجاد)\n(تمناني ليلقاني أبي ... وددت وأينما مني ودادي)","topic":"ذكر عمرو بن معديكرب وأخباره","topicNo":186,"sp":5,"spl":"ذكر عمرو بن معديكرب وأخباره","song":1},
{"id":"b186-7","bab":"الجزء 15","sec":"ذكر عمرو بن معديكرب وأخباره","page":"ج15 ص200","text":"(ولو لاقيتني ومعي سلاحي ... تكشف شحم قلبك عن سواد)\n(أريد حباءه ويريد قتلي ... عذيرك من خليلك من مراد)\nتمام هذه الأبيات\n(تمناني وسابغتي دلاص ... كأن قتيرها حدق الجراد)\n(وسيفي كان من عهد ابن صد ... تخيره الفتى من قوم عاد)\n(ورمحي العنبري تخال فيه ... سنانا مثل مقباس الزناد)\n(وعجلزة يزل اللبد عنها ... أمر سراتها حلق الجياد)\n(إذا ضربت سمعت لها أزيزا ... كوقع القطر في الأدم الجلاد)\n(إذا لوجدت خالك غير نكس ... ولا متعلما قتل الوحاد)\n(يقلب للأمور شرنبثات ... بأظفار مغارزها حداد)\nابن سريج في الأول والثاني ثاني ثقيل بالبنصر ولابن محرز في السادس والخامس ثاني ثقيل بالخنصر في مجرى الوسطى وفي الرابع والخامس والسادس لحن للهذلي من رواية يونس وهذا البيت الخامس كان علي بن أبي طالب عليه السلام إذا نظر إلى ابن ملجم تمثل به أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثنا حيان بن بشر قال حدثنا جرير عن حمزة الزيات قال كان علي عليه السلام إذا نظر إلى ابن ملجم قال - وافر -\n(أريد حباءه ويريد قتلي ... عذيرك من خليلك من مراد)\nدثني العباس بن علي بن العباس ومحمد بن خلف وكيع قالا حدثنا أحمد بن منصور الرمادي قال حدثنا عبد الرزاق قال أخبرنا معمر عن أيوب\nعن ابن سيرين عن عبيدة السلماني قال كان علي بن أبي طالب إذا أعطى الناس فرأى ابن ملجم قال\n(أريد حباءه ويريد قتلي ... عذيرك من خليلك من مراد)\nدثني محمد بن الحسن الأشناني قال حدثنا علي بن المنذر الطريفي قال حدثنا محمد بن فضيل قال حدثنا فطر بن خليفة عن أبي الطفيل عامر بن واثلة والأصبغ بن نباتة قال قال علي عليه السلام ما يحبس أشقاها والذي نفسي بيده لتخضبن هذه من هذا قال أبو الطفيل وجمع علي الناس للبيعة فجاء عبد الرحمن بن ملجم المرادي فرده مرتين أو ثلاثا ثم بايعه ثم قال ما يحبس أشقاها فوالذي نفسي بيده لتخضبن هذه من هذا ثم تمثل بهذين البيتين وافر\n(أشدد حيازيمك للموت ... فإن الموت يأتيك)\n(ولا تجزع من القتل ... إذا حل بواديك)","topic":"ذكر عمرو بن معديكرب وأخباره","topicNo":186,"sp":6,"spl":"ذكر عمرو بن معديكرب وأخباره"},
{"id":"b186-8","bab":"الجزء 15","sec":"رجع الخبر إلى سياقة خبر عمرو","page":"ج15 ص221","text":"قال وجاءت بنو مازن إلى عمرو فقالوا إن أخاك قتله رجل منا سفيه وهو سكران ونحن يدك وعضدك فنسألك الرحم وإلا أخذت الدية ما أحببت فهم عمرو بذلك وقال - بسيط -\n(إحدى يدي أصابتني ولم ترد ... )\nبلغ ذلك أختا لعمرو يقال لها كبشة وكانت ناكحا في بني الحارث بن كعب فغضبت فلما وافى الناس من الموسم قالت شعرا تعير عمرا - طويل -\n(أرسل عبد الله إذ حان يومه ... إلى قومه لا تعقلوا لهم دمي)\n(ولا تأخذوا منهم إفالا وأبكرا ... وأترك في بيت بصعدة مظلم)\n(ودع عنك عمرا مسالم ... وهل بطن عمرو غير شبر لمطعم)\n(فإن أنتم لم تقبلوا واتديتم ... فمشوا بآذان النعام المصلم)\n(أيقتل عبد الله سيد قومه ... بنو مازن أن سب راعي المخزم)\nقال عمرو قصيدة له عند ذلك يقول فيها - متقارب -\n(أرقت وأمسيت لا أرقد ... وساورني الموجع الأسود)\n(وبت لذكرى بني مازن ... كأني مرتفق أرمد)\nيه لحن من خفيف الثقيل الأول بالوسطى نسبه يحيى المكي إلى ابن محرز وذكر الهشامي أنه منحول ثم أكب على بني مازن وهم غارون فقتلهم وقال في ذلك شعرا - وافر -\n(خذوا حققا مخطمة صفايا ... وكيدي يا مخزم أن أكيدا)\n(قتلتم سادتي وتركتموني ... على أكتافكم عبئا جديدا)\n(فمن يأبى من الأقوام نصرا ... ويتركنا فإنا لن نريدا)\nأرادت بنو مازن أن ترد عليهم الدية لما آذنهم بحرب فأبى عمرو وكانت بنو مازن من أعداء مذحج وكان عبد الله أخا كبشة لأبيها وأمها دون عمرو وكان\nعمرو قد هم بالكف عنهم حين قتل من قتل منهم فركبت كبشة في نساء من قومها وتركت عمرا أخاها وعيرته فأحمته فأكب عليهم أيضا بالقتل فلما أكثر فيهم القتل تفرقوا فلحقت بنو مازن بصاحبهم بتميم ولحقت ناشرة ببني أسد وهم رهط الصقعب بن الصحصح ولحقت فالج بسليم بن منصور وفالج وناشرة ابنا أنمار بن مازن بن ربيعة بن منبه بن صعب بن سعد العشيرة وأمهما هند بنت عدس ابن زيد بن عبد الله بن دارم فقال كابية بن حرقوص بن مازن - كامل -\n(يا ليلتي ما ليلتي بالبلدة ... ردت علي نجومها فارتدت)\n(من كان أسرع في تفرق فالج ... فلبونه جربت معا وأغدت)\n(هلا كناشرة الذي ضيعتم ... كالغصن في غلوائه المتنبت)\nقال عمرو في ذلك - وافر -\n(تمنت مازن جهلا خلاطي ... فذاقت مازن طعم الخلاط)\n(أطلت فراطكم عاما فعاما ... ودين المذحجي إلى فراط)\n(أطلت فراطكم حتى إذا ما ... قتلت سراتكم كانت قطاط)\n(غدرتم غدرة وغدرت أخرى ... فما إن بيننا أبدا يعاط)\nخبرني الحسين بن يحيى قال قال حماد قرأت على أبي قال المدائني حدثني رجل من قريش قال كنا عند فلان القرشي فجاءه رجل بجارية فغنته - سريع\n(بالله يا ظبي بني الحارث ... هل من وفى بالعهد كالناكث)\nغنته أيضا بغناء ابن سريج - منسرح -\n(يا طول ليلي وبت لم أنم ... وسادي الهم مبطن سقمي)\nأعجبته واستام مولاها فاشتط عليه فأبى شراءها وأعجبت الجارية بالفتى فلما امتنع مولاها من البيع إلا بشطط قال القرشي فلا حاجة لنا في جاريتك فلما قامت الجارية للانصراف رفعت صوتها تغني وتقول - وافر -\n(إذا لم تستطع شيئا فدعه ... وجاوزه إلى ما تستطيع)\nال فقال الفتى القرشي أفأنا لا أستطيع شراءك والله لأشترينك بما بلغت قالت الجارية فذاك أردت قال القرشي إذا لأجبتك وابتاعها من ساعته والله أعلم","topic":"ذكر عمرو بن معديكرب وأخباره","topicNo":186,"sp":7,"spl":"رجع الخبر إلى سياقة خبر عمرو","song":1,"partial":1},
{"id":"b186-9","bab":"الجزء 15","sec":"نسبة ما في هذا الخبر من الغناء","page":"ج15 ص224","text":"صوت سريع\n(بالله يا ظبي بني الحارث ... هل من وفى بالعهد كالناكث)\n(لا تخدعني بالمنى باطلا ... وأنت بي تلعب كالعابث)\nروضه من السريع الشعر لعمر بن أبي ربيعة والغناء لابن سريج رمل بالبنصر وفيه لسياط خفيف ثقيل أول بالوسطى وفيه لإبراهيم الموصلي لحن من رواية بذل ومنها - منسرح -\n(يا طول ليلي وبت لم أنم ... وسادي الهم مبطن سقمي)\n(إذ قمت ليلا على البلاط فأبصرت ... ربيبا فليت لم أقم)\n(فقلت عوجي تخبري خبرا ... وأنت منه كصاحب الحلم)\n(قالت بل اخشى العيون إذ حضرت ... حولي وقلبي مباشر الألم)\nعروضه من المنسرح والشعر والغناء لابن سريج رمل بالسبابة في مجرى الوسطى عن إسحاق وذكر محمد بن الفضل الهاشمي قال حدثنا أبي قال كان المأمون قد أطلق لأصحابه الكلام والمناظرة في مجلسه فناظر بين يديه محمد بن العباس الصولي علي بن الهيثم جونقا في الإمامة فتقلدها أحدهما ودفعها الآخر فلجت المناظرة بينهما إلى أن نبط محمد عليا فقال له علي إنما تكلمت بلسان غيرك ولو كنت في غير هذا المجلس لسمعت أكثر مما قلت فغضب المأمون وأنكر على محمد ما قاله وما كان منه من سوء الأدب بحضرته ونهض عن فرشه ونهض الجلساء فخرجوا وأراد محمد الانصراف فمنعه علي بن صالح صاحب المصلى وهو إذ ذاك يحجب المأمون وقال أفعلت ما فعلت بحضرة أمير المؤمنين ونهض على الحال التي رأيت ثم تنصرف بغير إذن اجلس حتى نعرف رأيه فيك وأمر بأن يجلس قال ومكث المأمون ساعة فجلس على سريره وأمر بالجلساء فردوا إليه فدخل إليه علي بن صالح فعرفه ما كان من قول علي بن محمد في الانصراف وما كان من منعه إياه فقال دعه ينصرف إلى لعنة الله فانصرف وقال المأمون لجلسائه أتدرون لم دخلت إلى النساء في هذا الوقت قالوا لا قال إنه لما كان من أمر هذا الجاهل ما كان لم آمن فلتات الغضب وله بنا حرمة فدخلت إلى النساء فعابثتهن حتى سكن غضبي\nقال وما مضى محمد عن وجهه إلا إلى طاهر فسأله الركوب إلى المأمون وأن يستوهبه جرمه فقال طاهر ليس هذا من أوقاتي وقد كتب إلي خليفتي في الدار أنه دعا بالجلساء فقال أكره أن أبيت ليلة وأمير المؤمنين علي ساخط فلم يزل به حتى ركب طاهر معه فأذن له فدخل ومجير الخادم واقف على رأس المأمون فلما بصر المأمون بطاهر أخذ منديلا فمسح به عينيه مرتين أو ثلاثا إلى أن وصل إليه وحرك شفتيه بشيء أنكره طاهر ثم دنا فسلم فرد السلام وأمره بالجلوس فجلس في موضعه فسأله عن مجيئه في غير وقته فعرفه الخبر واستوهبه ذنب محمد فوهبه له وانصرف وعرف محمدا ذلك ثم دعا بهارون ابن خنعويه وكان شيخا خراسانيا داهية ثقة عنده فذكر له فعل المأمون وقال له الق كاتب مجير والطف له واضمن له عشرة آلاف درهم على تعريفك ما قاله المأمون ففعل ذلك ولطف له فعرفه أنه لما رأى طاهرا دمعت عيناه وترحم على محمد الأمين ومسح دمعه بالمنديل فلما عرف ذلك طاهر ركب من وقته إلى أحمد بن أبي خالد الأحول وكان طاهر لا يركب إلى أحد من أصحاب المأمون وكلهم يركب إليه فقال له جئتك لتوليني خراسان وتحتال لي فيها وكان أحمد يتولى فض الخرائط بين يدي المأمون وغسان بن عباد يتولى إذ ذاك خراسان فقال له أحمد هلا أقمت بمنزلك وبعثت إلي حتى أصير إليك ولا يشهر الخبر فيما تريده بما ليس من عادتك لأن المأمون يعلم أنك لا تركب إلى أحد من أصحابه وسيبلغه هذا فينكره فانصرف واغض عن هذا الأمر وأمهلني مدة حتى أحتال لك ولبث مدة وزور ابن أبي خالد كتابا عن غسان بن عباد إلى المأمون يذكر فيه أنه عليل وأنه لا يأمن على نفسه ويسأل أن يستخلف غيره على خراسان وجعله في خريطة وفضها بين يدي المأمون في خرائط وردت عليه فلما قرأ على المأمون الكتاب اغتم به وقال له ما ترى فقال لعل هذه علة عارضة تزول وسيرد بعد هذا غيره فيرى حينئذ أمير المؤمنين رأيه ثم أمسك أياما وكتب كتابا آخر","topic":"ذكر عمرو بن معديكرب وأخباره","topicNo":186,"sp":8,"spl":"نسبة ما في هذا الخبر من الغناء","song":1},
{"id":"b186-10","bab":"الجزء 15","sec":"نسبة ما في هذا الخبر من الغناء","page":"ج15 ص224","text":"ودسه في الخرائط يذكر فيه أنه تناهى في العلة إلى ما لا يرجو معه نفسه فلما قرأه المأمون قلق وقال يا أحمد إنه لا مدفع لأمر خراسان فما ترى فقال هذا رأي إن أشرت فيه بما أرى فلم أصب لم أستقبله وأمير المؤمنين أعلم بخدمه ومن يصلح بخراسان منهم قال فجعل المأمون يسمي رجالا ويطعن أحمد على واحد واحد منهم إلى أن قال فما ترى في الأعور قال إن كان عند أحد قيام بهذا الأمر ونهوض فيه فعنده فدعا به المأمون فعقد له على خراسان وأمره أن يعسكر فعسكر بباب خراسان ثم تعقب الرأي فعلم أنه قد أخطأ فتوقف عن امضائه وخشي أن يوحش طاهرا بنقضه فمضى شهر تام وطاهر مقيم بمعسكره ثم إن المأمون في السحر من ليلة أحد وثلاثين يوما من عقده له عقد اللواء لطاهر ظاهرا وأمر بإحضار مخارق المغني فأحضر وقد صلى المأمون الغداة مع طلوع الفجر فقال يا مخارق أتغني - وافر -\n(إذا لم تستطع شيئا فدعه ... وجاوزه إلى ما تستطيع)\n(وكيف تريد أن تدعى حكيما ... وأنت لكل ما تهوى تبوع)\nال نعم قال هاته فغناه فقال ما صنعت شيئا فهل تعرف من يقوله أحسن مما تقوله قال نعم علويه الأعسر فأمر بإحضاره فكأنه كان وراء الستر فأمره أن يغنيه فغناه واحتفل فقال ما صنعت شيئا أتعرف من يقوله أحسن مما تقوله قال نعم عمرو بن بانة شيخنا فأمر بإحضاره فدخل في مقدار دخول علويه فأمر بأن يغنيه الصوت فغناه فأحسن فقال أحسنت ما شئت هكذا ينبغي أن يقال ثم قال يا غلام اسقني رطلا واسق صاحبيه رطلا رطلا ثم دعا له بعشرة آلاف درهم وخلعة ثلاثة أثواب ثم أمره بإعادته فأعاده فرد القول الذي قاله وأمر له بمثل ما أمر حتى فعل ذلك عشرا وحصل لعمرو مائة ألف درهم وثلاثون ثوبا ودخل المؤذنون فأذنوه بالظهر فعقد إصبعه الوسطى بإبهامه وقال برق يمان برق يمان وكذلك كان يفعل إذا أراد أن ينصرف من بحضرته من الجلساء فقال عمرو يا أمير المؤمنين قد أنعمت علي وأحسنت إلي فإن رأيت أن تأذن لي في\nمقاسمة أخوي ما وصل إلي فقد حضراه فقال ما أحسن ما استمحت لهما بل نعطيهما نحن ولا نلحقهما بك وأمر لكل واحد بمثل نصف جائزة عمرو وبكر إلى طاهر فرحله فلما ثنى عنان دابته منصرفا دنا منه حميد الطوسي فقال اطرح على ذنبه ترابا فقال اخسأ يا كلب ونفذ طاهر لوجهه وقدم غسان بن عباد فسأله عن علته وسببها فحلف له أنه لم يكن عليلا ولا كتب بشيء في هذا فعلم المأمون أن طاهرا احتال عليه بابن أبي خالد وأمسك على ذلك فلما كان بعد مدة من مقدم طاهر إلى خراسان قطع الدعاء للمأمون على المنبر يوم الجمعة فقال له عون بن مجاشع بن مسعدة صاحب البريد لم تدع في هذه الجمعة لأمير المؤمنين فقال سهو وقع فلا تكتب به وفعل مثل ذلك في الجمعة الثانية وقال لعون لا تكتب به وفعله في الجمعة الثالثة فقال له عون إن كتب التجار لا تنقطع من بغداد وإن اتصل هذا الخبر بأمير المؤمنين من غيرنا لم آمن أن يكون سبب زوال نعمتي فقال اكتب بما أحببت فكتب إلى المأمون بالخبر فلما وصل كتابه دعا بأحمد بن أبي خالد وقال إنه لم يذهب علي احتيالك في أمر طاهر وتمويهك له وأنا أعطي الله عهدا لئن لم تشخص حتى توافيني به كما أخرجته من قبضتي وتصلح ما أفسدته علي من أمر ملكي لأبيدن غضراءك فشخص أحمد وجعل يتلوم في الطريق ويقول لأصحاب البرد اكتبوا بخبر علة أجدها فلما وصل الري لقيته الأخبار ووافاه رسل طلحة بن طاهر بوفاة طاهر فأغذ السير حتى قدم خراسان فلقيه طلحة على حد غفلة فقال له أحمد لا تكلمني ولا ترني وجهك فإن أباك عرضني للعطب وزوال النعمة مع احتيالي له وسعيي كان في محبته فقال له أبي قد مضى لسبيله ولو أدركته لما خرج عن\nطاعتك وأما أنا فأحلف لك بكل ما تسكن به نفسك وأبذل كل ما عندي من مال وغيره فاضمن له عني حسن الطاعة وضبط الناحية والإخلاص في النصيحة فكتب أحمد بخبره وخبر طاهر وخبر طلحة إلى المأمون وأشار بتقليده فأنفذ المأمون إليه اللواء والخلع والعهد وانصرف أحمد إلى مدينة السلام أخبرني وكيع قال حدثني هارون بن محمد بن عبد الملك الزيات قال حدثني حماد بن إسحاق عن أبيه قال مدح ابن هرمة رجلا من قريش فلم يثبه فقال له ابن عم له لا تفعل فإنه شاعر مفوه فلم يقبل منه فقال فيه ابن هرمة - وافر -\n(فهلا إذ عجزت عن المعالي ... وعما يفعل الرجل القريع)","topic":"ذكر عمرو بن معديكرب وأخباره","topicNo":186,"sp":9,"spl":"نسبة ما في هذا الخبر من الغناء"},
{"id":"b186-11","bab":"الجزء 15","sec":"نسبة ما في هذا الخبر من الغناء","page":"ج15 ص224","text":"(أخذت برأي عمرو حين ذكى ... وشب لناره الشرف الرفيع)\n(إذا لم تستطع شيئا فدعه ... وجاوزه إلى ما تستطيع)\nمما قاله عمرو بن معد يكرب في ريحانة أخته وغني فيه قوله - بسيط -\n(هاج لك الشوق من ريحانة الطربا ... إذ فارقتك وأمست دارها غربا)\n(ما زلت أحبس يوم البين راحلتي ... حتى استمروا وأذرت دمعها سربا)\n(حتى ترفع بالحزان يركضها ... مثل المهاة مرته الريح فاضطربا)\n(والغانيات يقتلن الرجال إذا ... ضرجن بالزعفران الريط والنقبا)\n(من كل آنسة لم يغذها عدم ... ولا تشد لشيء صوتها صخبا)\n(إن الغواني قد أهلكنني وأرى ... حبالهن ضعيفات القوى كذبا)\nنى في هذا الشعر ابن سريج خفيف ثقيل من رواية حماد وفيه رمل نسبه حبش إليه أيضا وقال الأصمعي هذا الشعر لسهل بن الحنظلية الغنوي ثم الضبيني ثم الجابري وهو جابر بن ضبينة قال أبو الفرج الأصبهاني وسهل بن الحنظلية أحد أصحاب رسول الله وقد روى عنه حديثا كثيرا فذكر الأصمعي أن السبب في قوله هذا الشعر أنه اجتمع ناس من العرب بعكاظ منهم قرة بن هبيرة القشيري في سنين تتابعت على الناس فتواعدوا وتواقفوا أن لا يتغاوروا حتى يخصب الناس ثم قالوا ابعثوا إلى المنتشر بن وهب الباهلي ثم الوائلي فليشهد أمرنا ولندخله معنا فأتاهم فأعلموه ما صنعوه قال فما يأكل قومي إلى ذاك فقال له ابن جارم الضبي إنك لهناك يا أخا باهلة قال أما أنا فالغسل والنساء علي حرام حتى آكل من قمع إبلك فتفرقوا ولم يكن إلا ذلك وقال ابن جارم للمنتشر عند قوله استك أضيق من ذاك فأغار\nالمنتشر على ابن جارم فلما رآه ابن جارم رمى بنفسه في وجار ضبع وأطرد المنتشر إبله ورعاءها فقال سهل في ذلك\n(هاج لك الشوق من ريحانة الطربا ... )\nي قصيدة طويلة له حسنة وقال في ذلك أعشى باهلة - طويل -\n(فدى لك نفسي إذ تركت ابن جارم ... أجب السنام بعد ما كان مصعبا)\nقال المخبل في ذلك - طويل -\n(إن قشيرا من لقاح ابن جارم ... كغاسلة حيضا وليست بطاهر)\n(وأنبأتماني أن قرة آمن ... فناك أباه من مجير وخافر)\n(فلا توكلوها الباهلي وتقعدوا ... لدى غرض أرميكم بالنواقر)\n(إذا هي حلت بالذهاب وذي حسا ... وراحت خفاف الوطء حوس الخواطر)\nأخبرنا أحمد بن عمار قال أخبرني يعقوب بن إسرائيل قال حدثني قعنب\nابن المحرز قال أخبرنا الهيثم بن عدي عن ابن عياش عن محمد بن المنتشر قال أخبرني من شهد الأشعث بن قيس وعمرو بن معد يكرب وقد تنازعا في شيء فقال عمرو للأشعث نحن قتلنا أباك ونكنا أمك فقال سعد قوما أف لكما فقال الأشعث لعمرو والله لأضرطنك فقال كلا إنها عزوز موثقة قال جرير بن عبد الله البجلي فأخذت بيد الأشعث فنترته فوقع على وجهه ثم أخذت بيد عمرو فجذبته فما تحلحل والله ولكأنما حركت أسطوانة القصر وقال أبو عبيدة قدم عمرو بن معد يكرب والأجلح بن وقاص الفهمي على عمر بن الخطاب رضي الله عنه فأتياه وبين يديه مال يوزن فقال متى قدمتما قالا يوم الخميس قال فما حبسكما قالا شغلنا بالمنزل يوم قدمنا ثم كانت الجمعة ثم غدونا عليك اليوم فلما فرغ من وزن المال نحاه ثم أقبل عليهما فقال هيه فقال عمرو يا أمير المؤمنين هذا الأجلح بن وقاص شديد المرة بعيد الفرة وشيك الكرة والله ما رأيت مثله من الرجال صارعا ومصروعا والله لكأنه لا يموت فقال عمر للأجلح بن وقاص وأقبل عليه هيه قال وأنا أعرف الغضب في وجهه فقلت يا أمير المؤمنين الناس صالحون كثير نسلهم دارة أرزاقهم خصب نباتهم أجرياء على عدوهم جبان عدوهم عنهم صالحون بصلاح إمامهم والله ما رأينا مثلك إلا من تقدمك فنستمتع الله بك فقال ما منعك أن تقول في صاحبك مثل الذي قال فيك قال منعني ما رأيت في وجهك قال قد أصبت أما لو قلت له مثل الذي لك لأوجعتكما عقوبة فإن تركتك لنفسك فسوف أتركه لك والله لوددت لو سلمت لكم حالكم هذه أبدا أما إنه سيأتي عليك يوم تعضه وينهشك وتهره وينبحك ولست له يومئذ وليس لك فإن لم يكن بعهدكم فما أقربه منكم","topic":"ذكر عمرو بن معديكرب وأخباره","topicNo":186,"sp":10,"spl":"نسبة ما في هذا الخبر من الغناء","partial":1},
{"id":"b186-12","bab":"الجزء 15","sec":"نسبة ما في هذا الخبر من الغناء","page":"ج15 ص224","text":"قال أبو عبيدة حدثنا يونس وأبو الخطاب قالا لما كان يوم القادسية أصاب المسلمون أسلحة وتيجانا ومناطق ورقابا فبلغت مالا عظيما فعزل سعد الخمس ثم فض البقية فأصاب الفارس ستة آلاف والراجل ألفان فبقي مال دثر فكتب إلى عمر رضي الله عنه بما فعل فكتب إليه أن رد على المسلمين الخمس وأعط من لحق بك ممن لم يشهد الوقعة ففعل فأجراهم مجرى من شهد وكتب إليه عمر بذلك فكتب إليه أن فض ما بقي على حملة القرآن فأتاه عمرو بن معد يكرب فقال ما معك من كتاب الله تعالى فقال إني أسلمت باليمن ثم غزوت فشغلت عن حفظ القرآن قال ما لك في هذا المال نصيب قال وأتاه بشر بن ربيعة الخثعمي صاحب جبانة بشر فقال ما معك من كتاب الله قال بسم الله الرحمن الرحيم فضحك القوم منه ولم يعطه شيئا فقال عمرو في ذلك - بسيط -\n(إذا قتلنا ولا يبكي لنا أحد ... قالت قريش إلا تلك المقادير)\n(نعطى السوية من طعن له نفذ ... ولا سوية إذ تعطى الدنانير)\nقال بشر بن ربيعة - طويل -\n(أنخت بباب القادسية ناقتي ... وسعد بن وقاص علي أمير)\n(وسعد أمير شره دون خيره ... وخير أمير بالعراق جرير)\n(وعند أمير المؤمنين نوافل ... وعند المثنى فضة وحرير)\n(تذكر هداك الله وقع سيوفنا ... بباب قديس والمكر عسير)\n(عشية ود القوم لو أن بعضهم ... يعار جناحي طائر فيطير)\n(إذا ما فرغنا من قراع كتيبة ... دلفنا لأخرى كالجبال تسير)\n(ترى القوم فيها واجمين كأنهم ... جمال بأحمال لهن زفير)\nكتب سعد إلى عمر رضي الله تعالى عنه بما قال لهما وما ردا عليه وبالقصيدتين فكتب أن أعطهما على بلائهما فأعطى كل واحد منهما ألفي درهم قال وحدثني أبو حفص السلمي قال كتب عمر إلى سلمان بن ربيعة الباهلي إن في جندك عمرو بن معد يكرب وطلحة بن خويلد الأسدي فإذا حضر الناس فأدنهما وشاورهما وابعثهما في الطلائع وإذا وضعت الحرب أوزارها فضعهما حيث وضعا أنفسهما يعني بذلك ارتدادهما وكان عمرو ارتد وطليحة تنبأ قال وحدثنا أبو حفص السلمي قال عرض سلمان بن ربيعة جنده بأرمينية فجعل لا يقبل إلا عتيقا فمر به عمرو بن معد يكرب بفرس غليظ فقال سلمان هذا هجين فقال عمرو والهجين يعرف الهجين فبلغ عمر رضي الله تعالى عنه قوله فكتب إليه أما بعد فإنك القائل لأميرك ما قلت وإنه بلغني أن عندك سيفا تسميه الصمصامة وعندي سيف أسميه مصمما وأقسم لئن وضعته بين أذنيك لا أقلع حتى يبلغ قحفك وكتب إلى سلمان يلومه في حلمه عنه\nقال وزعموا أن عمرا شهد فتح اليرموك وفتح القادسية وفتح نهاوند مع النعمان بن مقرن المزني وكتب عمر إلى النعمان إن في جندك رجلين عمرو بن معد يكرب وطليحة بن خويلد الأسدي من بني قعين فأحضرهما الحرب وشاورهما في الأمر ولا تولهما عملا والسلام صوت - طويل -\n(خليلي هبا طالما قد رقدتما ... أجدكما لا تقضيان كراكما)\n(سأبكيكما طول الحياة وما الذي ... يرد على ذي لوعة إن بكاكما)\nيروى ذي عولة الشعر لقس بن ساعدة الإيادي فيما أخبرنا به محمد بن العباس اليزيدي في خبر أنا ذاكره هاهنا وذكر يعقوب بن السكيت أنه لعيسى بن قدامة الأسدي وذكر العتبي أنه لرجل من بني عامر بن صعصعة يقال له الحسن بن الحارث والغناء لهاشم بن سليمان ثقيل أول بالوسطى عن عمرو","topic":"ذكر عمرو بن معديكرب وأخباره","topicNo":186,"sp":11,"spl":"نسبة ما في هذا الخبر من الغناء"},
{"id":"b187-1","bab":"الجزء 15","sec":"ذكر خبر قس بن ساعدة ونسبه وقصته في هذا الشعر","page":"ج15 ص236","text":"هو قس بن ساعدة بن عمرو وقيل مكان عمرو شمر بن عدي بن مالك بن أيدعان بن النمر بن واثلة بن الطمثان بن زيد مناة بن يقدم بن أفصى بن دعمي بن إياد خطيب العرب وشاعرها وحليمها وحكيمها في عصره يقال إنه أول من علا على شرف وخطب عليه وأول من قال في كلامه أما بعد وأول من اتكأ عند خطبته على سيف أو عصا وأدركه رسول الله قبل النبوة ورآه بعكاظ فكان يأثر عنه كلاما سمعه منه وسئل عنه فقال يحشر أمة وحده وقد سمعت خبره من جهات عدة إلا أنه لم يحضرني وقت كتبت هذا الخبر غيره وهو إن لم يكن من أقواها على مذهب أهل الحديث إسنادا فهو من أتمها\nأخبرني محمد بن العباس اليزيدي قال حدثنا أبو شعيب صالح بن عمران قال حدثني عمر بن عبد الرحمن بن حفص النسائي قال حدثني عبد الله بن محمد قال حدثني الحسن بن عبد الله قال حدثني محمد بن السائب عن أبي صالح عن ابن عباس قال لما قدم وفد إياد على النبي قال ما فعل قس بن ساعدة قالوا مات يا رسول الله قال كأني أنظر إليه بسوق عكاظ على جمل له أورق وهو يتكلم بكلام عليه حلاوة ما أجدني أحفظه فقال رجل من القوم أنا أحفظه يا رسول الله قال كيف سمعته يقول قال سمعته يقول أيها الناس اسمعوا وعوا من عاش مات ومن مات فات وكل ما هو آت آت ليل داج وسماء ذات أبراج بحار تزخر ونجوم تزهر وضوء وظلام وبر وآثام ومطعم ومشرب وملبس ومركب ما لي أرى الناس يذهبون ولا يرجعون أرضوا بالمقام فأقاموا أم تركوا فناموا وإله قس بن ساعدة ما على وجه الأرض دين أفضل من دين قد أظلكم زمانه وأدرككم أوانه فطوبى لمن أدركه فاتبعه وويل لمن خالفه ثم أنشأ يقول - مجزوء الكامل -\n(في الذاهبين الأولين ... من القرون لنا بصائر)\n(لما رأيت مواردا ... للموت ليس لها مصادر)\n(ورأيت قومي نحوها ... يمضي الأصاغر والأكابر)\n(أيقنت أني لا محالة ... حيث صار القوم صائر)\nفقال النبي ( يرحم الله قسا إني لأرجو أن يبعث يوم القيامة أمة وحده\nقال رجل يا رسول الله لقد رأيت من قس عجبا قال وما رأيت قال بينا أنا بجبل يقال له سمعان في يوم شديد الحر إذ أنا بقس بن ساعدة تحت ظل شجرة عند عين ماء وعنده سباع كلما زأر سبع منها على صاحبه ضربه بيده وقال كف حتى يشرب الذي ورد قبلك قال ففرقت فقال لا تخف وإذا أنا بقبرين بينهما مسجد فقلت له ما هذان القبران قال هذان قبرا أخوين كانا لي فماتا فاتخذت بينهما مسجدا أعبد الله جل وعز فيه حتى ألحق بهما ثم ذكر أيامهما فبكى ثم أنشأ يقول - طويل -\n(خليلي هبا طالما قد رقدتما ... أجدكما لا تقضيان كراكما)\n(ألم تعلما أني بسمعان مفرد ... وما لي فيه من حبيب سواكما)\n(أقيم على قبريكما لست بارحا ... طوال الليالي أو يجيب صداكما)\n(كأنكما والموت أقرب غاية ... بجسمي في قبريكما قد أتاكما)\n(فلو جعلت نفس لنفس وقاية ... لجدت بنفسي أن تكون فداكما)\nقال النبي ( يرحم الله قسا\nوأما الحكاية عن يعقوب بن السكيت أن الشعر لعيسى بن قدامة الأسدي فأخبرني بها علي بن سليمان الأخفش عن السكوني قال قال يعقوب بن السكيت\nقال عيسى بن قدامة الأسدي وكان قدم قاسان وكان له نديمان فماتا وكان يجيء فيجلس عند القبرين وهما براوند في موضع يقال له خزاق فيشرب ويصب على القبرين حتى يقضي وطره ثم ينصرف وينشد وهو يشرب - طويل -\n(خليلي هبا طالما قد رقدتما ... أجدكما لا تقضيان كراكما)\n(ألم تعلما ما لي براوند هذه ... ولا بخزاق من نديم سواكما)\n(مقيم على قبريكما لست بارحا ... طوال الليالي أو يجيب صداكما)\n(جرى الموت مجرى اللحم والعظم منكما ... كأن الذي يسقي العقار سقاكما)\n(تحمل من يهوي القفول وغادروا ... أخا لكما أشجاه ما قد شجاكما)\n(فأي أخ يجفو أخا بعد موته ... فلست الذي من بعد موت جفاكما)\n(أصب على قبريكما من مدامة ... فإلا تذوقا أرو منها ثراكما)\n(أناديكما كيما تجيبا وتنطقا ... وليس مجابا صوته من دعاكما)\n(أمن طول نوم لا تجيبان داعيا ... خليلي ما هذا الذي قد دهاكما)\n(قضيت بأني لا محالة هالك ... وأني سيعروني الذي قد عراكما)\n(سأبكيكما طول الحياة وما الذي ... يرد على ذي عولة إن بكاكما)","topic":"ذكر خبر قس بن ساعدة ونسبه وقصته في هذا الشعر","topicNo":187,"sp":0,"spl":"ذكر خبر قس بن ساعدة ونسبه وقصته في هذا الشعر"},
{"id":"b187-2","bab":"الجزء 15","sec":"ذكر خبر قس بن ساعدة ونسبه وقصته في هذا الشعر","page":"ج15 ص236","text":"وأخبرني ابن عمار أبو العباس أحمد بن عبيد الله بخبر هؤلاء عن أحمد بن يحيى البلاذري قال حدثنا عبد الله بن صالح بن مسلم العجلي قال بلغني أن ثلاثة نفر من أهل الكوفة كانوا في الجيش الذي وجهه الحجاج إلى الديلم وكانوا يتنادمون لا يخالطون غيرهم فإنهم لعلى ذلك إذ مات أحدهم فدفنه صاحباه وكانا يشربان عند قبره فإذا بلغه الكأس هراقاها على قبره وبكيا ثم إن الثاني مات فدفنه الباقي إلى جنب صاحبه وكان يجلس عند قبريهما فيشرب ويصب الكأس على الذي يليه ثم على الآخر ويبكي وقال فيهما\n(نديمي هبا طالما قد رقدتما ... )\nوذكر بعض الأبيات التي تقدم ذكرها وقال مكان براوند هذه بقزوين وسائر الخبر نحو ما ذكرناه قال ابن عمار فقبورهم هناك تعرف بقبور الندماء ذكر العتبي عن أبيه أن الشعر للحزين بن الحارث أحد بني عامر بن صعصعة وكان أحد نديميه من بني أسد والآخر من بني حنيفة فلما مات أحدهما كان يشرب ويصب على قبره ويقول - رمل -\n(لا تصرد هامة من كأسها ... واسقه الخمر وإن كان قبر)\n(كان حرا فهوى فيمن هوى ... كل عود ذي شعوب ينكسر)\nال ثم مات الآخر فكان يشرب عند قبريهما وينشد\n(خليلي هبا طالما قد رقدتما ... )\nالأبيات قال ثم قالت له كاهنة إنك لا تموت حتى تنهشك حية في شجرة بوادي كذا\nوكذا فورد ذلك الوادي في سفر له وسأل عنه فعرفه وقد كان خط في أصل شجرة ومد رجله عليه فنهشته حية فأنشأ يقول - طويل -\n(خليلي هذا حيث رمسي فعرجا ... علي فإني نازل فمعرس)\n(لبست رداء العيش أحوى أجره العشيات ... حتى لم يكن فيه ملبس)\n(تركت خبائي حيث أرسى عماده ... علي وهذا مرمسي حيث أرمس)\n(أحتفي الذي لا بد أنك قاتلي ... هلم فما في غابر العيش منفس)\n(أبعد نديمي اللذين بعاقل ... بكيتهما حولا مدى أتوجس)","topic":"ذكر خبر قس بن ساعدة ونسبه وقصته في هذا الشعر","topicNo":187,"sp":1,"spl":"ذكر خبر قس بن ساعدة ونسبه وقصته في هذا الشعر","partialRef":{"sid":"b186-12","gi":2,"vi":0,"side":0},"partial":1},
{"id":"b187-3","bab":"الجزء 15","sec":"ذكر هاشم بن سليمان وبعض أخباره","page":"ج15 ص242","text":"هو هاشم بن سليمان مولى بني أمية ويكنى أبا العباس وكان موسى الهادي يسميه أبا الغريض وهو حسن الصنعة عزيزها وفيه يقول الشاعر - سريع -\n(يا وحشتي بعدك يا هاشم ... غبت فشجوي بك لي دائم)\n(اللهو واللذة يا هاشم ... ما لم تكن حاضره مأتم)\nأخبرني علي بن عبد العزيز قال حدثنا عبيد الله بن عبد الله بن خرداذبه قال كان موسى الهادي يميل إلى هاشم بن سليمان ويمازحه ويلقبه أبا الغريض وأخبرني الحسين بن يحيى عن حماد قال بلغني أن هاشم بن سليمان دخل يوما على موسى الهادي فغناه - مجزوء الكامل -\n(لو يرسل الأزل الظباء ... ترود ليس لهن قائد)\n(لتيممتك تدلها ... رياك للسبل الموارد)\n(وإذا الرياح تنكرت ... نكبا هواجرها صوارد)\n(فالناس سائلة إليك ... فصادرا تغني ووارد)\nلشعر لطريح بن إسماعيل الثقفي يقوله في الوليد بن يزيد بن عبد الملك والغناء لهاشم بن سليمان خفيف ثقيل أول بالبنصر فطرب موسى وكان بين يديه كانون كبير ضخم عليه فحم فقال له سلني ما شئت قال تملأ لي هذا الكانون فأمر له بذلك وفرغ الكانون فوسع ست بدور فدفعها إليه وقد أخبرني بهذا الخبر الحسن بن علي قال حدثنا ابن مهرويه قال حدثنا عبد الله بن أبي سعد عن أبي توبة عن محمد بن جبر عن هاشم بن سليمان قال أصبح موسى أمير المؤمنين يوما وعنده جماعة منا فقال يا هاشم غنني - كامل -\n(أبهار قد هيجت لي أوجاعا ... )\nإن أصبت مرادي فيه فلك حاجة مقضية فغنيته فقال قد أصبت وأحسنت سل حاجتك فقال يا أمير المؤمنين تأمر أن يملأ هذا الكانون دراهم قال وبين يديه كانون عظيم فأمر به فملئ فوسع ثلاثين ألف درهم فلما حصلتها قال يا ناقص الهمة والله لو سألتني أن أملأه دنانير لفعلت فقلت أقلني يا أمير\nالمؤمنين فقال لا سبيل إلى ذلك فلم يسعدك الجد به نسبة هذا الصوت - كامل -\n(أبهار قد هيجت لي أوجاعا ... وتركتني عبدا لكم مطواعا)\n(بحديثك الحسن الذي لو كلمت ... وحش الفلاة به لجئن سراعا)\n(وإذا مررت على البهار منضدا ... في السوق هيج لي إليك نزاعا)\n(والله لو علم البهار بأنها ... أضحت سميته لصار ذراعا)\nلغناء لهاشم ثاني ثقيل بالبنصر عن عمرو وفيه ثقيل أول بالبنصر ينسب إلى إبراهيم الموصلي وإلى يحيى المكي وإلى إسحاق أخبرني أحمد بن عبد العزيز واسماعيل بن يونس قالا حدثنا عمر بن شبة قال حدثني بعض أصحابنا قال كنا في منزل محمد بن اسماعيل بن علي بن عبد الله بن عباس وكان عالما بالغناء والفقه جميعا وقد كان يحيى بن أكثم وصفه للمأمون بالفقه ووصفه أحمد بن يوسف بالعلم بالغناء فقال المأمون ما أعجب ما اجتمع فيه العلم بالفقه والغناء فكتبت إلى إسحاق بن إبراهيم الموصلي أن يتحول إلينا وكان في جوارنا وعندنا يومئذ محمد بن أيوب بن جعفر ابن سليمان وذكاء وصغير غلاما أحمد بن يوسف الكاتب فكتب إلينا إسحاق جعلت فداءكم قد أخذت دواء فإذا خرجت منه حملت قدري وصرت إليكم وكتب في أسفل كتابه - رجز -\n(أنا شماطيط الذي حدثت به ... متى أنبه للغداء أنتبه)\n(ثم أدور حوله وأحتبه ... حتى يقال شره ولست به)\nثم جاءنا ومعه بديح غلامه فتغدينا وشربنا فغنى ذكاء غلام أحمد بن يوسف\n(أبهار قد هيجت لي أوجاعا ... )\nكامل فسأله إسحاق أن يعيده فأعاده مرارا ثم قال له ممن أخذت هذا فقال من معاذ بن الطبيب قال والصنعة فيه له فقال له إسحاق أحب أن تلقيه على بديح ففعل فلما صليت العشاء انصرف ذكاء وقعد أبو جعفر يشرب يعني مولاه وعنده قوم وتخلف صغير فغنانا فقال له إسحاق أنت والله يا غلام ماخوري وسكر محمد بن إسماعيل في آخر النهار فغنانا - متقارب -\n(دعوني أغض إذا ما بدت ... وأملك طرفي فلا أنظر)\nقال إسحاق لمحمد بن الحسن آجرك الله في ابن عمك أي قد سكر فأقدم على الغناء بحضرتي","topic":"ذكر خبر قس بن ساعدة ونسبه وقصته في هذا الشعر","topicNo":187,"sp":2,"spl":"ذكر هاشم بن سليمان وبعض أخباره","song":1,"partial":1},
{"id":"b187-4","bab":"الجزء 15","sec":"نسبة هذا الصوت","page":"ج15 ص245","text":"صوت - متقارب -\n(هبوني أغض إذا ما بدت ... وأملك طرفي فلا أنظر)\n(فكيف احتيالي إذا ما الدموع ... نطقن فبحن بما أضمر)\n(أيا من سروري به شقوة ... ومن صفو عيشي به أكدر)\n(أمني تخاف انتشار الحديث ... وحظي في ستره أوفر)\n(ولو لم أصنه لبقيا عليك ... نظرت لنفسي كما تنظر)\nالشعر للعباس بن الأحنف والغناء للزبير بن دحمان ثقيل أول بالوسطى عن عمرو في الأبيات الثلاثة الأول وفيها لعمرو بن بانة ماخوري وفي\n(أيا من سروري به شقوة ... )\nسليم هزج وفيه ثاني ثقيل ينسب إلى حسين بن محرز وإلى عباس منقار صوت - رجز -\n(هذا أوان الشد فاشتدي زيم ... قد لفها الليل بسواق حطم)\n(ليس براعي إبل ولا غنم ... ولا بجزار على ظهر وضم)\nروضه من الرجز الشعر لرشيد بن رميض العنزي يقوله في الحطم وهو شريح بن ضبيعة وأمه هند بنت حسان بن عمرو بن مرثد والغناء ليزيد حوراء - خفيف - ثقيل أول بالبنصر وفيه خفيف رمل يقال إنه لأحمد المكي قال أبو عبيدة كان شريح بن ضبيعة غزا اليمن في جموع جمعها من ربيعة فغنم وسبى بعد حرب كانت بينه وبين كندة أسر فيها فرعان بن مهدي بن معد يكرب عم الأشعث بن قيس وأخذ على طريق مفازة فضل بهم دليلهم ثم هرب منهم ومات فرعان في أيديهم عطشا وهلك منهم ناس كثير بالعطش وجعل الحطم يسوق بأصحابه سوقا عنيفا حتى نجوا ووردوا الماء فقال فيه رشيد - رجز -\n(هذا أوان الشد فاشتدي زيم ... ليس براعي إبل ولا غنم)\n(ولا بجزار على ظهر وضم ... نام الحداة وابن هند لم ينم)\n(باتت يقاسيها غلام كالزلم ... خدلج الساقين خفاف القدم)\n(قد لفها الليل بسواق حطم ... )\nلقب يومئذ الحطم لقول رشيد هذا فيه وأدرك الحطم الإسلام فأسلم ثم ارتد بعد وفاة رسول الله حدثنا محمد بن جرير الطبري قال حدثنا عبد الله بن سعد الزهري قال أخبرنا عمي يعقوب قال أخبرني سيف قال خرج العلاء بن الحضرمي نحو البحرين وكان من حديث البحرين أن رسول الله لما مات ارتدوا ففاءت عبد القيس منهم وأما بكر فتمت على ردتها وكان الذي ثنى عبد القيس الجارود بن المعلى فذكر سيف عن إسماعيل بن مسلم عن الحسن بن أبي الحسن قال قدم الجارود بن المعلى على النبي مرتادا وقال أسلم يا جارود فقال إن لي دينا قال له النبي إن دينك يا جارود ليس بشيء وليس بدين فقال له الجارود فإن أنا أسلمت فما كان من تبعة في الإسلام فعليك قال نعم فأسلم وأقام بالمدينة حتى فقه حدثنا محمد بن جرير قال حدثنا محمد بن حميد قال حدثنا سلمة بن الفضل عن أبي إسحاق قال اجتمعت ربيعة بالبحرين فقالوا ردوا الملك في آل المنذر فملكوا المنذر بن النعمان بن المنذر وكان يسمى الغرور ثم أسلم بعد ذلك وقال لست بالغرور ولكني المغرور حدثنا محمد بن جرير قال حدثنا عبد الله بن سعد قال أخبرني عمي قال أخبرنا سيف عن إسماعيل بن مسلم عن عمير بن فلان العبدي قال لما مات\nرسول الله خرج الحطم بن ضبيعة في بني قيس بن ثعلبة ومن اتبعه من بكر بن وائل على الردة ومن تأشب إليه من غير المرتدين ممن لم يزل كافرا حتى نزل القطيف وهجر واستغوى الخط و من كان بهما من الزط والسيابجة وبعث بعثا إلى دارين فأقا موا له ليجعل عبد القيس بينهم وبينه وكانوا مخالفين له يمدون المنذرو المسلمين وأرسل إلى الغرور بن سويد بن المنذر ابن أخي النعمان بن المنذر فقال له اثبت فإني إن ظفرت ملكتك البحرين حتى تكون كالنعمان بالحيرة وبعث إلى رواثا وقيل إلى جؤاثا فحاصرهم وألح عليهم فاشتد الحصار على المحصورين من المسلمين وفيهم رجل من صالحي المسلمين يقال له عبد الله بن حذف أحد بني أبي بكر بن كلاب فاشتد عليه وعليهم الجوع حتى كادوا يهلكون فقال عبد الله بن حذف - وافر -\n(ألا أبلغ أبا بكر رسولا ... وفتيان المدينة أجمعينا)\n(فهل لكم إلى قوم كرام ... قعود في جؤاثا محصرينا)\n(كأن دماءهم في كل فج ... شعاع الشمس يعشي الناظرينا)\n(توكلنا على الرحمن إنا ... وجدنا النصر للمتوكلينا)\nدثني محمد بن جرير قال كتب إلى السري بن يحيى عن شعيب بن إبراهيم عن سيف بن عمر عن الصقعب بن عطية بن بلال عن سهم بن","topic":"ذكر خبر قس بن ساعدة ونسبه وقصته في هذا الشعر","topicNo":187,"sp":3,"spl":"نسبة هذا الصوت","partial":1},
{"id":"b187-5","bab":"الجزء 15","sec":"نسبة هذا الصوت","page":"ج15 ص245","text":"منجاب عن منجاب بن راشد قال بعث أبو بكر العلاء بن الحضرمي على قتال أهل الردة بالبحرين فتلاحق به لم من لم يرتد من المسلمين وسلك بنا الدهناء حتى إذا كنا في بحبوحتها أراد الله عز و جل أن يرينا آية فنزل العلاء وأمر الناس بالنزول فنفرت الإبل في جوف الليل فما بقي بعير ولا زاد ولا مزاد ولا بناء يعني الخيم قبل أن يحطوا فما علمت جمعا هجم عليه من الغم ما هجم علينا وأوصى بعضنا إلى بعض ونادى منادي العلاء اجتمعوا فاجتمعنا إليه فقال ما هذا الذي ظهر فيكم وغلب عليكم فقال الناس وكيف نلام ونحن إن بلغنا غدا لم تحم شمسه حتى نصير حديثا فقال أيها الناس لا تراعوا ألستم مسلمين ألستم في سبيل الله ألستم أنصار الله قالوا بلى قال فأبشروا فوالله لا يخذل الله تبارك وتعالى من كان في مثل حالكم ونادى المنادي بصلاة الصبح حين طلع الفجر فصلى بنا ومنا المتيمم ومنا من لم يزل على طهوره فلما قضى صلاته جثا لركبتيه وجثا الناس معه فنصب في الدعاء ونصبوا فلمع لهم سراب فأقبل على الدعاء ثم لمع لهم آخر كذلك فقال الرائد ماء فقام وقام الناس فمشينا حتى نزلنا عليه فشربنا واغتسلنا فما تعالى النهار حتى أقبلت الإبل من كل وجه وأناخت إلينا فقام كل رجل إلى ظهره فأخذه فما فقدنا سلكا فأرويناها العلل بعد النهل وتروحنا وكان أبو هريرة رفيقي فلما غبنا عن ذلك المكان قال لي كيف علمك بموضع ذلك الماء فقلت أنا أهدى الناس بهذه البلاد قال فكر معي حتى تقيمني عليه فكررت به فأنخت على ذلك\nالمكان بعينه فإذا هو لا غدير به ولا أثر للماء فقلت له والله لولا أني لا أرى الغدير لأخبرتك أن هذا هو المكان وما رأيت بهذا المكان ماء قبل ذلك فنظر أبو هريرة فإذا إداوة مملوءة فقال يا سهم هذا والله المكان ولهذا رجعت ورجعت بك وملأت إداوتي هذه ثم وضعتها على شفير الوادي فقلت إن كان منا من المن وكانت آية عرفتها وإن كان غياثا عرفته فإذا من من المن وحمدت الله جل وعز ثم سرنا حتى نزلنا هجر فأرسل العلاء إلى الجارود ورجل آخر أن انضما في عبد القيس حتى تنزلا على الحطم مما يليكما وخرج هو فيمن معه وفيمن قدم عليه حتى ينزل مما يلي هجر وتجمع المسلمون كلهم إلى العلاء بن الحضرمي ثم خندق المسلمون والمشركون فكانوا يتراوحون القتال ويرجعون إلى خندقهم فكانوا كذلك شهرا فبينا الناس ليلة كذلك إذ سمع المسلمون في عسكر المشركين ضوضاء شديدة فكأنها ضوضاء هزيمة فقال العلاء من يأتينا بخبر القوم فقال عبد الله بن حذف أنا آتيكم بخبر القوم وكانت أمه عجلية فخرج حتى إذا دنا من خندقهم أخذوه فقالوا له من أنت فانتسب لهم وجعل ينادي يا أبجراه فجاء أبجر بن بجير فعرفه فقال ما شأنك فقال لا أضيعن الليلة بين اللهازم علام أقتل وحولي عساكر من عجل وتيم اللات وعنزة وقيس أيتلاعب بي الحطم ونزاع القبائل وأنتم شهود فتخلصه وقال والله إني لأظنك بئس ابن الأخت لأخوالك الليلة قال دعني من هذا وأطعمني فقد مت جوعا فقرب إليه طعاما فأكل ثم قال زودني واحملني وجوزني انطلق إلى طيتي ويقول ذلك لرجل قد غلب عليه الشراب ففعل وحمله على بعير","topic":"ذكر خبر قس بن ساعدة ونسبه وقصته في هذا الشعر","topicNo":187,"sp":4,"spl":"نسبة هذا الصوت"},
{"id":"b187-6","bab":"الجزء 15","sec":"نسبة هذا الصوت","page":"ج15 ص245","text":"وزوده وجوزه وخرج عبد الله حتى دخل عسكر المسلمين فأخبرهم أن القوم سكارى فخرج القوم عليهم حتى اقتحموا عسكرهم فوضعوا فيهم السيوف حيث شاؤوا واقتحموا الخندق هرابا فمترد وناج ودهش ومقتول ومأسور واستولى المسلمون على ما في العسكر ولم يفلت رجل إلا بما عليه فأما أبجر فأفلت وأما الحطم فإنه بعل ودهش وطار فؤاده فقام إلى فرسه والمسلمون خلالهم يجوسونهم ليركبه فلما وضع رجله في الركاب انقطع فمر به عفيف بن المنذر أحد بني عمرو بن تميم والحطم يستغيث ويقول ألا رجل من بني قيس ابن ثعلبة يعقلني فرفع صوته فعرفه عفيف فقال أبو ضبيعة قال نعم قال أعطني رجلك أعقلك فأعطاه رجله يعقلها فنفحها فأطنها من الفخذ وتركه فقال أجهز علي فقال إني لأحب أن لا تموت حتى أمضك وكان مع عفيف عدة من ولد أبيه فأصيبوا ليلتئذ وجعل الحطم يقول ذلك لمن لا يعرفه حتى مر به قيس بن عاصم فقال له ذلك فعرفه فمال عليه فقتله فلما رأى فخذه نادرة قال واسوأتاه لو عرفت الذي به لم أحركه وخرج المسلمون بعد ما أحرزوا الخندق على القوم يطلبونهم فاتبعوهم فلحق قيس بن عاصم أبجر وكان فرس أبجر أقوى من فرس قيس فلما خشي أن يفوته طعنه في العرقوب فقطع العصب وسلم النسا فقال عفيف بن المنذر في ذلك - طويل -\n(فإن يرقأ العرقوب لا يرقأ النسا ... وما كل من يبقى بذلك عالم)\n(ألم تر أنا قد فللنا حماتهم ... بأسرة عمرو والرباب الأكارم)\nوأسر عفيف بن المنذر الغرور ابن أخي النعمان بن المنذر فكلمته\nالرباب فيه وكان ابن أختهم وسألوه أن يجيره فجاء به إلى العلاء قال إني أجرته قال ومن هو قال الغرور قال العلاء أنت غررت هؤلاء قال أيها الملك إني لست بالغرور ولكني المغرور قال أسلم فأسلم وبقي بهجر وكان الغرور اسمه ليس بلقب وقتل العفيف أيضا المنذر بن سويد أخا الغرور لأمه وكان له يومئذ بلاء عظيم فأصبح العلاء يقسم الأنفال ونفل رجالا من أهل البلاء ثيابا فكان فيمن نفل عفيف بن المنذر وقيس بن عاصم وثمامة بن أثال فأما ثمامة فنفل ثيابا فيها خميصة ذات أعلام وكان الحطم يباهي فيها وباع الباقي وهرب الفل إلى دارين فركبوا إليها السفن فجمعهم الله عز و جل بها وندب العلاء الناس إلى دارين وخطبهم فقال إن الله عز و جل قد جمع لكم أحزاب الشيطان وشذاذ الحرب في هذا اليوم وقد أراكم من آياته في البر لتعتبروا بها في البحر فانهضوا إلى عدوكم ثم استعرضوا البحر إليهم فإن الله جل وعز قد جمعهم به فقالوا نفعل ولا نهاب والله بعد الدهناء هولا ما بقينا فارتحل وارتحلوا حتى أتى ساحل البحر فاقتحموا على الخيل هم والحمولة والإبل والبغال الراكب والراجل ودعا ودعوا وكان دعاؤه و دعاؤهم يا أرحم الراحمين يا كريم يا حليم يا صمد يا حي يا محيي الموتى يا حي يا قيوم لا إله إلا أنت يا ربنا فأجازوا ذلك الخليج بإذن الله يمشون على\nمثل رملة ميثاء فوقها ماء يغمر أخفاف الإبل وبين الساحل ودارين مسيرة يوم وليلة لسفن البحر ووصل المسلمون إليها فما تركوا من المشركين بها مخبرا وسبوا الذراري واستاقوا الأموال فبلغ من ذلك نفل الفارس من المسلمين ستة آلاف والراجل ألفين فلما فرغوا رجعوا عودهم على بدئهم وفي ذلك يقول عفيف - طويل -\n(ألم تر أن الله ذلل بحره ... وأنزل بالكفار إحدى الجلائل)\n(دعونا الذي شق البحار فجاءنا ... بأعجب من شق البحار الأوائل)","topic":"ذكر خبر قس بن ساعدة ونسبه وقصته في هذا الشعر","topicNo":187,"sp":5,"spl":"نسبة هذا الصوت"},
{"id":"b187-7","bab":"الجزء 15","sec":"نسبة هذا الصوت","page":"ج15 ص245","text":"أقفل العلاء الناس إلا من أحب المقام فاختار ثمامة بن أثال الذي نفله العلاء خميصة الحطم حين نزل على ماء لبني قيس بن ثعلبة فلما رأوه عرفوا الخميصة فبعثوا إليه رجلا فسألوه أهو الذي قتل الحطم قال لا ولوددت أني قتلته قالوا فأنى لك حلته قال نفلتها قالوا وهل ينفل إلا القاتل قال إنها لم تكن عليه إنما كانت في رحله قالوا كذبت فقتلوه وكان بهجر راهب فأسلم فقيل له ما دعاك إلى الإسلام فقال ثلاثة أشياء خشيت أن يمسخني الله بعدها إن أنا لم أفعل فيض في الرمال وتمهيد أثباج البحور ودعاء سمعته في عسكرهم في الهواء من السحر قالوا وما هو قال اللهم إنك أنت الرحمن الرحيم لا إله غيرك والبديع ليس قبلك شيء والدائم غير الغافل والحي الذي لا يموت وخالق ما يرى وما لا يرى وكل يوم أنت في شأن وعلمت اللهم كل شيء بغير تعليم فعلمت أن القوم لم يعاونوا بالملائكة إلا وهم على أمر الله جل وعز فلقد كان أصحاب رسول الله يسمعون هذا من ذلك الهجري بعد\nصوت - خفيف -\n(يا خليلي من ملام دعاني ... وألما الغداة بالأظعان)\n(لا تلوما في آل زينب إن القلب ... رهن بآل زينب عان)\nلشعر لعمر بن أبي ربيعة والغناء للغريض خفيف رمل بالبنصر وهذا الشعر يقوله في زينب بنت موسى أخت قدامة بن موسى الجمحي أخبرني حرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عبد الملك بن عبد العزيز بن عبد الله بن أبي سلمة قال حدثني قدامة بن موسى قال خرجت بأختي زينب بنت موسى إلى العمرة فلما كنت بسرف لقيني عمر بن أبي ربيعة على فرس فسلم علي فقلت إني أراك متوجها يا أبا الخطاب قال ذكرت لي امرأة من قومي برزة الجمال فأردت الحديث معها قلت أما علمت أنها أختي قال لا والله واستحيا وثنى عنق فرسه راجعا إلى مكة أخبرني حرمي قال حدثني الزبير قال حدثني عبد الرحمن بن عبد الله بن عبد العزيز الزهري قال نسب ابن أبي ربيعة بزينب بنت موسى الجمحي أخت قدامة بن موسى فقال - خفيف -\n(يا خليلي من ملام دعاني ... )\nذكر البيتين وبعدهما\n(لم تدع للنساء عندي نصيبا ... غير ما قلت مازحا بلساني)\nفقال له ابن أبي عتيق أما قلبك فمغيب عنا وأما لسانك فشاهد عليك أخبرني الحرمي قال حدثني الزبير قال قال عبد الرحمن بن عبد الله بن عبد العزيز الزهري لما نسب عمر بن أبي ربيعة بزينب قال\n(لم تدع للنساء عندي نصيبا ... غير ما قلت مازحا بلساني)\nال له ابن أبي عتيق رضيت لهما بالمودة وللنساء بالدهفشة قال والدهفشة التجميش والخديعة بالشيء اليسير أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير قال أخبرني مثل ذلك عبد الملك بن عبد العزيز عن يوسف بن الماجشون قال فبلغ ذلك أبا وداعة السهمي فأنكره فقيل لابن أبي عتيق أبو وداعة قد اعترض لعمر بن أبي ربيعة دون زينب بنت موسى الجمحي وقال لا أقر له أن يذكر في الشعر امرأة من بني هصيص فقال ابن أبي عتيق لا تلوموا أبا وداعة أن ينعظ من سمرقند على أهل عدن قال عبد الملك وفيها يقول أيضا عمر - خفيف -\n(طال عن آل زينب الإعراض ... للتعزي وما بنا الإبغاض)\n(ووليدا قد كان علقها القلب ... إلى أن علا الرؤوس البياض)\n(حبلها عندنا متين وحبلي ... عندها واهن القوى أنقاض)\nناه ابن محرز رمل بالبنصر عن حبش وفيها يقول أيضا - خفيف\n\n(أيها الكاشح المعير بالصرم ... تزحزح فما بها الهجران)\n(لا مطاع في آل زينب فارجع ... أو تكلم حتى يمل اللسان)\n(فاجعل الليل موعدا حين يمسي ... ويعفي حديثنا الكتمان)\n(كيف صبري عن بعض نفسي وهل يصبر ... عن بعض نفسه إنسان)\n(ولقد أشهد المحدث عند القصر ... فيه تعفف وبيان)\n(في زمان من المعيشة لذ ... قد مضى عصره وهذا زمان)\nروضه من الخفيف غناه ابن سريج ولحنه رمل بالوسطى من نسخة عمرو بن بانة الثانية ووافقته دنانير وذكر يونس أن فيه لابن محرز ولابن عباد الكاتب لحنين ولم يجنسهما وأول لحن عباد لا مطاع في آل زينب وأول لحن ابن محرز ولقد أشهد المحدث قال وفيها يقول أيضا طويل\n(أحدث نفسي والأحاديث جمة ... وأكبر همي والأحاديث زينب)\n(إذا طلعت شمس النهار ذكرتها ... وأحدث ذكراها إذا الشمس تغرب)\nكر حماد عن أبيه أن فيه للهذلي لحنا لم ينسبه صوت - مجزوء الكامل -\n(يا نصب عيني لا أرى ... حيث التفت سواك شيا)\n(إني لميت إن صددت ... وإن وصلت رجعت حيا)","topic":"ذكر خبر قس بن ساعدة ونسبه وقصته في هذا الشعر","topicNo":187,"sp":6,"spl":"نسبة هذا الصوت","song":2,"partialRef":{"sid":"b2-14","gi":5,"vi":0,"side":0},"partial":1},
{"id":"b187-8","bab":"الجزء 15","sec":"نسبة هذا الصوت","page":"ج15 ص245","text":"لشعر لعلي بن أديم الجعفي الكوفي والغناء لعمرو بن بانة رمل بالوسطى","topic":"ذكر خبر قس بن ساعدة ونسبه وقصته في هذا الشعر","topicNo":187,"sp":7,"spl":"نسبة هذا الصوت"},
{"id":"b188-1","bab":"الجزء 15","sec":"ذكر علي بن أديم وخبره","page":"ج15 ص257","text":"هو رجل من تجار أهل الكوفة كان يبيع البز وكان متأدبا صالح الشعر يهوى جارية يقال لها منهلة واستهيم بها مدة ثم بيعت فمات أسفا عليها وله حديث طويل معها في كتاب مفرد مشهور صنعه أهل الكوفة لهما فيه ذكر قصصهما وقتا وقتا وما قال فيها من الأشعار وأمرهما متعالم عند العامة وليس مما يصلح الإطالة به أخبرني أحمد بن عبيد الله بن عمار قال حدثني محمد بن داود بن الجراح قال حدثنا أحمد بن أبي خيثمة قال قال دعبل بن علي كان بالكوفة رجل يقال له علي بن أديم وكان يهوى جارية لبعض أهلها فتعاظم أمره وبيعت الجارية فمات جزعا عليها وبلغها خبره فماتت قال وحدثني بعض أهل الكوفة أنه علقها وهي صبية تختلف إلى الكتاب فكان يجيء إلى ذلك المؤدب فيجلس عنده لينظر إليها فلما أن بلغت باعها مواليها لبعض الهاشميين فمات جزعا عليها قال وأنشدني له أيضا - كامل -\n(صاحوا الرحيل وحثني صحبي ... قالوا الرواح فطيروا لبي)\n(واشتقت شوقا كاد يقتلني ... والنفس مشرفة على نحب)\n(لم يلق عند البين ذو كلف ... يوما كما لاقيت من كرب)\n(لا صبر لي عند الفراق على ... فقد الحبيب ولوعة الحب)\nالشعر لعلي بن أديم الكوفي الجعفي والغناء لحكم الوادي وذكر حبش أن لابراهيم بن أبي الهيثم فيه لحنا والله أعلم أخبرني محمد بن خلف بن المرزبان قال حدثني أبو بكر العمري قال حدثني دعبل بن علي قال كان بالكوفة رجل من بني أسد يقال له علي بن أديم فهوي جارية لبعض نساء بني عبس فباعتها لرجل من بني هاشم فخرج بها عن الكوفة فمات علي بن أديم جزعا عليها بعد ثلاثة أيام من خروجها وبلغها خبره فماتت بعده فعمل أهل الكوفة لهما أخبارا هي مشهورة عندهم حدثني محمد بن خلف بن المرزبان قال حدثنا أبو بكر العمري قال حدثنا محمد بن سماعة قال آخر من مات من العشق علي بن أديم الجعفي مر بمكتب في بني عبس بالكوفة فرأى فيه جارية تسمى منهلة عليها ثياب سواد فاستهيم بها وأعجبته وكلف بها وقال فيها - مجزوء الكامل -\n(إني لما يعتادني ... من حب لابسة السواد)\n(في فتنة وبلية ... ما إن يطيقهما فؤادي)\n(فبقيت لا دنيا أصبت ... وفاتني طلب المعاد)\nسأل عنها فإذا لها مالكة عبسية وكان ابن أديم خزازا فتحمل أبوه بجماعة من التجار على مولاتها لتبيعها فأبت وخرج إلى أم جعفر ورفع إليها قصته يسألها فيها المعونة على الجارية فخرج له توقيع بما أحب وأقام يتنجز تمام أمره فبينا هو\nذات يوم على باب أم جعفر إذ خرجت امرأة من دارها فقالت أين العاشق فأشاروا إليه فقالت أنت عاشق وبينك وبين من تحب القناطر والجسور والمياه والأنهار مع ما لا يؤمن من حدوث الحوادث فكيف تصبر على هذا إنك لجسور صبور فخامر قلبه هذا القول وجزع فبادر فاكترى بغلا إلى الكوفة على الدخول فمات يوم دخول الكوفة","topic":"ذكر علي بن أديم وخبره","topicNo":188,"sp":0,"spl":"ذكر علي بن أديم وخبره","song":1},
{"id":"b188-2","bab":"الجزء 15","sec":"ذكر عمرو بن بانة","page":"ج15 ص260","text":"هو عمرو بن محمد بن سليمان بن راشد مولى ثقيف وكان أبوه صاحب ديوان ووجها من وجوه الكتاب وينسب إلى أمه بانة بنت روح القحطبية وكان مغنيا محسنا وشاعرا صالح الشعر وصنعته صنعة متوسطة النادر منها ليس بالكثير وكان يقعده عن اللحاق بالمتقدم في الصنعة أنه كان مرتجلا والمرتجل من المحدثين لا يلحق الضراب وعلى ذلك فما فيه مطعن ولا يقصر جيد صنعته عن صنعة غيره من طبقته وإن كانت قليلة وروايته أحسن رواية وكتابه في الأغاني أصل من الأصول وكان يذهب مذهب إبراهيم بن المهدي في الغناء وتجنيسه ويخالف إسحاق ويتعصب عليه تعصبا شديدا ويواجهه بذلك وينصر إبراهيم بن المهدي عليه وكان تياها معجبا شديد الذهاب بنفسه وهو معدود في ندماء الخلفاء ومغنيهم على ما كان به من الوضح وفيه يقول الشاعر - متقارب -\n(أقول لعمرو وقد مر بي ... فسلم تسليمة جافيه)\n(لئن فضلوك بفضل الغناء ... لقد فضل الله بالعافيه)\nوقال ابن حمدون كان عمرو حسن الحكاية لمن أخذ الغناء عنه حتى كان من يسمعه لو توارى عن عينه عمرو ثم غنى لم يشكك في أنه هو الذي أخذ عنه لحسن حكايته وكان محظوظا ممن يعلمه ما علم أحدا قط إلا خرج نادرا مبرزا فأخبرني جحظة قال حدثني أبو العبيس بن حمدون قال قال لي عمرو بن بانة علمت عشرة غلمان كلهم تبينت فيهم الثقافة والحذق وعلمت أنه يتقدم أحدهم أنت وتمرة وما تبينت قط من أحد خلاف ذلك فعلمته وقال محمد بن الحسن الكاتب حدثني أبو حارثة الباهلي عن أخيه أبي معاوية قال سمعت عمرو بن بانة يقول لإسحاق في كلام جرى بينهما ليس مثلي يقاس بمثلك لأنك تعلمت الغناء تكسبا وتعلمته تطربا وكنت أضرب لئلا أتعلمه وكنت تضرب حتى تتعلمه وأخبرني علي بن سليمان الأخفش قال حدثني محمد بن الحسن بن الحرون قال اجتمع عمرو بن بانة والحسين بن الضحاك في منزل ابن شعوف وكان له خادم يقال له مفحم وكان عمرو يتهم به فلما أخذ فيه الشراب سأل عمرو الحسين بن الضحاك أن يقول في مفحم شعرا ليغني فيه فقال الحسين - منسرح -\n(وا بأبي مفحم لغرته ... قلت له إذ خلوت مكتتما)\n(تحب بالله من يخصك بالحب ... فما قال لا ولا نعما)\nلشعر للحسين بن الضحاك والغناء لعمرو بن بانة ثاني ثقيل بالبنصر قال فغنى فيه عمرو ولم يزل هذا الشعر غناءهم وفيه طربهم إلى أن\nتفرقوا وأتاهم في عشيتهم إسحاق بن إبراهيم الموصلي فسألوا ابن شعوف أن لا يأذن له فحجبه وانصرف إسحاق بن إبراهيم الموصلي إلى منزله فلما تفرقوا مر به الحسين بن الضحاك وهو سكران فأخبره بجميع ما دار بينهما في مجلسهم فكتب إسحاق إلى ابن شعوف - منسرح -\n(يا ابن شعوف أما سمعت بما ... قد صار في الناس كلهم علما)\n(أتاك عمرو فبات ليلته ... في كل ما يشتهى كما زعما)\n(حتى إذا ما الظلام خالطه ... سرى دبيبا فجامع الخدما)\n(ثمت لم يرض أن يفوز بذا ... سرا ولكن أبدى الذي كتما)\n(حتى تغنى لفرط صبوته ... صوتا شفى من فؤاده السقما)\n(وا بأبي مفحم لغرته ... قلت له إذ خلوت مكتتما)\n(تحب بالله من يخصك بالود ... فما قال لا ولا نعما)\nهجر ابن شعوف عمرو بن بانة مدة وقطع عشرته وأخبرني محمد بن العباس اليزيدي بهذا الخبر قال حدثني ميمون بن الأزرق قال كان لمحمد بن شعوف الهاشمي ثلاثة غلمان مغنين ومنهم اثنان صقلبيان محبوبان خاقان وحسين وكان خاقان أحسن الناس غناء وكان حسين يغني غناء متوسطا وهو مع ذلك أضرب الناس وكان قليل الكلام جميل الأخلاق أحسن الناس وجها وجسما وكان الغلام الثالث فحلا يقال له حجاج حسن الوجه رومي حسن الغناء فتعشق عمرو بن بانة منهم المعروف بحسين وقال فيه - منسرح -\n(وا بأبي مفحم لغرته ... قلت له إذ خلوت مكتتما)\n(تحب بالله من يخصك بالود ... فما قال لا ولا نعما)\nلم يذكر غير هذا وقال محمد بن الحسن حدثني أبو الحسين العاصمي قال دخلت أنا\nوصديق لي على عمرو بن بانة في يوم صائف فصادفناه جالسا في ظل طويل ممتع فدعاني إلى مشاركته فيه وجعل يغنينا يومه كله لحنه - وافر -\n(نقابك فاتن لا تفتنينا ... ونشرك طيب لا تحرمينا)\n(وخاتمك اليماني غير شك ... ختمت به رقاب العالمينا)","topic":"ذكر علي بن أديم وخبره","topicNo":188,"sp":1,"spl":"ذكر عمرو بن بانة","song":1},
{"id":"b188-3","bab":"الجزء 15","sec":"ذكر عمرو بن بانة","page":"ج15 ص260","text":"لغناء لعمرو بن بانة هزج خفيف بالبنصر قال فما طربت لغناء قط طربي له ولا سمعت أشجى ولا أكثر نغما ولا أحسن من غنائه أخبرني جحظة قال حدثني أبو حشيشة قال كنت يوما عند عمرو بن بانة فزاره خادم كان يحبه فأقام عنده فطلب عمرو في الدنيا كلها من يضرب عليه فلم يجد أحدا فقال له جعفر الطبال إن أنا غنيتك اليوم على عود يضرب به عليك أي شيء لي عندك قال مائة درهم ودستيجة نبيذ وكان جعفر حاذقا متقدما نادرا طيبا وكان نذل الهمة فقال أسمعني مخرج صوتك ففعل فسوى عليه طبله كما يسوى الوتر واتكأ عليه بركبته فأوقع عليه ولم يزل عمرو يغني بقية يومه على إيقاعه لا ينكر منه شيئا حتى انقضى يومنا ودفع إليه مائة درهم وأحضر الدستيجة فلم يكن له من يحملها فحملها جعفر على عنقه وغطاها بطيلسانه وانصرفنا قال أبو حشيشة فحدثت بهذا الحديث إسحاق بن عمرو بن بزيع وكان صديق إبراهيم بن المهدي فحدثني أن إبراهيم بن المهدي قال له يا جعفر حذق فلانة جاريتي ضرب الطبل ولك مائة دينار أعجل لك منها خمسين قال نعم فعجلت له الخمسون وعلمها فلما حذقت طالب إبراهيم بتتمة المائة فلم يعطه فاستعدى عليه أحمد بن أبي دواد الحسني خليفته فأعداه ووكل إبراهيم\nوكيلا فلما تقدم مع الوكيل إلى القاضي أراد الوكيل أن يكسر حجة جعفر فقال أصلح الله القاضي سله من أين له هذا الذي يدعي وما سببه فقال جعفر أصلح الله القاضي أنا رجل طبال وشارطني إبراهيم على مائة دينار على أن أحذق جاريته فلانة وعجل لي بخمسين دينارا ومنعني الباقي بعد أن رضي حذقها فيحضر القاضي الجارية وطبلها وأحضر أنا طبلي ويسمعنا القاضي فإن كانت مثلي قضى لي عليه وإلا حذقتها فيه حتى يرضى القاضي فقال له القاضي قم عليك وعليها لعنة الله وعلى من يرضى بذلك منك ومنها فأخذ الأعوان بيده فأقاموه وقال علي بن محمد الهشامي حدثني جدي ابن حمدون قال كنت عند عمرو بن بانة يوما ففتح باب داره فإذا بخادم أبيض شيخ قد دخل يقود بغلا له عليه مزادة فلما رآه عمرو صرخ لا إله إلا الله ما أعجب أمرك يا دنيا فقلت له ما لك قال يا أبا عبد الله هذا الخادم رزق غلام علويه المغني الذي يقول فيه الحسين بن الضحاك الشاعر - سريع -\n(يا ليت رزقا كان من رزقي ... يا ليته حظي من الخلق)\nد صار إلى ما ترى ثم غناني لحنا له في هذا الشعر فما سمعت أحسن منه منذ خلقت","topic":"ذكر علي بن أديم وخبره","topicNo":188,"sp":2,"spl":"ذكر عمرو بن بانة"},
{"id":"b188-4","bab":"الجزء 15","sec":"نسبة هذا اللحن","page":"ج15 ص264","text":"\n(يا ليت رزقا كان من رزقي ... يا ليته حظي من الخلق)\n(يا شادنا ملكته رقي ... فلست أرجو راحة العتق)\nلشعر للحسين بن الضحاك والغناء لعمرو بن بانة ولحنه من الثقيل الأول بالوسطى وقال علي بن محمد الهشامي حدثني جدي يعني ابن حمدون قال\nكنا عند المتوكل ومعنا عمرو بن بانة في آخر يوم من شعبان فقال له عمرو يا أمير المؤمنين جعلني الله فداءك تأمر لي بمنزل فإنه لا منزل لي يسعني فأمر المتوكل عبيد الله بن يحيى بأن يبتاع له منزلا يختاره قال وهجم الصوم وشغل عبيد الله وانقطع عمرو عنا فلما أهل شوال دعا بنا المتوكل فكان أول صوت غناه عمرو في شعر هذا - منسرح -\n(ملاك ربي الأعياد تخلقها ... في طول عمر يا سيد الناس)\n(دفعت عن منزل أمرت به ... فإنني عنه مباعد خاس)\n(فمر بتسليمه إلي على ... رغم عدوي بحرمة الكاس)\n(أعوذ بالله والخليفة أن ... يرجع ما قلته على راسي)\nلحن عمرو في هذا الموضع هزج بالبنصر فدعا المتوكل بعبيد الله بن يحيى فقال له لم دافعت عمرا بابتياع المنزل الذي كنت أمرتك بابتياعه فاعتل بدخول الصوم وتشعب الأشغال فتقدم إليه أن لا يؤخر ابتياع ذلك إليه فابتاع له الدور التي في دور سر من رأى بحضرة المعلى بن أيوب وفيها توفي عمرو أخبرني محمد بن إبراهيم قريص قال سمعت أحمد بن أبي العلاء يحدث أستاذي يعني محمد بن داود بن الجراح قال جمع عبد الله بن طاهر بين المغنين وأراد أن يمتحنهم وأخرج بدرة دراهم سبقا لمن تقدم منهم وأحسن فحضره\nمخارق وعلويه وعمرو بن بانة ومحمد بن الحارث بن بسخنر فغنى فلم يصنع شيئا وتبعه محمد بن الحارث فكانت هذه سبيله وامتدت الأعين إلى مخارق وعمرو فبدأ مخارق فغنى مجزوء الكامل\n(إني امرؤ من خيرهم ... عمي وخالي من جذام)\nفما نهنهه عمرو مع انقطاع نفسه حتى غنى سريع\n(يا ربع سلامة بالمنحنى ... بخيف سلع جادك الوابل)\nكان إبراهيم بن المهدي حاضرا فبكى طربا وقال أحسنت والله واستحققت فإن أعطيته وإلا فخذه من مالي يا حبيبي عني أخذت هذا الصوت وقد والله زدت علي فيه وأحسنت غاية الإحسان ولا يزال صوتي عليك أبدا فقال له عبد الله من حكمت له بالسبق فقد حصل وأمر له بالبدرة فحملت إلى عمرو ثم حدثنا بعد ذلك أن إسحاق لقي عمرو بن راشد الخناق فقال له قد بلغني خبر المجلس الذي جمع عبد الله فيه المغنين يمتحنهم ولو شاء لكان في راحة من ذلك قلت وكيف قال أما مخارق فأحسن القوم غناء إذا اتفق له أن يحسن وقلما يتفق له ذلك وأما محمد بن الحارث فأحسنهم شمائل وأملحهم إشارة بأطراف وجهه في الغناء وليس له غير ذلك وأما عمرو بن بانة فأعلم القوم وأرقاهم وأما علويه فمن أدخله ابن الزانية مع هؤلاء","topic":"ذكر علي بن أديم وخبره","topicNo":188,"sp":3,"spl":"نسبة هذا اللحن — نسبة هذين الصوتين صوت مجزوء الكامل","song":2},
{"id":"b188-5","bab":"الجزء 15","sec":"نسبة هذين الصوتين صوت مجزوء الكامل","page":"ج15 ص266","text":"(إني امرؤ من خيرهم ... عمي وخالي من جذام)\n(خود كضوء البدر أو ... أضوا لدى الليل التمام)\n(يجري وشاحاها على ... نحر نقي كالرخام)\nوالغناء لابن جامع رمل مطلق في مجرى البنصر عن إسحاق","topic":"ذكر علي بن أديم وخبره","topicNo":188,"sp":3,"spl":"نسبة هذا اللحن — نسبة هذين الصوتين صوت مجزوء الكامل"},
{"id":"b189-1","bab":"الجزء 15","sec":"صوت خفيف","page":"ج15 ص267","text":"(يا خليلي من بني شيبان ... أنا لا شك ميت فابكياني)\n(إن روحي لم يبق منها سوى شيء ... يسير معلق بلساني)\nلشعر لأبي العتاهية والغناء لإبراهيم رمل بالوسطى عن عمرو والهشامي وإبراهيم وهذا الشعر يخاطب به أبو العتاهية عبد الله وزائدة بن معن بن زائدة الشيباني وكان صديقا وخاصا بهما ثم إن يزيد بن معن غضب لمولاة لهم يقال لها سعدى وكان أبو العتاهية يشبب بها فضربه مائة سوط فهجاه وهجا إخوته ثم أصلح بينهم مندل بن علي العبدي وهو مولى أبي العتاهية فعاد إلى ما كان عليه لهم فأخبرني وكيع قال حدثني حماد بن إسحاق عن أبيه وأخبرني أحمد بن عبيد الله بن عمار قال حدثني علي بن محمد النوفلي عن أبيه قالا قول أبي العتاهية\n(يا خليلي من بني شيبان ... )\nخاطب به عبد الله ويزيد ابني معن بن زائدة أو قال عبد الله وزائدة أخبرني ابن عمار قال حدثني زيد بن موسى بن حماد وأخبرني محمد بن يحيى قال حدثني محمد بن سعيد قال حدثني أبو سويد عبد القوي بن محمد ابن أبي العتاهية قال\nكان أبو العتاهية في حداثته يهوى امرأة من أهل الحيرة نائحة لها حسن وجمال ودماثة وكان ممن يهواها أيضا عبد الله بن معن بن زائدة أبو الفضل وكانت مولاة لهم يقال لها سعدى وكان أبو العتاهية مغرما بالنساء فقال فيها - طويل -\n(ألا يا ذوات السحق في الغرب والشرق ... أفقن فإن النيك أشهى من السحق)\n(أفقن فإن الخبز بالأدم يشتهى ... وليس يسوغ الخبز بالخبز في الخلق)\n(أراكن ترقعن الخروق بمثلها ... وأي لبيب يرقع الخرق بالخرق)\n(وهل يصلح المهراس إلا بعوده ... إذا احتيج منه ذات يوم إلى الدق)\nال وقال فيه أيضا - خفيف -\n(قلت للقلب إذ طوى وصل سعدى ... لهواه البعيدة الأنساب)\n(أنت مثل الذي يفر من القطر ... حذار الندى إلى الميزاب)\nال محمد بن محمد في خبره فغضب عبد الله بن معن لسعدى فضرب أبا العتاهية مائة فقال - مجزوء الخفيف -\n(جلدتني بكفها ... بنت معن بن زائده)\n(جلدتني بكفها ... بأبي أنت جالده)\n(جلدتني وبالغت ... مائة غير واحده)\n(إجلدي إجلدي اجلدي ... إنما أنت والده)\nخبرني وكيع قال حدثني أبو أيوب المديني قال احتال عبد الله بن معن فضرب أبا العتاهية ضربا غير مبرح إشفاقا مما يغنى به فقال\n(إجلدي إجلدي اجلدي ... إنما أنت والده)\nخبرني محمد بن يحيى قال حدثنا الغلابي قال حدثني مهدي قال تهدد عبد الله بن معن أبا العتاهية وخوفه ونهاه أن يعرض لمولاته سعدى فقال أبو العتاهية قوله - مجزوء الوافر -\n(ألا قل لابن معن والذي ... في الود قد حالا)\n(لقد بلغت ما قال ... فما باليت ما قالا)\n(ولو كان من الأسد ... لما راع ولا هالا)\n(فصغ ما كنت حليت ... به سيفك خلخالا)\n(فما تصنع بالسيف ... إذا لم تك قتالا)\n(ولو مد إلى أذنيه ... كفيه لما نالا)\n(قصير الطول والطول ... فلا شب ولا طالا)\n(أرى قومك أبطالا ... وقد أصبحت بطالا)\nخبرني محمد بن يحيى قال حدثني الحسن بن علي الرازي قال حدثني أحمد بن أبي فنن قال كنا عند ابن الأعرابي فذكر قول يحيى بن نوفل في عبد الملك بن عمير القاضي - طويل -\n(إذا كلمته ذات دل لحاجة ... فهم بأن يقضي تنحنح أو سعل)\nأن عبد الملك بن سليمان بن عمير قال تركني والله وإن السعلة لتعرض لي في الخلاء فأذكر قوله فأتركها قال فقلت له هذا عبد الله بن معن بن زائدة يقول له أبو العتاهية - مجزوء الوافر\n(فصغ ما كنت حليت ... به سيفك خلخالا)\n(وما تصنع بالسيف ... إذا لم تك قتالا)\nال فقال عبد الله ما لبست السيف قط فلمحني إنسان إلا قلت إنه يحفظ شعر أبي العتاهية في فينظر إلي بسببه فقال ابن الأعرابي اعجبوا إليه لعنه الله يهجو مولاه وكان أبو العتاهية من موالي بني شيبان وقال محمد بن موسى في خبره وقال أبو العتاهية يهجو عبد الله بن معن - سريع -\n(لا تكثرا يا صاحبي رحلي ... في شتم من أكثر من عذلي)\n(سبحان من خص ابن معن بما ... أرى به من قلة العقل)\n(قال ابن معن وجلا نفسه ... على من الجلوة يا أهلي)\n(أنا فتاة الحي من وائل ... في الشرف الباذخ والنبل)\n(ما في بني شيبان أهل الحجى ... جارية واحدة مثلي)\n(يا ليتني أبصرت دلالة ... تدلني اليوم على فحل)\n(والهفتا اليوم على أمرد ... يلصق مني القرط بالحجل)\n(أتيته يوما فصافحته ... فقال دع كفي وخذ رجلي)\n(يكنى أبا الفضل فيا من رأى ... جارية تكنى أبا الفضل)","topic":"ذكر آدم بن عبد العزيز وأخباره","topicNo":189,"sp":0,"spl":"صوت خفيف","partial":1},
{"id":"b189-2","bab":"الجزء 15","sec":"صوت خفيف","page":"ج15 ص267","text":"(قد نقطت في خدها نقطة ... مخافة العين من الكحل)\n(إن زرتموها قال حجابها ... نحن عن الزوار في شغل)\n(مولاتنا خالية عندها ... بعل ولا إذن على البعل)\n(قولا لعبد الله لا تجهلن ... وأنت رأس النوك والجهل)\n(أتجلد الناس وأنت امرؤ ... تجلد في الدبر وفي القبل)\n(تبذل ما يمنع أهل الندى ... هذا لعمري منتهى البذل)\n(ما ينبغي للناس أن ينسبوا ... من كان ذا جود إلى البخل)\nقال في ضربه إياه - خفيف -\n(ضربتني بكفها بنت معن ... أوجعت كفها وما أوجعتني)\n(ولعمري لولا أذى كفها إذ ... ضربتني بالسوط ما تركتني)\nخبرني ابن عمار قال حدثني محمد بن موسى وأخبرني محمد بن يحيى قال حدثني جبلة بن محمد قالا لما اتصل هجاء أبي العتاهية بعبد الله بن معن غضب من ذلك أخوه يزيد بن معن فهجاه أبو العتاهية فقال - وافر -\n(بنى معن ويهدمه يزيد ... كذاك الله يفعل ما يريد)\n(فمعن كان للحساد غما ... وهذا قد يسر به الحسود)\n(يزيد يزيد في منع وبخل ... وينقص في النوال ولا يزيد)\nخبرني محمد بن يحيى عن جبلة بن محمد قال حدثني أبي قال لما هجا أبو العتاهية بني معن فمضوا إلى مندل وحيان ابني علي العنزيين الفقيهين وكانا من سادات أهل الكوفة وهما من بني عمرو بن عمرو بطن من يقدم بن عنزة فقالوا لهما نحن بيت واحد وأهل ولا فرق بيننا وقد أتانا من مولاكم هذا ما لو أتى من بعيد الولاء لوجب أن تردعاه فأحضرا أبا العتاهية ولم يكن يمكنه الخلاف عليهما فأصلحا بينه وبين عبد الله ويزيد ابني معن وضمنا عنه خلوص النية وعنهما ألا يتتبعاه بسوء وكانا ممن لا يمكن خلافهما فرجعت الحال إلى المودة والصفاء وجعل الناس يعذلون أبا العتاهية فيما فرط منه ولامه آخرون على صلحه لهم فقال - مجزوء الرمل -\n(ما لعذالي وما لي ... أمروني بالضلال)\n(عذلوني في اغتفاري ... لابن معن واحتمالي)\n(أنا منه كنت أكبى ... زندة في كل حال)\n(كل ما قد كان منه ... فلقبح من فعالي)\n(إنما كانت يميني ... صرمت جهلا شمالي)\n(ماله بل نفسه لي ... وله نفسي ومالي)\n(قل لمن يعجب من حسن ... رجوعي وانتقالي)\n(قد رأينا ذا كثيرا ... جاريا بين الرجال)\n(رب وصل بعد صد ... وقلى بعد وصال)\nخبرني محمد بن يحيى قال حدثنا محمد بن موسى قال كان أبو العباس زائدة بن معن صديقا لأبي العتاهية ولم يعن أخويه عليه فمات فرثاه فقال - وافر -\n(حزنت لموت زائدة بن معن ... حقيق أن يطول عليه حزني)\n(فتى الفتيان زائدة المصفى ... أبو العباس كان أخي وخدني)\n(فتى قومي وأي فتى توارت ... به الأكفان تحت ثرى ولبن)\n(ألا يا قبر زائدة بن معن ... دعوتك كي تجيب فلم تجبني)\n(سل الأيام عن أركان قومي ... أصبت بهن ركنا بعد ركن)","topic":"ذكر آدم بن عبد العزيز وأخباره","topicNo":189,"sp":1,"spl":"صوت خفيف"},
{"id":"b189-3","bab":"الجزء 15","sec":"صوت طويل","page":"ج15 ص272","text":"(فما روضة بالحزن طيبة الثرى ... يمج الندى جثجاثها وعرارها)\n(بأطيب من أردان عزة موهنا ... وقد أوقدت بالمندل الرطب نارها)\n(فإن خفيت كانت لعينيك قرة ... وإن تبد يوما لم يعممك عارها)\n(من الخفرات البيض لم تر شقوة ... وفي الحسب المكنون صاف نجارها)\nلشعر لكثير والغناء لمعبد في الأول والثاني ولحنه من الثقيل الأول بالسبابة في مجرى الوسطى عن إسحاق وذكر عمرو بن بانة أنه لابن سريج وللغريض في الرابع والثالث ثقيل أول بالبنصر عن عمرو وحبش وذكر الهشامي أن في الأول والثاني رملا لابن سريج بالوسطى وذكر عمرو وحبش أن فيه رملا لابن جامع بالبنصر وفي الأبيات خفيف ثقيل يقال إنه لمعبد ويقال إنه للغريض وأحسبه للغريض أخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة هكذا موقوفا لم يتجاوز وأخبرني أن كثير بن عبد الرحمن كان غاليا في التشيع وأخبر عن قطام صاحبة ابن ملجم في قدمة قدمها الكوفة فأراد الدخول عليها ليوبخها فقيل له لا تردها فإن لها جوابا فأبى وأتاها فوقف على بابها فقرعه فقالت من هذا فقال كثير بن عبد الرحمن الشاعر فقالت لبنات عم لها تنحين حتى يدخل الرجل فولجن البيت وأذنت له فدخل وتنحت من بين يديه فرآها وقد ولت فقال لها أنت قطام قالت نعم قال صاحبة علي بن أبي طالب عليه السلام قالت\nصاحبة عبد الرحمن بن ملجم قال أليس فيك قتل علي بن أبي طالب قالت بل مات بأجله قال أما والله لقد كنت أحب أن أراك فلما رأيتك نبت عيني عنك فما احلوليت في خلدي قالت والله إنك لقصير القامة عظيم الهامة قبيح المنظر وإنك لكما قال الأول تسمع بالمعيدي خير من أن تراه فقال - طويل -\n(رأت رجلا أودى السفار بوجهه ... فلم يبق إلا منظر وجناجن)\n(فإن أك معروق العظام فإنني ... إذا وزن الأقوام بالقوم وازن)\n(وإني لما استودعتني من أمانة ... إذا ضاعت الأسرار للسر دافن)\nقلت أنت لله أبوك كثير عزة قال نعم قالت الحمد لله الذي قصر بك فصرت لا تعرف إلا بامرأة فقال الأمر كذلك فوالله لقد سار بها شعري وطار بها ذكري وقرب من الخليفة مجلسي وأنا لكما قلت - طويل -\n(فإن خفيت كانت لعينك قرة ... وإن تبد يوما لم يعمك عارها)\n(فما روضة بالحزن طيبة الثرى ... يمج الندى جثجاثها وعرارها)\n(بأطيب من أردان عزة موهنا ... وقد أوقدت بالمندل اللدن نارها)\nقالت بالله ما رأيت شاعرا قط أنقص عقلا منك ولا أضعف وصفا أين أنت من سيدك امرئ القيس حيث يقول - طويل\n(ألم ترياني كلما جئت طارقا ... وجدت بها طيبا وإن لم تطيب)\nخرج وهو يقول - كامل -\n(ألحق أبلج لا يخيل سبيله ... والحق يعرفه ذوو الألباب)\nوت - مجزوء الرمل -\n(هاك فاشربها خليلي ... في مدى الليل الطويل)\n(قهوة في ظل كرم ... سبيت من نهر بيل)\n(في لسان المرء منها ... مثل طعم الزنجبيل)\n(قل لمن يلحاك فيها ... من فقيه أو نبيل)\n(أنت دعها وارج أخرى ... من رحيق السلسبيل)\n(تعطش اليوم وتسقى ... في غد نعت الطلول)\nلشعر لآدم بن عبد العزيز بن عمر بن عبد العزيز والغناء لإبراهيم الموصلي هزج بالنصر عن حبش ولإبراهيم بن المهدي في الخامس والسادس والأول خفيف رمل بالوسطى عن الهشامي ولهاشم فيها ثاني ثقيل بالبنصر وقيل لعبد الرحيم","topic":"ذكر آدم بن عبد العزيز وأخباره","topicNo":189,"sp":2,"spl":"صوت طويل"},
{"id":"b189-4","bab":"الجزء 15","sec":"ذكر آدم بن عبد العزيز وأخباره","page":"ج15 ص276","text":"آدم بن عبد العزيز بن عمر بن عبد العزيز بن مروان بن الحكم بن أبي العاص بن أمية بن عبد شمس بن عبد مناف وأمه أم عاصم بنت سفيان بن عبد العزيز بن مروان بن الحكم أيضا وهو أحد من من عليه أبو العباس السفاح من بني أمية لما قتل من وجد منهم وكان آدم في أول أمره خليعا ماجنا منهمكا في الشراب ثم نسك بعد ما عمر ومات على طريقة محمودة وأخبرني الحسين بن علي عن أحمد بن سعيد الدمشقي عن الزبير بن بكار عن عمه أن المهدي أنشد هذه الأبيات وغني فيها بحضرته - مجزوء الرمل -\n(أنت دعها وارج أخرى ... من رحيق السلسبيل)\nسأل عن قائلها فقيل آدم بن عبد العزيز بن عمر بن عبد العزيز فدعا به فقال له ويلك تزندقت قال لا والله يا أمير المؤمنين ومتى رأيت قرشيا تزندق والمحنة\nفي هذا إليك ولكنه طرب غلبني وشعر طفح على قلبي في حال الحداثة فنطقت به فخلى سبيله قال وكان المهدي يحبه ويكرمه لظرفه وطيب نفسه وروي هذا الخبر عن مصعب الزبيري وإسحاق بن إبراهيم الموصلي قال كان آدم بن عبد العزيز يشرب الخمر ويفرط في المجون وكان شاعرا فأخذه المهدي فضربه ثلاثمائة سوط على أن يقر بالزندقة فقال والله ما أشركت بالله طرفة عين ومتى رأيت قرشيا تزندق قال فأين قولك - مجزوء الرمل -\n(اسقني واسق غصينا ... لا تبع بالنقد دينا)\n(اسقنيها مزة الطعم ... تريك الشين زينا)\nي هذين البيتين لعمرو بن بانة ثاني ثقيل بالوسطى ولإبراهيم هزج بالبنصر قال فقال لئن كنت ذاك فما هو مما يشهد على قائله بالزندقة قال فأين قولك - مجزوء الرمل -\n(اسقني واسق خليلي ... في مدى الليل الطويل)\n(قهوة صهباء صرفا ... سبيت من نهر بيل)\n(لونها أصفر صاف ... وهي كالمسك الفتيل)\n(في لسان المرء منها ... مثل طعم الزنجبيل)\n(ريحها ينفح منها ... ساطعا من رأس ميل)\n(من ينل منها ثلاثا ... ينس منهاج السبيل)\n(فمتى ما نال خمسا ... تركته كالقتيل)\n(ليس يدري حين ذاكم ... ما دبير من قبيل)\n(إن سمعي عن كلام اللائم ... فيها الثقيل)\n(لشديد الوقر إني ... غير مطواع ذليل)\n(قل لمن يلحاك فيها ... من فقيه أو نبيل)\n(أنت دعها وارج أخرى ... من رحيق السلسبيل)\n(نعطش اليوم ونسقى ... في غد نعت الطلول)\nقال كنت فتى من فتيان قريش أشرب النبيذ وأقول ما قلت على سبيل المجون والله ما كفرت بالله قط ولا شككت فيه فخلى سبيله ورق له قال مصعب وهو الذي يقول - مجزوء الخفيف -\n(اسقني يا معاوية ... سبعة أو ثمانيه)\n(اسقنيها وغنني ... قبل أخذ الزبانيه)\n(اسقنيها مدامة ... مزة الطعم صافيه)\n(ثم من لامنا عليها ... فذاك ابن زانيه)\nيه خفيف رمل بالبنصر ينسب إلى أحمد بن المكي وإلى حكم الوادي قال وآدم الذي يقول - وافر\n(أقول وراعني إيوان كسرى ... برأس معان أو أدروسفان)\n(وأبصرت البغال مربطات ... به من بعد أزمنة حسان)\n(يعز على أبي ساسان كسرى ... بموقفكن في هذا المكان)\n(شربت على تذكر عيش كسرى ... شرابا لونه كالزعفران)\n(ورحت كأنني كسرى إذا ما ... علاه التاج يوم المهرجان)\nال وهو الذي يقول - متقارب -\n(أحبك حبين لي واحد ... وآخر أنك أهل لذاك)\n(فأما الذي هو حب الطباع ... فشيء خصصت به عن سواك)\n(وأما الذي هو حب الجمال ... فلست أرى ذاك حتى أراك)\n(ولست أمن بهذا عليك ... لك المن في ذا وهذا وذاك)\nخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عمي عن فليح بن سليمان قال مررنا يوما مع خالصة في موكبها فوقفت على آدم بن عبد العزيز فقالت يا أخي طلبت منا حاجة فرفعناها لك إلى السيدة وأمرت بها وهي في الديوان فساء ظنك بها فقعدت عن تنجزها قال فموه لها عذرا اعتذر به فوقفت عن الموكب حتى مضت ثم قلت له أخملت نفسك والله ما أحسب أنه حبسك عنها إلا الشراب أنت ترى الناس يركضون خلفها وهي ترف عليك لحاجتك فقال والله هو ذاك إذا أصبحت فكل كسرة ولو بملح وافتح دنك فإن\nكان حامضا دبغ معدتك وإن كان حلوا خرطك وإن كان مدركا فهو الذي أردت قلت لا بارك الله عليك ومضيت ثم أقلع بعد ذلك وتاب فاستأذن يوما على يعقوب بن الربيع وأنا عنده فقال يعقوب ارفعوا الشراب فإن هذا قد تاب وأحسبه يكره أن يراه فرفع وأذن له فلما دخل قال ( إني لأجد ريح يوسف لولا أن تفندون","topic":"ذكر آدم بن عبد العزيز وأخباره","topicNo":189,"sp":3,"spl":"ذكر آدم بن عبد العزيز وأخباره","song":1},
{"id":"b189-5","bab":"الجزء 15","sec":"ذكر آدم بن عبد العزيز وأخباره","page":"ج15 ص276","text":"ال يعقوب هو الذي وجدت ولكننا ظننا أن يثقل عليك لتركك الشراب قال إي والله إنه ليثقل علي ذاك قال فهل قلت في ذلك شيئا منذ تركته قال قلت طويل\n(ألا هل فتى عن شربها اليوم صابر ... ليجزيه يوما بذلك قادر)\n(شربت فلما قيل ليس بنازع ... نزعت وثوبي من أذى اللوم طاهر)\nخبرني علي بن صالح بن الهيثم قال حدثني أبو هفان عن إسحاق قال كان مع المهدي رجل من أهل الموصل يقال له سليمان بن المختار وكانت له لحية عظيمة فذهب يوما ليركب فوقعت لحيته تحت قدمه في الركاب فذهب عامتها فقال آدم بن عبد العزيز قوله - مجزوء الوافر -\n(قد استوجب في الحكم ... سليمان بن مختار)\n(بما طول من لحيته ... جزا بمنشار)\n(أو السيف أو الحلق ... أو التحريق بالنار)\n(فقد صار بها أشهر ... من راية بيطار)\nقال ثم أنشدها عمر بن بزيغ المهدي فضحك وسارت الأبيات فقال أسيد بن أسيد وكان وافر اللحية ينبغي لأمير المؤمنين أن يكف هذا الماجن عن الناس\nفبلغت آدم بن عبد العزيز فقال - مجزوء الرمل -\n(لحية تمت وطالت ... لأسيد بن أسيد)\n(كشراع من عباء ... قطعت حبل الوريد)\n(يعجب الناظر منها ... من قريب وبعيد)\n(هي إن زادت قليلا ... قطعت حبل الوريد)\nقال وكان المهدي يدني آدم ويحبه ويقربه وهو الذي قال لعبد الله بن علي لما أمر بقتله في بني أمية بنهر أبي فطرس إن أبي لم يكن كآبائهم وقد علمت مذهبه فيكم فقال صدقت وأطلقه وكان طيب النفس متصوفا ومات على توبة ومذهب جميل","topic":"ذكر آدم بن عبد العزيز وأخباره","topicNo":189,"sp":4,"spl":"ذكر آدم بن عبد العزيز وأخباره"},
{"id":"b190-1","bab":"الجزء 15","sec":"صوت مجزوء الوافر","page":"ج15 ص281","text":"(ألا يا صاح للعجب ... دعوتك ثم لم تجب)\n(إلى القينات واللذات ... والصهباء والطرب)\n(ومنهن التي تبلت ... فؤادك ثم لم تتب)\nلشعر ليزيد بن معاوية يقوله للحسين بن علي بن أبي طالب عليه السلام والغناء لسائب خاثر خفيف رمل بالوسطى عن حبش أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثني المدائني قال قدم سلم بن زياد على يزيد فنادمه فقال له ليلة ألا أوليك خراسان قال بلى وسجستان فعقد له في ليلته فقال - خفيف\n(اسقني شربة فرو عظامي ... ثم عد واسق مثلها ابن زياد)\n(موضع السر والأمانة مني ... وعلى ثغر مغنمي وجهادي)\nال ولما رجع في خلافة أبيه جلس بالمدينة على شراب فاستأذن عليه عبد الله بن العباس والحسين بن علي فأمر بشرابه فرفع وقيل له إن ابن عباس إن وجد ريح شرابك عرفه فحجبه وأذن للحسين فلما دخل وجد رائحة الشراب مع الطيب فقال لله در طيبك هذا ما أطيبه وما كنت أحسب أحدا يتقدمنا في صنعة الطيب فما هذا يا ابن معاوية فقال يا أبا عبد الله هذا طيب يصنع لنا بالشأم ثم دعا بقدح فشربه ثم دعا بقدح آخر فقال اسق أبا عبد الله يا غلام فقال الحسين عليك شرابك أيها المرء لا عين عليك مني فشرب وقال - مجزوء الوافر -\n(ألا يا صاح للعجب ... دعوتك ثم لم تجب)\n(إلى القينات واللذات ... والصهباء والطرب)\n(وباطية مكللة ... عليها سادة العرب)\n(وفيهن التي تبلت ... فؤادك ثم لم تتب)\nوثب الحسين عليه السلام وقال بل فؤادك يا ابن معاوية صوت - وافر -\n(أإن نادى هديلا يوم فلج ... مع الإشراق في فنن حمام)\n(ظللت كأن دمعك در سلك ... وهى خيطا وأسلمه النظام)\n(تموت تشوقا طورا وتحيا ... وأنت جدير أنك مستهام)\n(كأنك من تذكر أم عمرو ... وحبل وصالها خلق رمام)\n(سلام الله يا مطر عليها ... وليس عليك يا مطر السلام)\n(فإن يكن النكاح أحل أنثى ... فإن نكاحها مطرا حرام)\n(ولا غفر الإله لمنكحيها ... ذنوبهم وإن صلوا وصاموا)\n(فطلقها فلست لها بكفء ... وإلا عض مفرقك الحسام)\nلشعر للأحوص والغناء لمعبد من القدر الأوسط من الثقيل الأول بالبنصر في مجرى الوسطى ولإبراهيم الموصلي في الأربعة الأبيات الأول ثاني ثقيل أول بالسبابة في مجرى البنصر أخبرني الحرمي قال حدثنا الزبير قال حدثني محمد بن ثابت بن إبراهيم ابن خلاد الأنصاري قال حدثني أبو عبد الله بن سعد الأنصاري قال قدم الأحوص البصرة فخطب إلى رجل من تميم ابنته وذكر له نسبه فقال هات لي شاهدا واحدا يشهد أنك ابن حمي الدبر وأزوجك فجاءه بمن شهد له على ذلك فزوجه إياها وشرطت عليه ألا يمنعها من أحد من أهلها فخرج إلى المدينة وكانت أختها عند رجل من بني تميم قريبا من طريقهم فقالت\nله اعدل بي إلى أختي ففعل فذبحت لهم وأكرمتهم وكانت من أحسن الناس وكان زوجها في إبله فقالت زوجة الأحوص له أقم حتى يأتي فلما أمسوا راح مع إبله ورعائه وراحت غنمه فراح من ذلك أمر كثير وكان يسمى مطرا فلما رآه الأحوص ازدراه واقتحمته عينه وكان قبيحا دميما فقالت له زوجته قم إلى سلفك وسلم عليه فقال وأشار إلى أخت زوجته بإصبعه - وافر -\n(سلام الله يا مطر عليها ... وليس عليك يا مطر السلام)\nذكر الأبيات وأشار إلى مطر بإصبعه فوثب إليه مطر وبنوه وكاد الأمر يتفاقم حتى حجز بينهم قال الزبير قال محمد بن ثابت أبو عبد الله بن سعد الذي حدث بهذا الحديث أمه بنت الأحوص وأمها التميمية أخت زوجة مطر وأخبرنا الحسين بن يحيى قال حدثنا حماد عن أبيه أن امرأة الأحوص التي تزوجها إحدى بني سعد بن زيد مناة بن تميم وذكر باقي القصيدة وهو قوله - وافر -\n(كأنك من تذكر أم عمرو ... وحبل وصالها خلق رمام)\n(صريع مدامة غلبت عليه ... تموت لها المفاصل والعظام)\n(وأنى من بلادك أم عمرو ... سقى دارا تحل بها الغمام)\n(تحل النعف من أحد وأدنى ... مساكنها الشبيكة أو سنام)\n(فلو لم ينكحوا إلا كفيا ... لكان كفيها الملك الهمام)\nأخبرني الحسين قال قال حماد قرأت على أبي حدثنا ابن كناسة قال مر بنا أشعب ونحن جماعة في المجلس فأتى جار لنا صاحب جوار يقال له أبان بن سليمان وعليه رداء خلق قد بدا منه ظهره وبه آثار فسلم علينا فرددنا عليه السلام فلما مضى قال بعض القوم مدني مجلود فأراه سمعها أو سمعها رجل يمشي معه فأخبره فلما انصرف وانتهى إلى المجلس قال - وافر -","topic":"ذكر متمم وأخباره وخبر مالك ومقتله","topicNo":190,"sp":0,"spl":"صوت مجزوء الوافر"},
{"id":"b190-2","bab":"الجزء 15","sec":"صوت مجزوء الوافر","page":"ج15 ص281","text":"(سلام الله يا مطر عليها ... وليس عليك يا مطر السلام)\nقلت للقوم أنتم والله مطر ومثل ما جرى في هذا الخبر من قوله في المرأة خبر له آخر شبيه به مع ابن حزم أخبرني الحرمي قال حدثنا الزبير قال حدثنا محمد بن فضالة عن جميع ابن يعقوب قال خطب أبو بكر بن محمد بن عمرو بن حزم بنت عبد الله بن حنظلة بن أبي عامر إلى أخيها معمر بن عبد الله فزوجه إياها فقال الأحوص أبياتا وقال لفتى من بني عمرو بن عوف أنشدها معمر بن عبد الله في مجلسه ولك هذه الجبة فقال الفتى نعم فجاءه وهو في مجلسه فقال - بسيط -\n(يا معمر يا ابن زيد حين تنكحها ... وتستبد بأمر الغي والرشد)\nقال كان ذلك الرجل غائبا فقال الفتى - بسيط -\n(أما تذكرت صيفيا فتحفظه ... أو عاصما أو قتيل الشعب من أحد)\nال ما فعلت ولا تذكرت فقال الفتى\n(أكنت تجهل حزما حين تنكحها ... أم خفت لا زلت فيها جائع الكبد)\nقال معمر لم أجهل حزما فقال الفتى\n(أبعد صهر بني الخطاب تجعلهم ... صهرا وبعد بني العوام من أسد)\nقال معمر قد كان ذلك فقال الفتى\n(هبها سليلة خيل غير مقرفة ... مظلومة حبست للعير في الجدد)\nال نعم أعانها الله وصبرها فقال الفتى\n(فكل ما نالنا من عار منكحها ... شوى إذا فارقته وهي لم تلد)\nال نعم إلى الله عز و جل في ذلك الرغبة قال الزبير أما قوله صهر بني الخطاب فإن جميلة بنت أبي الأقلح كانت عند عمر بن الخطاب فولدت له عاصم بن عمر وأما صهر بني العوام فإن نهيسة بنت النعمان بن عبد الله بن أبي عقبة كانت عند يحيى بن حمزة بن عبد الله ابن الزبير فولدت له أبا بكر ومحمدا أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير قال حدثني مصعب قال قال الهدير كرهت أم جعفر أصواتا من الغناء القديم فأرسلت لها رسولا يلقيها في البحر ثم غنتها جارية بعد ذلك - وافر -\n(سلام الله يا مطر عليها ... وليس عليك يا مطر السلام)\nقالت هذا أرسلوا به رسولا مفردا إلى دهلك ليلقيه في البحر خاصة قال والذي حمل أم جعفر على هذا التطير على ابنها محمد الأمين من هذه\nالأصوات أيام محاربته المأمون فمنها قوله - طويل -\n(كليب لعمري كان أكثر ناصرا ... وأيسر جرما منك ضرج بالدم)\nمنها قوله - طويل -\n(هم قتلوه كي يكونوا مكانه ... كما غدرت يوما بكسرى مرازبه)\nمنها قوله - طويل -\n(رأيت زهيرا تحت كلكل خالد ... فأقبلت أسعى كالعجول أبادر)\nمنها قوله - طويل -\n(أبا منذر أفنيت فاستبق بعضنا ... حنانيك بعض الشر أهون من بعض)\nضى الحديث","topic":"ذكر متمم وأخباره وخبر مالك ومقتله","topicNo":190,"sp":1,"spl":"صوت مجزوء الوافر — صوت طويل"},
{"id":"b190-3","bab":"الجزء 15","sec":"صوت طويل","page":"ج15 ص287","text":"(وكنا كندماني جذيمة حقبة ... من الدهر حتى قيل لن يتصدعا)\n(فلما تفرقنا كأني ومالكا ... لطول اجتماع لم نبت ليلة معا)\nلشعر لمتمم بن نويرة يرثي أخاه مالكا والغناء لسياط\n20 -","topic":"ذكر متمم وأخباره وخبر مالك ومقتله","topicNo":190,"sp":1,"spl":"صوت مجزوء الوافر — صوت طويل"},
{"id":"b190-4","bab":"الجزء 15","sec":"ذكر متمم وأخباره وخبر مالك ومقتله","page":"ج15 ص289","text":"هو متمم بن نويرة بن عمرو بن شداد بن عبيد بن ثعلبة بن يربوع بن حنظلة بن مالك بن زيد مناة بن تميم بن مر بن أد بن طابخة بن الياس بن مضر بن نزار ويكنى متمم بن نويرة أبا نهشل ويكنى أخوه مالك أبا المغوار وكان مالك يقال له فارس ذي الخمار قيل له ذلك بفرس كان عنده يقال له ذو الخمار وفيه يقول وقد أحمده في بعض وقائعه - طويل -\n(جزاني دوائي ذو الخمار وصنعتي ... بما بات أطواء بني الأصاغر)\nخبرني أبو خليفة عن محمد بن سلام قال كان مالك بن نويرة شريفا\nفارسا وكان فيه خيلاء وتقدم وكان ذا لمة كبيرة وكان يقال له الجفول وكان مالك قتل في الردة قتله خالد بن الوليد بالبطاح في خلافة أبي بكر وكان مقيما بالبطاح فلما تنبأت سجاح اتبعها ثم أظهر أنه مسلم فضرب خالد عنقه صبرا فطعن عليه في ذلك جماعة من الصحابة منهم عمر بن الخطاب وأبو قتادة الأنصاري لأنه تزوج امرأة مالك بعده وقد كان يقال إنه يهواها في الجاهلية واتهم لذلك أنه قتله مسلما ليتزوج امرأته بعده حدثنا بالسبب في مقتل مالك بن نويرة محمد بن جرير الطبري قال كتب إلي السري بن يحيى يذكر عن شعيب بن إبراهيم التيمي عن سيف ابن عمر عن الصقعب بن عطية عن أبيه أن رسول الله استعمل عماله على بني تميم فكان مالك بن نويرة عامله على بني يربوع قال ولما تنبأت سجاح بنت الحارث بن سويد بن عقفان وسارت من الجزيرة راسلت مالك بن نويرة ودعته إلى الموادعة فأجابها وقناها عن غزوها وحملها على أحياء من بني تميم فأجابته وقالت نعم فشأنك بمن رأيت وإنما أنا امرأة من بني يربوع وإن كان ملك فهو ملككم فلما تزوجها مسيلمة الكذاب ودخل بها انصرفت إلى الجزيرة وصالحته أن يحمل عليها النصف من غلات اليمامة فارعوى حينئذ مالك بن نويرة وندم وتحير في أمره فلحق بالبطاح ولم يبق في بلاد بني حنظلة شيء يكره إلا ما بقي من أمر مالك بن نويرة ومن تأشب إليه بالبطاح فهو على حاله متحير ما يدري ما يصنع\nوقال سيف فحدثني سهل بن يوسف عن القاسم بن محمد وعمرو بن شعيب قالا لما أراد خالد بن الوليد المسير خرج من ظفر وقد استبرأ أسدا وغطفان وطيئا فسار يريد البطاح دون الحزن وعليها مالك بن نويرة وقد تردد عليه أمره وقد ترددت الأنصار على خالد وتخلفت عنه وقالوا ما هذا بعهد الخليفة إلينا فقد عهد إلينا إن نحن فرغنا من البزاخة واستبرأنا بلاد القوم أن يكتب إلينا بما نعمل فقال خالد إن يكن عهد إليكم هذا فقد عهد إلي أن أمضي وأنا الأمير وإلي تنتهي الأخبار ولو أنه لم يأتني له كتاب ولا أمر ثم رأيت فرصة إن أعلمته بها فاتتني لم أعلمه حتى أنتهزها وكذلك لو ابتلينا بأمر ليس منه عهد إلينا فيه لم ندع أن نرى أفضل ما بحضرتنا ونعمل به وهذا مالك بن نويرة بحيالنا وأنا قاصد له بمن معي من المهاجرين والتابعين لهم بإحسان ولست أكرههم ومضى خالد وبرمت الأنصار وتذامروا وقالوا لئن أصاب القوم خيرا إنه لخير حرمتموه ولئن أصابتهم مصيبة ليجتنبنكم الناس فأجمعوا على اللحاق بخالد وجردوا إليه رسولا فأقام عليهم حتى لحقوا به ثم سار حتى لحق البطاح فلم يجد به أحدا قال السري عن شعيب عن سيف عن خزيمة بن شجرة العقفاني عن عثمان بن سويد عن سويد بن المنعبة الرياحي قال قدم خالد بن الوليد البطاح فلم يجد عليه أحدا ووجد مالك بن نويرة قد فرقهم في أموالهم ونهاهم","topic":"ذكر متمم وأخباره وخبر مالك ومقتله","topicNo":190,"sp":2,"spl":"ذكر متمم وأخباره وخبر مالك ومقتله"},
{"id":"b190-5","bab":"الجزء 15","sec":"ذكر متمم وأخباره وخبر مالك ومقتله","page":"ج15 ص289","text":"عن الاجتماع فبعث السرايا وأمرهم بداعية الإسلام فمن أجاب فسالموه ومن لم يجب وامتنع فاقتلوه وكان فيما أوصاهم أبو بكر إذا نزلتم منزلا فأذنوا وأقيموا فإن أذن القوم وأقاموا فكفوا عنهم وإن لم يفعلوا فلا شيء إلا الغارة ثم اقتلوهم كل قتلة الحرق فما سواه فإن أجابوكم إلى داعية الإسلام فسائلوهم فإن هم أقروا بالزكاة قبلتم منهم وإلا فلا شيء إلا الغارة ولا كلمة فجاءته الخيل بمالك بن نويرة في نفر معه من بني ثعلبة بن يربوع ومن بني عاصم وعبيد وعرين وجعفر واختلفت السرية فيهم وفيهم أبو قتادة وكان ممن شهد أنهم قد أذنوا وأقاموا وصلوا فلما اختلفوا فيهم أمر بحبسهم في ليلة باردة لا يقوم لها شيء وجعلت تزداد بردا فأمر خالد مناديا فنادى دافئوا أسراكم وكان في لغة كنانة إذا قالوا دافأنا الرجل وأدفئوه فذلك معنى اقتلوه من الدفء فظن القوم أنه يريد القتل فقتلوهم فقتل ضرار بن الأزور مالكا فسمع خالد الواعية فخرج وقد فرغوا منهم فقال إذا أراد الله أمرا أصابه وقد اختلف القوم فيهم فقال أبو قتادة هذا عملك فزبره خالد فغضب ومضى حتى أتى أبا بكر فغضب عليه أبو بكر حتى كلمه عمر بن الخطاب فيه فلم يرض إلا بأن يرجع إليه فرجع إليه فلم يزل معه حتى قدم المدينة وقد كان تزوج خالد أم تميم بنت المنهال وتركها لينقضي طهرها وكانت العرب تكره النساء في الحرب وتعايره فقال عمر لأبي بكر إن في سيف خالد رهقا وحق عليه أن\nتقيده وأكثر عليه في ذلك وكان أبو بكر لا يقيد من عماله ولا من وزعته فقال هبه يا عمر تأول فأخطأ فارفع لسانك عن خالد وودى مالكا وكتب إلى خالد أن يقدم عليه ففعل وأخبره خبره فعذره وقبل منه وعنفه بالتزويج الذي كانت العرب تعيب عليه من ذلك فذكر سيف عن هشام بن عروة عن أبيه قال شهد قوم من السرية أنهم أذنوا وأقاموا وصلوا وشهد آخرون أنه لم يكن من ذلك شيء فقتلوا وقدم أخوه متمم ينشد أبا بكر دمه ويطلب إليه في سبيهم فكتب له برد السبي وألح عليه عمر في خالد أن يعزله وقال إن في سيفه لرهقا فقال له لا يا عمر لم أكن لأشيم سيفا سله الله على الكافرين حدثنا محمد بن إسحاق قال كتب إلى السري عن شعيب عن سيف عن خزيمة عن عثمان عن سويد قال كان مالك من أكثر الناس شعرا وإن أهل العسكر أثفوا القدور برؤوسهم فما منها رأس إلا وصلت النار إلى بشرته ما خلا مالكا فإن القدر نضجت وما نضج رأسه من كثرة شعره ووقى الشعر البشرة من حر النار أن تبلغ منه ذلك قال وأنشد متمم عمر بن الخطاب ذكر خمصه يعني قوله - طويل -\n(لقد كفن المنهال تحت ردائه ... فتى غير مبطان العشيات أروعا)\nفقال أكذاك كان يا متمم قال أما ما أعني فنعم أخبرني اليزيدي قال حدثنا الزبير قال حدثني محمد بن فليح عن موسى بن عقبة عن ابن شهاب وحدثنيه أحمد بن الجعد قال حدثنا محمد بن إسحاق المسيبي قال حدثنا محمد بن فليح عن موسى بن عقبة عن ابن شهاب أن مالك بن نويرة كان من أكثر الناس شعرا وأن خالدا لما قتله أمر برأسه فجعل أثفية لقدر فنضج ما فيها قبل أن تبلغ النار إلى شواته أخبرني محمد بن جرير قال حدثنا محمد بن حميد قال حدثنا مسلمة عن ابن إسحاق عن طلحة بن عبيد الله بن عبد الرحمن بن أبي بكر الصديق رضي الله عنه أن أبا بكر كان من عهده إلى جيوشه أن إذا غشيتم دارا من دور الناس فسمعتم فيها أذانا للصلاة فأمسكوا عن أهلها حتى تسألوهم ماذا نقموا وإذا لم تسمعوا أذانا فشنوا الغارة واقتلوا وحرقوا فكان ممن شهد لمالك بالإسلام أبو قتادة الأنصاري واسمه الحارث بن ربعي أخو بني سلمة وقد كان عاهد الله أنه لا يشهد حربا بعدها أبدا وكان يحدث أنهم لما غشوا القوم راعوهم تحت الليل فأخذ القوم السلاح قال فقلنا لهم إنا المسلمون فقالوا ونحن المسلمون قلنا فما بال السلاح معكم فإن كنتم كما تقولون فضعوا السلاح ففعلوا ثم صلينا وصلوا وكان خالد يعتذر في قتله أنه قال له وهو يراجعه ما إخال صاحبكم يعني النبي إلا وقد كان يقول كذا وكذا فقال خالد أو ما تعده صاحبا ثم قدمه فضرب عنقه وأعناق أصحابه فلما بلغ قتلهم عمر بن الخطاب تكلم فيه عند أبي بكر رضي الله عنه وقال عدو الله عدا على امرىء مسلم","topic":"ذكر متمم وأخباره وخبر مالك ومقتله","topicNo":190,"sp":3,"spl":"ذكر متمم وأخباره وخبر مالك ومقتله"},
{"id":"b190-6","bab":"الجزء 15","sec":"ذكر متمم وأخباره وخبر مالك ومقتله","page":"ج15 ص289","text":"فقتله ثم نزا على امرأته وأقبل خالد بن الوليد قافلا حتى دخل المسجد وعليه قباء له وعليه صدأ الحديد معتجرا بعمامة قد غرز فيها أسهما فلما أن دخل المسجد قام إليه عمر فانتزع الأسهم من رأسه فحطمها ثم قال أقتلت امرأ مسلما ثم نزوت على امرأته والله لأرجمنك بأحجارك ولا يكلمه خالد بن الوليد ولا يظن إلا أن رأي أبي بكر على مثل رأي عمر فيه حتى دخل على أبي بكر فأخبره الخبر واعتذر إليه فعذره أبو بكر وتجاوز له عما كان في حربه تلك فخرج خالد حين رضي عنه أبو بكر وعمر جالس في المسجد الحرام فقال هلم إلي يا ابن أم شملة فعرف عمر أن أبا بكر قد رضي عنه فلم يكلمه ودخل بيته وكان الذي قتل مالك بن نويرة عبد بن الأزور الأسدي وقال محمد بن جرير قال ابن الكلبي الذي قتل مالك بن نويرة ضرار بن الأزور وهكذا روى أبو زيد عمر بن شبة عن أصحابه وأبو خليفة عن محمد بن سلام قال قدم مالك بن نويرة على النبي فيمن قدم من أمثاله من العرب فولاه صدقات قومه بني يربوع فلما مات النبي اضطرب فيها فلم يحمد أمره وفرق ما في يده من إبل الصدقة فكلمه الأقرع بن حابس المجاشعي والقعقاع بن معبد بن زرارة الدارمي فقالا له إن لهذا الأمر قائما وطالبا فلا تعجل بتفرقة ما في يدك فقال - وافر -\n(أراني الله بالنعم المندى ... ببرقة رحرحان وقد أراني)\n(تمشي يابن عوذة في تميم ... وصاحبك الأقيرع تلحياني)\n(حميت جميعها بالسيف صلتا ... ولم ترعش يداي ولا بناني)\nعني أم القعقاع وهي معاذة بنت ضرار بن عمرو وقال أيضا - طويل -\n(وقلت خذوا أموالكم غير خائف ... ولا ناظر فيما يجيء من الغد)\n(فإن قام بالأمر المخوف قائم ... منعنا وقلنا الدين دين محمد)\nال ابن سلام فمن لا يعذر خالدا يقول إنه قال لخالد وبهذا أمرك صاحبك يعني النبي وأنه أراد بهذه القرشية ومن يعذر خالدا يقول إنه أراد انتفاء من النبوة ويحتج بشعريه المذكورين آنفا ويذكر خالد أن النبي لما وجهه إلى ابن جلندى قال له يا أبا سليمان إن رأت عينك مالكا فلا تزايله أو تقتله قال محمد بن سلام وسمعني يوما يونس وأنا أراد التميمية في خالد وأعذره فقال لي يا أبا عبد الله أما سمعت بساقي أم تميم يعني زوجة مالك التي تزوجها خالد لما قتله وكان يقال إنه لم ير أحسن من ساقيها قال وأحسن ما سمعت من عذر خالد قول متمم بأن أخاه لم يستشهد ففيه دليل على عذر خالد أخبرنا اليزيدي قال حدثنا الرياشي قال حدثني محمد بن الحكم البجلي عن الأنصاري قال صلى متمم بن نويرة مع أبي بكر الصبح ثم أنشده قوله - كامل\n(نعم القتيل إذا الرياح تناوحت ... تحت الإزار قتلت يا ابن الأزور)\n(أدعوته بالله ثم قتلته ... لو هو دعاك بذمة لم يغدر)\nقال أبو بكر والله ما دعوته ولا قتلته فقال - كامل -\n(لا يضمر الفحشاء تحت ردائه ... حلو شمائله عفيف المئزر)\n(ولنعم حشو الدرع أنت وحاسرا ... ولنعم مأوى الطارق المتنور)\nال ثم بكى حتى سالت عينه ثم انخرط على سية قوسه متكئا يعني مغشيا عليه أخبرني اليزيدي قال حدثنا الرياشي قال حدثني محمد بن صخر بن خلخلة قال ذكر متمم بن نويرة أخاه في المدينة فقيل له إنك لتذكر أخاك فما كانت صفته أوصفه لنا فقال كان يركب الجمل الثفال في الليلة الباردة يرتوي\nلأهله بين المزادتين المضرجتين عليه الشملة الفلوت يقود الفرس الجرور ثم يصبح ضاحكا أخبرني اليزيدي قال حدثنا أحمد بن زهير عن الزبير بن حبيب بن بدر الطائي وغيره أن المنهال رجلا من بني يربوع مر على أشلاء مالك بن نويرة لما قتله خالد فأخذ ثوبا وكفنه فيه ودفنه ففيه يقول متمم - طويل -\n(لعمري وما دهري بتأبين مالك ... ولا جزع مما أصاب فأوجعا)\n(لقد كفن المنهال تحت ردائه ... فتى غير مبطان العشيات أروعا)\nناه عمرو بن أبي الكنات ثقيل أول بالوسطى عن حبش أخبرني أحمد بن عبيد الله بن عمار قال حدثنا الحسن بن محمد البصري قال حدثنا الحسن بن إسماعيل القضاعي قال حدثني أحمد بن عمار العبدي وكان من العلم بموضع قال حدثني أبي عن جدي قال صليت مع عمر ابن الخطاب الصبح فلما انفتل من صلاته إذا هو برجل قصير أعور متنكبا قوسا وبيده هراوة فقال من هذا فقال متمم بن نويرة فاستنشده قوله في أخيه فأنشده - طويل\n(لعمري وما دهري بتأبين مالك ... ولا جزع مما أصاب فأوجعا)","topic":"ذكر متمم وأخباره وخبر مالك ومقتله","topicNo":190,"sp":4,"spl":"ذكر متمم وأخباره وخبر مالك ومقتله","song":1},
{"id":"b190-7","bab":"الجزء 15","sec":"ذكر متمم وأخباره وخبر مالك ومقتله","page":"ج15 ص289","text":"(لقد كفن المنهال تحت ثيابه ... فتى غير مبطان العشيات أروعا)\nتى بلغ إلى قوله - طويل -\n(وكنا كندماني جذيمة حقبة ... من الدهر حتى قيل لن يتصدعا)\n(فلما تفرقنا كأني ومالكا ... لطول اجتماع لم نبت ليلة معا)\nفقال عمر هذا والله التأبين ولوددت أني أحسن الشعر فأرثي أخي زيدا بمثل ما رثيت به أخاك فقال متمم لو أن أخي مات على ما مات عليه أخوك ما رثيته وكان قتل باليمامة شهيدا وأمير الجيش خالد بن الوليد فقال لعمر ما عزاني أحد عن أخي بمثل ما عزاني به متمم قال وكان عمر يقول ما هبت الصبا من نحو اليمامة إلا خيل إلي أني أشم ريح أخي زيد قال وقيل لمتمم ما بلغ من وجدك على أخيك فقال أصبت بإحدى عيني فما قطرت منها دمعة عشرين سنة فلما قتل أخي استهلت فما ترقأ أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثنا أبو أحمد الزبيري قال حدثنا عبد الله بن لاحق عن ابن أبي مليكة قال مات عبد الرحمن بن أبي بكر بالحبشي خارج مكة فحمل فدفن بمكة فقدمت عائشة فوقفت على قبره وقالت متمثلة - طويل -\n(وكنا كندماني جذيمة حقبة ... من الدهر حتى قيل لن يتصدعا)\n(فلما تفرقنا كأني ومالكا ... لطول اجتماع لم نبت ليلة معا)\nأما والله لو حضرتك لدفنت حيث مت ولو شهدتك ما زرتك أخبرني إبراهيم بن أيوب قال حدثنا عبد الله بن مسلم بن قتيبة أن متمم بن نويرة دخل على عمر بن الخطاب فقال له عمر ما أرى في أصحابك مثلك فقال يا أمير المؤمنين أما والله إني مع ذلك لأركب الجمل الثفال وأعتقل الرمح الشطون وألبس الشملة الفلوت ولقد أسرتني بنو تغلب في الجاهلية فبلغ ذلك أخي مالكا فجاء ليفديني منهم فلما رآه القوم أعجبهم جماله وحدثهم فأعجبهم حديثه فأطلقوني له بغير فداء أخبرني أحمد بن عبد العزيز قال حدثني النوفلي عن أبيه وأهله قالوا لما أنشد متمم بن نويرة عمر بن الخطاب قوله يرثي أخاه مالكا - طويل -\n(وكنا كندماني جذيمة حقبة ... من الدهر حتى قيل لن يتصدعا)\n(فلما تفرقنا كأني ومالكا ... لطول اجتماع لم نبت ليلة معا)\nال له عمر هل كان مالك يحبك مثل محبتك إياه أم هل كان مثلك فقال وأين أنا من مالك وهل أبلغ مالكا والله يا أمير المؤمنين لقد أسرني حي من العرب فشدوني وثاقا بالقد وألقوني بفنائهم فبلغه خبري فأقبل على راحلته حتى انتهى إلى القوم وهم جلوس في ناديهم فلما نظر إلي أعرض عني ونظر القوم إليه فعدل إليهم وعرفت ما أراد فسلم عليهم وحادثهم وضاحكهم وأنشدهم فوالله إن زال كذلك حتى ملأهم سرورا وحضر غداؤهم فسألوه ليتغدى معهم فنزل وأكل ثم نظر إلي وقال إنه لقبيح بنا أن نأكل ورجل ملقى بين أيدينا لا يأكل معنا وأمسك يده عن الطعام فلما رأى ذلك القوم نهضوا وصبوا الماء على قدي حتى لان وخلوني ثم جاؤوا فأجلسوني معهم على الغداء فلما أكلنا قال لهم\nأما ترون تحرم هذا بنا وأكله معنا إنه لقبيح بكم أن تردوه إلى القد فخلوا سبيلي فكان كما وصفت وما كذبت في شيء من صفته إلا أني وصفته خميص البطن وكان ذا بطن أخبرني الحسن بن علي قال حدثنا أحمد بن نصر العتيقي قال حدثني محمد بن الحسن بن مسعود الزرقي عن أبيه عن مروان بن موسى ووجدت هذا الخبر أيضا في كتاب محمد بن علي بن حمزة العلوي عن علي بن محمد النوفلي عن أبيه أن عمر بن الخطاب قال لمتمم بن نويرة إنكم أهل بيت قد تفانيتم فلو تزوجت عسى أن ترزق ولدا يكون فيه بقية منكم فتزوج امرأة بالمدينة فلم ترض أخلاقه لشدة حزنه على أخيه وقلة حفله بها فكانت تماظه وتؤذيه فطلقها وقال - طويل -\n(أقول لهند حين لم أرض فعلها ... أهذا دلال الحب أم فعل فارك)\n(أم الصرم ما تبغي وكل مفارق ... يسير علينا فقده بعد مالك)\nخبرني محمد بن جعفر الصيدلاني النحوي قال حدثنا محمد بن موسى بن حماد قال حدثنا عبد الله بن أبي سعد قال حدثني أحمد بن معاوية عن سلمويه بن أبي صالح عن عبد الله بن المبارك عن نعيم بن أبي عمرو الرازي قال بينا طلحة والزبير يسيران بين مكة والمدينة إذ عرض لهما أعرابي فوقفا ليمضي فوقف فتعجلا ليسبقاه فتعجل فقالا ما أثقلك يا أعرابي تعجلنا لنسبقك فتعجلت فوقفنا لتمضي فوقفت فقال لا إله إلا الله مفني أغدر الناس أغدر بأصحاب محمد هباني خفت الضلال فأحببت أن أستدل بكما أو","topic":"ذكر متمم وأخباره وخبر مالك ومقتله","topicNo":190,"sp":5,"spl":"ذكر متمم وأخباره وخبر مالك ومقتله"},
{"id":"b190-8","bab":"الجزء 15","sec":"ذكر متمم وأخباره وخبر مالك ومقتله","page":"ج15 ص289","text":"خفت الوحشة فأحببت أن أستأنس بكما فقال طلحة من أنت قال أنا متمم ابن نويرة فقال طلحة واسوأتاه لقد مللنا غير مملول هات بعض ما ذكرت في أخيك من البكاء فزوجوه أم خالد فبينا هو واضع رأسه على فخذها إذ بكى فقالت لا إله إلا الله أما تنسى أخاك فأنشأ يقول - طويل -\n(أقول لها لما نهتني عن البكا ... أفي مالك تلحينني أم خالد)\n(فإن كان إخواني أصيبوا وأخطأت ... بني أمك اليوم الحتوف الرواصد)\n(فكل بني أم سيمسون ليلة ... ولم يبق من أعيانهم غير واحد)\nما معنى قول متمم\n(وكنا كندماني جذيمة حقبة ... )\nإنه يعني نديمي جذيمة الأبرش الملك وهو جذيمة بن مالك بن فهم ابن غانم بن دوس بن عدثان الأسدي وكان الخبر في ذلك ما أخبرنا به علي بن سليمان الأخفش عن أبي سعيد السكري عن محمد بن حبيب وذكر ابن الكلبي عن أبيه والشرقي وغيره من الرواة أن جذيمة الأبرش وأصله من الأزد وكان أول من ملك قضاعة بالحيرة وأول من حدا النعال وأدلج من الملوك ورفع له الشمع قال يوما لجلسائه قد ذكر لي عن غلام من لخم مقيم في أخواله من إياد له ظرف ولب فلو بعثت إليه يكون في ندماني ووليته كأسي والقيام بمجلسي كان الرأي فقالوا الرأي ما رأى الملك فليبعث إليه ففعل فلما قدم فعل به ما أراد له فمكث كذلك مدة طويلة ثم أشرفت عليه يوما رقاش ابنة الملك أخت جذيمة فلم تزل تراسله\nحتى اتصل بينهما ثم قالت له يا عدي إذا سقيت القوم فامزج لهم واسق الملك صرفا فإذا أخذت منه الخمر فاخطبني إليه فإنه يزوجك وأشهد القوم عليه إن هو فعل ففعل الغلام ذلك فخطبها فزوجه وانصرف الغلام بالخبر إليها فقالت عرس بأهلك ففعل فلما أصبح غدا مضرجا بالخلوق فقال له جذيمة ما هذه الآثار يا عدي قال آثار العرس قال أي عرس قال عرس رقاش قال فنخر وأكب على الأرض ورفع عدي جراميزه فأسرع جذيمة في طلبه فلم يحسسه وقيل إنه قتله وكتب إلى أخته - خفيف -\n(حدثيني رقاش لا تكذبيني ... أبحر زنيت أم بهجين)\n(أم بعبد فأنت أهل لعبد ... أم بدون فأنت أهل لدون)\nالت بل زوجتني امرأ عربيا فنقلها جذيمة وحصنها في قصره واشتملت على حمل فولدت منه غلاما وسمته عمرا وربته فلما ترعرع حلته وعطرته وألبسته كسوة مثله ثم أرته خاله فأعجب به وألقيت عليه منه محبة ومودة حتى إذا وصف خرج الغلمان يجتنون الكمأة في سنة قد أكمأت وخرج معهم وقد خرج جذيمة فبسط له في روضة فكان الغلمان إذا أصابوا الكمأة أكلوها وإذا أصابها عمرو خبأها ثم أقبلوا يتعادون وهو معهم يقدمهم ويقول - سريع -\n(هذا جناي وخياره فيه ... إذ كل جان يده إلى فيه)\nفالتزمه جذيمة وحباه وقرب من قلبه وحل منه بكل مكان ثم إن الجن استطارته فلم يزل جذيمة يرسل في الآفاق في طلبه فلم يسمع له بخبر فكف عنه ثم أقبل رجلان يقال لأحدهما عقيل والآخر مالك ابنا فالج وهما يريدان الملك بهدية فنزلا على ماء ومعهما قينة يقال لها أم عمرو فنصبت قدرا وأصلحت طعاما فبينما هما يأكلان إذ أقبل رجل أشعث أغبر قد طالت أظفاره وساءت حاله حتى جلس مزجر الكلب فمد يده فناولته شيئا فأكله ثم مد يده فقالت إن يعط العبد كراعا يتسع ذراعا فأرسلتها مثلا ثم ناولت صاحبيها من شرابها وأوكأت دنها فقال عمرو بن عدي - وافر -\n(صددت الكأس عنا أم عمرو ... وكان الكأس مجراها اليمينا)\n(وما شر الثلاثة أم عمرو ... بصاحبك الذي لا تصبحينا)\nناه معبد فيما ذكر عن إسحاق في كتابه الكبير وقد زعم بعض الرواة أن هذا الشعر لعمرو بن معد يكرب وأخبرنا اليزيدي قال حدثنا الخليل بن أسد النوشجاني قال حدثنا حفص بن عمرو عن الهيثم بن عدي عن ابن عياش أن هذا الشعر لعمرو بن معد يكرب في ربيعة بن نصر اللخمي","topic":"ذكر متمم وأخباره وخبر مالك ومقتله","topicNo":190,"sp":6,"spl":"ذكر متمم وأخباره وخبر مالك ومقتله","song":1,"partialRef":{"sid":"b190-3","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b190-9","bab":"الجزء 15","sec":"رجع الحديث إلى سياقه","page":"ج15 ص305","text":"فقال الرجلان ومن أنت فقال إن تنكراني أو تنكرا نسبي فإنني عمرو وعدي أبي فقاما إليه فلثماه وغسلا رأسه وقلما أظفاره وقصرا من لمته وألبساه من طرائف ثيابهما وقالا ما كنا لنهدي إلى الملك هدية أنفس عنده ولا هو عليها أحسن صفدا من ابن أخته فقد رده الله عز و جل إليه فخرجا حتى إذا دفعا إلى باب الملك بشراه به فصرفه إلى أمه فألبسته ثيابا من ثياب الملوك وجعلت في عنقه طوقا كانت تلبسه إياه وهو صغير وأمرته بالدخول على خاله فلما رآه قال شب عمرو عن الطوق فأرسلها مثلا وقال للرجلين اللذين قدما به احكما فلكما حكمكما قالا منادمتك ما بقيت وبقينا قال ذلك لكما فهما نديما جذيمة اللذان ذكرهما متمم وضربت بهما الشعراء المثل قال أبو خراش الهذلي - طويل -\n(ألم تعلمي أن قد تفرق قبلنا ... خليلا صفاء مالك وعقيل)\nقال ابن حبيب في خبره وكان جذيمة من أفضل الملوك رأيا وأبعدهم مغارا وأشدهم نكاية وهو أول من استجمع له الملك بأرض العراق وكانت منازله ما بين الأنبار وبقة وهيت وعين التمر وأطراف البر والقطقطانة والحيرة فقصد في جموعه عمرو بن الظرب بن حسان بن أذينة بن السميدع بن هوبر العاملي من عاملة العماليق فجمع عمرو جموعه ولقيه فقتله جذيمة وفض جموعه فانفلوا وملكوا عليهم ابنته الزباء وكانت من أحزم الناس فخافت أن تغزوها ملوك العرب فاتخذت لنفسها نفقا في حصن كان لها على شاطئ الفرات وسكرت الفرات في وقت قلة الماء وبنت أزجا من الآجر والكلس متصلا بذلك النفق وجعلت نفقا آخر في البرية متصلا بمدينة لأختها ثم أجرت الماء عليه فكانت إذا خافت عدوا دخلت النفق فلما اجتمع لها أمرها واستحكم ملكها أجمعت على غزو جذيمة ثائرة بأبيها فقالت لها أختها وكانت ذات رأي وحزم إنك إن غزوت جذيمة فإنه امرؤ له ما يصده فإن ظفرت أصبت ثأرك وإن ظفر بك فلا بقية لك والحرب سجال ولا تدرين كيف تكون ألك أم عليك ولكن ابعثي إليه فأعلميه أنك قد رغبت في أن تتزوجيه وتجمعي ملكك إلى ملكه وسليه أن يجيبك إلى ذلك لأنه إن اغتر ففعل ظفرت به بلا مخاطرة فكتبت الزباء في ذلك إلى جذيمة تقول له إنها قد رغبت في صلة بلدها ببلده وإنها في ضعف من سلطانها وقلة ضبط لمملكتها وإنها لم تجد كفأ غيره وتسأله الإقبال عليها وجمع ملكها إلى ملكه فلما وصل ذلك إليه استخفه وطمع\nفيه فشاور أصحابه فكل صوب رأيه في قصدها وإجابتها إلا قصير بن سعد بن عمرو بن جذيمة بن قيس بن هلال بن نمارة بن لخم فقال هذا رأي فاتر وغدر حاضر فإن كانت صادقة فلتقبل إليك وإلا فلا تمكنها من نفسك فتقع في حبالها وقد وترتها في أبيها فلم يوافق جذيمة ما قال وقال له أنت امرؤ رأيك في الكن لا في الضح ورحل فقال له قصير في طريقه انصرف ودمك في وجهك فقال جذيمة ببقة قضي الأمر فأرسلها مثلا ومضى حتى إذا شارف مدينتها قال لقصير ما الرأي قال ببقة تركت الرأي قال فما ظنك بالزباء قال القول رداف والحزم عيرانة لا تخاف واستقبله رسلها بالهدايا والألطاف فقال يا قصير كيف ترى قال خطر يسير في خطب كبير وستلقاك الخيول فإن سارت أمامك فالمرأة صادقة وإن أخذت في جنبيك وأحاطت بك فالقوم غادرون فلقيته الخيول فأحاطت به فقال له قصير اركب العصا فإنها لا تدرك ولا تسبق يعني فرسا له كانت تجنب قبل أن يحولوا بينك وبين جنودك فلم يفعل فجال قصير في ظهرها فمرت به تعدو في أول أصحاب جذيمة ولما أحيط بجذيمة التفت فرأى قصيرا على فرسه العصا في أول القوم فقال لحازم من يجري العصا في أول القوم فذكر أبو عبيدة والأصمعي","topic":"ذكر متمم وأخباره وخبر مالك ومقتله","topicNo":190,"sp":7,"spl":"رجع الحديث إلى سياقه"},
{"id":"b190-10","bab":"الجزء 15","sec":"رجع الحديث إلى سياقه","page":"ج15 ص305","text":"أنها لم تكن تقف حتى جرت ثلاثين ميلا ثم وقفت فبالت هناك فبني على ذلك الموضع برج يسمى العصا وأخذ جذيمة فأدخل على الزباء فاستقبلته قد كشفت عن فرجها فإذا هي قد ضفرت الشعر عليه فقالت يا جذيم أذات عروس ترى قال بل أرى متاع أمة لكعاء غير ذات خفر ثم قال بلغ المدى وجف الثرى وأمر غدر أرى قالت والله ما ذلك من عدم مواس ولا قلة أواس ولكنها شيمة ما أناس ثم قالت لجواريها خذن بعضد سيدكن ففعلن ثم دعت بنطع فأجلسته عليه وأمرت برواهشه فقطعت في طست من ذهب يسيل دمه فيه وقالت له يا جذيم لا يضيعن من دمك شيء فإني أريده للخبل فقال لها وما يحزنك من دم أضاعه أهله وإنما كان بعض الكهان قال لها إن نقط من دمه شيء في غير الطست أدرك بثأره فلم يزل دمه يجري في الطست حتى ضعف فتحرك فنقطت من دمه نقطة على أسطوانة رخام ومات قال والعرب تتحدث في أن دماء الملوك شفاء من الخبل قال المتلمس - طويل -\n(من الدارميين الذين دماؤهم ... شفاء من الداء المجنة والخبل)\nال وجمعت دمه في برنية وجعلته في خزانتها ومضى قصير إلى عمرو بن\nعبد الحر التنوخي فقال له اطلب بدم ابن عمك وإلا سبتك به العرب فلم يحفل بذلك فخرج قصير إلى عمرو بن عدي ابن أخت جذيمة فقال هل لك في أن أصرف الجنود إليك على أن تطلب بثأر خالك فجعل ذلك له فأتى القادة والأعلام فقال لهم أنتم القادة والرؤساء وعندنا الأموال والكنوز فانصرف إليه منهم بشر كثير فالتقى بعمرو التنوخي فلما صافوا القتال تابعه التنوخي ومالك بن عمرو بن عدي فقال له قصير انظر ما وعدتني في الزباء فقال وكيف وهي أمنع من عقاب الجو فقال أما إذ أبيت فإني جادع أنفي وأذني ومحتال لقتلها فأعني وخلاك ذم فقال له عمرو وأنت أبصر فجدع قصير أنفه ثم انطلق حتى دخل على الزباء فقالت من أنت قال أنا قصير ولا ورب البشر ما كان على ظهر الأرض أحد أنصح لخدمته مني ولا أغش لك حتى جدع عمرو بن عدي أنفي وأذني فعرفت أني لن أكون مع أحد أثقل عليه منك فقالت أي قصير نقبل ذلك منك ونصر لك في بضاعتنا وأعطته مالا للتجارة فأتى بيت مال الحيرة فأخذ منه بأمر عدي ما ظن أنه يرضيها وانصرف إليها به فلما رأت ما جاء به فرحت وزادته ولم يزل حتى أنست به فقال لها إنه ليس من ملك ولا ملكة إلا وقد ينبغي له أن يتخذ نفقا يهرب إليه عند حدوث حادثة يخافها فقالت أما أني قد فعلت واتخذت نفقا تحت سريري هذا يخرج إلى نفق تحت سرير أختي وأرته إياه فأظهر لها سرورا بذلك وخرج في تجارته كما كان يفعل وعرف عمرو بن عدي ما فعله فركب عمرو في ألفي دارع على ألف بعير في الجوالق حتى إذا صاروا إليها تقدم قصير يسبق الإبل ودخل على الزباء فقال لها اصعدي في حائط مدينتك فانظري إلى مالك وتقدمي إلى بوابك فلا يعرض لشيء من أعكامنا فإني قد جئت بمال صامت وقد كانت أمنته فلم تكن تتهمه ولا تخافه\nفصعدت كما أمرها فلما نظرت إلى ثقل مشي الجمال قالت وقيل إنه مصنوع منسوب إليها رجز\n(ما للجمال مشيها وئيدا ... أجندلا يحملن أم حديدا)\n(أم صرفانا باردا شديدا ... أم الرجال جثما قعودا)\nلما دخل آخر الجمال نخس البواب عكما من الأعجام بمنخسة معه فأصابت خاصرة رجل فضرط فقال البواب شر والله عكمتم به في الجوالقات فثاروا بأهل المدينة ضربا بالسيف فانصرفت راجعة فاستقبلها عمرو بن عدي فضربها فقتلها وقيل بل مصت خاتمها وقالت بيدي لا بيد عمرو وخربت المدينة وسبيت الذراري وغنم عمرو كل شيء كان لها ولأبيها وأختها وقال الشعراء في ذلك تذكر ما كان من قصير في مشورته على جذيمة وفي جدعه أنفه فأكثروا قال عدي بن زيد - وافر -\n(ألا يا أيها المثري المرجى ... ألم تسمع بخطب الأولينا)\n(دعا بالبقة الأمراء يوما ... جذيمة ينتحي عصبا ثبينا)\n(فطاوع أمرهم وعصى قصيرا ... وكان يقول لو سمع اليقينا)\nوهي طويلة وقال المتلمس يذكر جدع قصير أنفه - طويل -\n(ومن حذر الأيام ما حز أنفه ... قصير وخاض الموت بالسيف بيهس)\nكان جذيمة الملك شاعرا وإنما قيل له الوضاح لبرص كان به وكان يعظم أن يسمى بذلك فجعل مكانه الأبرش والوضاح وهو الذي يقول - مجزوء الكامل -\n(والملك كان لذي نواس ... حوله تردي يحابر)\n(بالسابغات وبالقنا ... والبيض تبرق والمغافر)\n(أزمان لا ملك يجير ... ولا ذمام لمن يجاور)\n(أودى بهم غير الزمان ... فمنجد منهم وغائر)","topic":"ذكر متمم وأخباره وخبر مالك ومقتله","topicNo":190,"sp":8,"spl":"رجع الحديث إلى سياقه"},
{"id":"b190-11","bab":"الجزء 15","sec":"رجع الحديث إلى سياقه","page":"ج15 ص305","text":"هو الذي يقول - مديد -\n(ربما أوفيت في علم ... ترفعن ثوبي شمالات)\n(في شباب أنا رابئهم ... هم لذي العورة صمات)\n(ليت شعري ما أطاف بهم ... نحن أدلجنا وهم باتوا)\n(ثم أبنا غانمين وكم ... كر ناس قبلنا ماتوا)\nيه غناء يقال إنه ليمان ويقال إنه لمعبد ولم يصح","topic":"ذكر متمم وأخباره وخبر مالك ومقتله","topicNo":190,"sp":9,"spl":"رجع الحديث إلى سياقه"},
{"id":"b191-1","bab":"الجزء 15","sec":"صوت بسيط","page":"ج15 ص312","text":"(في كفه خيزران ريحه عبق ... من كف أروع في عرنينه شمم)\n(يغضي حياء ويغضى من مهابته ... فما يكلم4 إلا حين يبتسم)\nلشعر لحزين بن سليمان الديلي والغناء لإسحاق ثاني ثقيل بالبنصر عن حبش وفيه لعريب رمل عمله على لحن ابن سريج\n21 -","topic":"أخبار الحزين ونسبه","topicNo":191,"sp":0,"spl":"صوت بسيط — أخبار الحزين ونسبه"},
{"id":"b191-2","bab":"الجزء 15","sec":"أخبار الحزين ونسبه","page":"ج15 ص313","text":"ذكر الواقدي أنه من كنانة وأنه صليبة وأن الحزين لقب غلب عليه وأن اسمه عمرو بن عبيد بن وهيب بن مالك ويكنى أبا الشعثاء بن حريث بن جابر بن بجير وهو راعي الشمس الأكبر بن يعمر بن عدي بن الديل بن بكر بن عبد مناة بن كنانة أخبرني بذلك أحمد بن عبد العزيز عن عمر بن شبة عن الواقدي قال وأما عمر بن شبة فإنه ذكر أن الحزين مولى وأنه الحزين بن سليمان ويكنى سليمان أبا الشعثاء ويكنى الحزين أبا الحكم من شعراء الدولة الأموية حجازي مطبوع ليس من فحول طبقته وكان هجاء خبيث اللسان ساقطا يرضيه اليسير ويتكسب بالشر وهجاء الناس وليس ممن خدم الخلفاء ولا انتجعهم بمدح ولا كان يريم الحجاز حتى مات وهذا الشعر يقوله الحزين في عبد الله بن عبد الملك بن مروان وكان\nعبد الله من فتيان بني أمية وظرفائهم وكان حسن الوجه حسن المذهب وأمه أم ولد وزوجة عبد الله رملة بنت عبد الله بن عبد الله وعبد الله هذا هو عبد الحجر بن عبد المدان بن الديان بن قطن بن زياد بن الحارث بن مالك بن ربيعة بن كعب بن الحارث بن عمرو وزوجته هند بنت أبي عبيدة بن عبد الله بن ربيعة بن الأسود بن مطلب بن أسد بن عبد العزى بن قصي تزوجها لما كان يقال إنها ناتق في ولادها فمات عنها ولم تلد له فخلفه محمد بن علي بن عبد الله بن العباس على رملة فولدت له محمدا وإبراهيم وموسى وبنات أخبرني بذلك عمر بن عبد الله بن جميل العتكي وأحمد بن عبد العزيز الجوهري ويحيى بن علي بن يحيى قالوا حدثنا عمر بن شبة عن ابن رواحة وغيره وأخبرني به الطوسي والحرمي عن الزبير عن عمه أخبرني حبيب بن نصر المهلبي قال حدثني الزبير قال حدثني عمي أن عبد الله بن عبد الملك حج فقال له أبوه سيأتيك الحزين الشاعر بالمدينة وهو ذرب اللسان فإياك أن تحتجب عنه وأرضه وصفته أنه أشعر ذو بطن عظيم الأنف فلما قدم عبد الله المدينة وصفه لحاجبه وقال له إياك أن ترده فلم يأت الحزين حتى قام فدخل لينام فقال له الحاجب قد ارتفع فلما ولى ذكر فلحقه فقال ارجع فاستأذن له فأدخله فلما صار بين يديه ورأى جماله وبهاءه وفي يده قضيب خيزران وقف ساكتا فأمهله عبد الله حتى ظن أنه قد أراح ثم قال له السلام رحمك الله أولا فقال عليك السلام وحيا الله وجهك أيها الأمير إني قد كنت مدحتك بشعر فلما دخلت عليك ورأيت جمالك وبهاءك أذهلني عنه فأنسيت ما كنت قلته وقد قلت في مقامي هذا بيتين فقال ما هما قال - بسيط\n(في كفه خيزران ريحها عبق ... من كف أروع في عرنينه شمم)\n(يغضي حياء ويغضى من مهابته ... فما يكلم إلا حين يبتسم)\nأجازه فقال أخدمني أصلحك الله فإنه لا خادم لي فقال اختر أحد هذين الغلامين فأخذ أحدهما فقال له عبد الله أعلينا ترذل خذ الأكبر والناس يروون هذين البيتين للفرزدق في أبياته التي يمدح بها علي بن الحسين بن أبي طالب عليه السلام التي أولها - بسيط -\n(هذا الذي تعرف البطحاء وطأته ... والبيت يعرفه والحل والحرم)\nوهو غلط ممن رواه فيها وليس هذان البيتان مما يمدح به مثل علي بن الحسين عليهما السلام وله من الفضل المتعالم ما ليس لأحد حدثني محمد بن محمد بن سليمان الباغندي قال حدثني محمد بن عمر العدني قال حدثني سفيان بن عيينة عن الزهري قال ما رأيت هاشميا أفضل من علي بن الحسين حدثني محمد قال حدثنا يوسف بن موسى القطان قال حدثنا جرير بن المغيرة قال كان علي بن الحسين يبخل فلما مات وجدوه يعول مائة أهل بيت بالمدينة حدثني الحسن بن علي قال حدثني محمد بن معرس قال حدثنا محمد ابن ميمون قال حدثنا سفيان عن ابن أبي حمزة الثمالي قال كان علي بن الحسين يحمل جراب الخبز على ظهره فيتصدق به ويقول إن صدقة الليل تطفئ غضب الرب حدثني أبو عبد الله الصيرفي قال حدثنا الفضل بن الحسين المصري قال","topic":"أخبار الحزين ونسبه","topicNo":191,"sp":0,"spl":"صوت بسيط — أخبار الحزين ونسبه"},
{"id":"b191-3","bab":"الجزء 15","sec":"أخبار الحزين ونسبه","page":"ج15 ص313","text":"حدثنا أحمد بن سليمان قال حدثنا ابن عائشة قال حدثنا سعد بن عامر عن جويرية بن أسماء عن نافع قال قال علي بن الحسين ما أكلت بقرابتي من رسول الله شيئا قط حدثنا الحسن بن علي قال حدثني عبد الله بن أحمد بن حنبل قال حدثني إسحاق بن موسى الأنصاري قال حدثنا يونس بن بكير عن محمد بن إسحاق قال كان ناس من أهل المدينة يعيشون ما يدرون من أين عيشهم فلما مات علي بن الحسين فقدوا ما كانوا يؤتون به بالليل وأما الأبيات التي مدح بها الفزردق علي بن الحسين وخبره فيها فحدثني بها أحمد بن محمد بن الجعد ومحمد بن يحيى قالا حدثنا محمد بن زكريا الغلابي قال حدثنا ابن عائشة قال حج هشام بن عبد الملك في خلافة الوليد أخيه ومعه رؤساء أهل الشام فجهد أن يستلم الحجر فلم يقدر من ازدحام الناس فنصب له منبر فجلس عليه ينظر إلى الناس وأقبل علي بن الحسين وهو أحسن الناس وجها وأنظفهم ثوبا وأطيبهم رائحة فطاف بالبيت فلما بلغ الحجر الأسود تنحى الناس كلهم وأخلوا له الحجر ليستلمه هيبة وإجلالا له فغاظ ذلك هشاما وبلغ منه فقال رجل لهشام من هذا أصلح الله الأمير قال لا أعرفه وكان به عارفا ولكنه خاف أن يرغب فيه أهل الشام ويسمعوا منه فقال الفرزدق وكان لذلك كله حاضرا أنا أعرفه فسلني يا شامي قال ومن هو قال - بسيط -\n(هذا الذي تعرف البطحاء وطأته ... والبيت يعرفه والحل والحرم)\n(هذا ابن خير عباد الله كلهم ... هذا التقي النقي الطاهر العلم)\n(إذا رأته قريش قال قائلها ... إلى مكارم هذا ينتهي الكرم)\n(يكاد يمسكه عرفان راحته ... ركن الحطيم إذا ما جاء يستلم)\n(فليس قولك من هذا بضائره ... العرب تعرف من أنكرت والعجم)\n(أي الخلائق ليست في رقابهم ... لأولية هذا أو له نعم)\n(من يعرف الله يعرف أولية ذا ... فالدين من بيت هذا ناله الأمم)\nحبسه هشام فقال الفرزدق - طويل -\n(أيحبسني بين المدينة والتي ... إليها قلوب الناس يهوي منيبها)\n(يقلب رأسا لم يكن رأس سيد ... وعينا له حولاء باد عيوبها)\nبعث إليه هشام فأخرجه ووجه إليه علي بن الحسين عشرة آلاف درهم وقال اعذر يا أبا فراس فلو كان عندنا في هذا الوقت أكثر من هذا لوصلناك به فردها وقال ما قلت ما كان إلا لله وما كنت لأرزأ عليه شيئا فقال له علي قد رأى الله مكانك فشكرك ولكنا أهل بيت إذا أنفذنا شيئا ما نرجع فيه فأقسم عليه فقبلها ومن الناس أيضا من يروي هذه الأبيات لداود بن سلم في قثم بن العباس ومنهم من يرويها لخالد بن يزيد فيه فهي في روايته - بسيط -\n(كم صارخ بك من راج وراجية ... يرجوك يا قثم الخيرات يا قثم)\n(أي العمائر ليست في رقابهم ... لأولية هذا أو له نعم)\n(في كفه خيزران ريحها عبق ... من كف أروع في عرنينه شمم)\n(يغضي حياء ويغضى من مهابته ... فما يكلم إلا حين يبتسم)\nوممن ذكر لنا ذلك الصولي عن الغلابي عن مهدي بن سابق أن داود بن سلم قال هذه الأبيات الأربعة سوى البيت الأول في شعره في علي بن الحسين عليه السلام وذكر الرياشي عن الأصمعي أن رجلا من العرب يقال له داود وقف لقثم\nفناداه وقال - بسيط -\n(يكاد يمسكه عرفان راحته ... ركن الحطيم إذا ما جاء يستلم)\n(كما صارخ بك من راج وراجية ... في الناس يا قثم الخيرات يا قثم)\nأمر له بجائزة سنية والصحيح أنها للحزين في عبد الله بن عبد الملك وقد غلط ابن عائشة في إدخاله البيتين في تلك الأبيات وأبيات الحزين مؤتلفة منتظمة المعاني متشابهة تنبئ عن نفسها وهي - بسيط -\n(الله يعلم أن قد جبت ذا يمن ... ثم العراقين لا يثنيني السأم)\n(ثم الجزيرة أعلاها وأسفلها ... كذاك تسري على الأهوال بي القدم)\n(ثم المواسم قد أوطنتها زمنا ... وحيث تحلق عند الجمرة اللمم)\n(قالوا دمشق ينبيك الخبير بها ... ثم ائت مصر فثم النائل العمم)\n(لما وقفت عليها في الجموع ضحى ... وقد تعرضت الحجاب والخدم)\n(حييته بسلام وهو مرتفق ... وضجة القوم عند الباب تزدحم)\n(في كفه خيزران ريحها عبق ... من كف أروع في عرنينه شمم)\n(يغضي حياء ويغضى من مهابته ... فما يكلم إلا حين يبتسم)\n(ترى رؤوس بني مروان خاضعة ... يمشون حول ركابيه وما ظلموا)\n(إن هش هشوا له واستبشروا جذلا ... وإن هم آنسوا إعراضه وجموا)\n(كلتا يديه ربيع عند ذي خلف ... بحر يفيض وهادي عارض هزم)\nمن الناس من يقول إن الحزين قالها في عبد العزيز بن مروان لذكره","topic":"أخبار الحزين ونسبه","topicNo":191,"sp":1,"spl":"أخبار الحزين ونسبه"}]);
window.__BOOK__['p08'].push([{"id":"b191-4","bab":"الجزء 15","sec":"أخبار الحزين ونسبه","page":"ج15 ص313","text":"دمشق ومصر وقد كان ثم عبد الله بن عبد الملك أيضا في مصر والحزين بها أخبرني الحرمي قال حدثنا الزبير قال حدثني محمد بن يحيى أبو غسان عن عبد العزيز بن عمران الزهري قال وفد الحزين على عبد الله بن عبد الملك وفي الرقيق أخوان فقال عبد الله للحزين أي الرقيق أعجب إليك قال ليختر لي الأمير قال عبد الله قد رضيت لك هذا لأحدهما فإني رأيته حسن الصلاح قال الحزين لا حاجة لي به فأعطني أخاه فأعطاه إياه قال والغلامان مزاحم مولى عمر بن عبد العزيز وتميم أبو محمد بن تميم وهو الذي اختاره الحزين قال فقال في عبد الله يمدحه - بسيط -\n(الله يعلم أن قد حييت ذا يمن ... )\nذكر القصيدة بطولها على هذا السبيل أخبرني وكيع عن محمد بن علي بن حمزة العلوي قال حدثنا أبو غسان دماذ عن أبي عبيدة قال كان على المدينة طائف يقال له صفوان مولى لآل محرمة بن نوفل فجاء الحزين الديلي إلى شيخ من أهل المدينة فاستعاره حماره وذهب إلى العقيق فشرب وأقبل على الحمار وقد سكر فجاء به الحمار حتى وقف به على باب المسجد كما كان صاحبه عوده إياه فمر به صفوان فأخذه فحبسه وحبس الحمار فأصبح والحمار محبوس معه فأنشأ يقول - وافر -\n(أيا أهل المدينة خبروني ... بأي جريرة حبس الحمار)\n(فما للعير من جرم إليكم ... وما بالعير إن ظلم انتصار)\nردوا الحمار على صاحبه وضربوا الحزين الحد فأقبل إلى مولى صفوان وهو في المسجد فقال - طويل\n(نشدتك بالبيت الذي طيف حوله ... وزمزم والبيت الحرام المحجب)\n(لزانية صفوان أم لعفيفة ... لأعلم ما آتي وما أتجنب)\nفقال مولاه هو لزانية فخرج وهو ينادي إن صفوان ابن الزانية فتعلق به صفوان فقال هذا مولاك يشهد أنك ابن زانية فخلى عنه وقال محمد بن علي بن حمزة وأخبرني الرياشي أن ابن عم للحزين استشاره في امرأة يتزوجها فقال له إن لها إخوة مشائيم وقد ردوا عنها غير واحد وأخشى أن يردوك فتطلق عليك ألسنا كانت عنك خرسا فخطبها ولم يقبل منه فردوه فقتال الحزين - طويل -\n(نهيتك عن أمر فلم تقبل النهى ... وحذرتك اليوم الغواة الأشائما)\n(فصرت إلى ما لم أكن منه آمنا ... وأشمت أعدائي وأنطقت لائما)\n(وما بهم من رغبة عنك قل لهم ... فإن تسألوني تسألوا بي عالما)\nسخت من كتاب لعلي بن محمد الشامي حدثني أبو محلم ولم يتجاوزه وأخبرني عيسى بن الحسن قال حدثنا سليمان بن أبي شيخ قال حدثني عمر بن سلام مولى عمر بن الجعاب أن الحزين الديلي خرج مع ابن لسهيل بن عبد الرحمن بن عوف إلى منتزه لهم فسكر الحزين وانصرف فبات في الطريق وسلب ثيابه فأرسل إلى سهيل يخبره الخبر ويستمنحه فلم يمنحه وبلغ الخبر سفيان بن عاصم بن عبد العزيز بن مروان فأرسل إليه بجميع ما يحتاج إليه وعوضه ثمن ثيابه فقال الحزين في ذلك - منسرح -\n(هلا سهيلا أشبهت أو بعض أعمامك ... يا ذا الخلائق الشكسه)\n(ضيعت ندمانك الكريم ولم ... تشفق عليه من ليلة نحسه)\n(ثم تعاللت إذ أتاك له ... صبحا رسول بعلة طفسه)\n(لكن سفيان لم يكن وكلا ... لما أتتنا صلاته سلسه)\n(سما به أروع ونفس فتى ... أروع ليست كنفسك الدنسه)\nدثنا الصولي قال حدثنا ثعلب قال حدثني عبد الله بن شبيب قال مر الحزين الديلي على مجلس لبني كعب بن خزاعة وهو سكران فضحكوا عليه فوقف عليهم وقال - بسيط -\n(لا بارك الله في كعب ومجلسهم ... ماذا تجمع من لؤم ومن ضرع)\n(لا يدرسون كتاب الله بينهم ... ولا يصومون من حرص على الشبع)\nوثب إليه مشايخهم فاعتذروا منه وسألوه الكف وأن لا يزيد شيئا على ما قاله فأجابهم وانصرف أخبرني الحرمي قال حدثنا الزبير قال حدثنا عمرو بن أبي بكر المؤملي قال حدثني عبد الله بن أبي عبيدة قال كان الحزين قد ضرب على كل رجل من قريش درهمين درهمين في كل شهر منهم ابن أبي عتيق فجاءه لأخذ درهميه وهو على حمار أعجف قال وكثير مع ابن أبي عتيق فدعا ابن أبي عتيق للحزين بدرهمين فقال له الحزين من هذا معك قال هذا أبو صخر كثير بن أبي جمعة قال وكان قصيرا دميما فقال له الحزين أتأذن لي أن أهجوه ببيت قال لا لعمري لا آذن لك أن تهجو جليسي ولكن أشتري عرضه منك بدرهمين","topic":"أخبار الحزين ونسبه","topicNo":191,"sp":2,"spl":"أخبار الحزين ونسبه","partial":1},
{"id":"b191-5","bab":"الجزء 15","sec":"أخبار الحزين ونسبه","page":"ج15 ص313","text":"آخرين ودعا له بهما فأصغى ثم قال لا بد لي من هجائه ببيت قال أو أشتري ذلك منك بدرهمين آخرين ودعا له بهما فأخذهما وقال ما أنا بتاركه حتى أهجوه قال أو أشتري ذلك منك بدرهمين آخرين فقال له كثير ائذن له وما عسى أن يقول في فأذن له ابن أبي عتيق فقال - طويل -\n(قصير القميص فاحش عند بيته ... يعض القراد باسته وهو قائم)\nوثب كثير إليه فوكزه فسقط هو والحمار وخلص ابن أبي عتيق بينهما وقال لكثير قبحك الله أتأذن له وتبسط إليه يدك قال كثير وأنا ظننته يبلغ في هذا كله في بيت واحد ولكثير مع الحزين أخبار أخر قد ذكرت في أخبار كثير أخبرني الحرمي قال حدثني عمي عن الضحاك بن عثمان قال حدثني ابن عروة بن أذينة قال كان الحزين صديقا لأبي وعشيرا على النبيذ وكان كثيرا ما يأتيه وكان بالمدينة قينة يهواها الحزين ويكثر غشيانها فبيعت وأخرجت عن المدينة فأتى الحزين أبي وهو كئيب حزين كاسمه فقال له أبي ما لك يا أبا حكيم قال أنا والله يا أبا عامر كما قال كثير - طويل -\n(لعمري لئن كان الفؤاد من الهوى ... بغى سقما إني إذا لسقيم)\n(سألت حكيما أين شطت بها النوى ... فخبرني ما لا أحب حكيم)\nقال له أبي أنت مجنون إن أقمت على هذا أخبرني أحمد بن سليمان الطوسي قال حدثنا الزبير قال حدثني مصعب قال مر الحزين على جعفر بن محمد بن عبد الله بن نوفل بن الحارث وعليه\nأطمار فقال له يا ابن أبي الشعثاء إلى أين أصبحت غاديا قال أمتع الله بك نزل عبد الله بن عبد الملك الحرة يريد الحج وقد كنت وفدت إليه بمصر فأحسن إلي قال أفما وجدت شيئا تلبسه غير هذه الثياب قال قد استعرت من أهل المدينة فلم يعرني أحد منهم غير هذه الثياب فدعا جعفر غلاما فقال ائتني بجبة صوف وقميص ورداء فجاءه بذلك فقال أبل وأخلق فلما ولى الحزين قال جلساء جعفر له ما صنعت إنه يعمد إلى هذه الثياب التي كسوته إياها فيبيعها ويفسد بثمنها قال ما أبالي إذا كافأته بثيابه ما صنع بها فسمع الحزين قولهم وما رد عليهم ومضى حتى أتى عبد الله بن عبد الملك فأحسن إليه وكساه فلما أصبح الحزين أتى جعفرا ومعه القوم الذين لاموه بالأمس وأنشده - طويل -\n(وما زال ينمو جعفر بن محمد ... إلى المجد حتى عبهلته عواذله)\n(وقلن له هل من طريف وتالد ... من المال إلا أنت في الحق باذله)\n(يحاولنه عن شيمة قد علمنها ... وفي نفسه أمر كريم يحاوله)\nم قال له بأبي أنت وأمي سمعت ما قالوا وما رددت عليهم أخبرني الحرمي قال حدثنا الزبير قال حدثني محمد بن الضحاك عن أبيه قال صحب الحزين رجلا من بني عامر بن لؤي يلقب أبا بعرة وكان استعمل على سعايات فلم يصنع إليه خيرا وكان قد صحب قبله عمرو بن مساحق وسعد بن نوفل فأحمدهما فقال له - طويل\n(صحبتك عاما بعد سعد بن نوفل ... وعمرو فما أشبهت سعدا ولا عمرا)\n(وجادا كما قصرت في طلب العلا ... فحزت به ذما وحازا به شكرا)\nال وأبو بعرة هذا هو الذي كان يعبث بجارية لابن أبي عتيق فشكته إليه فقال لها عديه فإذا جاءك فأدخليه إلي ففعلت فأدخلته عليه وهو وشيخ من نظرائه جالسان في حجلة فلما رآهما قال أقسم بالله ما اجتمعتما إلا على ريبة فقال له ابن أبي عتيق استر علينا ستر الله عليك قال وآل أبي بعرة هم موالي آل أبي سمير قال فلما ولي المهدي باعوا ولاءهم منه قال الزبير وأنشدني عمي تمام الأبيات التي هجا بها أبا بعرة وسماه لي فقال وكان اسمه عيسى وهي - طويل -\n(أولاك الجعاد البيض من آل مالك ... وأنتم بنو قين لحقتم به نزرا)\nصب نزرا على الحال كأنه قال لحقتم به نزرا قليلا من الرجال\n(نسوق بيعورا أميرا كأنما ... نسوق به في كل مجمعة وبرا)\n(فإن يكن البيعور ذم رفيقه ... قراه فقد كانت إمارته نكرا)\n(ومتبع البيعور يرجو نواله ... فقد زاده البيعور في فقره فقرا)\nخبرني الحرمي قال حدثني الزبير قال حدثني صالح عن عامر بن صالح قال مدح الحزين عمرو بن عمرو بن الزبير فلم يعطه شيئا وأخبرني بهذا الخبر عمي تاما واللفظ له ولم يذكر الزبير منه إلا يسيرا قال حدثنا الكراني قال حدثنا العمري قال حدثني عطاء بن مصعب عن","topic":"أخبار الحزين ونسبه","topicNo":191,"sp":3,"spl":"أخبار الحزين ونسبه"},
{"id":"b191-6","bab":"الجزء 15","sec":"أخبار الحزين ونسبه","page":"ج15 ص313","text":"عاصم بن الحدثان قال دخل الحزين على عمرو بن عمرو بن الزبير بن العوام منزله فامتدحه وسأله حاجة فقال له ليس إلى ما تطلب سبيل ولا نقدر أن نملأ الناس معاذير وما كل من سألنا حاجة استحق أن نقضيها ولرب مستحق لها قد منعناه حاجته فقال الحزين أفمن المستحقين أنا قال لا والله وكيف تكون مستحقا لشيء من الخير وأنت تشتم أعراض الناس وتهتك حريمهم وترميهم بالمعضلات إنما المستحق من كف أذاه وبذل نداه ووقم أعداه فقال له الحزين أفمن هؤلاء أنت فقال له عمرو أين تبعدني لا أم لك من هذه المنزلة وأفضل منها فوثب الحزين من عنده وأنشأ يقول - وافر -\n(حلفت وما صبرت على يمين ... ولو أدعى إلى أيمان صبر)\n(برب الراقصات بشعث قوم ... يوافون الجمار لصبح عشر)\n(لو ان اللؤم كان مع الثريا ... لكان حليفه عمرو بن عمرو)\n(ولو أني عرفت بأن عمرا ... حليف اللؤم ما ضيعت شعري)\nفقال العمري وحدثني لقيط أن الحزين قال فيه أيضا يهجوه ويمدح محمد بن مروان بن الحكم وجاءه فشكا إليه عمرا فوصله وأحسن إليه قال - طويل -\n(إذا لم يكن للمرء فضل يزينه ... سوى ما ادعى يوما فليس له فضل)\n(وتلقى الفتى ضخما جميلا رواؤه ... يروعك في النادي وليس له عقل)\n(وآخر تنبو العين عنه مهذب ... يجود إذا ما الضخم نهنهه البخل)\n(فيا راجيا عمرو بن عمرو وسيبه ... أتعرف عمرا أم أتاه بك الجهل)\n(فإن كنت ذا جهل فقد يخطئ الفتى ... وإن كنت ذا حزم إذا حارت النبل)\n(جهلت ابن عمرو فالتمس سيب غيره ... ودونك مرمى ليس في جده هزل)\n(عليك ابن مروان الأغر محمدا ... تجده كريما لا يطيش له نبل)\nال لقيط فلما أنشد الحزين محمد بن مروان هذا الشعر أمر له بخمسة آلاف درهم وقال له اكفف يا أخا بني ليث عن عمرو بن عمرو ولك حكمك فقال لا والله ولا بحمر النعم وسودها لو أعطيتها ما كففت عنه لأنه ما علمت كثير الشر قليل الخير متسلط على صديقه فظ على أهله وخير ابن عمرو بالثريا معلق فقال له محمد بن مروان هذا شعر فقال بعد ساعة يصير شعرا ولو شئت لعجلته ثم قال - طويل -\n(شر ابن عمروحاضر لصديقه ... وخير ابن عمرو بالثريا معلق)\n(ووجه ابن عمرو باسر إن طلبته ... نوالا إذا جاد الكريم الموفق)\n(فبئس الفتى عمرو بن عمرو إذا غدت ... كتائب هيجاء المنية تبرق)\n(فلا زال عمرو للبلايا درية ... تباكره حتى يموت وتطرق)\n(يهر هرير الكلب عمرو إذا رأى ... طعاما فما ينفك يبكي ويشهق)\nال فزجره محمد عنه وقال له أف لك قد أكثرت الهجاء وأبلغت في الشتيمة\nقال العمري وحدثني عطاء بن مصعب عن عبد الله بن الليث الليثي قال قال الحزين الديلي يهجو عمرو بن عمرو بن الزبير - طويل -\n(لعمرك ما عمرو بن عمرو بماجد ... ولكنه كز اليدين بخيل)\n(ينام عن التقوى ويوقظه الخنا ... فيخبط أثناء الظلام يجول)\n(فلا خير في عمرو لجار ولا له ... ذمام ولكن للئام وصول)\n(مواعيد عمرو ترهات ووجهه ... على كل ما قد قلت فيه دليل)\n(جبان وفحاش لئيم مذمم ... وأكذب خلق الله حين يقول)\n(كلام ابن عمرو صوفة وسط بلقع ... وكف ابن عمرو في الرخاء تطول)\n(وإن حزبته الحازبات تشنجت ... يداه ورمح في الهياج كليل)\nبلغ شعره عمرا فقال ما له لعنه الله ولعن من ولده لقد هجاني بنية صادقة ولسان صنع ذلق وما عداني إلى غيري قال فلقي الحزين عروة بن أذينة الليثي فأنشده هذه الأبيات فقال له ويحك بعضها كان يكفيك فقد بنيتها ولم تقم أودها وداخلتها وجعلت معانيها في أكمتها قال الحزين ذلك والله أرغب للناس فيها فقال له عروة خير الناس من حلم عن الجهال وما أراه إلا قد حلم عنك فقال الحزين حلم والله عني شاء أو أبى برغمه وصغره قال العمري فحدثنا عطاء عن عاصم بن الحدثان قال لقي شبان من ولد الزبير الحزين فتناولوه بألسنتهم وهموا بضربه فحال بينهم وبينه ابن لمصعب\nابن الزبير فقال الحزين يهجوهم ويهجو جماعة من بني أسد بن عبد العزى سوى بني مصعب الذين منعوهم منه قال - طويل -\n(لحا الله حيا من قريش تحالفوا ... على البخل بالمعروف والجود بالنكر)\n(فصاروا لخلق الله في اللؤم غاية ... بهم تضرب الأمثال في النثر والشعر)\n(فيا عمرو لو أشبهت عمرا ومصعبا ... حمدت ولكن أنت منقبض البشر)\n(بني أسد سادت قريش بجودها ... معدا وسادتكم معد يد الدهر)\n(تجود قريش بالندى ورضيتم ... بني أسد باللؤم والذل والغدر)","topic":"أخبار الحزين ونسبه","topicNo":191,"sp":4,"spl":"أخبار الحزين ونسبه"},
{"id":"b191-7","bab":"الجزء 15","sec":"أخبار الحزين ونسبه","page":"ج15 ص313","text":"(أعمرو بن عمرو لست ممن تعده ... قريش إذا ما كاثروا الناس بالفخر)\n(أبت لك يا عمرو بن عمرو دناءة ... وخلق لئيم أن تريش وأن تبري)\nخبرني الحرمي قال حدثنا الزبير قال حدثني محمد بن الضحاك الحزامي قال حدثني أبي قال كان الحزين سفيها نذلا يمدح بالنزر إذا أعطيه ويهجو على مثله إذا منع فنزل بعاصم بن عمرو بن عثمان فلم يقره فقال يهجوه بقوله - طويل -\n(سيروا فقد جن الظلام عليكم ... فباست الذي يرجو القرى عند عاصم)\n(ظللنا عليه وهو كالتيس طاعما ... نشد على أكبادنا بالعمائم)\n(وما لي من ذنب إليه علمته ... سوى أنني قد جئته غير صائم)\nقيل له إن عاصما كثيرا ما تسمي به قريش فقال أما والله لأبيننه لهم فقال - طويل\n(إليك ابن عثمان بن عفان عاصم بن ... عمرو سرت عنسي فخاب سراها)\n(فقد صادفت كز اليدين مبخلا ... جبانا إذا ما الحرب شب لظاها)\n(بخيلا بما في رحله غير أنه ... إذا ما خلت عرس الخليل أتاها)\nخبرني الحرمي قال حدثنا الزبير قال حدثني محمد بن الضحاك عن أبيه قال قال الحزين لهلال بن يحيى بن طلحة قوله - طويل -\n(هلال بن يحيى غرة لا خفا بها ... على الناس في عسر الزمان ولا اليسر)\n(وسعد بن إبراهيم ظفر موسخ ... فهل يستريح الناس من وسخ الظفر)\nيعني سعد بن إبراهيم بن عبد الرحمن بن عوف وكان ولي قضاء المدينة من هشام بن عبد الملك فلم يعط الحزين شيئا فهجاه وقال فيه أيضا - طويل -\n(أتيت هلالا أرتجي فضل سيبه ... فأفلتني مما أحب هلال)\n(هلال بن يحيى غرة لا خفا بها ... لكل أناس غرة وهلال)\nوت - طويل -\n(ألم تشهد الجونين والشعب ذا الصفا ... وكرات قيس يوم دير الجماجم)\n(تحرض يابن القين قيسا ليجعلوا ... لقومك يوما مثل يوم الأراقم)\n(بسيف أبي رغوان سيف مجاشع ... ضربت ولم تضرب بسيف ابن ظالم)\n(ضربت به عند الإمام فأرعشت ... يداك وقالوا محدث غير صارم)\nالشعر لجرير والغناء لابن محرز ثقيل أول بالبنصر وهذه الأبيات يقولها جرير يهجو الفرزدق ويعيره بضربة ضربها بسيفه رجلا من الروم فحضره سليمان بن عبد الملك فلم يصنع شيئا فحدثنا بخبره في ذلك محمد بن العباس اليزيدي قال حدثنا سليمان بن أبي شيخ قال حدثنا صالح بن سليمان عن إبراهيم بن جبلة بن مخرمة الكندي وكان شيخا كبيرا وكان من أصحاب عبد الملك بن مروان ثم كان من أصحاب المنصور قال كنت حاضرا سليمان بن عبد الملك وأخبرنا علي بن سليمان الأخفش واليزيدي عن السكري عن محمد بن حبيب عن أبي عبيدة وعن قتادة عن أبي عبيدة في كتاب النقائض عن رؤبة بن العجاج قال حج سليمان بن عبد الملك ومعه الشعراء وحججت معهم فمر بالمدينة منصرفا فأتي بأسرى من الروم نحو من أربعمائة فقعد سليمان وعنده عبد الله بن الحسن بن الحسن بن علي عليهم السلام وعليه ثوبان ممصران وهو أقربهم منه مجلسا فأدنوا إليه بطريقهم وهو في جامعة فقال لعبد الله بن الحسن قم فاضرب عنقه فقام فما أعطاه أحد سيفا حتى دفع إليه حرسي سيفا كليلا فضربه فأبان عنقه وذراعه وأطن ساعده وبعض الغل فقال له سليمان اجلس فوالله ما ضربته بسيفك ولكن بحسبك وجعل يدفع الأسرى إلى\nالوجوه وإلى الناس فيقتلونهم حتى دفع إلى جرير رجلا فدست إليه بنو عبس سيفا قاطعا في قراب أبيض فضربه فأبان رأسه ودفع إلى الفرزدق أسيرا فدست إليه القيسية سيفا كليلا فضرب به الأسير ضربات فلم يصنع شيئا فضحك سليمان وضحك الناس معه هذه رواية أبي عبيدة عن رؤبة وأما سليمان بن أبي شيخ فإنه ذكر في خبره أن سليمان لما دفع إليه الأسير دفع إليه سيفا وقال له اقتله به فقال لا بل أضربه بسيف مجاشع واخترط سيفه فضربه به فلم يغن شيئا فقال له سليمان أما والله لقد بقي عليك عارها وشنارها فقال جرير قصيدته التي يهجوه فيها ومنها الصوت المذكور وأولها قوله - طويل -\n(ألا حي ربع المنزل المتقادم ... وما حل مذ حلت به أم سالم)\nهي طويلة فقال الفرزدق صوت - طويل -\n(فهل ضربة الرومي جاعلة لكم ... أبا عن كليب أو أبا مثل دارم)\n(كذاك سيوف الهند تنبو ظباتها ... وتقطع أحيانا مناط التمائم)\n(ولا نقتل الأسرى ولكن نفكهم ... إذا أثقل الأعناق حمل المغارم)\nكر يونس أن في هذه الأبيات لحنا لابن محرز ولم يجنسه وقال يعرض بسليمان ويعيره بنبو سيف ورقاء بن زهير العبسي عن خالد بن جعفر وبنو عبس أخوال سليمان قال - طويل","topic":"أخبار الحزين ونسبه","topicNo":191,"sp":5,"spl":"أخبار الحزين ونسبه"},
{"id":"b191-8","bab":"الجزء 15","sec":"أخبار الحزين ونسبه","page":"ج15 ص313","text":"(فإن يك سيف خان أو قدر أتى ... بتعجيل نفس حتفها غير شاهد)\n(فسيف بني عبس وقد ضربوا به ... نبا بيدي ورقاء عن رأس خالد)\n(كذاك سيوف الهند تنبو ظباتها ... وتقطع أحيانا مناط القلائد)\nروي هذا الخبر عن عوانة بن الحكم قال فيه إن الفرزدق قال لسليمان يا أمير المؤمنين هب لي هذا الأسير فوهبه له فأعتقه وقال الأبيات التي تقدم ذكرها ثم أقبل على رواته وأصحابه فقال كأني بابن المراغة وقد بلغه خبري فقال - طويل -\n(بسيف أبي رغوان سيف مجاشع ... ضربت ولم تضرب بسيف ابن ظالم)\n(ضربت به عند الإمام فأرعشت ... يداك وقالوا محدث غير صارم)\nال فما لبثنا غير مدة يسيرة حتى جاءتنا القصيدة وفيها هذان البيتان فعجبنا من فطنة الفرزدق وأخبرني بهذا الخبر محمد بن خلف وكيع قال حدثنا محمد بن عيسى بن حمزة العلوي قال حدثنا أبو عثمان المازني قال زعم جهم بن خلف أن رؤبة بن العجاج حدثه فذكر هذه القصيدة وزاد فيها قال واستوهب الفرزدق الأسير فوهبه له سليمان فأعتقه وكساه وقال قصيدته التي يقول فيها - طويل -\n(ولا نقتل الأسرى ولكن نفكهم ... إذا أثقل الأعناق حمل المغارم)\nال وقال في ذلك - طويل\n(تباشر يربوع بنبوة ضربة ... ضربت بها بين الطلا والحراقد)\n(ولو شئت قد السيف ما بين عنقه ... إلى علق بين الحجابين جامد)\n(فإن ينب سيف أو تراخت منية ... لميقات نفس حتفها غير شاهد)\n(فسيف بني عبس وقد ضربوا به ... نبا بيدي ورقاء عن رأس خالد)\nقال وقال في ذلك - بسيط -\n(أيضحك الناس أن أضحكت سيدهم ... خليفة الله يستسقى به المطر)\n(فما نبا السيف عن جبن ولا دهش ... عند الإمام ولكن أخر القدر)\n(ولو ضربت به عمرا مقلده ... لخر جثمانه ما فوقه شعر)\n(وما يقدم نفسا قبل ميتتها ... جمع اليدين ولا الصمصامة الذكر)\nأما يوم الجونين الذي ذكره جرير فهو اليوم الذي أغار فيه عتيبة بن الحارث بن شهاب على بني كلاب وهو يوم الرغام أخبرني بخبره علي بن سليمان الأخفش ومحمد بن العباس اليزيدي عن السكري عن ابن حبيب ودماذ عن أبي عبيدة وعن إبراهيم بن سعدان عن أبيه أن عتيبة بن الحارث بن شهاب أغار في بني ثعلبة بن يربوع على طوائف من بني كلاب يوم الجونين فاطرد إبلهم وكان أنس بن العباس الأصم أخو بني رعل من بني سليم مجاورا في بني كلاب وكان بين بني ثعلبة بن يربوع وبين بني رعل عهد لا يسفك دم ولا يؤكل مال فلما سمع الكلابيون الدعوى يال ثعلبة يال\nعبيد يال جعفر عرفوهم فقالوا لأنس بن العباس قد عرفنا ما بين بني رعل وبني ثعلبة بن يربوع فأدركهم فاحبسهم علينا حتى نلحق فخرج أنس في آثارهم حتى أدركهم فلما دنا منهم قال عتيبة بن الحارث لأخيه حنظلة أغن عنا هذا الفارس فاستقبله حنظلة فقال له أنس إنما أنا أخوكم وعقيدكم وكنت في هؤلاء القوم فأغرتم على إبلي فيما أغرتم عليه وهو معكم فرجع حنظلة إلى أخيه فأخبره الخبر فقال له حياك الله وهلم فوال إبلك أي اعزلها قال والله ما أعرفها وبنو أخي وأهل بيتي معي وقد أمرتهم بالركوب في أثري وهم أعرف بها مني فطلع فوارس بني كلاب فاستقبلهم حنظلة بن الحارث في فوارس فقال لهم أنس إنما هم بني وبنو أخي وإنما يربثهم لتلحق فوارس بني كلاب فلحقوا فحمل الحوثرة بن قيس بن جزء بن خالد بن جعفر على حنظلة فقتله وحمل لأم ابن سلمة أخو بني ضبارى بن عبيد بن ثعلبة على الحوثرة هو وابن مزنة أخو بني عاصم بن عبيد فأسراه ودفعاه إلى عتيبة فقتله صبرا وهزم الكلابيون ومضى بنو ثعلبة بالإبل وفيها إبل أنس فلم تقر أنسا نفسه حتى اتبعهم رجاء أن يصيب منهم غرة وهم يسيرون في شجراء فتخلف عتيبة لقضاء حاجته وأمسك برأس فرسه فلم يشعر إلا بأنس قد مر في آثارهم فتقدم حتى وثب عليه فأسره فأتى به عتيبة أصحابه فقال بنو عبيدة قد عرفنا أن لأم بن سلمة وابن مزنة قد أسرا الحوثرة فدفعاه إليك فضربت عنقه فأعقبهما في أنس بن عباس فمن قتلته خير من أنس فأبى عتيبة أن يفعل ذلك حتى افتدى أنس نفسه بمائتي بعير فقال العباس بن مرداس يعير عتيبة بن الحارث بفعله - كامل\n(كثر الضجاج وما سمعت بغادر ... كعتيبة بن الحارث بن شهاب)\n(جللت حنظلة المخانة والخنا ... ودنست آخر هذه الأحقاب)\n(وأسرتم أنسا فما حاولتم ... بإسار جاركم بني الميقاب)\nلميقاب التي تلد الحمقى والوقب الأحمق","topic":"أخبار الحزين ونسبه","topicNo":191,"sp":6,"spl":"أخبار الحزين ونسبه"},
{"id":"b191-9","bab":"الجزء 15","sec":"أخبار الحزين ونسبه","page":"ج15 ص313","text":"(باست التي ولدتك واست معاشر ... تركوك تحرسهم من الأحساب)\nقال عتيبة بن الحارث - وافر -\n(غدرتم غدرة وغدرت أخرى ... فليس إلى توافينا سبيل)\n(كأنكم غداة بني كلاب ... تفاقدتم علي لكم دليل)\nوله تفاقدتم دعاء عليهم أن يفقد بعضهم بعضا صوت - طويل -\n(وبالعفر دار من جميلة هيجت ... سوالف حب في فؤادك منصب)\n(وكنت إذا ناءت بها غربة النوى ... شديد القوى لم تدر ما قول مشغب)\n(كريمة حر الوجه لم تدع هالكا ... من القوم هلكا في غد غير معقب)\n(أسيلة مجرى الدمع خمصانة الحشا ... بروق الثنايا ذات خلق مشرعب)\nلعفر منازل لقيس بالعالية سوالف مواض يقول هيجت حبا قد كان ثم انقطع ومنصب ذو نصب ونأت وناءت وبانت بمعنى واحد أي بعدت ومشغب ذو شغب عليك وخلاف في حبها ويروى مشعب أي متعدد\nيصرفك عنها وقوله لم تدع هالكا أي لم تندب هالكا هلك فلم يخلف غيره ولم يعقب ومعنى ذلك أنها في عدد وقوم يخلف بعضهم بعضا في المكارم لا كمن إذا مات سيد قومها أو كريم منهم لم يقم أحد منهم مقامه والمشرعب الجسيم الطويل والشرعبي الطويل الشعر لطفيل الغنوي والغناء لجميلة ثقيل أول بالوسطى عن الهشامي وذكره حماد عن أبيه لها ولم يجنسه وروى إسحاق عن أبيه عن سياط عن يونس أن هذا أحسن صوت صنعته جميلة","topic":"أخبار الحزين ونسبه","topicNo":191,"sp":7,"spl":"أخبار الحزين ونسبه"},
{"id":"b192-1","bab":"الجزء 15","sec":"نسب الطفيل الغنوي وأخباره","page":"ج15 ص337","text":"قال ابن الكلبي هو طفيل بن عوف بن كعب بن خلف بن ضبيس بن خليف بن مالك بن سعد بن عوف بن كعب بن غنم بن غني بن أعصر بن سعد بن قيس بن عيلان ووافقه ابن حبيب في النسب إلا في خلف بن ضبيس فإنه لم يذكر خلفا وقال هو طفيل بن عوف بن ضبيس قال أبو عبيدة اسم غني عمرو واسم أعصر منبه وإنما سمي أعصر لقوله - كامل -\n(قالت عميرة ما لرأسك بعد ما ... فقد الشباب أتى بلون منكر)\n(أعمير إن أباك غير رأسه ... مر الليالي واختلاف الأعصر)\nسمي بذلك وطفيل شاعر جاهلي من الفحول المعدودين ويكنى أبا قران يقال إنه من أقدم شعراء قيس وهو من أوصف العرب للخيل\nأخبرني هاشم بن محمد بن هارون بن عبد الله بن مالك أبو دلف الخزاعي قال حدثنا عبد الرحمن بن عبد الله بن قريب الأنصاري قال قال لي عمي إن رجلا من العرب سمع الناس يتذاكرون الخيل ومعرفتها والبصر بها فقال كان يقال إن طفيلا ركب الخيل ووليها لأهله وإن أبا دواد الأيادي ملكها لنفسه ووليها لغيره كان يليها للملوك وأن النابغة الجعدي لما أسلم الناس وآمنوا اجتمعوا وتحدثوا ووصفوا الخيل فسمع ما قالوه فأضافه إلى ما كان سمع وعرف قبل ذلك في صفة الخيل وكان هؤلاء نعات الخيل أخبرني هاشم بن محمد قال حدثنا عبد الرحمن قال حدثني عمي قال كان طفيل أكبر من النابغة وليس في قيس فحل أقدم منه قال وكان معاوية يقول خلوا لي طفيلا وقولوا ما شئتم في غيره من الشعراء أخبرني عبد الله بن مالك النحوي قال حدثنا محمد بن حبيب قال كان طفيل الغنوي يسمى طفيل الخيل لكثرة وصفه إياها أخبرني محمد بن الحسين الكندي خطيب مسجد القادسية قال حدثني الرياشي قال حدثني الأصمعي قال كان أهل الجاهلية يسمون طفيلا الغنوي المحبر لحسن وصفه الخيل أخبرني علي بن سليمان الأخفش قال حدثني محمد بن يزيد قال قال أبو عبيدة طفيل الغنوي والنابغة الجعدي وأبو دواد الإيادي أعلم العرب بالخيل وأوصفهم لها أخبرني عمي قال حدثنا محمد بن سعد الكراني قال حدثنا العمري عن لقيط قال قال قتيبة بن مسلم لأعرابي من غني قدم عليه من خراسان أي بيت قالته العرب أعف قال قول طفيل الغنوي - بسيط\n(ولا أكون وكاء الزاد أحبسه ... لقد علمت بأن الزاد مأكول)\nقال فأي بيت قالته العرب في الحرب أجود قال قول طفيل - طويل -\n(بحي إذا قيل اركبوا لم يقل لهم ... عواوير يخشون الردى أين نركب)\nال فأي بيت قالته العرب في الصبر أجود قال قول نافع بن خليفة الغنوي - طويل -\n(ومن خير ما فينا من الأمر أننا ... متى ما نوافي موطن الصبر نصبر)\nال فقال قتيبة ما تركت لإخوانك من باهلة قال قول صاحبهم - طويل -\n(وإنا أناس ما تزال سوامنا ... تنور نيران العدو مناسمه)\n(وليس لنا حي نضاف إليهم ... ولكن لنا عود شديد شكائمه)\n(حرام وإن صليته ودهنته ... تأوده ما كان في السيف قائمه)\nهذه القصيدة المذكورة فيها الغناء يقولها طفيل في وقعة أوقعها قومه بطيئ وحرب كانت بينه وبينهم وذكر أبو عمرو الشيباني والطوسي فيما رواه عن الأصمعي وأبي عبيدة أن رجلا من غني يقال له قيس الندامى وفد على بعض الملوك\nوكان قيس سيدا جوادا فلما حفل المجلس أقبل الملك على من حضره من وفود العرب فقال لأضعن تاجي على أكرم رجل من العرب فوضعه على رأس قيس وأعطاه ما شاء ونادمه مدة ثم أذن له في الانصراف إلى بلده فلما قرب من بلاد طيىء خرجوا إليه وهم لا يعرفونه فلقوه برمان فقتلوه فلما علموا أنه قيس ندموا لأياديه كانت فيهم فدفنوه وبنوا عليه بيتا ثم إن طفيلا جمع جموعا من قيس فأغار على طيىء فاستاق من مواشيهم ما شاء وقتل منهم قتلى كثيرة وكانت هذه الوقعة بين القنان وشرقي سلمى فذلك قول طفيل في هذه القصيدة - طويل -\n(فذوقوا كما ذقنا غداة محجر ... من الغيظ في أكبادنا والتحوب)\n(فبالقتل قتل والسوام بمثله ... وبالشل شل الغائط المتصوب)\nأخبرني علي بن الحسن بن علي قال حدثنا الحارث بن محمد عن المدائني عن سلمة بن محارب قال لما مات محمد بن الحجاج بن يوسف جزع عليه الحجاج جزعا شديدا ودخل الناس عليه يعزونه ويسلونه وهو لا يسلو ولا يزداد إلا جزعا وتفجعا وكان فيمن دخل عليه رجل كان الحجاج قتل ابنه يوم الزاوية فلما رأى جزعه وقلة ثباته للمصيبة شمت به وسر لما ظهر له منه وتمثل بقول طفيل - طويل -\n(فذقوا كما ذقنا غداة محجر ... من الغيظ في أكبادنا والتحوب)","topic":"نسب الطفيل الغنوي وأخباره","topicNo":192,"sp":0,"spl":"نسب الطفيل الغنوي وأخباره"},
{"id":"b192-2","bab":"الجزء 15","sec":"نسب الطفيل الغنوي وأخباره","page":"ج15 ص337","text":"وفي هذه القصيدة يقول طفيل - طويل -\n(ترى العين ما تهوى وفيها زيادة ... من اليمن إذ تبدو وملهى لملعب)\n(وبيت تهب الريح في حجراته ... بأرض فضاء بابه لم يحجب)\n(سماوته أسمال برد محبر ... وصهوته من أتحمي معصب)\nخبرني عيسى بن الحسين بن الوراق قال حدثنا الرياشي عن العتبى عن عن أبيه قال قال عبد الملك بن مروان لولده وأهله أي بيت ضربته العرب على عصابة ووصفته أشرف حواء وأهلا وبناء فقالوا فأكثروا وتكلم من حضر فأطالوا فقال عبد الملك أكرم بيت وصفته العرب بيت طفيل الذي يقوله فيه - طويل -\n(وبيت تهب الريح في حجراته ... بأرض فضاء بابه لم يحجب)\n(سماوته أسمال برد محبر ... وصهوته من أتحمي معصب)\n(وأطنابه أرسان جرد كأنها ... صدور القنا من بادىء ومعقب)\n(نصبت على قوم تدر رماحهم ... عروق الأعادي من غرير وأشيب)\nقال أبو عمرو الشيباني كانت فزارة لقيت بني أبي بكر بن كلاب وجيرانهم من محارب فأوقعت بهم وقعة عظيمة ثم أدركتهم غني فاستنقذتهم فلما قتلت طيىء قيس الندامى وقتلت بنو عبس هريم بن سنان بن عمرو بن يربوع بن طريف ابن خرشة بن عبيد بن سعد بن كعب بن جلان بن غنم بن غني وكان فارسا حسيبا\nقد ساد ورأس قتله ابن هدم العبسي طريد الملك فقال له الملك كيف قتلته قال حملت عليه في الكبة وطعنته في السبة حتى خرج الرمح من اللبة وقتل أسماء بن واقد بن رفيد بن رياح بن يربوع بن ثعلبة بن سعد بن عوف بن كعب بن جلان وهو من النجوم وحصن بن يربوع بن طريف وأمهم جندع بنت عمرو بن الأغر بن مالك بن سعد بن عوف فاستغاثت غني ببني أبي بكر وبني محارب فقعدوا عنهم فقال طفيل في ذلك يمن عليهم بما كان منهم في نصرتهم ويرثي القتلى قال - طويل -\n(تأوبني هم من الليل منصب ... وجاء من الأخبار ما لا أكذب)\n(تتابعن حتى لم تكن لي ريبة ... ولم يك عما خبروا متعقب)\n(وكان هريم من سنان خليفة ... وحصن ومن أسماء لما تغيبوا)\n(ومن قيس الثاوي برمان بيته ... ويوم حقيل فاد آخر معجب)\n(أشم طويل الساعدين كأنه ... فنيق هجان في يديه مركب)\n(وبالسهب ميمون النقيبة قوله ... لملتمس المعروف أهل ومرحب)","topic":"نسب الطفيل الغنوي وأخباره","topicNo":192,"sp":1,"spl":"نسب الطفيل الغنوي وأخباره"},
{"id":"b192-3","bab":"الجزء 15","sec":"صوت طويل","page":"ج15 ص343","text":"(كواكب دجن كلما انقض كوكب ... بدا وانجلت عنه الدجنة كوكب)\nلغناء لسليم أخي بابويه ثاني ثقيل عن الهشامي وهي قصيدة طويلة وذكرت منها هذه الأبيات من أجل الغناء الذي فيها ومن مختار مرثيته فيها قوله - طويل -\n(لعمري لقد خلى ابن جندع ثلمة ... ومن أين إن لم يرأب الله ترأب)\n(نداماي أمسوا قد تخليت عنهم ... فكيف ألذ الخمر أم كيف أشرب)\n(مضوا سلفا قصد السبيل عليهم ... وصرف المنايا بالرجال تقلب)\nوت - سريع -\n(فديت من بات يغنيني ... وبت أسقيه ويسقيني)\n(ثم اصطبحنا قهوة عتقت ... من عهد سابور وشيرين)\nلشعر والغناء لمحمد بن حمزة بن نصير وجه القرعة ولحنه فيه رمل أول بالبنصر لا نعرف له صنعة غيره\n23 - سب محمد بن حمزة بن نصير الوصيف وأخباره هو محمد بن حمزة بن نصير الوصيف مولى المنصور ويكنى أبا جعفر ويلقب وجه القرعة وهو أحد المغنين الحذاق الضراب الرواة وقد أخذ عن إبراهيم الموصلي وطبقته وكان حسن الأداء طيب الصوت لا علة فيه إلا أنه كان إذا غنى الهزج خاصة خرج بسبب لا يعرف إلا لآفة تعرض للحس في جنس من الأجناس فلا يصح له بتة فذكر محمد بن الحسن الكاتب أن إسحاق بن محمد الهاشمي حدثه عن أبيه أنه شهد إسحاق بن إبراهيم الموصلي عند عمه هارون بن عيسى وعنده محمد بن الحسن بن مصعب قال فأتانا محمد بن حمزة وجه القرعة فسر به عمي وكان شرس الخلق أبي النفس فكان إذا سئل الغناء أباه فإذا أمسك عنه كان هو المبتدئ به فأمسكنا عنه حتى طلب العود فأتي به فغنى وقال - مجزوء الرمل -\n(مر بي سرب ظباء ... رائحات من قباء)\nال وكان يحسنه ويجيده فجعل إسحاق يشرب ويستعيده حتى شرب ثلاثة\nأرطال ثم قال أحسنت يا غلام هذا الغناء لي وأنت تتقدمني فيه ولا يخلق الغناء ما دام مثلك ينشأ فيه قال وحدثني إسحاق الهاشمي عن أبيه قال كنا في البستان المعروف ببستان خالص النصراني ببغداد ومعنا محمد بن حمزة وجه القرعة فيغنينا قوله - مجزوء الكامل -\n(يا دار أقفر رسمها ... بين المحصب والحجون)\n(يا بشر إني فاعلمي ... والله مجتهدا يميني)\nإذا برجل راكب على حمار يؤمنا وهو يصيح أحسنت يا أبا جعفر أحسنت والله فقلنا اصعد إلينا كائنا من كنت فصعد وقال لو منعتموني من الصعود لما امتنعت ثم سفر اللثام عن وجهه فإذا هو مخارق فقال يا أبا جعفر أعد علي صوتك فأعاده فشرب رطلا من شرابنا وقال لولا أني مدعو الخليفة لأقمت عندكم واستمعت هذا الغناء الذي هو أحسن من الزهر غب المطر","topic":"نسب الطفيل الغنوي وأخباره","topicNo":192,"sp":2,"spl":"صوت طويل"},
{"id":"b192-4","bab":"الجزء 15","sec":"نسبة ما في هذه الأخبار من الغناء","page":"ج15 ص345","text":"منها - مجزوء الرمل -\n(مر بي سرب ظباء ... رائحات من قباء)\n(زمرا نحو المصلى ... يتمشين حذائي)\n(فتجاسرت وألقيت ... سرابيل الحياء)\n(وقديما كان لهوي ... وفتوني بالنساء)\nالغناء لإسحاق مما لا يشك فيه من صنعته ولحنه من ثقيل أول مطلق في مجرى الوسطى وذكر محمد بن أحمد المكي أنه لجده يحيى وذكر حبش أن فيه لابن جامع ثاني ثقيل بالوسطى ومنها - مجزوء الكامل -\n(يا بشر إني فاعلمي ... والله مجتهدا يميني)\n(ما إن صرمت حبالكم ... فصلي حبالي أو ذريني)\n(استبدلوا طلب الحجاز ... وسرة البلد الأمين)\n(بحدائق محفوفة ... بالبيت من عنب وتين)\n(يا دار أقفر رسمها ... بين المحصب والحجون)\n(أقوت وغير آيها ... طول التقادم والسنين)\nلشعر للحارث بن خالد والغناء لابن جامع في الأربعة الأبيات الأول رمل بالوسطى ولابن سريج في الخامس والسادس والأول والثاني ثقيل أول بالبنصر أخبرني الحسن بن علي قال حدثني محمد بن مهرويه قال حدثنا عبد الله ابن أبي سعد قال حدثني الفضل بن المغني عن محمد بن جبر قال دخلنا على\nإسحاق بن إبراهيم الموصلي نعوده من علة كان وجدها فصادفنا عنده مخارقا وعلويه وأحمد بن المكي وهم يتحدثون فاتصل الحديث بينهم وعرض إسحاق عليهم أن يقيموا عنده ليتفرج بهم ويخرج إليهم ستارته يغنون من ورائها ففعلوا وجاء محمد بن حمزة وجه القرعة على بقية ذلك فاحتبسه إسحاق معهم ووضع النبيذ وغنوا فغنى مخارق أو علويه صوتا من الغناء القديم فخالفه محمد فيه وفي صانعه وطال مراؤهما في ذلك وإسحاق ساكت ثم تحاكما إليه فحكم لمحمد وراجعه علويه فقال له إسحاق حسبك فوالله ما فيكم أدرى بما يخرج من رأسه منه ثم غنى أحمد بن يحيى المكي قوله - بسيط -\n(قل للجمانة لا تعجل بإسراج ... )\nفقال محمد هذا اللحن لمعبد ولا يعرف له هزج غيره فقال أحمد أما على ما شرط أبو محمد آنفا من أنه ليس في الجماعة أدرى بما يخرج من رأسه منك فلا معارض لك فقال له إسحاق يا أبا جعفر ما عنيتك والله فيما قلت ولكن قد قال إنه لا يعرف لمعبد هزج غير هذا وكلنا نعلم إنه لمعبد فأكذبه أنت بهزج آخر له مما لا يشك فيه فقال أحمد ما أعرف","topic":"نسب الطفيل الغنوي وأخباره","topicNo":192,"sp":3,"spl":"نسبة ما في هذه الأخبار من الغناء — نسبة هذا الصوت","song":2,"partial":1},
{"id":"b192-5","bab":"الجزء 15","sec":"نسبة هذا الصوت","page":"ج15 ص347","text":"قال محمد بن الحسن وحدثني إسحاق الهاشمي عن أبيه أن محمدا دخل معه على إسحاق الموصلي مهنئا له بالسلامة من علة كان فيها فدعا بعود فأمر به إسحاق فدفع إلى محمد فغنى أصواتا للقدماء وأصواتا لإبراهيم وأصواتا لإسحاق في إيقاعات مختلفة فوجه إسحاق خادما بين يديه إلى جواري أبيه فخرجن حتى سمعنه من وراء حجاب ثم ودعه وانصرف فقال إسحاق\nللجواري ما عندكن في هذا الفتى فقلن ذكرنا والله أباك فيما غناه فقال صدقتن ثم أقبل علينا فقال هو مغن محسن ولكنه لا يصلح للمطارحة لكثرة زوائده ومثله إذا طارح جسر الذي يأخذ عنه فلم ينتفع به ولكنه ناهيك به من مغن مطرب قال إسحاق وحدثت أنه صار إلى مخارق عائدا فصادف عنده المغنين جميعا فلما طلع تغامزوا عليه فسلم على مخارق وسأله به فأقبل عليه مخارق ثم قال له يا أبا جعفر إن جواريك اللواتي في ملكي قد تركن الدرس من مدة فأحب أن تدخل إليهن وتأخذ عليهن وتصلح من غنائهن ثم صاح بالخدم فسعوا بين يديه إلى حجرة الجواري ففعل ما سأله مخارق ثم خرج فأعلمه أنه قد أتى ما أحبه والتفت إلى المغنين فقال قد رأيت غمزكم فهل فيكم أحد رضي أبو المهنا أعزه الله حذقه وأدبه وأمانته ورضيه لجواريه غيري ثم ولى فكأنما ألقمهم حجرا فما أجابه أحد صوت - كامل -\n(عفت الديار محلها فمقامها ... بمنى تأبد غولها فرجامها)\n(فمدافع الريان عري رسمها ... خلقا كما ضمن الوحي سلامها)\n(فاقنع بما قسم الإله فإنما ... قسم الخلائق بيننا علامها)\nعروضه من الكامل عفت درست ومنى موضع في بلاد بني عامر وليس منى مكة تأبد توحش والغول والرجام جبلان بالحمى والريان واد مدافعه مجاري الماء فيه وعري رسمها أي ترك وارتحل عنه يقول عري من أهله وسلامها صخورها واحدتها سلمة\nالشعر للبيد بن ربيعة العامري والغناء لابن سريج رمل بالسبابة في مجرى البنصر عن إسحاق وفيه لابن محرز خفيف رمل أول بالوسطى عن حبش وذكر الهشامي أن فيه رملا آخر للهذلي في الثالث والأول","topic":"نسب الطفيل الغنوي وأخباره","topicNo":192,"sp":3,"spl":"نسبة ما في هذه الأخبار من الغناء — نسبة هذا الصوت"},
{"id":"b193-1","bab":"الجزء 15","sec":"نسب لبيد وأخباره","page":"ج15 ص350","text":"هو لبيد بن ربيعة بن مالك بن جعفر بن كلاب بن ربيعة بن عامر بن صعصعة بن معاوية بن بكر بن هوازن بن منصور بن عكرمة بن خصفة بن قيس بن عيلان بن مضر وكان يقال لأبيه ربيع المقترين لجوده وسخائه وقتلته بنو أسد في الحرب التي كانت بينهم وبين قومهم وقومه وعمه أبو براء عامر بن مالك ملاعب الأسنة سمي بذلك لقول أوس بن حجر فيه - طويل -\n(فلاعب أطراف الأسنة عامر ... فراح له حظ الكتيبة أجمع)\nوأم لبيد تامرة بنت زنباع العبسية إحدى بنات جذيمة بن رواحة ولبيد أحد شعراء الجاهلية المعدودين فيها والمخضرمين ممن أدرك الإسلام وهو من أشراف الشعراء المجيدين الفرسان القراء المعمرين يقال إنه عمر مائة وخمسا وأربعين سنة أخبرني بخبره في عمره أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة عن عبد الله بن محمد بن حكيم وأخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثنا عبد الله بن أبي سعد عن علي بن الصباح عن ابن الكلبي وعن علي بن المسور عن الأصمعي وعن المدائني وعن رجال ذكرهم منهم أبو اليقظان وابن دأب وابن جعدبة والوقاصي أن لبيد بن ربيعة قدم على رسول الله وفد بني كلاب بعد وفاة أخيه أربد وعامر بن الطفيل فأسلم وهاجر وحسن إسلامه ونزل الكوفة أيام عمر بن الخطاب رضي الله تعالى عنه فأقام بها ومات بها هناك في آخر خلافة معاوية فكان عمره مائة وخمسا وأربعين سنة منها تسعون سنة في الجاهلية وبقيتها في الإسلام قال عمر بن شبة في خبره فحدثني عبد الله بن محمد بن حكيم أن لبيدا قال حين بلغ سبعا وسبعين سنة بسيط -\n(قامت تشكى إلي النفس مجهشة ... وقد حملتك سبعا بعد سبعينا)\n(فإن تزادي ثلاثا تبلغي أملا ... وفي الثلاث وفاء للثمانينا)\nلما بلغ التسعين قال - طويل\n(كأني وقد جاوزت عشرين حجة ... خلعت بها عن منكبي ردائيا)\nفلما بلغ مائة وعشرا قال - بسيط -\n(أليس في مائة قد عاشها رجل ... وفي تكامل عشربعدها عمر)\nلما جاوزها قال - كامل -\n(ولقد سئمت من الحياة وطولها ... وسؤال هذا الناس كيف لبيد)\n(غلب الرجال وكان غير مغلب ... دهر طويل دائم ممدود)\n(يوما أرى يأتي علي وليلة ... وكلاهما بعد المضاء يعود)\n(وأراه يأتي مثل يوم لقيته ... لم ينتقص وضعفت وهو يزيد)\nخبرني محمد بن الحسن بن دريد قال حدثنا أبو حاتم السجستاني قال حدثنا الأصمعي قال وفد عامر بن مالك ملاعب الأسنة وكان يكنى أبا البراء في رهط من بني جعفر ومعه لبيد بن ربيعة ومالك بن جعفر وعامر بن مالك عم لبيد على النعمان فوجدوا عنده الربيع بن زياد العبسي وأمه فاطمة بنت الخرشب وكان الربيع نديما للنعمان مع رجل من تجار الشام يقال له زرجون بن توفيل وكان حريفا للنعمان يبايعه وكان أديبا حسن الحديث والندام فاستخفه النعمان وكان إذا أراد أن يخلو على شرابه بعث إليه وإلى النطاسي متطبب كان له وإلى الربيع بن زياد فخلا بهم فلما قدم الجعفريون كانوا يحضرون النعمان لحاجتهم فإذا خرجوا من عنده خلا به الربيع فطعن فيهم وذكر معايبهم وكانت بنو جعفر له أعداء فلم يزل بالنعمان حتى صده عنهم فدخلوا","topic":"نسب لبيد وأخباره","topicNo":193,"sp":0,"spl":"نسب لبيد وأخباره"},
{"id":"b193-2","bab":"الجزء 15","sec":"نسب لبيد وأخباره","page":"ج15 ص350","text":"عليه يوما فرأوا منه جفاء وقد كان يكرمهم ويقربهم فخرجوا غضابا ولبيد متخلف في رحالهم يحفظ متاعهم ويغدو بإبلهم كل صباح يرعاها فأتاهم ذات ليلة وهم يتذاكرون أمر الربيع فسألهم عنه فكتموه فقال والله لا حفظت لكم متاعا ولا سرحت لكم بعيرا أو تخبروني فيم أنتم وكانت أم لبيد يتيمة في حجر الربيع فقالوا خالك قد غلبنا على الملك وصد عنا وجهه فقال لبيد هل تقدرون على أن تجمعوا بيني وبينه فأزجره عنكم بقول ممض لا يلتفت إليه النعمان أبدا فقالوا وهل عندك شيء قال نعم قالوا فإنا نبلوك قال وما ذاك قالوا تشتم هذه البقلة وقدامهم بقلة دقيقة القضبان قلية الورق لاصقة بالأرض تدعى التربة فقال هذه التربة التي لا تذكي نارا ولا تؤهل دارا ولا تسر جارا عودها ضئيل وفرعها كليل وخيرها قليل أقبح البقول مرعى وأقصرها فرعا وأشدهما قلعا بلدها شاسع وآكلها جائع والمقيم عليها قانع فالقوا بي أخا عبس أرده عنكم بتعس وأتركه من أمره في لبس قالوا نصبح ونرى فيك رأينا فقال عامر انظروا إلى غلامكم هذا يعني لبيدا فإن رأيتموه نائما فليس أمره بشيء إنما هو يتكلم بما جاء على لسانه وإن رأيتموه ساهرا فهو صاحبه فرمقوه فوجدوه وقد ركب رحلا وهو يكدم وسطه حتى أصبح فقالوا أنت والله صاحبه فعمدوا إليه فحلقوا رأسه وتركوا دؤابته وألبسوه حلة ثم غدا معهم وأدخلوه على النعمان فوجدوه يتغدى ومعه الربيع بن زياد وهما يأكلان لا ثالث لهما والدار والمجالس مملوءة من الوفود فلما فرغ من الغداء أذن للجعفريين فدخلوا عليه وقد كان أمرهم تقارب فذكروا الذي قدموا له من حاجتهم فاعترض الربيع بن زياد في كلامهم فقال لبيد في ذلك - رجز\n(أكل يوم هامتي مقزعه ... يا رب هيجا هي خير من دعه)\n(نحن بني أم البنين الأربعه ... سيوف حز وجفان مترعه)\n(نحن خيار عامربن صعصعه ... الضاربون الهام تحت الخيضعه)\n(والمطمعون الجفنة المدعدعه ... مهلا أبيت اللعن لا تأكل معه)\n(إن استه من برص ملمعه ... وإنه يدخل فيها إصبعه)\n(يدخلها حتى يواري أشجعه ... كأنه يطلب شيئا ضيعه)\nرفع النعمان يده من الطعام وقال خبثت والله علي طعامي يا غلام وما رأيت كاليوم فأقبل الربيع على النعمان فقال كذب والله ابن الفاعلة ولقد فعلت بأمه كذا وكذا فقال له لبيد مثلك فعل ذلك بربيبة أهله والقريبة من أهله وإن أمي من نساء لم يكن فواعل ما ذكرت وقضى النعمان حوائج الجعفريين ومضى من وقته وصرفهم ومضى الربيع بن زياد إلى منزله من وقته فبعث إليه النعمان بضعف ما كان يحبوه وأمره بالانصراف إلى أهله فكتب إليه الربيع إني قد عرفت أنه قد وقع في صدرك ما قال لبيد وإني لست بارحا حتى تبعث إلي من يجردني فيعلم من حضرك من الناس أني لست كما قال لبيد فأرسل إليه إنك لست صانعا بانتفائك مما قال لبيد شيئا ولا قادرا على رد ما زلت به الألسن فالحق بأهلك فلحق بأهله ثم أرسل إلى النعمان بأبيات شعر قالها وهي - بسيط -\n(لئن رحلت جمالي لا إلى سعة ... ما مثلها سعة عرضا ولا طولا)\n(بحيث لو وردت لخم بأجمعها ... لم يعدلوا ريشة من ريش سمويلا)\n(ترعى الروائم أحرار البقول بها ... لا مثل رعيكم ملحا وغسويلا)\n(فاثبت بأرضك بعدي واخل متكئا ... مع النطاسي طورا وابن توفيلا)\nأجابه النعمان بقوله - بسيط -\n(شرد برحلك عني حيث شئت ولا ... تكثر علي ودع عنك الأباطيلا)\n(فقد ذكرت بشيء لست ناسيه ... ما جاورت مصر أهل الشام والنيلا)\n(فما انتفاؤك منه بعد ما جزعت ... هوج المطي به نحو ابن سمويلا)\n(قد قيل ذلك إن حقا وإن كذبا ... فما اعتذارك من قول إذا قيلا)\n(فالحق بحيث رأيت الأرض واسعة ... فانشر بها الطرف إن عرضا وإن طولا)\nال وقال لبيد يهجو الربيع بن زياد ويزعمون أنها مصنوعة قال - رجز -\n(ربيع لا يسقك نحوي سائق ... فتطلب الأذحال والحقائق)\n(ويعلم المعيا به والسابق ... ما أنت إن ضم عليك المازق)\n(إلا كشيء عاقه العوائق ... إنك حاس حسوة فذائق)\n(لا بد أن يغمز منك العاتق ... غمزا ترى أنك منه ذارق)\n(إنك شيخ خائن منافق ... بالمخزيات ظاهر مطابق)\nكان لبيد يقول الشعر ويقول لا تظهروه حتى قال - كامل\n(عفت الديار محلها فمقامها ... )","topic":"نسب لبيد وأخباره","topicNo":193,"sp":1,"spl":"نسب لبيد وأخباره","partialRef":{"sid":"b192-5","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b193-3","bab":"الجزء 15","sec":"نسب لبيد وأخباره","page":"ج15 ص350","text":"ذكر ما صنع الربيع بن زياد وضمرة بن ضمرة ومن حضرهم من وجوه الناس فقال لهم لبيد حينئذ أظهروها قال الأصمعي في تفسير قوله الخيضعة أصله الخضعة بغير ياء يعني الجلبة والأصوات فزاد فيها الياء وقال في قوله بالمخزيات ظاهر مطابق يقال طابق الدابة إذا وضع يديه ثم رفعهما فوضع مكانهما رجليه وكذلك إذا كان يطأ في شوك والمأزق المضيق والنازق الخفيف نسخت من كتاب مروي عن أبي الحكم قال حدثني العلاء بن عبد الله الموقع قال اجتمع عند الوليد بن عقبة سماره وهو أمير الكوفة وفيهم لبيد فسأل لبيدا عما كان بينه وبين الربيع بن زياد عند النعمان فقال له لبيد هذا كان من أمر الجاهلية وقد جاء الله بالإسلام فقال له عزمت عليك وكانوا يرون لعزمة الأمير حقا فجعل يحدثهم فحسده رجل من غني فقال ما علمنا بهذا قال أجل يا ابن أخي لم يدرك أبوك مثل ذلك وكان أبوك ممن لم يشهد تلك المشاهد فيحدثك أخبرني عمي قال حدثنا الكراني قال حدثني العمري قال حدثني الهيثم عن ابن عياش عن محمد بن المنتشر قال لم يسمع من لبيد فخره في الإسلام غير يوم واحد فإنه كان في رحبة غني مستلقيا على ظهره قد سجى نفسه بثوبه إذ أقبل شاب من غني فقال قبح الله طفيلا حيث يقول - طويل -\n(جزى الله عنا جعفرا حيث أشرفت ... بنا نعلنا في الواطئين فزلت)\n(أبوا أن يملونا ولو أن أمنا ... تلاقي الذي يلقون منا لملت)\n(فذو المال موفور وكل معصب ... إلى حجرات أدفأت وأظلت)\n(وقالت هلموا الدار حتى تبينوا ... وتنجلي الغماء عما تجلت)\nيت شعري ما الذي رأى من بني جعفر حيث يقول هذا فيهم قال فكشف لبيد الثوب عن وجهه وقال يا ابن أخي إنك أدركت الناس وقد جعلت لهم شرطة يزعون بعضهم عن بعض ودار رزق تخرج الخادم بجرابها فتأتي برزق أهلها وبيت مال يأخذون منه أعطيتهم ولو أدركت طفيلا يوم يقول هذا لم تلمه ثم استلقى وهو يقول أستغفر الله فلم يزل يقول أستغفر الله حتى قام أخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة قال حدثنا محمد بن حكيم عن خالد بن سعيد قال مر لبيد بالكوفة على مجلس بني نهد وهو يتوكأ على محجن له فبعثوا إليه رسولا يسأله عن أشعر العرب فسأله فقال الملك الضليل ذو القروح فرجع فأخبرهم فقالوا هذا امرؤ القيس ثم رجع إليه فسأله ثم من فقال له الغلام المقتول من بني بكر فرجع فأخبرهم فقالوا هذا طرفة ثم رجع فسأله ثم من فقال ثم صاحب المحجن يعني نفسه أخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثني أبو عبيدة قال لم يقل لبيد في الإسلام إلا بيتا واحدا وهو - بسيط\n(الحمد لله إذ لم يأتني أجلي ... حتى لبست من الإسلام سربالا)\nخبرني أحمد قال أخبرني عمي قال حدثني محمد بن عباد بن حبيب المهلبي قال حدثنا نصر بن دأب عن داود بن أبي هند عن الشعبي قال كتب عمر بن الخطاب رضي الله عنه إلى المغيرة بن شعبة وهو على الكوفة أن استنشد من قبلك من شعراء مصرك ما قالوا في الإسلام فأرسل إلى الأغلب الراجز العجلي فقال له أنشدني فقال - رجز -\n(أرجزا تريد أم قصيدا ... لقد طلبت هينا موجودا)\nثم أرسل إلى لبيد فقال أنشدني فقال إن شئت ما عفي عنه يعني الجاهلية فقال لا أنشدني ما قلت في الإسلام فانطلق فكتب سورة البقرة في صحيفة ثم أتى بها وقال أبدلني الله هذه في الإسلام مكان الشعر فكتب بذلك المغيرة إلى عمر فنقص من عطاء الأغلب خمسمائة وجعلها في عطاء لبيد فكان عطاؤه ألفين وخمسمائة فكتب الأغلب يا أمير المؤمنين أتنقص عطائي أن أطعتك فرد عليه خمسمائة وأقر عطاء لبيد على ألفين وخمسمائة قال أبو زيد وأراد معاوية أن ينقصه من عطائه لما ولي الخلافة وقال هذان الفودان يعني الألفين فما بال العلاوة يعني الخمسمائة فقال له لبيد إنما أنا هامة اليوم أو غد فأعرني اسمها فلعلي لا أقبضها أبدا فتبقى لك العلاوة والفودان فرق له وترك عطاءه على حاله فمات ولم يقبضه وقال عمر بن شبة في خبره الذي ذكره عن عبد الله بن محمد بن حكيم","topic":"نسب لبيد وأخباره","topicNo":193,"sp":2,"spl":"نسب لبيد وأخباره"},
{"id":"b193-4","bab":"الجزء 15","sec":"نسب لبيد وأخباره","page":"ج15 ص350","text":"وأخبرني به إبراهيم بن أيوب عن عبد الله بن مسلم قالا كان لبيد من جوداء العرب وكان قد آلى في الجاهلية أن لا تهب صبا إلا أطعم وكان له جفنتان يغدو بهما ويروح في كل يوم على مسجد قومه فيطعمهم فهبت الصبا يوما والوليد بن عقبة على الكوفة فصعد الوليد المنبر فخطب الناس ثم قال إن أخاكم لبيد بن ربيعة قد نذر في الجاهلية ألا تهب صبا إلا أطعم وهذا يوم من أيامه وقد هبت صبا فأعينوه وأنا أول من فعل ثم نزل عن المنبر فأرسل إليه بمائة بكرة وكتب إليه بأبيات قالها - وافر -\n(أرى الجزار يشحذ شفرتيه ... إذا هبت رياح أبي عقيل)\n(أشم الأنف أصيد عامري ... طويل الباع كالسيف الصقيل)\n(وفى ابن الجعفري بحلفتيه ... على العلات والمال القليل)\n(بنحر الكوم إذ سحبت عليه ... ذيول صبا تجاوب بالأصيل)\nلما بلغت أبياته لبيدا قال لابنته أجيبيه فلعمري لقد عشت برهة وما أعيا بجواب شاعر فقالت ابنته - وافر -\n(إذا هبت رياح أبي عقيل ... دعونا عند هبتها الوليدا)\n(أشم الأنف أروع عبشميا ... أعان على مروءته لبيدا)\n(بأمثال الهضاب كأن ركبا ... عليها من بني حام قعودا)\n(أبا وهب جزاك الله خيرا ... نحرناها فأطعمنا الثريدا)\n(فعد إن الكريم له معاد ... وظني يا ابن أروى أن تعودا)\nقال لها لبيد أحسنت لولا أنك استطعمته فقالت إن الملوك لا يستحيا من مسألتهم فقال وأنت يا بنية في هذه أشعر أخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثني محمد ابن عمران الضبي قال حدثني القاسم بن يعلى عن المفضل الضبي قال قدم الفرزدق فمر بمسجد بني أقيصر وعليه رجل ينشد قول لبيد - كامل -\n(وجلا السيول عن الطلول كأنها ... زبر تجد متونها أقلامها)\nسجد الفرزدق فقيل له ما هذا يا أبا فراس فقال أنتم تعرفون سجدة القرآن وأنا أعرف سجدة الشعر أخبرنا أحمد بن عبد الله بن عمار قال حدثنا يعقوب الثقفي وابن عياش ومسعر بن كدام كلهم عن عبد الملك بن عمير قال\nأخبرني من أرسله القراء الأشراف قال الهيثم فقلت لابن عياش من القراء الأشراف قال سليمان بن صرد الخزاعي والمسيب بن نجبة الفزاري وخالد بن عرفطة الزهري ومسروق بن الأجدع الهمداني وهانئ بن عروة المرادي إلى لبيد ابن ربيعة وهو في المسجد وفي يده محجن فقلت يا أبا عقيل إخوانك يقرئونك السلام ويقولون أي العرب أشعر قال الملك الضليل ذو القروح فردوني إليه وقولوا ومن ذو القروح قال امرؤ القيس فأعادوني إليه وقالوا ثم من قال الغلام ابن ثماني عشرة سنة فردوني إليه فقلت ومن هو فقال طرفة فردوني إليه فقلت ثم من قال صاحب المحجن حيث يقول - رمل -\n(إن تقوى ربنا خير نفل ... وبإذن الله ريثي وعجل)\n(أحمد الله ولا ند له ... بيديه الخير ما شاء فعل)\n(من هداه سبل الخير اهتدى ... ناعم البال ومن شاء أضل)\nعني نفسه ثم قال أستغفر الله أخبرني إسماعيل بن يونس الشيعي قال حدثنا عمر بن شبة عن ابن البواب قال جلس المعتصم يوما للشراب فغناه بعض المغنين قوله - رمل -\n(وبنو العباس لا يأتون لا ... وعلى ألسنهم خفت نعم)\n(زينت أحلامهم أحسابهم ... وكذاك الحلم زين للكرم)\nقال ما أعرف هذا الشعر فلمن هو قيل للبيد فقال وما للبيد وبني العباس قال المغني إنما قال\n(وبنو الديان لا يأتون ... )\nفجعلته وبنو العباس فاستحسن فعله ووصله وكان يعجب بشعر لبيد فقال من منكم يروي قوله\n(بلينا وما تبلى النجوم الطوالع ... )\n- طويل - فقال بعض الجلساء أنا فقال أنشدنيها فأنشد\n(بلينا وما تبلى النجوم الطوالع ... وتبقى الجبال بعدنا والمصانع)\n(وقد كنت في أكناف جار مضنة ... ففارقني جار بأربد نافع)\nبكى المعتصم حتى جرت دموعه وترحم على المأمون وقال هكذا كان رحمة الله عليه ثم اندفع وهو ينشد باقيها ويقول\n(فلا جزع إن فرق الدهر بيننا ... فكل امرىء يوما له الدهر فاجع)\n(وما الناس إلا كالديار وأهلها ... بها يوم حلوها وبعد بلاقع)\n(ويمضون أرسالا ونخلف بعدهم ... كما ضم إحدى الراحتين الأصابع)\n(وما المرء إلا كالشهاب وضوئه ... يحور رمادا بعد إذ هو ساطع)\n(وما البر إلا مضمرات من التقى ... وما المال إلا عاريات ودائع)\n(أليس ورائي إن تراخت منيتي ... لزوم العصا تحنى عليها الأصابع)\n(أخبر أخبار القرون التي مضت ... أدب كأني كلما قمت راكع)\n(فأصبحت مثل السيف أخلق جفنه ... تقادم عهد القين والنصل قاطع)","topic":"نسب لبيد وأخباره","topicNo":193,"sp":3,"spl":"نسب لبيد وأخباره","partial":1},
{"id":"b193-5","bab":"الجزء 15","sec":"نسب لبيد وأخباره","page":"ج15 ص350","text":"(فلا تبعدن إن المنية موعد ... علينا فدان للطلوع وطالع)\n(أعاذل ما يدريك إلا تظنيا ... إذا رحل الفتيان من هو راجع)\n(أتجزع مما أحدث الدهر بالفتى ... وأي كريم لم تصبه القوارع)\n(لعمرك ما تدري الضوارب بالحصى ... ولا زاجرات الطير ما الله صانع)\nال فعجبنا والله من حسن ألفاظه وصحة إنشاده وجودة اختياره أخبرني الحسين بن علي قال حدثنا محمد بن القاسم بن مهرويه وحدثنا محمد بن جرير الطبري قال حدثنا محمد بن حميد الرازي قال حدثنا سلمة بن الفضل عن محمد بن إسحاق قال كان عثمان بن مظعون في جوار الوليد بن المغيرة فتفكر يوما في نفسه فقال والله ما ينبغي لمسلم أن يكون آمنا في جوار كافر ورسول الله خائف فجاء إلى الوليد بن المغيرة فقال له أحب أن تبرأ من جواري قال لعله رابك ريب قال لا ولكن أحب أن تفعل قال فاذهب بنا حتى أبرأ منك حيث أجرتك فخرج معه إلى المسجد الحرام فلما وقف على جماعة قريش قال لهم هذا ابن مظعون قد كنت أجرته ثم سألني أن ابرأ منه أكذاك يا عثمان قال نعم قال اشهدوا أني منه بريء قال وجماعة يتحدثون من قريش معهم لبيد بن ربيعة ينشدهم فجلس عثمان مع القوم فأنشدهم لبيد - طويل -\n(ألا كل شيء ما خلا الله باطل ... )\nفقال له عثمان صدقت فقال لبيد\n(وكل نعيم لا محالة زائل ... )\nقال عثمان كذبت فلم يدر القوم ما عنى فأشار بعضهم إلى لبيد أن يعيد فأعاد فصدقه في النصف الأول وكذبه في الآخر لأن نعيم الجنة لا يزول فقال لبيد يا معشر قريش ما كان مثل هذا يكون في مجلسكم فقام أبي بن خلف أو ابنه فلطم وجه عثمان فقال له قائل لقد كنت في منعة من هذا بالأمس فقال له ما أحوج عيني هذه الصحيحة إلى أن يصيبها ما أصاب الأخرى في الله أخبرني محمد بن خلف بن المرزبان قال حدثنا أحمد بن الهيثم قال حدثني العمري عن الهيثم بن عدي عن عبد الله بن عياش قال كتب عبد الملك إلى الحجاج يأمره بإشخاص الشعبي إليه فأشخصه فألزمه ولده وأمر بتخريجهم ومذاكرتهم قال فدعاني يوما في علته التي مات فيها فغص بلقمة وأنا بين يديه فتساند طويلا ثم قال أصبحت كما قال الشاعر - طويل -\n(كأني وقد جاوزت سبعين حجة ... خلعت بها عني عذار لجام)\n(إذا ما رآني الناس قالوا ألم يكن ... شديد محال البطش غير كهام)\n(رمتني بنات الدهر من حيث لا أرى ... وكيف بمن يرمى وليس برام)\n(ولو أنني أرمى بسهم رأيته ... ولكنني أرمى بغير سهام)\nقال الشعبي فقلت إنا لله استسلم الرجل والله للموت فقلت أصلحك الله ولكن مثلك ما قال لبيد - بسيط -\n(باتت تشكى إلي الموت مجهشة ... وقد حملتك سبعا بعد سبعينا)\n(فإن تزادي ثلاثا تبلغي أملا ... وفي الثلاث وفاء للثمانينا)\nعاش إلى أن بلغ مائة تسعين سنة فقال - طويل -\n(كأني وقد جاوزت تسعين حجة ... خلعت بها عن منكبي ردائيا)\nعاش إلى أن بلغ مائة وعشر سنين قال - بسيط -\n(أليس في مائة قد عاشها رجل ... وفي تكامل عشر بعدها عمر)\nعاش إلى أن بلغ مائة وعشرين سنة فقال - كامل -\n(ولقد سئمت من الحياة وطولها ... وسؤال هذا الناس كيف لبيد)\n(غلب الرجال وكان غير مغلب ... دهر جديد دائم ممدود)\n(يوم أرى يأتي عليه وليلة ... وكلاهما بعد المضاء يعود)\nفرح واستبشر وقال ما أرى بأسا وقد وجدت خفا وأمر لي بأربعة آلاف درهم فقبضتها وخرجت فما بلغت الباب حتى سمعت الواعية عليه وغنى في هذه الأبيات التي أولها - كامل -\n(غلب الرجال وكان غير مغلب ... )\nمر الوادي خفيف رمل مطلق بالوسطى عن عمرو أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثنا هارون بن مسلم عن العمري عن الهيثم بن عدي عن حماد الراوية قال\nنظر النابغة الذبياني إلى لبيد بن ربيعة وهو صبي مع أعمامه على باب النعمان بن المنذر فسأل عنه فنسب له فقال يا غلام إن عينيك لعينا شاعر أفتقرض من الشعر شيئا قال نعم يا عم قال فأنشدني شيئا مما قلته فأنشده قوله - وافر -\n(ألم تربع على الدمن الخوالي ... )\nقال له يا غلام أنت أشعر بني عامر زدني يا بني فأنشده\n(طلل لخولة بالرسيس قديم ... )","topic":"نسب لبيد وأخباره","topicNo":193,"sp":4,"spl":"نسب لبيد وأخباره","partialRef":{"sid":"b193-1","gi":4,"vi":1,"side":0},"partial":1},
{"id":"b193-6","bab":"الجزء 15","sec":"نسب لبيد وأخباره","page":"ج15 ص350","text":"- كامل - فضرب بيديه إلى جنبيه وقال اذهب فأنت أشعر من قيس كلها أو قال هوازن كلها وأخبرني بهذا الخبر عمي قال حدثنا العمري عن لقيط عن أبيه وحماد الراوية عن عبد الله بن قتادة المحاربي قال كنت مع النابغة بباب النعمان بن المنذر فقال لي النابغة هل رأيت لبيد بن ربيعة فيمن حضر قلت نعم قال أيهم أشعر قلت الفتى الذي رأيت من حاله كيت وكيت فقال اجلس بنا حتى يخرج إلينا قال فجلسنا فلما خرج قال له النابغة إلي يا ابن أخي فأتاه فقال أنشدني فأنشده قوله - وافر -\n(ألم تلمم على الدمن الخوالي ... لسلمى بالمذانب فالقفال)\nقال له النابغة أنت أشعر بني عامر زدني فأنشده - كامل -\n(طلل لخولة بالرسيس قديم ... فبعاقل فالأنعمين رسوم)\nفقال له أنت أشعر هوازن زدني فأنشده قوله - كامل -\n(عفت الديار محلها فمقامها ... بمنى تأبد غولها فرجامها)\nقال له النابغة اذهب فأنت أشعر العرب أخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثني عبد الله بن محمد بن حكيم عن خالد بن سعيد أن لبيدا لما حضرته الوفاة قال لابن أخيه ولم يكن له ولد ذكر يا بني إن أباك لم يمت ولكنه فني فإذا قبض أبوك فأقبله القبلة وسجه بثوبه ولا تصرخن عليه صارخة وانظر جفنتي اللتين كنت أصنعهما فاصنعهما ثم احملهما إلى المسجد فإذا سلم الإمام فقدمها إليهم فإذا طعموا فقل لهم فليحضروا جنازة أخيهم ثم أنشد قوله - مجزوء الكامل -\n(وإذا دفنت أباك فاجعل ... فوقه خشبا وطينا)\n(وسقائفا صما رواسيها ... يسددن الغصونا)\n(ليقين حر الوجه سفساف ... التراب ولن يقينا)\nال وهذه الأبيات من قصيدة طويلة وقد ذكر يونس أن لابن سريج لحنا في أبيات من قصيدة لبيد هذه ولم يجنسه صوت - مجزوء الكامل -\n(أبني هل أبصرت أعمامي ... بني أم البنينا)\n(وأبي الذي كان الأرامل ... في الشتاء له قطينا)\n(وأبا شريك والمنازل في المضيق إذا لقينا ... )\n(ما إن رأيت ولا سمعت ... بمثلهم في العالمينا)\n(فبقيت بعدهم وكنت ... بطول صحبتهم ضنينا)\n(دعني وما ملكت يميني ... إن سددت بها الشؤونا)\n(وافعل بمالك ما بدا ... لك مستعانا أو معينا)\nال وقال لابنتيه حين احتضر وفيه غناء - طويل -\n(تمنى ابنتاي أن يعيش أبوهما ... وهل أنا إلا من ربيعة أو مضر)\n(فإن حان يوما أن يموت أبوكما ... فلا تخمشا وجها ولا تحلقا شعر)\n(وقولا هو المرء الذي لا حليفه ... أضاع ولا خان الصديق ولا غدر)\n(إلى الحول ثم اسم السلام عليكما ... ومن يبك حولا كاملا فقد اعتذر)\nي هذه الأبيات هزج خفيف مطلق في مجرى الوسطى وذكر الهشامي أنه لإسحاق وذكر أحمد بن يحيى أنه لإبراهيم قال فكانت ابنتاه تلبسان ثيابهما في كل يوم ثم تأتيان مجلس بني\nجعفر بن كلاب فترثيانه ولا تعولان فأقامتا على ذلك حولا ثم انصرفتا صوت - وافر -\n(سألناه الجزيل فما تأبى ... فأعطى فوق منيتنا وزادا)\n(وأحسن ثم أحسن ثم عدنا ... فأحسن ثم عدت له فعادا)\n(مرارا ما دنوت إليه إلا ... تبسم ضاحكا وثنى الوسادا)\nلشعر لزياد الأعجم والغناء لشارية خفيف رمل بالبنصر مطلق\n25 - خبار زياد الأعجم ونسبه زياد بن سليمان مولى عبد القيس أحد بني عامر بن الحارث ثم أحد بني مالك بن عامر الخارجية أخبرني بذلك علي بن سليمان الأخفش عن أبي سعيد السكري وأخبرني محمد بن العباس اليزيدي عن عمه عن ابن حبيب قال هو زياد بن جابر بن عمرو مولى عبد القيس وكان ينزل إصطخر فغلبت العجمة على لسانه فقيل له الأعجم وذكر ابن النطاح مثل ذلك في نسبه وخالف في بلده وذكر أن أصله ومولده ومنشأه بأصبهان ثم انتقل إلى خراسان فلم يزل بها حتى مات وكان شاعرا جزل الشعر فصيح الألفاظ على لكنة لسانه وجريه على لفظ أهل بلده\nأخبرني الحسن بن علي قال حدثنا محمد بن موسى قال حدثت عن المدائني أن زيادا الأعجم دعا غلاما له ليرسله في حاجة فأبطأ فلما جاءه قال له منذ لدن دأوتك إلى أن قلت لبي ما كنت تسنأ يريد منذ لدن دعوتك إلى إن قلت لبيك ماذا كنت تصنع فهذه ألفاظه كما ترى في نهاية القبح واللكنة وهو الذي يقول يرثي المغيرة بن المهلب بقوله - كامل -\n(قل للقوافل والغزي إذا غزوا ... والباكرين وللمجد الرائح)\n(إن المروءة والسماحة ضمنا ... قبرا بمرو على الطريق الواضح)\n(فإذا مررت بقبره فاعقر به ... كوم الهجان وكل طرف سابح)","topic":"نسب لبيد وأخباره","topicNo":193,"sp":5,"spl":"نسب لبيد وأخباره","song":1,"partial":1},
{"id":"b193-7","bab":"الجزء 15","sec":"نسب لبيد وأخباره","page":"ج15 ص350","text":"(وانضح جوانب قبره بدمائها ... فلقد يكون أخا دم وذبائح)\n(يا من بمهوى الشمس من حي إلى ... ما بين مطلع قرنها المتنازح)\n(مات المغيرة بعد طول تعرض ... للموت بين أسنة وصفائح)\n(والقتل ليس إلى القتال ولا أرى ... حيا يؤخر للشفيق الناصح)\nهي طويلة وهذا من نادر الكلام ونقي المعاني ومختار القصيد وهي معدودة من مراثي الشعراء في عصر زياد ومقدمها لابن جامع في الأبيات الأربعة الأول غناء أوله نشيد كله ثم تعود الصنعة إلى الثاني والثالث في طريقة الهزج بالوسطى وقد أخبرني علي بن سليمان الأخفش عن السكري عن محمد بن حبيب أن من الناس من يروي هذه القصيدة للصلتان العبدي وهذا قول شاذ والصحيح أنها لزياد قد دونها الرواة غير مدفوع عنها أخبرني محمد بن خلف وكيع قال حدثني إسحاق بن محمد النخعي قال حدثنا ابن عائشة عن أبيه قال رثى زياد الأعجم المغيرة بن المهلب فقال - كامل -\n(إن الشجاعة والسماحة ضمنا ... قبرا بمرو على الطريق الواضح)\n(فإذا مررت بقبره فاعقر به ... كوم الهجان وكل طرف سابح)\nقال له يزيد بن المهلب يا أبا أمامة أفعقرت أنت عنده قال كنت على بنت\nالهمار يريد الحمار أخبرني مالك بن محمد الشيباني قال كنت حاضرا في مجلس أبي العباس فقلت وقد قرئ عليه شعر زياد الأعجم فقرئت عليه قصيدته - كامل -\n(قل للقوافل والغزي إذا غزوا ... والباكرين وللمجد الرائح)\nال فقلت إنها من مختار الشعر ولقد أنشدت لبعض المحدثين في نحو هذا المعنى أبياتا حسنة ثم أنشدنا - خفيف -\n(أيها الناعيان من تنعيان ... وعلى من أراكما تبكيان)\n(اندبا الماجد الكريم أبا إسحاق ... رب المعروف والإحسان)\n(واذهبا بي إن لم يكن لكما عقر ... إلى جنب قبره فاعقراني)\n(وانضحا من دمي عليه فقد كا ... ن دمي من نداه لو تعلمان)\nخبرني وكيع قال حدثني إسحاق بن محمد النخعي عن ابن عائشة عن أبيه قال كان المهلب بن أبي صفرة بخراسان فخرج إليه زياد الأعجم فمدحه فأمر له بجائزة فأقام عنده أياما قال فإنا لبعشية نشرب مع حبيب بن المهلب في دار له وفيها حمامة إذ سجعت الحمامة فقال زياد - وافر -\n(تغني أنت في ذممي وعهدي ... وذمة والدي إن لم تطاري)\n(وبيتك فاصلحيه ولا تخافي ... على صفر مزغبة صغار)\n(فإنك كلما غنيت صوتا ... ذكرت أحبتي وذكرت داري)\n(فإما يقتلوك طلبت ثأرا ... له نبأ لأنك في جواري)\nقال حبيب يا غلام هات القوس فقال له زياد ما تصنع بها قال أرمي جارتك هذه قال والله لئن رميتها لأستعدين عليك الأمير فأتى بالقوس فنزع لها سهما فقتلها فوثب زياد فدخل على المهلب فحدثه الحديث وأنشده الشعر فقال المهلب علي بأبي بسطام فأتي بحبيب فقال له أعط أبا أمامة دية جارته ألف دينار فقال أطال الله بقاء الأمير إنما كنت ألعب قال أعطه كما آمرك فأنشأ زياد يقول - طويل -\n(فلله عينا من رأى كقضية ... قضى لي بها قرم العراق المهلب)\n(رماها حبيب بن المهلب رمية ... فأثبتها بالسهم والسهم يغرب)\n(فألزمه عقل القتيل ابن حرة ... وقال حبيب إنما كنت ألعب)\n(فقال زياد لا يروع جاره ... وجارة جاري مثل جلدي وأقرب)\nال فحمل حبيب إليه ألف دينار على كره منه فإنه ليشرب مع حبيب يوما إذ عربد عليه حبيب وقد كان حبيب ضغن عليه مما جرى فأمر بشق قباء ديباج كان عليه فقام فقال - طويل -\n(لعمرك ما الديباج خرقت وحده ... ولكنما خرقت جلد المهلب)\nبعث المهلب إلى حبيب فأحضره وقال له صدق زياد ما خرقت إلا جلدي تبعث هذا على أن يهجوني ثم بعث إليه فأحضره فاستل سخيمته من صدره وأمر له بمال وصرفه\nوقد أخبرني وكيع بهذا الخبر أيضا قال أحمد بن الهيثم بن فراس قال العمري عن الهيثم بن عدي قال تهاجى قتادة بن مغرب اليشكري وزياد الأعجم بخراسان وكان زياد يخرج وعليه قباء ديباج تشبها بالأعاجم فمر به يزيد بن المهلب وهو على حاله تلك فأمر به فقنع أسواطا ومزقت ثيابه وقال له أبأهل الكفر والشرك تتشبه لا أم لك فقال زياد - طويل -\n(لعمرك ما الديباج خرقت وحده ... ولكنما خرقت جلد المهلب)","topic":"نسب لبيد وأخباره","topicNo":193,"sp":6,"spl":"نسب لبيد وأخباره"},
{"id":"b193-8","bab":"الجزء 15","sec":"نسب لبيد وأخباره","page":"ج15 ص350","text":"ذكر باقي الخبر مثله وقال فيه فدعا به المهلب فقال له يا أبا أمامة قلت شيئا آخر قال لا والله أيها الأمير قال فلا تقل وأعتبه وكساه وحمله وأمر له بعشرة آلاف درهم وقال له اعذر ابن أخيك يا أبا أمامة فإنه لم يعرفك وهذه الأبيات التي فيها الغناء يقولها زياد الأعجم في عمر بن عبيد الله بن معمر التيمي أخبرني بخبره في ذلك أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال أتى زياد الأعجم عمر بن عبيد الله بن معمر بفارس وقدم عليه عراك بن محمد الفقيه من مصر فكان عراك يحدثه بحديث الفقهاء فقال زياد - طويل -\n(يحدثنا أن القيامة قد أتت ... وجاء عراك يبتغي المال من مصر)\n(فكم بين باب النوب إن كنت صادقا ... وإيوان كسرى من فلاة ومن قصر)\nوقال يمدح عمر بن عبيد الله - وافر -\n(سألناه الجزيل فما تأبى ... وأعطى فوق منيتنا وزادا)\nذكر الأبيات الثلاثة نسخت من كتاب ابن أبي الدنيا أخبرني محمد بن زياد عن ابن عائشة وأخبرني هاشم بن محمد قال حدثني عيسى بن إسماعيل عن ابن عائشة وخبر ابن أبي الدنيا أتم قال كان زياد الأعجم صديقا لعمر بن عبيد الله بن معمر قبل أن يلي فقال له عمر يا أبا أمامة لو قد وليت لتركتك لا تحتاج إلى أحد أبدا فلما ولي فارس قصده فلما لقيه أنشأ يقول - طويل -\n(أبلغ أبا حفص رسالة ناصح ... أتت من زياد مستبينا كلامها)\n(فإنك مثل الشمس لا ستر دونها ... فكيف أبا حفص علي ظلامها)\nقال له عمر لا يكون عليك ظلامها أبدا فقال زياد - طويل -\n(لقد كنت أدعو الله في السر أن أرى ... أمور معد في يديك نظامها)\nقال له قد رأيت ذلك فقال\n(فلما أتاني ما أردت تباشرت ... بناتي وقلن العام لا شك عامها)\nال فهو عامهن إن شاء الله تعالى فقال\n(فإني وأرضا أنت فيها ابن معمر ... كمكة لم يطرب لأرض حمامها)\nال فهي كذلك يا زياد فقال\n(إذا اخترت أرضا للمقام رضيتها ... لنفسي ولم يثقل علي مقامها)\n(وكنت أمني النفس منك ابن معمر ... أماني أرجو أن يتم تمامها)\nال قد أتمها الله عليك فقال\n(فلا أك كالمجري إلى رأس غاية ... يرجي سماء لم يصبه غمامها)\nال لست كذلك فسل حاجتك قال نجيبة ورحالتها وفرس رائع وسائسه وبدرة وحاملها وجارية وخادمها وتخت ثياب ووصيف يحمله فقال قد أمرنا لك بجميع ما سألت وهو لك علينا في كل عام فخرج من عنده حتى قدم على عبد الله بن الحشرج وهو بسابور فأنزله وألطفه فقال في ذلك - كامل -\n(إن السماحة والمروءة والندى ... في قبة ضربت على ابن الحشرج)\n(ملك أغر متوج ذو نائل ... للمعتفين يمينه لم تشنج)\n(يا خير من صعد المنابر بالتقى ... بعد النبي المصطفى المتحرج)\n(لما أتيتك راجيا لنوالكم ... ألفيت باب نوالكم لم يرتج)\nأمر له بعشرة آلاف درهم\nأخبرنا محمد بن خلف وكيع عن عبد الله بن محمد عن عبيد بن الحسن بن عبد الرحمن بهذا الخبر فقال فيه أتى زياد عبد الله بن عامر بن كريز والخبر الأول أصح وزاد في الشعر - وافر -\n(أخ لك لا تراه الدهر إلا ... على العلات بساما جوادا)\nقال له عمر أحسنت يا أبا أمامة ولك لكل بيت ألف قال دعني أتمها مائة قال أما إنك لو كنت فعلت لفعلت ولكن لك ما رزقت أخبرني أحمد بن عبد العزيز قال حدثنا ابن عائشة قال حدثني أبي قال لما خرج ابن الأشعث أرسل عبد الملك إلى عمر بن عبيد الله ابن معمر ليقدم عليه فلما كان بضمير وهي من الشأم مات بالطاعون فقام عبد الملك على قبره وقال أما والله لقد علمت قريش أن قد فقدت اليوم نابا من أنيابها وقال جد خلاد بن أبي عمرو الأعمى وكانوا موالي أبي وجرة بن أبي عمرو بن أمية أهو اليوم ناب لما مات وكان أمس ضرسا كليلة أما والله لوددت أن السماء وقعت على الأرض فلم يعش بينهما أحد بعده وسمعها عبد الملك فتغافل عنها قال وقال الفرزدق يرثيه - بسيط -\n(يا أيها الناس لا تبكوا على أحد ... بعد الذي بضمير وافق القدرا)\n(كانت يداه لنا سيفا نصول به ... على العدو وغيثا ينبت الشجرا)\n(أما قريش أبا حفص فقد رزئت ... بالشام إذ فارقتك البأس والظفرا)\n(من يقتل الجوع من بعد الشهيد ومن ... بالسيف يقتل كبش القوم إذ عكرا)\n(إن النوائح لم يعددن في عمر ... ما كان فيه إذا المولى به افتخرا)\n(إذا عددن فعالا أو له حسبا ... ويوم هيجاء يعشي بأسه البصرا)\n(كم من جبان إلى الهيجا دنوت له ... يوم اللقاء ولولا أنت ما صبرا)","topic":"نسب لبيد وأخباره","topicNo":193,"sp":7,"spl":"نسب لبيد وأخباره"},
{"id":"b193-9","bab":"الجزء 15","sec":"نسب لبيد وأخباره","page":"ج15 ص350","text":"خبرنا أحمد حدثنا عمر بن شبة قال حدثنا عفان بن مسلم قال حدثنا حماد بن سلمة قال أخبرنا حميد عن سليمان بن قتة قال بعث عمر بن عبيد الله ابن معمر إلى ابن عمر والقاسم بن محمد بألف دينار فأتيت عبد الله بن عمر وهو يغتسل في مستحم له فأخرج يده فصببتها في يده فقال وصلت رحما وقد جاءتنا على حاجة وأتيت القاسم فأبى أن يقبلها فقالت لي امرأته إن كان القاسم ابن عمه فأنا لابنة عمه فأعطيتها قال فكان عمر يبعث بهذه الثياب العمرية يقسمها بين أهل المدينة فقال ابن عمر جزى الله من اقتنى هذه الثياب بالمدينة خيرا وقال لي عمر لقد بلغني عن صاحبك شيء كرهته قلت وما ذاك قال يعطي المهاجرين ألفا ألفا ويعطي الأنصار سبعمائة سبعمائة فأخبرته فسوى بينهم أخبرنا أحمد قال حدثنا أبو زيد قال كانت لرجل جارية يهواها فاحتاج إلى بيعها فابتاعها منه عمر بن عبيد الله بن معمر فلما قبض ثمنها أنشأت تقول - طويل -\n(هنيئا لك المال الذي قد قبضته ... ولم يبق في كفي غير التحسر)\n(فإني لحزن من فراقك موجع ... أناجي به قلبا طويل التفكر)\nقال لا ترحلي ثم قال\n(ولولا قعود الدهر بي عنك لم يكن ... يفرقنا شيء سوى الموت فاعذري)\n(عليك سلام لا زيارة بيننا ... ولا وصل إلا أن يشاء ابن معمر)\nقال قد شئت خذ الجارية وثمنها فأخذها وانصرف أخبرني عمي قال حدثنا عبد الله بن أبي سعد قال حدثني محمد بن زياد\nقال حدثني ابن عائشة قال استبطأ زياد الأعجم عمر بن عبيد الله بن معمر في زيارته إياه فقال - طويل -\n(أصابت علينا جودك العين يا عمر ... فنحن لها نبغي التمائم والنشر)\n(أصابتك عين في سماحك صلبة ... ويا رب عين صلبة تفلق الحجر)\n(سنرقيك بالأشعار حتى تملها ... فإن لم تفق يوما رقيناك بالسور)\nبلغته الأبيات فأرضاه وسرحه أخبرني عمي قال حدثني الكراني قال حدثني العمري قال حدثني من سمع حمادا الراوية يقول امتدح زياد الأعجم عباد بن الحصين الحبطي وكان على شرطة الحارث بن عبد الله بن أبي ربيعة الذي يقال له القباع وطلب حاجة فلم يقضها فقال زياد - متقارب -\n(سألت أبا جهضم حاجة ... وكنت أراه قريبا يسيرا)\n(فلو أنني خفت منه الخلاف ... والمنع لي لم أسله نقيرا)\n(وكيف الرجاء لما عنده ... وقد خالط البخل منه الضميرا)\n(أقلني أبا جهضم حاجتي ... فإني امرؤ كان ظني غرورا)\nخبرني عمي قال حدثني الكراني عن العمري عن عطاء بن مصعب عن عاصم بن الحدثان قال مر يزيد بن حبناء الضبي بزياد الأعجم وهو ينشد شعرا قد هجا به قتادة بن مغرب فأفحش فيه فقال له يزيد بن حبناء ألم يأن لك أن ترعوي وتترك تمزيق أعراض قومك ويحك حتى متى تتمادى في الضلال\nكأنك بالموت قد صبحك أو مساك فقال زياد فيه - طويل -\n(يحذرني الموت ابن حبناء والفتى ... إلى الموت يغدو جاهدا ويروح)\n(وكل امرىء لا بد للموت صائر ... وإن عاش دهرا في البلاد يسيح)\n(فقل ليزيد يا ابن حبناء لا تعظ ... أخاك وعظ نفسا فأنت جنوح)\n(تركت التقى والدين دين محمد ... لأهلي التقى والمسلمين يلوح)\n(وتابعت مراق العراقين سادرا ... وأنت غليظ القصريين صحيح)\nقال له يزيد بن عاصم الشني قبحك الله أتهجو رجلا وعظك وأمرك بمعروف بمثل هذا الهجاء هلا كففت إذ لم تقبل أراه والله سيأتي على نفسك ثم لا تحبق فيك عنزان اذهب ويحك فأته واعتذر إليه لعله يقبل عذرك فمشى إليه بجماعة من عبد القيس فشفعوا إليه فيه فقال لا تثريب لست واجدا عليه بعد يومي هذا أخبرني أحمد بن علي قال سمعت جدي علي بن يحيى يحدث عن أبي الحسن عن رجل من جعفي قال كنت جالسا عند المهلب إذ أقبل رجل طويل مضطرب فلما رآه المهلب قال اللهم إني أعوذ بك من شره فجاء فقال أصلح الله الأمير إني قد مدحتك ببيت صفده مائة ألف درهم فسكت المهلب فأعاد القول فقال له أنشده فأنشده - طويل -\n(فتى زاده السلطان في الخير رغبة ... إذا غير السلطان كل خليل)\nفقال له المهلب يا أبا أمامة مائة ألف فوالله ما هي عندنا ولكن ثلاثون ألفا فيها عروض وأمر له بها فإذا هو زياد الأعجم أخبرني عمي قال حدثني الكراني وأبو العيناء عن القحذمي قال لقي الفرزدق زيادا الأعجم فقال له الفرزدق لقد هممت أن أهجو عبد القيس وأصف من فسوهم شيئا قال له زياد كما أنت حتى أسمعك شيئا ثم قال قل إن شئت أو أمسك قال هات قال - طويل -","topic":"نسب لبيد وأخباره","topicNo":193,"sp":8,"spl":"نسب لبيد وأخباره"},
{"id":"b193-10","bab":"الجزء 15","sec":"نسب لبيد وأخباره","page":"ج15 ص350","text":"(وما ترك الهاجون لي إن هجوته ... مصحا أراه في أديم الفرزدق)\n(فإنا وما تهدي لنا إن هجوتنا ... لكالبحر مهما يلق في البحر يغرق)\nقال له الفرزدق حسبك هلم نتتارك قال ذاك إليك وما عاوده بشيء وأخبرني بهذا الخبر محمد بن الحسن بن دريد قال حدثنا العتبى عن العباس بن هشام عن أبيه قال حدثني خراش وكان عالما راوية لأبي ولمؤرج ولجابر بن كلثوم قال أقبل الفرزدق وزياد ينشد الناس في المربد وقد اجتمعوا حوله فقال من هذا قيل الأعجم فأقبل نحوه فقيل له هذا الفرزدق قد أقبل عليك فقام فتلقاه وحيا كل واحد منهما صاحبه فقال له الفرزدق ما زالت تنازعني نفسي إلى هجاء عبد القيس منذ دهر قال زياد وما\nيدعوك إلى ذلك قال لأني رأيت الأشقري هجاكم فلم يصنع شيئا وأنا أشعر منه وقد عرفت الذي هيج بينك وبينه قال وما هو قال إنكم اجتمعتم في قبة عبد الله بن الحشرج بخراسان فقلت له قد قلت شيئا فمن قال مثله فهو أشعر مني ومن لم يقل مثله ومد إلي عنقه فإني أشعر منه فقال لك وما قلت فقلت قلت - طويل -\n(وقافية حذاء بت أحوكها ... إذا ما سهيل في السماء تلالا)\nقال لك الأشقري - طويل -\n(وأقلف صلى بعد ما ناك أمه ... يرى ذاك في دين المجوس حلالا)\nأقبلت على من حضر فقلت يا لأم كعب أخزاها الله تعالى ما أنمها حين تخبر ابنها بقلفتي فضحك الناس وغلبت عليه في المجلس فقال له زياد يا أبا فراس هب لي نفسك ساعة ولا تعجل حتى يأتيك رسولي بهديتي ثم ترى رأيك وظن الفرزدق أنه سيهدي إليه شيئا يستكفه به فكتب إليه - طويل -\n(وما ترك الهاجون لي إن أردته ... مصحا أراه في أديم الفرزدق)\n(وما تركوا لحما يدقون عظمه ... لآكله ألقوه للمتعرق)\n(سأحطم ما أبقوا له من عظامه ... فأنكت عظم الساق منه وأنتقي)\n(فإنا وما تهدي لنا إن هجوتنا ... لكالبحر مهما يلق في البحر يغرق)\nبعث إليه الفرزدق لا أهجو قوما أنت منهم أبدا قال أبو المنذر زياد أهجى من كعب الأشقري وقد أوثر عليه في عدة قصائد منها التي يقول فيها - متقارب -\n(قبيلة خيرها شرها ... وأصدقها الكاذب الآثم)\n(وضيفهم وسط أبياتهم ... وإن لم يكن صائما صائم)\nفيه يقول - طويل -\n(إذا عذب الله الرجال بشعرهم ... أمنت لكعب أن يعذب بالشعر)\nفيه يقول - وافر -\n(أتتك الأزد مصفرا لحاها ... تساقط من مناخرها الجواف)\nخبرني وكيع قال حدثني أحمد بن عمر بن بكير قال حدثنا الهيثم عن ابن عياش قال دخل أبو قلابة الجرمي مسجد البصرة وإذا زياد الأعجم فقال زياد من هذا قال أبو قلابة الجرمي فقام على رأسه فقال - طويل -\n(قم صاغرا يا كهل جرم فإنما ... يقال لكهل الصدق قم غير صاغر)\n(فإنك شيخ ميت ومورث ... قضاعة ميراث البسوس وقاشر)\n(قضى الله خلق الناس ثم خلقتم ... بقية خلق الله آخر آخر)\n(فلم تسمعوا إلا بما كان قبلكم ... ولم تدركوا إلا بدق الحوافر)\n(فلو رد أهل الحق من مات منكم ... إلى حقه لم تدفنوا في المقابر)\nقيل له فأين كانوا يدفنون يا أبا أمامة قال في النواويس","topic":"نسب لبيد وأخباره","topicNo":193,"sp":9,"spl":"نسب لبيد وأخباره"},
{"id":"b193-11","bab":"الجزء 16","sec":"أخبار شارية","page":"ج16 ص5","text":"قال أبو الفرج علي بن الحسين كانت شارية مولدة من مولدات البصرة يقال إن أباها كان رجلا من بني سامة بن لؤي المعروفين ببني ناجية وأنه جحدها وكانت أمها أمة فدخلت في الرق وقيل بل سرقت فبيعت فاشترتها امرأة من بني هاشم فأدبتها وعلمتها الغناء ثم اشتراها إبراهيم بن المهدي فأخذت غناءها كله أو أكثره عنه وبذلك يحتج من يقدمها على عريب ويقول إن\nإبراهيم خرجها وكان يأخذها بصحة الأداء لنفسه وبمعرفة ما يأخذها به ولم تكن هذه حال عريب لأن المراكبي لم يكن يقارب إبراهيم في العلم ولا يقاس به في بعضه فضلا عن سائره أخبرني بخبرها محمد بن إبراهيم قريض أن ابن المعتز دفع إليه كتابه الذي ألفه في أخبارها وقال له أن يرويه عنه فنسخت منه ما كان يصلح لهذا الكتاب على شرطي فيه وأضفت إليه ما وجدته من أخبارها عن غيره في الكتب وسمعته أنا عمن رويته عنه قال ابن المعتز حدثني عيسى بن هارون المنصوري أن شارية كانت لامرأة من الهاشميات بصرية من ولد جعفر بن سليمان فحملتها لتبيعها ببغداد فعرضت على إسحاق بن إبراهيم الموصلي فأعطى بها ثلثمائة دينار ثم استغلاها بذلك ولم يردها فجيء بها إلى إبراهيم بن المهدي فعرضت عليه فساوم بها فقالت له مولاتها قد بذلتها لإسحاق بن إبراهيم بثلثمائة دينار وأنت أيها الأمير أعزك الله بها أحق فقال زنوا لها ما قالت فوزن لها ثم دعا بقيمته فقال خذي هذه الجارية ولا ترينيها سنة وقولي للجواري يطرحن عليها فلما كان بعد سنة أخرجت إليه فنظر إليها وسمعها فأرسل إلى إسحاق بن إبراهيم الموصلي فدعاه وأراه إياها وأسمعه غناءها وقال هذه جارية تباع فبكم تأخذها\nلنفسك قال إسحاق آخذها بثلاثة آلاف دينار وهي رخيصة بها قال له إبراهيم أتعرفها قال لا قال هذه الجارية التي عرضتها عليك الهاشمية بثلثمائة دينار فلم تقبل فبقي إسحاق متحيرا يعجب من حالها وما انقلبت إليه وقال ابن المعتز حدثني الهشامي عن محمد بن راشد أن شارية كانت مولدة البصرة وكانت لها أم خبيثة منكرة تدعي أنها بنت محمد بن زيد من بني سامة بن لؤي قال ابن المعتز وحدثني غيره أنها كانت تدعي أنها من بني زهرة قال الهشامي فجيء بها إلى بغداد وعرضت على إبراهيم بن المهدي فأعجب بها إعجابا شديدا فلم يزل يعطي بها حتى بلغت ثمانية آلاف درهم فقال لي هبة الله بن إبراهيم بن المهدي إنه لم يكن عند أبي درهم ولا دانق فقال لي ويحك قد أعجبتني والله هذه الجارية إعجابا شديدا وليس عندنا شيء فقلت له نبيع ما نملكه حتى الخزف ونجمع ثمنها فقال لي قد فكرت في شيء اذهب إلى علي بن هشام فأقرئه مني السلام وقل له جعلني الله فداءك قد عرضت علي جارية قد أخذت بمجامع قلبي وليس عندي ثمنها فأحب أن تقرضني عشرة آلاف درهم فقلت له إن ثمنها ثمانية آلاف درهم فلم تكثر على الرجل بعشرة آلاف\nدرهم فقال إذا اشتريناها بثمانية آلاف درهم لا بد أن نكسوها ونقيم لها ما تحتاج إليه فصرت إلى علي بن هشام فأبلغته الرسالة فدعا بوكيل له وقال له ادفع إلى خادمه عشرين ألفا وقل له أنا لا أصلك ولكن هي لك حلال في الدنيا والآخرة قال فصرت إلى أبي بالدراهم فلو طلعت عليه بالخلافة لم تكن تعدل عنده تلك الدراهم وكانت أمها خبيثة فكانت كلما لم يعط إبراهيم ابنتها ما تشتهي ذهبت إلى عبد الوهاب بن علي ودفعت إليه رقعة يرفعها إلى المعتصم تسأله أن تأخذ ابنتها من إبراهيم قال ابن المعتز وأخبرني عبد الواحد بن إبراهيم بن محمد بن الخصيب قال ذكر يوسف بن إبراهيم المصري صاحب إبراهيم بن المهدي أن إبراهيم وجه به إلى عبد الوهاب بن علي في حاجة كانت له قال فلقيته وانصرفت من عنده فلم أخرج من دهليز عبد الوهاب حتى استقبلتني امرأة فلما نظرت في وجهي سترت وجهها فأخبرني شاكري أن المرأة هي أم شارية جارية إبراهيم فبادرت إلى إبراهيم وقلت له أدرك فإني رأيت أم شارية في دار عبد الوهاب وهي من تعلم وما يفجؤك","topic":"نسب لبيد وأخباره","topicNo":193,"sp":10,"spl":"أخبار شارية"},
{"id":"b193-12","bab":"الجزء 16","sec":"أخبار شارية","page":"ج16 ص5","text":"إلا حيلة قد أوقعتها فقال لي في جواب ذلك أشهدك أن جاريتي شارية صدقة على ميمونة بنت إبراهيم بن المهدي ثم أشهد ابنة هبة الله على مثل ذلك وأمرني بالركوب إلى دار ابن أبي دواد وإحضار من قدرت عليه من الشهود المعدلين عنده فأحضرته أكثر من عشرين شاهدا وأمر بإخراج شارية فخرجت فقال لها أسفري فجزعت من ذلك فأعلمها أنه إنما أمرها بذلك لخير يريده بها ففعلت فقال لها تسمي فقالت أنا شارية أمتك فقال لهم تأملوا وجهها ففعلوا ثم قال فإني أشهدكم أنها حرة لوجه الله تعالى وأني قد تزوجتها وأصدقتها عشرة آلاف درهم يا شارية مولاة إبراهيم بن المهدي أرضيت قالت نعم يا سيدي قد رضيت والحمد لله على ما أنعم به علي فأمرها بالدخول وأطعم الشهود وطيبهم وانصرفوا فما أحسبهم بلغوا دار ابن أبي دواد حتى دخل علينا عبد الوهاب بن علي فأقرأ عمه سلام المعتصم ثم قال له يقول لك يا أمير المؤمنين من المفترض علي طاعتك وصيانتك عن كل ما يعرك إذ كنت عمي وصنو أبي وقد رفعت إلي امرأة من قريش قصة ذكرت فيها أنها من بني زهرة صليبة وأنها أم شارية واحتجت بأنه لا تكون بنت امرأة من قريش أمة\nفإن كانت هذه المرأة صادقة في أن شارية بنتها وأنها من بني زهرة فمن المحال أن تكون شارية أمة والآشبه بك والأصلح إخراج شارية من دارك وسترها عند من تثق به من أهلك حتى نكشف ما قالت هذه المرأة فإن ثبت ما قالته أمرت من جعلتها عنده بإطلاقها وكان في ذلك الحظ لك في دينك ومروءتك وإن لم يصح ذلك أعيدت الجارية إلى منزلك وقد زال عنك القول الذي لا يليق بك ولا يحسن فقال له إبراهيم فديتك يا أبا إبراهيم هب شارية بنت زهرة بن كلاب أتنكر على ابن عباس بن عبد المطلب أن يكون بعلا لها فقال عبد الوهاب لا فقال إبراهيم فأبلغ أمير المؤمنين أطال الله بقاءه السلامة وأخبره أن شارية حرة وأني قد تزوجتها بشهادة جماعة من العدول وقد كان الشهود بعد منصرفهم من عند إبراهيم صاروا إلى ابن أبي دواد فشم منهم من رائحة الطيب ما أنكره فسألهم عنه فأعلموه أنهم حضروا عتق شارية وتزوج إبراهيم إياها فركب إلى المعتصم فحدثه بالحديث معجبا له منه فقال ضل سعي عبد الوهاب ودخل عبد الوهاب على المعتصم فلما رآه يمشي في صحن الدار سد المعتصم أنف نفسه وقال يا عبد الوهاب أنا أشم رائحة صوف محرق وأحسب أن عمي لم يقنعه ردك إلا وعلى أذنك صوفة حتى أحرقها فشممت رائحتها منك فقال الأمر على ما ظن أمير المؤمنين وأقبح ولما انصرف عبد الوهاب من عند إبراهيم ابتاع إبراهيم من بنته ميمونة شارية بعشرة آلاف درهم وستر ذلك عنها فكان عتقه إياها وهي في ملك غيره ثم ابتاعها من ميمونة فحل له فرجها فكان يطؤها على أنها أمته وهي تتوهم أنه يطؤها على أنها حرة فلما توفي طلبت مشاركة أم محمد بنت خالد زوجته في الثمن فأظهرت خبرها وسئلت ميمونة وهبة الله عن الخبر فأخبرا به المعتصم فأمر المعتصم بابتياعها من ميمونة فابتيعت بخمسة آلاف\nوخمسمائة دينار فحولت إلى داره فكانت في ملكه حتى توفي قال ابن المعتز وقد قيل إن المعتصم ابتاعها بثلثمائة ألف درهم قال وكان منصور بن محمد بن واضح يزعم أن إبراهيم اقترض ثمن شارية من ابنته وملكها إبراهيم ولها سبع سنين فرباها تربية الولد حتى لقد ذكرت أنها كانت في حجره جالسة وقد أعجب بصوت أخذته منه إذ طمثت أول طمثها فأحس بذلك فدعا قيمة له فأمرها بأن تأتيه بثوب خام فلفه عليها فقال احمليها فقد اقشعرت وأحسب برد الحش قد آذاها قال وحدثت شارية أنها كانت معه في حراقة قد توسط بها دجلة في ليلة مقمرة وهي تغني إذ اندفعت فغنت\n(لقد حثوا الجمال ليهربوا ... منا فلم يئلوا)\nقام إليها فأمسك فاها وقال أنت والله أحسن من الغريض وجها وغناء فما يؤمنني عليك أمسكي قال وحدث حمدون بن إسماعيل أنه دخل على إبراهيم يوما فقال له أتحب أن أسمعك شيئا لم تسمعه قط قال نعم فقال هاتوا شارية فخرجت فأمرها أن تغني لحن إسحاق\n(هل بالديار التي حييتها أحد ... )","topic":"نسب لبيد وأخباره","topicNo":193,"sp":11,"spl":"أخبار شارية","partial":1},
{"id":"b193-13","bab":"الجزء 16","sec":"أخبار شارية","page":"ج16 ص5","text":"قال حمدون فغنتني شيئا لم أسمع مثله قط فقلت لا والله يا سيدي ما سمعت هكذا فقال أتحب أن تسمعه أحسن من هذا فقلت لا يكون فقال بلى والله تقر بذاك فقلت على اسم الله فغناه هو فرأيت فضلا عجيبا فقلت ما ظننت أن هذا يفضل ذاك هذا الفضل قال أفتحب أن تسمعه أحسن من هذا وذاك فقلت هذا الذي لا يكون فقال بلى والله فقلت فهات قال بحياتي يا شارية قوليه وأحيلي حلقك فيه فسمعت والله فضلا بينا فأكثرت التعجب فقال لي يا أبا جعفر ما أهون هذا على السامع تدري بالله كم مرة رددت عليها موضعا في هذا الصوت قلت لا قال فقل وأكثر قلت مائة مرة قال اصعد ما بدا لك قلت ثلثمائة قال أكثر والله من ألف مرة حتى قالته كذا قال وكانت ريق تقول إن شارية كانت إذا اضطربت في صوت فغاية ما عنده من عقوبتها أنه يقيمها تغنيه على رجليها فإن لم تبلغ الذي يريد ضربت ريق قال ويقال إن شارية لم تضرب بالعود إلا في أيام المتوكل لما اتصل الشر بينها وبين عريب فصارت تقعد بها عند الضرب فضربت هي بعد ذلك","topic":"نسب لبيد وأخباره","topicNo":193,"sp":12,"spl":"أخبار شارية — إبراهيم يمتنع من بيعها"},
{"id":"b193-14","bab":"الجزء 16","sec":"إبراهيم يمتنع من بيعها","page":"ج16 ص13","text":"قال ابن المعتز وحدث محمد بن سهل بن عبد الكريم المعروف بسهل الأحول وكان قاضي الكتاب في زمانه وكان يكتب لإبراهيم وكان شيخا ثقة قال أعطى المعتصم إبراهيم بشارية سبعين ألف دينار فامتنع من بيعها فعاتبته على ذلك فلم يجبني بشيء ثم دعاني بعد أيام فدخلت وبين يديه مائدة لطيفة فأحضره الغلام سفودا فيه ثلاث فراريج فرمى إلي بواحدة فأكلتها وأكل اثنتين ثم شرب رطلا وسقانيه ثم أتي بسفود آخر ففعل كما فعل وشرب كما شرب وسقاني ثم ضرب سترا كان إلى جانبه فسمعت حركة العيدان ثم قال يا شارية تغني فسمعت شيئا ذهب بعقلي فقال يا سهل هذه التي عاتبتني في أن أبيعها بسبعين ألف دينار لا والله ولا هذه الساعة الواحدة بسبعين ألف دينار قال وكانت شارية تقول إن أباها من قريش وإنها سرقت صغيرة فبيعت بالبصرة من امرأة هاشمية وباعتها من إبراهيم بن المهدي والله أعلم أخبرني عمي قال حدثني عبيد الله بن عبد الله بن طاهر قال أمرني المعتز ذات يوم بالمقام عنده فأقمت فأمر فمدت الستارة وخرج\nمن كان يغني وراءها وفيهن شارية ولم أكن سمعتها قبل ذلك فاستحسنت ما سمعت منها فقال لي أمير المؤمنين المعتز يا عبيد الله كيف ما تسمع منها عندك فقلت حظ العجب من هذا الغناء أكثر من حظ الطرب فاستحسن ذلك وأخبرها به فاستحسنته قال ابن المعتز وأخبرني الهشامي قال قالت لي ريق كنت ألعب أنا وشارية بالنرد بين يدي إبراهيم وهو متكىء على مخدة ينظر إلينا فجرى بيني وبين شارية مشاجرة في اللعب فأغلظت لها في الكلام بعض الغلظة فاستوى إبراهيم جالسا وقال أراك تستخفين بها فوالله لا أحد يخلفك غيرها وأومأ إلى حلقه بيده قال وحدثني الهشامي قال حدثني عمرو بن بانة قال حضرت يوما مجلس المعتصم وضربت الستارة وخرجت الجواري وكنت إلى جانب مخارق فغنت شارية فأحسنت جدا فقلت لمخارق هذه الجارية في حسن الغناء على ما تسمع ووجهها وجه حسن فكيف لم\nيتحرم بها إبراهيم بن المهدي فقال لي أحد الحظوظ التي رفعت لهذا الخليفة منع إبراهيم بن المهدي من ذلك قال عبد الله بن المعتز وحدثني أبو محمد الحسن بن يحيى أخو علي بن يحيى عن ريق قالت استزار المعتصم من إبراهيم بن المهدي جواريه وكان في جفوة من السلطان تلك الأيام فنالته ضيقة قالت فتحمل ذهابنا إليه على ضعف فحضرنا مجلس المعتصم ونحن في سراويلات مرقعة فجعلنا نرى جواري المعتصم وما عليهن من الجوهر والثياب الفاخرة فلم تستجمع إلينا أنفسنا حتى غنوا وغنينا فطرب المعتصم على غنائنا ورآنا أمثل من جواريه فتحولت إلينا أنفسنا في التيه والصلف وأمر لنا المعتصم بمائة ألف درهم","topic":"نسب لبيد وأخباره","topicNo":193,"sp":12,"spl":"أخبار شارية — إبراهيم يمتنع من بيعها"},
{"id":"b193-15","bab":"الجزء 16","sec":"غناؤها وكرمها","page":"ج16 ص15","text":"قال وحدثني أبو العبيس عن أبيه قال كانت شارية أحسن الناس غناء منذ توفي المعتصم إلى آخر خلافة الواثق\nقال أبو العبيس وحدثتني ريق أن المعتصم افتضها وأنها كانت معها في تلك الليلة قال أبو العبيس وحدثتني طباع جارية الواثق أن الواثق كان يسميها ستي وكانت تعلم فريدة فلم تبق في تعليمها غاية إلى أن وقع بينهما شيء بحضرة الواثق فحلفت أنها لا تنصحها ولا تنصح أحدا بعدها فلم تكن تطرح بعد ذلك صوتا إلا نقصت من نغمه وكان المعتمد قد تعشق شرة جاريتها وكانت أكمل الناس ملاحة وخفة روح وعجز عن شرائها فسأل أم المعتز أن تشتريها له فاشترتها من شارية بعشرة آلاف دينار وأهدتها إليه ثم تزوجت بعد وفاة المعتمد بابن البقال المغني وكان يتعشقها فقال عبد الله بن المعتز وكان يتعشقها\n(أقول وقد ضاقت بأحزانها نفسي ... ألا رب تطليق قريب من العرس)\n(لئن صرت للبقال يا شر زوجة ... فلا عجب قد يربض الكلب في الشمس)\nوقال يعقوب بن بنان كانت شارية خاصة بصالح بن وصيف فلما بلغه رحيل موسى بن بغا من الجبل يريده بسبب قتله المعتز أودع شارية جوهره فظهر لها جوهر كثير بعد ذلك فلما أوقع موسى بصالح استترت شارية عند هارون بن شعيب العكبري وكان أنظف خلق الله طعاما وأسراه مائدة وأوسخه كل شيء بعد ذلك وكان له بسر من رأى منزل فيه بستان\nكبير وكانت شارية تسميه أبي وتزوره إلى منزله فتحتمل معها كل شيء تحتاج إليه حتى الحصير الذي تقعد عليه قال وكانت شارية من أكرم الناس عاشرها أبو الحسن علي بن الحسين عند هارون هذا ثم أضاق في وقت فاقترض منها على غير رهن عشرة آلاف دينار ومكثت عليه أكثر من سنة ما أذكرته بها ولا طالبته حتى ردها ابتداء قال يعقوب بن بنان وكان أهل سر من رأى متحازبين فقوم مع شارية وقوم مع عريب لا يدخل أصحاب هذه مع هؤلاء ولا أصحاب هذه في هؤلاء فكان أبو الصقر إسماعيل بن بلبل عريبيا فدعا علي بن الحسين يوم جمعة أبا الصقر إسماعيل بن بلبل وعنده عريب وجواريها فاتصل الخبر بشارية فبعثت بجواريها إلى علي بن الحسين بعد يوم أو يومين وأمرت إحداهن وما أدري من هي مهرجان أو مطرب أو قمرية إلا أنها إحدى الثلاثة أن تغني قوله\n(لا تعودن بعدها ... فترى كيف أصنع)\nلما سمع علي الغناء ضحك وقال لست أعود قال وكان المعتمد قد وثق بشارية فلم يكن يأكل إلا طعامها فمكثت دهرا من الدهور تعد له في كل يوم جونتين وكان طعامه منهما في أيام المتوكل قال ابن المعتز وحدثني أحمد بن نعيم عن ريق قالت كان مولاي إبراهيم يسمي شارية بنتي ويسميني أختي\nحدثني جحظة قال كنت عند المعتمد يوما فغنته شارية بشعر مولاها إبراهيم بن المهدي ولحنه\n(يا طول علة قلبي المعتاد ... إلف الكرام وصحبة الأمجاد)\nقال لها أحسنت والله فقالت هذا غنائي وأنا عارية فكيف لو كنت كاسية فأمر لها بألف ثوب من جميع أنواع الثياب الخاصية فحمل ذلك إليها فقال لي علي بن يحيى المنجم اجعل انصرافك معي ففعلت فقال لي هل بلغك أن خليفة أمر لمغنية بمثل ما أمر به أمير المؤمنين اليوم لشارية قلت لا فأمر بإخراج سير الخلفاء فأقبل بها الغلمان يحملونها في دفاتر عظام فتصفحناها كلها فما وجدنا أحدا قبله فعل ذلك","topic":"نسب لبيد وأخباره","topicNo":193,"sp":13,"spl":"غناؤها وكرمها"},
{"id":"b193-16","bab":"الجزء 16","sec":"نسبة هذا الصوت","page":"ج16 ص18","text":"\n(يا طول علة قلبي المعتاد ... إلف الكرام وصحبة الأمجاد)\n(ما زلت آلف كل قرم ماجد ... متقدم الآباء والأجداد)\nالشعر لإبراهيم بن المهدي والغناء لعلويه - خفيف رمل - لشارية بالبنصر ولم يقع إلينا فيه طريقة غير هذه أخبرني هاشم بن محمد الخزاعي قال حدثني عبد الله بن أبي سعيد قال حدثني محمد بن مالك الخزاعي قال حدثتني ملح العطارة وكانت من أحسن الناس غناء وإنما سميت العطارة لكثرة استعمالها العطر المطيب قالت غنت شارية يوما بين يدي المتوكل وأنا واقفة مع الجواري\n(بالله قولوا لي لمن ذا الرشا ... المثقل الردف الهضيم الحشا)\n(أظرف ما كان إذا ما صحا ... وأملح الناس إذا ما انتشى)\n(وقد بنى برج حمام له ... أرسل فيه طائرا مرعشا)\n(يا ليتني كنت حماما له ... أو باشقا يفعل بي ما يشا)\n(لو لبس القوهي من رقة ... أوجعه القوهي أو خدشا)\nهو - هزج - فطرب المتوكل وقال لشارية لمن هذا الغناء فقالت أخذته من دار المأمون ولا أدري لمن هو فقلت له أنا أعلم\nلمن هو فقال لمن هو يا ملح فقلت أقوله لك سرا قال أنا في دار النساء وليس يحضرني إلا حرمي فقوليه فقلت الشعر والغناء جميعا لخديجة بنت المأمون قالته في خادم لأبيها كانت تهواه وغنت فيه هذا اللحن فأطرق طويلا ثم قال لا يسمع هذا منك أحد\n(أحبك يا سلمى على غير ريبة ... وما خير حب لا تعف سرائره)\n(أحبك حبا لا أعنف بعده ... محبا ولكني إذا ليم عاذره)\n(وقد مات حبي أول الحب فانقضى ... ولو مت أضحى الحب قد مات آخره)\n(ولما تناهى الحب في القلب واردا ... أقام وسدت فيه عنه مصادره)\nلشعر للحسين بن مطير الأسدي والغناء لإسحاق هزج بالبنصر","topic":"نسب لبيد وأخباره","topicNo":193,"sp":14,"spl":"نسبة هذا الصوت","song":2},
{"id":"b194-1","bab":"الجزء 16","sec":"أخبار الحسين بن مطير ونسبه","page":"ج16 ص21","text":"هو الحسين بن مطير بن مكمل مولى لبني أسد بن خزيمة ثم لبني سعد بن مالك بن ثعلبة بن دودان بن أسد وكان جده مكمل عبدا فأعتقه مولاه وقيل بل كاتبه فسعى في مكاتبته حتى أداها وأعتق وهو من مخضرمي الدولتين الأموية والعباسية شاعر متقدم في القصيد والرجز فصيح قد مدح بني أمية وبني العباس أخبرني أحمد بن عبيد الله بن عمار عن محمد بن داود بن الجراح عن محمد بن الحسن بن الحرون أنه كان من ساكني زبالة وكان زيه وكلامه يشبه مذاهب الأعراب وأهل البادية وذلك بين في شعره ومما يدل على إدراكه دولة بني أمية ومدحه إياهم ما أخبرنا به يحيى بن علي بن يحيى إجازة قال أخبرني أبي عن إسحاق بن إبراهيم الموصلي عن مروان بن أبي حفصة قال دخلت أنا وطريح بن\nالثقفي والحسين بن مطير الأسدي في عدة من الشعراء على الوليد بن يزيد وهو في فرش قد غاب فيها وإذا رجل كلما أنشد شاعر شعرا وقف الوليد على بيت بيت منه وقال هذا أخذه من موضع كذا وكذا وهذا المعنى نقله من شعر فلان حتى أتى على أكثر الشعراء فقلت من هذا قالوا هذا حماد الراوية فلما وقفت بين يدي الوليد لأنشده قلت ما كلام هذا في مجلس أمير المؤمنين وهو لحانة فتهانف الشيخ ثم قال يا بن أخي أنا رجل أكلم العامة وأتكلم بكلامها فهل تروي من أشعار العرب شيئا فذهب عني الشعر كله إلا شعر ابن مقبل فقلت نعم لابن مقبل فأنشدته\n(سل الدار من جنبي جبر فواهب ... الى ما رأى هضب القليب المضيح)\nثم جزت فقال قف ماذا يقول فلم أدر ما يقول فقال يا بن أخي أنا أعلم الناس بكلام العرب يقال تراءى الموضعان إذا تقابلا","topic":"أخبار الحسين بن مطير ونسبه","topicNo":194,"sp":0,"spl":"أخبار الحسين بن مطير ونسبه — وفوده على معن بن زائدة"},
{"id":"b194-2","bab":"الجزء 16","sec":"وفوده على معن بن زائدة","page":"ج16 ص23","text":"أخبرني أحمد بن عبيد الله بن عمار والحسن بن علي ويحيى بن علي قالوا حدثنا الحسن بن عليل العنزي قال حدثنا أحمد بن عبد الله بن علي قال حدثني أبي أن الحسين بن مطير وفد على معن بن زائدة لما ولي اليمن وقد مدحه فلما دخل عليه أنشده\n(أتيتك إذ لم يبق غيرك جابر ... ولا واهب يعطي اللها والرغائبا)\nقال له معن يا أخا بني أسد ليس هذا بمدح إنما المدح قول نهار بن توسعة أخي بني تيم الله بن ثعلبة في مسمع بن مالك\n(قلدته عرا الأمور نزار ... قبل أن تهلك السراة البحور)\nال وأول هذا الشعر\n(اظعني من هراة قد مر فيها ... حجج مذ سكنتها وشهور)\n(اظعني نحو مسمع تجديه ... نعم ذو المنثنى ونعم المزور)\n(سوف يكفيك إن نبت بك أرض ... بخراسان أو جفاك أمير)\n(من بني الحصن عامل بن بريح ... لا قليل الندى ولا منزور)\n(والذي يفزع الكماة إليه ... حين تدمى من الطعان النحور)\n(فاصطنع يا بن مالك آل بكر ... واجبر العظم إنه مكسور)\nغدا إليه بأرجوزته التي مدحه بها وأولها\n(حديث ريا حبذا إدلالها ... )\n(تسأل عن حالي وما سؤالها ... )\n(عن امرىء قد شفه خيالها ... )\n(وهي شفاء النفس لو تنالها ... )\nقول فيها يمدحه\n(سل سيوفا محدثا صقالها ... )\n(صاب على أعدائه وبالها ... )\n(وعند معن ذي الندى أمثالها ... )\nفاستحسنها وأجزل صلته أخبرني ابن عمار ويحيى بن علي قالا حدثنا محمد بن القاسم بن مهرويه قال حدثني أبو المثنى أحمد ابن يعقوب ابن أخت أبي بكر الأصم قال كنا في مجلس الأصمعي فأنشده رجل لدعبل بن علي\n(أين الشباب وأية سلكا ... )\nاستحسنا قوله\n(لا تعجبي يا سلم من رجل ... ضحك المشيب برأسه فبكى)\nقال الأصمعي هذا أخذه من قول الحسين بن مطير\n(أين أهل القباب بالدهناء ... أين جيراننا على الأحساء)\n(فارقونا والأرض ملبسة نور ... الأقاحي يجاد بالأنواء)\n(كل يوم بأقحوان جديد ... تضحك الأرض من بكاء السماء)\nخبرني يحيى بن علي بن يحيى قال حدثني محمد بن القاسم الدينوري قال حدثني محمد بن عمران الضبي قال","topic":"أخبار الحسين بن مطير ونسبه","topicNo":194,"sp":0,"spl":"أخبار الحسين بن مطير ونسبه — وفوده على معن بن زائدة","partial":1},
{"id":"b194-3","bab":"الجزء 16","sec":"أبياته تسهر المهدي","page":"ج16 ص26","text":"قال المهدي للمفضل الضبي أسهرتني البارحة أبيات الحسين بن مطير الأسدي قال وما هي يا أمير المؤمنين قال قوله\n(وقد تغدر الدنيا فيضحي فقيرها ... غنيا ويغنى بعد بؤس فقيرها)\n(فلا تقرب الأمر الحرام فإنه ... حلاوته تفنى ويبقى مريرها)\n(وكم قد رأينا من تغير عيشة ... وأخرى صفا بعد اكدرار غديرها)\nقال له المفضل مثل هذا فليسهرك يا أمير المؤمنين وقد أخبرني بهذا الخبر عمي رحمه الله أتم من هذا قال نسخت من كتاب المفضل بن سلمة قال أبو عكرمة الضبي قال المفضل الضبي كنت يوما جالسا على بابي وأنا محتاج إلى درهم وعلي عشرة آلاف درهم إذ جاءني رسول المهدي فقال أجب أمير المؤمنين فقلت ما بعث إلي في هذا الوقت إلا لسعاية ساع وتخوفته لخروجي كان مع إبراهيم بن\nعبد الله بن حسن فدخلت منزلي فتطهرت ولبست ثوبين نظيفين وصرت إليه فلما مثلت بين يديه سلمت فرد علي وأمرني بالجلوس فلما سكن جأشي قال لي يا مفضل أي بيت قالته العرب أفخر فتشككت ساعة ثم قلت بيت الخنساء وكان مستلقيا فاستوى جالسا ثم قال وأي بيت هو قلت قولها\n(وإن صخرا لتأتم الهداة به ... كأنه علم في رأسه نار)\nأومأ إلى إسحاق بن بزيع ثم قال قد قلت له ذلك فأباه فقلت الصواب ما قاله أمير المؤمنين ثم قال حدثني يا مفضل قلت أي الحديث أعجب إلى أمير المؤمنين قال حديث النساء فحدثته حتى انتصف النهار ثم قال لي يا مفضل أسهرني البارحة بيتا ابن مطير وأنشد البيتين المذكورين في الخبر الأول ثم قال ألهذين ثالث يا مفضل قلت نعم يا أمير المؤمنين فقال وما هو فأنشدته قوله\n(وكم قد رأينا من تغير عيشة ... وأخرى صفا بعد اكدرار غديرها)\nوكان المهدي رقيقا فاستعبر ثم قال يا مفضل كيف حالك قلت كيف يكون حال من هو مأخوذ بعشرة آلاف درهم فأمر لي بثلاثين ألف درهم وقال اقض دينك وأصلح شأنك فقبضتها وانصرفت","topic":"أخبار الحسين بن مطير ونسبه","topicNo":194,"sp":1,"spl":"أبياته تسهر المهدي"},
{"id":"b194-4","bab":"الجزء 16","sec":"مدحه المهدي","page":"ج16 ص28","text":"أخبرني يحيى بن علي عن علي بن يحيى إجازة وحدثنا الحسن بن علي قال حدثنا محمد بن القاسم عن عبد الله بن أبي سعد قال حدثني إسحاق بن عيسى بن موسى بن مجمع أحد بني سوار بن الحارث الأسدي قال أخبرني جدي موسى بن مجمع قال قال الحسين بن مطير في المهدي قصيدته التي يقول فيها\n(إليك أمير المؤمنين تعسفت ... بنا البيد هوجاء النجاء خبوب)\n(ولو لم يكن قدامها ما تقاذفت ... جبال بها مغبرة وسهوب)\n(فتى هو من غير التخلق ماجد ... ومن غير تأديب الرجال أديب)\n(علا خلقه خلق الرجال وخلقه ... إذا ضاق أخلاق الرجال رحيب)\n(إذا شاهد القواد سار أمامهم ... جريء على ما يتقون وثوب)\n(وإن غاب عنهم شاهدتهم مهابة ... بها يقهر الأعداء حين يغيب)\n(يعف ويستحيي إذا كان خاليا ... كما عف واستحيا بحيث رقيب)\nلما أنشدها المهدي أمر له بسبعين ألف درهم وحصان جواد وكان الحسين من الثعلبية وتلك داره بها قال ابن أبي سعد وأرانيها الشيخ\nأخبرني محمد بن خلف وكيع قال حدثني محمد بن القاسم بن مهرويه قال حدثني عبد الله بن أبي سعد عن إسحاق بن عيسى قال دخل الحسين بن مطير على المهدي فأنشده قوله\n(لو يعبد الناس يا مهدي أفضلهم ... ما كان في الناس إلا أنت معبود)\n(أضحت يمينك من جود مصورة ... لا بل يمينك منها صور الجود)\n(لو أن من نوره مثقال خردلة ... في السود طرا إذن لابيضت السود)\nأمر له لكل بيت بألف درهم أخبرني أحمد بن عبيد الله بن عمار قال حدثني أحمد بن سليمان بن أبي شيخ قال حدثني أبي قال خرج المهدي يوما فلقيه الحسين بن مطير فأنشده قوله\n(أضحت يمينك من جود مصورة ... لا بل يمينك منها صور الجود)\nقال كذبت يا فاسق وهل تركت من شعرك موضعا لأحد بعد قولك في معن بن زائدة حيث تقول\n(ألما بمعن ثم قولا لقبره ... سقيت الغوادي مربعا ثم مربعا)\nأخرجوه عني فأخرجوه وتمام الأبيات\n(أيا قبر معن كنت أول حفرة ... من الأرض خطت للمكارم مضجعا)\n(أيا قبر معن كيف واريت جوده ... وقد كان منه البر والبحر مترعا)\n(بلى قد وسعت الجود والجود ميت ... ولو كان حيا ضقت حتى تصدعا)\n(فتى عيش في معروفه بعد موته ... كما كان بعد السيل مجراه ممرعا)\n(أبى ذكر معن أن تموت فعاله ... وإن كان قد لاقى حماما ومصرعا)\nخبرني أحمد بن يحيى بن علي بن يحيى إجازة قال حدثني ابن مهرويه قال حدثني علي بن عبيد الكوفي قال حدثني الحسين بن أبي الخصيب الكاتب عن أحمد بن يوسف الكاتب قال كنت أنا وعبد الله بن طاهر عند المأمون وهو مستلق على قفاه فقال لعبد الله بن طاهر يا أبا العباس من أشعر من قال الشعر في خلافة بني هاشم قال أمير المؤمنين أعلم بهذا وأعلى عينا فقال له على ذاك فقل وتكلم أنت أيضا يا أحمد بن يوسف فقال عبد الله بن طاهر أشعرهم الذي يقول\n(أيا قبر معن كنت أول خطة ... من الأرض خطت للمكارم مضجعا)\nقال أحمد بن يوسف بل أشعرهم الذي يقول\n(وقف الهوى بي حيث أنت فليس لي ... متأخر عنه ولا متقدم)\nقال أبيت يا أحمد إلا غزلا أين أنتم عن الذي يقول\n(يا شقيق النفس من حكم ... نمت عن ليلى ولم أنم)\nخبرني الحسن بن علي قال حدثنا أبو خليفة عن التوزي قال قلت لأبي عبيدة ما تقول في شعر الحسين بن مطير فقال والله لوددت أن الشعراء قاربته في قوله\n(مخصرة الأوساط زانت عقودها ... بأحسن مما زينتها عقودها)\n(فصفر تراقيها وحمر أكفها ... وسود نواصيها وبيض خدودها)","topic":"أخبار الحسين بن مطير ونسبه","topicNo":194,"sp":2,"spl":"مدحه المهدي"},
{"id":"b194-5","bab":"الجزء 16","sec":"شعره في وصف السحاب والمطر","page":"ج16 ص32","text":"أخبرني علي بن سليمان الأخفش قال أنشدنا محمد بن يزيد للحسين بن مطير قال كان سبب قوله هذه الأبيات أن واليا ولي المدينة فدخل عليه الحسين بن مطير فقيل له هذا من أشعر الناس فأراد أن يختبره وقد كانت سحابة مكفهرة نشأت وتتابع منها الرعد والبرق وجاءت بمطر جود فقال له صف هذه السحابة فقال\n(مستضحك بلوامع مستعبر ... بمدامع لم تمرها الأقذاء)\n(فله بلا حزن ولا بمسرة ... ضحك يراوح بينه وبكاء)\n(كثرت لكثرة ودقه أطباؤه ... فإذا تحلب فاضت الأطباء)\n(وكأن بارقه حريق تلتقي ... ريح عليه وعرفج وألاء)\n(لو كان من لجج السواحل ماؤه ... لم يبق في لجج السواحل ماء)\n\n(إذا ما أم عبد الله ... لم تحلل بواديه)\n(ولم تمس قريبا هيج ... الحزن دواعيه)\n(غزال راعه القناص ... تحميه صياصيه)\n(وما ذكري حبيبا وقليل ... ما أواتيه)\n(كذي الخمر تمناها ... وقد أنزف ساقيه)\n(عرفت الربع بالإكليل ... عفته سوافيه)\n(بجو ناعم الحوذان ... ملتف روابيه)\nالشعر مختلط بعضه للنعمان بن بشير الأنصاري وبعضه ليزيد بن معاوية فالذي للنعمان بن بشير منه الثلاثة الأبيات الأول والبيت الأخير وباقيها ليزيد بن معاوية ورواه من يوثق به وبروايته لنوفل بن أسد بن عبد العزى فأما من ذكر أنه للنعمان بن بشير فأبو عمرو الشيباني وجدت ذلك عنه في كتابه وخالد بن كلثوم نسخته من كتاب أبي سعيد السكري في مجموع شعر النعمان وتمام الأبيات للنعمان بن بشير بعد الأربعة الأبيات التي نسبتها إليه فإنها متوالية قال\n(فبحت اليوم بالأمر اللذي ... قد كنت تخفيه)\n(فإن أكتمه يوما ... فإني سوف أبديه)\n(وما زلت أفديه ... وأدنيه وأرقيه)\n(وأسعى في هواه أبدا حتى ألاقيه ... )\n(فبات الريم مني حذرا ... زلت مراقيه)\nالغناء لمعبد - خفيف رمل - بالوسطى عن عمرو وذكره إسحاق في - خفيف الرمل - بالسبابة في مجرى البنصر ولم ينسبه إلى أحد وفيه للغريض - ثقيل - أول بالوسطى عن الهشامي وحنين","topic":"أخبار الحسين بن مطير ونسبه","topicNo":194,"sp":3,"spl":"شعره في وصف السحاب والمطر","song":1,"partial":1},
{"id":"b195-1","bab":"الجزء 16","sec":"أخبار النعمان بن بشير ونسبه","page":"ج16 ص35","text":"هو النعمان بن بشير بن سعد بن ثعلبة بن خلاس بن زيد بن مالك الأغر بن ثعلبة بن كعب بن الخزرج بن الحارث بن الخزرج وأمه عمرة بنت رواحة أخت عبد الله بن رواحة التي يقول فيها قيس بن الخطيم\n(أجد بعمرة غنيانها ... فتهجر أم شاننا شانها)\n(وعمرة من سروات النساء ... تنفح بالمسك أردانها)\nله صحبة بالنبي ولأبيه بشير بن سعد وكان جاء إلى النبي\nومعه آخر ليشهد معه غزوة له فيما قيل فاستصغرهما فردهما وأبوه بشير بن سعد أول من قام يوم السقيفة من الأنصار إلى أبي بكر رضي الله عنه فبايعه ثم توالت الأنصار فبايعته وشهد بشير بيعة العقبة وبدرا وأحدا والخندق والمشاهد كلها واستشهد يوم عين التمر مع خالد بن الوليد وكان النعمان عثمانيا وشهد مع معاوية صفين ولم يكن معه من الأنصار غيره وكان كريما عليه رفيعا عنده وعند يزيد ابنه بعده وعمر إلى خلافة مروان بن الحكم وكان يتولى حمص فلما بويع لمروان دعا إلى ابن الزبير وخالف على مروان وذلك بعد قتل الضحاك بن قيس بمرج راهط فلم يجبه أهل حمص إلى ذلك فهرب منهم وتبعوه فأدركوه فقتلوه وذلك في سنة خمس وستين ويقال إن النعمان بن بشير أول مولود ولد بالمدينة بعد قدوم رسول الله إياها وقد قيل ذلك في عبد الله بن الزبير إلا أن النعمان أول مولود ولد بعد\nمقدمه من الأنصار روى ذلك عبد الله بن أبي بكر بن محمد بن عمرو بن حزم وروى النعمان بن بشير عن النبي كثيرا حدثني أحمد بن محمد بن الجعد الوشاء قال حدثني أبو بكر بن أبي شيبة قال حدثنا عباد بن العوام عن الحصين عن الشعبي قال سمعت النعمان بن بشير يقول أعطاني أبي عطية فقالت أمي عمرة لا أرضى حتى تشهد رسول الله فأتى رسول الله فقال ابني من عمرة أعطيته عطية فأمرتني أن أشهدك فقال أعطيت كل ولدك مثل هذا قال لا فقال فاتقوا الله واعدلوا بين أولادكم أخبرني محمد بن خلف وكيع قال حدثنا محمد بن سعيد قال حدثنا العمري عن الهيثم بن عدي عن مجالد عن الشعبي قال أمر معاوية لأهل الكوفة بزيادة عشرة دنانير في أعطيتهم وعامله يومئذ على الكوفة وأرضها النعمان بن بشير وكان عثمانيا وكان يبغض أهل الكوفة لرأيهم في علي عليه السلام فأبى النعمان أن ينفذها لهم فكلموه وسألوه بالله فأبى أن يفعل وكان إذا خطب على المنبر أكثر قراءة القرآن وكان يقول لا ترون على منبركم هذا أحدا بعدي يقول إنه سمع رسول الله فصعد المنبر يوما فقال يا أهل الكوفة فصاحوا ننشدك الله والزيادة فقال اسكتوا فلما أكثروا قال أتدرون ما مثلي ومثلكم قالوا لا قال مثل\nالضبع والضب والثعلب فإن الضبع والثعلب أتيا الضب في وجاره فنادياه أبا الحسل فقال سميعا دعوتما قالا أتيناك لتحكم بيننا قال في بيته يؤتى الحكم قالت الضبع إني حللت عيبتي قال فعل الحرة فعلت قال فلقطت ثمرة قال طيبا لقطت قالت فأكلها الثعلب قال لنفسه نظر قالت فلطمته قال بجرمه قالت فلطمني قال حر انتصر قالت فاقض بيننا قال قد فعلت قال حدث امرأة حديثين فإن أبت فعشرة فقال عبد الله بن همام السلولي\n(زيادتنا نعمان لا تحبسنها ... خف الله فينا والكتاب الذي تتلو)\n(فإنك قد حملت منا أمانة ... بما عجزت عنه الصلاخمة البزل)\n(فلا يك باب الشر تحسن فتحه ... وباب الندى والخيرات له قفل)\n(وقد نلت سلطانا عظيما فلا يكن ... لغيرك جمات الندى ولك البخل)\n(وأنت امرؤ حلو اللسان بليغه ... فما باله عند الزيادة لا يحلو)\n(وقبلك قد كانوا علينا أئمة ... يهمهم تقويمنا وهم عصل)\n(إذا نصبوا للقول قالوا فأحسنوا ... ولكن حسن القول خالفه الفعل)\n(يذمون دنياهم وهم يرضعونها ... أفاويق حتى ما يدر لهم ثعل)\n(فيا معشر الأنصار إني أخوكم ... وإني لمعروف أنى منكم أهل)\n(ومن أجل إيواء النبي ونصره ... يحبكم قلبي وغيركم الأصل)\nقال النعمان بن بشير لا عليه ألا يتقرب فوالله لا أجيزها ولا أنفذها أبدا","topic":"أخبار النعمان بن بشير ونسبه","topicNo":195,"sp":0,"spl":"أخبار النعمان بن بشير ونسبه"},
{"id":"b195-2","bab":"الجزء 16","sec":"النعمان يقول عزة تزيد النفس طيبا","page":"ج16 ص39","text":"أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثنا الأصمعي قال حدثني شيخ قديم من أهل المدينة وأخبرني إسماعيل بن يونس الشيعي قال حدثنا عمر بن شبة قال حدثنا أبو غسان عن أبي السائب المخزومي وأخبرني الحسين بن يحيى المرداسي عن\nحماد بن إسحاق عن أبيه قال ذكر لي عن جعفر بن محرز الدوسي قال دخل النعمان بن بشير المدينة في أيام يزيد بن معاوية وابن الزبير فقال والله لقد أخفقت أذناي من الغناء فأسمعوني فقيل له لو وجهت إلى عزة الميلاء فإنها من قد عرفت فقال إي ورب الكعبة إنها لممن تزيد النفس طيبا والعقل شحذا ابعثوا إليها عن رسالتي فإن أبت صرت إليها فقال له بعض القوم إن النقلة تشتد عليها لثقل بدنها وما بالمدينة دابة تحملها فقال النعمان بن بشير وأين النجائب عليها الهوادج فوجه إليها بنجب فذكرت علة فلما عاد الرسول إلى النعمان قال لجليسه أنت كنت أخبر بها قوموا بنا فقام هو مع خواص أصحابه حتى طرقوها فأذنت وأكرمت واعتذرت فقبل النعمان عذرها وقال لها غني فغنت\n(أجد بعمرة غنيانها ... فتهجر أم شاننا شانها)\n(وعمرة من سروات النساء ... تنفح بالمسك أردانها)\nال فأشير إليها أنها أمه فأمسكت فقال غني فوالله ما ذكرت إلا كرما وطيبا ولا تغني سائر اليوم غيره فلم تزل تغنيه هذا اللحن فقط حتى انصرف قال إسحاق فتذاكروا هذا الحديث عند الهيثم بن عدي فقال ألا أزيدكم فيه طريفة فقلنا بلى يا أبا عبد الرحمن فقال قال لقيط ونحن\nعند سعيد الزبيري قال عامر الشعبي اشتاق النعمان بن بشير إلى الغناء فصار إلى منزل عزة الميلاء فلما انصرف إذا امرأة بالباب منتظرة له فلما خرج شكت إليه كثرة غشيان زوجها إياها فقال النعمان لأقضين بينكما بقضية لا ترد علي قد أحل الله له من النساء أربعا مثنى وثلاث ورباع له مرتان بالنهار ومرتان بالليل أخبرني محمد بن الحسن بن دريد قال حدثني عمي عن العباس بن هشام عن أبيه وأخبرني الحسين بن يحيى عن حماد عن أبيه عن الكلبي وأخبرني عمي قال حدثنا الكراني قال حدثني العمري عن الهيثم بن عدي قالوا","topic":"أخبار النعمان بن بشير ونسبه","topicNo":195,"sp":1,"spl":"النعمان يقول عزة تزيد النفس طيبا","song":1},
{"id":"b195-3","bab":"الجزء 16","sec":"الأعشى يمدح النعمان والأخطل يهجو الأنصار","page":"ج16 ص41","text":"خرج أعشى همدان إلى الشام في ولاية مروان بن الحكم فلم ينل فيها حظا فجاء إلى النعمان بن بشير وهو عامل على حمص فشكا إليه حاله فكلم له النعمان اليمانية وقال لهم هذا شاعر اليمن ولسانها واستماحهم له فقالوا نعم يعطيه كل واحد منا دينارين من عطائه فقال أعطوه دينارا واجعلوا ذلك معجلا فقالوا له أعطه إياه من بيت المال واحتسب ذلك على كل رجل من عطائه ففعل النعمان ذلك وكانوا عشرين\nألفا فأعطاه عشرين ألف دينار وارتجعها منهم عند العطاء فقال الأعشى يمدح النعمان\n(ولم أر للحاجات عند التماسها ... كنعمان نعمان الندى ابن بشير)\n(إذا قال أوفى ما يقول ولم يكن ... كمدل إلى الأقوام حبل غرور)\n(متى أكفر النعمان لا ألف شاكرا ... وما خير من لا يقتدي بشكور)\n(فلولا أخو الأنصار كنت كنازل ... ثوى ما ثوى لم ينقلب بنقير)\nخبرني أحمد بن عبد العزيز الجوهري وحبيب بن نصر المهلبي قالا حدثنا عمر بن شبة قال حدثنا يحيى الزبيري قال حدثني ابن أبي زريق قال شبب عبد الرحمن بن حسان برملة بنت معاوية فقال\n(رمل هل تذكرين يوم غزال ... إذ قطعنا مسيرنا بالتمني)\n(إذ تقولين عمرك الله هل شيء ... وإن جل سوف يسليك عني)\n(أم هل اطمعت منكم يا بن حسان ... كما قد أراك أطعمت مني)\nفبلغ ذلك يزيد بن معاوية فغضب ودخل على معاوية فقال يا أمير المؤمنين ألا ترى إلى هذا العلج من أهل يثرب يتهكم بأعراضنا ويشبب بنسائنا فقال ومن هو قال عبد الرحمن بن حسان وأنشده ما\nقال فقال يا يزيد ليس العقوبة من أحد أقبح منها بذوي القدرة ولكن أمهل حتى يقدم وفد الأنصار ثم اذكرني به فلما قدموا أذكره به فلما دخلوا قال يا عبد الرحمن ألم يبلغني أنك شببت برملة بنت أمير المؤمنين قال بلى ولو علمت أن أحدا أشرف لشعري منها لذكرته فقال فأين أنت عن أختها هند قال وإن لها لأختا يقال لها هند قال نعم وإنما أراد معاوية أن يشبب بهما جميعا فيكذب نفسه قال فلم يرض يزيد ما كان من معاوية في ذلك فأرسل إلى كعب بن الجعيل فقال اهج الأنصار فقال أفرق من أمير المؤمنين ولكن أدلك على هذا الشاعر الكافر الماهر الأخطل قال فدعاه فقال له اهج الأنصار فقال أفرق من أمير المؤمنين قال لا تخف شيئا أنا بذلك لك فهجاهم فقال\n(وإذا نسبت ابن الفريعة خلته ... كالجحش بين حمارة وحمار)\n(لعن الإله من اليهود عصابة ... بالجزع بين صليصل وصدار)\n(قوم إذا هدر العصير رأيتهم ... حمرا عيونهم من المسطار)\n(خلوا المكارم لستم من أهلها ... وخذوا مساحيكم بني النجار)\n(إن الفوارس يعرفون ظهوركم ... أولاد كل مقبح أكار)\n(ذهبت قريش بالمكارم والعلا ... واللؤم تحت عمائم الأنصار)\nبلغ ذلك النعمان بن بشير فدخل على معاوية فحسر عمامته عن رأسه وقال يا أمير المؤمنين أترى لؤما قال بل أرى كرما وخيرا فما ذاك قال زعم الأخطل أن اللؤم تحت عمائم الأنصار قال أوفعل ذلك قال نعم قال لك لسانه وكتب فيه أن يؤتى به فلما أتى به سأل الرسول أن يدخله إلى يزيد أولا فأدخله عليه فقال له هذا الذي كنت أخاف قال لا تخف شيئا ودخل إلى معاوية فقال علام أرسل إلى هذا الرجل الذي يمدحنا ويرمي من وراء جمرتنا قال هجا الأنصار قال ومن زعم ذلك قال النعمان بن بشير قال لا تقبل قوله عليه وهو المدعي لنفسه ولكن تدعوه بالبينة فإن أثبت شيئا أخذت به له فدعاه بالبينة فلم يأت بها فخلى سبيله فقال الأخطل\n(وإني غداة استعبرت أم مالك ... لراض من السلطان أن يتهددا)\n(ولولا يزيد ابن الملوك وسعيه ... تجللت حدبارا من الشر أنكدا)\n(فكم أنقذتني من خطوب حباله ... وخرساء لو يرمى بها الفيل بلدا)\n(ودافع عني يوم جلق غمرة ... وهما ينسيني الشراب المبردا)\n(وبات نجيا في دمشق لحية ... إذا هم لم ينم السليم وأقصدا)\n(يخافته طورا وطورا إذا رأى ... من الوجه إقبالا ألح وأجهدا)\n(أبا خالد دافعت عني عظيمة ... وأدركت لحمي قبل أن يتبددا)\n(وأطفأت عني نار نعمان بعدما ... أغذ لأمر فاجر وتجردا)\n(ولما رأى النعمان دوني ابن حرة ... طوى الكشح إذ لم يستطعني وعردا)","topic":"أخبار النعمان بن بشير ونسبه","topicNo":195,"sp":2,"spl":"الأعشى يمدح النعمان والأخطل يهجو الأنصار"},
{"id":"b195-4","bab":"الجزء 16","sec":"الأعشى يمدح النعمان والأخطل يهجو الأنصار","page":"ج16 ص41","text":"دثني عمي قال حدثنا احمد بن الحارث الخراز عن المدائني عن أبي بكر الهذلي قال لما أمر يزيد بن معاوية بن كعب بن الجعيل بهجاء الأنصار قال له أرادي أنت إلى الكفر بعد الإسلام أأهجو قوما آووا رسول الله ونصروه قال أما إذ كنت غير فاعل فأرشدني إلى من يفعل ذلك قال غلام منا خبيث الدين نصراني فدله على الأخطل أخبرنا محمد بن الحسن بن دريد قال حدثنا أبو حاتم عن أبي عبيدة عن أبي الخطاب قال لما كثر الهجاء بين عبد الرحمن بن حسان بن ثابت وعبد الرحمن بن\nالحكم بن أبي العاص وتفاحشا كتب معاوية إلى سعيد بن العاص وهو عامله على المدينة أن يجلد كل واحد منهما مئة سوط وكان ابن حسان صديقا لسعيد وما مدح أحدا غيره قط فكره أن يضربه أو يضرب ابن عمه فأمسك عنهما ثم ولى مروان فلما قدم أخذ ابن حسان فضربه مئة سوط ولم يضرب أخاه فكتب ابن حسان إلى النعمان بن بشير وهو بالشام وكان كبيرا أثيرا مكينا عند معاوية\n(ليت شعري أغائب ليس بالشام ... خليلي أم راقد نعمان)\n(أية ما يكن فقد يرجع الغائب ... يوما ويوقظ الوسنان)\n(إن عمرا وعامرا أبوينا ... وحراما قدما على العهد كانوا)\n(أفهم مانعوك أم قلة الكتاب ... أم أنت عاتب غضبان)\n(أم جفاء أم أعوزتك القراطيس ... أم امري به عليك هوان)\n(يوم أنبئت أن ساقي رضت ... وأتتكم بذلك الركبان)\n(ثم قالوا إن ابن عمك في بلوى ... أمور أتى بها الحدثان)\n(فنسيت الأرحام والود والصحبة ... فيما أتت به الأزمان)\n(إنما الرمح فاعلمن قناة ... أو كبعض العيدان لولا السنان)\nوهي قصيدة طويلة فدخل النعمان بن بشير على معاوية فقال يا أمير المؤمنين إنك أمرت سعيدا بأن يضرب ابن حسان وابن الحكم مئة مئة فلم يفعل ثم وليت أخاه فضرب ابن حسان ولم يضرب أخاه قال فتريد ماذا قال أن تكتب إليه بمثل ما كتبت به إلى سعيد فكتب معاوية إليه يعزم عليه أن يضرب أخاه مئة فضربه خمسين وبعث إليه ابن حسان بحلة وسأله أن يعفو عن خمسين ففعل وقال لأهل المدينة إنما ضربني حد الحر مئة وضربه حد العبد خمسين فشاعت هذه الكلمة حتى بلغت ابن الحكم فجاء إلى أخيه فأخبره وقال لا حاجة لي فيما عفا عنه ابن حسان فبعث إليه مروان لا حاجة لنا فيما تركت فهلم فاقتص من صاحبك فحضر فضربه به مروان خمسين أخرى أخبرني الحسن بن علي قال أخبرنا أحمد بن الحارث قال حدثنا المدائني عن يعقوب بن داود الثقفي ومعاوية بن محارب أن معاوية تزوج امرأة من كلب فقال لامرأته ميسون أم يزيد بن\nمعاوية ادخلي فانظري إلى ابنة عمك هذه فأتتها فنظرت إليها ثم رجعت فقالت ما رأيت مثلها ولقد رأيت خالا تحت سرتها ليوضعن تحت مكانه في حجرها رأس زوجها فتطير من ذلك فتزوجها حبيب بن سلمة ثم طلقها فتزوجها النعمان بن بشير فلما قتل وضعوا رأسه في حجرها قالوا وكان النعمان بن بشير لما قتل الضحاك بن قيس بمرج راهط في خلافة مروان بن الحكم أراد أن يهرب من حمص وكان عاملا عليها فخالف ودعا لابن الزبير فطلبه أهل حمص فقتلوه واحتزوا رأسه فقالت امرأته هذه الكلبية ألقوا رأسه في حجري فأنا أحق به فألقوه في حجرها فضمته إلى جسده وكفنته ودفنته أخبرني هاشم بن محمد أبو دلف الخزاعي قال حدثنا أبو غسان دماذ قال حدثنا أبو عبيدة قال نظر معاوية إلى رجل في مجلسه فراقه حسنا وشارة وجسما فاستنطقه فوجده سديدا فقال له ممن أنت قال ممن أنعم الله عليه بالإسلام فاجعلني حيث شئت يا أمير المؤمنين قال عليك بهذه الأزد الطويلة العريضة الكثير عددها التي لا تمنع من دخل فيهم ولا تبالي من خرج منهم فغضب النعمان بن بشير ووثب من بين يديه وقال أما والله إنك ما علمت لسيء المجالسة لجليسك عاق بزورك قليل الرعاية لأهل الحرمة بك فأقسم عليه إلا جلس فجلس فضاحكه معاوية طويلا ثم قال له إن قوما أولهم غسان وآخرهم الأنصار لكرام وسأله عن حوائجه فقضاها حتى رضي","topic":"أخبار النعمان بن بشير ونسبه","topicNo":195,"sp":3,"spl":"الأعشى يمدح النعمان والأخطل يهجو الأنصار"},
{"id":"b195-5","bab":"الجزء 16","sec":"باكورة شعر النعمان","page":"ج16 ص49","text":"نسخت من كتاب أبي سعيد السكري بخطه أخبرنا ابن حبيب قال قال خالد بن كلثوم خرج النعمان بن بشير في ركب من قومه وهو يومئذ حديث السن حتى نزلوا بأرض من الأردن يقال لها حفير وحاضرتها بنو القين فأهدت لهم امرأة من بني القين يقال لها ليلى هدية فبينا القوم يتحدثون ويذكرون الشعراء إذ قال بعضهم يا نعمان هل قلت شعرا قال لا والله ما قلت فقال شيخ من الحارث بن الخزرج يقال له ثابت بن سماك لم تقل شعرا قط قال لا قال فأقسم عليك لتربطن إلى هذه السرحة فلا تفارقها حتى يرتحل القوم أو تقول شعرا فقال عند ذلك وهو أول شعر قاله\n(يا خليلي ودعا دار ليلى ... ليس مثلي يحل دار الهوان)\n(إن قينية تحل محبا ... وحفيرا فجنبتي ترفلان)\n(لا تؤاتيك في المغيب إذا ما ... حال من دونها فروع قنان)\n(إن ليلى ولو كلفت بليلى ... عاقها عنك عائق غيروان)\nقال وضرب الدهر على ذلك وأتى عليه زمن طويل ثم إن ليلى\nالقينية قدمت عليه بعد ذلك وهو أمير على حمص فلما رآها عرفها فأنشأ يقول\n(ألا استأذنت ليلى فقلنا لها لجي ... ومالك ألا تدخلي بسلام)\n(فإن أناسا زرتهم ثم حرموا ... عليك دخول البيت غير كرام)\nأحسن صلتها ورفدها طول مقامها إلى أن رحلت عنه أخبرني عمي قال حدثنا عبد الله بن أبي سعد قال حدثني محمد بن الحسن بن مسعود عن أبيه عن مشيخة من الأنصار قال حضرت وفود الأنصار باب معاوية بن أبي سفيان فخرج إليهم حاجبه سعد أبو درة وقد حجب بعده عبد الملك بن مروان فقالوا له استأذن للأنصار فدخل إليه وعنده عمرو بن العاص فاستأذن لهم فقال له عمرو ما هذا اللقب يا أمير المؤمنين اردد القوم إلى أنسابهم فقال معاوية إني أخاف من ذلك الشنعة فقال هي كلمة تقولها إن مضت عضتهم ونقصتهم وإلا فهذا الاسم راجع إليهم فقال له اخرج فقل من كان ههنا من ولد عمرو بن عامر فليدخل فقالها الحاجب فدخل ولد عمرو بن عامر كلهم إلا الأنصار فنظر معاوية إلى عمرو نظرا منكرا فقال له باعدت جدا فقال اخرج\nفقل من كان ههنا من الأوس والخزرج فليدخل فخرج فقالها فلم يدخل أحد فقال له معاوية اخرج فقل من كان ههنا من الأنصار فليدخل فخرج فقالها فدخلوا يقدمهم النعمان بن بشير وهو يقول\n(ياسعد لا تعد الدعاء فما لنا ... نسب نجيب به سوى الأنصار)\n(نسب تخيره الإله لقومنا ... أثقل به نسبا على الكفار)\n(إن الذين ثووا ببدر منكم ... يوم القليب هم وقود النار)\nقال معاوية لعمرو قد كنا أغنياء عن هذا والنعمان بن بشير هو من المعروفين في الشعر سلفا وخلفا جده شاعر وأبوه شاعر وعمه شاعر وهو شاعر وأولاده وأولاد أولاده شعراء فأما جده سعد بن الحصين فهو القائل\n(إن كنت سائلة والحق معتبة ... فالأزد نسبتنا والماء غسان)\n(شم الأنوف لهم عز ومكرمة ... كانت لهم من جبال الطود أركان)\nعمه الحسين بن سعد أخو بشير بن سعد القائل\n(إذ لم أزر إلا لآكل أكلة ... فلا رفعت كفي إلي طعامي)\n(فما أكلة إن نلتها بغنيمة ... ولا جوعة إن جعتها بغرام)\nوأبوه بشير بن سعد الذي يقول\n(لعمرة بالبطحاء بين معرف ... وبين المطاف مسكن ومحاضر)\n(لعمري لحي بين دار مزاحم ... وبين الجثا لا يجشم السير حاضر)\n(وحي حلال لا يروع سربهم ... لهم من وراء القاصيات زوافر)\n(أحق بها من فتية وركائب ... يقطع عنها الليل عوج ضوامر)\n(تقول وتذري الدمع عن حر وجهها ... لعلك نفسي قبل نفسك باكر)\n(أباح لها بطريق فارس غائطا ... لها من ذرا الجولان بقل وزاهر)\n(فقربتها للرحل وهي كأنها ... ظليم نعام بالسماوة نافر)\n(فأوردتها ماء فما شربت به ... سوى أنه قد بل منها المشافر)\n(فباتت سراها ليلة ثم عرست ... بيثرب والأعراب باد وحاضر)\nقال خالد بن كلثوم ودخل النعمان بن بشير على معاوية لما هجا الأخطل الأنصار فلما مثل بين يديه أنشأ يقول\n(معاوي إلا تعطنا الحق تعترف ... لحي الأزد مشدودا عليها العمائم)\n(أيشتمنا عبد الأراقم ضلة ... وماذا الذي تجدي عليك الأراقم)\n(فمالي ثأر غير قطع لسانه ... فدونك من يرضيه عنك الدراهم)\n(وأرع رويدا لا تسمنا دنية ... لعلك في غب الحوادث نادم)\n(متى تلق منا عصبة خزرجية ... أو الأوس يوما تخترمك المخارم)\n(وتلقك خيل كالقطا مسبطرة ... شماطيط أرسال عليها الشكائم)\n(يسومها العمران عمرو بن عامر ... وعمران حتى تستباح المحارم)","topic":"أخبار النعمان بن بشير ونسبه","topicNo":195,"sp":4,"spl":"باكورة شعر النعمان"},
{"id":"b195-6","bab":"الجزء 16","sec":"باكورة شعر النعمان","page":"ج16 ص49","text":"(ويبدو من الخود الغريرة حجلها ... وتبيض من هول السيوف المقادم)\n(فتطلب شعب الصدع بعد انفتاقه ... فتعيا به فالآن والأمر سالم)\n(وإلا فبزي لأمة تبعية ... مواريث آبائي وأبيض صارم)\n(وأجرد خوار العنان كأنه ... بدومة موشي الذراعين صائم)\n(وأسمر خطي كأن كعوبه ... نوى القسب فيها لهذمي ضبارم)\n(فإن كنت لم تشهد ببدر وقيعة ... أذلت قريشا والأنوف رواغم)\n(فسائل بنا حيي لؤي بن غالب ... وأنت بما تخفي من الأمر عالم)\n(ألم تبتدركم يوم بدر سيوفنا ... وليلك عما ناب قومك نائم)\n(ضربناكم حتى تفرق جمعكم ... وطارت أكف منكم وجماجم)\n(وعاذت على البيت الحرام عوانس ... وأنت على خوف عليك تمائم)\n(وعضت قريش بالأنامل بغضة ... ومن قبل ما عضت علينا الأباهم)\n(فكنا لها في كل امر تكيده ... مكان الشجا والأمر فيه تفاقم)\n(فما إن رمى رام فأوهى صفاتنا ... ولا ضامنا يوما من الدهر ضائم)\n(وإني لأغضي عن أمور كثيرة ... سترقى بها يوما إليك السلالم)\n(أصانع فيها عبد شمس وإنني ... لتلك التي في النفس مني أكاتم)\n(فلا تشتمنا يابن حرب فإنما ... ترقي إلى تلك الأمور الأشائم)\n(فما أنت والأمر الذي لست أهله ... ولكن ولي الحق والأمر هاشم)\n(إليهم يصير الأمر بعد شتاته ... فمن لك بالأمر الذي هو لازم)\n(بهم شرع الله الهدى واهتدى بهم ... ومنهم له هاد إمام وخاتم)\nال فلما بلغت هذه الأبيات معاوية أمر بدفع الأخطل إليه ليقطع لسانه فاستجار بيزيد بن معاوية فمنع منه وأرضوا النعمان حتى رضي وكف عنه\nوقال عمرو بن أبي عمرو الشيباني عن أبيه لما ضرب مروان بن الحكم عبد الرحمن بن حسان الحد ولم يضرب أخاه حين تهاجيا وتقاذفا كتب عبد الرحمن إلى النعمان بن بشير يشتكي ذلك إليه فدخل إلى معاوية وأنشأ يقول\n(يابن أبي سفيان ما مثلنا ... جار عليه ملك أو أمير)\n(اذكر بنا مقدم أفراسنا ... بالحنو إذ أنت إلينا فقير)\n(واذكر غداة الساعدي الذي ... آثركم بالأمر فيها بشير)\n(واحذر عليهم مثل بدر فقد ... مر بكم يوم ببدر عسير)\n(إن ابن حسان له ثائر ... فأعطه الحق تصح الصدور)\n(ومثل أيام لنا شتتت ... ملكا لكم أمرك فيها صغير)\n(أما ترى الأزد وأشياعها ... نحوك خزرا كاظمات تزير)\n(يطوف حولي منهم معشر ... ان صلت صالوا وهم لي نصير)\n(يأبى لنا الضيم فلا يعتلي ... عز منيع وعديد كثير)\n(وعنصر في حر جرثومة ... عادية تنقل عنها الصخور)\nخبرني محمد بن خلف وكيع قال حدثني أحمد بن الهيثم الفراسي قال حدثني العمري عن الهيثم بن عدي قال\nحضرت الأنصار باب معاوية ومعهم النعمان بن بشير فخرج إليهم سعد أبو درة وكان حاجب معاوية ثم حجب عبد الملك بن مروان فقال استأذن لنا فدخل فقال لمعاوية الأنصار بالباب فقال له عمرو بن العاص ما هذا اللقب الذي قد جعلوه نسبا ارددهم إلى نسبهم فقال معاوية إن علينا في ذلك شناعة قال وما في ذلك إنما هي كلمة مكان كلمة ولا مرد لها فقال له معاوية اخرج فناد من بالباب من ولد عمرو بن عامر فليدخل فخرج فنادى بذلك فدخل من كان هناك منهم سوى الأنصار فقال له اخرج فناد من كان ههنا من الأوس والخزرج فليدخل فخرج فنادى ذلك فوثب النعمان بن بشير فأنشأ يقول\n(يا سعد لا تعد الدعاء فما لنا ... نسب نجيب به سوى الأنصار)\n(نسب تخيره الإله لقومنا ... أثقل به نسبا على الكفار)\n(إن الذين ثووا ببدر منكم ... يوم القليب هم وقود النار)\nقام مغضبا وانصرف فبعث معاوية فرده فترضاه وقضى حوائجه وحوائج من حضر معه من الأنصار","topic":"أخبار النعمان بن بشير ونسبه","topicNo":195,"sp":5,"spl":"باكورة شعر النعمان"},
{"id":"b195-7","bab":"الجزء 16","sec":"من محتار شعر النعمان","page":"ج16 ص56","text":"ومن مختار شعر النعمان قوله رواها خالد بن كلثوم واخترت منها\n(إذا ذكرت أم الحويرث أخضلت ... دموعي على السربال أربعة سكبا)\n(كأني لما فرقت بيننا النوى ... أجاور في الأغلال تغلب أو كلبا)\n(وكنا كماء العين والجفن لا ترى ... لواش بغى نقض الهوى بيننا إربا)\n(فأمسى الوشاة غيروا ود بيننا ... فلا صلة ترعى لدي ولا قربى)\n(جرى بيننا سعي الوشاة فأصبحت ... كأني - ولم أذنب - جنيت لها ذنبا)\n(فإن تصرميني تصرمي بي واصلا ... لدى الود معراضا إذا ما التوى صعبا)\n(عزوفا إذا خاف الهوان عن الهوى ... ويأبى فلا يعطي مودته غصبا)\n(فإن أستطع أصبر وإن يغلب الهوى ... فمثل الذي لاقيت كلفني نصبا)\nاخترت هذه الأبيات من قصيدة أخرى وأولها\n(أهيج دمعك رسم الطلل ... عفا غير مطرد كالخلل)\n(نعم فاستهل لعرفانه ... يسح ويهمي بفيض سبل)\n(ديار الألوف وأترابها ... وأنت من الحب كالمختبل)\n(ليالي تسبي قلوب الرجال ... تحت الخدور بحسن الغزل)\n(من الناهضات بأعجازهن ... حين يقوم جزيل الكفل)\n(كأن الرضاب وصوب السحاب ... بات يشاب بذوب العسل)\n(من الليل خالط أنيابها ... بعيد الكرى واختلاف العلل)\nخذ هذا المعنى جميل منه فقال\n(وكأن طارقها على علل الكرى ... والنجم وهنا قد دنا لتغور)\n(يشتم ريح مدامة معلولة ... بسحيق مسك في ذكي العنبر)\nفي هذه القصيدة يقول النعمان\n(وأروع ذي شرف حازم ... صروم وصول حبال الخلل)\n(كريم البلاء صبور اللقاء ... صافي الثناء قليل العذل)\n(عظيم الرماد طويل العماد ... واري الزناد بعيد القفل)\n(أقمت له ولأصحابه ... عمود السرى بذمول رمل)\n(مداخلة سرحة جسرة ... على الأين دوسرة كالجمل)\nمن شعراء ولد النعمان بن بشير ابنه عبد الله بن النعمان وهو القائل\n(ماذا رجاؤك غائبا ... من لا يسرك شاهدا)\n(وإذا دنوت يزيده ... منك الدنو تباعدا)\nمنهم عبد الخالق بن أبان بن النعمان بن بشير شاعر مكثر وهو القائل في قصيدة طويلة\n(وشاد أبونا الشيخ عمرو بن عامر ... بأعلى ذرا العلياء ركنا تأثلا)\n(وخط حياض المجد مترعة لنا ... ملاء فعل الصفو منها وأنهلا)\n(وأشرع فيها الناس بعد فما لهم ... من المجد إلا سؤره حين أفضلا)\n(وفي غيرنا مجد من الناس كلهم ... فأما كمثل العشر من مجدنا فلا)\nوله أشعار كثيرة لم أحب الإطالة بذكرها ومنهم شبيب بن يزيد بن النعمان بن بشير شاعر مكثر مجيد وهو القائل من قصيدة طويلة يعاتب بني أمية عند اختلاف أمرهم في أيام الوليد بن يزيد وبعده أولها\n(يا قلب صبرا جميلا لا تمت حزنا ... قد كنت من أن ترى جلد القوى قمنا)\nقول فيها\n(بل أيها الراكب المزجي مطيته ... لقيت حيث توجهت الثنا الحسنا)\n(أبلغ أمية أعلاها وأسفلها ... قولا ينفر عن نوامها الوسنا)\n(إن الخلافة أمر كان يعظمه ... خيار أولكم قدما وأولنا)\n(فقد بقرتم بأيديكم بطونكم ... وقد وعظتم فما أحسنتم الأذنا)\n(أغريتم بكم جهلا عدوكم ... في غير فائدة فاستوسقوا سننا)\n(لما سفكتم بأيديكم دماءكم ... بغيا وغشيتم أبوابكم درنا)\nمنهم إبراهيم بن بشير بن سعد أخو النعمان شاعر مكثر وهو القائل في قصيدة طويلة\n(أشاقتك أظعان الحدوج البواكر ... كنخل النجير الشامخات المواقر)\n(على كل فتلاء الذراعين جسرة ... وأعيس نضاخ المهد عذافر)\n(نعم فاستدرت عبرة العين لوعة ... وما أنت عن ذكرى سليمى بصابر)\n(ولم أرى سلمى بعد إذ نحن جيرة ... من الدهر إلا وقفة بالمشاعر)\n(ألا رب ليل قد سريت سواده ... الى ردح الأعجاز غر المحاجر)\n(ليالي يدعوني الصبا فأجيبه ... أجر إزاري عاصيا أمر زاجري)\n(وإذ لمتي مثل الجناح أثنيثة ... أمشي الهوينى لا يروع طائري)\n(فأصبحت قد ودعت كم بغيره ... مخافة ربي يوم تبلى سرائري)\nبنت النعمان بن بشير واسمها حميدة كانت شاعرة ذات لسان وعارضة وشر فكانت تهجو أزواجها وكانت تحت الحارث بن خالد المخزومي وقيل بل كانت تحت المهاجر بن عبد الله بن خالد فقالت فيه\n(كهول دمشق وشبانها ... أحب إلي من الجاليه)\n(صماحهم كصماح التيوس ... أعيا على المسك والغاليه)\n(وقمل يدب دبيب الجراد ... أكاريس أعيا على الفاليه)\nفطلقها فتزوجها روح بن زنباع فهجته وقالت تخاطب أخاها الذي زوجها من روح وتقول\n(أضل الله حلمك من غلام ... متى كانت مناكحنا جذام)\n(أترضى بالأكارع والذنابى ... وقد كنا يقر لنا السنام)\nقالت تهجو روحا","topic":"أخبار النعمان بن بشير ونسبه","topicNo":195,"sp":6,"spl":"من محتار شعر النعمان"},
{"id":"b195-8","bab":"الجزء 16","sec":"من محتار شعر النعمان","page":"ج16 ص56","text":"(بكى الخز من روح وأنكر جلده ... وعجت عجيجا من جذام المطارف)\n(وقال العباء نحن كنا ثيابهم ... وأكسية كدرية وقطائف)\nطلقها روح وقال سلط الله عليك بعلا يشرب الخمر ويقيئها في حجرك فتزوجت بعده الفيض بن أبي عقيل الثقفي وكان يسكر ويقيء في حجرها فكانت تقول أجيبت في دعوة روح وقالت في الفيض\n(سميت فيضا وما شيء تفيض به ... إلا بسلحك بين الباب والدار)\n(فتلك دعوة روح الخير أعرفها ... سقى الإله صداه الأوطف الساري)\nقالت فيه\n(وهل أنا إلا مهرة عربية ... سليلة أفراس تجللها بغل)\n(فإن نتجت مهرا كريما فبالحرى ... وإن كان إقراف فما أنجب الفحل)\nكذا روى خالد بن كلثوم هذين البيتين لها وغيره يرويهما لمالك بن أسماء لما تزوج الحجاج أخته هندا وهي القائلة لما تزوج الحجاج أختها أم أبان\n(قد كنت أرجو بعض ما يرجو الراج ... أن تنكحيه ملكا أو ذا تاج)\n(إذا تذكرت نكاح الحجاج ... تضرم القلب بحزن وهاج)\n(وفاضت العين بماء ثجاج ... لو كان نعمان قتيل الأعلاج)\n(مستوي الشخص صحيح الأوداج ... ما نلت بختل الدراج)\nأخرجها الحجاج من العراق وردها إلى الشام\n(نفرت قلوصي من حجارة حرة ... بنيت على طلق اليدين وهوب)\n(لا تنفري يا ناق منه فإنه ... شريب خمر مسعر لحروب)\n(لا يبعدن ربيعة بن مكدم ... وسقى الغوادي قبره بذنوب)\n(لولا السفار وبعد خدق مهمة ... لتركتها تحبو على العرقوب)\nقال إن الشعر لحسان بن ثابت الأنصاري ويقال إنه لضرار بن الخطاب الفهري أخبرني أبو خليفة إجازة عن محمد بن سلام قال الصحيح أن هذه الأبيات لعمرو بن شقيق أحد بني فهر بن مالك ومن الناس من يرويها لمكرز بن حفص بن الأحنف الفهري وعمرو بن شقيق أولى بها والغناء لمالك - خفيف ثقيل - بإطلاق الوتر في مجرى البنصر","topic":"أخبار النعمان بن بشير ونسبه","topicNo":195,"sp":7,"spl":"من محتار شعر النعمان","song":1},
{"id":"b196-1","bab":"الجزء 16","sec":"أخبار مقتل ربيعة ونسبه","page":"ج16 ص64","text":"وهذا الشعر قيل في قتل ربيعة بن مكدم بن عامر بن حرثان بن جذيمة بن علقمة بن جذل الطعان بن فراس بن عثمان بن ثعلبة بن مالك بن كنانة أحد فرسان مضر المعدودين وشجعانهم المشهورين قتله نبيشة بن حبيب السلمي في يوم الكديد وكان السبب في ذلك فيما ذكره محمد بن الحسن بن دريد إجازة عن أبي حاتم عن أبي عبيدة ونسخته أيضا من رواية الأصمعي وحماد صاحب أبي غسان دماذ والأثرم فجمعتها ههنا قال أبو عبيدة قال أبو عمرو بن العلاء وقع تدارؤ بين نفر من بني سليم بن منصور وبين نفر من بني فراس بن مالك بن كنانة فقتلت بنو فراس رجلين من بني سليم بن منصور ثم إنهم ودوهما ثم ضرب الدهر ضرباته\nفخرج نبيشة بن حبيب السلمي غازيا فلقي ظعنا من بني كنانة بالكديد في نفر من قومه وبصر بهم نفر من بني فراس بن مالك فيهم عبد الله بن جذل الطعان بن فراس والحارث بن مكدم أبو الفارعة وقال بعضهم أبو الفرعة أخو ربيعة بن مكدم قال وهو مجدور يومئذ يحمل في محفة فلما رآهم أبو الفارعة قال هؤلاء بنو سليم يطلبون دماءهم فقال أخوه ربيعة بن مكدم أنا أذهب حتى أعلم علم القوم فآتيكم بخبرهم فتوجه نحوهم فلما ولى قال بعض الظعن هرب ربيعة فقالت أخته أم عزة بنت مكدم أين تنتهي نفرة الفتى فعطف وقدسمع قول النساء فقال\n(لقد علمن أنني غير فرق ... لأطعنن طعنة وأعتنق)\n(أعمل فيهم حين تحمر الحدق ... عضبا حساما وسنانا يأتلق)\nال ثم انطلق يعدو به فرسه فحمل عليه بعض القوم فاستطرد له في طريق الظعن وانفرد به رجل من القوم فقتله ربيعة ثم رماه نبيشة أو طعنه فلحق بالظعن يستدمي حتى أتى إلى أمه أم سيار فقال اجعلي على يدي عصابة وهو يرتجز ويقول\n(شدي علي العصب أم سيار ... )\n(لقد رزيت فارسا كالدينار ... )\n(يطعن بالرمح أمام الأدبار ... )\nقالت أمه\n(إنا بنو ثعلبة بن مالك ... مرزأ أخيارنا كذلك)\n(من بين مقتول وبين هالك ... ولا يكون الرزء إلا ذلك)\nال أبو عبيدة وشدت أمه عليه عصابة فاستسقاها ماء فقالت إنك إن شربت الماء مت فكر على القوم فكر راجعا يشد على القوم ويذبهم ونزفه الدم حتى أثخن فقال للظعن أوضعن ركابكن خلفي حتى تنتهين إلى أدنى بيوت الحي فإني لما بي وسوف أقف دونكن لهم على العقبة وأعتمد على رمحي فلن يقدموا عليكن لمكاني ففعلن ذلك فنحون إلى مأمنهن قال أبو عبيدة قال أبو عمرو بن العلاء ولا نعلم قتيلا ولا ميتا حمى ظعائن غيره قال وإنه يومئذ لغلام له ذؤابة قال فاعتمد على رمحه وهو واقف لهن على متن فرسه حتى بلغن مأمنهن وما تقدم القوم عليه فقال نبيشة بن حبيب إنه لمائل العنق وما أظنه إلا قد مات فأمر رجلا من خزاعة كان معه أن يرمي فرسه فرماها فقمصت وزالت فمال عنها ميتا قال ويقال بل الذي رمى فرسه نبيشة فانصرفوا عنه وقد فاتهم الظعن قال أبو عبيدة ولحقوا يومئذ أبا الفرعة الحارث بن مكدم فقتلوه وألقوا على ربيعة أحجارا","topic":"أخبار مقتل ربيعة ونسبه","topicNo":196,"sp":0,"spl":"أخبار مقتل ربيعة ونسبه","partial":1},
{"id":"b196-2","bab":"الجزء 16","sec":"أشعار في رثائه","page":"ج16 ص66","text":"فمر به رجل من بني الحارث بن فهر فنفرت ناقته من تلك الأحجار التي أهيلت على ربيعة فقال يرثيه ويعتذر ألا يكون عقر ناقته على قبره وحض على قتلته وعير من فر وأسلمه من قومه\n(نفرت قلوصي من حجارة حرة ... بنيت على طلق اليدين وهوب)\n(لا تنفري يا ناق منه فإنه ... سباء خمر مسعر لحروب)\n(لولا السفار وبعد خرق مهمه ... لتركتها تحبو على العرقوب)\n(مر الفوارس عن ربيعة بعدما ... نجاهم من غمة المكروب)\n(يدعو عليا حين أسلم ظهره ... فلقد دعوت هناك غير مجيب)\n(لله در بني علي إنهم ... لم يحمشوا غزوا كولغ الذيب)\n(نعم الفتى أدى نبيشة بزه ... يوم الكديد نبيشة بن حبيب)\n(لا يبعدن ربيعة بن مكدم ... وسقى الغوادي قبره بذنوب)\nال أبو عبيدة ويقال إن الذي قال هذا الشعر هو ضرار بن الخطاب بن مرداس أحد بني محارب بن فهر وقال آخر هو حسان بن ثابت وقال الأثرم أنشدني أبو عبيدة مرة أخرى هذا البيت\n(وسقى الغوادي قبره بذنوب ... )\nاحتج به في قول الله عز و جل ( ذنوبا مثل ذنوب أصحابهم\nفسألته لمن هذا البيت فقال لمكرز بن حفص بن الأحنف أحد بني عامر بن لؤي رجل من قريش الظواهر ولم يسمه ههنا وقال عبد الله بن جذل الطعان واسمه بلعاء\n(لأطلبن بربيعة بن مكدم ... حتى أنال عصية بن معيص)\nقال إن عصية من بني سليم وهو عصية بن معيص بن عامر بن لؤي\n(وتقاد كل طمرة ممحوصة ... ومقلص عبل الشوى ممحوص)\nقال رجل من بني الحارث بن الخزرج من الأنصار يرثي ربيعة بن مكدم وقال أبو عبيدة زعم أبو الخطاب الأخفش أنه لحسان بن ثابت يحض على قتله\n(ولأصرفن سوى حذيفة مدحتي ... لفتى الشتاء وفارس الأجراف)\n(مأوى الضريك إذا الرياح تناوحت ... ضخم الدسيعة مخلف متلاف)\n(من لا يزال يكب كل ثقيلة ... كوماء غير مسائل منزاف)\n(رحب المباءة والجناب موطأ ... مأوى لكل معتق بسواف)\n(فسقى الغوادي قبرك ابن مكدم ... من صوب كل مجلجل وكاف)\n(أبلغ بني بكر وخص فوارسا ... لحقوا الملامة دون كل لحاف)\n(أسلمتم جذل الطعان أخاكم ... بين الكديد وقلة الأعراف)\nالأعراف رمل قال الأثرم الأعراف كل ما ارتفع ومنه قول الله تعالى ( ونادى أصحاب الأعراف حتى هوى متزايلا أوصاله ... للحد بين جنادل وقفاف لله در بني علي إن هم ... لم يثأروا عوفا وحي خفاف\nقال الأثرم وأنشدنا أبو عبيدة هذه القصيدة مرة لقيس بن الخطيم حين قتل قاتل أبيه فقال\n(تذكر ليلى حسنها وصفاءها ... )\nقال ابن جذل الطعان في ذلك أيضا\n(ألا لله در بني فراس ... لقد أورثتم حزنا وجيعا)\n(غداة ثوى ربيعة في مكر ... تمج عروقه علقا نجيعا)\n(فلن أنسى ربيعة إذ تعالى ... بكاء الظعن تدعو يا ربيعا)\nقال كعب بن زهير وأمه من بني أشجع بن عامر بن الليث بن بكر بن كنانة يرثي ربيعة بن مكدم ويحض على بني سليم ويعير بني كنانة بالدماء\nالتي أدوها إلى بني سليم وهم لا يدركون قتلاهم عندهم بدرك قتل فيهم ولا دية\n(بان الشباب وكل إلف بائن ... ظعن الشباب مع الخليط الظاعن)\n(قالت أميمة ما لجسمك شاحبا ... وأراك ذا بث ولست بدائن)\n(غضي ملامك إن بي من لومكم ... داء أظن مماطلي أو فاتني)\n(أبلغ كنانة غثها وسمينها ... الباذلين رباعها بالقاطن)\n(أن المذلة أن تطل دماؤكم ... ودماء عوف ضامن في العاهن)\n(أموالكم عوض لهم بدمائهم ... ودماؤكم كلف لهم بظعائن)\n(طلبوا فأدرك وترهم مولاهم ... وأبت محاملكم إباء الحارن)\n(شدوا المآزر فاثأروا بأخيكم ... إن الحفائظ نعم ربح الثامن)\n(كيف الحياة ربيعة بن مكدم ... يغدى عليك بمزهر أو قائن)\n(وهو التريكة بالعراء وحارث ... فقع القراقر بالمكان الواتن)\n(كم غادروا لك من أرامل عيا ... جزر الضباع ومن ضريك واكن)\nقالت أم عمرو أخت ربيعة ترثي ربيعة\n(ما بال عينك منها الدمع مهراق ... سحا ولا عازب لالا ولا راقي)\n(أبكي على هالك أودى وأورثني ... بعد التفرق حزنا بعده باقي)\n(لو كان يرجع ميتا وجد ذي رحم ... أبقى أخي سالما وجدي وإشفاقي)\n(أو كان يفدى لكان الأهل كلهم ... وما أثمر من مال له واقي)\n(لكن سهام المنايا من نصبن له ... لم ينجه طب ذي طب ولا راقي)\n(فاذهب فلا يبعدنك الله من رجل ... لاقى الذي كل حي مثله لاقي)\n(فسوف أبكيك ما ناحت مطوقة ... وما سريت مع الساري على ساقي)\n(أبكى لذكرته عبرى مفجعة ... ما إن يجف لها من ذكره ماقي)\nقال عبد الله يرثيه","topic":"أخبار مقتل ربيعة ونسبه","topicNo":196,"sp":1,"spl":"أشعار في رثائه","partialRef":{"sid":"b16-4","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b196-3","bab":"الجزء 16","sec":"أشعار في رثائه","page":"ج16 ص66","text":"(خلى علي ربيعة بن مكدم ... حزنا يكاد له الفؤاد يزول)\n(فإذا ذكرت ربيعة بن مكدم ... ظلت لذكراه الدموع تسيل)\n(نعم الفتى حيا وفارس بهمة ... يردي بشكته أقب ذؤول)\n(سقت الغوادي بالكديد رمة ... والناس إما هالك وقتيل)\n(فإذا لقيت ربيعة بن مكدم ... فعلى ربيعة من نداه قبول)\n(كيف العزاء ولا تزال خريدة ... تبكي ربيعة غادة عطبول)\n(يأبى لي الله المذلة إنما ... يعطى المذلة عاجز تنبيل)\nقال عبد الله أيضا يرثيه\n(نادى الظعائن يا ربيعة بعد ما ... لم يبق غير حشاشة وفواق)\n(فأجابها والرمح في حيزومه ... أنفا بطعن كالشعيب دفاق)\n(يا ريط إن ربيعة بن مكدم ... وربيع قومك آذنا بفراق)\n(ولئن هلكت لرب فارس بهمة ... فرجت كربته وضيق خناق)\nقال أيضا يتوعد بني سليم\n(ولست لحاضر إن لم أزركم ... كتائب من كنانة كالصريم)\n(على قب الأياطل مضمرات ... أضر بنيها علك الشكيم)\nخبرني أحمد بن عبيد الله بن عمار قال حدثنا يعقوب بن إسرائيل قال حدثني الطلحي قال أخبرني عبد الله بن إبراهيم الجمحي ومحمد بن الحسن بن زبالة في مجلس واحد قالا مر حسان بن ثابت بقبر ربيعة بن مكدم الكناني بثنية كعب ويقال بثنية غزال فقلعت به راحلته فقال\n(نفرت قلوصي من حجارة حرة ... بنيت على طلق اليدين وهوب)\n(لا تنفري يا ناق منه فإنه ... شريب خمر مسعر لحروب)\n(لولا السفار وبعد خرق مهمه ... لتركتها تحبو على العرقوب)\nبلغ شعره بني كنانة فقالوا والله لو عقرها لسقنا إليه ألف ناقة سود الحدق أخبرني محمد بن الحسن بن دريد قال حدثنا السجستاني قال\nحدثنا أبو عبيدة قال خرج دريد بن الصمة في فوارس من بني جشم حتى إذا كانوا بواد لبني كنانة يقال له الأخرم وهو يريد الغارة على بني كنانة رفع له رجل من ناحية الوادي معه ظعينة فلما نظر إليه قال لفارس من أصحابه صح به أن خل عن الظعينة وانج بنفسك وهو لا يعرفه فانتهى إليه الرجل فصاح به وألح عليه فلما أتى ألقى الزمام وقال للظعينة\n(سيري على رسلك سير الآمن ... سير رداح ذات جأش ساكن)\n(إن انثنائي دون قرني شائني ... وابلي بلائي واخبري وعايني)\nم حمل على الفارس فقتله وأخذ فرسه فأعطاه الظعينة فبعث دريد فارسا آخر لينظر ما صنع صاحبه فرآه صريعا فصاح به فتصامم عنه فظن أنه لم يسمعه فغشيه فألقى الزمام إليها ثم حمل على الفارس فطعنه فصرعه وهو يقول\n(خل سبيل الحرة المنيعه ... إنك لاق دونها ربيعه)\n(في كفه خطية مطيعه ... أو لا فخذها طعنة سريعه)\n(فالطعن مني في الوغى شريعه ... )\nلما أبطأ على دريد بعث فارسا آخر لينظر ما صنعا فانتهى إليهما فرآهما صريعين ونظر إليه يقود ظعينته ويجرر رمحه فقال له الفارس\nخل عن الظعينة فقال لها ربيعة اقصدي قصد البيوت ثم أقبل عليه فقال\n(ماذا تريد من شتيم عابس ... ألم تر الفارس بعد الفارس)\n(أرداهما عامل رمح يابس ... )\nم طعنه فصرعه وانكسر رمحه فارتاب دريد وظن أنهم قد أخذوا الظعينة وقتلوا الرجل فلحق بهم فوجد ربيعة لا رمح معه وقد دنا من الحي ووجد القوم قد قتلوا فقال دريد أيها الفارس إن مثلك لا يقتل وإن الخيل ثائرة بأصحابها ولا أرى معك رمحا وأراك حديث السن فدونك هذا الرمح فإني راجع إلى أصحابي فمثبط عنك فأتى دريد أصحابه وقال إن فارس الظعينة قد حماها وقتل فوارسكم وانتزع رمحي ولا طمع لكم فيه فانصرف القوم وقال دريد في ذلك\n(ما إن رأيت ولا سمعت بمثله ... حامي الظعينة فارسا لم يقتل)\n(أردى فوارس لم يكونوا نهزة ... ثم استمر كأنه لم يفعل)\n(متهلل تبدو أسرة وجهه ... مثل الحمام جلته كف الصيقل)\n(يزجي ظعينته ويسحب رمحه ... متوجها بمناه نحو المنزل)\n(وترى الفوارس من مخافة رمحه ... مثل البغاث خشين وقع الأجدل)\n(يا ليت شعري من أبوه وأمه ... يا صاح من يك مثله لم يجهل)\nقال ربيعة\n(إن كان ينفعك اليقين فسائلي ... عني الظعينة يوم وادي الأخرم)\n(هل هي لأول من أتاها نهزة ... لولا طعان ربيعة بن مكدم)\n(إذ قال لي أدنى الفوارس ميتة ... خل الظعينة طائعا لا تندم)\n(فصرفت راحلة الظعينة نحوه ... عبدا ليعلم بعض ما لم يعلم)\n(وهتكت بالرمح الطويل إهابه ... فهوى صريعا لليدين وللفم)\n(ومنحت آخر بعده جياشة ... نجلاء فاغرة كشدق الأضجم)\n(ولقد شفعتهما بآخر ثالث ... وأبى الفرار لي الغداة تكرمي)","topic":"أخبار مقتل ربيعة ونسبه","topicNo":196,"sp":2,"spl":"أشعار في رثائه","partial":1},
{"id":"b196-4","bab":"الجزء 16","sec":"أشعار في رثائه","page":"ج16 ص66","text":"ال فلم يلبث بنو مالك بن كنانة رهط ربيعة بن مكدم أن أغاروا على بني جشم رهط دريد فقتلوا وأسروا وغنموا وأسروا دريد بن الصمة فأخفى نسبه فبينا هو عندهم محبوس إذ جاء نسوة يتهادين إليه فصرخت امرأة منهن فقالت هلكتم وأهلكتم ماذا جر علينا قومنا هذا والله الذي أعطى ربيعة رمحه يوم الظعينة ثم ألقت عليه ثوبها وقالت يا آل فراس أنا جارة له منكم هذا صاحبنا يوم الوادي فسألوه من هو فقال أنا دريد بن الصمة فمن صاحبي قالوا ربيعة بن مكدم قال فما فعل قالوا قتله بنو سليم قال فمن الظعينة التي كانت معه قالت المرأة ريطة بنت جذل الطعان وأنا هي وأنا امرأته فحبسه القوم وآمروا أنفسهم وقالوا لا ينبغي أن تكفر نعمة دريد على صاحبنا وقال بعضهم والله لا يخرج من أيدينا إلا برضا المخارق الذي أسره وانبعثت المرأة في الليل فقالت\n(سنجزي دريدا عن ربيعة نعمة ... وكل فتى يجزى بما كان قدما)\n(فإن كان خيرا كان خيرا جزاؤه ... وإن كان شرا كان شرا مذمما)\n(سنجزيه نعمى لم تكن بصغيرة ... بإعطائه الرمح السديد المقوما)\n(فقد أدركت كفاه فينا جزاءه ... وأهل بأن يجزى الذي كان أنعما)\n(فلا تكفروه حق نعماه فيكم ... ولا تركبوا تلك التي تملأ الفما)\n(فلو كان حيا لم يضق بثوابه ... ذراعا غنيا كان أو كان معدما)\n(ففكوا دريدا من إسار مخارق ... ولا تجعلوا البؤسى إلى الشر سلما)\nأصبح القوم فتعاونوا بينهم فأطلقوه وكسته ريطة وجهزته ولحق بقومه ولم يزل كافا عن غزو بني فراس حتى هلك","topic":"أخبار مقتل ربيعة ونسبه","topicNo":196,"sp":3,"spl":"أشعار في رثائه"},
{"id":"b196-5","bab":"الجزء 16","sec":"أحيل الناس وأشجعهم وأجبنهم","page":"ج16 ص76","text":"أخبرني الحسن بن علي قال حدثني هارون بن محمد بن عبد الملك قال حدثني محمد بن يعقوب بن أبي مريم العدوي البصري قال حدثني محمد بن عمر الأزدي قال حدثني أبو البلاد الغطفاني وقبيصة بن ميمون الصادري قالا سأل عمر بن الخطاب رضي الله عنه عمرو بن معد يكرب الزبيدي من أشجع من رأيت فقال والله يا أمير المؤمنين لأخبرنك عن أحيل الناس وعن أشجع الناس وعن أجبن الناس فقال له عمر هات فقال أربعت المدينة فخرجت كأحسن ما رأيت وكانت لي فرس شمقمقة طويلة سريعة\nالإبقاء تمطق بالعرق تمطق الشيخ بالمرق فركبتها ثم آليت لا ألقى أحدا إلا قتلته فخرجت وعلي مقدي فإذا أنا بفتى بين غرضين فقلت له خذ حذرك فإني قاتلك فقال والله ما أنصفتني يا أبا ثور أنا كما ترى أعزل أميل عوارة والعوارة الذي لا ترس معه فأنظرني حتى آخذ نبلي فقلت وما غناؤها عنك قال أمتنع بها قلت خذها قال لا والله أو تعطيني من العهود ما يثلجني أنك لا تروعني حتى آخذها فأثلجته فقال وإله قريش لا آخذها أبدا فسلم والله مني وذهبت فهذا أحيل الناس ثم مضيت حتى اشتمل علي الليل فوالله إني لأسير في قمر زاهر كالنور الظاهر إذا بفتى على فرس يقود ظعينة وهو يقول\n(يا لدينا يا لدينا ... ليتنا يعدى علينا)\n(ثم يبلى ما لدينا ... )\nم يخرج حنظلة من مخلاته فيرمي بها في السماء فلا تبلغ الأرض حتى ينظمها بمشقص من نبله فصحت به خذ حذرك ثكلتك أمك فإني قاتلك فمال عن فرسه فإذا هو في الأرض فقلت إن هذا إلا استخفاف فدنوت منه وصحت به ويلك ما أجهلك فما تحلحل ولا زال عن\nموضعه فشككت الرمح في إهابه فإذا هو كأنه قد مات منذ سنة فمضيت وتركته فهذا أجبن الناس ثم مضيت فأصبحت بين دكادك هرشى إلى غزال فنظرت إلى أبيات فعدلت إليها فإذا فيها جوار ثلاث كأنهن نجوم الثريا فبكين حين رأينني فقلت ما يبكيكن فقلن لما ابتلينا به منك ومن ورائنا أخت هي أجمل منا فأشرفت من فدفد فإذا بمن لم أر شيئا قط أحسن من وجهه وإذا بغلام يخصف نعله عليه ذؤابة يسحبها فلما نظر إلي وثب على الفرس مبادرا ثم ركض فسبقني إلى البيوت فوجدهن قد ارتعن فسمعته يقول لهن\n(مهلا نسياتي إذن لا ترتعن ... ان يمنع اليوم نساء تمنعن)\n(أرخين أذيال المروط وارتعن ... )\nلما دنوت منه قال أتطردني أم أطردك قلت أطردك فركض وركضت في أثره حتى إذا مكنت السنان في لفتته واللفتة أسفل من الكتف اتكأت عليه فإذا هو والله مع لبب فرسه ثم استوى في سرجه فقلت\nأقلني قال اطرد فتبعته حتى إذا ظننت أن السنان في ماضغيه اعتمدت عليه فإذا هو والله قائم على الأرض والسنان ماض زالج واستوى على فرسه فقلت أقلني قال اطرد فطردته حتى إذا مكنت السنان في متنه اتكأت عليه وأنا أظن أني قد فرغت منه فمال في ظهر فرسه حتى نظرت إلى يديه في الأرض ومضى السنان زالجا ثم استوى وقال أبعد ثلاث تريد ماذا أطردني ثكلتك أمك فوليت وأنا مرعوب منه فلما غشيني ووجدت حس السنان التفت فإذا هو يطردني بالرمح بلا سنان فكف عني واستنزلني فنزلت ونزل فجز ناصيتي وقال انطلق فإني أنفس بك عن القتل فكان ذلك والله يا أمير المؤمنين عندي أشد من الموت فذاك أشجع من رأيت وسألت عن الفتى فقيل ربيعة بن مكدم الفراسي من بني كنانة وقد أخبرني أحمد بن عبد العزيز الجوهري هذا الخبر وفيه خلاف للأول قال حدثنا عمر بن شبة قال حدثني محمد بن موسى الهذلي قال حدثني سكين بن محمد قال دخل عمرو بن معد يكرب على عمر بن الخطاب رضي الله عنه فقال له يا أبا ثور من أين أقبلت قال من عند سيد بني مخزوم أعظمها هامة وأمدها قامة وأقلها ملامة وأفضلها حلما وأقدمها سلما وأجرئها مقدما قال ومن هو قال سيف الله وسيف رسوله قال وأي شيء صنعت عنده قال أتيته زائرا فدعا لي بكعب وقوس وثور فقال","topic":"أخبار مقتل ربيعة ونسبه","topicNo":196,"sp":4,"spl":"أحيل الناس وأشجعهم وأجبنهم","partial":1},
{"id":"b196-6","bab":"الجزء 16","sec":"أحيل الناس وأشجعهم وأجبنهم","page":"ج16 ص76","text":"عمر وأبيك إن في هذا لشبعا قال لي أو لك يا أمير المؤمنين قال لي ولك قال له فوالله إني لآكل الجذعة وأشرب التبن من اللبن رثيئة وصرفا فلم تقول هذا يا أمير المؤمنين فقال له عمر أي أحياء قومك خير قال مذحج وكل قد كان فيه خير شداد فوارسها فوارس أبطالها أهل الربا والرباح قال عمر وأين سعد العشيرة قال هم أشدنا شريسا وأكثرنا خميسا وأكرمنا رئيسا وهم الأوفياء البررة المساعير الفجرة قال عمر يا أبا ثور ألك علم بالسلاح قال على الخبير سقطت سل عما بدا لك قال أخبرني عن النبل قال منايا تخطىء وتصيب قال فأخبرني عن الرمح قال أخوك وربما خانك قال فأخبرني عن الترس قال ذاك مجن وعليه تدور الدوائر قال أخبرني عن الدرع قال مشغلة للفارس متعبة للراجل قال أخبرني عن السيف قال عنه قارعتك لأمك الهبل قال لا بل لأمك قال عمرو بل لأمك فرفع عمر الدرة فضرب بها عمرا وكان عمرو محتبيا فانحلت حبوته فاستوى قائما وأنشأ يقول\n(أتضربني كأنك ذو رعين ... بخير معيشة أو ذو نواس)\n(فكم ملك قديم قد رأينا ... وعز ظاهر الجبروت قاسي)\n(فأضحى أهله بادوا وأضحى ... ينقل من أناس في أناس)\nال صدقت يا أبا ثور وقد هدم ذلك كله الإسلام أقسمت عليك لما جلست فجلس فقال له عمر هل كععت من فارس قط ممن لقيت قال اعلم يا أمير المؤمنين أني لم أستحل الكذب في الجاهلية فكيف أستحله في الإسلام ولقد قلت لجبهة من خيلي خيل بني زبيد أغيروا بنا على بني البكاء فقالوا بعيد علينا المغار فقلت فعلى بني مالك بن كنانة قال فأتينا على قوم سراة فقال عمر ما علمك بأنهم سراة قال رأيت مزاود خيلهم كثيرة وقدورا مثفاة وقباب أدم فعرفت أن القوم سراة فتركت خيلي حجرة وجلست في موضع أتسمع كلامهم فإذا بجارية منهم قد خرجت من خيمتها فجلست بين صواحب لها ثم دعت وليدة من ولائدها فقالت ادعي فلانا فدعت لها برجل من الحي فقالت له إن نفسي تحدثني أن خيلا تغير على الحي فكيف أنت إن زوجتك نفسي فقال أفعل وأصنع وجعل يصف نفسه فيفرط فقالت له انصرف حتى أرى رأيي وأقبلت على صواحباتها فقالت ما عنده خير ادعي لي فلانا فدعت بآخر فخاطبته بمثل ما خاطبت به صاحبه فأجابها بنحو جوابه فقالت له انصرف حتى أرى رأيي وقالت لصواحباتها ولا عند هذا خير أيضا ثم قالت للوليدة ادعي لي ربيعة بن مكدم فدعته فقالت له مثل\nقولها للرجلين فقال لها إن أعجز العجز وصف المرء نفسه ولكني إذا لقيت أعذرت وحسب المرء غناء أن يعذر فقالت له قد زوجتك نفسي فاحضر غدا مجلس الحي ليعلموا ذلك فانصرف من عندها وانتظرت حتى ذهب الليل ولاح الفجر فخرجت من مكمني وركبت فرسي وقلت لخيلي أغيري فأغارت وتركتها وقصدت نحو النسوة ومجلسهن فكشفت عن خيمة المرأة فإذا أنا بامرأة تامة الحسن فلما ملأت بصرها مني أهوت إلى درعها فشقته وقالت واثكلاه والله ما أبكي على مال ولا تلاد ولكن على أخت من وراء هذا القوز تبقى بعدي في مثل هذا الغائط فتهلك ضيعة وأومأت بيدها إلى قوز رمل إلى جانبهم فقلت هذه غنيمة من وراء غنيمة فدفعت فرسي حتى أوفيت على الأيفاع فإذا أنا برجل جلد نجد أهلب أغلب يخصف نعله وإلى جنبه فرسه وسلاحه فلما رآني رمىبنعله ثم استوى على فرسه وأخذ رمحه ومضى ولم يحفل بي فطفقت أشجره بالرمح خفقا وأقول له يا هذا استأسر فمضى ما يحفل بي حتى أشرف على الوادي فلما رأى الخيل تحوي إبله استعبر باكيا وأنشأ يقول\n(قد علمت إذ منحتني فاها ... أني سأحوي اليوم من حواها)\n(بل ليت شعري اليوم من دهاها ... )\nأجبته\n(عمرو على طول الوجى دهاها ... بالخيل يحميها على وجاها)\n(حتى إذا حل بها احتواها ... )\nحمل علي وهو يقول\n(أهون بنضر العيش في دار ندم ... أفيض دمعا كلما فاض انسجم)\n(أنا ابن عبد الله محمود الشيم ... مؤتمن الغيب وفي بالذمم)\n(أكرم من يمشي بساق وقدم ... كالليث إن هم بتقصام قصم)\nحملت عليه وأنا أقول\n(أنا ابن ذي التقليد في الشهر الأصم ... أنا ابن ذي الإكليل قتال البهم)\n(من يلقني يود كما أودت إرم ... أتركه لحما على ظهر وضم)\nحمل علي وهو يقول\n(هذا حمى قد غاب عنه ذائده ... الموت ورد والأنام وارده)","topic":"أخبار مقتل ربيعة ونسبه","topicNo":196,"sp":5,"spl":"أحيل الناس وأشجعهم وأجبنهم","partial":1},
{"id":"b196-7","bab":"الجزء 16","sec":"أحيل الناس وأشجعهم وأجبنهم","page":"ج16 ص76","text":"حمل علي فضربني فرغت وأخطأني فوقع سيفه في قربوس السرج فقطعه وما تحته حتى هجم على مسح الفرس ثم ثنى بضربة أخرى فرغت وأخطأني فوقع سيفه على مؤخر السرج فقطعه حتى وصل إلى فخذ الفرس وصرت راجلا فقلت ويحك من أنت فوالله ما ظننت أحدا من العرب يقدم علي إلا ثلاثة الحارث بن ظالم للعجب والخيلاء وعامر بن الطفيل للسن والتجربة وربيعة بن مكدم للحداثة والغرة فمن\nأنت ويلك قال بل الويل لك فمن أنت قلت عمرو بن معد يكرب قال وأنا ربيعة بن مكدم قلت يا هذا إني قد صرت راجلا فاختر مني إحدى ثلاث إن شئت اجتلدنا بسيفينا حتى يموت الأعجز وإن شئت اصطرعنا فأينا صرع صاحبه حكم فيه وإن شئت سالمتك وسالمتني قال الصلح إذن إن كان لقومك فيك حاجة وما بي أيضا على قومي هوان قلت فذاك لك وأخذت بيده حتى أتيت أصحابي وقد حازوا نعمه فقلت هل تعلمون أني كععت عن فارس قط من الأبطال إذا لقيته قالوا نعيذك من ذاك قال قلت فانظروا هذا النعم الذي حزتموه فخذوه مني غدا في بني زبيد فإنه نعم هذا الفتى والله لا يوصل إلى شيء منه وأنا حي فقالوا لحاك الله فارس قوم أشقيتنا حتى إذا هجمنا على الغنيمة الباردة فثأتنا عنها قال قلت إنه لا بد لكم من ذلك وأن تهبوها لي ولربيعة بن مكدم فقالوا وإنه لهو قلت نعم فردوها وسالمته فأمن حربي وأمنت حربه حتى هلك وفي بعض هذه الأراجيز التي جرت بين عمرو بن معد يكرب وربيعة بن مكدم غناء نسبته وقد جمع شعراهما معا في لحن واحد وهو\n(أنا ابن ذي التقليد في الشهر الأصم ... أنا ابن عبد الله قتال البهم)\n(أكرم من يمشي بساق وقدم ... من يلقني يود كما أودت إرم)\n(أتركه لحما على ظهر وضم ... كالليث إن هم بتقصام قصم)\n(مؤتمن الغيب وفي بالذمم ... )\nكر أحمد بن يحيى المكي أن الغناء في هذا الشعر لحنين - خفيف ثقيل - بإطلاق الوتر في مجرى البنصر وذكر الهشامي أنه لابن سرجيس الملقب بقراريط حدثتني قمرية العمرية جارية عمرو بن بانة أنها أخذت عن أحمد بن العلاء هذا اللحن فقال لها انظري أي صوت أخذت فوالله لقد أخذته عن مخارق فلما استوى لي قال لي مخارق انظر أي صوت أخذت فوالله لقد أخذته عن يحيى المكي فلما غنيته الرشيد أطربه فوهب ليحيى عشرة آلاف درهم أخبرني علي بن سليمان الأخفش قال حدثني محمد بن الحسن الأحول عن الطرسوسي عن ابن الأعرابي قال\nأجود بيت وصفت به الطعنة قول أهبان بن عادياء قاتل ربيعة بن مكدم حيث يقول\n(ولقد طعنت ربيعة بن مكدم ... يوم الكديد فخر غير موسد)\n(في ناقع شرقت بما في جوفه ... منه بأحمر كالعقيق المجسد)\n\n(أدركت ما منيت نفسي خاليا ... لله درك يابنة النعمان !)\n(إني لحلفك بالصليب مصدق ... والصلب أصدق حلفة الرهبان)\n(ولقد رددت على المغيرة ذهنه ... إن الملوك بطيئة الإذعان)\n(يا هند حسبك قد صدقت فأمسكي ... والصدق خير مقالة الإنسان)\nلشعر للمغيرة بن شعبة الثقفي يقوله في هند بنت النعمان بن المنذر وقد خطبها فردته وخبره في ذلك وغيره يذكر هاهنا إن شاء الله والغناء لحنين ثاني - ثقيل - بالبنصر عن الهشامي وإبراهيم","topic":"أخبار مقتل ربيعة ونسبه","topicNo":196,"sp":6,"spl":"أحيل الناس وأشجعهم وأجبنهم","song":2,"partialRef":{"sid":"b196-6","gi":3,"vi":1,"side":1},"partial":1},
{"id":"b197-1","bab":"الجزء 16","sec":"أخبار المغيرة بن شعبة ونسبه","page":"ج16 ص87","text":"هو المغيرة بن شعبة بن أبي عامر بن مسعود بن معتب بن مالك بن كعب بن عمرو بن سعد بن عوف بن قسي وهو ثقيفب ويكنى أبا عبد الله وكان يكنى أبا عيسى فغيرها عمر بن الخطاب رضي الله عنه وكناه أبا عبد الله وأمه أسماء بنت الأفقم بن أبي عمرو بن ظويلم بن جعيل بن عمرو بن دهمان بن نصر بن معاوية بن بكر بن هوازن وكان المغيرة بن شعبة من دهاة العرب وحزمتها وذوي الرأي منها والحيل الثاقبة وكان يقال له في الجاهلية والإسلام مغيرة الرأي وكان يقال ما اعتلج في صدر المغيرة أمران إلا اختار أحزمهما وصحب النبي وشهد معه الحديبية وما بعدها وبعثه أبو بكر رضي الله عنه إلى أهل النجير وشهد فتح اليمامة وفتوح الشام وكان أعور أصيبت عينه في يوم اليرموك وشهد القادسية مع سعد بن أبي وقاص فلما أراد مراسلة رستم لم يجد في العرب أدهى منه ولا أعقل فبعث به إليه وكان السفير بينهما حتى وقعت الحرب وولاه عمر بن الخطاب رضي الله عنه عدة ولايات إحداها البصرة\nففتح وهو واليها ميسان ودست ميسان وأبرقباذ وقاتل الفرس بالمرغاب فهزمهم ونهض إلى من كان بسوق الأهواز فقاتلهم وهزمهم وفتحها وانحازوا إلى نهر تيرى ومناذر الكبرى فزحف إليهم فقاتلهم وهزمهم وفتحها وخرج إلى المشرق مع النعمان بن المقرن وكان المغيرة على ميسرته وكان عمر قد عهد إن هلك النعمان فالأمير حذيفة فإن هلك\nحذيفة فالأمير المغيرة بن شعبة ولما فتحت نهاوند سار المغيرة في جيش إلى همذان ففتحها وولاه عمر رضي الله عنه بعد ذلك الكوفة فقتل عمر وهو واليها وولاه أيضا إياها معاوية بن أبي سفيان رضي الله عنه فكان عليها إلى أن مات بها وهو أول من وضع ديوان الإعطاء بالبصرة ورتب الناس فيه فأعطاهم على الديوان ثم صار ذلك رسما لهم بعد ذلك يحتذونه","topic":"أخبار المغيرة بن شعبة ونسبه","topicNo":197,"sp":0,"spl":"أخبار المغيرة بن شعبة ونسبه"},
{"id":"b197-2","bab":"الجزء 16","sec":"إسلامه","page":"ج16 ص89","text":"قال محمد بن سعد كاتب الواقدي أخبرنا محمد بن عمر قال حدثني محمد بن سعيد الثقفي وعبد الرحمن بن عبد العزيز وعبد الملك بن عيسى الثقفي وعبد الله بن عبد الرحمن بن يعلى بن كعب ومحمد بن يعقوب بن عتبة عن أبيه وغيرهم قالوا قال المغيرة بن شعبة كنا قوما من العرب متمسكين بديننا ونحن سدنة اللات فأراني لو رأيت قوما قد أسلموا ما تبعتهم فأجمع نفر من بني مالك الوفود على المقوقس وأهدوا له هدايا فأجمعت الخروج معهم فاستشرت عمي عروة بن مسعود فنهاني وقال لي ليس معك من بني أبيك أحد فأبيت\nإلا الخروج وخرجت معهم وليس معهم أحد من الأحلاف غيري حتى دخلنا الإسكندرية فإذا المقوقس في مجلس مطل على البحر فركبت قاربا حتى حاذيت مجلسه فنظر إلي فأنكرني وأمر من يسائلني ما أنا وما أريد فسألني المأمور فأخبرته بأمرنا وقدومنا عليه فأمر بنا أن ننزل في الكنيسة وأجرى علينا ضيافة ثم دعا بنا فنظر إلى رأس بني مالك فأدناه إليه وأجلسه معه ثم سأله أكل القوم من بني مالك فقال نعم إلا رجلا واحدا من الأحلاف فعرفه إياي فكنت أهون القوم عليه ووضعوا هداياهم بين يديه فسر بها وأمر بقبضها وأمر لهم بجوائز وفضل بعضهم على بعض وقصر بي فأعطاني شيئا قليلا لا ذكر له وخرجنا فأقبلت بنو مالك يشترون هدايا لأهلهم وهم مسرورون ولم يعرض علي أحد منهم مواساة وخرجوا وحملوا معهم خمرا فكانوا يشربون منها وأشرب معهم ونفسي تأبى أن تدعني معهم وقلت ينصرفون إلى الطائف بما أصابوا وما حباهم به الملك ويخبرون قومي بتقصيره بي وازدرائه إياي فأجمعت على قتلهم فقلت أنا أجد صداعا فوضعوا شرابهم ودعوني فقلت رأسي يصدع ولكني أجلس وأسقيكم فلم ينكروا شيئا وجلست أسقيهم وأشرب القدح بعد القدح فلما دبت الكأس فيهم اشتهوا الشراب فجعلت أصرف لهم وأترع الكأس فيشربون ولا يدرون فأهمدتهم الكأس حتى ناموا ما يعقلون فوثبت إليهم فقتلتهم جميعا وأخذت جميع ما كان معهم فقدمت على النبي فوجدته جالسا في المسجد مع أصحابه وعلي ثياب السفر فسلمت بسلام الإسلام فنظر إلي أبو بكر بن أبي قحافة وكان بي عارفا فقال ابن أخي عروة قلت نعم جئت أشهد أن لا إله إلا الله وأن محمدا رسول الله فقال رسول الله الحمد لله الذي هداك إلى الإسلام فقال أبو بكر رضي الله عنه أفمن مصر أقبلتم قلت نعم\nقال فما فعل المالكيون الذين كانوا معك قلت كان بيني وبينهم بعض ما يكون بين العرب ونحن على دين الشرك فقتلتهم وأخذت أسلابهم وجئت بها إلى رسول الله ليخمسها ويرى فيها رأيه فإنما هي غنيمة من مشركين وأنا مسلم مصدق بمحمد فقال رسول الله أما إسلامك فنقبله ولا نأخذ من أموالهم شيئا ولا نخمسها لأن هذا غدر والغدر لا خير فيه فأخذني ما قرب وما بعد وقلت يا رسول الله إنما قتلتهم وأنا على دين قومي ثم أسلمت حين دخلت عليك الساعة قال فإن الإسلام يجب ما كان قبله وكان قتل منهم ثلاثة عشر إنسانا فبلغ ذلك ثقيفا بالطائف فتداعوا للقتال ثم اصطلحوا على أن يحمل عمي عروة بن مسعود ثلاث عشرة دية قال المغيرة وأقمت مع النبي حتى اعتمر عمرة الحديبية في ذي القعدة سنة ست من الهجرة فكانت أول سفرة خرجت معه فيها وكنت أكون مع أبي بكر وألزم النبي فيمن يلزم وبعثت قريش عام الحديبية عروة بن مسعود إلى النبي فأتاه يكلمه وجعل يمس لحية رسول الله وأنا قائم على رأسه مقنع في الحديد فقلت لعروة وهو يمس لحية رسول الله اكفف يدك قبل ألا تصل إليك فقال عروة يا محمد من هذا ما أفظه وأغلظه فقال هذا ابن أخيك المغيرة بن شعبة فقال عروة يا عدو الله ما غسلت عني سوءتك إلا بالأمس يا غدر أخبرني محمد بن خلف قال حدثني أحمد بن الهيثم الفراسي قال حدثنا العمري عن الهيثم بن عدي عن مجالد عن الشعبي قال قال المغيرة بن شعبة أول ما عرفني به العرب من الحزم والدهاء أني كنت في ركب من قومي في طريق لنا إلى الحيرة فقالوا لي قد اشتهينا الخمر وما معنا إلا","topic":"أخبار المغيرة بن شعبة ونسبه","topicNo":197,"sp":1,"spl":"إسلامه"},
{"id":"b197-3","bab":"الجزء 16","sec":"إسلامه","page":"ج16 ص89","text":"درهم زائف فقلت هاتوه وهلموا زقين فقالوا وما يكفيك لدرهم زائف زق واحد فقلت أعطوني ما طلبت وخلاكم ذم ففعلوا وهم يهزأون بي فصببت في أحد الزقين شيئا من ماء ثم جئت إلى خمار فقلت له كل لي ملء هذا الزق فملأه فأخرجت الدرهم الزائف فأعطيته إياه فقال لي ما هذا ويحك أمجنون أنت فقلت مالك قال إن ثمن هذا الزق عشرون درهما جيادا وهذا درهم زائف فقلت أنا رجل بدوي وظننت أن هذا يصلح كما ترى فإن صلح وإلا فخذ شرابك فاكتال مني ما كاله وبقي في زقي من الشراب بقدر ما كان فيه من الماء فأفرغته في الزق الآخر وحملتهما على ظهري وخرجت وصببت في الزق الأول ماء ودخلت إلى خمار آخر فقلت إني أريد ملء هذا الزق خمرا فانظر إلى ما معي منه فإن كان عندك مثله فأعطني فنظر إليه وإنما أردت ألا يستريب بي إذا رددت الخمر عليه فلما رآه قال عندي أجود منه قلت هات فأخرج لي شرابا فاكتلته في الزق الذي فيه الماء ثم دفعت إليه الدرهم الزائف فقال لي مثل قول صاحبه فقلت خذ خمرك فأخذ ما كان كاله لي وهو يرى أني خلطته بالشراب الذي أريته إياه وخرجت فجعلته مع الخمر الأول ولم أزل أفعل ذلك بكل خمار في الحيرة حتى ملأت زقي الأول وبعض الآخر ثم رجعت إلى أصحابي فوضعت الزقين بين أيديهم\nورددت درهمهم فقالوا لي ويحك أي شيء صنعت فحدثتهم فجعلوا يعجبون وشاع لي الذكر في العرب بالدهاء حتى اليوم قال محمد بن سعد أخبرنا محمد بن معاوية النيسابوري قال حدثنا داود بن خالد عن العباس بن عبد الله بن معبد بن العباس قال أول من خضب بالسواد المغيرة بن شعبة خرج على الناس وكان عهدهم به أبيض الشعر فعجب الناس منه قال محمد وأخبرني شهاب بن عباد قال حدثنا إبراهيم بن حميد الرواسي عن إسماعيل بن أبي خالد عن قيس بن أبي خازم عن المغيرة بن شعبة قال كنت جالسا عند أبي بكر إذ عرض عليه فرس له فقال له رجل من الأنصار احملني عليها فقال أبو بكر لأن أحمل عليها غلاما قد ركب الخيل على غرلته أحب إلي من أن أحملك عليها فقال له الأنصاري أنا خير منك ومن أبيك قال المغيرة فغضبت لما قال ذلك لأبي بكر رضي الله عنه فقمت إليه فأخذت برأسه فركبته وسقط على أنفه فكأنما كان عزالي مزادة فتوعدني الأنصار أن يستفيدوا مني فبلغ ذلك أبا بكر فقام فقال أما بعد فقد بلغني عن رجال منكم زعموا أني مقيدهم من المغيرة ووالله لأن أخرجهم من دارهم أقرب إليهم من أن أقيدهم من وزعة الله الذين يزعون إليه","topic":"أخبار المغيرة بن شعبة ونسبه","topicNo":197,"sp":2,"spl":"إسلامه"},
{"id":"b197-4","bab":"الجزء 16","sec":"يخطب هند ابنة التسعين عاما","page":"ج16 ص94","text":"أخبرني إسماعيل بن يونس الشيعي وحبيب بن نصر المهلبي قالا حدثنا عمر بن شبة قال حدثنا محمد بن سلام الجمحي قال حدثنا حسان بن العلاء الرياحي عن أبيه عن الشعبي قال ركب المغيرة بن شعبة إلى هند بنت النعمان بن المنذر وهي بدير هند متنصرة عمياء بنت تسعين سنة فقالت له من أنت قال أنا المغيرة بن شعبة قالت أنت عامل هذه المدرة تعني الكوفة قال نعم قالت فما حاجتك قال جئتك خاطبا إليك نفسك قالت أما والله لو كنت جئت تبغي جمالا أو دينا أو حسبا لزوجناك ولكنك أردت أن تجلس في موسم من مواسم العرب فتقول تزوجت بنت النعمان بن المنذر وهذا والصليب أمر لا يكون أبدا أو ما يكفيك فخرا أن تكون في ملك النعمان وبلاده تدبرهما كما تريد وبكت فقال لها أي العرب كان أحب إلى أبيك قالت ربيعة قال فأين كان يجعل قيسا قالت ما كان يستعتبهم من طاعة قال فأين كان يجعل ثقيفا قالت رويدا لا تعجل بينا أنا ذات يوم جالسة في خدر لي إلى جنب أبي إذ دخل عليه رجلان أحدهما من هوازن والآخر من بني مازن كل\nواحد منهما يقول إن ثقيفا منا فأنشأ أبي يقول\n(إن ثقيفا لم يكن هوازنا ... ولم يناسب عامرا ومازنا)\n(إلا قريبا فانشر المحاسنا ... )\nخرج المغيرة وهو يقول\n(أدركت ما منيت نفسي خاليا ... لله درك يابنة النعمان !)\nذكر الأبيات التي مضت وذكرت الغناء فيها أخبرني محمد بن خلف قال أخبرنا الحارث بن محمد قال قال أبو عبيدة قال العلاء بن جرير العنبري بينا حسان بن ثابت ذات يوم جالس بالخيف من منى وهو يومئذ مكفوف إذ زفر زفرة ثم أنشأ يقول\n(وكأن حافرها بكل خميلة ... صاع يكيل به شحيح معدم)\n(عاري الأشاجع من ثقيف أصله ... عبد ويزعم أنه من يقدم)\nال والمغيرة بن شعبة يسمع ما يقول فبعث إليه بخمسة آلاف درهم فلما أتاه بها الرسول قال من بعث بهذه قال المغيرة بن شعبة سمع ما قلت فقال واسوأتاه وقبلها أخبرني هاشم بن محمد الخزاعي قال حدثنا عيسى بن إسماعيل\nالعتكي قال حدثنا محمد بن سلام الجمحي قال أحصن المغيرة بن شعبة إلى أن مات ثمانين امرأة فيهن ثلاث بنات لأبي سفيان بن حرب وفيهن حفصة بنت سعد بن أبي وقاص وهي أم ابنه حمزة بن المغيرة وعائشة بنت جرير بن عبد الله وقال أبو اليقظان صلى المغيرة بالناس سنة أربعين في العام الذي قتل فيه علي بن أبي طالب عليه السلام فجعل يوم الأضحى يوم عرفة أظنه خاف أن يعزل فسبق ذلك فقال الراجز\n(سيري رويدا وابتغي المغيره ... كلفتها الإدلاج بالظهيرة)\nال وكان المغيرة مطلاقا فكان إذا اجتمع عنده أربع نسوة قال إنكن لطويلات الأعناق كريمات الأخلاق ولكني رجل مطلاق فاعتددن وكان يقول النساء أربع والرجال أربعة رجل مذكر وامرأة مؤنثة فهو قوام عليها ورجل مؤنث وامرأة مذكرة فهي قوامة عليه ورجل مذكر وامرأة مذكرة فهما كالوعلين ينتطحان ورجل مؤنث وامرأة مؤنثة فهما لا يأتيان بخير ولا يفلحان","topic":"أخبار المغيرة بن شعبة ونسبه","topicNo":197,"sp":3,"spl":"يخطب هند ابنة التسعين عاما","partial":1},
{"id":"b197-5","bab":"الجزء 16","sec":"المغيرة يتزوج تسعا وثمانين امرأة","page":"ج16 ص96","text":"أخبرني أحمد بن عبيد الله بن عمار قال حدثنا عمر بن شبة قال حدثنا الأصمعي قال حدثنا أبو هلال عن مطير الوراق قال قال المغيرة بن شعبة نكحت تسعا وثمانين امرأة أو قال أكثر من ثمانين امرأة فما أمسكت\nامرأة منهن على حب أمسكها لودها ولحسبها ولكذا ولكذا قال أبو زيد وبلغني أنهم ذكروا النساء عند المغيرة بن شعبة فقال أنا أعلمكم بهن تزوجت ثلاثا وتسعين امرأة منهن سبعون بكرا فوجدت اليمانية كثوبك أخذت بجانبه فاتبعك بقيته ووجدت الربعية أمتك أمرتها فأطاعتك ووجدت المضرية قرنا ساورته فغلبته أو غلبك حدثنا ابن عمار قال حدثنا عمر بن شبة قال حدثنا أبو عاصم قال رأى المغيرة امرأة له تخلل بعد صلاة الصبح فطلقها فقالت علام طلقني قيل رآك تخللين فظن أنك أكلت فقالت أبعده الله والله ما أتخلل إلا من السواك أخبرنا أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثني موسى بن إسماعيل قال حدثنا حماد بن سلمة عن زيد بن أسلم أن رجلا جاء فنادى يستأذن لأبي عيسى على أمير المؤمنين فقال عمر أيكم أبو عيسى قال المغيرة بن شعبة أنا فقال له عمر هل لعيسى من أب أما يكفيكم معاشر العرب أن تكتنوا بأبي عبد الله وأبي عبد الرحمن\nفقال له رجل من القوم أشهد أن النبي كناه بها فقال له عمر إن النبي قد غفر له ما تقدم من ذنبه وما تأخر وأنا لا أدري ما يفعل بي فكناه أبا عبد الله أخبرني هاشم بن محمد قال حدثنا أبو غسان دماذ عن أبي عبيدة قال حدثني عمرو بن بحر أبو عثمان الجاحظ قال كان الجمال بالكوفة ينتهي إلى أربعة نفر المغيرة بن شعبة وجرير بن عبد الله والأشعث بن قيس وحجر بن عدي وكلهم كان أعور فكان المغيرة والأشعث وجرير يوما متواقفين بالكوفة بالكناسة فطلع عليهم أعرابي فقال لهم المغيرة دعوني أحركه قالوا لا تفعل فإن للأعراب جوابا يؤثر قال لا بد قالوا فأنت أعلم قال له يا أعرابي هل تعرف المغيرة بن شعبة قال نعم أعرفه أعور زانيا فوجم ثم تجلد فقال هل تعرف الأشعث بن قيس قال نعم ذاك رجل لا يعرى قومه قال وكيف\nذاك قال لأنه حائك ابن حائك قال فهل تعرف جرير بن عبد الله قال وكيف لا أعرف رجلا لولاه ما عرفت عشيرته قالوا له قبحك الله فإنك شر جليس فهل تحب أن نوقر لك بعيرك هذا مالا وتموت أكرم العرب قال فمن يبلغه أهلي إذن فانصرفوا عنه وتركوه أخبرني علي بن سليمان الأخفش قال حدثني أبو سعيد السكري قال حدثنا محمد بن أبي السري واسم أبي السري سهل بن سلام الأزدي قال حدثني هشام بن محمد قال أخبرنا عوانة بن الحكم قال خرج المغيرة بن شعبة وهو على الكوفة يومئذ ومعه الهيثم بن الأسود النخعي بعد غب مطر يسير بظهر الكوفة والحوف فلقي ابن لسان الحمرة أحد بني تيم الله بن ثعلبة وهو لا يعرف المغيرة فقال له المغيرة من أين أقبلت يا أعرابي قال من السماوة قال فكيف تركت الأرض خلفك قال عريضة أريضة قال وكيف كان المطر قال عفى الأثر وملأ الحفر قال ممن أنت قال من بكر بن وائل قال فكيف علمك بهم قال إن جهلتهم لم أعرف غيرهم قال فما تقول في بني شيبان قال سادتنا وسادة غيرنا قال فما تقول في بني ذهل قال سادة نوكى قال فقيس بن ثعلبة قال إن جاورتهم سرقوك وإن","topic":"أخبار المغيرة بن شعبة ونسبه","topicNo":197,"sp":4,"spl":"المغيرة يتزوج تسعا وثمانين امرأة"},
{"id":"b197-6","bab":"الجزء 16","sec":"المغيرة يتزوج تسعا وثمانين امرأة","page":"ج16 ص96","text":"ائتمنتهم خانوك قال فبنو تيم الله بن ثعلبة قال رعاء البقر وعراقيب الكلاب قال فما تقول في بني يشكر قال صريح تحسبه مولى قال هشام لأن في ألوانهم حمرة قال فعجل قال أحلاس الخيل قال فحنيفة قال يطعمون الطعام ويضربون الهام قال فعنزة قال لا تلتقي بهم الشفتان لؤما قال فضبيعة أضجم قال جدعا وعقرا قال فأخبرني عن النساء قال النساء أربع ربيع مربع وجميع تجمع وشيطان سمعمع وغل لا يخلع قال فسر قال أما الربيع المربع فالتي إذا نظرت إليها سرتك وإذا أقسمت عليها أبرتك وأما التي هي جميع تجمع فالمرأة تتزوجها ولها نشب فتجمع نشبك إلى نشبها وأما الشيطان السمعمع فالكالحة في وجهك إذا دخلت والمولولة في أثرك إذا خرجت وأما الغل الذي لا يخلع فبنت عمك السوداء القصيرة الفوهاء الدميمة التي قد نثرت لك بطنها إن طلقتها ضاع ولدك وإن أمسكتها فعلى جدع أنفك فقال له المغيرة بل أنفك ثم قال له ما تقول في أميرك المغيرة بن شعبة قال أعور زناء فقال الهيثم فض الله فاك ويلك هذا الأمير المغيرة فقال إنها كلمة والله تقال فانطلق به المغيرة إلى منزله وعنده يومئذ أربع نسوة وستون أو سبعون أمة قال له ويحك هل يزني الحر وعنده مثل هؤلاء ثم قال لهن المغيرة ارمين إليه بحلاكن ففعلن\nفخرج الأعرابي بملء كسائه ذهبا وفضة","topic":"أخبار المغيرة بن شعبة ونسبه","topicNo":197,"sp":5,"spl":"المغيرة يتزوج تسعا وثمانين امرأة — يغش علي ويخدع مصقلة الشيباني"},
{"id":"b197-7","bab":"الجزء 16","sec":"يغش علي ويخدع مصقلة الشيباني","page":"ج16 ص101","text":"أخبرني عبيد الله بن محمد قال حدثنا الخراز عن المدائني عن أبي مخنف وأخبرني أحمد بن عيسى العجلي قال حدثنا الحسن بن نصر قال حدثني أبي نصر بن مزاحم قال حدثنا عمر بن سعد عن أبي مخنف عن رجاله أن المغيرة بن شعبة جاء إلى علي بن أبي طالب عليه السلام فقال له اكتب إلى معاوية فوله الشام ومره بأخذ البيعة لك فإنك إن لم تفعل وأردت عزله حاربك فقال علي عليه السلام ( ما كنت متخذ المضلين عضدا\nفانصرف المغيرة وتركه فلما كان من غد جاءه فقال إني فكرت فيما أشرت به عليك أمس فوجدته خطأ ووجدت رأيك أصوب فقال له علي لم يخف علي ما أردت قد نصحتني في الأولى وغششتني في الآخرة ولكني والله لا آتي أمرا أجد فيه فسادا لديني طلبا لصلاح دنياي فانصرف المغيرة أخبرني الحسن بن علي قال حدثني إبراهيم بن سعيد بن شاهين قال حدثني محمد بن يونس الشيرازي قال حدثني محمد بن غسان الضبي قال حدثني زاجر بن عبد الله الثقفي مولى الحجاج بن يوسف قال كان بين المغيرة بن شعبة وبين مصقلة بن هبيرة الشيباني تنازع\nفضرع له المغيرة وتواضع في كلامه حتى طمع فيه مصقلة واستعلى عليه فشتمه فقدمه المغيرة إلى شريح وهو القاضي يومئذ فأقام عليه البينة فضربه الحد فآلى مصقلة ألا يقيم ببلدة فيها المغيرة بن شعبة ما دام حيا وخرج إلى بني شيبان فنزل فيهم إلى أن مات المغيرة ثم دخل الكوفة فتلقاه قومه وسلموا عليه فما فرغ من التسليم حتى سألهم عن مقابر ثقيف فأرشدوه إليها فجعل قوم من مواليه يلتقطون له الحجارة فقال ما هذا قالوا ظننا أنك تريد أن ترجم قبره فقال ألقوا ما في أيديكم فألقوه وانطلق حتى وقف على قبره ثم قال والله لقد كنت نافعا لصديقك ضائرا لعدوك وما مثلك إلا كما قال مهلهل في أخيه كليب\n(إن تحت الأحجار حزما وعزما ... وخصيما ألد ذا معلاق)\n(حية في الوجار أربد لا ينقع ... منه السليم نفث الراقي)\nأخبرني بهذا الخبر محمد بن خلف بن المرزبان عن أحمد بن القاسم عن العمري عن الهيثم بن عدي عن مجالد عن الشعبي أن مصقلة قال له والله إني لأعرف شبهي في عروة ابنك فأشهد عليه بذلك وجلده الحد وذكر باقي الخبر مثل الذي قبله","topic":"أخبار المغيرة بن شعبة ونسبه","topicNo":197,"sp":5,"spl":"المغيرة يتزوج تسعا وثمانين امرأة — يغش علي ويخدع مصقلة الشيباني"},
{"id":"b197-8","bab":"الجزء 16","sec":"عمر لا ينخدع","page":"ج16 ص102","text":"أخبرني محمد بن عبد الله الرازي قال حدثنا أحمد بن الحارث عن\nالمدائني عن مسلمة بن محارب قال قال رجل من قريش لعمر بن الخطاب رضوان الله عليه ألا تتزوج أم كلثوم بنت أبي بكر فتحفظه بعد وفاته وتخلفه في أهله فقال عمر بلى إني لأحب ذاك فاذهب إلى عائشة فاذكر لها ذلك وعد إلي بجوابها فمضى الرسول إلى عائشة فأخبرها بما قال عمر فأجابته إلى ذلك وقالت له حبا وكرامة ودخل إليها بعقب ذلك المغيرة بن شعبة فرآها مهمومة فقال لها مالك يا أم المؤمنين فأخبرته برسالة عمر وقالت إن هذه جارية حدثة وأردت لها ألين عيشا من عمر فقال لها علي أن أكفيك وخرج من عندها فدخل على عمر فقال بالرفاء والبنين قد بلغني ما أتيته من صلة أبي بكر في أهله وخطبتك أم كلثوم فقال قد كان ذاك قال إلا أنك يا أمير المؤمنين رجل شديد الخلق على أهلك وهذه صبية حديثة السن فلا تزال تنكر عليها الشيء فتضربها فتصيح يا أبتاه فيغمك ذلك وتتألم له عائشة ويذكرون أبا بكر فيبكون عليه فتجدد لهم المصيبة به مع قرب عهدها في كل يوم فقال له متى كنت عند عائشة واصدقني فقال آنفا فقال عمر أشهد أنهم كرهوني فتضمنت لهم أن تصرفني عما طلبت وقد أعفيتهم فعاد إلى عائشة فأخبرها بالخبر وأمسك عمر عن معاودتها","topic":"أخبار المغيرة بن شعبة ونسبه","topicNo":197,"sp":6,"spl":"عمر لا ينخدع"},
{"id":"b197-9","bab":"الجزء 16","sec":"المغيرة يزني وأبو بكرة يشهد عليه","page":"ج16 ص103","text":"حدثنا أحمد بن عبد العزيز الجوهري وأحمد بن عبيد الله بن عمار قالا حدثنا عمر بن شبة قال حدثنا علي بن محمد النوفلي عن محمد بن\nسليمان الباقلاني عن قتادة عن غنيم بن قيس قال كان المغيرة بن شعبة يختلف إلى امرأة من ثقيف يقال لها الرقطاء فلقيه أبو بكرة فقال له أين تريد قال أزور آل فلان فأخذ بتلابيبه وقال إن الأمير يزار ولا يزور وحدثنا بخبره لما شهد عليه الشهود عند عمر رضي الله عنه أحمد بن عبيد الله بن عمار وأحمد بن عبد العزيز قالا حدثنا عمر بن شبة فرواه عن جماعة من رجاله بحكايات متفرقة قال عمر بن شبة حدثني أبو بكر العليمي قال أخبرنا هشام عن عيينة بن عبد الرحمن بن جوشن عن أبيه عن أبي بكرة قال عمر بن شبة وحدثنا عمرو بن عاصم قال حدثنا حماد بن سلمة عن علي بن يزيد عن عبد الرحمن بن أبي بكرة قال أبو زيد عمر بن شبة وحدثنا علي بن محمد بن حباب بن موسى عن مجالد عن الشعبي قال وحدثنا محمد بن عبد الله الأنصاري قال حدثنا عوف عن قسامة بن زهير قال أبو زيد عمر بن شبة قال الواقدي حدثنا عبد الرحمن بن محمد ابن أبي بكرة عن أبيه عن مالك بن أوس بن الحدثان قال وحدثني محمد بن الجهم عن علي بن أبي هاشم عن إسماعيل بن أبي عبلة عن عبد العزيز بن صهيب عن أنس بن مالك\nأن المغيرة بن شعبة كان يخرج من دار الإمارة وسط النهار وكان أبو بكرة يلقاه فيقول له أين يذهب الأمير فيقول آتي حاجة فيقول له حاجة ماذا إن الأمير يزار ولا يزور قال وكانت المرأة التي يأتيها جارة لأبي بكرة قال فبينا أبو بكرة في غرفة له مع أصحابه وأخويه نافع وزياد ورجل آخر يقال له شبل بن معبد وكانت غرفة جارته تلك بحذاء غرفة أبي بكرة فضربت الريح باب المرأة ففتحته فنظر القوم فإذا هم بالمغيرة ينكحها فقال أبو بكرة هذه بلية ابتليتم بها فانظروا فنظروا حتى أثبتوا فنزل أبو بكرة فجلس حتى خرج عليه المغيرة من بيت المرأة فقال له إنه قد كان من أمرك ما قد علمت فاعتزلنا قال وذهب ليصلي بالناس الظهر فمنعه أبو بكرة وقال له لا والله لا تصلي بنا وقد فعلت ما فعلت فقال الناس دعوه فليصل فإنه الأمير واكتبوا بذلكم إلى عمر فكتبوا إليه فورد كتابه بأن يقدموا عليه جميعا المغيرة والشهود وقال المدائني في حديثه عن حباب بن موسى وبعث عمر بأبي موسى الأشعري على البصرة وعزم عليه ألا يضع كتابه من يده حتى يرحل المغيرة بن شعبة قال قال علي بن أبي هاشم في حديثه إن أبا موسى قال لعمر لما أمره أن يرحله من وقته أو خير من ذلك يا أمير المؤمنين نتركه يتجهز ثلاثا ثم يخرج قال فصلينا صلاة الغداة بظهر المربد ودخلنا المسجد فإذا هم يصلون الرجال والنساء مختلطين فدخل رجل على المغيرة فقال له\nإني رأيت أبا موسى في جانب المسجد عليه برنس فقال له المغيرة ما جاء زائرا ولا تاجرا فدخلنا عليه ومعه صحيفة ملء يده فلما رآنا قال الأمير فأعطاه أبو موسى الكتاب فلما قرأه ذهب يتحرك عن سريره فقال أبو موسى مكانك تجهز ثلاثا وقال الآخرون إن أبا موسى أمره أن يرحل من وقته فقال له المغيرة لقد علمت ما وجهت فيه فألا تقدمت فصليت فقال له أبو موسى ما أنا وأنت في هذا الأمر إلا سواء فقال له المغيرة فإني أحب أن أقيم ثلاثا لأتجهز فقال قد عزم علي أمير المؤمنين ألا أضع عهدي من يدي إذا قرأته عليك حتى أرحلك إليه قال إن شئت شفعتني وأبررت قسم أمير المؤمنين قال وكيف قال تؤجلني إلى الظهر وتمسك الكتاب في يدك قالوا فقد رئي أبو موسى يمشي مقبلا ومدبرا وإن الكتاب لفي يده معلقا بخيط فتجهز المغيرة وبعث إلى أبي موسى بعقيلة جارية عربية من سبي اليمامة من بني حنيفة ويقال إنها مولدة الطائف ومعها خادم لها وسار المغيرة حين صلى الظهر حتى قدم على عمر وقال في حديث محمد بن عبد الله الأنصاري فلما قدم على عمر قال له إنه قد شهد عليك بامر إن كان حقا لأن تكون مت قبل ذلك كان خيرا لك قال أبو زيد وحدثني الحكم بن موسى قال حدثنا يحيى بن حمزة عن إسحاق بن عبد الله بن أبي فروة عن عبد الله بن عبد الرحمن الأنصاري عن مصعب بن سعد أن عمر بن الخطاب رضي الله عنه جلس ودعا المغيرة والشهود فتقدم","topic":"أخبار المغيرة بن شعبة ونسبه","topicNo":197,"sp":7,"spl":"المغيرة يزني وأبو بكرة يشهد عليه"},
{"id":"b197-10","bab":"الجزء 16","sec":"المغيرة يزني وأبو بكرة يشهد عليه","page":"ج16 ص103","text":"أبو بكرة فقال له أرأيته بين فخذيها قال نعم والله لكأني أنظر إلى تشريم جدري بفخذيها فقال له المغيرة لقد ألطفت النظر فقال له لم آل أن أثبت ما يخزيك الله به فقال له عمر لا والله حتى تشهد لقد رأيته يلج فيه كما يلج المرود في المكحلة فقال نعم أشهد على ذلك فقال له اذهب عنك مغيرة ذهب ربعك ثم دعا نافعا فقال له علام تشهد قال على مثل شهادة أبي بكرة قال لا حتى تشهد أنه كان يلج فيه ولوج المرود في المكحلة فقال نعم حتى بلغ قذذه فقال اذهب عنك مغيرة ذهب نصفك ثم دعا الثالث فقال علام تشهد فقال على مثل شهادة صاحبي فقال له علي بن أبي طالب عليه السلام اذهب عنك مغيرة ذهب ثلاثة أرباعك قال حتى مكث يبكي إلى المهاجرين فبكوا وبكى إلى أمهات المؤمنين حتى بكين معه وحتى لا يجالس هؤلاء الثلاثة أحد من أهل المدينة قال ثم كتب إلى زياد فقدم على عمر فلما رآه جلس له في المسجد واجتمع إليه رؤوس المهاجرين والأنصار قال المغيرة ومعي كلمة قد رفعتها لأكلم القوم قال فلما رآه عمر مقبلا قال إني لأرى رجلا لن يخزي الله على لسانه رجلا من المهاجرين قال أبو زيد وحدثنا عفان قال حدثنا السري بن يحيى قال حدثنا عبد الكريم بن رشيد عن أبي عثمان النهدي قال لما شهد عند عمر الشاهد الأول على المغيرة تغير لذلك لون عمر ثم جاء آخر فشهد فانكسر لذلك انكسارا شديدا ثم جاء رجل شاب يخطر بين يديه فرفع عمر رأسه إليه وقال له ما عندك يا سلح العقاب وصاح أبو\nعثمان صيحة تحكي صيحة عمر قال عبد الكريم لقد كدت أن يغشى علي وقال آخرون قال المغيرة فقمت إلى زياد فقلت له لا مخبأ لعطر بعد عروس ثم قلت يا زياد اذكر الله واذكر موقف يوم القيامة فإن الله وكتابه ورسوله وأمير المؤمنين قد حقنوا دمي إلا أن تتجاوز إلى ما لم تر ما رأيت فلا يحملك شر منظر رأيته على أن تتجاوزه إلى ما لم تر فوالله لو كنت بين بطني وبطنها ما رأيت أين سلك ذكري منها قال فترنقت عيناه واحمر وجهه وقال يا أمير المؤمنين أما أن أحق ما حق القوم فليس ذلك عندي ولكني رأيت مجلسا قبيحا وسمعت نفسا حثيثا وانبهارا ورأيته متبطنها فقال له أرأيته يدخله كالميل في المكحلة فقال لا وقال غير هؤلاء إن زيادا قال له رأيته رافعا برجليها ورأيت خصيتيه تترددان بين فخذيها ورأيت حفزا شديدا وسمعت نفسا عاليا فقال له أرأيته يدخله ويخرجه كالميل في المكحلة فقال لا فقال عمر الله أكبر قم إليهم فاضربهم فقام إلى أبي بكرة فضربه ثمانين وضرب الباقين وأعجبه قول زياد ودرأ عن المغيرة الرجم فقال أبو بكرة بعد أن ضرب فإني أشهد أن المغيرة فعل كذا وكذا فهم عمر بضربه فقال له علي عليه السلام إن ضربته رجمت صاحبك ونهاه عن ذلك قال يعني أنه إن ضربه جعل شهادته بشهادتين فوجب بذلك الرجم على المغيرة قال واستتاب عمر أبا بكرة فقال إنما تستتيبني لتقبل شهادتي قال أجل قال لا أشهد بين اثنين ما بقيت في الدنيا قال فلما ضربوا\nالحد قال المغيرة الله أكبر الحمد لله الذي أخزاكم فقال له عمر اسكت أخزى الله مكانا رأوك فيه قال وأقام أبو بكرة على قوله وكان يقول والله ما أنسى رقط فخذيها قال وتاب الاثنان فقبلت شهادتهما قال وكان أبو بكرة بعد ذلك إذا دعي إلى شهادة يقول اطلب غيري فإن زيادا قد أفسد علي شهادتي قال أبو زيد وحدثني سليمان بن داود بن علي قال حدثني إبراهيم بن سعد عن أبيه عن جده قال لما ضرب أبو بكرة أمرت أمه بشاة فذبحت وجعلت جلدها على ظهره قال فكان أبي يقول ما ذاك إلا من ضرب شديد حدثنا ابن عمار والجوهري قالا حدثنا عمر بن شبة قال حدثنا علي بن محمد عن يحيى بن زكريا عن مجالد عن الشعبي قال كانت أم جميل بنت عمر التي رمي بها المغيرة بن شعبة بالكوفة تختلف إلى المغيرة في حوائجها فيقضيها لها قال ووافقت عمر بالموسم والمغيرة هناك فقال له عمر أتعرف هذه قال نعم هذه أم كلثوم بنت علي فقال له عمر أتتجاهل علي والله ما أظن أبا بكرة كذب عليك وما رأيتك إلا خفت أن أرمى بحجارة من السماء حدثني أحمد بن الجعد قال حدثنا محمد بن عباد قال حدثنا سفيان بن عيينة عن عمرو بن دينار عن أبي جعفر قال قال علي بن أبي طالب عليه السلام لئن لم ينته المغيرة لأتبعنه أحجاره وقال غيره لئن أخذت المغيرة لأتبعنه أحجاره","topic":"أخبار المغيرة بن شعبة ونسبه","topicNo":197,"sp":8,"spl":"المغيرة يزني وأبو بكرة يشهد عليه"},
{"id":"b197-11","bab":"الجزء 16","sec":"المغيرة يزني وأبو بكرة يشهد عليه","page":"ج16 ص103","text":"أخبرني ابن عمار والجوهري قالا حدثنا عمر بن شبة قال حدثنا المدائني قال قال حسان بن ثابت يهجو المغيرة بن شعبة في هذه القصة\n(لو إن اللؤم ينسب كان عبدا ... قبيح الوجه أعور من ثقيف)\n(تركت الدين والإسلام لما ... بدت لك غدوة ذات النصيف)\n(وراجعت الصبا وذكرت عهدا ... من القينات والغمز اللطيف)\nخبرني الجوهري وابن عمار قالا حدثنا عمر بن شبة قال حدثنا المدائني عن عبد الله بن سلم الفهري قال لما شخص المغيرة إلى عمر رأى في طريقه جارية فأعجبته فخطبها إلى أبيها فقال له أنت على هذه الحال قال وما عليك إن أعف فهو الذي تريد وإن أقتل ترثني فزوجه قال أبو زيد قال الواقدي تزوجها بالرقم وهي امرأة من بني مرة فلما قدم بها على عمر قال إنك لفارغ القلب طويل الشبق وقال محمد بن سعد أخبرني محمد بن عبد الله الأسدي قال حدثنا مسعر عن زياد بن علاقة قال سمعت جرير بن عبد الله حين مات المغيرة بن شعبة يقول استغفروا لأميركم هذا فإنه كان يحب العافية قال وكان المغيرة أصهب الشعر جدا أكشف يفرق رأسه\nقرونا أربعة أقلص الشفتين مهتوما ضخم الهامة عبل الذراعين بعيد ما بين المنكبين قال وقال الواقدي حدثني محمد بن موسى الثقفي عن أبيه قال مات المغيرة بن شعبة بالكوفة سنة خمسين في خلافة معاوية وهو ابن سبعين سنة وكان رجلا طوالا أعور أصيبت عينه يوم اليرموك\n(جنية ولها جن يعلمها ... رمي القلوب بقوس ما لها وتر)\n(إن كان ذا قدرا يعطيك نافلة ... منا ويحرمنا ما أنصف القدر)\nلشعر لمحمد بن بشير الخارجي والغناء لإبراهيم - هزج - بالبنصر عن الهشامي","topic":"أخبار المغيرة بن شعبة ونسبه","topicNo":197,"sp":9,"spl":"المغيرة يزني وأبو بكرة يشهد عليه","song":1},
{"id":"b198-1","bab":"الجزء 16","sec":"أخبار محمد بن بشير الخارجي ونسبه","page":"ج16 ص112","text":"هو محمد بن بشير بن عبد الله بن عقيل بن أسعد بن حبيب بن سنان بن عدي بن عوف بن بكر بن يشكر بن عدوان الخارجي من بني خارجة بن عدوان بن عمرو بن قيس بن عيلان بن مضر ويقال لعدوان وفهم ابنا جديلة نسبا إلى أمهما جديلة بنت مر بن أد بن طابخة بن إلياس بن مضر ويكنى محمد بن بشير أبا سليمان شاعر فصيح حجازي مطبوع من شعراء الدولة الأموية وكان منقطعا إلى أبي عبيدة بن عبد الله بن زمعة القرشي أحد بني أسد بن عبد العزى وهو جد ولد عبد الله بن الحسن بن الحسن لأمهم هند بنت أبي عبيدة بن زمعة القرشي ولدت لعبد الله محمدا وإبراهيم وموسى وكانت لمحمد بن بشير فيه مدائح ومراث مختارة وهي عيون شعره وكان يبدو في أكثر زمانه ويقيم في بوادي المدينة ولا يكاد يحضر مع الناس أخبرني بقطعة من أخباره الحسن بن علي قال حدثنا أحمد بن زهير قال حدثني مصعب الزبيري قال أحمد وحدثنا الزبير بن بكار قال حدثني سليمان بن عياش السعدي وعمي مصعب وحدثني بقطعة أخرى منها عيسى بن الحسن الوراق عن الزبير عن سليمان بن عياش وقد ذكرت كل ذلك في مواضعه","topic":"أخبار محمد بن بشير الخارجي ونسبه","topicNo":198,"sp":0,"spl":"أخبار محمد بن بشير الخارجي ونسبه"},
{"id":"b198-2","bab":"الجزء 16","sec":"عائشة بنت يحيى تأبى أن تتزوجه","page":"ج16 ص113","text":"قال ابن أبي خيثمة في روايته عن مصعب وعن الزبير عن سليمان بن عياش كان الخارجي واسمه محمد بن بشير بن عبد الله بن عقيل بن سعد بن حبيب بن سنان بن عدي بن عوف بن بكر شاعرا فصيحا ويكنى أبا سليمان فقدم البصرة في طلب ميراث له بها فخطب عائشة بنت يحيى بن يعمر الخارجية من خارجة عدوان فأبت أن تتزوجه إلا أن يقيم معها بالبصرة ويترك الحجاز ويكون أمرها في الفرقة إليها فأبى أن يفعل وقال في ذلك\n(أرق الحزين وعاده سهده ... لطوارق الهم التي ترده)\n(وذكرت من لانت له كبدي ... فأبى فليس تلين لي كبده)\n(ونأى فليس بنازل بلدي ... أبدا وليس بمصلحي بلده)\n(فصدعت حين أبى مودته ... صدع الزجاجة دائم أبده)\n(وعرفت أن الطير قد صدقت ... يوم الكدانة شر ما تعده)\n(فاصبر فإن لكل ذي أجل ... يوما يجيء فينقضي عدده)\n(ماذا تعاتب من زمانك إذ ... ظعن الحبيب وحل بي كمده)\nالا وخاطب أباها يحيى بن يعمر في ذلك فقال له إنها امرأة برزة عاقلة لا يفتات على مثلها بأمرها وما عندها عنك من رغبة ولكنها امرأة في خلقها شدة ولها غيرة وقد بلغني أن لك زوجتين وما أراها تصبر على أن تكون ثالثة لهما فانظر في أمرك وشاور فيه فإما أن أقمت بالبصرة معها فعفت لك عن صاحبتيك إذ لا مجاورة بينهما وبينها ولا عشرة وإن شئت\nفارقتهما وأخرجها معك فصار إلى رحله مغموما وشاور ابن عم له يقال له وراد بن عمرو في ذلك فقال له إن في يحيى بن يعمر لرغبة لثروته وكثرة ماله وما ذكرته من جمال ابنته وما نحب أن تفارق زوجتيك وكانت إحداهما ابنة عمه والأخرى من أشجع فتقيم معها السنة بالبصرة ونمضي نحن فإن رغبت فيها تمسكت بها وأقمت بمكانك وإن رغبت في العود إلى بلدك كتبت إلينا فجئناك حتى تنصرف معنا إلى بلدك ففكر ليلة أجمع في ذلك ثم غدا عازما على الرجوع إلى الحجاز وقال\n(لئن أقمت بحيث الفيض في رجب ... حتى أهل به من قابل رجبا)\n(وراح في السفر وراد فهيجني ... ان الغريب إذا هيجته طربا)\n(إن الغريب يهيج الحزن صبوته ... إذا المصاحب حياه وقد ركبا)\n(قد قلت أمس لوراد وصاحبه ... عوجا على الخارجي اليوم واحتسبا)\n(وأبلغا أم سعد أن عانيها ... أعيا على شفعاء الناس فاجتنبا)\n(لما رأيت نجي القوم قلت لهم ... هل يعدون نجي القوم ما كتبا)\n(وقلت إني متى أجلب شفاعتكم ... أندم وإن أشق الغي ما اجتلبا)\n(وإن مثلي متى يسمع مقالتكم ... ويعرف العين يندم قبل أن يجبا)\n(إني وما كبر الحجاج تحملهم ... بزل المطايا بجنبي نخلة عصبا)\n(وما أهل به الداعي وما وقفت ... عليا ربيعة ترمي بالحصى الحصبا)\n(جهدا لمن ظن أني سوف أظعنها ... عن ربع غانية أخرى لقد كذبا)\n(أأبتغي الحسن في أخرى وأتركها ... فذاك حين تركت الدين والحسبا)\n(وما انقضى الهم من سعدى وما علقت ... مني الحبائل حتى رمتها حقبا)\n(وما خلوت بها يوما فتعجبني ... إلا غدا أكثر اليومين لي عجبا)\n(بل أيها السائلي ما ليس يدركه ... مهلا فإنك قد كلفتني تعبا)\n(كم من شفيع أتاني وهو يحسب لي ... حسبا فأقصره من دون ما حسبا)\n(فإن يكن لهواها أو قرابتها ... حب قديم فما غاب ولا ذهبا)\n(هما علي فإن أرضيتها رضيا ... عني وإن غضبت في باطل غضبا)\n(كائن ذهبت فرداني بكيدهما ... عما طلبت وجاءاها بما طلبا)\n(وقد ذهبت فلم أصبح بمنزلة ... إلا أنازع من أسبابها سببا)\n(ويلمها خلة لو كنت مسجحة ... أو كنت ترجع من عصريك ما ذهبا)\n(أنت الظعينة لا ترمى برمتها ... ولا يفجعها ابن العم ما اصطحبا)\nخبرني عيسى بن الحسين قال حدثنا الزبير بن بكار قال حدثني سليمان بن عياش السعدي قال قدم أعراب من بني سليم أقحمتهم السنة إلى الروحاء فخطب إلى\nبعضهم رجل من الموالي من أهل الروحاء فزوجه فركب محمد بن بشير الخارجي إلى المدينة وواليها يومئذ إبراهيم بن هشام بن إسماعيل بن هشام بن الوليد بن المغيرة فاستعداه الخارجي على المولى فأرسل إبراهيم إليه وإلى النفر السلميين وفرق بين المولى وزوجته وضربه مائتي سوط وحلق رأسه ولحيته وحاجبيه فقال محمد بن بشير في ذلك\n(شهدت غداة خصم بني سليم ... وجوها من قضائك غير سود)\n(قضيت بسنة وحكمت عدلا ... ولم ترث الحكومة من بعيد)\n(إذا غمز القنا وجدت لعمري ... قناتك حين تغمز خير عود)\n(إذا عض الثقاف بها اشمأزت ... أبي النفس بائنة الصعود)","topic":"أخبار محمد بن بشير الخارجي ونسبه","topicNo":198,"sp":1,"spl":"عائشة بنت يحيى تأبى أن تتزوجه"},
{"id":"b198-3","bab":"الجزء 16","sec":"عائشة بنت يحيى تأبى أن تتزوجه","page":"ج16 ص113","text":"(حمى حدبا لحوم بنات قوم ... وهم تحت التراب أبو الوليد)\n(وفي المئتين للمولى نكال ... وفي سلب الحواجب والخدود)\n(إذا كافأتهم ببنات كسرى ... فهل يجد الموالي من مزيد)\n(فأي الحق أنصف للموالي ... من اصهار العبيد إلى العبيد)\nدثني عمي قال حدثنا الزبير بن بكار قال حدثني سليمان بن عياش قال كان للخارجي عبد وكان يتلطف له ويخدمه حتى أعتقه وأعطاه مالا فعمل به وربح فيه ثم احتاج الخارجي بعد ذلك إلى معونة أو قرض في نائبة لحقته فبعث إلى مولاه في ذلك وقد كان المولى أثرى واتسعت حاله فحلف\nله أنه لا يملك شيئا فقال الخارجي في ذلك\n(يسعى لك المولى ذليلا مدقعا ... ويخذلك المولى إذا اشتد كاهله)\n(فأمسك عليك العبد أول وهلة ... ولا تنفلت من راحتيك حبائله)\nوقال أيضا\n(إذا افتقر المولى سعى لك جاهدا ... لترضى وإن نال الغنى عنك أدبرا)","topic":"أخبار محمد بن بشير الخارجي ونسبه","topicNo":198,"sp":2,"spl":"عائشة بنت يحيى تأبى أن تتزوجه"},
{"id":"b198-4","bab":"الجزء 16","sec":"تأخرت زوجتاه فتزوج ثالثة","page":"ج16 ص117","text":"حدثني عيسى بن الحسين قال حدثنا الزبير قال حدثني سليمان بن عياش السعدي قال كان محمد بن بشير الخارجي بين زوجتين له وكان يسكن الروحاء فأجدب عليه منزله فوجه غنما إلى سحابة وقعت برجفان وهو جبل يطل على مضيق يليل فشقت غيبتها عليه فقال لزوجتيه لو تحولتما إلى غنمنا فقالتا له بل تذهب فتطلع إليها وتصرفها إلى موضع قريب حتى نوافيك فيه فمضى وزودتاه وطبين وقالتا له اجمع لنا اللبن ووعدتاه موضعا من رجفان يقال له ذو القشع فانطلق فصرف غنمه إلى ذلك الموضع ثم انتظرهما فأبطأتا عليه وخالفته سحابة إليهما فأقامتا وقالتا يبلغ إلى غنمه ثم يأتينا فجعل يصعد في الجبل وينزل يتبصرهما فلا يراهما فبينما هو كذلك إذ أبصر امرأتين قد نزلتا فقال أنزل فأتحدث إليهما فإذا هو بامرأة مسنة ومعها بنت لها شابة فأعجبته فقال لها أتزوجينني ابنتك هذه قالت إن كنت كفوءا فانتسب لها فقالت أعرف النسب ولا أعرف الوجه ولكن يأتي أبوها فجاء\nأبوها فعرفه فأخبرته امرأته بما طلب فقال نعم وزوجه إياها فساق إليها قطعة من غنمه ثم بنى بها وانتظر فلم ير زوجتيه تقدمان عليه فارتحل إليهما بزوجته وبقية غنمه فلما طلع عليهما وقف فأخذ بيدها ثم أنشأ يقول\n(كأني موف للهلال عشية ... بأسفل ذات القشع منتظر القطر)\n(وأنتن تلبسن الجديدة بعدما ... طردت بطي الوطب في البلق والعفر)\n(فكان الذي قلتن أعدد بضاعة ... لناهد بيضاء الترائب والنحر)\n(كأن سموط الدر منها معلق ... بجيداء في ضال بوجرة أو سدر)\n(تكون بلاغا ثم لست بمخبر ... إذا وديت لي ما وددتن من أمري)\nخبرني الحسن بن علي قال حدثنا أحمد بن زهير قال حدثني مصعب قال حدثني أحمد بن زهير وحدثني الزبير بن بكار قال حدثني سليمان بن عياش قالا كان محمد بن بشير يتحدث إلى امرأة من مزينة وكان قومها قد جاوروهم ثم جاء الربيع وأخصبت بلاد مزينة فارتحلوا فقال محمد بن بشير\n(لو بينت لك يوم فراقها ... أن التفرق من عشية أو غد)\n(لشكوت إذ علق الفؤاد بهائم ... علق حبائل هائم لم يعهد)\n(وتبرجت لك فاستبتك بواضح ... صلت وأسود في النصيف معقد)\n(بيضاء خالصة البياض كأنها ... قمر توسط ليل صيف مبرد)\n(موسومة بالحسن ذات حواسد ... إن الجمال مظنة للحسد)\n(لم يطغها سرف الشباب ولم تضع ... عنها معاهدة النصيح المرشد)\n(خود إذا كثر الكلام تعوذت ... بحمى الحياء وإن تكلم تقصد)\n(وكأن طعم سلافة مشمولة ... تنصب في إثر السواك الأغيد)\n(وترى مدامعها ترقرق مقلة ... حوراء ترغب عن سواد الإثمد)\n(ماذا إذا برزت غداة رحيلهام ... الحسن تحت رقاق تلك الأبرد)\n(ولدت بأسعد أنجم فمحلها ... ومسيرها أبدا بطلق الأسعد)\n(الله يسعدها ويسقي دارها ... خضل الرباب سرى ولما يرعد)\nخبرني الحسن بن علي قال حدثنا أحمد بن زهير قال حدثني الزبير قال حدثني سليمان بن عياش قال صحب محمد بن بشير رفقة من قضاعة إلى مكة وكانت فيهم امرأة جميلة فكان يسايرها ويحادثها ثم خطبها إلى نفسها فقالت لا سبيل إلى ذلك لأنك لست لي بعشير ولا جاري في بلدي ولا أنا ممن تطمعه رغبة عن بلده ووطنه فلم يزل يحادثها ويسايرها حتى انقضى الحج ففرق بينهما\nنزوعهما إلى أوطانهما فقال الخارجي في ذلك\n(أستغفر الله ربي من مخدرة ... يوما بدا لي منها الكشح والكتد)\n(من رفقة صاحبونا في ندائهم ... كل حرام فما ذموا ولا حمدوا)\n(حتى إذا البدن كانت في مناحرها ... يعلو المناسم منها مزبد جسد)\n(وحلق القوم واعتموا عمائمهم ... واحتل كل حرام رأسه لبد)\n(أقبلت أسألها ما بال رفقتها ... وما أبالي أغاب القوم أم شهدوا)\n(فقربت لي واحلولت مقالتها ... وعوقتني وقالت بعض ما تجد)\n(أنى ينال حجازي بحاجته ... إحدى بني القين أدنى دارها برد)\nخبرني عيسى بن الحسين قال حدثنا الزبير قال حدثنا سليمان بن عياش قال خطب محمد بن بشير امرأة من قومه فقالت له طلق امرأتك حتى أتزوجك فأبى وانصرف عنها وقال في ذلك\n(أأطلب الحسن في أخرى وأتركها ... فذاك حين تركت الدين والحسبا)\n(هي الظعينة لا يرمى برمتها ... ولا يفجعها ابن العم ما اصطحبا)\n(فما خلوت بها يوما فتعجبني ... إلا غدا أكثر اليومين لي عجبا)\nدثني عيسى قال حدثنا الزبير قال بلغني عن صالح بن قدامة بن إبراهيم أن محمد بن حاطب الجمحي يروي شيئا من أخبار الخارجي","topic":"أخبار محمد بن بشير الخارجي ونسبه","topicNo":198,"sp":3,"spl":"تأخرت زوجتاه فتزوج ثالثة"},
{"id":"b198-5","bab":"الجزء 16","sec":"تأخرت زوجتاه فتزوج ثالثة","page":"ج16 ص117","text":"وأشعاره فأرسلت إليه مولى من موالينا يقال له محمد بن يحيى كان من الكتاب وسألته أن يكتب لي ما عنده فكان فيما كتب لنا قال زعم الخارجي واسمه محمد بن بشير وكنيته أبو سليمان وهو رجل من عدوان وكان يسكن الروحاء قال بينا نحن بالروحاء في عام جدب قليل الأمطار ومعنا سليمان بن الحصين وابن أخته وإذا بقطار ضخم كثير الثقل يهوي قادم من المدينة حتى نزلوا بجانب الروحاء الغربي بيننا وبينهم الوادي وإذا هم من الأنصار وفيهم سعيد بن عبد الرحمن بن حسان بن ثابت فلبثنا أياما ثم إذا بسليمان بن الحصين يقول لي أرسل إلي النساء يقلن أمالكم في الحديث حاجة فقلت لهن فكيف برجالكن قلن بلغنا أن لكم صاحبا يعرف بالخارجي صاحب صيد فإن أتاهم فحدثهم عن الصيد انطلقوا معه وخلوتم فتحدثتم قال فقلت لسليمان بئس لعمر الله ما أردت مني أأذهب إلى القوم فأغرهم وآثم وأتعب وتنالون أنتم حاجتكم دوني ما هذا لي برأي قال لي سليمان فأنظرني إذن أرسل إلى النساء وأخبرهن بقولك فأرسل إليهن فأخبرهن بما قلت فقلن قل له احتل لنا عليهم هذه المرة بما قلنا لك وعلينا أن نحتال لك المرة الأخرى قال الخارجي فخرجت حتى أتيت القوم فحدثتهم وذكرت لهم الصيد فطارت إليه أنفسهم فخرجت بهم وأخذت لهم كلابا وشباكا وتزودنا لثلاث وانطلقت أحدثهم وألهيهم فحدثتهم بالصدق حتى نفد ثم حدثتهم بما يشبه الصدق حتى نفد ثم صرحت لهم بمحض الكذب حتى مضت ثلاث\nوجعلت لا أحدثهم حديثا إلا قالوا صدقت وغبت بهم ثلاثا ما أعلم أنا عاينا صيدا فقلت في ذلك\n(إني لأعجب مني كيف افكههم ... أم كيف أخدع قوما ما بهم حمق !)\n(أظل في البيد ألهيهم وأخبرهم ... أخبار قوم وما كانوا وما خلقوا)\n(ولو صدقت لقلت القوم قد قدموا ... حين انطلقنا وآتي ساعة انطلقوا)\n(أم كيف تحرم أيد لم تخن أحدا ... شيئا وتظفر أيديهم وقد سرقوا)\n(ونرتمي اليوم حتى لا يكون له ... شمس ويرمون حتى يبرق الأفق)\n(يرمون أحور مخضوبا بغير دم ... دفعا وأنت وشاحا صيدك العلق)\n(تسعى بكلبين تبغيه وصيدهم ... صيد يرجى قليلا ثم يعتنق)\n(ما زلت أحدوهم حتى جعلتهم ... في أصل محنية ما إن بها طرق)\n(ولو تركتهم فيها لمزقهم ... شيخا مزينة إن قالا انعقوا نعقوا)\n(إن كنتم أبدا جاري صديقكم ... والدهر مختلف ألوانه طرق)\n(فمتعوني فإني لا أرى أحدا ... إلا له أجل في الموت مستبق)","topic":"أخبار محمد بن بشير الخارجي ونسبه","topicNo":198,"sp":4,"spl":"تأخرت زوجتاه فتزوج ثالثة — رثاؤه سليمان بن الحصين"},
{"id":"b198-6","bab":"الجزء 16","sec":"رثاؤه سليمان بن الحصين","page":"ج16 ص122","text":"قال سليمان بن عياش ومات سليمان بن الحصين هذا وكان خليلا للخارجي مصافيا له وصديقا مخلصا فجزع عليه وحزن حزنا شديدا فقال يرثيه\n(يا أيها المتمني أن يكون فتى ... مثل ابن ليلى لقد خلى لك السبلا)\n(إن ترحل العيس كي تسعى مساعيه ... يشفق عليك وتعمل دون ما عملا)\n(لو سرت في الناس أقصاهم وأقربهم ... في شقة الأرض حتى تحسر الإبلا)\n(تبغي فتى فوق ظهر الأرض ما وجدوا ... مثل الذي غيبوا في بطنها رجلا)\n(اعدد ثلاث خصال قد عرفن له ... هل سب من أحد أو سب أو بخلا)\nال سليمان بن عياش لما مات عبد العزيز بن مروان ونعي إلى أخيه عبد الملك تمثل بأبيات الخارجي هذه وجعل يرددها ويبكي أخبرني عيسى قال حدثنا الزبير قال حدثني عمي عن أبيه قال قال الرشيد يوما لجلسائه أنشدوني شعرا حسنا في امرأة خفرة كريمة فأنشدوا فأكثروا وأنا ساكت فقال لي إيه يا بن مصعب أما إنك لو شئت لكفيتنا سائر اليوم فقلت نعم يا أمير المؤمنين لقد أحسن محمد بن بشير الخارجي حيث يقول\n(بيضاء خالصة البياض كأنها ... قمر توسط جنح ليل مبرد)\n(موسومة بالحسن ذات حواسد ... ان الحسان مظنة للحسد)\n(وترى مدامعها ترقرق مقلة ... حوراء ترغب عن سواد الإثمد)\n(خود إذا كثر الكلام تعوذت ... بحمى الحياء وإن تكلم تقصد)\n(لم يطغها شرف الشباب ولم تضع ... منها معاهدة النصيح المرشد)\n(وتبرجت لك فاستبتك بواضح ... صلت وأسود في النصيف معقد)\n(وكأن طعم سلافة مشمولة ... بالريق في أثر السواك الأغيد)\nقال الرشيد هذا والله الشعر لا ما أنشدتمونيه سائر اليوم ثم أمر مؤدب ابنيه محمد الأمين وعبد الله المأمون فرواهما الأبيات","topic":"أخبار محمد بن بشير الخارجي ونسبه","topicNo":198,"sp":4,"spl":"تأخرت زوجتاه فتزوج ثالثة — رثاؤه سليمان بن الحصين"},
{"id":"b198-7","bab":"الجزء 16","sec":"الخارجي رجل النساء","page":"ج16 ص124","text":"أخبرني الحسن بن علي قال حدثنا أحمد بن زهير قال حدثنا الزبير بن بكار قال حدثني سليمان بن عياش قال كان محمد بن بشير الخارجي يتحدث إلى عبدة بنت حسان المزنية ويقيل عندها أحيانا وربما بات عندها ضيفا لإعجابه بحديثها فنهاها قومها عنه وقالوا ما مبيت رجل بامرأة أيم فجاءها ذات يوم فلم تدخله خباءها وقالت له قد نهاني قومي عنك وكان قد أمسى فمنعته المبيت وقالت لا تبت عندنا فيظن بي وبك شر فانصرف وقال فيها\n(ظللت لدى أطنابها وكأنني ... أسير معنى في مخلخله كبل)\n(أخير إما جلسة عند دارها ... وإما مراح لا قريب ولا سهل)\n(فإنك لو أكرمت ضيفك لم يعب ... عليك الذي تأتين حمو ولا بعل)\n(وقد كان ينميها إلى ذروة العلا ... أب لا تخطاه المطية والرحل)\n(فهل أنت إلا جنة عبقرية ... يخالط من خالطت من حبكم خبل)\n(وهل أنت إلا نبعة كان أصلها ... نضارا فلم يفضحك فرع ولا أصل)\n(صددت امرأ عن ظل بيتك ماله ... بواديك لولاكم صديق ولا أهل)\nأخبرني الحسن بن علي قال حدثنا أحمد بن زهير قال حدثنا الزبير قال حدثني سليمان بن عياش قال خرج محمد وسليمان ابنا عبيد الله بن الحصين الأسلميان حتى أتيا امرأة من الأنصار من بني ساعدة فبرزت لهما وتحدثا عندها وقالا لها هل لك في صاحب لنا ظريف شاعر فقالت من هو قالا محمد بن بشير الخارجي قالت لا حاجة بي إلى لقائه ولا تجيئاني به معكما فإنكما إن أتيتما به لم آذن لكما فجاءا به معهما وأخبراه بما قالت لهما وأجلساه في بعض الطريق وتقدما إليها فخرجت إليهما وجاءهما الخارجي بعد خروجها إليهما فرحبا به وسلما عليه فقالت لهما من هذا قالا هذا الخارجي الذي كنا نخبرك عنه فقالت والله ما أرى فيه من خير وما أشبهه إلا بعبدنا أبي الجون فاستحيا الخارجي وجلس هنيهة ثم قام من عندها وعلقها قلبه فقال فيها\n(ألا قد رابني ويريب غيري ... عشية حكمها حيف مريب)\n(وأصبحت المودة عند ليلى ... منازل ليس لي فيها نصيب)\n(ذهبت وقد بدا لي ذاك منها ... لأهجوها فيغلبني النسيب)\n(وأنسى غيظ نفسي إن قلبي ... لمن واددت فيئته قريب)\n(فلا قلب مصر كل ذنب ... ولا راض بغير رضا غضوب)\n(فدعها لست صاحبها وراجع ... حديثك إن شأنكما عجيب)\nال وبلغ الأشجعية زوجة محمد بن بشير ما قالته الأنصارية فعيرته بذلك وكانت إذا أرادت غيظه كنته أبا الجون فقال في ذلك\n(وأيدي الهدايا ما رأيت معاتبا ... من الناس إلا الساعدية أجمل)\n(وقد أخطأتني يوم بطحاء منعم ... لها كفف يصطاد فيها وأحبل)\n(وقد قال أهلي خير كسب كسبته ... أبو الجون فاكسب مثلها حين ترحل)\n(فإن بات إيضاعي بأمر مسرة ... لكن فما تسخطن في العيش أطول)\nخبرني الحسن قال حدثنا أحمد قال حدثنا الزبير قال حدثني سليمان بن عياش قال اجتمع محمد بن بشير الخارجي وسائب بن ذكوان راوية كثير بمكة فوافقا نسوة من بني غفار يتحدثن فجلسا إليهن وتحدثا معهن حتى تفرقن وبقيت واحدة منهن تحدث الخارجي وتستنشده شعره حتى أصبحوا فقال لهم رجل مر بهم أما تبرحون عن هذا الشعر وأنتم حرم ولا تدعون إنشاده وقول الزور في المسجد فقالت المرأة كذبت لعمر الله ما قول الشعر بزور ولا السلام والحديث حرام على محرم ولا محل فانصرف الرجل وقال فيها الخارجي\n(أما لك أن تزور وأنت خلو ... صحيح القلب أخت بني غفار)\n(فما برحت تعيرك مقلتيها ... فتعطيك المنية في استتار)\n(وتسهو في حديث القوم حتى ... يبين بعض ذلك ما تواري)\n(فمت يا قلب ما بك من دفاع ... فينجيك الدفاع ولا فرار)\n(فلم أر طالبا بدم كمثلي ... أود وحسن مطلوب بثار)\n(إذا ذكروا بثأري قلت سقيا ... لثأري ذي الخواتم والسوار)\n(وما عرفت دمي فتبوء منه ... برهن في حبالي أو ضمار)\n(وقد زعم العواذل أن يومي ... ويومك بالمحصب ذي الجمار)\n(من الإغباء ثم زعمت أن لا ... وقلت لدى التنازع والتمار)\n(كذبتم ما السلام بقول زور ... وما اليوم الحرام بيوم ثار)\n(ولا تسليمنا حرما بإثم ... ولا الحب الكريم لنا بعار)\n(فإن لم نلقكم فسقى الغوادي ... بلادك والرويات السواري)\nقال سليمان وفي هذه المرأة يقول الخارجي وقد رحلوا عن مكة فودعها وتفرقوا\n(يا أحسن الناس لولا أن نائلها ... قدما لمن يبتغي ميسورها عسر)\n(وإنما دلها سحر تصيد به ... وإنما قلبها للمشتكي حجر)\n(هل تذكرين كما لم أنس عهدكم ... وقد يدوم لعهد الخلة الذكر)","topic":"أخبار محمد بن بشير الخارجي ونسبه","topicNo":198,"sp":5,"spl":"الخارجي رجل النساء"},
{"id":"b198-8","bab":"الجزء 16","sec":"الخارجي رجل النساء","page":"ج16 ص124","text":"(قولي وركبك قد مالت عمائمهم ... وقد سقاهم بكأس الشقوة السفر)\n(يا ليت أني بأثوابي وراحلتي ... عبد لأهلك هذا العام مؤتجر)\n(فقد أطلت اعتلالا دون حاجتنا ... بالحج أمس فهذا الحل والسفر)\n(ما بال رأيك إذ عهدي وعهدكم ... إلفان ليس لنا في الود مزدجر)\n(فكان حظك منها نظرة طرفت ... إنسان عينك حتى ما بها نظر)\n(أكنت أبخل من كانت مواعده ... دينا إلى أجل يرجى وينتظر)\n(وقد نظرت وما ألفيت من أحد ... يعتاده الشوق إلا بدؤه النظر)\n(أبقت شجى لك لا ينسى وقادحة ... في أسود القلب لم يشعر بها أخر)\n(جنية أو لها جن يعلمها ... رمي القلوب بقوس ما لها وتر)\n(تجلو بقادمتي ورقاء عن برد ... حمر المفاغر في أطرافها أشر)\n(خود مبتلة ريا معاصمها ... قدر الثياب فلا طول ولا قصر)\n(إذا مجاسدها اغتالت فواضلها ... منها روادف فعمات ومؤتزر)\n(إن هبت الريح حنت في وشائحها ... كما يجاذب عود القينة الوتر)\n(بيضاء تعشو بها الأبصار إن برزت ... في الحج ليلة إحدى عشرة القمر)\n(ألا رسول إذا بانت يبلغها ... عنا وإن لم تؤلف بيننا المرر)\n(أني - بآية وجد قد ظفرت به ... مني ولم يك في وجدي بكم ظفر)\n(- قتيل يوم تلاقينا وأن دمي ... عنها وعمن أجارت من دمي هدر)\n(تقضين في ولا أقضي عليك كما ... يقضي المليك على المملوك يقتسر)\n(إن كان ذا قدرا يعطيك نافلة ... منا ويحرمنا ما أنصف القدر)\nخبرني عيسى بن الحسين قال حدثنا الزبير قال حدثني سليمان بن عياش قال كان الخارجي قدم البصرة فتزوج بها امرأة من عدوان كانت موسرة\nفأقام عندها بالبصرة مدة ثم توخم البصرة فطالبها بأن ترحل معه إلى الحجاز فقالت ما أنا بتاركة مالي وضيعتي ههنا تذهب وتضيع وأمضي معك إلى بلد الجدب والفقر والضيق فإما أن أقمت هاهنا أو طلقتني فطلقها وخرج إلى الحجاز ثم ندم وتذكرها فقال\n(دامت لعينك عبرة وسجوم ... وثوت بقلبك زفرة وهموم)\n(طيف لزينب ما يزال مؤرقي ... بعد الهدو فما يكاد يريم)\n(إذا تعرض في المنام خيالها ... نكأ الفؤاد خيالها المحلوم)\n(أجعلت ذنبك ذنبه وظلمته ... عند التحاكم والمدل ظلوم)\n(ولئن تجنيت الذنوب فإنه ... ذو الداء يعذر والصحيح يلوم)\n(ولقد أراك غداة بنت وعهدكم ... في الوصل لا حرج ولا مذموم)\n(أضحت تحكمك التجارب والنهى ... عنه ويكلفه بك التحكيم)\n\n(برأ الألى علقوا الحبائل قبله ... فنجوا وأصبح في الوثاق يهيم)\n(ولقد أردت الصبر عنك فعاقني ... علق بقلبي من هواك قديم)\n(ضعفت معاهد حبهن مع الصبا ... ومع الشباب فبن وهو مقيم)\n(يبقى على حدث الزمان وريبه ... وعلى جفائك إنه لكريم)\n(وجنيت حين صححت وهو بدائه ... شتان ذاك مصحح وسقيم)\n(وأديته زمنا فعاذ بحلمه ... إن المحب عن الحبيب حليم)\n(وزعمت أنك تبخلين وشفه ... شوق إليك وإن بخلت أليم)\nغنى في هذه الأبيات الدارمي - خفيف رمل - بالوسطى عن الهشامي وفيه لعريب - خفيف ثقيل - مطلق وهو الذي يغنى الآن ويتعارفه الناس أخبرني عيسى بن الحسين قال حدثنا الزبير قال حدثني سليمان بن عياش السعدي قال كان الخارجي منقطعا إلى أبي عبيدة بن عبد الله بن زمعة وكان يكفيه مؤونته ويفضل عليه ويعطيه في كل سنة ما يكفيه ويغنيه ويغني قومه وعياله من البر والتمر والكسوة في الشتاء والصيف ويقطعه القطعة بعد القطعة من إبله وغنمه وكان منقطعا إليه وإلى زيد بن الحسن وابنه الحسن بن زيد وكلهم به بر وإليه محسن فمات أبو عبيدة وكان ينزل الفرش من ملل وكان الخارجي ينزل الروحاء فقال يرثيه\n(ألا أيها الناعي ابن زينب غدوة ... نعيت الندى دارت عليه الدوائر)\n(لعمري لقد أمسى قرى الضيف عاتما ... بذي الفرش لما غيبتك المقابر)\n(إذا سوفوا نادوا صداك ودونه ... صفيح وخوار من الترب مائر)\n(ينادون من أمسى تقطع دونه ... من البعد أنفاس الصدور الزوافر)\n(فقومي اضربي عينيك يا هند لن تري ... أبا مثله تسمو إليه المفاخر)\nال الزبير فحدثني سليمان بن عياش قال كانت هند بنت أبي عبيدة عند عبد الله بن حسن بن حسن فلما مات أبوها جزعت عليه جزعا شديدا ووجدت وجدا عظيما فكلم عبد الله بن الحسن محمد بن بشير الخارجي أن يدخل إليها فيعزيها ويسليها عن أبيها فدخل إليها معه فلما نظر إليها صاح بأعلى صوته\n(قومي اضربي عينيك يا هند لن تري ... أبا مثله تسمو إليه المفاخر)","topic":"أخبار محمد بن بشير الخارجي ونسبه","topicNo":198,"sp":6,"spl":"الخارجي رجل النساء","song":1},
{"id":"b198-9","bab":"الجزء 16","sec":"الخارجي رجل النساء","page":"ج16 ص124","text":"(وكنت إذا فاخرت أسميت والدا ... يزين كما زان اليدين الأساور)\n(فإن تعوليه يشف يوما عويله ... غليلك أو يعذرك بالنوح عاذر)\n(وتحزنك ليلات طوال وقد مضت ... بذي الفرش ليلات تسر قصائر)\n(فلقاه رب يغفر الذنب رحمة ... إذا بليت يوم الحساب السرائر)\n(إذا ما ابن زاد الركب لم يمس ليلة ... قفا صفر لم يقرب الفرش زائر)\n(لقد علم الأقوام أن بناته ... صوادق إذ يندبنه وقواصر)\nال فقامت هند فصكت وجهها وعينيها وصاحت بويلها وحربها والخارجي يبكي معها حتى لقيا جهدا فقال له عبد الله بن الحسن ألهذا دعوتك ويحك فقال له أفظننت أني أعزيها عن أبي عبيدة والله ما يسليني عنه أحد ولا لي عنه ولا عن فقده صبر فكيف يسليها عنه من ليس يسلو بعده","topic":"أخبار محمد بن بشير الخارجي ونسبه","topicNo":198,"sp":7,"spl":"الخارجي رجل النساء"},
{"id":"b198-10","bab":"الجزء 16","sec":"يمدح زيد بن الحسن ويبكي سليمان بن الحصين","page":"ج16 ص132","text":"أخبرني عيسى قال حدثني الزبير قال حدثني سليمان بن عياش قال وعد رجل محمد بن بشير الخارجي بقلوص فمطله فقال فيه يذمه ويمدح زيد بن الحسن بن علي بن أبي طالب عليه السلام\n(لعلك والموعود حق وفاؤه ... بدا لك في تلك القلوص بداء)\n(فإن الذي ألقى إذا قال قائل ... من الناس هل أحسستها لعناء)\n(يقول الذي يبدي الشمات وقوله ... علي وإشمات العدو سواء)\n(دعوت - وقد أخلفتني الوعد - دعوة ... بزيد فلم يضلل هناك دعاء)\n(بأبيض مثل البدر عظم حقه ... رجال من آل المصطفى ونساء)\nبلغت الأبيات زيد بن الحسن فبعث إليه بقلوص من خيار إبله فقال يمدحه\n(إذا نزل ابن المصطفى بطن تلعة ... نفى جدبها واخضر بالنبت عودها)\n(وزيد ربيع الناس في كل شتوة ... إذا أخلفت أنواؤها ورعودها)\n(حمول لأشناق الديات كأنه ... سراج الدجى إذ قارنته سعودها)\nخبرني عيسى قال حدثني الزبير قال حدثني سليمان بن عياش قال نظر الخارجي إلى نعش سليمان بن الحصين وقد أخرج فهتف بهم فقال\n(ألم تروا أن فتى سيدا ... راح على نعش بني مالك)\n(لا أنفس العيش لمن بعده ... وأنفس الهلك على الهالك)\nقال فيه أيضا\n(ألا أيها الباكي أخاه وإنما ... تفرق يوم الفدفد الأخوان)\n(أخي يوم أحجار الثمام بكيته ... ولو حم يومي قبله لبكاني)\n(تداعت به أيامه فاخترمنه ... وأبقين لي شجوا بكل زمان)\n(فليت الذي ينعى سليمان غدوة ... بكى عند قبري مثلها ونهاني)\n(فلو قسمت في الجن والإنس لوعتي ... عليه بكى من حرها الثقلان)\n(ولو كانت الأيام تطلب فدية ... إليه وصرف الدهر ما ألواني)\nخبرني عيسى قال حدثنا الزبير قال حدثنا سليمان بن عياش قال خرج محمد بن بشير يرمي الأروى ومعه جماعة فيهم رجل من الموالي من أهل السيالة فصعد المولى على صفاة بيضاء يرمي من فوقها فزلت قدمه عنها فصاح حتى سقط على الأرض وأحدث في ثيابه فقال الخارجي في ذلك\n(حرق يا صفاة في ذراك ... بالنار إن لم تمنعي أرواك)\n(تعلمي أن بذي الأراك ... أيتها الأروى - ذوي عراك)\n(قوما أعدوا شبك الشباك ... يبغون ضبعا قتلت أباك)\n(نعم ملوي الحيد المداك ... إذا صوت الجالب في أخراك)\n(ولم يقل منتصحا إياك ... بين مقاطيها ركبت فاك)\n(فعدت والطعن على كلاك ... مثل الأضاحي بيد النساك)\n(يرمى بالأكتاف على الأوراك ... كما أطحت العبد عن صفاك)\n(أما السيالي فلن ينساك ... لو يرتميك الناس ما رماك)\nأخبرني عيسى قال حدثنا الزبير قال حدثنا سليمان بن عياش قال كانت عند الخارجي بنت عم له فهجاه بعض قرابتها فأجابه الخارجي فغضبت زوجته وقالت هجوت قرابتي فقال الخارجي في ذلك\n(أما ما أقول لهم فعابت ... علي وقد هجيت فما تعيب)\n(فرمت وقد بدا لي ذاك منها ... لأهجوها فيمنعني النسيب)\n(فلا قلب يبصر كل ذنب ... ولا راض بغير رضا غضوب)\nخبرني الحسن بن علي قال حدثنا أحمد بن زهير قال حدثني مصعب قال وحدثني الزبير عن سليمان بن عياش قالا\nتزوج الخارجي جارية من بني ليث شابة وقد أسن وأسنت زوجته العدوانية فضربت دونه حجابا وتوارت عنه ودعت نسوة من عشيرتها فجلسن عندها يلهون ويتغنين ويضربن بالدفوف وعرف ذلك محمد فقال\n(لئن عانس قد شاب ما بين قرنها ... الى كعبها وابيض عنها شبابها)\n(صبت في طلاب اللهو يوما وعلقت ... حجابا لقد كانت يسيرا حجابها)\n(لقد متعت بالعيش حتى تشعبت ... من اللهو إذ لا ينكر اللهو بابها)\n(فبيني برغم ثم ظلي فربما ... ثوى الرغم منها حيث يثوي نقابها)\n(لبيضاء لم تنسب لجد يعيبها ... هجان ولم تنبح لئيما كلابها)\n(تأود في الممشى كأن قناعها ... على ظبية أدماء طاب شبابها)\n(مهفهفة الأعطاف خفاقة الحشى ... جميل محياها قليل عتابها)\n(إذا ما دعت بابني نزار وقارعت ... ذوي المجد لم يردد عليها انتسابها)","topic":"أخبار محمد بن بشير الخارجي ونسبه","topicNo":198,"sp":8,"spl":"يمدح زيد بن الحسن ويبكي سليمان بن الحصين"},
{"id":"b198-11","bab":"الجزء 16","sec":"إبراهيم المخزومي يصله بعد استعطاف","page":"ج16 ص135","text":"حدثنا الحسن بن علي قال حدثنا أحمد بن زهير قال حدثنا الزبير بن بكار قال حدثني عمي عن الضحاك بن عثمان قال لما ولي إبراهيم بن هشام الحرمين دخل إليه محمد بن بشير\nالخارجي وكان له قبل ذلك صديقا فأعرض عنه ولم يظهر به بشاشة ولا أنسا ثم عاوده فاستأذنه في الإنشاد فأعرض عنه وأخرجه الحاجب من داره وكان إبراهيم بن هشام تياها شديد الذهاب بنفسه فوقف له يوم الجمعة على طريقه إلى المسجد فلما حاذاه صاح به\n(يابن الهشامين طرا حزت مجدهما ... وما تخونه نقض وإمرار)\n(لا تشمتن بي الأعداء إنهم ... بيني وبينك سماع ونظار)\n(وإن شكري إن ردوا بغيظهم ... في ذمة الله إعلان وإسرار)\n(فاكرر بنائلك المحمود من سعة ... علي إنك بالمعروف كرار)\nفقال لحاجبه قل له يرجع إلي إذا عدت فرجع فأدخله إليه وقضى دينه وكساه ووصله وعاد إلى ما عهده منه أخبرني الحسن قال حدثنا أحمد بن زهير قال حدثني مصعب عن أبيه قال عثر بعروة بن أذينة حماره عند ثنية العويقل فقال عروة\n(ليت العويقل مسدود وأصبح من ... فوق الثنية فيه ردم يأجوج)\n(فتستريح ذوو الحاجات من غلظ ... ويسلك السهل يمشي كل منتوج)\nفقال محمد بن بشير الخارجي يرد عليه\n(سبحان ربك تب مما أتيت به ... ما يسدد الله يصبح وهو مرتوج)\n(وهل يسد وللحجاج فيه إذا ... ما أصعدوا فيه تكبير وتلجيج)\n(ما زال منذ أذل الله موطئه ... ومنذ آذن أن البيت محجوج)\n(يهدي له الوفد وفد الله مطربة ... كأنه شطب بالقد منسوج)\n(خل الطريق إليها إن زائرها ... والساكنين بها الشتم الأباليج)\n(لا يسدد الله نقبا كان يسلكه البيض ... البهاليل والعوج العناجيج)\n(لو سده الله يوما ثم عج له ... من يسلك النقب أمسى وهو مفروج)\nخبرني الحسن قال حدثنا أحمد بن زهير قال حدثنا مصعب قال كان للخارجي أخ يقال له بشار بن بشير وكان يجالس أعداءه ويعاشر من يعلم أنه مباين له وفيه يقول\n(وإني قد نصحت فلم تصدق ... بنصحي واعتددت فما تبالي)\n(وإني قد بدا لي أن نصحي ... لغيبك واعتدادي في ضلال)\n(فكم هذا أذودك عن قطاعي ... كتذويد المحلأة النهال)\n(فلا تبغ الذنوب علي واقصد ... لأمرك من قطاع أو وصال)\n(فسوف أرى خلالك من تصافي ... إذا فارقتني وترى خلالي)\n(وإن جزاء عهدك إذ تولى ... بأن أغضي وأسكت لا أبالي)\nخبرني عيسى بن الحسين قال حدثنا الزبير بن بكار قال حدثنا سليمان بن عياش قال كان الخارجي معجبا بزوجته سعدى وكانت من أسوأ الناس خلقا وأشده على عشير فكان يلقى منها عنتا فغاضبها يوما لقول آذته به واعتزلها وانتقل إلى زوجته الأخرى فأقام عندها ثلاثا ثم اشتاق إلى سعدى وتذكرها وبدا له في الرجوع إلى بيتها فتحول إليها وقال\n(أراني إذا غالبت بالصبر حبها ... أبى الصبر ما ألقى بسعدى فأغلب)\n(وقد علمت عند التعاتب أننا ... إذا ظلمتنا أو ظلمنا سنعتب)\n(وإني وإن لم أجن ذنبا سأبتغي ... رضاها وأعفو ذنبها حين تذنب)\n(وإني وإن أنبت فيها يزيدني ... بها عجبا من كان فيها يؤنب)\nخبرني عيسى قال حدثنا الزبير قال حدثنا سليمان بن عياش قال كان بشار بن بشير أخو محمد بن بشير يعاديه ويجالس أعداءه فقال الخارجي فيه\n(كفاني الذي ضيعت مني وإنما ... يضيع الحقوق ظالما من أضاعها)\n(صنيعة من ولاك سوء صنيعها ... وولى سواك أجرها واصطناعها)\n(أبى لك كسب الخير رأي مقصر ... ونفس أضاق الله بالخير باعها)\n(إذا هي حثته على الخير مرة ... عصاها وإن همت بشر أطاعها)\n(فلولا رجال كاشحون يسرهم ... أذاك وقربى لا أحب انقطاعها)\n(إذا بان إن زلت بك النعل زلة ... فراق خلال لا تطيق ارتجاعها)\n(وإني متى أحمل على ذاك أطلع ... عليك عيوبا لا أحب اطلاعها)\n(فإن تك أحلام ترد إخاءنا ... علينا فمن هذا يرد سماعها)\n(سأنهاك نهيا مجملا وقصائدا ... نواصح تشفي من شؤون صداعها)\n(ومن يجتلب نحوي القصائد يجتلب ... قراه ويتبع من يحب اتباعها)\n(إذا ما الفتى ذو اللب حلت قصائد ... إليه فيخل للقوافي رباعها)","topic":"أخبار محمد بن بشير الخارجي ونسبه","topicNo":198,"sp":9,"spl":"إبراهيم المخزومي يصله بعد استعطاف"},
{"id":"b198-12","bab":"الجزء 16","sec":"رثاؤه زيد بن حسن","page":"ج16 ص139","text":"أخبرني عيسى بن الحسين الوراق قال حدثنا الزبير قال حدثنا سليمان بن عياش قال لما دفن زيد بن حسن وانصرف الناس عن قبره جاء محمد بن بشير إلى الحسن بن زيد وعنده بنو هاشم ووجوه قريش يعزونه فأخذ بعضادتي الباب وقال\n(أعيني جودا بالدموع وأسعدا ... بني رحم ما كان زيد يهينها)\n(ولا زيد إلا أن يجود بعبرة ... على القبر شاكي نكبة يستكينها)\n(وما كنت تلقى وجه زيد ببلدة ... من الأرض إلا وجه زيد يزينها)\n(لعمر أبي الناعي لعمت مصيبة ... على الناس واختصت قصيا رصينها)\n(وأنى لنا أمثال زيد وجده ... مبلغ آيات الهدى وأمينها)\n(وكان حليفيه السماحة والندى ... فقد فارق الدنيا نداها ولينها)\n(غدت غدوة ترمي لؤي بن غالب ... بجعد الثرى فوق امرىء ما يشينها)\n(أغر بطاحي بكت من فراقه ... عكاظ فبطحاء الصفا فحجونها)\n(فقل للتي يعلو على الناس صوتها ... ألا لا أعان الله من لا يعينها)\n(وأرملة تبكي وقد شق جيبها ... عليه فآبت وهي شعث قرونها)\n(ولو فقهت ما يفقه الناس أصبحت ... خواشع أعلام الفلاة وعينها)\n(نعاه لنا الناعي فظلنا كأننا ... نرى الأرض فيها آية حان حينها)\n(وزالت بنا أقدامنا وتقلبت ... ظهور روابيها بنا وبطونها)\n(وآب ذوو الألباب منا كأنما ... يرون شمالا فارقتها يمينها)\n(سقى الله سقيا رحمة ترب حفرة ... مقيم على زيد ثراها وطينها)\nال فما رئي يوم كان أكثر باكيا من يومئذ أخبرني محمد بن خلف بن المرزبان قال حدثنا أحمد بن الهيثم بن فراس قال حدثني العمري عن لقيط قال كان محمد بن بشير الخارجي من أهل المدينة وكانت له بنت عم سرية\nجميلة قد خطبها غير واحد من سروات قريش فلم ترضه فقال لأبيه زوجنيها فقال له كيف أزوجكها وقد رد عمك عنها أشراف قريش فذهب إلى عمه فخطبها إليه فوعده بذلك وقرب منه فمضى محمد إلى أبيه فأخبره فقال له ما أراه يفعل ثم عاوده فزوجه إياها فغضبت الجارية وقالت له خطبني إليك أشراف قريش فرددتهم وزوجتني هذا الغلام الفقير فقال لها هو ابن عمك وأولى الناس بك فلما بنى بها جعلت تستخف به وتستخدمه وتبعثه في غنمها مرة وإلى نخلها أخرى فلما رأى ذلك من فعلها قال شعرا ثم خلا في بيت يترنم به ويسمعها وهو\n(تثاقلت أن كنت ابن عم نكحته ... فملت وقد يشفى ذوو الرأي بالعذل)\n(فإنك إلا تتركي بعض ما أرى ... تنازعك أخرى كالقرينة في الحبل)\n(تلزك ما اسطاعت إذا كان قسمها ... كقسمك حقا في التلاد وفي البعل)\n(متى تحمليها منك يوما لحالة ... فتتبعها تحملك منها على مثل)\nال فصلحت ولم ير منها بعد ما سمعت شيئا يكرهه\n(علام هجرت ولم تهجري ... ومثلك في الهجر لم يعذر)\n(قطعت حبالك من شادن ... أغن قطوف الخطا أحور)\nلشعر لسديف مولى بني هاشم والغناء لأبي العبيس بن حمدون - خفيف ثقيل - بالسبابة والوسطى","topic":"أخبار محمد بن بشير الخارجي ونسبه","topicNo":198,"sp":10,"spl":"رثاؤه زيد بن حسن","song":1},
{"id":"b199-1","bab":"الجزء 16","sec":"ذكر سديف وأخباره","page":"ج16 ص142","text":"هو سديف بن ميمون مولى خزاعة وكان سبب ادعائه ولاء بني هاشم أنه تزوج مولاة لآل أبي لهب فادعى ولاءهم ودخل في جملة مواليهم على الأيام وقيل بل أبوه هو كان المتزوج مولاة اللهبيين فولدت منه سديفا فلما يفع وقال الشعر وعرف بالبيان وحسن العارضة ادعى الولاء في موالي أبيه فغلبوا عليه وسديف شاعر مقل من شعراء الحجاز ومن مخضرمي الدولتين وكان شديد التعصب لبني هاشم مظهرا لذلك في أيام بني أمية فكان يخرج إلى أحجار صفا في ظهر مكة يقال لها صفي السباب ويخرج مولى لبني أمية معه يقال له سباب فيتسابان ويتشاتمان ويذكران المثالب والمعايب ويخرج معهما من سفهاء الفريقين من يتعصب لهذا ولهذا فلا يبرحون حتى تكون بينهم الجراح والشجاج ويخرج السلطان إليهم فيفرقهم ويعاقب الجناة فلم تزل تلك العصبية بمكة حتى شاعت في العامة والسفلة فكانوا صنفين يقال لهما السديفية والسبابية طول أيام بني أمية ثم انقطع ذلك في أيام بني هاشم وصارت العصبية بمكة في الحناطين والحرارين\nأخبرني عمر بن عبيد الله بن جميل العتكي وأحمد بن عبد العزيز الجوهري قالا حدثنا عمر بن شبة قال حدثني فليح بن إسماعيل قال قال سديف قصيدة يذكر فيها أمر بني حسن بن حسن وأنشدها المنصور بعد قتله لمحمد بن عبد الله بن حسن فلما أتى على هذا البيت\n(يا سوءنا للقوم لا كفوا ولا ... إذ حاربوا كانوا من الأحرار)\nقال له المنصور أتحضهم علي يا سديف فقال لا ولكني أؤنبهم يا أمير المؤمنين وذكر ابن المعتز أن العوفي حدثه عن أحمد بن إبراهيم الرياحي قال سلم سديف بن ميمون يوما على رجل من بني عبد الدار فقال له العبدري من أنت يا هذا قال أنا رجل من قومك أنا سديف بن ميمون فقال له والله ما في قومي سديف ولا ميمون قال صدقت لا والله ما كان قط فيهم ميمون ولا مبارك\n(لعمرك إنني لأحب دارا ... تكون بها سكينة والرباب)\n(أحبهما وأبذل جل مالي ... وليس لعاتب عندي عتاب)\nلشعر للحسين بن علي بن أبي طالب عليهما السلام والغناء لابن سريج\n- رمل - بالبنصر وفيه للهذلي ثقيل أول بالسبابة في مجرى الوسطى عن إسحاق","topic":"ذكر سديف وأخباره","topicNo":199,"sp":0,"spl":"ذكر سديف وأخباره","song":1},
{"id":"b200-1","bab":"الجزء 16","sec":"أخبار الحسين بن علي ونسبه","page":"ج16 ص145","text":"الحسين بن علي بن أبي طالب بن هاشم بن عبد مناف بن قصي بن كلاب بن مرة بن كعب بن لؤي بن غالب وقد تكرر هذا النسب في عدة مواضع من هذا الكتاب واسم أبي طالب عبد مناف واسم عبد المطلب شيبة واسم هاشم عمرو وأم علي بن أبي طالب فاطمة بنت أسد بن هاشم بن عبد مناف وكانت أول هاشمية تزوجها هاشمي وهي أم سائر ولد أبي طالب وأم الحسين بن علي بن أبي طالب فاطمة بنت رسول الله وأمها خديجة بنت خويلد بن أسد بن عبد العزى بن قصي وكانت خديجة تكنى أم هند وكانت فاطمة تكنى أم أبيها ذكر ذلك قعنب بن محرز قال حدثنا أبو نعيم عن حسين بن زيد عن جعفر بن محمد عن أبيه وكان علي بن أبي طالب سمى الحسن حربا فسماه رسول الله الحسن ثم ولد له الحسين فسماه حربا فسماه رسول الله الحسين حدثني بذلك أحمد بن الجعد قال حدثنا عبد الرحمن بن صالح قال حدثنا يحيى بن عيسى قال حدثنا الأعمش عن سالم بن أبي الجعد قال قال علي بن أبي طالب كنت رجلا أحب الحرب فلما ولد الحسن هممت أن أسميه حربا فسماه رسول الله الحسن فلما ولد الحسين هممت أن أسميه حربا فسماه رسول الله الحسين ثم قال سميتهما باسمي ابني هارون شبر وشبير\nوأخبرنا محمد بن عبد الله بن سليمان الحضرمي قال حدثنا محمد بن يحيى الأحول قال حدثنا خلاد المقرىء قال حدثنا قيس بن الربيع بن أبي حصين عن يحيى بن وثاب عن ابن عمر قال كان على الحسن والحسين تعويذتان حشوهما من زغب جناح جبريل عليه السلام وهذا الشعر يقوله الحسين بن علي في امرأته الرباب بنت امرىء القيس بن عدي بن أوس بن جابر بن كعب بن عليم بن كلب بن وبرة بن تغلب ابن حلوان بن عمران بن الحاف بن قضاعة وأمها هند بنت الربيع بن مسعود بن معاذ بن حصين بن كعب بن عليم بن كلب وفي ابنته منها سكينة بنت الحسين واسم سكينة أميمة وقيل أمينة وقيل آمنة وسكينة لقب لقبت به قال مصعب فيما أخبرني به الطوسي عن زبير عنه اسمها آمنة أخبرني أحمد بن عبد العزيز وإسماعيل بن يونس قالا حدثنا عمر بن شبة قال حدثنا أبو نعيم عن عمر بن ثابت عن مالك بن أعين قال\nسمعت سكينة بنت الحسين تقول عاتب عمي الحسن أبي في أمي فقال\n(لعمرك إنني لأحب دارا ... تكون بها سكينة والرباب)\n(أحبهما وأبذل جل مالي ... وليس لعاتب عندي عتاب)\nدثنا محمد بن العباس اليزيدي قال حدثنا الخليل بن أسد قال حدثنا العمري عن ابن الكلبي عن أبيه قال قال لي عبد الله بن الحسن بن الحسن ما اسم سكينة بنت الحسين فقلت سكينة فقال لا اسمها آمنة وروى أن رجلا سأل عبد الله بن الحسن عن اسم سكينة فقال أمينة فقال له إن ابن الكلبي يقول أميمة فقال سل ابن الكلبي عن أمه وسلني عن أمي وقال المدائني حدثني أبو إسحاق المالكي قال سكينة لقب واسمها آمنة وهذا هو الصحيح حدثني أحمد بن محمد بن سعيد قال حدثنا يحيى بن الحسن العلوي قال حدثنا شيخ من قريش قال حدثنا أبو حذافة أو غيره قال أسلم امرؤ القيس بن عدي على يد عمر بن الخطاب رضي الله عنه\nفما صلى الله صلاة حتى ولاه عمر وما أمسى حتى خطب إليه علي عليه السلام ابنته الرباب على ابنه الحسين فزوجه إياها فولدت له عبد الله وسكينة ولدي الحسين عليهما السلام وفي سكينة وأمها يقول\n(لعمرك إنني لأحب دارا ... تحل بها سكينة والرباب)\nذكر البيت الآخر وزاد على البيتين\n(فلست لهم وإن غابوا مضيعا ... حياتي أو يغيبني التراب)\nنسخت هذا الخبر من كتاب أبي عبد الرحمن الغلابي وهو أتم قال حدثنا علي بن صالح عن علي بن مجاهد عن أبي المثنى محمد بن السائب الكلبي قال أخبرنا عبد الله بن حسن بن حسن قال حدثني خالي عبد الجبار بن منظور بن زبان بن سيار الفزاري قال حدثني عوف بن خارجة المري قال والله إني لعند عمر بن الخطاب رضي الله عنه في خلافته إذ أقبل رجل أفحج أجلى أمعر يتخطى رقاب الناس حتى قام بين يدي عمر فحياه بتحية الخلافة فقال له عمر فمن أنت قال امرؤ نصراني أنا امرؤ القيس بن عدي الكلبي قال فلم يعرفه عمر فقال له رجل من القوم هذا صاحب بكر بن وائل الذي أغار عليهم في الجاهلية يوم فلج قال فما تريد قال أريد الإسلام فعرضه عليه عمر رضي الله عنه فقبله ثم دعا له برمح فعقد له على من أسلم بالشام من قضاعة فأدبر الشيخ واللواء يهتز على رأسه","topic":"أخبار الحسين بن علي ونسبه","topicNo":200,"sp":0,"spl":"أخبار الحسين بن علي ونسبه"},
{"id":"b200-2","bab":"الجزء 16","sec":"أخبار الحسين بن علي ونسبه","page":"ج16 ص145","text":"قال عوف فوالله ما رأيت رجلا لم يصل لله ركعة قط أمر على جماعة من المسلمين قبله ونهض علي بن أبي طالب رضوان الله عليه من المجلس ومعه ابناه الحسن والحسين عليهم السلام حتى أدركه فأخذ ثيابه فقال له يا عم أنا علي بن أبي طالب ابن عم رسول الله وصهره وهذان ابناي الحسن والحسين من ابنته وقد رغبنا في صهرك فأنكحنا فقال قد أنكحتك يا علي المحياة بنت امرىء القيس وأنكحتك يا حسن سلمى بنت امرىء القيس وأنكحتك يا حسين الرباب بنت امرىء القيس وقال هشام بن الكلبي كانت الرباب من خيار النساء وأفضلهن فخطبت بعد قتل الحسين عليه السلام فقالت ما كنت لأتخذ حما بعد رسول الله قال المدائني حدثني أبو إسحاق المالكي قال قيل لسكينة واسمها آمنة وسكينة لقب أختك فاطمة ناسكة وأنت تمزحين كثيرا فقالت لأنكم سميتموها باسم جدتها المؤمنة - تعني فاطمة بنت رسول الله - وسميتموني باسم جدتي التي لم تدرك الإسلام تعني آمنة بنت وهب أم رسول الله","topic":"أخبار الحسين بن علي ونسبه","topicNo":200,"sp":1,"spl":"أخبار الحسين بن علي ونسبه — الرباب ترثي زوجها الحسين"},
{"id":"b200-3","bab":"الجزء 16","sec":"الرباب ترثي زوجها الحسين","page":"ج16 ص149","text":"أخبرني عمي قال حدثنا الكناني عن قعنب بن المحرز الباهلي عن محمد بن الحكم عن عوانة قال رثت الرباب بنت امرىء القيس أم سكينة بنت الحسين زوجها الحسين عليه السلام حين قتل فقالت\n(إن الذي كان نورا يستضاء به ... بكربلاء قتيل غير مدفون)\n(سبط النبي جزاك الله صالحة ... عنا وجنبت خسران الموازين)\n(قد كنت لي جبلا صعبا ألوذ به ... وكنت تصحبنا بالرحم والدين)\n(من لليتامى ومن للسائلين ومن ... يغني ويأوي إليه كل مسكين)\n(والله لا أبتغي صهرا بصهركم ... حتى أغيب بين الرمل والطين)\nخبرني الطوسي قال حدثني الزبير عن عمه قال أخبرني إسماعيل بن بكار قال حدثني أحمد بن سعيد عن يحيى بن الحسين العلوي عن الزبير عن عمه قال وأخبرني إسماعيل بن يعقوب عن عبد الله بن موسى قالا كان الحسن بن الحسن بن علي بن أبي طالب خطب إلى عمه الحسين فقال له الحسين عليهم السلام يابن أخي قد كنت أنتظر هذا منك انطلق معي فخرج به حتى أدخله منزله فخيره في ابنتيه فاطمة وسكينة فاختار فاطمة فزوجه إياها وكان يقال إن امرأة تختار على سكينة لمنقطعة القرين في الحسن وقال عبد الله بن موسى في خبره إن الحسين خيره فاستحيا فقال له قد اخترت لك فاطمة فهي أكثرهما شبها بأمي فاطمة بنت رسول الله","topic":"أخبار الحسين بن علي ونسبه","topicNo":200,"sp":1,"spl":"أخبار الحسين بن علي ونسبه — الرباب ترثي زوجها الحسين"},
{"id":"b200-4","bab":"الجزء 16","sec":"أحاديث عن سكينة","page":"ج16 ص150","text":"حدثني أحمد بن محمد بن سعيد قال حدثني يحيى بن الحسن العلوي قال كتب إلي عباد بن يعقوب يخبرني عن جدي يحيى بن سليمان بن الحسين العلوي قال كانت سكينة في مأتم فيه بنت لعثمان فقالت بنت عثمان أنا بنت الشهيد فسكتت سكينة فلما قال المؤذن أشهد أن محمدا رسول الله قالت سكينة هذا أبي أو أبوك فقالت العثمانية لا جرم لا أفخر عليكم أبدا\nأخبرني أحمد بن محمد قال حدثنا يحيى قال حدثنا مروان بن موسى القروي قال حدثنا بعض أصحابنا قال كانت سكينة تجيء في ستارة يوم الجمعة فتقوم بإزاء ابن مطيرة وهو خالد بن عبد الملك بن الحارث بن الحكم إذا صعد المنبر فإذا شتم عليا شتمته هي وجواريها فكان يأمر الحرس فيضربون جواريها أخبرني الطوسي عن الزبير عن عمه مصعب قال كانت سكينة عفيفة سليمة برزة من النساء تجالس الأجلة من قريش وتجتمع إليها الشعراء وكانت ظريفة مزاحة أخبرني الطوسي قال حدثنا الزبير عن عمه قال حدثني معاوية بن بكر قال قالت سكينة أدخلت على مصعب وأنا أحسن من النار الموقدة أخبرني الحسن بن علي قال حدثني محمد بن موسى عن أبي أيوب المديني عن مصعب قال كانت سكينة أحسن الناس شعرا فكانت تصفف جمتها تصفيفا لم ير أحسن منه حتى عرف ذلك فكانت تلك الجمة تسمى السكينية وكان عمر بن عبد العزيز إذا وجد رجلا قد صفف جمته السكينية جلده وحلقه\nأخبرني أحمد بن عبيد الله بن عمار عن أحمد بن سليمان بن أبي شيخ عن أبيه عن أبي سفيان الحميري قال بعثت سكينة بنت الحسين عليهما السلام إلى حبيش بن دلجة بغالية لأنه كان من أخوالها فلما وصلت إليه قال فأين كانت - حبيش بن دلجة - عن الصياح يقدر أن الصياح أرفع من الغالية قال محمد بن سلام كانت سكينة مزاحة فلسعتها دبرة فولولت فقالت لها أمها مالك يا سيدتي وجزعت فقالت لسعتني دبيرة مثل الأبيرة فأوجعتني قطيرة وقال هارون بن أبي عبيد الله حدثني ضمرة بن ضمرة قال أجلست سكينة شيخا فارسيا على سلة بيض وبعثت إلى سليمان بن يسار كأنها تريد أن تسأله عن شيء فجاءها إكراما لها فأمرت من أخرج إليه ذلك الشيخ جالسا على السلة فيها البيض فولى يسبح قال وبعثت سكينة إلى صاحب الشرطة بالمدينة أنه دخل علينا شامي\nفابعث إلينا بالشرط فركب ومعه الشرط فلما أتى إلى الباب أمرت ففتح له وأمرت جارية من جواريها فأخرجت إليه برغوثا فقال ما هذا قالت هذا الشامي الذي شكوناه فانصرفوا يضحكون أخبرني محمد بن جعفر النحوي قال حدثنا أحمد بن القاسم قال حدثنا أبو هفان قال حدثنا سيف بن إبراهيم صاحب إبراهيم بن المهدي قال حدثني إبراهيم بن المهدي أن الرشيد لما ولاه دمشق استوهبه صحبة دبية والغاضري وعبيدة بن أشعب وحكم الوادي فوهبهم له فأشخصهم معه قال فكان فيما حدثني به عبيدة قال إبراهيم ركبت حمارة وهو عديلي ونمت على ظهرها فلما بلغنا ثنية العقاب اشتد علي البرد فاحتجت إلى الزيادة من الدثار فدعوت بدواج سمور فألقيته على ظهري ودعوت بمن كان معي في سمري في تلك الليلة وكانوا\nحولي فقلت لابن أشعب حدثني بأعجب ما تعلم من طمع أبيك فقال أعجب من طمع أبي طمع ابنه فقلت وما بلغ من طمعك فقال دعوت آنفا لما اشتد عليك البرد بدواج سمور لتستدفىء به فلم أشك أنك دعوت به لتجعله علي فغلبني الضحك وخلعت عليه الدواج ثم قلت له ما أحسب لك قرابة بالمدينة فقال اللهم غفرا لي بالمدينة قرابات وأي قرابات قلت أيكونون عشرة قال وما عشرة قلت فعشرين قال اللهم غفرا لا تذكر العشرات ولا المئين وتجاوز ذكر الألوف إلى ما هو أكثر منها قلت ويحك ليس بينك وبين أشعب أحد فكيف يكون هذا فقال إن زيد بن عمرو بن عثمان بن عفان تزوج سكينة بنت الحسين فخف أبي على قلبها فأحسنت إليه وكانت عطاياها خلاف عطايا مولاه فمال إليها بكليته قال وحج سليمان بن عبد الملك وهو خليفة فاستأذن زيد بن عمرو سكينة وأعلمها أنها أول سنة حج فيها الخليفة وأنه لا يمكنه التخلف عن الحج معه وكانت لزيد ضيعة يقال لها العرج وكان له فيها جوار فأعلمته أنها لا تأذن له إلا أن يخرج أشعب معه فيكون عينا لها عليه ومانعا له من العدول إلى العرج ومن اتخاذ جارية لنفسه في بدأته ورجعته فقنع بذلك وأخرج أشعب معه وكان له فرس كثير الأوضاح حسن المنظر يصونه عن","topic":"أخبار الحسين بن علي ونسبه","topicNo":200,"sp":2,"spl":"أحاديث عن سكينة"},
{"id":"b200-5","bab":"الجزء 16","sec":"أحاديث عن سكينة","page":"ج16 ص150","text":"الركوب إلا في مسايرة خليفة أو أمير أو يوم زينة وله سرج يصونه ولا يركب به غير ذلك الفرس وكان معه طيب لا يتطيب به إلا في مثل ذلك اليوم الذي يركب فيه وحلة موشية يصونها عن اللبس إلا في يوم يريد التجمل فيه بها فحج مع سليمان وكانت له عنده حوائج كثير فقضاها ووصله وأجزل صلته وانصرف سليمان من حجه ولم يسلك طريق المدينة وانصرف ابن عثمان يريد المدينة فنزل على ماء لبني عامر بن صعصعة ودعا أشعب فأحضره وصر صرة فيها أربعمائة دينار وأعلمه أنه ليس بينه وبين العرج إلا أميال وأنه إن أذن له في المسير إليها والمبيت بها عند جواريه غلس إليه فوافى وقت ارتحال الناس ووهب له أربعمائة دينار فقبل يده ورجله وأذن له في السير إلى حيث أحب وحلف له أنه يحلف لسكينة بالأيمان المحرجة أنه ما سار إلى العرج ولا اتخذ جارية منذ فارق سكينة إلى أن يرجع إليها فدفع إليه مولاه الدنانير ومضى قال أبو إسحاق قال ابن أشعب حدثني أبي أنه لا يتوهم أن مولاه سار نصف ميل حتى رأى في الماء الذي كان عليه رحل زيد جاريتين عليهما قربتان فألقتا القربتين وألقتا ثيابهما عنهما ورمتا بأنفسهما في الغدير وعامتا فيه ورأى من مجردهما ما أعجبه واستحسنه فسألهما عند خروجهما من الماء عن نسبهما فأعلمتاه أنهما من إماء نسوة خلوف لبني عامر بن صعصعة هن بالقرب من ذلك الغدير فسألهما هل سبيل إلى مولياتهما لمحادثة شيخ\nحسن الخلق طيب العشرة كثير النوادر فقالتا وأنى لهن بمن هذه صفته فقال لهما أنا ذاك فقالتا انطلق معنا فوثب إلى فرس زيد فأسرجه بسرجه الذي كان يسرجه به ويركبه ودعا بحلته التي كان يضن بها فلبسها وأحضر السفط الذي كان فيه طيبه فتطيب منه وركب الفرس ومضى معهما حتى وافى الحي فأقام في محادثة أهله إلى قرب وقت صلاة العصر فأقبل في ذلك الوقت رجال الحي وقد انصرفوا غانمين من غزاتهم وأقبلت تمر به الرعلة بعد الرعلة فيقفون به فيقولون ممن الرجل فينتسب في نسب زيد فيقول كل من اجتاز به ما نرى به بأسا وينصرفون عنه إلى قرب غروب الشمس فأقبل شيخ فان على حجر هرمة هزيل ففعل مثل ما كان يفعل من اجتاز فسأله مثلما يسألون عنه فأخبره بمثل ما كان يخبر من تقدمه فقال مثل قولهم قال ابن أشعب قال أبي ثم رأيت الشيخ وقد وقف بعد قوله فأوجست منه خيفة لأني رأيته قد جعل يده اليسرى تحت حاجبيه فرفعهما ثم استدار ليرى وجهي فركبت الفرس فما استويت عليه حتى سمعته يقول أقسم بالله ما هذا قرشي وما هذا إلا وجه عبد فركضت وركض خلفي فرأى حجره مقصرة فلما يئس من اللحاق بي انتزع سهما فرماني به فوقع في مؤخرة السرج فكسرها ودخلتني من صوته روعة أحدثت لها في الحلة ووافيت رحل مولاي فغسلت الحلة ونشرتها فلم تجف ليلا وغلس مولاي من العرج فوافاني في وقت الرحيل فرأى الحلة منشورة ومؤخرة السرج","topic":"أخبار الحسين بن علي ونسبه","topicNo":200,"sp":3,"spl":"أحاديث عن سكينة"},
{"id":"b200-6","bab":"الجزء 16","sec":"أحاديث عن سكينة","page":"ج16 ص150","text":"مكسورة والفرس قد أضر بها الركض وسفط الطيب مكسور الختم فسألني عن السبب فصدقته فقال لي ويحك أما كفاك ما صنعت بي حتى انتسبت في نسبي فجعلتني عند أشراف قومي من العرب جماشا وسكت عني فلم يقل لي أحسنت ولا أسأت حتى وافينا المدينة فلما وافاها سألته سكينة عن خبره فقال لها يا بنت رسول الله وما سؤالك إياي ولم يزل ثقتك معي وهو أمين علي فسليه عن خبري يصدقك عنه فسألتني فأخبرتها أني لم أنكر عليه شيئا ولم أمكنه من ابتياع جارية ولم أطلق له الاجتياز بالعرج فاستحلفتني على ذلك فلما حلفت لها بالأيمان المحرجة فيها طلاق أمك وثب فوقف بين يديها وقال أي ابنة عم ويا بنت رسول الله كذبك والله العلج ولقد أخذ مني أربعمائة دينار على أن أذن لي في المصير إلى العرج فأقمت بها يوما وليلة وغسلت بها عدة من جواري وها أنا ذا تائب إلى الله مما كان مني وقد جعلت توبتي هبتهن لك وتقدمت في حملهن إليك وهن موافيات المدينة في عشية اليوم فبيعهن أو عتقهن إليك الأمر فيه وأنت أعلم بما ترين في العبد السوء فأمرتني بإحضار أربعمائة الدينار فأحضرتها فأمرت بابتياع خشب بثلثمائة دينار وأمرت بنشره وليس عندي ولا عند أحد من أهل المدينة علم بما تريده فيه ثم أمرت بأن يتخذ بيت كبير وجعلت النفقة عليه في أجرة النجارين من المائة الدينار الباقية ثم أمرت بابتياع بيض وتبن وسرجين بما بقي من المائة الدينار بعد أجرة النجارين ثم أدخلتني البيت وفيه البيض والتبن والسرجين وحلفت بحق جدها ألا أخرج من ذلك البيت حتى أحضن ذلك البيض كله إلى أن يفقس ففعلت ذلك ولم أزل أحضنه حتى\nفقس كله فخرج منه الألوف من الفراريج وربيت في دار سكينة فكانت تنسبهن إلي وتقول بنات أشعب قال أبو إسحاق قال لي وبقي ذلك النسل في أيدي الناس إلى الآن فكلهم إخواني وأهلي قال فضحكت والله حتى غلبت وأمرت له بعشرة آلاف درهم فحملت بحضرتي إليه","topic":"أخبار الحسين بن علي ونسبه","topicNo":200,"sp":4,"spl":"أحاديث عن سكينة"},
{"id":"b200-7","bab":"الجزء 16","sec":"أزواج سكينة","page":"ج16 ص158","text":"أخبرني الطوسي والحرمي قالا حدثنا الزبير بن بكار قال حدثني عمي مصعب قال تزوجت سكينة بنت الحسين عليه السلام عدة أزواج أولهم عبد الله بن الحسن بن علي وهو ابن عمها وأبو عذرتها ومصعب بن الزبير وعبد الله بن عثمان الحزامي وزيد بن عمرو بن عثمان والأصبغ بن عبد العزيز بن مروان ولم يدخل بها وإبراهيم بن عبد الرحمن بن عوف ولم يدخل بها قال مصعب ويحيى بن الحسن العلوي إن عبد الله بن حسن زوجها كان يكنى أبا جعفر وأمه بنت السليل بن عبد الله البجلي أخي جرير بن عبد الله\nقال ثم خلفه عليها مصعب بن الزبير زوجه إياها أخوها علي بن الحسين ومهرها مصعب ألف ألف درهم قال مصعب وحدثني مصعب بن عثمان أن علي بن الحسين أخاها حملها إليه فأعطاه أربعين ألف دينار قال مصعب وحدثني معاوية بن بكر الباهلي قال قالت سكينة دخلت على مصعب وأنا أحسن من النار الموقدة في الليلة القرة قال فولدت من مصعب بنتا فقال لها سميها زهراء قالت بل أسميها باسم إحدى أمهاتي وسمتها الرباب فلما قتل مصعب ولي أخوه عروة تركته فزوجها يعني الرباب بنت مصعب ابنه عثمان بن عروة فماتت وهي صغيرة فورثها عثمان بن عروة عشرة آلاف دينار قال الزبير فحدثني محمد بن سلام عن شعيب بن صخر عن أمه سعدة بنت عبد الله بن سالم قالت لقيت سكينة بين مكة ومنى فقالت قفي لي يابنة عبد الله فوقفت فكشفت عن بنتها من مصعب فإذا هي قد أثقلتها بالحلي واللؤلؤ فقالت ما ألبستها إياه إلا لتفضحه قال الزبير وحدثني عمي عن الماجشون قال قالت سكينة لعائشة بنت طلحة أنا أجمل منك وقالت عائشة بل أنا\nفاختصمتا إلى عمر بن أبي ربيعة فقال لأقضين بينكما أما أنت يا سكينة فأملح منها وأما أنت يا عائشة فأجمل منها فقالت سكينة قضيت لي والله وكانت سكينة تسمي عائشة ذات الأذنين وكانت عظيمة الأذنين أخبرني الحسن بن علي قال حدثني أحمد بن زهير قال حدثنا المدائني قال خطب سكينة بنت الحسين عليه السلام عبد الملك بن مروان فقالت أمها لا والله لا يتزوجها أبدا وقد قتل ابن أخي تعني مصعبا وأما محمد بن سلام الجمحي فإنه ذكر فيما أخبرني به أبو الحسن الأسدي عن الرياشي عنه أن أبا عذرتها هو عندي عبد الله بن الحسن بن علي ثم خلف عليها العثماني ثم مصعب بن الزبير ثم الأصبغ بن عبد العزيز بن مروان فقال فيه بعض المدنيين\n(نكحت سكينة بالحساب ثلاثة ... فإذا دخلت بها فأنت الرابع)\nقال وكان يتولى مصر فكتبت إليه إن أرض مصر وخمة فبنى لها مدينة تسمى مدينة الأصبغ وبلغ عبد الملك تزوجه إياها فنفس بها عليه فكتب إليه اختر مصر أو سكينة فبعث إليها بطلاقها ولم يدخل بها ومتعها بعشرين ألف دينار ومروا بها في طريقها على منزل فقالت ما اسم هذا المنزل قالوا جوف الحمار قالت ما كنت لأدخل جوف الحمار أبدا\nوذكر محمد بن سلام في هذا الخبر الذي رواه الرياشي عن شعيب بن صخر أن الحزامي عبد الله بن عثمان خلف الأصبغ عليها وولدت منه بنتا وذكر عن أمه سعدة بنت عبد الله أن سكينة أرتها بنتها من الحزامي وقد أثقلتها باللؤلؤ وهي في قبة فقالت والله ما ألبستها إياه إلا لتفضحه تريد أنها تفضح الحلي بحسنها لأنها أحسن منه أخبرني ابن أبي الأزهر قال حدثنا حماد بن إسحاق عن أبيه عن الهيثم بن عدي عن صالح بن حسان وغيره أن سكينة كانت عند عمرو بن حكيم بن حزام ثم تزوجها بعده زيد بن عمرو بن عثمان بن عفان ثم تزوجها مصعب بن الزبير فلما قتل مصعب خطبها إبراهيم بن عبد الرحمن بن عوف فبعثت إليه أبلغ من حمقك أن تبعث إلى سكينة بنت الحسين بن فاطمة بنت رسول الله تخطبها فأمسك عن ذلك قال ثم تنفست يوما بنانة جارية سكينة وتنهدت حتى كادت أضلاعها تتحطم فقالت لها سكينة مالك ويلك قالت أحب أن أرى في الدار جلبة تعني العرس فدعت مولى لها تثق به فقالت له اذهب إلى إبراهيم بن عبد الرحمن بن عوف فقل له إن الذي كنا ندفعك عنه قد بدا لنا فيه أنت من أخوال رسول الله فأحضر بيتك قال فجمع عدة من بني زهرة وأفناء قريش من بني جمح وغيرهم نحوا من سبعين رجلا أو ثمانين ثم أرسل إلى","topic":"أخبار الحسين بن علي ونسبه","topicNo":200,"sp":5,"spl":"أزواج سكينة"},
{"id":"b200-8","bab":"الجزء 16","sec":"أزواج سكينة","page":"ج16 ص158","text":"علي بن الحسين والحسن بن الحسن وغيرهم من بني هاشم فلما أتاهم الخبر اجتمعوا وقالوا هذه السفيهة تريد أن تتزوج إبراهيم بن عبد الرحمن بن عوف فتنادى بنو هاشم واجتمعوا وقالوا لا يخرجن أحد منكم إلا ومعه عصا فجاؤوا وما بقي إلا الكلام فقال اضربوا بالعصى فاضطربوا هم وبنو زهرة حتى تشاجوا فشج بينهم يومئذ أكثر من مائة إنسان ثم قالت بنو هاشم أين هذه قالوا في هذا البيت فدخلوا إليها فقالوا أبلغ هذا من صنعك ثم جاؤوا بكساء طاروقي فبسطوه ثم حملوها وأخذوا بجوانبه - أو قال بزواياه الأربع - فالتفتت إلى بنانة فقالت يا بنانة أرأيت في الدار جلبة قالت إي والله إلا أنها شديدة وقال هارون بن الزيات أخبرني أبو حذيفة عن مصعب قال كان أول أزواج سكينة عبد الله بن الحسن بن علي قتل عنها ولم تلد له وخلف عليها مصعب فولدت له جارية ثم خلف عليها عبد الله بن عثمان بن عبد الله بن حكيم بن حزام فنشزت عليه فطلقها ثم خلف عليها الأصبغ بن عبد العزيز فأصدقها صداقا كثيرا فقال الشاعر\n(نكحت سكينة بالحساب ثلاثة ... فإذا دخلت بها فأنت الرابع)\n(إن البقيع إذا تتابع زرعه ... خاب البقيع وخاب فيه الزارع)\nبلغ ذلك عبد الملك بن مروان فغضب وقال أما تزوجنا أحسابنا حتى تزوجنا أموالنا فطلقها فطلقها فخلف عليها العثماني وشرطت عليه ألا يطلقها ولا يمنعها شيئا تريده وأن يقيمها حيث خلتها أم منظور ولا يخالفها\nفي أمر تريده فكانت تقول له يابن عثمان اخرج بنا إلى مكة فإذا خرج بها فسارت يوما أو يومين قالت ارجع بنا إلى المدينة فإذا رجع يومه ذاك قالت اخرج بنا إلى مكة فقال له سليمان بن عبد الملك أعلم أنك قد شرطت لها شروطا لم تف بها فطلقها فطلقها فخلف عليها إبراهيم بن عبد الرحمن بن عوف فكره ذلك أهلها وخاصموه إلى هشام بن إسماعيل فبعث إليها يخيرها فجاء إبراهيم بن عبد الرحمن من حيث تسمع كلامه فقال لها جعلت فداءك قد خيرتك فاختاريني فقالت قلت ماذا بأبي تهزأ بي فعرف ذلك فانصرف وخيروها فقالت لا أريده قال وماتت فصلى عليها شيبة بن نصاح وأما ابن الكلبي فذكر فيما أخبرنا به الجوهري عن عمر بن شبة عن عبد الله بن محمد بن حكيم عنه أن أول أزواجها الأصبغ ومات ولم يرها ثم زيد بن عمرو العثماني قال وولدت له ابنه عثمان الذي يقال له قرين ثم الحزامي ثم خلف عليها مصعب فولدت له جارية ثم خلف عليها إبراهيم بن عبد الرحمن بن عوف ولم يدخل بها قال عمر بن شبة وحدثني محمد بن يحيى قال تزوج مصعب سكينة وهو يومئذ بالبصرة عامل لأخيه عبد الله بن الزبير وكان بين مصعب وبين أخيه رسول يقال له أبو السلاس وهو الذي جاء بنعيه فقال ابن قيس فيه\n(قد أتانا بما كرهنا أبو السلاس ... كانت بنفسه الأوجاع)\nوفي هذا الشعر غناء قد ذكر في موضعه وهذا غلط من محمد بن يحيى ليست قصة أبي السلاس مع مصعب وإنما هي مع ابن جعفر قال محمد بن يحيى ولما تزوج مصعب سكينة على ألف ألف كتب عبد الله بن همام على يد أبي السلاس إلى عبد الله بن الزبير\n(أبلغ أمير المؤمنين رسالة ... من ناصح لك لا يريد خداعا)\n(بضع الفتاة بألف ألف كامل ... وتبيت سادات الجنود جياعا)\n(لو لأبي حفص أقول مقالتي ... وأبث ما أبثثتكم لارتاعا)\nال وكان ابن الزبير قد أوصاه ألا يعطيه أحد كتابا إلا جاء به فلما أتاه بهذا الكتاب قال صدق والله لو يقول هذه المقالة لأبي حفص لارتاع من تزويج امرأة على ألف ألف درهم ثم قال إن مصعبا لما وليته البصرة أغمد سيفه وسل أيره وعزله عن البصرة وأمره أن يجيء على ذات الجيش وقال إني لأرجو أن يخسف الله بك فيها فبلغ عبد الملك بن مروان قول عبد الله في مصعب فقال لكن عبد الله والله أغمد سيفه وأيره وخيره","topic":"أخبار الحسين بن علي ونسبه","topicNo":200,"sp":6,"spl":"أزواج سكينة"},
{"id":"b200-9","bab":"الجزء 16","sec":"مغاضبة زيد بن عمرو العثماني لسكينة","page":"ج16 ص164","text":"قال ابن زيد أخبرني محمد بن يحيى عن ابن شهاب الزهري قال ذكر أن زيد بن عمرو بن عثمان العثماني خرج إلى مال له مغاضبا لسكينة وعمر بن عبد العزيز يومئذ والي المدينة فأقام سبعة أشهر فاستعدته سكينة على زيد وذكرت غيبته مع ولائده سبعة أشهر وأنها شرطت عليه أنه إن مس امرأة أو حال بينها وبين شيء من ماله أو منعها مخرجا تريده فهي خلية فبعث إليه عمر فأحضره وأمر ابن حزم أن ينظر بينهما قال حدثني أبو بكر بن عبد الله قال بعثني عمر وبعث معي محمد بن معقل بن يسار الأشجعي إلى ابن حزم وقال اشهدا قضاءه\nفدخلنا عليه وعنده زيد جالس وفاطمة امرأة ابن حزم في الحجلة وجاءت سكينة فقال ابن حزم أدخلوها وحدها فقالت والله لا أدخل إلا ومعي ولائدي فأدخلن معها فلما دخلت قالت يا جارية أثني لي هذه الوسادة ففعلت وجلست عليها ولصق زيد بالسرير حتى كاد يدخل في جوفه خوفا منها فقال لها ابن حزم يابنة الحسين إن الله عز و جل يحب القصد في كل شيء فقالت له وما أنكرت مني إني وإياك والله كالذي يرى الشعرة في عين صاحبه ولا يرى الخشبة في عينه فقال لها أما والله لو كنت رجلا لسطوت بك فقالت له يابن فرتنى ألا تزال تتوعدني وشتمته وشتمها فلما بلغا ذلك قال ابن أبي الجهم العدوي ما بهذا أمرنا فأمض الحكم ولا تشاتم فقالت لمولاة لها من هذا قالت أبو بكر بن عبد الله بن أبي الجهم فقالت لا أراك ههنا وأنا اشتم بحضرتك ثم هتفت برجال قريش وحضت ابن أبي الجهم وقالت اما والله لو كان أصحاب الحرة أحياء لقتلوا هذا العبد اليهودي عند شتمه إياي أي عدو الله تشتمني وأبوك الخارج مع يهود صبابة بدينهم لما أخرجهم رسول الله إلى أريحاء يابن فرتنى قال وشتمها وشتمته قال ثم أحضرنا زيدا فكلمها وخضع لها فقالت ما أعرفني بك يا\nزيد والله لا تراني أبدا أتراك تمكث مع جواريك سبعة أشهر لا تقربهن املأ عينك الآن مني فإنك لا تراني بعد الليلة أبدا وجعلت تردد هذا القول ومثله فكلما تكلمت ترفث لابن حزم وامرأته في الحجلة وهو يقلق لسماع امرأته ذلك فيه ثم حكم بينهما بأن سكينة إن جاءت ببينة على ما ادعنه وإلا فاليمين على زيد فقامت وقالت لزيد يابن عثمان تزود مني بنظرة فإنك والله لا تراني بعد الليلة أبدا وابن حزم صامت ثم خرجنا وجئنا إلى عمر بن عبد العزيز وهو ينتظرنا في وسط الدار في ليلة شاتية فسألنا عن الخبر فأخبرناه فجعل يضحك حتى أمسك بطنه ثم دعا زيدا من غد فأحلفه ورد سكينة عليه وأخبرني الحرمي بن أبي العلاء قال حدثني الزبير بن بكار عن عمه قال قالت سكينة لأم أشعب سمعت للناس خبرا قالت لا فبعثت إلى إبراهيم بن عبد الرحمن بن عوف فتزوجته وبلغ ذلك بني هاشم فأنكروه وحملوا العصي وجاؤوا فقاتلوا بني زهرة حتى كثرت الشجاج ثم فرق بينهم وخيرت سكينة فأبت نكاح إبراهيم ثم التفتت إلى أم أشعب وقالت أترين الآن أنه كان للناس اليوم خبر قالت أي والله - بأبي أنت - وأي خبر","topic":"أخبار الحسين بن علي ونسبه","topicNo":200,"sp":7,"spl":"مغاضبة زيد بن عمرو العثماني لسكينة"},
{"id":"b200-10","bab":"الجزء 16","sec":"زوجها بخيل وهي تبغض أهل الكوفة","page":"ج16 ص166","text":"قال هارون بن الزيات وجدت في كتاب القاسم بن يوسف حدثني الهيثم بن عدي عن أشعب قال تزوج زيد بن عمرو بن عثمان بن عفان سكينة وكان أبخل قرشي رأيته فخرج حاجا وخرجت سكينة معه فلم تدع إوزة ولا دجاجة ولا خبيصا ولا\nفاكهة إلا حملته معها وأعطتني مائة دينار وقالت يابن أم حميدة اخرج معنا فخرجت ومعنا طعام على خمسة أجمال فلما أتينا السيالة نزلنا وأمرت بالطعام أن يقدم فلما جيء بالأطباق أقبل أغيلمة من الأنصار يسلمون على زيد فلما رآهم قال أوه خاصرتي باسم الله ارفعوا الطعام وهاتوا الترياق والماء الحار فأتي به فجعل يتوجرهما حتى انصرفوا ورحلنا وقد هلكت جوعا فلم آكل إلا مما اشتريته من السويق فلما كان من الغد أصبحت وبي من الجوع ما الله أعلم به ودعا بالطعام وأتي به قال فأمر بإسخانه وجاءته مشيخة من قريش يسلمون عليه فلما رآهم اعتل بالخاصرة ودعا بالترياق والماء الحار فتوجره ورفع الطعام فلما ذهبوا أمر بإعادته فأتي به وقد برد فقال لي يا أشعب هل إلى إسخان هذا الدجاج سبيل فقلت له أخبرني عن دجاجك هذا أمن آل فرعون فهو يعرض على النار غدوا وعشيا أخبرني أحمد بن عبيد الله بن عمار قال حدثنا سليمان بن أبي شيخ عن محمد بن الحكم عن عوانة قال جاء قوم من أهل الكوفة يسلمون على سكينة فقالت لهم الله يعلم أني أبغضكم قتلتم جدي عليا وأبي الحسين وأخي عليا وزوجي مصعبا فبأي وجه تلقونني أيتمتموني صغيرة وأرملتموني كبيرة أخبرني الحسن بن علي عن أحمد بن زهير عن المدائني قال بينما\nسكينة ذات ليلة تسير إذ سمعت حاديا يحدو في الليل يقول\n(لولا ثلاث هن عيش الدهر ... )\nقالت لقائد قطارها ألحق بنا هذا الرجل حتى نسمع منه ما هذه الثلاث فطال طلبه لذلك حتى أتعبها فقالت لغلام لها سر أنت حتى تسمع منه فرجع إليها فقال سمعته يقول\n(الماء والنوم وأم عمرو ... )\nفقالت قبحه الله أتعبني منذ الليلة قال وحدثني المدائني أن أشعب حج مع سكينة فأمرت له بجمل قوي يحمل أثقاله فأعطاه القيم جملا ضعيفا فلما جاء إلى سكينة قالت له أعطوك ما أردت قال عرسه الطلاق لو أنه حمل قتبا على الجمل لما حمله فكيف يحمل محملا أخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة عن نعيم بن سالم بن علي الأنصاري عن سفيان بن حرب قال رأيت سكينة بنت الحسين عليه السلام ترمي الجمار فسقطت من يدها الحصاة السابعة فرمت بخاتمها مكانها وقال هارون بن الزيات حدثني أبو حذافة السهمي قال أخبرني غير واحد منهم محمد بن طلحة أن سكينة ناقلت بمالها بالزوراء إلى قصر يقال له البريدي بلزق الجماء فلما سال العقيق خرجت ومعها جواريها تمشي حتى جاءت السيل فجلست\nعلى جرفه ومالت برجليها في السيل ثم قالت هذا في است المغبون والله لهذه الساعة من هذا القصر خير من الزوراء قال وكان البريدي قصرا لا غلة له وإنما يتنزه فيه وكانت غلة الزوراء غلة وافرة عظيمة","topic":"أخبار الحسين بن علي ونسبه","topicNo":200,"sp":8,"spl":"زوجها بخيل وهي تبغض أهل الكوفة","partial":1},
{"id":"b200-11","bab":"الجزء 16","sec":"بدراقس يجري لها عملية جراحية","page":"ج16 ص169","text":"وقال هارون وحدثني علي بن محمد النوفلي عن أبيه وعمه وغيرهما من مشايخ الهاشميين والطالبيين أن سكينة بنت الحسين عليه السلام خرجت بها سلعة في أسفل عينها فكبرت حتى أخذت وجهها وعينها وعظم شأنها وكان بدراقس منقطعا إليها في خدمتها فقالت له ألا ترى ما قد وقعت فيه فقال لها أتصبرين على ما يمسك من الألم حتى أعالجك قالت نعم فأضجعها وشق جلد وجهها حتى ظهرت السلعة ثم كشط الجلد عنها أجمع وسلخ اللحم من تحتها حتى ظهرت عروق السلعة وكان منها شيء تحت الحدقة فرفع الحدقة عنه حتى جعلها ناحية ثم سل عروق السلعة من تحتها فأخرجها أجمع ورد العين إلى موضعها وعالجها وسكينة مضطجعة لا تتحرك ولا تئن حتى فرغ مما أراد فزال عنها وبرئت منها وبقي أثر تلك الجراحة في مؤخر عينها فكان أحسن شيء في وجهها وكان أحسن على وجهها من كل حلي وزينة ولم يؤثر ذلك في نظرها ولا في عينها أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال أخبرني عيسى بن إسماعيل عن محمد بن سلام عن جرير المديني عن المدائني وأخبرني به محمد بن أبي الأزهر قال حدثنا حماد بن إسحاق عن\nأبيه عن محمد بن سلام وأخبرني به أحمد بن عبد العزيز الجوهري عن عمر بن شبة موقوفا عليه قالوا اجتمع في ضيافة سكينة بنت الحسين عليه السلام جرير والفرزدق وكثير وجميل ونصيب فمكثوا أياما ثم أذنت لهم فدخلوا عليها فقعدت حيث تراهم ولا يرونها وتسمع كلامهم ثم أخرجت وصيفة لها وضيئة وقد روت الأشعار والأحاديث فقالت أيكم الفرزدق فقال لها هأنذا فقالت أنت القائل\n(هما دلتاني من ثمانين قامة ... كما انحط باز أقتم الريش كاسره)\n(فلما استوت رجلاي بالأرض قالتا ... أحي يرجى أم قتيل نحاذره)\n(فقلت ارفعوا الأمراس لا يشعروا بنا ... وأقبلت في أعجاز ليل أبادره)\n(أبادر بوابين قد وكلا بنا ... وأحمر من ساج تبص مسامره)\nال نعم قالت فما دعاك إلى إفشاء سرها وسرك هلا سترتها وسترت نفسك خذ هذه الألف والحق بأهلك ثم دخلت على مولاتها وخرجت فقالت أيكم جرير فقال لها هأنذا فقالت أنت القائل\n(طرقتك صائدة القلوب وليس ذا ... حين الزيارة فارجعي بسلام)\n(تجري السواك على أغر كأنه ... برد تحدر من متون غمام)\n(لو كان عهدك كالذي حدثتنا ... لوصلت ذاك فكان غير رمام)\n(إني أواصل من أردت وصاله ... بحبال لا صلف ولا لوام)\nال نعم قالت أفلا أخذت بيدها ورحبت بها وقلت لها ما يقال لمثلها أنت عفيف وفيك ضعف خذ هذه الألف والحق بأهلك ثم دخلت على مولاتها وخرجت فقالت أيكم كثير فقال هأنذا فقالت أنت القائل\n(وأعجبني يا عز منك خلائق ... كرام إذا عد الخلائق أربع)\n(دنوك حتى يطمع الطالب الصبا ... ودفعك أسباب الهوى حين يطمع)\n(وقطعك أسباب الكريم ووصلك اللئيم ... وخلات المكارم ترفع)\n(فوالله ما يدري كريم مماطل ... أينساك إذ باعدت أم يتضرع)\nال نعم قالت ملحت وشكلت خذ هذه الثلاثة الآلاف والحق بأهلك ثم دخلت إلى مولاتها وخرجت فقالت أيكم نصيب قال هأنذا قالت أأنت القائل\n(ولولا أن يقال صبا نصيب ... لقلت بنفسي النشأ الصغار)\n(بنفسي كل مهضوم حشاها ... إذا ظلمت فليس لها انتصار)\nال نعم قالت ربيتنا صغارا ومدحتنا كبارا خذ هذه الأربعة الآلاف والحق بأهلك ثم دخلت على مولاتها وخرجت فقالت يا جميل مولاتي تقرئك السلام وتقول لك والله ما زلت مشتاقة لرؤيتك منذ سمعت قولك\n(ألا ليت شعري هل أبيتن ليلة ... بوادي القرى إني إذا لسعيد)\n(لكل حديث بينهن بشاشة ... وكل قتيل عندهن شهيد)\nجعلت حديثنا بشاشة وقتلانا شهداء خذ هذه الأربعة الآلاف الدينار والحق بأهلك","topic":"أخبار الحسين بن علي ونسبه","topicNo":200,"sp":9,"spl":"بدراقس يجري لها عملية جراحية"},
{"id":"b200-12","bab":"الجزء 16","sec":"سكينة تحكم في شعر الشعراء","page":"ج16 ص172","text":"أخبرني ابن أبي الأزهر قال حدثنا حماد عن أبيه عن أبي عبد الله الزبيري قال اجتمع بالمدينة راوية جرير وراوية كثير وراوية جميل وراوية نصيب وراوية الأحوص فافتخر كل واحد منهم بصاحبه وقال صاحبي أشعر فحكموا\nسكينة بنت الحسين بن علي عليهما السلام لما يعرفونه من عقلها وبصرها بالشعر فخرجوا يتقادون حتى استأذنوا عليها فأذنت لهم فذكروا لها الذي كان من أمرهم فقالت لراوية جرير أليس صاحبك الذي يقول\n(طرقتك صائدة القلوب وليس ذا ... حين الزيارة فارجعي بسلام)\nوأي ساعة أحلى للزيارة من الطروق قبح الله صاحبك وقبح شعره ألا قال فادخلي بسلام ثم قالت لراوية كثير أليس صاحبك الذي يقول\n(يقر بعيني ما يقر بعينها ... وأحسن شيء ما به العين قرت)\nليس شيء أقر لعينها من النكاح أفيحب صاحبك أن ينكح قبح الله صاحبك وقبح شعره ثم قالت لراوية جميل أليس صاحبك الذي يقول\n(فلو تركت عقلي معي ما طلبتها ... ولكن طلابيها لما فات من عقلي)\nما أرى بصاحبك من هوى إنما يطلب عقله قبح الله صاحبك وقبح شعره ثم قالت لراوية نصيب أليس صاحبك الذي يقول\n(أهيم بدعد ما حييت فإن أمت ... فيا حربا من ذا يهيم بها بعدي)\nما أرى له همة إلا من يتعشقههما بعده قبحه الله وقبح شعره ألا قال\n(أهيم بدعد ما حييت فإن أمت ... فلا صلحت دعد لذي خلة بعدي)\nثم قالت لراوية الأحوص أليس صاحبك الذي يقول\n(من عاشقين تواعدا وتراسلا ... ليلا إذا نجم الثريا حلقا)\n(باتا بأنعم ليلة وألذها ... حتى إذا وضح الصباح تفرقا)\nال نعم قالت قبحه الله وقبح شعره ألا قال تعانقا قال إسحاق في خبره فلم تثن على أحد منهم في ذلك اليوم ولم تقدمه قال وذكر لي الهيثم بن عدي مثل ذلك في جميعهم إلا جميلا فإنه خالف هذه الرواية وقال فقالت لراوية جميل أليس صاحبك الذي يقول\n(فيا ليتني أعمى أصم تقودني ... بثينة لا يخفى علي كلامها)\nقال نعم قالت رحم الله صاحبك كان صادقا في شعره كان جميلا كاسمه فحكمت له وفي الأشعار المذكورة في الأخبار أغان تذكر ها هنا نسبتها فمنها\n(هما دلتاني من ثمانين قامة ... كما انقض باز أقتم الريش كاسره)\n(فلما استوت رجلاي بالأرض قالتا ... أحي يرجى أم قتيل نحاذره)\nروضه - الطويل - الشعر للفرزدق والغناء للحجبي - ورمل - بالبنصر عن الهشامي وحبش وأخبرني أبو خليفة في كتابه إلي قال حدثنا محمد بن سلام عن يونس وحدثنا به اليزيدي قال حدثنا أحمد بن زهير قال حدثنا محمد بن سلام عن يونس قال\nكان للفرزدق غلامان يقال لأحدهما وقاع وللآخر زنقطة قال ولوقاع يقول الفرزدق\n(تغلغل وقاع إليها فأقبلت ... تخوض خداريا من الليل أخضرا)\n(لطيف إذا ما انغل أدرك ما ابتغى ... إذا هو للظبي المروع تقترا)\nله يقول أيضا\n(فأبلغهن وحي القول عني ... وأدخل رأسه تحت القرام)\n(أسيد ذو خريطة نهارا ... من المتلقطي قرد القمام)\n(فقلن له نواعدك الثريا ... وذاك إليه مجتمع الرجام)\n\n(ثلاث واثنتان فهن خمس ... وسادسة تميل مع السنام)\n(خرجن إلي لم يطمثن قبلي ... فهن أصح من بيض النعام)\n(فبتن بجانبي مصرعات ... وبت أفض أغلاق الختام)\nي هذه الأبيات الثلاثة لابن جامع - خفيف رمل - بالبنصر عن الهشامي\nوفيها هزج يمان بالوسطى عن عمرو بن بانة وذكر حبش أن الهزج لفليح وأن لحن ابن جامع ثاني ثقيل بالوسطى أخبرني أبو خليفة قال حدثنا محمد بن سلام قال قال الفرزدق وهو بالمدينة\n(هما دلتاني من ثمانين قامة ... كما انقض باز أقتم الريش كاسره)\n(فلما استوت رجلاي بالأرض قالتا ... أحي يرجى أم قتيل نحاذره)\n(فقلت ارفعوا الأسباب لا يفطنوا بنا ... ووليت في أعجاز ليل أبادره)\n(أبادر بوابين قد وكلا بنا ... وأحمر من ساج تبص مسامره)\n(وأصبحت في القوم الجلوس وأصبحت ... مغلقة دوني عليها دساكره)\nال فأنكرت ذلك قريش عليه وأزعجه مروان عن المدينة وهو واليها لمعاوية وأجله ثلاثة أيام فقال\n(يا مرو إن مطيتي محبوسة ... ترجوا الحباء وربها لم ييأس)\n(وأتيتني بصحيفة مختومة ... أخشى علي بها حباء النقرس)\n(ألق الصحيفة يا فرزدق لا تكن ... نكداء مثل صحيفة المتلمس)\nوقال في ذلك\n(وأخرجني وأجلني ثلاثا ... كما وعدت لمهلكها ثمود)\nذكر ذلك جرير في مناقضته إياه فقال\n(وشبهت نفسك أشقى ثمود ... فقالوا ضللت ولم تهتد)\nعني تأجيل مروان له ثلاثا وقال فيه أيضا جرير","topic":"أخبار الحسين بن علي ونسبه","topicNo":200,"sp":10,"spl":"سكينة تحكم في شعر الشعراء","song":2},
{"id":"b200-13","bab":"الجزء 16","sec":"سكينة تحكم في شعر الشعراء","page":"ج16 ص172","text":"(تدليت تزني من ثمانين قامة ... وقصرت عن باع العلا والمكارم)\nهما قصيدتان أخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال قال سليمان بن عبد الملك للفرزدق أنشدني أجود شعر قلته فأنشده قوله\n(عزفت بأعشاش وما كدت تعزف ... وأنكرت من حدراء ما كنت تعرف)\nقال له زدني فأنشده قوله\n(ثلاث واثنتان فهن خمس ... وسادسة تميل إلى الشمام)\nقال له سليمان ما أظنك إلا قد أحللت بنفسك العقوبة أقررت بالزنا عندي وأنا إمام ولا بد لي من إقامة الحد عليك قال إن أخذت في بقول الله عز و جل لم تفعل قال وما قال الله عز و جل قال قال ( والشعراء يتبعهم الغاوون\nألم تر أنهم في كل واد يهيمون وأنهم يقولون ما لا يفعلون\nفضحك سليمان وقال تلافيتها ودرأت عن نفسك وأمر له بجائزة سنية وخلع عليه أخبرني هاشم بن محمد قال حدثنا أبو غسان دماذ عن أبي عبيدة قال نزل الفرزدق هو ومن معه بقوم من العرب فأنزلوه وأكرموه وأحسنوا قراه فلما كان في الليل دب إلى جارية منهم فراودها عن نفسها فصاحت فتبادر القوم إليها فأخذوها من يده وأنبوه فجعل يفكر واهتم فقال له الرجل الذي نزل به مالك أتحب أن أزوجك من هذه الجارية فقال لا والله ما ذلك بي ولكني كأني بابن المراغة قد بلغه هذا الخبر فقال في\n(وكنت إذا حللت بدار قوم ... رحلت بخزية وتركت عارا)\nقال له الرجل لعله لا يفطن لهذا فقال عسى أن يكون ذلك قال فوالله ما لبثوا أن مر بهم راكب ينشد هذا البيت فسألوه عنه فأنشدهم قصيدة لجرير يعيره بذلك الفعل وفيها هذا البيت بعينه ومنها\n(طرقتك صائدة القلوب وليس ذا ... حين الزيارة فارجعي بسلام)\n(تجري السواك على أغر كأنه ... برد تحدر من متون غمام)\n(هيهات منزلنا بجو سويقة ... ممن يحل بواطن الآجام)\n(إقر السلام على سعاد وقل لها ... لوما ترد رسولنا بسلام)\nلشعر لجرير والغناء لابن سريج ثاني ثقيل بالسبابة في مجرى البنصر عن ابن المكي وذكره إسحاق في هذه الطريق أيضا ولم ينسبه إلى أحد وأظنه من منحول يحيى وذكره عمرو بن بانة أيضا لابن سريج في الثاني والرابع في هذه الطريقة وذكر علي بن يحيى أن فيه لابن سريج ثقيل أول في الثاني والثالث وأنكر ذلك حبش وقال هو بالوسطى قال علي بن يحيى ومن الناس من ينسبه إلى سياط وذكر حبش أن فيه للهذلي خفيف ثقيل بالبنصر وللغريض ثاني ثقيل بالوسطى ومنها\n(من عاشقين تراسلا وتواعدا ... بلقا إذا نجم الثريا حلقا)\n(بعثا أمامهما مخافة رقبة ... رصدا فمزق عنهما ما مزقا)\n(باتا بأنعم ليلة وألذها ... حتى إذا وضح الصباح تفرقا)\nلشعر للأحوص والغناء لمعبد خفيف ثقيل أول بالبنصر عن يونس والهشامي","topic":"أخبار الحسين بن علي ونسبه","topicNo":200,"sp":11,"spl":"سكينة تحكم في شعر الشعراء","song":2},
{"id":"b200-14","bab":"الجزء 16","sec":"رجع الحديث إلى أخبار سكينة سكينة والفرزدق","page":"ج16 ص180","text":"وروى أحمد بن الحارث الخراز عن المدائني عن أبي يعقوب الثقفي عن عامر الشعبي وذكر أيضا أبو عبيدة معمر بن المثنى أن الفرزدق خرج حاجا فلما قضى حجه خرج إلى المدينة فدخل على سكينة بنت الحسين عليه السلام مسلما فقالت له يا فرزدق من أشعر الناس قال أنا قالت كذبت أشعر منك الذي يقول\n(بنفسي من تجنبه عزيز ... علي ومن زيارته لمام)\n(ومن أمسي وأصبح لا أراه ... ويطرقني إذا هجع النيام)\nقال والله لئن أذنت لي لأسمعنك أحسن منه قالت أقيموه فأخرج ثم عاد إليها من الغد فدخل عليها فقالت يا فرزدق من أشعر الناس قال أنا قالت كذبت صاحبك أشعر منك حيث يقول\n(لولا الحياء لعادني استعبار ... ولزرت قبرك والحبيب يزار)\n(كانت إذا هجر الضجيع فراشها ... كتم الحديث وعفت الأسرار)\n(لا يلبث القرناء أن يتفرقوا ... ليل يكر عليهم ونهار)\nفقال والله لئن أذنت لي لأسمعنك أحسن منه فأمرت به فأخرج ثم عاد إليها في اليوم الثالث وحولها مولدات كأنهن التماثيل فنظر الفرزدق إلى واحدة منهن فأعجب بها فقالت يا فرزدق من أشعر الناس فقال أنا فقالت كذبت صاحبك أشعر منك حيث يقول\n(إن العيون التي في طرفها مرض ... قتلننا ثم لم يحيين قتلانا)\n(يصرعن ذا اللب حتى لا حراك به ... وهن أضعف خلق الله أركانا)\nفقال يا بنت رسول الله إن لي عليك حقا عظيما ضربت إليك من مكة أريد التسليم عليك فكان في دخولي إليك تكذيبي ومنعك إياي أن أسمعك وبي ما قد عيل معه صبري وهذه المنايا تغدو وتروح ولعلي لا أفارق المدينة حتى أموت فإن أنا مت فمري أن أدرج في كفني وأدفن في حر تلك الجارية يعني الجارية التي أعجبته فضحكت سكينة وأمرت له بالجارية فخرج بها آخذا بريطتها وأمرت الجواري أن يدفعن في أقفائهما ثم قالت يا فرزدق أحسن صحبتها فإني آثرتك بها على نفسي أخبرني أحمد بن عبيد الله بن عمار وأحمد بن عبد العزيز الجوهري قالا حدثنا علي بن محمد النوفلي قال حدثني أبي عن أبيه وعمومته وجماعة من شيوخ بني هاشم أنه لم يصل على أحد بعد رسول الله بغير إمام إلا سكينة بنت الحسين عليه السلام فإنها ماتت وعلى المدينة خالد بن عبد الملك فأرسلوا إليه فآذنوه بالجنازة وذلك في أول النهار في حر شديد فأرسل إليهم لا تحدثوا حدثا حتى أجيء فأصلي عليها فوضع النعش في موضع المصلى على\nالجنائز وجلسوا ينتظرونه حتى جاءت الظهر فأرسلوا إليه فقال لا تحدثوا فيها شيئا حتى أجيء فجاءت العصر ثم لم يزالوا ينتظرونه حتى صليت العشاء كل ذلك يرسلون إليه فلا يأذن لهم حتى صليت العتمة ولم يجىء ومكث الناس جلوسا حتى غلبهم النعاس فقاموا فأقبلوا يصلون عليها جمعا جمعا وينصرفون فقال علي بن الحسين عليه السلام من أعان بطيب رحمه الله قال وإنما أراد خالد بن عبد الملك فيما ظن قوم أن تنتن قال فأتي بالمجامر فوضعت حول النعش ونهض ابن أختها محمد بن عبد الله العثماني فأتى عطارا كان يعرف عنده عودا فاشتراه منه بأربعمائة دينار ثم أتى به فسجر حول السرير حتى أصبح وقد فرغ منه فلما صليت الصبح أرسل إليهم صلوا عليها وادفنوها فصلى عليها شيبة بن نصاح وذكر يحيى بن الحسين في خبره أن عبد الله بن حسن هو الذي ابتاع لها العود بأربعمائة دينار\n(وأنا الأخضر من يعرفني ... أخضر الجلدة من بيت العرب)\n(من يساجلني يساجل ماجدا ... يملأ الدلو إلى عقد الكرب)\n(إنما عبد مناف جوهر ... زين الجوهر عبد المطلب)\n(كل قوم صيغة من فضة ... وبنو عبد مناف من ذهب)\n(نحن قوم قد بنى الله لنا ... شرفا فوق بيوتات العرب)\n(بنبي الله وابني عمه ... وبعباس بن عبد المطلب)\nلشعر للفضل بن العباس اللهبي والغناء لمعبد - ثقيل - أول بالبنصر في الأول والثاني والثالث ولابن محرز في الأول والثاني - خفيف ثقيل - أول مطلق في مجرى البنصر وذكر يونس أن فيهما لمعبد ومالك وابن محرز وابن مسجح وابن سريج خمسة ألحان وذكر الهشامي أن لحن ابن سريج رمل ولحن مالك - خفيف ورمل - ولحن معبد - خفيف ثقيل - ولحن ابن محرز - ثقيل - أول وذكر ابن المكي أن الثقيل الأول لمالك وذكر عمرو بن بانة في كتابه الثاني أن لابن مسجح أو لابن محرز فيه - خفيف رمل - وذكر الهشامي أن فيه رملا آخر بالوسطى لأبي سعيد مولى فائد ولأبي الحسن مولى سكينة في الثالث والرابع - خفيف ثقيل - وذكر حبش أن لابن صاحب الوضوء في الأول","topic":"أخبار الحسين بن علي ونسبه","topicNo":200,"sp":12,"spl":"رجع الحديث إلى أخبار سكينة سكينة والفرزدق","song":1},
{"id":"b200-15","bab":"الجزء 16","sec":"رجع الحديث إلى أخبار سكينة سكينة والفرزدق","page":"ج16 ص180","text":"والثاني ثاني - ثقيل - بالبنصر ولابن سريج - ثقيل - أول بالبنصر وذكر حماد عن أبيه أن لابن عائشة فيهما لحنا ووافقه ابن المكي وذكر أنه - خفيف رمل - قال وقيل إنه لدحمان وذكر ابن خرداذبه أن لخليدة المكية في الرابع والثالث - خفيف رمل - وفي الخامس والسادس والأول - رمل - يقال إنه لإبراهيم ويقال إنه لإسحاق والخامس والسادس من هذه الأبيات وإن كان شعر الفضل بن العباس اللهبي فليس من القصيدة التي فيها\n(وأنا الأخضر من يعرفني ... )\nكن من قصيدة له أولها\n(شاب رأسي ولداتي لم تشب ... بعد لهو وشباب ولعب)\n(شيب المفرق مني وبدا ... في حفافي لحيتي مثل العطب)\nي هذين البيتين لهاشم ونفيلة - خفيف رمل - بالوسطى والقصيدة التي فيها\n(وأنا الأخضر من يعرفني ... أخضر الجلدة من نسل العرب)\nأولها قوله\n(طرب الشيخ ولا حين طرب ... وتصابى وصبا الشيخ عجب)","topic":"أخبار الحسين بن علي ونسبه","topicNo":200,"sp":13,"spl":"رجع الحديث إلى أخبار سكينة سكينة والفرزدق","partialRef":{"sid":"b200-14","gi":3,"vi":0,"side":0},"partial":1},
{"id":"b201-1","bab":"الجزء 16","sec":"أخبار الفضل بن العباس اللهبي ونسبه","page":"ج16 ص185","text":"الفضل بن العباس بن عتبة بن أبي لهب واسمه عبد العزى بن عبد المطلب بن هاشم بن عبد مناف وكان أحد شعراء بني هاشم المذكورين وفصحائهم وكان شديد الأدمة ولذلك قال\n(وأنا الأخضر من يعرفني ... )\nهو هاشمي الأبوين أمه بنت العباس بن عبد المطلب أخبرني بذلك محمد بن العباس اليزيدي عن عمه عبيد الله عن ابن حبيب وإنما أتاه السواد من قبل أمه جدته وكانت حبشية وكان النبي زوج عتبة إحدى بناته فلما بعثه الله تعالى نبيا أقسمت عليه أم جميل أن يطلقها فجاء إلى النبي فقال يا محمد أشهد من حضر أني قد كفرت بربك وطلقت ابنتك فدعا عليه رسول الله أن يبعث الله عليه كلبا من كلابه يقتله فبعث الله عز و جل عليه أسدا فافترسه أخبرني الحسن بن القاسم البجلي الكوفي قال حدثنا علي بن إبراهيم بن المعلى قال حدثني الوليد بن وهب عن أبي حمزة الثمالي عن عكرمة قال لما نزلت ( والنجم إذا هوى\nقال عتبة للنبي أنا أكفر برب\nالنجم إذا هوى فقال رسول الله اللهم أرسل عليه كلبا من كلابك قال فقال ابن عباس فخرج إلى الشام في ركب فيهم هبار بن الأسود حتى إذا كانوا بوادي الغاضرة وهي مسبعة نزلوا ليلا فافترشوا صفا واحدا فقال عتبة أتريدون أن تجعلوني حجرة لا والله لا أبيت إلا وسطكم فبات وسطهم قال هبار فما أنبهني إلا السبع يشم رؤوسهم رجلا رجلا حتى انتهى إليه فأنشب أنيابه في صدغيه فصاح أي قوم قتلني دعوة محمد فأمسكوه فلم يلبث أن مات في أيديهم أخبرني الحسن بن الهيثم قال حدثنا علي بن إبراهيم قال حدثني الوليد بن وهب عن أبي حمزة عن هشام بن عروة عن أبيه مثله إلا أنه قال قال عتبة أن بريء من الذي دنا فتدلى قال وقال هبار فضغمه الأسد ضغمة فالتقت أنيابه عليه","topic":"أخبار الفضل بن العباس اللهبي ونسبه","topicNo":201,"sp":0,"spl":"أخبار الفضل بن العباس اللهبي ونسبه — الفضل والأحوص","partialRef":{"sid":"b200-14","gi":3,"vi":0,"side":0},"partial":1},
{"id":"b201-2","bab":"الجزء 16","sec":"الفضل والأحوص","page":"ج16 ص186","text":"نسخت من كتاب ابن النطاح عن الهيثم بن عدي وقد أخبرنا به محمد بن العباس اليزيدي في كتاب الجوابات قال حدثنا أحمد بن\nالحارث عن المدائني إلا أن رواية ابن النطاح أتم واللفظ له قال مر الفضل اللهبي بالأحوص وهو ينشد وقد اجتمع الناس عليه فحسده فقال له يا أحوص إنك لشاعر ولكنك لا تعرف الغريب ولا تعرب قال بلى والله إني لأبصر الناس بالغريب والإعراب فأسألك قال نعم قال\n(ما ذات حبل يراها الناس كلهم ... وسط الجحيم فلا تخفى على أحد)\n(كل الحبال حبال الناس من شعر ... وحبلها وسط أهل النار من مسد)\nقال له الفضل بن العباس\n(ماذا أردت إلى شتمي ومنقصتي ... ماذا أردت إلى حمالة الحطب)\n(أذكرت بنت قروم سادة نجب ... كانت حليلة شيخ ثاقب النسب)\nانصرف عنه","topic":"أخبار الفضل بن العباس اللهبي ونسبه","topicNo":201,"sp":0,"spl":"أخبار الفضل بن العباس اللهبي ونسبه — الفضل والأحوص"},
{"id":"b201-3","bab":"الجزء 16","sec":"بين الفضل والحزين الديلي والفرزدق","page":"ج16 ص187","text":"قال ابن النطاح وحدثت أن الحزين الديلي مر بالفضل يوم جمعة وعنده قوم ينشدهم فقال له الحزين أتنشد الشعر والناس يروحون إلى الصلاة فقال الفضل ويلك يا حزين أتتعرض لي كأنك لا تعرفني قال بلى والله إني لأعرفك\nويعرفك معي كل من قرأ سورة ( تبت يدا أبي لهب\nوقال يهجوه\n(إذا ما كنت مفتخرا بجد ... فعرج عن أبي لهب قليلا)\n(فقد أخزى الإله أباك دهرا ... وقلد عرسه حبلا طويلا)\nأعرض عنه الفضل وتكرم عن جوابه وكان الحزين مغرى به وبهجائه حدثني الحسن بن علي قال حدثنا القاسم بن محمد الأنباري قال حدثنا أبو عكرمة عامر بن عمران قال دخل الفرزدق المدينة فنظر إلى الفضل بن العباس بن عتبة ينشد\n(من يساجلني يساجل ماجدا ... يملأ الدلو إلى عقد الكرب)\nقال الفرزدق من المنشد فأخبر به فقال ما يساجلك إلا من عض بظر أمه حدثني محمد بن العباس اليزيدي قال حدثنا سليمان بن أبي شيخ قال حدثنا محمد بن الحكم قال قدم الوليد بن عبد الملك حاجا إلى مكة وهو خليفة فدخل عليه\nالفضل بن العباس بن عتبة فشكا إليه كثرة العيال وسأله فأعطاه مالا وإبلا ورقيقا فلما مات الوليد ولي سليمان فحج فأتاه فسأله فلم يعطه شيئا فقال\n(يا صاحب العيس التي رحلت ... محبوسة لعشية النفر)\n(امرر على قبر الوليد فقل له ... صلى الإله عليك من قبر)\n(يا واصل الرحم التي قطعت ... وأصابها الجفوات في الدهر)\n(إني وجدت الخل بعدك كاذبا ... فبرئت من كذب ومن غدر)\n(ولقد مررت بنسوة يندبنه ... بيض السواعد من بني فهر)\n(تبكي لسيدها الأجل وما ... يبكين من ناب ولا بكر)\n(يبكينه ويقلن سيدنا ... ضاع الخلافة آخر الدهر)\n(ماذا لقيت جزيت صالحة ... من جفوة الإخوان لو تدري)\nخبرني وكيع بهذا الخبر قال حدثني محمد بن علي بن حمزة قال حدثنا أبو غسان قال أخبرنا أبو عبيدة عن عبد العزيز بن أبي ثابت قال كان الفضل بن العباس منقطعا إلى الوليد بن عبد الملك فلما مات الوليد جفاه سليمان وحرمه فقال\n(يا راكب العيس التي وقفت ... للنفر يوم صبيحة النحر)\nذكر الأبيات قال وكان الوليد فرض له فريضة يعطاها كل سنة فقال يا أمير المؤمنين بقي شارب الريح قال وما شارب الريح قال حماري افرض له شيئا ففرض له خمسة دنانير فأخذها ولم يكن يطعمه فعمد رجل فكتب رقعة يذكر فيها قصة الحمار وعلقها في عنقه وجاء بها إلى القاضي فأضحك منه الناس","topic":"أخبار الفضل بن العباس اللهبي ونسبه","topicNo":201,"sp":1,"spl":"بين الفضل والحزين الديلي والفرزدق"},
{"id":"b201-4","bab":"الجزء 16","sec":"بخل الفضل","page":"ج16 ص190","text":"حدثنا اليزيدي قال حدثنا سليمان بن أبي شيخ قال حدثني أبو الشكر مولى بني هاشم كوفي ظريف قال كان الفضل بن العباس بخيلا فقدم علي بن عبد الله بن العباس حاجا فأتاه في منزله مسلما عليه فقال كيف أنت وكيف حالك قال بخير نحن في عافية قال فهل من حاجة قال لا والله وإني لأشتهي هذا العنب وقد أغلاه علينا هؤلاء العلوج فغمز غلاما له فذهب فأتاه بسلة عظيمة من عنب فجعل يغسل له عنقودا عنقودا ويناوله فكلما فعل ذلك قال برتك رحم أخبرني الحسن بن علي قال حدثنا أحمد بن سعيد الدمشقي قال حدثنا الزبير بن بكار عن عمه قال كان الفضل بن العباس بخيلا وكان ثقيل البدن إذا أراد أن يمضي في حاجة استعار مركوبا فطال ذلك عليه وعلى أهل المدينة من فعله فقال له بعض بني هاشم أنا أشتري لك حمارا تركبه وتستغني عن العارية ففعل\nوبعث به إليه فكان يستعير له سرجا إذا أراد أن يركبه فتواصى الناس بألا يعيره أحد سرجا فلما طال عليه ذلك اشترى سرجا بخمسة دراهم وقال\n(ولما رأيت المال مألف أهله ... وصان ذوي الأخطار أن يتبذلوا)\n(رجعت إلى مالي فأعتبت بعضه ... فأعتبني إني كذلك أفعل)\nثم قال للذي اشترى له الحمار إني لا أطيق علفه فإما أن تبعث إلي علفه وإلا رددته فكان يبعث إليه بعلف كل ليلة وشعير ولا يدع هو أيضا أن يطلب من كل أحد يأنس به علفا لحماره فيبعث به إليه فيعلفه التبن دون الشعير حتى هزل وعطب فرفع الحزين الكناني إلى ابن حزم أو عبد العزيز بن عبد المطلب رقعة وكتب في رأسها قصة حمار الفضل اللهبي وذكر فيها أنه يركبه ويأخذ علفه وقضيمه من الناس ويعلفه التبن ويبيع الشعير ويأخذ ثمنه ويسأل أن ينصف منه فضحك لما قرأ الرقعة وقال لئن كنت مازحا إني لأراك صادقا وأمر بتحويل حمار اللهبي إلى إصطبله ليعلفه ويقضمه فإذا أراد ركوبه دفع إليه أخبرني وكيع قال حدثني محمد بن سعد الشامي عن ابن عائشة قال كان الفضل اللهبي بغير سرج فاستعار سرجا فمطله الرجل حتى خاف أن تفوته حاجته فاشترى سرجا ومضى لحاجته وأنشأ يقول\n(ولما رأيت المال مألف أهله ... )\nذكر البيتين ولم يزد عليهما شيئا\nأخبرني أحمد بن عبيد الله بن عمار قال حدثني علي بن محمد النوفلي قال كان أبي عند إسحاق بن عيسى بن علي وهو والي البصرة وعنده وجوه أهل البصرة وقد كانت فيهم بقية حسنة في ذلك الدهر فأفاضوا في ذكر بني هاشم وما أعطاهم الله من الفضل بنبيه فمن منشد شعرا ومتحدث حديثا وذاكر فضيلة من فضائل بني هاشم فقال أبي قد جمع هذا الكلام الفضل بن العباس اللهبي في بيت قاله ثم أنشد قوله\n(ما بات قوم كرام يدعون يدا ... إلا لقومي عليهم منة ويد)\n(نحن السنام الذي طالت شظيته ... فما يخالطه الأدواء والعمد)\nمن صلى صلاتنا وذبح ذبيحتنا عرف أن لرسول الله يدا عليه بما هداه الله عز و جل إلى الإسلام به ونحن قومه فتلك منة لنا على الناس وفي هذين البيتين غناء لابن محرز هزج بالبنصر في رواية عمرو بن بانة وقوله طالت شظيته الشظية الشظى قال دريد بن الصمة\n(سليم الشظى عبل الشوى شنج النسا ... أمين القوى نهد طويل المقلد)\nالعمد داء يصيب البعير من مؤخر سنامه إلى عجزه فلا يلبثه أو يقتله","topic":"أخبار الفضل بن العباس اللهبي ونسبه","topicNo":201,"sp":2,"spl":"بخل الفضل","partial":1},
{"id":"b201-5","bab":"الجزء 16","sec":"مدحه عبد الملك","page":"ج16 ص192","text":"أخبرني أحمد بن عبيد الله بن عمار وأحمد بن عبد العزيز الجوهري قالا حدثنا عمر بن شبة قال حدثنا محمد بن يحيى عن عبد العزيز بن عمران\nقال أخبرني أحمد بن هاشم بن عتبة بن أبي وقاص قال قدم الفضل بن العباس بن عتبة بن أبي لهب على عبد الملك بن مروان فأنشده وعنده ابن لعبيد الله بن زياد فقال الزيادي والله ما أسمع شعرا فلما كان العشي راح إليه الفضل فوقف بين يديه ثم قال يا أمير المؤمنين\n(أتيتك حالا وابن عم وعمة ... ولم أك شعبا لاطه بك مشعب)\n(فصل واشجات بيننا من قرابة ... ألا صلة الأرحام أبقى واقرب)\n(ولا تجعلني كامرىء ليس بينه ... وبينكم قربى ولا متنسب)\n(أتحدب من دون العشيرة كلها ... فأنت على مولاك أحنى وأحدب)\nقال الزيادي هذا والله يا أمير المؤمنين الشعر فقال عبد الملك النخس يكفيك البطيء وجعل يضحك من استرسال الزيادي في يده وأحسن صلته وأخبرني أحمد بن عبيد الله بن عمار قال حدثني النوفلي قال حدثني عمي قال لما قدم الفضل اللهبي على عبد الملك بن مروان أمر له بعشرة آلاف درهم ثم حج الوليد فأمر له بمثلها فلما قدم الأحيحي على المهدي فمدحه قال المهدي لمن حضر كم كان عبد الملك أعطى الفضل اللهبي لما مدحه فما أعلم هاشميا مدحه غيره فقيل له أعطاه عشرة آلاف درهم قال فكم أعطاه الوليد قالوا مثل عطية أبيه فأمر للأحيحي بثلاثين ألف درهم أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثني أحمد بن معاوية عن عثمان بن إبراهيم الحاطبي قال\nخرج علي بن عبد الله بن العباس بالفضل اللهبي إلى عبد الملك بن مروان بالشام فخرج عبد الملك يوما رائحا على نجيب له ومعه بغلة تجنب فحدا حادي عبد الملك به فقال\n(يا أيها البكر الذي أراكا ... عليك سهل الأرض في ممشاكا)\n(ويلك هل تعلم من علاكا ... إن ابن مروان على ذراكا)\n(خليفة الله الذي امتطاكا ... لم يعل بكرا مثل من علاكا)\nفعارضه الفضل اللهبي فحدا بعلي بن عبد الله بن عباس فقال\n(يا أيها السائل عن علي ... سألت عن بدر لنا بدري)\n(أغلب في العلياء غالبي ... ولين الشيمة هاشمي)\n(حاء على بكر له مهري ... )\nنظر عبد الملك إلى علي فقال أهذا مجنون آل أبي لهب قال نعم فلما أعطى قريشا مر به اسمه فحرمه وقال يعطيه علي هكذا رواية عمر بن شبة وأخبرني ابن عمار بهذا الخبر عن علي بن محمد بن النوفلي عن عمه أن سليمان بن عبد الملك حج في خلافة الوليد فجاء إلى زمزم فجلس عندها ودخل الفضل اللهبي يستقي فجعل يرتجز ويقول\n(يا أيها السائل عن علي ... سألت عن بدر لنا بدري)\n(مقدم في الخير أبطحي ... ولين الشيمة هاشمي)\n(زمزمنا بوركت من ركي ... بوركت للساقي وللمسقي)\nغضب سليمان وهم بالفضل فكفه عنه علي بن عبد الله ثم أتاه بقدح\nفيه نبيذ من نبيذ السقاية فأعطاه إياه وسأله أن يشربه فأخذه من يده كالمتعجب ثم قال نعم إنه يستحب ووضعه في يده ولم يشربه فلما ولي الخلافة وحج لقيه الفضل فلم يعطه شيئا نسخت من كتاب ابن النطاح قال ذكر أبو الحسن المدائني أن الحارث بن خالد المخزومي كان يحسد الفضل اللهبي على شعره ويعاديه لأن أبا لهب كان قامر جده العاصي بن هشام على ماله فقمره ثم قامره على رقة فقمره فأسلمه قينا ثم بعث به بديلا يوم بدر فقتله علي بن أبي طالب عليه السلام فكان إذا أنشد شيئا من شعره يقول هذا شعر ابن حمالة الحطب فقال الفضل في ذلك\n(ماذا تحاول من شتمي ومنقصتي ... ماذا تعير من حمالة الحطب)\n(غراء سائلة في المجد غرتها ... كانت حليلة شيخ ثاقب النسب)\n(إنا وإن رسول الله جاء بنا ... شيخ عظيم شؤون الرأس والنشب)\n(يا لعن الله قوما أنت سيدهم ... في جلدة بين أصل الثيل والذنب)\n(أبالقيون توافيني تفاخرني ... وتدعي المجد قد أفرطت في الكذب)\n(وفي ثلاثة رهط أنت رابعهم ... توعدني واسطا جرثومة العرب)\n(في أسرة من قريش هم دعائمها ... تشفي دماؤهم للخيل والكلب)\n(اما أبوك فعبد لست تنكره ... وكان مالكه جدي أبو لهب)\n(النبع عيداننا والمجد شيمتنا ... لسنا كقومك من مرخ ولا غرب)\nأخبرني محمد بن العباس اليزيدي قال حدثني عمي عبيد الله بن محمد عن ابن حبيب عن ابن الأعرابي قال كان رجل من بني كنانة يقال له عقرب حناط قد داين الفضل اللهبي فمطله ثم مر به الفضل وهو يبيع حنطة له ويقول\n(جاءت بها ضابطة التجار ... صافية كقطع الأوتار)","topic":"أخبار الفضل بن العباس اللهبي ونسبه","topicNo":201,"sp":3,"spl":"مدحه عبد الملك","partial":1},
{"id":"b201-6","bab":"الجزء 16","sec":"مدحه عبد الملك","page":"ج16 ص192","text":"قال الفضل\n(قد تجرت عقرب في سوقنا ... يا عجبا للعقرب التاجره)\n(قد صافت العقرب واستيقنت ... أن مالها دنيا ولا آخره)\n(فإن تعد عادت لما ساءها ... وكانت النعل لها حاضره)\n(إن عدوا كيده في استه ... لغير ذي كيد ولا نائره)\n(كل عدو يتقى مقبلا ... وعقرب تخشى من الدابره)\n(كأنها إذ خرجت هودج ... شدت قواه رفعة باكره)","topic":"أخبار الفضل بن العباس اللهبي ونسبه","topicNo":201,"sp":4,"spl":"مدحه عبد الملك"},
{"id":"b201-7","bab":"الجزء 16","sec":"مفاخرته مع عمر بن أبي ربيعة","page":"ج16 ص196","text":"أخبرني هاشم بن محمد الخزاعي قال حدثنا دماذ أبو غسان عن أبي عبيدة ووجدته في بعض الكتب عن الرياشي عن زكويه العلائي عن ابن عائشة عن أبيه والروايتان كالمتفقتين أن عمر بن أبي ربيعة وفد على عبد الملك بن مروان فأدخل عليه فسأله عن نسبه فانتسب فقال له\n(لا أنعم الله بقين عينا ... تحية السخط إذا التقينا)\nأأنت لا أم لك القائل\n(نظرت إليها بالمحصب من منى ... ولي نظر لولا التحرج عارم)\n(فقلت أشمس أم مصابيح بيعة ... بدت لك خلف السجف أم أنت حالم)\n(بعيدة مهوى القرط إما لنوفل ... أبوها وإما عبد شمس وهاشم)\nلغناء لابن سريج - رمل - بالوسطى من رواية عمرو بن بانة ومن رواية حماد بن إسحاق عن أبيه ولمعبد فيه لحن من رواية إسحاق - ثقيل - أول بالسبابة في مجرى البنصر أوله\n(بعيدة مهوى القرط إما لنوفل ... )\nفي لحن معبد خاصة قوله\n(ومد عليها السجف يوم لقيتها ... على عجل تباعها والخوادم)\nتمام الشعر\n(فلم أستطعها غير أن قد بدا لنا ... عشية راحت كفها والمعاصم)\n(معاصم لم تضرب على البهم بالضحى ... عصاها ووجه لم تلحه السمائم)\nرجع إلى سياقة الخبر\nثم قال له عبد الملك قاتلك الله ما ألأمك أما كانت لك في بنات العرب مندوحة عن بنات عمك فقال عمر بئست والله هذه التحية يا أمير المؤمنين لابن العم على شحط الدار ونأي المزار فقال له عبد الملك أراك مرتدعا عن ذلك فقال إني إلى الله تعالى تائب فقال عبد الملك إذن يتوب الله عليك وسيحسن جائزتك ولكن أخبرني عن منازعتك اللهبي في المسجد الجامع فقد أتاني نبأ ذلك وكنت أحب أن أسمعه منك قال عمر نعم يا أمير المؤمنين بينا أنا جالس في المسجد الحرام في جماعة من قريش إذ دخل علينا الفضل بن العباس بن عتبة فسلم وجلس ووافقني وأنا أتمثل بهذا البيت\n(وأصبح بطن مكة مقشعرا ... كأن الأرض ليس بها هشام)\nفأقبل علي وقال يا أخا بني مخزوم والله إن بلدة تبحبح بها عبد المطلب وبعث منها رسول الله واستقر بها بيت الله عز و جل لحقيقة ألا تقشعر لهشام وإن أشعر من هذا البيت وأصدق قول من يقول\n(إنما عبد مناف جوهر ... زين الجوهر عبد المطلب)\nأقبلت عليه فقلت يا أخا بني هاشم إن أشعر من صاحبك الذي يقول\n(إن الدليل على الخيرات أجمعها ... أبناء مخزوم للخيرات مخزوم)\nفقال لي أشعر والله من صاحبك الذي يقول\n(جبريل أهدى لنا الخيرات أجمعها ... إذ أم هاشم لا أبناء مخزوم)\nقلت في نفسي غلبني والله ثم حملني الطمع في انقطاعه علي فخاطبته فقلت بل أشعر منه الذي يقول\n(أبناء مخزوم الحريق إذا ... حركته تارة ترى ضرما)\n(يخرج منه الشرار مع لهب ... من حاد عن حره فقد سلما)\nوالله ما تلعثم أن أقبل علي بوجهه فقال يا أخا بني مخزوم أشعر من صاحبك وأصدق الذي يقول\n(هاشم بحر إذا سما وطما ... أخمد حر الحريق واضطرما)\n(واعلم وخير المقال أصدقه ... بأن من رام هاشما هشما)\nال فتمنيت والله يا أمير المؤمنين أن الأرض ساخت بي ثم تجلدت عليه فقلت يا أخا بني هاشم أشعر من صاحبك الذي يقول\n(أبناء مخزوم أنجم طلعت ... للناس تجلو بنورها الظلما)\n(تجود بالنيل قبل تسأله ... جودا هنيئا وتضرب البهما)\nأقبل علي بأسرع من اللحظ ثم قال أشعر من صاحبك وأصدق الذي يقول\n(هاشم شمس بالسعد مطلعها ... إذا بدت أخفت النجوم معا)\n(اختار منها ربي النبي فمن ... قارعها بعد أحمد قرعا)\nاسودت الدنيا في عيني ودير بي وانقطعت فلم أحر جوابا ثم قلت له يا أخا بني هاشم إن كنت تفخر علينا برسول الله فما يسعنا مفاخرتك فقال كيف لا أم لك والله لو كان منك لفخرت به علي فقلت صدقت واستغفر الله إنه لموضع الفخار وداخلني السرور لقطعه الكلام ولئلا ينالني عوز عن إجابته فأفتضح ثم إنه ابتدأ بالمناقضة فأفكر هنيهة ثم قال قد قلت فلم أجد بدا من الاستماع فقلت هات فقال\n(نحن الذين إذا سما لفخارهم ... ذو الفخر أقعده هناك القعدد)\n(افخر بنا إن كنت يوما فاخرا ... تلق الألى فخروا بفخرك أفردوا)\n(قل يابن مخزوم لكل مفاخر ... منا المبارك ذو الرسالة أحمد)\n(ماذا يقول ذوو الفخار هنا لكم ... هيهات ذلك هل ينال الفرقد)\nفحصرت والله وتبلدت وقلت له إن لك عندي جوابا فأنظرني وأفكرت مليا ثم أنشأت أقول\n(لا فخر إلا قد علاه محمد ... فإذا فخرت به فإني أشهد)\n(أن قد فخرت وفقت كل مفاخر ... وإليك في الشرف الرفيع المعمد)","topic":"أخبار الفضل بن العباس اللهبي ونسبه","topicNo":201,"sp":5,"spl":"مفاخرته مع عمر بن أبي ربيعة","song":1,"partialRef":{"sid":"b2-34","gi":0,"vi":2,"side":0},"partial":1},
{"id":"b201-8","bab":"الجزء 16","sec":"مفاخرته مع عمر بن أبي ربيعة","page":"ج16 ص196","text":"(ولنا دعائم قد بناها أول ... في المكرمات جرى عليها المولد)\n(من رامها حاشى النبي وأهله ... بالفخر غطمطه الخليج المزبد)\n(دع ذا ورح لغناء خود بضة ... مما نطقت به وغنى معبد)\n(مع فتية تندى بطون أكفهم ... جودا إذا هر الزمان الأنكد)\n(يتناولون سلافة عانية ... طابت لشاربها وطاب المقعد)\nوالله يا أمير المؤمنين لقد أجابني بجواب كان أشد علي من الشعر قال لي يا أخا بني مخزوم أريك السها وتريني القمر - قال أبو عبد الله اليزيدي أدلك على الأمر الغامض وأنت لم تبلغ أن ترى الأمر الواضح وهذا مثل - أتخرج من المفاخرة إلى شرب الراح وهي الخمر المحرمة فقلت له أما علمت أصلحك الله أن الله عز و جل يقول في الشعراء ( وأنهم يقولون ما لا يفعلون\nفقال صدقت وقد استثنى الله قوما منهم فقال ( إلا الذين آمنوا وعملوا الصالحات\nفإن كنت منهم فقد دخلت تحت الاستثناء وقد استحققت العقوبة بدعائك إليها وإن لم تكن منهم فالشرك بالله عليك أعظم من شرب الخمر فقلت أصلحك الله لا أجد للمستخذي شيئا أصلح من السكوت فضحك وقال أستغفر الله وقام عني قال فضحك عبد الملك حتى استلقى وقال يابن أبي ربيعة أما علمت أن لبني عبد مناف ألسنة لا تطاق ارفع حوائجك قال فرفعتها فقضاها وأحسن جائزتي وصرفني واللفظ في هذا الخبر لمحمد بن العباس","topic":"أخبار الفضل بن العباس اللهبي ونسبه","topicNo":201,"sp":6,"spl":"مفاخرته مع عمر بن أبي ربيعة"},
{"id":"b201-9","bab":"الجزء 16","sec":"ذكر خبر من لم يمض له خبر ولا يأتي ممن ذكرت صنعته في هذا الخبر","page":"ج16 ص201","text":"منهم خليدة المكية وهي مولاة لابن شماس كانت هي وعقيلة وربيحة يعرفن بالشماسيات وقد أخذت الغناء عن ابن سريج ومعبد ومالك\nفأخبرني الحرمي بن أبي العلاء والطوسي قالا حدثنا الزبير بن بكار عن عمه قال كانت لهشام بن عروة جفنة يصيب منها هو وبنوه ناحية وكان محمد بن هشام يصنع الطعام الرقيق فيشير إليهم فيمسكون عن الأكل فيفطن هشام فيقول لقد حدث شيء ثم يقوم محمد فيتسلل القوم إليه وجاءت خليدة المكية فصعدوا غرفة فلما غنت إذا حفز ونفس فإذا هو هشام قد طلع وهو ينشد\n(يا قدمي الحقاني بالقوم ... لا تعداني كسلا بعد اليوم)\nلما رآهم قال أحسبه قد جلس معهم وقال لخليدة غني فغنت فقال لها اكتبي في صدرك قل هو الله أحد والمعوذتين لا تصيبك العين أخبرني علي بن عبد العزيز الكاتب عن ابن خرداذبة قال حدثني إسحاق بن إبراهيم الموصلي عن الفضل بن الربيع قال ما رأيت ابن جامع يطرب لغناء كما يطرب لغناء خليدة المكية وكانت سوداء وفيها يقول الشاعر\n(فتنت كاتب الأمير رياحا ... يا لقوم خليدة المكيه)\nخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة ونسخت هذا الخبر\nبعينه من كتاب جعفر بن قدامة يخطه قال حدثني عمر بن شبة قال بلغني أن محمد بن عبد الله بن عمرو بن عثمان بن عفان أرسل إلى خليدة المكية أبا عون مولاه يخطبها عليه فاستأذن فأذنت له وعليها ثياب رقاق لا تسترها ثم وثبت فقالت إنما ظننتك بعض سفهائك ولكني ألبس لك ثياب مثلك ثم أخرج إليك ففعلت وقالت قل قال أرسلني إليك مولاي وهو من تعلمين بين رسول الله وبين علي وعثمان وهو ابن عم أمير المؤمنين يخطبك وقالت قد نسبته فأبلغت فاسمع نسبي أنا بأبي أنت إن أبي بيع على غير عقد الإسلام ولا عهده فعاش عبدا ومات وفي رجله قيد وفي عنقه سلسلة وعلى الإباق والسرقة وولدتني امي على غير رشدة وماتت وهي آبقة فأنا من تعلم فإن أراد صاحبك نكاحا مباحا أو زنا صراحا فهلم إليه فنحن له فقال إنه لا يدخل في الحرام قالت ولا ينبغي أن يستحيي من الحلال فأما نكاح السر فلا والله لا فعلته ولا كنت عارا على القيان قال فأتيت محمدا فأخبرته فقال ويلك أتزوجها معلنا وعندي بنت طلحة بن عبيد الله لا ولكن ارجع إليها فقل لها تختلف إلي أردد بصري فيها لعلي أسلو فرجعت فأبلغتها الرسالة فضحكت وقالت أما هذا فنعم لسنا نمنعه منه\n\n(رب ليل ناعم أحييته ... في عفاف عند قباء الحشى)\n(ونهار قد لهونا بالتي ... لا نرى شبها لها فيمن مشى)\n(لطلوع الشمس حتى آذنت ... بغروب عند إبان العشا)\n(لسليمى ما دعت قمرية ... بهديل فوق غصن من غضى)\n(وعقار قهوة باكرتها ... في ندامى كمصابيح الدجى)\n(وجواد سابح أقحمته ... حومة الموت على زرق القنا)\nلشعر للمهاجر بن خالد بن الوليد فيما ذكر الزبير بن بكار وذكر أبو عمرو الشيباني وخالد بن كلثوم أنه لابنه خالد بن المهاجر والغناء لابن محرز - ثقيل - أول بالسبابة في مجرى البنصر عن إسحاق وفيه لإبراهيم الموصلي لحنان أحدهما - هزج خفيف - بالسبابة في مجرى البنصر عن إسحاق وابن المكي والآخر - رمل - بالبنصر عن عمرو وابن المكي والهشامي وفيه لمعبد - خفيف ثقيل - بالخنصر والبنصر عن ابن المكي قال وفيه لمالك - خفيف ثقيل - آخر نشيد ووافقه عمرو والهشامي وذكر عمرو في نسخته الأولى أنه لابن محرز والمعمول عليه الرواية الثانية","topic":"أخبار الفضل بن العباس اللهبي ونسبه","topicNo":201,"sp":7,"spl":"ذكر خبر من لم يمض له خبر ولا يأتي ممن ذكرت صنعته في هذا الخبر","song":1}]);
window.__BOOK__['p08'].push([{"id":"b202-2","bab":"الجزء 16","sec":"أخبار المهاجر بن خالد ونسبه وأخبار ابنه خالد — خالد سيف الله","page":"ج16 ص204 – ج16 ص205","text":"المهاجر بن خالد بن الوليد بن المغيرة بن عبد الله بن عمر بن مخزوم بن يقظة بن مرة بن كعب بن لؤي بن غالب وكان الوليد بن المغيرة سيدا من سادات قريش وجوادا من جودائها وكان يلقب بالوحيد وأمه صخرة بنت الحارث بن عبد الله بن عبد شمس امرأة من بجيلة ثم من قسر ولما مات الوليد بن المغيرة أرخت قريش بوفاته مدة لإعظامها إياه حتى كان عام الفيل فجعلوه تاريخا هكذا ذكر ابن دأب وأما الزبير بن بكار فذكر عن عمرو بن أبي بكر المؤملي أنها كانت تؤرخ بوفاة هشام بن المغيرة تسع سنين إلى أن كانت السنة التي بنوا فيها الكعبة فأرخوا بها\nولخالد بن الوليد من الشهرة بصحبة رسول الله والغناء في حروبه المحل المشهور ولقبه رسول الله سيف الله وهاجر إلى النبي قبل الفتح وبعد الحديبية هو وعمرو بن العاص\nوعثمان بن طلحة فقال النبي لما رآهم رمتكم مكة بأفلاذ كبدها وشهد فتح مكة مع النبي فكان أول من دخلها في مهاجرة العرب من أسفل مكة وشهد يوم مؤتة فلما قتل زيد بن حارثة وجعفر بن أبي طالب وعبد الله بن رواحة ورأى ألا طاقة للمسلمين بالقوم انحاز بهم وحامى عليهم حتى سلموا فلقبه يومئذ رسول الله سيف الله حدثنا بذلك أجمع الحرمي بن أبي العلاء والطوسي عن الزبير بن بكار وكان خالد يوم حنين في مقدمة رسول الله ومعه بنو سليم فأصابته جراح كثيرة فأتاه رسول الله بعد هزيمة المشركين فنفث على جراحه فاندملت ونهض وله آثار في قتال أهل الردة في أيام أبي بكر رضي الله عنه مشهورة يطول ذكرها وهو فتح الحيرة بعث إليه أهلها عبد المسيح بن عمرو بن بقيلة فكلمه خالد فقال له من أين أقبلت قال من ورائي قال وأين تريد قال أمامي قال ابن كم أنت قال ابن رجل وامرأة قال فأين أقصى أثرك قال منتهى عمري قال أتعقل قال نعم وأقيد قال ما هذه الحصون قال بنيناها نتقي بها السفيه حتى يردعه الحليم قال لأمر ما اختارك\nقومك ما هذا في يدك قال سم ساعة قال وما تصنع به قال أردت أن أنظر ما تردني به فإن بلغت ما فيه صلاح لقومي عدت إليهم وإلا شربته فقتلت نفسي ولم أرجع إلى قومي بما يكرهون فقال له خالد أرنيه فناوله إياه فقال خالد باسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم ثم أكله فتجللته غشية ثم أفاق يمسح العرق عن وجهه فرجع ابن بقيلة إلى قومه فأخبرهم بذلك وقال ما هؤلاء القوم إلا من الشياطين وما لكم بهم طاقة فصالحوهم على ما يريدون ففعلوا أخبرني بذلك إبراهيم بن السري عن يحيى التميمي عن أبيه عن شعيب بن سيف وأخبرني به الحسن بن علي عن الحارث بن محمد عن محمد بن سعد عن الواقدي وأمره أبو بكر على جميع الجيوش التي بعثها إلى الشام لحرب الروم وفيهم أبو عبيدة بن الجراح ومعاذ بن جبل فرضوا به وبإمارته قالوا وكان رسول الله قد حلق رأسه ذات يوم فأخذ خالد شعره فجعله في قلنسوة له فكان لا يلقى جيشا وهي عليه إلا هزمه وروى عن النبي الحديث وحمل عنه ورآه النبي متدليا من هرشى فقال نعم الرجل خالد بن الوليد أخبرنا بذلك الطوسي والحرمي قالا حدثنا الزبير بن بكار قال حدثني\nيعقوب بن محمد عن عبد العزيز بن محمد عن عبد الواحد بن أبي عون عن أبي سعيد المقبري عن أبي هريرة أن رسول الله قال ذلك له قال الزبير وحدثني محمد بن سلام عن أبان بن عثمان قال لما مات خالد بن الوليد لم تبق امرأة من بني المغيرة إلا وضعت لمتها على قبره يعني حلقت رأسها ووضعت شعرها على قبره قال ابن سلام وقال يونس النحوي إن عمر رضي الله عنه قال حينئذ دعوا نساء بني المغيرة يبكين أبا سليمان ويرقن من دموعهن سجلا أو سجلين ما لم يكن نقع أو لقلقة قال والنقع مد الصوت بالنحيب واللقلقة حركة اللسان بالولولة ونحوها قال الزبير فيما ذكره لي من رويت عنه حدثني محمد بن الضحاك عن أبيه أن عمر بن الخطاب رضي الله عنه كان أشبه الناس بخالد بن الوليد فخرج عمر سحرا فلقيه شيخ فقال له مرحبا بك يا أبا سليمان فنظر إليه عمر فإذا هو علقمة بن علاثة فرد عليه السلام فقال له علقمة عزلك عمر بن الخطاب فقال له عمر نعم قال ما شبع لا أشبع الله بطنه قال له","topic":"أخبار المهاجر بن خالد ونسبه وأخبار ابنه خالد","topicNo":202,"sp":0,"spl":"أخبار المهاجر بن خالد ونسبه وأخبار ابنه خالد — خالد سيف الله"},
{"id":"b202-3","bab":"الجزء 16","sec":"خالد سيف الله","page":"ج16 ص205","text":"عمر فما عندك قال ما عندي إلا السمع والطاعة فلما أصبح عمر دعا بخالد وحضره علقمة بن علاثة فأقبل على خالد فقال له ماذا قال لك علقمة قال ما قال لي شيئا قال اصدقني فحلف خالد بالله ما لقيه ولا قال له شيئا فقال له علقمة حلا أبا سليمان فتبسم عمر فعلم خالد أن علقمة قد غلط فنظر إليه وفطن علقمة فقال له قد كان ذلك يا أمير المؤمنين فاعف عني عفا الله عنك فضحك عمر وأخبره الخبر أخبرني عمي قال حدثني أحمد بن الحارث الخراز قال حدثنا المدائني عن شيخ من أهل الحجاز عن زيد بن رافع مولى المهاجرين خالد بن الوليد وعن أبي ذئب عن أبي سهيل أو ابن سهيل أن معاوية لما أراد أن يظهر العهد ليزيد قال لأهل الشام إن أمير المؤمنين قد كبرت سنه ورق جلده ودق عظمه واقترب أجله ويريد أن يستخلف عليكم فمن ترون فقالوا عبد الرحمن بن خالد بن الوليد فسكت وأضمرها ودس ابن أثال الطبيب إليه فسقاه سما فمات وبلغ ابن أخيه خالد بن المهاجر بن خالد بن الوليد خبره وهو بمكة وكان أسوأ الناس رأيا في عمه لأن أباه المهاجر كان مع علي عليه السلام بصفين وكان عبد الرحمن بن خالد بن الوليد مع معاوية وكان خالد بن المهاجر على رأي أبيه هاشمي المذهب ودخل مع بني هاشم الشعب فاضطغن ذلك ابن الزبير عليه فألقى عليه زق خمر وصب بعضه على رأسه وشنع عليه بأنه وجد ثملا من الخمر فضربه الحد فلما قتل عمه عبد الرحمن مر به عروة بن الزبير فقال له يا خالد أتدع ابن أثال ينقي أوصال عمك بالشأم وأنت بمكة مسبل إزارك\nتجره وتخطر فيه متخايلا فحمي خالد ودعا مولى له يدعى نافعا فأعلمه الخبر وقال له لا بد من قتل ابن أثال وكان نافع جلدا شهما فخرجا حتى قدما دمشق وكان ابن أثال يمسي عند معاوية فجلس له في مسجد دمشق إلى اسطوانة وجلس غلامه إلى أخرى حتى خرج فقال خالد لنافع إياك أن تعرض له أنت فإني أضربه ولكن احفظ ظهري واكفني من ورائي فإن رابك شيء يريدني من ورائي فشأنك فلما حاذاه وثب عليه فقتله وثار إليه من كان معه فصاح بهم نافع فانفرجوا ومضى خالد ونافع وتبعهما من كان معه فلما غشوهما حملا عليهم فتفرقوا حتى دخل خالد ونافع زقاقا ضيقا ففاتا القوم وبلغ معاوية الخبر فقال هذا خالد بن المهاجر اقلبوا الزقاق الذي دخل فيه ففتش عليه فأتي به فقال لا جزاك الله من زائر خيرا قتلت طبيبي قال قتلت المأمور وبقي الآمر فقال له عليك لعنة الله أما والله لو كان تشهد مرة واحدة لقتلتك به أمعك نافع قال لا قال بلى والله ما اجترأت إلا به ثم أمر بطلبه فوجد فأتي به فضربه مئة سوط ولم يهج خالدا بشيء أكثر من أن حبسه وألزم بني مخزوم دية ابن أثال اثني عشر ألف درهم أدخل بيت المال منها ستة آلاف درهم وأخذ ستة آلاف درهم ولم يزل ذلك يجري في دية المعاهد حتى ولي عمر بن عبد العزيز فأبطل الذي يأخذه السلطان لنفسه وأثبت الذي يدخل بيت المال وخالد بن المهاجر الذي يقول\n(يا صاح يا ذا الضامر العنس ... والرحل ذي الأنساع والحلس)\n(سير النهار ولست تاركه ... وتجد سيرا كلما تمسي)\nفي هذين البيتين وبيت ثالث لم أجده في شعر المهاجر ولا أدري أهو له أم ألحقه به المغنون لحنان - ثقيل - أول - وخفيف ثقيل - ذكر يونس أن أحدهما لمالك ولم يذكر طريقة لحنه ووجدته في جامع غناء معبد عن الهشامي ويحيى المكي له فيه - خفيف ثقيل - وهكذا ذكر علي بن يحيى أيضا ولعله رواه عن ابن المكي وإن كان هذا لمعبد صحيحا فلحن مالك هو الثقيل الأول وذكر حبش وهو ممن لا يحصل قوله أن لحن معبد - ثقيل - أول بالوسطى","topic":"أخبار المهاجر بن خالد ونسبه وأخبار ابنه خالد","topicNo":202,"sp":1,"spl":"خالد سيف الله","song":1},
{"id":"b202-4","bab":"الجزء 16","sec":"رجع الخبر إلى سياقة خبر خالد","page":"ج16 ص211","text":"قال ولما حبس معاوية خالد بن المهاجر قال في الحبس\n(إما خطاي تقاربت ... مشي المقيد في الحصار)\n(فبما أمشي في الأباطح ... يقتفي أثري إزاري)\n(دع ذا ولكن هل ترى ... نارا تشب بذي مرار)\n(ما إن تشب لقرة ... للمصطلين ولا قتار)\n(ما بال ليلك ليس ينقص ... طوله طول النهار)\n(لتقاصر الأزمان أم ... غرض الأسير من الإسار)\nقال فبلغت أبياته معاوية فرق له وأطلقه فرجع إلى مكة فلما قدمها لقي عروة بن الزبير فقال له أما ابن أثال فقد قتلته وذاك ابن جرموز ينقي\nأوصال الزبير بالبصرة فاقتله إن كنت ثائرا فشكاه إلى أبي بكر بن عبد الرحمن ابن الحارث بن هشام فأقسم عليه أن يمسك عنه ففعل أخبرني أحمد بن عبيد الله بن عمار قال حدثني يعقوب بن نعيم قال حدثني إسحاق بن محمد قال حدثني عيسى بن محمد القحطبي قال حدثني محمد بن الحارث بن بسخنر قال غنى إبراهيم بن المهدي يوما بحضرة المأمون وأنا حاضر\n(يا صاح يا ذا الضامر العنس ... والرحل ذي الأقتاب والحلس)\nال وكانت لي جائزة قد خرجت فقلت تأمر سيدي يا أمير المؤمنين بإلقاء هذا الصوت علي مكان جائزتي فهو أحب إلي منها فقال له يا عم ألق هذا الصوت على محمد فألقاه علي حتى إذا كدت أن آخذه قال اذهب فأنت أحذق الناس به فقلت إنه لم يصلح لي بعده قال فاغد غدا علي فغدوت عليه فأعاده ملتويا فقلت له أيها الأمير لك في الخلافة ما ليس لأحد أنت ابن الخليفة وأخو الخليفة وعم الخليفة تجود بالرغائب وتبخل علي بصوت فقال ما أحمقك إن المأمون لم يستبقني محبة لي ولا صلة لرحمي ولا ليرب المعروف عندي ولكنه سمع من هذا الجرم ما لم يسمعه من غيره قال فأعلمت المأمون بمقالته فقال إنا لا نكدر على أبي إسحاق عفونا عنه فدعه فلما كانت أيام المعتصم نشط للصبوح يوما فقال\nأحضروا عمي فجاء في دراعة بغير طيلسان فأعلمت المعتصم بخبر الصوت سرا فقال يا عم غنني\n(يا صاح يا ذا الضامر العنس ... والرحل ذي الأقتاب والحلس)\nغناه فقال ألقه على محمد فقال قد فعلت وقد سبق مني قول ألا أعيده عليه ثم كان يتجنب أن يغنيه حيث أحضر\n(أقفر بعد الأحبة البلد ... فهو كأن لم يكن به أحد)\n(شجاك نؤي عفت معالمه ... وهامد في العراص ملتبد)\n(أمك عنسية مهذبة ... طابت لها الأمهات والقصد)\n(تدعى زهيرية إذا انتسبت ... حيث تلاقى الأنساب والعدد)\nلشعر لحمزة بن بيض والغناء لمعبد - خفيف ثقيل - أول بالسبابة في مجرى الوسطى عن إسحاق وفيه لابن عباد ثاني - ثقيل - بالوسطى عن الهشامي وعمرو وابن المكي","topic":"أخبار المهاجر بن خالد ونسبه وأخبار ابنه خالد","topicNo":202,"sp":2,"spl":"رجع الخبر إلى سياقة خبر خالد","song":1},
{"id":"b203-1","bab":"الجزء 16","sec":"أخبار حمزة بن بيض ونسبه","page":"ج16 ص214","text":"حمزة بن بيض الحنفي شاعر إسلامي من شعراء الدولة الأموية كوفي خليع ماجن من فحول طبقته وكان كالمنقطع إلى المهلب بن أبي صفرة وولده ثم إلى أبان بن الوليد وبلال بن أبي برده واكتسب بالشعر من هؤلاء مالا عظيما ولم يدرك الدولة العباسية أخبرني عمي قال حدثنا أبو هفان قال أخبرني أبو محلم عن المفضل قال أخذ حمزة بن بيض الحنفي بالشعر ألف ألف درهم من مال وحملان\nوثياب ورقيق وغير ذلك أخبرني أحمد بن عبيد الله بن عمار قال حدثني عبد الله بن أبي سعد قال حدثني أبو توبة قال قدم حمزة بن بيض على بلال بن أبي بردة فلما وصل إلى بابه قال لحاجبه استأذن لحمزة بن بيض الحنفي فدخل الغلام إلى بلال فقال حمزة بن بيض بالباب وكان بلال كثير المزح معه فقال اخرج إليه فقل حمزة بن بيض ابن من فخرج الحاجب إليه فقال له ذلك فقال ادخل فقل له الذي جئت إليه إلى بنيان الحمام وأنت أمرد تسأله أن يهب لك طائرا فأدخلك وناكك ووهب لك طائرا فشتمه الحاجب فقال له ما أنت وذا بعثك برسالة فأخبره بالجواب فدخل الحاجب وهو مغضب فلما رآه بلال ضحك وقال ما قال لك قبحه الله قال ما كنت لأخبر الأمير بما قال فقال يا هذا أنت رسول فأد الجواب قال فأبى فأقسم عليه حتى أخبره فضحك حتى فحص برجله وقال قل له قد عرفنا العلامة فادخل فدخل فأكرمه ورفعه وسمع مديحه وأحسن صلته قال وأراد بقوله ابن بيض ابن من قول الشاعر فيه\n(أنت ابن بيض لعمري لست أنكره ... وقد صدقت ولكن من أبو بيض)\nخبرني علي بن سليمان الأخفش قال حدثني محمد بن الحسن الأحول عن الأثرم عن أبي عمرو وأخبرني وكيع قال حدثني عبيد الله بن محمد بن عبيد بن سفيان قال حدثني أبو الحسن الشيباني قال حدثني شعيب بن صفوان قال","topic":"أخبار حمزة بن بيض ونسبه","topicNo":203,"sp":0,"spl":"أخبار حمزة بن بيض ونسبه"},
{"id":"b203-2","bab":"الجزء 16","sec":"حمزة يمدح فيثاب","page":"ج16 ص215","text":"قدم حمزة بن بيض على مخلد بن يزيد بن المهلب وعنده الكميت\nفأنشده قوله فيه\n(أتيناك في حاجة فاقضها ... وقل مرحبا يجب المرحب)\n(ولا تكلنا إلى معشر ... متى يعدوا عدة يكذبوا)\n(فإنك في الفرع من أسرة ... لهم خضع الشرق والمغرب)\n(وفي أدب منهم ما نشأت ... ونعم لعمرك ما أدبوا)\n(بلغت لعشر مضت من سنيك ... ما يبلغ السيد الأشيب)\n(فهمك فيها جسام الأمور ... وهم لداتك أن يلعبوا)\n(وجدت فقلت ألا سائل ... فيعطى ولا راغب يرغب)\n(فمنك العطية للسائلين ... وممن ينوبك أن يطلبوا)\nأمر له بمئة ألف درهم فقبضها قال وكيع في خبره وسأله عن حوائجه فأخبره بها فقضى جميعها وقال أيضا في خبره فحسده الكميت فقال له يا حمزة أنت كمهدي التمر إلى هجر قال نعم ولكن تمرنا\nأطيب من تمر هجر أخبرني علي بن سليمان قال حدثني محمد بن يزيد النحوي قال قال الجاحظ أصاب حمزة بن بيض حصر فدخل عليه قوم يعودونه وهو في كرب القولنج إذ ضرط رجل منهم فقال حمزة من هذا المنعم عليه أخبرني الحسن بن علي قال حدثني محمد بن القاسم بن مهرويه قال قال علي بن الصباح حدثني هشام بن محمد عن الشرقي قال زعم هشام بن عروة أن عبد الرحمن بن عنبسة مر فإذا هو بغلام أصبح الغلمان وأحسنهم ولم يكن لعبد الرحمن ولد فسأل عنه فقيل له يتيم من أهل الشام قدم أبوه العراق في بعث فقتل وبقي الغلام هاهنا فضمه ابن عنبسة إليه وتبناه فوقع الغلام فيما شاء من الدنيا ومر يوما على برذون ومعه خدم على ابن بيض وحول ابن بيض عياله في يوم شات وهم شعث عراة فقال ابن بيض من هذا فقيل صدقة يتيم ابن عنبسة فقال\n(يشعث صبياننا وما يتموا ... وأنت صافي الأديم والحدقه)\n(فليت صبياننا إذا يتموا ... يلقون ما قد لقيت يا صدقه)\n(عوضك الله من أبيك ومن ... أمك في الشام بالعراق مقه)\n(كفاك عبد الرحمن فقدهما ... فأنت في كسوة وفي نفقه)\n(تظل في درمك وفاكهة ... ولحم طير ما شئت أو مرقه)\n(تأوي إلى حاضن وحاضنة ... زادا على والديك في الشفقه)\n(فكل هنيئا ما عاش ثم إذا ... مات فلغ في الدماء والسرقه)\n(وخالف المسلمين قبلتهم ... وضل عنهم وخادن الفسقه)\n(واشتر نهد التليل ذا خصل ... لصوته في الصهيل صهصلقه)\n(واقطع عليه الطريق تلف غدا ... رب دنانير جمة ورقه)\nلما مات عبد الرحمن أصابه ما قال ابن بيض أجمع من الفساد والسرقة وصحبة اللصوص ثم كان آخر ذلك أنه قطع الطريق فأخذ وصلب أخبرني أحمد بن عبيد الله بن عمار قال حدثني النوفلي عن أبيه قال ابن عمار وأخبرني أحمد بن سليمان بن أبي شيخ قال حدثني أبي عن أبي سفيان الحميري قال خرج حمزة بن بيض يريد سفرا فاضطره الليل إلى قرية عامرة كثيرة الأهل والمواشي من الشاء والبقر كثيرة الزرع فلم يصطنعوا به خيرا فغدا عليهم وقال\n(لعن الإله قرية يممتها ... فأضافني ليلا إليها المغرب)\n(الزارعين وليس لي زرع بها ... والحالبين وليس لي ما أحلب)\n(فلعل ذاك الزرع يودي أهله ... ولعل ذاك الشاء يوما يجرب)\n(ولعل طاعونا يصيب علوجها ... ويصيب ساكنها الزمان فتخرب)\nال فلم يمر بتلك القرية سنة حتى أصابهم الطاعون فأباد أهلها وخربت إلى اليوم فمر بهم ابن بيض فقال كلا زعمت أني لا أعطى منيتي قالوا\nوأبيك لقد أعطيتها فلو كنت تمنيت الجنة كان خيرا لك قال أنا أعلم بنفسي لا أتمنى ما لست له بأهل ولكني أرجو رحمة ربي عز و جل أخبرني الحسن بن علي قال حدثنا محمد بن زكرياء الغلابي قال قال ابن عائشة خرج ابن بيض في سفر فنزل بقوم فلم يحسنوا ضيافته وأتوه بخبز يابس وألقوا لبغلته تبنا فأعرض عنهم وأقبل على بغلته فقال\n(أحسبيها ليلة أدلجتها ... فكلي إن شئت تبنا أو ذري)\n(قد أتى ربك خبز يابس ... فتعزي معه واصطبري)","topic":"أخبار حمزة بن بيض ونسبه","topicNo":203,"sp":1,"spl":"حمزة يمدح فيثاب"},
{"id":"b203-3","bab":"الجزء 16","sec":"حمزة يمدح فيثاب","page":"ج16 ص215","text":"دثنا محمد بن العباس اليزيدي قال حدثنا أحمد بن الحارث الخراز قال حدثنا المدائني قال قال حمزة بن بيض يوما للفرزدق أيما أحب إليك تسبق الخير أو يسبقك قال لا أسبقه ولا يسبقني ولكن نكون معا فأيما أحب إليك أن تدخل إلى بيتك فتجد رجلا قابضا على حر امرأتك أو تجد امرأتك قابضة على أيره فقال كلام لا بد من جوابه والبادي أظلم بل أجدها قابضة على أيره قد أغبته عن نفسها نسخت من كتاب أبي إسحاق الشايميني قال ابن الأعرابي وقع بين بني حنيفة بالكوفة وبين بني تميم شر حتى نشبت الحرب بينهم فقال رجل لحمزة بن بيض ألا تأتي هؤلاء القوم فتدفعهم عن قومك فإنك ذو بيان وعارضة فقال\n(ألا لا تلمني يابن ماهان إنني ... أخاف على فخارتي أن تحطما)\n(ولو أنني أبتاع في السوق مثلها ... وجدك ما باليت أن أتقدما)","topic":"أخبار حمزة بن بيض ونسبه","topicNo":203,"sp":2,"spl":"حمزة يمدح فيثاب — مفاضلة بين ناسك وشارب للنبيذ"},
{"id":"b203-4","bab":"الجزء 16","sec":"مفاضلة بين ناسك وشارب للنبيذ","page":"ج16 ص220","text":"قال وكان لابن بيض صديق عامل من عمال ابن هبيرة فاستودع رجلا ناسكا ثلاثين ألف درهم واستودع مثلها نبيذيا فأما الناسك فبنى بها داره وتزوج النساء وأنفقها وجحده وأما النبيذي فأدى إليه الأمانة في ماله فقال حمزة بن بيض فيهما\n(ألا لا يغرنك ذو سجدة ... يظل بها دائبا يخدع)\n(كأن بجبهته جلبة ... يسبح طورا ويسترجع)\n(وما للتقى لزمت وجهه ... ولكن ليغتر مستودع)\n(فلا تنفرن من اهل النبيذ ... وإن قيل يشرب لا يقلع)\n(فعندك علم بما قد خبرت ... إن كان علم بهم ينفع)\n(ثلاثون ألفا حواها السجود ... فليست إلى أهلها ترجع)\n(بنى الدار من غير ما ماله ... وأصبح في بيته أربع)\n(مهائر من غير مال حواه ... يقاتون أرزاقهم جوع)\nأخبرني بهذا الخبر الحسين بن محمد بن زكريا الصحاف قال حدثنا قعنب بن المحرز قال حدثنا أبو عبيدة والأصمعي وكيسان بن المعرف فذكروا نحو هذا الخبر إلا أنه حكى أن حمزة بن بيض هو الذي استودع الرجلين المال وقال\n(وأدى أخو الكأس ما عنده ... وما كنت في ردها أطمع)\nخبرني محمد بن خلف وكيع قال حدثنا عبد الله بن شبيب قال حدثني أحمد بن محمد عن ابن داجة قال اختصم أبو الجون السحيمي وحمزة بن بيض إلى المهاجر بن عبد الله الكلابي وهو على اليمامة فوثب عليه حمزة وقال\n(غمضت في حاجة كانت تؤرقني ... لولا الذي قلت فيها قل تغميضي)\nقال وما الذي قلت لك قال\n(حلفت بالله لي أن سوف تنصفني ... فساغ في الحلق ربقي بعد تجريضي)\nال وأنا أحلف لأنصفنك قال\n(سل هؤلاء إلى ماذا شهادتهم ... أم كيف أنت وأصحاب المعاريض)\nال أوجعهم ضربا فقال\n(وسل سحيما إذا وافاك أجمعهم ... هل كان بالشر حوض قبل تحويضي)\nال فقضى له فأنشأ السحيمي يقول\n(أنت ابن بيض لعمري لست أنكره ... حقا يقينا ولكن من أبو بيض)\n(إن كنت أنبضت لي قوسا لترميني ... فقد رميتك رميا غير تنبيض)\n(أو كنت خضخضت لي وطبا لتسقيني ... فقد سقيتك محضا غير ممخوض)\nقال فوجم حمزة وقطع به فقيل له ويلك ما لك لا تجيبه قال وبم أجيبه والله لو قلت له عبد المطلب بن هاشم أبو بيض ما نفعني ذلك بعد قوله ولكن من أبو بيض وأخبرني بهذا الخبر ابن دريد عن أبي حاتم عن أبي عبيدة بمثله وقال فيه إن المخاصم له أبو الحويرث السحيمي","topic":"أخبار حمزة بن بيض ونسبه","topicNo":203,"sp":2,"spl":"حمزة يمدح فيثاب — مفاضلة بين ناسك وشارب للنبيذ"},
{"id":"b203-5","bab":"الجزء 16","sec":"مدح يزيد بن المهلب وسليمان بن عبد الملك فكافآه","page":"ج16 ص222","text":"أخبرني محمد بن الحسن بن دريد قال أخبرنا السكن بن سعيد عن محمد بن عباد قال\nدخل حمزة بن بيض على يزيد بن المهلب السجن فأنشده\n(أغلق دون السماح والجود والنجدة ... باب حديده أشب)\n(ابن ثلاث وأربعين مضت ... لا ضرع واهن ولا نكب)\n(لا بطر إن تتابعت نعم ... وصابر في البلاء محتسب)\n(برزت سبق الجواد في مهل ... وقصرت دون سعيك العرب)\nقال والله يا حمزة لقد أسأت إذ نوهت باسمي في غير وقت تنويه ولا منزل لك ثم رفع مقعدا تحته فرمى إليه بخرقة مصرورة وعليه صاحب خبر\nواقف فقال خذ هذا الدينار فوالله ما أملك ذهبا غيره فأخذه حمزة وأراد أن يرده فقال له سرا خذه ولا تخدع عنه فقال حمزة فلما قال لي لا تخدع عنه قلت والله ما هذا بدينار فقال لي صاحب الخبر ما أعطاك يزيد فقلت أعطاني دينارا فأردت أن أرده عليه فاستحييت منه فلما صرت إلى منزلي حللت الصرة فإذا فص ياقوت أحمر كأنه سقط زند فقلت والله لئن عرضت هذا بالعراق ليعلمن أني أخذته من يزيد فيؤخذ مني فخرجت به إلى خراسان فبعته من رجل يهودي بثلاثين ألفا فلما قبضت المال وصار الفص في يده قال لي والله لو أبيت إلا خمسين ألف درهم لأخذته منك فكأنما قذف في قلبي جمرة فلما رأى تغير وجهي قال إني رجل تاجر ولست أشك أني قد غممتك قلت إي والله وقتلتني فاخرج إلي مائة دينار فقال أنفق هذه في طريقك لتتوفر عليك تلك أخبرني الحسين بن يحيى قال قال حماد بن إسحاق قرأت على أبي دخل حمزة بن بيض على يزيد بن المهلب وهو في حبس عمر بن عبد العزيز فأنشده قوله فيه\n(أصبح في قيدك السماحة والحامل ... للمعضلات والحسب)\n(لا بطر إن تتابعت نعم ... وصابر في البلاء محتسب)\nقال له ويحك أتمدحني على هذه الحال قال نعم لئن كنت هكذا لطالما أثبت على الثناء فأحسنت الثواب والرفد فهل بأس أن نسلفك الآن قال أما إذ جعلته سلفا فاقنع بما حضر إلى أن يمكن قضاء دينك وأمر غلامه فدفع إليه أربعة آلاف درهم وبلغ ذلك عمر بن عبد العزيز فقال قاتله الله يعطي في الباطل ويمنع الحق يعطي الشعراء ويمنع الأمراء\nأخبرني محمد بن الحسن بن دريد قال حدثنا عبد الأول بن مزيد قال حدثنا العمري عن الهيثم بن عدي قال أخبرني مخلد بن حمزة بن بيض قال قدم أبي على يزيد بن المهلب وهو عند سليمان بن عبد الملك فأدخله إليه فأنشده\n(ساس الخلافة والداك كلاهما ... من بين سخطة ساخط أو طائع)\n(أبواك ثم أخوك أصبح ثالثا ... وعلى جبينك نور ملك الرابع)\n(سريت خوف بني المهلب بعدما ... نظروا إليك بسم موت ناقع)\n(ليس الذي ولاك ربك منهم ... عند الإله وعندهم بالضائع)\nأمر له بخمسين ألفا أخبرني عمي قال حدثنا عبد الله بن عمرو قال حدثني جعفر بن محمد العاصمي قال حدثني عيينة بن المنهال قال حدثني الهيثم بن عدي قال حدثني أبو يعقوب الثقفي قال قال لي حمزة بن بيض لما وفد الكميت بن زيد إلى مخلد بن يزيد بن المهلب وهو يخلف أباه على خراسان وكان واليها وله ثماني عشرة سنة وقد مدحه بقصيدته التي أولها\n(هلا سألت معالم الأطلال ... )\nهي التي يقول فيها\n(يمشين مشي قطا البطاح تأودا ... قب البطون رواجح الأكفال)\nقصيدته التي يقول فيها\n(هلا سألت منازلا بالأبرق ... )","topic":"أخبار حمزة بن بيض ونسبه","topicNo":203,"sp":3,"spl":"مدح يزيد بن المهلب وسليمان بن عبد الملك فكافآه","partialRef":{"sid":"b30-6","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b203-6","bab":"الجزء 16","sec":"مدح يزيد بن المهلب وسليمان بن عبد الملك فكافآه","page":"ج16 ص222","text":"عطاه مئة ألف درهم سوى العروض والحملان فقدم الكوفة في هيئة لم ير مثلها فقلت في نفسي والله لأنا أولى من الكميت بما ناله من مخلد بن يزيد وإني لحليفه وناصره في العصبية على الكميت وعلى مضر جميعا فهيأت لمخلد مديحا على روي قصيدتي الكميت وقافيتيهما ثم شخصت إليه فلما كان قبل خروجي إليه بيوم أتتني جماعة من ربيعة في خمس ديات عليهم لمضر في البدو فقالوا إنك تأتي مخلدا وهو فتى العرب ونحن نعلم أنك لا تؤثر على نفسك ولكن إذا فرغ من أمرك فأعلمه ممشانا إليك ومسألتنا إياك كلامه فنرجو أن تكون عند ظننا فلما قدمت على مخلد خراسان أنزلني وفرش لي وأخدمني وحملني وكساني وخلطني بنفسه فكنت أسمر معه فقال لي ليلة أعليك دين يابن بيض قلت دعني من مسألتك إياي عن الدين إنك قد أعطيت الكميت عطية لست أرضى بأقل منها وإلا لم أدخل الكوفة ولم أعير بتقصيرك بي عنه فضحك ثم قال لي بل أزيدك على ما أعطيت الكميت فأمر لي بمئة ألف درهم كما أعطى الكميت وزادني عليه وصنع بي في سائر الألطاف كما صنع به فلما فرغت من حاجتي أتيته يوما ومعي تذكرة بحاجة القوم في الديات فلما جلس أنشدته\n(أتيناك في حاجة فاقضها ... وقل مرحبا يجب المرحب)\n(ولا تكلنا إلى معشر ... متى يعدوا عدة يكذبوا)\n(فإنك في الفرع من أسرة ... لهم خضع الشرق والمغرب)\n(وفي أدب منهم ما نشأت ... ونعم لعمرك ما أدبوا)\n(بلغت لعشر مضت من سنيك ... ما يبلغ السيد الأشيب)\n(فهمك فيها جسام الأمور ... وهم لداتك أن يلعبوا)\nقال مرحبا بك وبحاجتك فما هي فأخرجت إليه رقعة القوم وقلت حمالات في ديات فتبسم ثم أمر لي بعشرة آلاف درهم فقلت أو غير ذلك أيها الأمير قال وما هو قلت أدل على قبر المهلب حتى أشكو إليه قطيعة ولده فتبسم ثم قال زده يا غلام عشرة آلاف أخرى فأبيت وقلت بل أدل على قبر المهلب فقال زده يا غلام عشرة آلاف أخرى فما زلت أكررها ويزيدني عشرة آلاف حتى بلغت سبعين ألفا فخشيت والله أن يكون يلعب أو يهزأ بي فقلت وصلك الله أيها الأمير وآجرك وأحسن جزاءك فقال مخلد أما والله لو أقمت على كلامك ثم أتى ذلك على خراج خراسان لأعطيتكه","topic":"أخبار حمزة بن بيض ونسبه","topicNo":203,"sp":4,"spl":"مدح يزيد بن المهلب وسليمان بن عبد الملك فكافآه"},
{"id":"b203-7","bab":"الجزء 16","sec":"المأمون والنضر بن شميل","page":"ج16 ص226","text":"أخبرني محمد بن مزيد بن أبي الأزهر قال حدثنا الزبير بن بكار قال حدثني النضر بن شميل قال دخلت على أمير المؤمنين المأمون بمرو وعلي أطمار مترعبلة فقال لي يا نضر تدخل على أمير المؤمنين في مثل هذه الثياب فقلت إن حر مرو لا يدفع إلا بمثل هذه الأخلاق فقال لا ولكنك رجل متقشف فتجارينا\nالحديث فقال المأمون حدثني هشيم بن بشير عن مجالد عن الشعبي عن ابن عباس قال قال رسول الله إذا تزوج الرجل المرأة لدينها وجمالها كان فيه سداد من عوز هكذا قال سداد بالفتح فقلت صدق يا أمير المؤمنين حدثني عوف الأعرابي عن الحسن أن النبي قال إذا تزوج الرجل المرأة لدينها وجمالها كان فيه سداد من عوز وكان المأمون متكئا فاستوى جالسا وقال السداد لحن يا نضر عندك قلت نعم هاهنا يا أمير المؤمنين وإنما هشيم لحن وكان لحانة فقال ما الفرق بينهما قلت السداد القصد في الدين والطريقة والسبيل والسداد البلغة وكل ما سددت به شيئا فهو سداد وقد قال العرجي\n(أضاعوني وأي فتى أضاعوا ... ليوم كريهة وسداد ثغر)\nال فأطرق المأمون مليا ثم قال قبح الله من لا أدب له ثم قال أنشدني يا نضر أخلب بيت للعرب قال قلت قول حمزة بن بيض يا أمير المؤمنين\n(تقول لي والعيون هاجعة ... أقم علينا يوما فلم أقم)\n(قالت فأي الوجوه قلت لها ... لأي وجه إلا إلى الحكم)\n(متى يقل حاجبا سرادقه ... هذا ابن بيض بالباب يبتسم)\n(قد كنت أسلمت فيك مقتبلا ... فهات إذ حل أعطني سلمي)\nفقال المأمون لله درك كأنما شق لك عن قلبي فأنشدني أنصف بيت للعرب قال قلت قول أبي عروبة المدني\n(إني وإن كان ابن عمي عاتبا ... لمزاحم من خلفه وورائه)\n(ومفيده نصري وإن كنت امرأ ... متزحزحا عن أرضه وسمائه)\n(وأكون والي سره وأصونه ... حتى يحين علي وقت أدائه)\n(وإذا الحوادث أجحفت بسوامه ... قرنت صحيحتنا إلى جربائه)\n(وإذا دعا باسمي ليركب مركبا ... صعبا قعدت له على سيسائه)\n(وإذا أتى من وجهه بطريفة ... لم أطلع مما وراء خبائه)\n(وإذا ارتدى ثوبا جميلا لم أقل ... يا ليت أن علي حسن ردائه)\nقال أحسنت يا نضر أنشدني الآن أقنع بيت قالته العرب فأنشدته قول ابن عبدل الأسدي\n(إني امرؤ لم أزل وذاك من الله ... قديما أعلم الأدبا)\n(أقيم بالدار ما اطمأنت بي الدار ... وإن كنت مازحا طربا)\n(لا أجتوي خلة الصديق ولا ... أتبع نفسي شيئا إذا ذهبا)\n(أطلب ما يطلب الكريم من الرزق ... بنفسي وأجمل الطلبا)\n(وأحلب الثرة الصفي ولا ... أجهد أخلاف غيرها حلبا)\n(إني رأيت الفتى الكريم إذا ... رغبته في صنيعة رغبا)\n(والعبد لا يطلب العلاء ولا ... يعطيك شيئا إلا إذا رهبا)\n(مثل الحمار الموقع السوء لا ... يحسن مشيا إلا إذا ضربا)\n(قد يرزق الخافض المقيم وما ... شد بعيس رحلا ولا قتبا)\n(ويحرم الرزق ذو المطية والرحل ... ومن لا يزال مغتربا)\n(ولم أجد عدة الخلائق إلا ... الدين لما اعتبرت والحسبا)\nقال أحسنت يا نضر وكتب لي إلى الحسن بن سهل بخمسين ألفا وأمر خادما بإيصال رقعة وتنجيز ما أمر به لي فمضيت معه إليه فلما قرأ التوقيع ضحك وقال لي يا نضر أنت الملحن لأمير المؤمنين قلت لا بل لهشيم قال فذاك إذن وأطلق لي الخمسين ألف درهم وأمر لي بثلاثين ألفا وأخبرني الحسين بن يحيى قال حدثنا حماد عن أبيه قال بلغني أن حمزة بن بيض الحنفي كان يسامر عبد الملك بن بشر بن مروان وكان عبد الملك يعبث به عبثا شديدا فوجه إليه ليلة برسول وقال خذه على أي حال وجدته عليها ولا تدعه يغيرها وحلفه على ذلك وغلظ الأيمان عليه فمضى الرسول فهجم عليه فوجده يريد أن يدخل الخلاء فقال أجب الأمير فقال ويحك إني أكلت طعاما كثيرا وشربت نبيذا حلوا وقد أخذني بطني قال والله لا تفارقني أو أمضي بك إليه ولو سلحت في ثيابك فجهد في الخلاص فلم يقدر عليه فمضي به إلى عبد الملك","topic":"أخبار حمزة بن بيض ونسبه","topicNo":203,"sp":5,"spl":"المأمون والنضر بن شميل"},
{"id":"b203-8","bab":"الجزء 16","sec":"المأمون والنضر بن شميل","page":"ج16 ص226","text":"فوجده قاعدا في طارمة له وجارية جميلة كان يتحظاها جالسة بين يديه تسجر الند في طارمته فجلس يحادثه وهو يعالج ما هو فيه قال فعرضت لي ريح فقلت أسرحها وأستريح فلعل ريحها لا يتبين مع هذا البخور فأطلقتها فغلبت والله ريح الند وغمرته فقال ما هذا يا حمزة قلت علي عهد الله وميثاقه وعلي المشي والهدي إن كنت فعلتها وما هذا إلا عمل هذه الفاجرة فغضب واحتفظ وخجلت الجارية فما قدرت على الكلام ثم جاءتني أخرى فسرحتها وسطع والله ريحها فقال ما هذا ويلك أنت والله الآفة فقلت امرأتي فلانة طالق ثلاثا إن كنت فعلتها قال وهذه اليمين لازمة لي إن كنت فعلتها وما هو إلا عمل هذه الجارية فقال ويلك ما قصتك قومي إلى الخلاء إن كنت تجدين حسا فزاد خجلها وأطرقت وطمعت فيها فسرحت الثالثة وسطع من ريحها ما لم يكن في الحساب فغضب عبد الملك حتى كاد يخرج من جلده ثم قال خذ يا حمزة بيد الزانية فقد وهبتها لك وامض فقد نغصت علي ليلتي فأخذت والله بيدها وخرجت فلقيني خادم له فقال ما تريد أن تصنع قلت أمضي بهذه قال لا تفعل فوالله لئن فعلت ليبغضنك بغضا لا تنتفع به بعدها أبدا وهذه مئة دينار فخذها ودع الجارية فإنه يتحظاها وسيندم على هبته إياها لك قلت والله لا نقصتك من خمس مئة دينار فلم يزل يزايدني حتى بلغ مئتي دينار ولم تطب نفسي أن أضيعها فقلت هاتها فأعطانيها وأخذها الخادم فلما كان بعد ثلاث دعاني عبد الملك فلما قربت من داره لقيني الخادم\nفقال لي هل لك في مئة دينار وتقول ما لا يضرك ولعله أن ينفعك قلت وما ذاك قال إذا دخلت إليه ادعيت إليه عنده الثلاث الفسوات ونسبتها إلى نفسك وتنفح عن الجارية ما قرفتها به قلت هاتها فدفعها إلي ودخلت على عبد الملك فلما وقفت بين يديه قلت ألي الأمان حتى أخبرك بخبر يسرك وتضحك منه قال لك الأمان قلت أرأيت ليلة حضوري وما جرى قال نعم فقلت فعلي وعلي إن كان فسا تلك الفسوات غيري فضحك حتى سقط على قفاه ثم قال ويلك فلم لم تخبرني قلت أردت بذلك خصالا منها أن قمت فقضيت حاجتي وقد كان رسولك منعني منها ومنها أني أخذت جاريتك ومنها أن كافأتك على أذاك لي بمثله فقال فأين الجارية قلت ما برحت من دارك ولا خرجت حتى سلمتها إلى فلان الخادم وأخذت مائتي دينار فسر بذلك وأمر لي بمئتي دينار أخرى وقال هذه لجميل فعلك بي وتركك أخذ الجارية قال حمزة بن بيض ودخلت إليه يوما وكان له غلام لم ير الناس أنتن إبطا منه فقال لي يا حمزة سابق غلامي حتى يفوح صنانكما فأيكما كان صنانه أنتن فله مئة دينار فطمعت في المائة ويئست منها لما أعلمه من نتن إبط الغلام فقلت أفعل وتعادينا فسبقني فسلحت في يدي ثم لطخت إبطي بالسلاح وقد كان عبد الملك جعل بيننا حكما يخبره بالقصة فلما دنا الغلام منه فشمه وثب وقال هذا والله لا يساجله شيء فصحت به لا تعجل بالحكم مكانك ثم دنوت منه فألقمت أنفه إبطي حتى علمت أنه قد\nخالط دماغه وأنا ممسك لرأسه تحت يدي فصاح الموت والله هذا بالكنف أشبه منه بالآباط فضحك عبد الملك ثم قال أفحكمت له قال نعم فأخذت الدنانير أخبرني عمي قال حدثني جعفر العاصمي قال حدثنا عيينة بن المنهال عن الهيثم بن عدي عن أبي يعقوب الثقفي قال قال حمزة بن بيض دخلت يوما على مخلد بن يزيد فقلت\n(إن المشارق والمغارب كلها ... تجبى وأنت أميرها وإمامها)\nضحك ثم قال مه فقلت\n(أغفيت قبل الصبح نوم مسهد ... في ساعة ما كنت قبل أنامها)\nال ثم ماذا كان قلت\n(فرأيت أنك جدت لي بوصيفة ... موسومة حسن علي قيامها)\nال قد فعلت فقلت\n(وببدرة حملت إلي وبلغة ... سفواء ناجية يصل لجامها)\nال قد حقق الله رؤياك ثم أمر لي بذلك كله وما علم الله أني رأيت من ذلك شيئا قال مؤلف هذا الكتاب وقد روي هذا الخبر بعينه لابن عبدل الأسدي وذكرته في أخباره\nأخبرني محمد بن الحسن بن دريد قال حدثنا أبو حاتم قال حدثنا عمارة بن عقيل بن بلال بن جرير قال حج حمزة بن بيض الحنفي فقال له ابن عم له أحجج بي معك فأخرجه معه فحوقل عليه بعد نشاطه فقال ابن بيض فيه\n(وذي سنة لم يدر ما السير قبلها ... ولم يعتسف خرقا من الأرض مجهلا)\n(ولم يدر ما حل الحبال وعقدها ... إذا البرد لم يترك لكفيه معملا)\n(ولم يقر مأجورا ولا حج حجة ... فيضرب سهما أو يصاحب مكتلا)\n(غدونا به كالبغل ينفض رأسه ... نشاطا بناه الخير حتى تفتلا)","topic":"أخبار حمزة بن بيض ونسبه","topicNo":203,"sp":6,"spl":"المأمون والنضر بن شميل"},
{"id":"b203-9","bab":"الجزء 16","sec":"المأمون والنضر بن شميل","page":"ج16 ص226","text":"(ترى المحمل المحسور ناء عرامه ... وبابا إذا أمسى من الشر مقفلا)\n(وإن قلت ليلا أين أنت لحاجة ... أجاب بأن لبيك عشرا وأقبلا)\n(يسوق مطي القوم طورا وتارة ... يقود وإن شئنا حدا ثم جلجلا)\n(فأجلته خمسا وقلت له انتظر ... رويدا وأجلنا المطي ليدبلا)\n(فلما صدرنا عن زبالة وارتمت ... بنا العيس منها منقلا ثم منقلا)\n(ترامت به الموماة حتى كأنما ... يسف بمعسول الخزيرة حنظلا)\n(وحتى نبا عن مزود القوم ضرسه ... وعادى من الجهد الثريد المرعبلا)\n(وحتى لو أن الليث ليث خفية ... يحاوله عن نفسه ما تحلحلا)\n(وحتى لو أن الله أعطاه سؤله ... وقيل له ما تشتهي قال محملا)\n(فقلت له لما رأيت الذي به ... وقد خفت أن ينضى لدينا ويهزلا)\n(أطعني وكل شيئا فقال معذرا ... من الجهد أطعمني ترابا وجندلا)\n(فللموت خير منك جارا وصاحبا ... فدعني فلا لبيك ثم تجدلا)\n(وقال أقلني عثرتي وارع حرمتي ... وقد فر مني مرتين ليقفلا)\n(فقلت له لا - والذي أنا عبده - ... أقيلك حتى تمسح الركن أولا)\nخبرني حبيب بن نصر المهلبي قال حدثني عبد الله بن عمرو بن سعد قال حدثني إسماعيل بن إبراهيم الهاشمي قال حدثني أبو عمر العمري قال حدثني عطاء بن مصعب عن عاصم بن الحدثان قال قدم حمزة بن بيض على مخلد بن يزيد بن المهلب فوعده أن يصنع به خيرا ثم شغل عنه فاختلف إليه مرارا فلم يصل إليه وأبطأت عليه عدته فقال ابن بيض\n(أمخلد إن الله ما شاء يصنع ... يجود فيعطي من يشاء ويمنع)\n(وإني قد أملت منك سحابة ... فحالت سرابا فوق بيداء تلمع)\n(فأجمعت صرما ثم قلت لعله ... يثوب إلى أمر جميل فيرجع)\n(فأيأسني من خير مخلد أنه ... على كل حال ليس لي فيه مطمع)\n(يجود لأقوام يودون أنه ... من البغض والشنآن أمسى يقطع)\n(ويبخل بالمعروف عمن يوده ... فوالله ما أدري به كيف أصنع)\n(أأصرمه فالصرم شر مغبة ... ونفسي إليه بالوصال تطلع)\n(وشتان بيني في الوصال وبينه ... على كل حال أستقيم ويظلع)\n(وقد كان دهرا واصلا لي مودة ... ويمنعني من صرف دهري أضرع)\n(وأعقبني صرما على غير إحنة ... وبخلا وقدما كان لي يتبرع)\n(وغيره ما غير الناس قبله ... فنفسي بما يأتي به ليس تقنع)\nم كتبها في قرطاس وختمه وبعث به مع رجل فدفعه إلى غلامه فدفعه الغلام إليه فلما قرأه سأل الغلام من صاحب الكتاب قال لا أعرفه فأدخل إليه الرجل فقال من أعطاك هذا الكتاب ومن بعث به معك قال لا أدري ولكن من صفته كذا وكذا ووصف صفة ابن بيض فأمر فضرب عشرين سوطا على رأسه وأمر له بخمس مئة درهم وكساه وقال إنما ضربناك أدبا لك لأنك حملت كتابا لا تدري ما فيه لمن لا تعرف فإياك أن تعود لمثلها قال الرجل لا والله أصلحك الله لا أحمل كتابا لمن أعرف ولا لمن لا أعرف قال له مخلد احذر فليس كل أحد يصنع بك صنيعي وبعث إلى ابن بيض فقال له أتعرف ما لحق صاحبك الرجل قال لا فحدثه مخلد بقصته فقال ابن بيض والله أصلحك الله لا تزال نفسه تتوق إلى العشرين سوطا مع الخمس مائة أبدا فضحك مخلد وأمر له بخمسة آلاف درهم وخمسة أثواب وقال وأنت والله لا تزال نفسك تتوق إلى عتاب إخوانك أبدا\nقال أجل والله ولكن من لي بمثلك يعتبني إذا استعتبته ويفعل بي مثل فعلك ثم قال\n(وأبيض بهلول إذا جئت داره ... كفاني وأعطاني الذي جئت أسأل)\n(ويعتبني يوما إذا كنت عاتبا ... وإن قلت زدني قال حقا سأفعل)\n(تراه إذا ما جئته تطلب الندى ... كأنك تعطيه الذي جئت تسأل)\n(فلله أبناء المهلب فتية ... إذا لقحت حرب عوان تأكل)\n(هم يصطلون الحرب والموت كانع ... بسمر القنا والمشرفية من عل)\n(ترى الموت تحت الخافقات أمامهم ... إذا وردوا علوا الرماح وأنهلوا)\n(يجودون حتى يحسب الناس أنهم ... لجودهم نذر عليهم يحلل)\n(غيوث لمن يرجو نداهم وجودهم ... سمام لأقوام ذعاف يثمل)\n(وفى لي أبناء المهلب إنهم ... إذا سئلوا المعروف لم يتسعلوا)\n(فذلك ميراث المهللب إنه ... كريم نماه للمكارم أول)\n(جرى وجرت آباؤه فتحرزوا ... عن الذم في عيطاء لا تتوقل)\nلما أنشده ابن بيض هذه الأبيات أمر له بعشرة آلاف درهم وعشرة أثواب وقال نزيدك ما زدتنا ونضعف لك فقال\n(أمخلد لم تترك لنفسي بغية ... وزدت على ما كنت أرجو وآمل)\n(فكنت كما قد قال معن فإنه ... بصير بما قد قال إذ يتمثل)\n(وجدت كثير المال إذ ضن معدما ... يذم ويلحاه الصديق المؤمل)","topic":"أخبار حمزة بن بيض ونسبه","topicNo":203,"sp":7,"spl":"المأمون والنضر بن شميل"},
{"id":"b203-10","bab":"الجزء 16","sec":"المأمون والنضر بن شميل","page":"ج16 ص226","text":"(وإن أحق الناس بالجود من رأى ... أباه جوادا للمكارم يجزل)\n(ترب الذي قدم كان قدضم والد ... أغر إذا ما جئته يتهلل)\n(وجدت يزيدا والمهلب برزا ... فقلت فإني مثل ذلك أفعل)\n(ففزت كما فازا وجاوزت غاية ... يقصر عنها السابق المتمهل)\n(فأنت غياث لليتامى وعصمة ... إليك جمال الطالبي الخير ترحل)\n(أصاب الذي رجى نداك مخيلة ... تصب عزاليها عليه وتهطل)\n(ولم تلف إذ رجوا نوالك باخلا ... تضن على المعروف والمال يعقل)\n(وموت الفتى خير له من حياته ... إذا كان ذا مال يضن ويبخل)\nقال له مخلد احتكم فأبى فأعطاه عشرة آلاف دينار وجارية وغلاما وبرذونا أخبرني إسماعيل بن يونس الشيعي قال حدثنا أحمد بن الحارث الخراز عن المدائني قال كان حمزة بن بيض شاعرا ظريفا فشاتم حماد بن الزبرقان وكان من ظرفاء أهل الكوفة وكلاهما صاحب شراب وكان حماد يتهم بالزندقة فمشى الرجال بينهما حتى اصطلحا فدخلا يوما على بعض ولاة الكوفة فقال لابن بيض أراك قد صالحت حمادا فقال ابن بيض نعم أصلحك الله على ألا آمره بالصلاة ولا ينهاني عنها","topic":"أخبار حمزة بن بيض ونسبه","topicNo":203,"sp":8,"spl":"المأمون والنضر بن شميل — اشتاق إلى أهله فقال شعرا"},
{"id":"b203-11","bab":"الجزء 16","sec":"اشتاق إلى أهله فقال شعرا","page":"ج16 ص237","text":"أخبرني محمد بن زكريا الصحاف قال حدثنا قعنب بن المحرز الباهلي قال حدثني الهيثم بن عدي قال\nقدم حمزة بن بيض البصرة زائرا لبلال بن أبي بردة بن أبي موسى وبينهما مودة منذ الصبا فطال مقامه عنده فاشتاق إلى أهله وولده فكتب إلى بلال\n(كلت رحالي وأعواني وأحراسي ... إلى الأمير وإدلاجي وإملاسي)\n(إلى امرىء مشبع مجدا ومكرمة ... عادية فهو حال منهما كاسي)\n(فلست منك ولا مما مننت به ... من فضل ودك كالمرمي في راسي)\n(إني وإياك والإخوان كلهم ... في العسر واليسر لو قيسوا بمقياس)\n(وذاك مما ينوب الدهر من حدث ... كالورد في المثل المضروب والآس)\n(يبيد هذا فيبلى بعد جدته ... غضا وآخره رهن بإيناس)\n(وأنت لي دائم باق بشاشته ... يهتز في عود لا عش ولا عاسي)\nعجل له بلال صلته وسرحه إلى الكوفة أخبرني محمد بن خلف وكيع قال حدثنا إسحاق بن محمد النخعي قال حدثنا أبو المعارك الضبي قال حدثني أبو مسكين قال دخل حمزة بن بيض على سليمان بن عبد الملك فلما مثل بين يديه أنشأ يقول\n(رأيتك في المنام شننت خزا ... علي بنفسجا وقضيت ديني)\n(فصدق يا فدتك النفس رؤيا ... رأتها في المنام لديك عيني)\nفقال سليمان يا غلام أدخله خزانة الكسوة واشنن عليه كل ثوب خز\nبنفسجي فيها فخرج كأنه مشجب ثم قال له كم دينك قال عشرة آلاف درهم فأمر له بها\n(من سره ضرب يرعبل بعضه ... بعضا كمعمعة الأباء المحرق)\n(فليأت مأسدة تسن سيوفها ... بين المذاد وبين جزع الخندق)\nيروى يمعمع بعضه بعضا والمعمعة اختلاف الأصوات وشدة زجلها والمأسدة الموضع الذي تجتمع فيه الأسد وتسن تحد يقال سيف مسنون والمذاد موضع بالمدينة والخندق يعني به الذي احتفره رسول الله وأصحابه حول المدينة والشعر لكعب بن مالك الأنصاري والغناء لابن محرز خفيف رمل بإطلاق الوتر في مجرى الوسطى عن إسحاق وعمرو","topic":"أخبار حمزة بن بيض ونسبه","topicNo":203,"sp":8,"spl":"المأمون والنضر بن شميل — اشتاق إلى أهله فقال شعرا","song":1},
{"id":"b204-1","bab":"الجزء 16","sec":"أخبار كعب بن مالك الأنصاري ونسبه","page":"ج16 ص240","text":"هو كعب بن مالك بن أبي كعب واسم أبي كعب عمرو بن القين بن كعب بن سواد وقيل القين بن سواد هكذا قال ابن الكلبي بن غنم بن كعب بن سلمة بن سعد بن علي بن أسد بن شاردة بن يزيد بن جشم بن الخزرج بن حارثة بن ثعلبة بن عمرو بن عامر بن حارثة بن امرىء القيس بن ثعلبة بن مازن بن الأزد بن الغوث وكان كعب بن مالك من شعراء أصحاب رسول الله المعدودين وهو بدري عقبي وأبوه مالك بن أبي كعب بن القين شاعر وله في حروب الأوس والخزرج التي كانت بينهم قبل الإسلام آثار وذكر وعمه قيس بن أبي كعب شهد بدرا وهو شاعر أيضا وهو الذي حالف جهينة على الأوس وخبره في ذلك يذكر في موضعه بعد أخبار كعب وأبيه ولكعب بن مالك أصل عريق وفرع طويل في الشعر ابنه عبد الرحمن شاعر وابن ابنه بشير بن عبد الرحمن شاعر والزبير بن خارجة بن عبد الله بن كعب شاعر ومعن بن عمرو بن عبد الله بن كعب شاعر وعبد الرحمن بن عبد الله بن كعب أبو الخطاب شاعر ومعن بن وهب بن كعب شاعر وكلهم مجيد مقدم وعمر كعب بن مالك وروى عن النبي حديثا كثيرا وكل بني كعب بن مالك قد روى عنه الحديث\nفمما رواه ابن ابنه بشير عن أبيه عنه حدثني أحمد بن الجعد قال حدثنا أبو بكر بن أبي شيبة قال حدثنا أحمد بن عبد الملك قال حدثنا عتاب بن سلمة عن إسحاق بن راشد عن الزهري قال كان بشير بن عبد الرحمن بن كعب يحدث عن أبيه أن كعب بن مالك كان يحدث أن رسول الله قال والذي نفسي بيده لكأنما تنضحونهم بالنبل بما تقولون لهم من الشعر ومما رواه عنه ابنه عبد الله أخبرني أحمد بن الجعد قال حدثنا أبو بكر بن أبي شيبة قال حدثنا بكر بن عبد الرحمن قال حدثنا عيسى بن المختار عن ابن أبي ليلى عن إسماعيل بن أمية عن محمد بن مسلم عن عبد الله بن كعب بن مالك عن أبيه قال كان رسول الله يصلي المغرب ثم يرجع الناس إلى أهاليهم وهم يبصرون مواقع النبل حين يرمون ومما رواه ابنه محمد أخبرني أحمد بن الجعد قال حدثنا أبو بكر بن أبي شيبة قال حدثنا محمد بن سابق قال حدثنا إبراهيم بن طهمان عن أبي الزبير عن محمد بن كعب عن أبيه أنه حدثه أن النبي بعثه وأوس بن الحدثان أيام التشريق فنادى إنه لا يدخل الجنة إلا مؤمن وأيام منى أيام أكل وشرب ويقال كان كعب بن مالك عثمانيا وهو أحد من قعد عن علي بن أبي طالب عليه السلام فلم يشهد معه حروبه وخاطبه في أمر عثمان وقتلته خطابا نذكره بعد هذا في أخباره ثم اعتزله وله مراث في عثمان بن عفان رحمه الله وتحريض للأنصار على نصرته قبل قتله وتأنيب لهم على خذلانه بعد ذلك منها قوله\n(فلو حلتم من دونه لم يزل لكم ... يد الدهر عز لا يبوخ ولا يسري)\n(ولم تقعدوا والدار كاب دخانها ... يحرق فيها بالسعير وبالجمر)\n(فلم أر يوما كان أكثر ضيعة ... وأقرب منه للغواية والنكر)","topic":"أخبار كعب بن مالك الأنصاري ونسبه","topicNo":204,"sp":0,"spl":"أخبار كعب بن مالك الأنصاري ونسبه"},
{"id":"b204-2","bab":"الجزء 16","sec":"كعب يرثي عثمان في المسجد","page":"ج16 ص242","text":"أخبرني هاشم بن محمد الخزاعي قال حدثنا أبو غسان دماذ عن أبي عبيدة قال كان كعب بن مالك الأنصاري أحد من عاون عثمان على المصريين يجري وشهر سلاحه فلما ناشد عثمان الناس أن يغمدوا سيوفهم انصرف ولم ير أن الأمر يخلص إليه ولا ويجري القوم إلى قتله فلما قتل وقف كعب بن مالك على مجلس الأنصار في مسجد رسول الله فأنشدهم\n(من مبلغ الأنصار عني آية ... رسلا تقص عليهم التبيانا)\n(أن قد فعلتم فعلة مذكورة ... كست الفضوح وأبدت الشنآنا)\n(بقعودكم في دوركم وأميركم ... تحشى ضواحي داره النيرانا)\n(بينا يرجي دفعكم عن داره ... ملئت حريقا كابيا ودخانا)\n(حتى إذا خلصوا إلى أبوابه ... دخلوا عليه صائما عطشانا)\n(يعلون قلته السيوف وأنتم ... متلبثون مكانكم رضوانا)\n(الله يعلم أنني لم أرضه ... لكم صنيعا يوم ذاك وشانا)\n(يا لهف نفسي إذ يقول ألا أرى ... نفرا من الأنصار لي أعوانا)\n(والله لو شهد ابن قيس ثابت ... ومعاشر كانوا له إخوانا)\nعني ثابت بن قيس بن شماس\n(وأبو دجانة وابن أرقم ثابت ... وأخو المشاهد من بني عجلانا)\nأبو دجانة سماك بن خرشة وابن أرقم ثابت البلوي وأخو المشاهد من بني عجلان معن بن عدي عقبي\n(ورفاعة العمري وابن معاذهم ... وأخو معاوي لم يخف خذلانا)\nفاعة ابن عبد المنذر العمري وابن معاذ سعد بن معاذ وأخو معاوية المنذر بن عمرو الساعدي عقبي بدري\n(قوم يرون الحق نصر أميرهم ... ويرون طاعة أمره إيمانا)\n(إن يتركوا فوضى يروا في دينهم ... أمرا يضيق عنهم البلدانا)\n(فليعلين الله كعب وليه ... وليجعلن عدوه الذلانا)\n(إني رأيت محمدا إختاره ... صهرا وكان يعده خلصانا)\n(محض الضرائب ماجدا أعراقه ... من خير خندف منصبا ومكانا)\n(عرفت له عليا معد كلها ... بعد النبي الملك والسلطانا)\n(من معشر لا يغدرون بجارهم ... كانوا بمكة يرتعون زمانا)\n(يعطون سائلهم ويأمن جارهم ... فيهم ويردون الكماة طعانا)\n(فلو انكم مع نصركم لنبيكم ... يوم اللقاء نصرتم عثمانا)\n(أنسيتم عهد النبي إليكم ... ولقد ألظ ووكد الأيمانا)\nال فجعل القوم يبكون ويستغفرون الله عز و جل أخبرني أحمد بن عبد العزيز الجوهري وحبيب بن نصر المهلبي قالا حدثنا عمر بن شبة قال حدثنا أبو عامر عن ابن جريج عن هشام بن عروة عن أبيه قال رجز راجز من قريش برسول الله فقال\n(لم يغذها مد ولا نصيف ... ولا تميرات ولا تعجيف)\n(لكن غذاها اللبن الحريف ... والمخض والقارص والصريف)\nال فاحتفظت الأنصار حيث ذكر المد والتمر فقالوا لكعب بن مالك\nانزل فنزل فقال\n(لم يغذها مد ولا نصيف ... لكن غذاها الحنظل النقيف)\n(ومذقة كطرة الخنيف ... تبيت بين الزرب والكنيف)\nفقال رسول الله اركبا أخبرني الجوهري والمهلبي قالا حدثنا عمر بن شبة قال حدثنا هوذة بن خليفة قال حدثنا عوف بن محمد عن محمد بن سيرين في حديث طويل قال كان يهجوهم يعني قريشا ثلاثة نفر من الأنصار يجيبونهم حسان بن ثابت وكعب بن مالك وعبد الله بن رواحة وكان حسان وكعب يعارضانهم بمثل قولهم بالوقائع والأيام والمآثر ويعيرانهم بالمثالب وكان عبد الله بن رواحة يعيرهم بالكفر وينسبهم إليه ويعلم أن ليس فيهم شيء شر من الكفر فكانوا في ذلك الزمان أشد شيء عليهم قول حسان وكعب وأهون شيء عليهم قول ابن رواحة فلما أسلموا وفقهوا الإسلام كان أشد القول عليهم قول ابن رواحة","topic":"أخبار كعب بن مالك الأنصاري ونسبه","topicNo":204,"sp":1,"spl":"كعب يرثي عثمان في المسجد"},
{"id":"b204-3","bab":"الجزء 16","sec":"كعب يستأذن الرسول في هجاء قريش","page":"ج16 ص245","text":"أخبرني الجوهري والمهلبي قالا حدثنا عمر بن شبة قال حدثنا\nعبد الله بن بكر السهمي قال حدثني حاتم بن أبي صغيرة قال حدثنا سماك بن حرب قال أتي رسول الله فقيل إن أبا سفيان بن الحارث بن عبد المطلب يهجوك فقام ابن رواحة فقال يا رسول الله ائذن لي فيه فقال له أنت الذي تقول فثبت الله قال نعم يا رسول الله أنا الذي أقول\n(فثبت الله ما أعطاك من حسن ... تثبيت موسى ونصرا كالذي نصرا)\nقال وأنت فعل الله بك مثل ذلك قال فوثب كعب بن مالك فقال يا رسول الله ائذن لي فيه فقال أنت الذي تقول همت قال نعم يا رسول الله أنا الذي أقول\n(همت سخينة أن تغالب ربها ... وليغلبن مغالب الغلاب)\nقال أما إن الله لم ينس لك ذلك أخبرني الجوهري والمهلبي قالا حدثنا عمر بن شبة قال حدثنا عبد الله بن يحيى مولى ثقيف قال حدثنا عبد الواحد بن زياد قال حدثنا مجالد عن الشعبي قال لما انهزم المشركون يوم الأحزاب قال رسول الله إن المشركين لن يغزوكم بعد اليوم ولكنكم تغزونهم وتسمعون منهم أذى ويهجونكم فمن يحمي أعراض المسلمين فقام عبد الله بن رواحة فقال أنا فقال إنك لحسن الشعر ثم قام كعب فقال أنا فقال وإنك لحسن الشعر أخبرني الجوهري والمهلبي قالا حدثنا عمر بن شبة قال حدثني\nمحمد بن منصور قال حدثني سعيد بن عامر قال حدثني جويرية بن أسماء قال بلغني أن رسول الله قال أمرت عبد الله بن رواحة فقال وأحسن وأمرت حسانا فشفى واشتفى أخبرني الجوهري والمهلبي قالا حدثنا عمر بن شبة قال حدثني أحمد بن عيسى قال حدثني عبد الله بن وهب عن عمرو بن الحارث أن يحيى بن سعيد حدثه عن عبد الله بن أنيس عن أمه وهي بنت كعب بن مالك أن النبي خرج على كعب وهو في مسجد رسول الله ينشد فلما رآه كأنه انقبض فقال ما كنتم فيه فقال كعب كنت أنشد فقال رسول الله فأنشد فأنشد حتى أتى على قوله\n(مقاتلنا عن جذمنا كل فخمة ... )\nقال رسول الله لا تقل عن جذمنا ولكن قل مقاتلنا عن ديننا قال أبو زيد وحدثني سعيد بن عامر قال حدثنا أبو عون عن ابن سيرين قال وقف رسول الله بباب كعب بن مالك فخرج فقال له رسول الله إيه فأنشده ثم قال إيه فأنشده ثم قال إيه فأنشده ثلاث مرات فقال رسول الله لهذا أشد عليهم من مواقع النبل أخبرني أحمد بن عبيد الله بن عمار قال حدثنا أبو جعفر محمد بن منصور الربعي وذكر أنه إسناد شآم هكذا قال قال ابن عمار في الخبر\nوذكر حديثا فيه طول لحسان بن ثابت والنعمان بن بشير وكعب بن مالك فذكرت ما كان لكعب فيه قال لما بويع لعلي بن أبي طالب عليه السلام بلغه عن حسان بن ثابت وكعب بن مالك والنعمان بن بشير - وكانوا عثمانية - أنهم يقدمون بني أمية على بني هاشم ويقولون الشأم خير من المدينة واتصل بهم أن ذلك قد بلغه فدخلوا عليه فقال له كعب بن مالك يا أمير المؤمنين أخبرنا عن عثمان أقتل ظالما فنقول بقولك أم قتل مظلوما فنقول بقولنا ونكلك إلى الشبهة فيه فالعجب من تيقننا وشكك وقد زعمت العرب أن عندك علم ما اختلفنا فيه فهاته نعرفه ثم قال\n(كف يديه ثم أغلق بابه ... وأيقن أن الله ليس بغافل)\n(وقال لمن في داره لا تقاتلوا ... عفا الله عن كل امرىء لم يقاتل)\n(فكيف رأيت الله صب عليهم العداوة ... والبغضاء بعد التواصل)\n(وكيف رأيت الخير أدبر عنهم ... وولى كإدبار النعام الجوافل)\nقال لهم علي عليه السلام لكم عندي ثلاثة أشياء استأثر عثمان فأساء الأثرة وجزعتم فأسأتم الجزع وعند الله ما تختلفون فيه إلى يوم القيامة فقالوا لا ترضى بهذا العرب ولا تعذرنا به فقال علي عليه السلام أتردون علي بين ظهراني المسلمين بلا بينة صادقة ولا حجة واضحة اخرجوا عني ولا تجاوروني في بلد أنا فيه أبدا فخرجوا من يومهم فساروا حتى أتوا معاوية فقال لهم لكم الولاية والكفاية فأعطى حسان بن ثابت ألف دينار وكعب بن مالك ألف دينار وولى النعمان بن بشير حمص ثم نقله إلى الكوفة بعد\nأخبرني عمي قال حدثنا أحمد بن الحارث قال حدثنا المدائني عن عبد الأعلى القرشي قال قال معاوية يوما لجلسائه أخبروني بأشجع بيت وصف به رجل قومه فقال له روح بن زنباع قول كعب بن مالك\n(نصل السيوف إذا قصرن بخطونا ... قدما ونلحقها إذا لم تلحق)\nقال له معاوية صدقت وأما أبوه مالك بن أبي كعب أبو كعب بن مالك فإني أذكر قبل أخباره شيئا مما يغنى فيه من شعره فمن ذلك قوله","topic":"أخبار كعب بن مالك الأنصاري ونسبه","topicNo":204,"sp":2,"spl":"كعب يستأذن الرسول في هجاء قريش","song":1,"partial":1},
{"id":"b204-4","bab":"الجزء 16","sec":"كعب يستأذن الرسول في هجاء قريش","page":"ج16 ص245","text":"(لعمر أبيها لا تقول حليلتي ... ألا فر عني مالك بن أبي كعب)\n(وهم يضربون الكبش يبرق بيضه ... ترى حوله الأبطال في حلق شهب)\nلشعر لمالك بن أبي كعب والغناء لمالك - ثقيل - أول بالبنصر عن يونس والهشامي وفيه لإبراهيم - خفيف ثقيل - بالوسطى جميعا عن الهشامي وزعم ابن المكي أن خفيف الثقيل هو لحن مالك","topic":"أخبار كعب بن مالك الأنصاري ونسبه","topicNo":204,"sp":3,"spl":"كعب يستأذن الرسول في هجاء قريش"},
{"id":"b204-5","bab":"الجزء 16","sec":"الخصومة بين أبيه وبرذع بن عدي","page":"ج16 ص249","text":"وهذا الشعر يقوله مالك بن أبي كعب في حرب كانت بينه وبين رجل من بني ظفر يقال له برذع بن عدي\nوكان السبب فيما ذكره جعفر العاصمي عن عيينة بن المنهال ونسخته من كتاب أعطانيه علي بن سليمان الأخفش أن رجلا من طيىء قدم يثرب بإبل له يبيعها فنزل في جوار برذع بن عدي أخي بني ظفر فباع إبله واقتضى أثمانها وكان مالك بن أبي كعب بن القين أخو بني سلمة اشترى منه جملا فجعله ناضحا فمطله مالك بن أبي كعب بثمن جمله وحضر شخوص الطائي فشكا ذلك إلى برذع فمشى معه إلى منزل مالك ليكلمه أن يوفيه ثمن جمله أو يرده عليه فلم يجدا مالكا في منزله ووجدا الجمل باركا بالفناء فبعثه برذع وقال للطائي انطلق بجملك ثم خرجا مسرعين حتى دخلا في دار النبيت فأمنا فارتحل الطائي بالجمل إلى بلاده وبلغ مالكا ما صنع برذع فكره أن ينشب بين قومه وبين النبيت حرب فكف وقد أغضبه ذلك وجعل يسفه برذعا في جراءته عليه وما صنع فقال برذع بن عدي في ذلك\n(أمن شحط دار من لبابة تجزع ... وصرف النوى مما يشت ويجمع)\n(وليس بها إلا ثلاث كأنها ... مسفعة أو قد علاهن أيدع)\n(قد اقتربت لو كان في قرب دارها ... جداء ولكن قد تضن وتمنع)\n(وكان لها بالمنحنى وجنوبه ... مصيف ومشتى قبل ذلك ومربع)\n(أتاني وعيد الخزرجي كأنني ... ذليل له عند اليهودي مضرع)\n(متى تلقني لا تلق نهزة واجد ... وتعلم أني في الهزاهز أروع)\n(معي سمحة صفراء من فرع نبعة ... ولين إذا مس الضريبة يقطع)\n(ومطرد لدن إذا هز متنه ... متين كخرص الذابلات وأهزع)\n(فلا وإلهي لا يقول مجاوري ... ألا إنني قد خانني اليوم برذع)\n(وأحفظ جاري أن أخاتل عرسه ... ومولاي بالنكراء لا أتطلع)\n(وأجعل مالي دون عرضي إنه ... على الوجد والإعدام عرض ممنع)\n(وأصبر نفسي في الكريهة إنه ... لذي كل نفس مستقر ومصرع)\n(وإني بحمد الله لا ثوب فاجر ... لبست ولا من خزية أتقنع)\nأجابه مالك بن أبي كعب فقال\n(هل للفؤاد لدى شنباء تنويل ... أم لا نوال فإعراض وتحميل)\n(إن النساء كأشجار نبتن معا ... منهن مر وبعض المر مأكول)\n(إن النساء ولو صورن من ذهب ... فيهن من هفوات الجهل تخبيل)\nلغناء لسليم هزج بالوسطى عن الهشامي وبذل\n(إنك إن تنه إحداهن عن خلق ... فإنه واجب لا بد مفعول)\n(ونعجة من نعاج الرمل خاذلة ... كأن مأقيها بالحسن مكحول)\n(ودعتها في مقامي ثم قلت لها ... حياك ربك إني عنك مشغول)\n(وليلة من جمادى قد شربت بها ... والزق بيني وبين الشرج معدول)\n(ومرجحن على عمد دلفت به ... كأنه رجل في الصف مقتول)\n(ولا أهاب إذا ما الحرب حرشها الأبطال ... واضطربت فيها البهاليل)\n(أمضي أمامهم والموت مكتنع ... قدما إذا ما كبا فيها التنابيل)\n(علي فضفاضة كالنهي سابغة ... وصارم مثل لون الملح مصقول)\n(ولدنة في يدي صفراء تعلبها ... بعامل كشهاب النار موصول)\n(إني من الخزرج الغر الذين هم ... أهل المكارم لا يلفى لهم جيل)\n(في الحرب أنهك منهم للعدو إذا ... شبت وأعظم نيلا إن هم سيلوا)\n(أشبهت من والدي عزا ومكرمة ... وبرذع مدغم في الأوس مجهول)\n(نبئته يدعي عزا ويوعدني ... نوكا وعندي له بالسيف تنكيل)\nال ثم إن مالك بن أبي كعب خرج يوما لبعض حاجته فبينا هو يمشي وحده إذ لقيه برذع ومعه رجلان من بني ظفر فلما رأوا مالكا أقبلوا نحوه فبدرهم مالك إلى مكان من الحرة كثير الحجارة مشرف فقام عليه وأخذ في يده أحجارا وأقبلوا حتى دنوا منه فشاتموه وراموه بالحجارة وجعل مالك يلتفت إلى الطريق الذي جاء منه كأنه يستبطىء ناسا فلما رآه برذع وصاحباه يكثر الالتفات ظنوا أنه ينتظر ناسا كانوا معه وخشوا أن يأتوهم على تلك الحال فانصرفوا عنه فقال مالك بن أبي كعب في ذلك\n(لعمر أبيها لا تقول حليلتي ... ألا فر عني مالك بن أبي كعب)\n(أقاتل حتى لا أرى لي مقاتلا ... وأنجو إذا غم الجبان من الكرب)\n(أبى لي أن أعطى الصغار ظلامة ... جدودي وآبائي الكرام أولو السلب)\n(هم يضربون الكبش يبرق بيضه ... ترى حوله الأبطال في حلق شهب)\n(وهم أورثوني مجدهم وفعالهم ... فأقسم لا يزري بهم أبدا عقبي)\nيروى لا يخزيهم\n(وأرعى لجاري ما حييت ذمامه ... وأعرف ما حق الرفيق على الصحب)\n(ولا أسمع الندمان شيئا يريبه ... إذا الكأس دارت بالمدام على الشرب)\n(إذا ما اعترى بعض الندامى لحاجة ... فقولي له أهلا وسهلا وفي الرحب)","topic":"أخبار كعب بن مالك الأنصاري ونسبه","topicNo":204,"sp":4,"spl":"الخصومة بين أبيه وبرذع بن عدي","song":1},
{"id":"b204-6","bab":"الجزء 16","sec":"الخصومة بين أبيه وبرذع بن عدي","page":"ج16 ص249","text":"(إذا أنفدوا الزق الروي وصرعوا ... نشاوى فلم أقنع بقولهم حسبي)\n(بعثت إلى حانوتها فاستبأتها ... بغير مكاس في السوام ولا غصب)\n(وقلت اشربوا ريا هنيئا فإنها ... كماء القليب في اليسارة والقرب)\n(يطاف عليهم بالسديف وعندهم ... قيان يلهين المزاهر بالضرب)\n(فإن يصبروا لي الدهر أصبرهم بها ... ويرحب لهم باعي ويغزر لهم شربي)\n(وكان أبي في المحل يطعم ضيفه ... ويروي نداماه ويصبر في الحرب)\n(ويمنع مولاه ويدرك تبله ... ولو كان ذاك التبل في مركب صعب)\n(إذا ما منعت المال منكم لثروة ... فلا يهنني مالي ولا ينم لي كسبي)\nقد روي أن الشعر المنسوب إلى مالك بن أبي كعب لرجل من مراد يقال له مالك بن أبي كعب وذكر له خبر في ذلك أخبرني به محمد بن خلف بن المرزبان قال حدثنا أحمد بن الهيثم بن فراس قال حدثنا العمري عن الهيثم بن عدي عن عبد الله بن عباس عن مجالد عن الشعبي قال كان رجل من مراد يكنى أبا كعب وكان له ابن يدعى مالكا وبنت يقال لها طريفة فزوج ابنه مالكا امرأة من أرحب فلم تزل معه حتى مات أبو كعب فقالت الأرحبية لمالك إني قد اشتقت إلى أهلي ووطني ونحن هاهنا في جدب وضيق عيش فلو ارتحلت بأهلك وبي فنزلت على أهلي لكان عيشنا أرغد وشملنا أجمع فأطاعها وارتحل بها وبأمه وبأخته إلى بلاد أرحب فمر بحي كان بينهم وبين أبيه ثأر فعرفوا فرسه فخرجوا إليه وأحدقوا به وقالوا له استسلم وسلم الظعينة فقال أما وسيفي بيدي وفرسي تحتي فلا وقاتلهم حتى صرع فقال وهو يجود بنفسه\n(لعمر أبيها لا تقول حليلتي ... ألا فر عني مالك بن أبي كعب)\nذكر باقي الأبيات التي تقدم ذكرها قبل هذا الخبر قال مؤلف هذا الكتاب وأحسب هذا الخبر مصنوعا وأن الصحيح هو الأول\n\n(خيرت أمرين ضاع الحزم بينهما ... إما الضياع وإما فتنة عمم)\n(فقد هممت مرارا أن أساجلهم ... كأس المنية لولا الله والرحم)\nلشعر لعيسى بن موسى الهاشمي والغناء لمتيم الهاشمية - خفيف رمل - من روايتي ابن المعتز والهشامي","topic":"أخبار كعب بن مالك الأنصاري ونسبه","topicNo":204,"sp":5,"spl":"الخصومة بين أبيه وبرذع بن عدي","song":1},
{"id":"b205-1","bab":"الجزء 16","sec":"أخبار عيسى بن موسى ونسبه","page":"ج16 ص256","text":"عيسى بن موسى بن محمد بن علي بن عبد الله بن العباس بن عبد المطلب بن هاشم بن عبد مناف وقد مضى في عدة مواضع من هذا الكتاب ما تجاوزه نسب هاشم إلى أقصى مدى الأنساب وأمه وأم سائر إخوته وأخواته أم ولد وعيسى ممن ولد ونشأ بالحميمة من أرض الشام وكان من فحول أهله وشجعانهم وذوي النجدة والرأي والبأس والسودد منهم وقبل أن أذكر أخباره فإني أبدأ بالرواية في أن الشعر له إذ كان الشعر ليس من شأنه ولعل منكرا أن ينكر ذلك إذا قرأه أخبرني حبيب بن نصر المهلبي وعمي قالا حدثنا عبد الله بن أبي سعد ورأيت هذا الخبر بعد ذلك في بعض كتب ابن أبي سعد فقابلت به ما روياه فوجدته موافقا قال ابن أبي سعد حدثني علي بن النطاح قال حدثني أبو عبد الله محمد بن إسحاق بن عيسى بن موسى قال لما خلع أبو جعفر عيسى بن موسى وبايع للمهدي قال عيسى بن موسى\n(خيرت أمرين ضاع الحزم بينهما ... إما صغار وإما فتنة عمم)\n(وقد هممت مرارا أن أساقيهم ... كأس المنية لولا الله والرحم)\n(ولو فعلت لزالت عنهم نعم ... بكفر أمثالها تستنزل النقم)\nعلى هذه الرواية في الشعر روى من ذكرت وعلى ما صدرت من الخلاف في الألفاظ يغنى أنشدني طاهر بن عبد الله الهاشمي قال أنشدني ابن بريهة المنصوري هذه الأبيات وحكى أن ناقدا خادم عيسى كان واقفا بين يديه ليلة أتاه خبر المنصور وما دبره عليه من الخلع قال فجعل يتململ على فراشه ويهمهم ثم جلس فأنشد هذه الأبيات فعلمت أنه كان يهمهم بها وسألت الله أن يلهمه العزاء والصبر على ما جرى شفقة عليه قال ابن أبي سعد في الخبر الذي قدمت ذكره عنهم وحدثني محمد بن يوسف الهاشمي قال حدثني عبد الله بن عبد الرحيم قال حدثتني كلثم بنت عيسى قالت قال موسى بن محمد بن علي بن عبد الله بن العباس رأيت في المنام كأني دخلت بستانا فلم آخذ منه إلا عنقودا واحدا عليه من الحب المرصف ما الله به عليم فولد له عيسى بن موسى ثم ولد لعيسى من قد رأيت قال ابن أبي سعد في خبره هذا وحدثني علي بن مسلم الهاشمي قال حدثني عبد الوهاب بن عبد الرحمن بن مالك مولى عيسى بن موسى قال حدثني أبي قال كنا مع عيسى بن موسى لما سكن الحيرة فأرسل إلي ليلة من الليالي فأخرجني من منزلي فجئت إليه فإذا هو جالس على كرسي فقال لي يا عبد الرحمن لقد سمعت الليلة في داري شيئا ما دخل سمعي قط إلا ليلة بالحميمة\nوالليلة فانظر ما هو فدخلت أستقري الصوت فإذا هو في المطبخ وإذا الطباخون قد اجتمعوا وعندهم رجل من أهل الحيرة يغنيهم بالعود فكسرت العود وأخرجت الرجل وعدت إليه فأخبرته فحلف لي أنه ما سمعه قط إلا تلك الليلة بالحميمة وليلته هذه أخبرني الحرمي بن أبي العلاء والطوسي قالا حدثنا الزبير بن بكار قال حدثني عبد الله بن محمد بن المنذر عن صفية بنت الزبير بن هشام بن عروة عن أبيها قال كان عيسى بن موسى إذا حج يحج ناس كثير من أهل المدينة يتعرضون لمعروفه فيصلهم قالت فمر أبي بأبي الشدائد الفزاري وهو ينشد بالمصلى\n(عصابة إن حج عيسى حجوا ... )\n(وإن أقام بالعراق دجوا ... )\n(قد لعقوا لعيقة فلجوا ... )\n(فالقوم قوم حجهم معوج ... )\n(ما هكذا كان يكون الحج ... )\nال ثم لقي أبو الشدائد بعد ذلك أبي فسلم عليه فلم يردد عليه فقال له مالك يا أبا عبد الله لا ترد السلام علي فقال ألم أسمعك تهجو حاج بيت الله الحرام فقال أبو الشدائد\n(إني ورب الكعبة المبنيه ... )\n(والله ما هجوت من ذي نيه ... )\n(ولا امرىء ذي رعة نقيه ... )\n(لكنني أرعي على البريه ... )\n(من عصبة أغلوا على الرعيه ... )\n(بغير أخلاق لهم سريه ... )\nوت\n(آثار ربع قدما ... أعيا جوابا صمما)\n(سحت عليه ديم ... بمائها فانهدما)\n(كان لسعدى علما ... فصار وحشا رمما)\n(أيام سعدى سقم ... وهي تداوي السقما)\nلشعر للرقاشي والغناء لابن المكي رمل بالوسطى عن عمرو بن بانة","topic":"أخبار عيسى بن موسى ونسبه","topicNo":205,"sp":0,"spl":"أخبار عيسى بن موسى ونسبه","partial":1},
{"id":"b206-1","bab":"الجزء 16","sec":"أخبار الرقاشي ونسبه","page":"ج16 ص259","text":"هو الفضل بن عبد الصمد مولى رقاش وهو من ربيعة وكان مطبوعا سهل الشعر نقي الكلام وقد ناقض أبا نواس وفيه يقول أبو نواس\n(وجدنا الفضل أكرم من رقاش ... لأن الفضل مولاه الرسول)\nراد أبو نواس بهذا نفيه عن ولائه لأنه كان أكرم ممن ينتمي إليه وذهب أبو نواس إلى قول النبي أنا مولى من لا مولى له وذكر إبراهيم بن تميم عن المعلى بن حميد أن الرقاشي كان من العجم من أهل الري","topic":"أخبار الرقاشي ونسبه","topicNo":206,"sp":0,"spl":"أخبار الرقاشي ونسبه — الرقاشي شاعر آل برمك"},
{"id":"b206-2","bab":"الجزء 16","sec":"الرقاشي شاعر آل برمك","page":"ج16 ص260","text":"وقد مدح الرقاشي الرشيد وأجازه إلا أن انقطاعه كان إلى آل برمك فأغنوه عن سواهم أخبرني حبيب بن نصر المهلبي قال حدثنا أحمد بن يزيد المهلبي قال حدثني أبي قال كان الفضل الرقاشي منقطعا إلى آل برمك مستغنيا بهم عن سواهم وكانوا يصولون به على الشعراء ويروون أولادهم أشعاره ويدونون القليل والكثير منها تعصبا له وحفظا لخدمته وتنويها باسمه وتحريكا لنشاطه فحفظ ذلك لهم فلما نكبوا صار إليهم في حبسهم فأقام معهم مدة أيامهم\nينشدهم ويسامرهم حتى ماتوا ثم رثاهم فأكثر ونشر محاسنهم وجودهم ومآثرهم فأفرط حتى نشر منها ما كان مطويا وأذاع منها ما كان مستورا وجرى على شاكلته بعدهم وكان كالموقوف المديح على جميعهم صغيرهم وكبيرهم ثم انقطع إلى طاهر وخرج معه إلى خراسان فلم يزل بها معه حتى مات وكان مع تقدمه في الشعر ماجنا خليعا متهاونا بمروءته ودينه وقصيدته التي يوصي فيها بالخلاعة والمجون مشهورة سائرة في الناس مبتذلة في أيدي الخاصة والعامة وهي التي أولها\n(أوصى الرقاشي إلى إخوانه ... وصية المحمود في ندمانه)\nقد رأيت هذه القصيدة بعينها بخط الجاحظ في شعر أبي نعامة من جملة قصيدة له طويلة يهجو فيها جماعة ويأتي في وسطها بقصيدة الرقاشي وقال عبد الله بن المعتز حدثني ابن أبي الخنساء عن أبيه قال لما قال أبو دلف\n\n(ناوليني الرمح قد طال ... عن الحرب جمامي)\n(مر لي شهران مذ لم ... أرم قوما بسهامي)\nال الرقاشي يعارضه\n(جنبيني الدرع قد طال ... عن القصف جمامي)\n(واكسري المطرد والبيض ... وأثني بالحسام)\n(واقذفي في لجة البحر ... بقوسي وسهامي)\n(وبترسي وبرمحي ... وبسرجي ولجامي)\n(فبحسبي أن تريني ... بين فتيان كرام)\n(سادة نغدو مجدين ... على حرب المدام)\n(واصطفاق العود والنايات ... في جوف الظلام)\n(هزم أرواح دنان ... لم ننلها باصطلام)\n(نهزم الراح إذا ما ... هم قوم بانهزام)\n(ثم خل الضرب والطعن ... لأجساد وهام)\n(لشقي قال قد طال ... عن الحرب جمامي)","topic":"أخبار الرقاشي ونسبه","topicNo":206,"sp":0,"spl":"أخبار الرقاشي ونسبه — الرقاشي شاعر آل برمك","song":1},
{"id":"b206-3","bab":"الجزء 16","sec":"رثاؤه العباس البرمكي وجعفر البرمكي","page":"ج16 ص262","text":"أخبرني الحسن بن علي قال حدثني محمد بن موسى عن ابن النطاح قال توفي العباس بن محمد بن خالد بن برمك بالخلد والرشيد بالرصافة\nفي يوم جمعة فأخرجت جنازته مع العصر وحضر الرشيد والأمين وأخرجت المضارب إلى مقابر البرامكة بباب البردان وفرش للرشيد في مسجد هناك وجاء الرشيد في الحلق بالأعلام والحراب فصلى عليه ووقف على قبره حتى دفن فلما خرج يحيى ومحمد أخواه من القبر قبلا يد الرشيد وسألاه الانصراف فقال لا حتى يسوى عليه التراب ولم يزل قائما حتى فرغ من أمره وعزاهما وأمرهما بالركوب فقال الرقاشي يرثي العباس بن محمد بن خالد بن برمك\n(أتحسبني باكرت بعدك لذة ... أبا الفضل أو رفعت عن عاتق سترا)\n(أو انتفعت عيناي بعد بنظرة ... أو ادنيت من كأس بمشمولة ثغرا)\n(جفاني إذن يوما إلى الليل مؤنسي ... وأضحت يميني من ذخائرها صفرا)\n(ولكنني استشعرت ثوب استكانة ... وبت كأن الموت يحفر لي قبرا)\nغنى في الأول والثاني من هذه الأبيات الرف ثاني ثقيل بالبنصر عن الهشامي وعبد الله بن موسى وفيه ثقيل أول مجهول أحسبه لبعض جواري البرامكة وفيهما لإبراهيم بن المهدي خفيف رمل عن عبد الله بن موسى ومن ذلك قوله في جعفر\n(كم هاتف بك من باك وباكية ... يا طيب للضيف إذ تدعى وللجار)\n(إن يعدم القطر كنت المزن بارقه ... لمع الدنانير لا ما خيل الساري)\nقوله\n(لعمرك ما بالموت عار على الفتى ... إذا لم تصبه في الحياة المعاير)\n(وما أحد حي وإن كان سالما ... بأسلم ممن غيبته المقابر)\n(ومن كان مما يحدث الدهر جازعا ... فلا بد يوما أن يرى وهو صابر)\n(وليس لذي عيش عن الموت مقصر ... وليس على الأيام والدهر غابر)\n(وكل شباب أو جديد إلى البلى ... وكل امرىء يوما إلى الله صائر)\n(فلا يبعدنك الله عني جعفرا ... بروحي ولو دارت علي الدوائر)\n(فآليت لا أنفك أبكيك ما دعت ... على فنن ورقاء أو طار طائر)\nخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثني أبو غسان عن عبد العزيز بن أبي ثابت عن محمد بن عبد العزيز أن الرقاشي الشاعر فني في حب البرامكة حتى خيف عليه أخبرني محمد بن القاسم الأنباري قال حدثني أبي عن أبي عكرمة قال وأخبرني علي بن سليمان الأخفش قال حدثني محمد بن موسى عن إسماعيل بن مجمع عن أحمد بن الحارث عن المدائني أنه لما دارت الدوائر على آل برمك وأمر بقتل جعفر بن يحيى وصلب\nاجتاز به الرقاشي الشاعر وهو على الجذع فوقف يبكي أحر بكاء ثم أنشأ يقول\n(أما والله لولا خوف واش ... وعين للخليفة لا تنام)\n(لطفنا حول جذعك واستلمنا ... كما للناس بالحجر استلام)\n(فما أبصرت قبلك يابن يحيى ... حساما قده السيف الحسام)\n(على اللذات والدنيا جميعا ... ودولة آل برمك السلام)\nكتب أصحاب الأخبار بذلك إلى الرشيد فأحضره فقال له ما حملك على ما قلت فقال يا أمير المؤمنين كان إلي محسنا فلما رأيته على الحال التي هو عليها حركني إحسانه فما ملكت نفسي حتى قلت الذي قلت قال وكم كان يجري عليك قال ألف دينار في كل سنة قال فإنا قد أضعفناها لك أخبرني هاشم بن محمد الخزاعي أبو دلف قال حدثنا الرياشي قال كان الفضل الرقاشي يجلس إلى إخوان له يحادثهم ويألفونه ويأنسون به فتفرقوا في طلب المعاش وترامت بهم الأسفار فمر الرقاشي بمجلسهم الذي كانوا يجلسون فيه فوقف فيه طويلا ثم استعبر وقال\n(لولا التطير قلت غيركم ... ريب الزمان فخنتم عهدي)\n(درست معالم كنت آلفها ... من بعدكم وتغيرت عندي)\nخبرني محمد بن جعفر الصيدلاني النحوي قال حدثنا محمد بن القاسم قال حدثني أبو هفان عن يوسف بن الداية قال كان أبو نواس والفضل الرقاشي جالسين فجاءهما عمرو الوراق\nفقال رأيت جارية خرجت من دور آل سليمان بن علي فما رأيت جارية أحسن منها هيفاء نجلاء زجاء دعجاء كأنها خوط بان أو جدل عنان فخاطبتها فأجابتني بأحلى لفظ وأحسن لسان وأجمل خطاب فقال الرقاشي قد والله عشقتها فقال أبو نواس أو تعرفها قال لا والله ولكن بالصفة ثم أنشأ يقول\n(صفات وظن أورثا القلب لوعة ... تضرم في أحشاء قلب متيم)\n(تمثلها نفسي لعيني فانثنى ... إليها بطرف الناظر المتوسم)\n(يحملني حبي لها فوق طاقتي ... من الشوق دأب الحائر المتقسم)","topic":"أخبار الرقاشي ونسبه","topicNo":206,"sp":1,"spl":"رثاؤه العباس البرمكي وجعفر البرمكي"},
{"id":"b206-4","bab":"الجزء 16","sec":"رثاؤه العباس البرمكي وجعفر البرمكي","page":"ج16 ص262","text":"خبرني أحمد بن عبد العزيز الجوهري قال حدثني محمد بن القاسم بن مهرويه قال حدثني عبد الرحيم بن أحمد بن زيد الحراني قال قيل لابن دراج الطفيلي أتتطفل على الرؤوس قال وكيف لي بها قيل إن فلانا وفلانا قد اشترياها ودخلا بستان ابن بزيع فخرج يحضر خوفا من فوتهما فوجدهما قد لوحا بالعظام فوقف عليها ينظر ثم استعبر وتمثل قول الرقاشي\n(آثار ربع قدما ... أعيا جوابي صمما)\nابن دراج هذا يقال له عثمان وهو مولى لكندة وكان في زمن المأمون وله شعر مليح وأدب صالح وأخبار طيبة يجري ذكرها ههنا","topic":"أخبار الرقاشي ونسبه","topicNo":206,"sp":2,"spl":"رثاؤه العباس البرمكي وجعفر البرمكي — أخبار ابن دراج الطفيلي"},
{"id":"b206-5","bab":"الجزء 16","sec":"أخبار ابن دراج الطفيلي","page":"ج16 ص268","text":"أخبرني الجوهري عن ابن مهرويه عن أبيه قال قيل لعثمان بن دراج أتعرف بستان فلان قال إي والله وإنه للجنة الحاضرة في الدنيا قيل له فلم لا تدخل إليه فتأكل من ثماره تحت أشجاره وتسبح في أنهاره قال لأن فيه كلبا لا يتمضمض إلا بدماء عراقيب الرجال أخبرني الجوهري قال حدثنا ابن مهرويه قال حدثنا عبد الرحيم بن أحمد بن زيد الحراني قال كان عثمان بن دراج يلزم سعيد بن عبد الكريم الخطابي أحد ولد زيد بن الخطاب فقال له ويحك إني أبخل بأدبك وعلمك وأصونك وأضن بك عما أنت فيه من التطفيل ولي وظيفة راتبة في كل يوم فالزمني وكن مدعوا أصلح لك مما تفعل فقال رحمك الله أين يذهب بك فأين لذة الجديد وطيب التنقل كل يوم من مكان إلى مكان وأين نيلك ووظيفتك من احتفال الأعراس وأين ألوانك من ألوان الوليمة قال فأما إذا أبيت ذاك فإذا ضاقت عليك المذاهب فإني فيئة لك قال أما هذا فنعم فبينا هو عنده ذات يوم إذ أتت الخطابي مولاة له فقالت جعلت فداك زوجت ابنتي من ابن عم لها ومنزلي بين قوم طفيليين لا آمنهم أن يهجموا علي فيأكلوا ما صنعت ويبقى من دعوت فوجه معي بمن يمنعهم فقال\nنعم هذا أبو سعيد قم معها يا أبا سعيد فقال مري بين يدي وقام وهو يقول\n(ضجت تميم أن تقتل عامر ... يوم النسار فأعتبوا بالصيلم)\nال وقال الخطابي هذا لابن دراج كيف تصنع بأهل العرس إذا لم يدخلوك قال أنوح على بابهم فيتطيرون بذلك فيدخلوني قال وقال له رجل ما هذه الصفرة في لونك قال من الفترة بين القصفين ومن خوفي كل يوم من نفاد الطعام قبل أن أشبع أخبرني أحمد قال حدثنا ابن مهرويه عن عبد الرحيم بن أحمد أن ابن دراج صار إلى باب علي بن زيد أيام كان يكتب للعباس بن المأمون فحجبه الحاجب وقال ليس هذا وقتك قد رأيت القواد يحجبون فكيف يؤذن لك أنت قال ليست سبيلي سبيلهم لأنه يحب أن يراني ويكره أن يراهم فلم يأذن له فبيناهما على ذلك إذ خرج علي بن زيد فقال ما منعك يا أبا سعيد أن تدخل فقال منعني هذا البغيض فالتفت إلى الحاجب فقال بلغ بك بغضك أن تحجب هذا ثم قال يا أبا سعيد ما أهديت إلي من النوادر قال مرت بي جنازة ومعي ابني ومع الجنازة امرأة تبكيه تقول بك يذهبون إلى بيت لا فرش فيه ولا وطاء ولا ضيافة ولا غطاء ولا خبز فيه ولا ماء فقال لي ابني يا أبة إلى بيتنا والله يذهبون بهذه الجنازة فقلت له وكيف ويلك قال لأن هذه صفة بيتنا فضحك علي وقال قد أمرت لك بثلاث مئة درهم قال قد وفر الله عليك نصفها على أن أتغدى معك قال\nوكان عثمان مع تطفيله أشره الناس فقال هي عليك موفرة كلها وتتغدى معنا وعثمان بن دراج الذي يقول\n(لذة التطفيل دومي ... وأقيمي لا تريمي)\n(أنت تشفين غليلي ... وتسلين همومي)\nود إلى الرقاشي أخبرني محمد بن الحسن بن دريد قال حدثنا العكلي قال دخل الرقاشي على بعض أمراء الصدقة فقال له قد أصبح خضابك قانيا قال لأني أمسيت له معانيا قال وكيف تفعله قال أنعم الحناء عجنا واجعل ماءه سخنا وأروي شعري قبله دهنا فإن بات قنا وإن لم يفعل أغنى\n(من لعين رأت خيالا مطيفا ... واقفا هكذا علينا وقوفا)\n(طارقا موهنا ألم فحيا ... ثم ولى فهاج قلبا ضعيفا)\n(ليت نفسي وليت أنفس قومي ... يا يزيد الندى تقيك الحتوفا)\n(عتكي مهلبي كريم ... حاتمي قد نال فرعا منيفا)\nروضه من الخفيف والشعر لربيعة الرقي يمدح يزيد بن حاتم المهلبي والغناء لعبد الرحيم الرف - خفيف رمل - بالوسطى عن عمرو","topic":"أخبار الرقاشي ونسبه","topicNo":206,"sp":2,"spl":"رثاؤه العباس البرمكي وجعفر البرمكي — أخبار ابن دراج الطفيلي","song":1},
{"id":"b207-1","bab":"الجزء 16","sec":"أخبار ربيعة الرقي ونسبه","page":"ج16 ص271","text":"هو ربيعة بن ثابت الأنصاري ويكنى أبا شبابة وقيل إنه كان يكنى أبا ثابت وكان ينزل الرقة وبها مولده ومنشؤه فأشخصه المهدي إليه فمدحه بعدة قصائد وأثابه عليها ثوابا كثيرا وهو من المكثرين المجيدين وكان ضريرا وإنما أخمل ذكره وأسقطه عن طبقته بعده عن العراق وتركه خدمة الخلفاء ومخالطة الشعراء وعلى ذلك فما عدم مفضلا لشعره مقدما له أخبرني أحمد بن عبيد الله بن عمار قال حدثنا محمد بن داود عن ابن أبي خيثمة عن دعبل قال قلت لمروان بن أبي حفصة من أشعركم جماعة المحدثين يا أبا السمط قال أشعرنا أسيرنا بيتا قلت ومن هو قال ربيعة الرقي الذي يقول\n(لشتان ما بين اليزيدين في الندى ... يزيد سليم والأغر ابن حاتم)\nهذا البيت من قصيدة له مدح بها يزيد بن حاتم المهلبي وهجا\nيزيد بن أسيد السلمي وبعد البيت الذي ذكره مروان\n(يزيد سليم سالم المال والفتى ... أخو الأزد للأموال غير مسالم)\n(فهم الفتى الأزدي إتلاف ماله ... وهم الفتى القيسي جمع الدراهم)\n(فلا يحسب التمتام أني هجوته ... ولكنني فضلت أهل المكارم)\n(فيابن أسيد لا تسام ابن حاتم ... فتقرع إن ساميته سن نادم)\n(هو البحر إن كلفت نفسك خوضه ... تهالكت في موج له متلاطم)\nخبرني أحمد بن عبيد الله بن عمار قال حدثني محمد بن القاسم بن مهرويه قال حدثني أسيد بن خالد الأنصاري قال قلت لأبي زيد النحوي إن الأصمعي قال لا يقال شتان ما بينهما إنما يقال شتان ما هما وأنشد قول الأعشى\n(شتان ما يومى على كورها ... )\nفقال كذب الأصمعي يقال شتان ما هما وشتان ما بينهما وأنشدني لربيعة الرقي واحتج به\n(لشتان ما بين اليزيدين في الندى ... يزيد سليم والأغر ابن حاتم)\nفي استشهاد مثل أبي زيد على دفع مثل قول الأصمعي بشعر ربيعة الرقي كفاية له في تفضيله\nوذكره عبد الله بن المعتز فقال كان ربيعة أشعر غزلا من أبي نواس لأن في غزل أبي نواس بردا كثيرا وغزل هذا سليم سهل عذب نسخت من كتاب لعمي حدثنا ابن أبي فنن قال اشتهى جواري المهدي أن يسمعن ربيعة الرقي فوجه إليه المهدي من أخذه من مسجده بالرقة وحمل على البريد حتى قدم به على المهدي فأدخل عليه فسمع ربيعة حسا من وراء الستر فقال إني أسمع حسا يا أمير المؤمنين فقال اسكت يابن اللخناء واستنشده ما أراد فضحك وضحكن منه قال وكان فيه لين وكذلك كان أبو العتاهية ثم أجازه جائزة سنية فقال له\n(يا أمير المؤمنين الله ... سماك الأمينا)\n(سرقوني من بلادي ... يا أمير المؤمنينا)\n(سرقوني فاقض فيهم ... بجزاء السارقينا)\nال قد قضيت فيهم أن يردوك إلى حيث أخذوك ثم أمر به فحمل على البريد من ساعته إلى الرقة وفي يزيد بن حاتم يقول أيضا\n(يزيد الأزد إن يزيد قومي ... سميك لا يجود كما تجود)\n(يقود جماعة وتقود أخرى ... فترزق من تقود ومن يقود)\n(فما تسعون يحقرها ثلاث ... يقيم حسابها رجل شديد)\n(وكف شثنة جمعت لوجء ... بأنكد من عطائك يا يزيد)","topic":"أخبار ربيعة الرقي ونسبه","topicNo":207,"sp":0,"spl":"أخبار ربيعة الرقي ونسبه","partial":1},
{"id":"b207-2","bab":"الجزء 16","sec":"كان السبب في غضب الرشيد على العباس بن محمد","page":"ج16 ص274","text":"أخبرني الحسن بن علي قال حدثنا أحمد بن الحارث عن المدائني قال امتدح ربيعة الرقي العباس بن محمد بن علي بن عبد الله بن العباس بقصيدة لم يسبق إليها حسنا وهي طويلة يقول فيها\n(لو قيل للعباس يا بن محمد ... قل لا وأنت مخلد ما قالها)\n(ما إن أعد من المكارم خصلة ... إلا وجدتك عمها أو خالها)\n(وإذا الملوك تسايروا في بلدة ... كانوا كواكبها وكنت هلالها)\n(إن المكارم لم تزل معقولة ... حتى حللت براحتيك عقالها)\nي البيت الأول والبيت الأخير - خفيف رمل - بالوسطى يقال إنه لإبراهيم ويقال إنه للحسين بن محرز قال فبعث إليه بدينارين وكان يقدر فيه ألفين فلما نظر إلى الدينارين كاد يجن غيظا وقال للرسول خذ الدينارين فهما لك على أن ترد الرقعة من حيث لا يدري العباس ففعل الرسول ذلك فأخذها ربيعة وأمر من كتب في ظهرها\n(مدحتك مدحة السيف المحلى ... لتجري في الكرام كما جريت)\n(فهبها مدحة ذهبت ضياعا ... كذبت عليك فيها وافتريت)\n(فأنت المرء ليس له وفاء ... كأني إذ مدحتك قد رثيت)\nم دفعها إلى الرسول وقال له ضعها في الموضع الذي أخذتها منه فردها الرسول في موضعها فلما كان من الغد أخذها العباس فنظر فيها فلما قرأ الأبيات غضب وقام من وقته فركب إلى الرشيد وكان أثيرا عنده يبجله\nويقدمه وكان قد هم أن يخطب إليه ابنته فرأى الكراهة في وجهه فقال ما شأنك قال هجاني ربيعة الرقي فأحضر فقال له الرشيد يا ماص كذا وكذا من أمه أتهجو عمي وآثر الخلق عندي لقد هممت أن أضرب عنقك فقال والله يا أمير المؤمنين لقد مدحته بقصيدة ما قال مثلها أحد من الشعراء في أحد من الخلفاء ولقد بالغت في الثناء وأكثرت في الوصف فإن رأى أمير المؤمنين أن يأمره بإحضارها فلما سمع الرشيد ذلك منه سكن غضبه وأحب أن ينظر في القصيدة فأمر العباس بإحضار الرقعة فتلكأ عليه العباس ساعة فقال له الرشيد سألتك بحق أمير المؤمنين إلا أمرت بإحضارها فعلم العباس أنه قد أخطأ وغلط فأمر بإحضارها فأحضرت فأخذها الرشيد وإذا فيها القصيدة بعينها فاستحسنها واستجادها وأعجب بها وقال والله ما قال أحد من الشعراء في أحد من الخلفاء مثلها لقد صدق ربيعة وبر ثم قال للعباس كم أثبته عليها فسكت العباس وتغير لونه وجرض بريقه فقال ربيعة أثابني عليها يا أمير المؤمنين بدينارين فتوهم الرشيد أنه قال ذلك من الموجدة على العباس فقال بحياتي يا رقي كم أثابك قال وحياتك يا أمير المؤمنين ما أثابني إلا بدينارين فغضب الرشيد غضبا شديدا ونظر في وجه العباس بن محمد وقال سوءة لك أية حال قعدت بك عن إثابته أقلة المال فوالله لقد مولتك جهدي أم انقطاع المادة عنك فوالله ما انقطعت عنك أم أصلك فهو الأصل لا يدانيه شيء أم نفسك فلا ذنب لي بل نفسك فعلت ذلك بك حتى فضحت أباك وأجدادك وفضحتني ونفسك فنكس العباس رأسه ولم ينطق\nفقال الرشيد يا غلام أعط ربيعة ثلاثين ألف درهم وخلعة واحمله على بغلة فلما حمل المال بين يديه والبس الخلعة قال له الرشيد بحياتي يا رقي لا تذكره في شيء من شعرك تعريضا ولا تصريحا وفتر الرشيد عما كان هم به أن يتزوج إليه وظهر منه له بعد ذلك جفاء كثير واطراح","topic":"أخبار ربيعة الرقي ونسبه","topicNo":207,"sp":1,"spl":"كان السبب في غضب الرشيد على العباس بن محمد","song":1},
{"id":"b207-3","bab":"الجزء 16","sec":"عبثه بالعباس بن محمد بحضرة الرشيد","page":"ج16 ص276","text":"أخبرني علي بن صالح بن الهيثم قال حدثني أحمد بن أبي فنن الشاعر قال حدثني من لا أحصي من الجلساء أن ربيعة الرقي كان لا يزال يعبث بالعباس بن محمد بحضرة الرشيد العبث الذي يبلغ منه منذ جرى بينهما في مديحه إياه ما جرى من حيث لا يتعلق عليه فيه بشيء فجاء العباس يوما إلى الرشيد ببرنية فيها غالية فوضعها بين يديه ثم قال هذه يا أمير المؤمنين غالية صنعتها لك بيدي اختير عنبرها من شحر عمان ومسكها من مفاوز التبت وبانها من قعر تهامة فالفضائل كلها مجموعة فيها والنعت يقصر عنها فاعترضه ربيعة فقال ما رأيت أعجب منك ومن صفتك لهذه الغالية عند من إليه كل موصوف يجلب وفي سوقه ينفق وبه إليه يتقرب وما قدر غاليتك هذه أعزك الله حتى تبلغ في وصفها ما بلغت أأجريت بها إليه نهرا أم حملت إليه منها وقرا إن تعظيمك هذا عند من تجبى إليه خزائن الأرض وأموالها من كل بلدة وتذل لهيبته جبابرة الملوك المطيعة والمخالفة وتتحفه بطرف بلدانها وبدائع ممالكها حتى كأنك قد فقت به على كل ما عنده أو\nأبدعت له ما لا يعرفه أو خصصته بما لم يحوه ملكه لا تخلو فيه من ضعف أو قصر همة أنشدك الله يا أمير المؤمنين إلا جعلت حظي من كل جائزة وفائدة توصلها إلي مدة سنتي الغالية حتى أتلقاها بحقها فقال ادفعوها إليه فدفعت إليه فأدخل يده فيها وأخرج ملئها وحل سراويله وأدخل يده فطلى بها استه وأخذ حفنة أخرى وطلى بها ذكره وأنثييه وأخرج حفنتين فجعلهما تحت إبطيه ثم قال يا أمير المؤمنين مر غلامي أن يدخل إلي فقال أدخلوه إليه وهو يضحك فأدخلوه إليه فدفع إليه البرنية غير مختومة وقال اذهب إلى جاريتي فلانة بهذه البرنية وقل لها طيبي بها حرك واستك وإبطيك حتى أجيء الساعة وأنيكك فأخذها الغلام ومضى وضحك الرشيد حتى غشي عليه وكاد العباس يموت غيظا ثم قام فانصرف وأمر الرشيد لربيعة بثلاثين ألف درهم وذكر علي بن الحسين بن عبد الأعلى أنه رأى قصيدة لربيعة الرقي مكتوبة في دور بساط من بسط السلطان قديم وكان مبسوطا في دار العامة بسر من رأى فنسخها منه وهي قوله\n(وتزعم أني قد تبدلت خلة ... سواها وهذا الباطل المتقول)\n(لحا الله من باع الصديق بغيره ... فقالت نعم حاشاك إن كنت تفعل)\n(ستصرم إنسانا إذا ما صرمتني ... يحبك فانظر بعده من تبدل)\nي هذه الأبيات الثلاثة الأبيات لحن من الثقيل الأول ينسب إلى إبراهيم\nالموصلي وإلى إبراهيم بن المهدي وفيه لعريب رمل من رواية ابن المعتز وكان سبب إغراق ربيعة في هجاء يزيد بن أسيد أنه زاره يستميحه لقضاء دين كان عليه فلم يجد عنده ما أحب وبلغ ذلك يزيد بن حاتم المهلبي فطفل على قضاء دينه وبره فاستفرغ ربيعة جهده في مدحه وله فيه عدة قصائد مختارة يطول ذكرها وقد كان أبو الشمقمق عارضه في قوله\n(لشتان ما بين اليزيدين في الندى ... يزيد سليم والأغر ابن حاتم)\nي قصيدة مدح بها يزيد بن مزيد وسلخ بيت الرقي بل نقله وقال\n(لشتان ما بين اليزيدين في الندى ... إذا عد في الناس المكارم والمجد)\n(يزيد بني شيبان أكرم منهما ... وإن غضبت قيس بن عيلان والأزد)\n(فتى لم تلده من رعين قبيلة ... ولا لخم تنميه ولم تنمه نهد)\n(ولكن نمته الغر من آل وائل ... وبرة تنميه ومن بعدها هند)\nلم يسر في هذا المعنى شيء كما سار بيت ربيعة أخبرني أحمد بن عبيد الله بن عمار قال حدثنا محمد بن داود بن الجراح\nقال حدثنا محمد بن أبي الأزهر قال عرض نخاس على أحمد بن يزيد بن أسيد الذي هجاه ربيعة جواري فاختار جاريتين منهن ثم قال للنخاس أيتهما أحب إليك قال بينهما أعز الله الأمير كما قال الشاعر\n(لشتان ما بين اليزيدين في الندى ... يزيد سليم والأغر ابن حاتم)\nأمر بجر رجله وجواريه أخبرني حبيب بن نصر المهلبي قال حدثنا عبد الله بن شبيب قال لما حج الرشيد لقيه قبل دخوله مكة رجلان من قريش فانتسب له أحدهما ثم قال يا أمير المؤمنين نهكتنا النوائب وأجحفت بأموالنا المصائب ولنا بك رحم أنت أولى من وصلها وأمل أنت أحق من صدقه فما بعدك مطلب ولا عنك مذهب ولا فوقك مسؤول ولا مثلك مأمول وتكلم الآخر فلم يأت بشيء فوصلهما وفضل الأول تفضيلا كثيرا ثم أقبل على الفضل بن الربيع فقال يا فضل\n(لشتان ما بين اليزيدين في الندى ... يزيد سليم والأغر ابن حاتم)","topic":"أخبار ربيعة الرقي ونسبه","topicNo":207,"sp":2,"spl":"عبثه بالعباس بن محمد بحضرة الرشيد","song":1},
{"id":"b207-4","bab":"الجزء 16","sec":"سبب هجائه ليزيد بن أسيد","page":"ج16 ص279","text":"قال أحمد بن أبي طاهر حدثني أبو دعامة علي بن زيد بن عطاء الملط قال لما هجا ربيعة يزيد بن أسيد السلمي وكان جليلا عند المنصور والمهدي وفضل عليه يزيد بن حاتم قلت لربيعة يا أبا شبابة ما حملك على أن\nهجوت رجلا من قومك وفضلت عليه رجلا من الأزد فقال أخبرك أملقت فلم يبق لي شيء إلا داري فرهنتها على خمس مئة درهم ورحلت إليه إلى أرمينية فأعلمته ذلك ومدحته وأقمت عنده حولا فوهب لي خمس مئة درهم فتحملت وصرت بها إلى منزلي فلم يبقي معي كبير شيء فنزلت في دار بكراء فقلت لو أتيت يزيد بن حاتم ثم قلت هذا ابن عمي فعل بي هذا الفعل فكيف غيره ثم حملت نفسي على أن أتيته فأعلم بمكاني فتركني شهرا حتى ضجرت فأكريت نفسي من الحمالين وكتبت بيتا في رقعة وطرحتها في دهليزه والبيت\n(أراني ولا كفران لله راجعا ... بخفي حنين من يزيد بن حاتم)\nوقعت الرقعة في يد حاجبه فأوصلها إليه من غير علمي ولا أمري فبعث خلفي فلما دخلت عليه قال هيه أنشدني ما قلت فتمنعت فقال والله لتنشدني فأنشدته فقال والله لا ترجع كذلك ثم قال انزعوا خفيه فنزعا فحشاهما دنانير وأمر لي بغلمان وجوار وكسا أفلا ترى لي أن أمدح هذا وأهجو ذاك قلت بلى والله ثم قال وسار شعري حتى بلغ المهدي فكان سبب دخولي إليه أخبرني الحسن بن علي الأدمي قال حدثني محمد بن الحسن بن عباد بن الشهيد القرقيسياني قال حدثني عمي عبد الله بن عباد أن ربيعة بن ثابت الرقي الأسدي كان يلقب الغاوي وكان يهوى جارية\nيقال لها عثمة أمة لرجل من أهل قرقيسياء يقال له ابن مرار وكان بنو هاشم في سلطانهم قد ولوه مصر فأصاب بها مالا عظيما وبلغه خبر ربيعة مع جاريته فأحضره وعرض عليه أن يهبها له فقال لا تهبها لي فإن كل مبذول مملول وأكره أن يذهب حبها من قلبي ولكن دعني أواصلها هكذا فهو أحب إلي قال وقال فيها\n(اعتاد قلبك من حبيبك عيده ... شوق عراك فأنت عنه تذوده)\n(والشوق قد غلب الفؤاد فقاده ... والشوق يغلب ذا الهوى فيقوده)\n(في دار مرار غزال كنيسة ... عطر عليه خزوزه وبروده)\n(ريم أغر كأنه من حسنه ... صنم يحج ببيعه معبوده)\n(عيناه عينا جؤذر بصريمة ... وله من الظبي المربب جيده)\n(ما ضر عثمة أن تلم بعاشق ... دنف الفؤاد متيم فتعوده)\n(وتلده من ريقها فلربما ... نفع السقيم من السقام لدوده)\nهي قصيدة طويلة مدح فيها بعض ولد يزيد بن المهلب أخبرني يحيى بن علي قال حدثني أبي عن إسحاق بن إبراهيم\nالموصلي عن أبي بشر الفزاري قال لقي ربيعة الرقي معن بن زائدة في قدمة قدمها إلى العراق فامتدحه بقصيدة وأنشده إياها راويته فلم يهش له معن ولا رضي ربيعة لقاءه إياه وأثابه ثوابا نزرا فرده ربيعة وهجاه هجاء كثيرا فمما هجاه به قوله\n(معن يا معن يا بن زائدة الكلب ... التي في الذراع لا في البنان)\n(لا تفاخر إذا فخرت بآبائك ... وافخر بعمك الحوفزان)\n(فهشام من وائل في مكان ... أنت ترضى بدون ذاك المكان)\n(ومتى كنت يابن ظبية ترجو ... أن تثني على ابنة الغضبان)\n(وهي حوراء كالمهاة هجان ... لهجان وأنت غير هجان)\n(وبنات السليل عند بني ظبية ... أف لكم بني شيبان)\n(قيل معن لنا فلما اختبرنا ... كان مرعى وليس كالسعدان)\nال أبو بشر ظبية التي عيره بها أمة كانت لبني نهار بن أبي ربيعة بن ذهل بن شيبان لقيها عبد الله بن زائدة بن مطر بن شريك وكانت راعية لأهلها وهي في غنمها فسرقها ووقع عليها فولدت له زائدة بن عبد الله أبا معن بن زائدة ودجاجة بنت عبد الله قال وبنت السليل التي عناها امرأة من ولد الحوفزان\nأخبرني يحيى عن أبيه عن إسحاق عن أبي بشر الفزاري قال كان ربيعة الرقي يهوى جارية لرجل من أهل الكوفة يقال لها عثمة وكان أهلها ينزلون في جوار جعفي فقال فيها في أبيات له\n(جعفي جيرانها فقد عطرت ... جعفي من نشرها ورياها)\nقال له رجل من جعفي وأنا جار لها بيت بيت والله ما شممت من دارهم ريحا طيبة قط فتشمم ربيعة رائحته وقال وما ذنبي إذا كنت أخشم والله إني لأجد ريحها وريح طيبها منك وأنت لا تجده من نفسك أخبرني يحيى عن أبيه عن إسحاق عن أبي بشر قال كنت حاضرا ربيعة الرقي يوما وجاءته امرأة من منزل هذه الجارية فقالت تقول لك فلانة إن بنت مولاي محمومة فإن كنت تعرف عوذة تكتبها لها فافعل فقال اكتب لها يا أبا بشر هذه العوذة","topic":"أخبار ربيعة الرقي ونسبه","topicNo":207,"sp":3,"spl":"سبب هجائه ليزيد بن أسيد"},
{"id":"b207-5","bab":"الجزء 16","sec":"سبب هجائه ليزيد بن أسيد","page":"ج16 ص279","text":"(تفو تفو باسم إلهي الذي ... لا يعرض السقم لمن قد شفى)\n(أعيذ مولاتي ومولاتها ... وابنتها بعوذة المصطفى)\n(من شر ما يعرض من علة ... في الصبح والليل إذا أسدفا)\nال فقلت له يا أبا ثابت لست أحسن أن أكتب تفو تفو فكيف أكتبها قال انضح المداد من رأس القلم في موضعين حتى يكون كالنفث وادفع العوذة إليها فإنها نافعة ففعلت ودفعتها إليها فلم تلبث أن جاءتنا الجارية وهي لا تتمالك ضحكا فقالت له يا مجنون ما فعلت بنا كدنا والله نفتضح بما صنعت قال فما أصنع بك أشاعر أنا أم صاحب تعاويذ\n\n(ألا من بين الأخوين ... أمهما هي الثكلى)\n(تسائل من رأى ابنيها ... وتستشفي فما تشفى)\n(فلما استيأست رجعت ... بعبرة واله حرى)\n(تتابع بين ولولة ... وبين مدامع تترى)\nروضه من - الهزج - الشعر لجويرية بنت خالد بن قارظ الكنانية وتكنى أم حكيم زوجة عبيد الله بن عبد المطلب في ابنيها اللذين قتلهما بسر بن أرطأة أحد بني عامر بن لؤي باليمن والغناء لابن سريج ولحنه من القدر الأوسط من - الثقيل - الأول بالخنصر في مجرى البنصر وفيه لحنين الحيري ثاني - ثقيل - عن الهشامي وفيه لأبي سعيد مولى فائد - خفيف ثقيل - الأول مطلق في مجرى الوسطى","topic":"أخبار ربيعة الرقي ونسبه","topicNo":207,"sp":4,"spl":"سبب هجائه ليزيد بن أسيد — ذكر الخبر في مقتل ابني عبيد الله بن العباس بن عبد المطلب","song":1},
{"id":"b207-6","bab":"الجزء 16","sec":"ذكر الخبر في مقتل ابني عبيد الله بن العباس بن عبد المطلب","page":"ج16 ص285","text":"أخبرني بالسبب في ذلك محمد بن أحمد بن الطلاس قال حدثنا أحمد بن الحارث الخراز قال حدثنا علي بن محمد المدائني عن أبي مخنف عن جويرية بن أسماء والصقعب بن زهير وأبي بكر الهذلي عن أبي عمرو الوقاصي أن معاوية بن أبي سفيان بعث بسر بن أرطاة أحد بني عامر بن لؤي بعد تحكيم الحكمين وعلي بن أبي طالب رضي الله عنه يومئذ حي وبعث معه جيشا ووجه برجل من غامد ضم إليه جيشا آخر ووجه الضحاك بن قيس الفهري في جيش آخر وأمرهم أن يسيروا في البلاد فيقتلوا كل من وجدوه من شيعة علي بن أبي طالب عليه السلام وأصحابه وأن يغيروا على سائر أعماله ويقتلوا أصحابه ولا يكفوا أيديهم عن النساء والصبيان فمضى بسر لذلك على وجهه حتى انتهى إلى المدينة فقتل بها ناسا من أصحاب علي عليه السلام وأهل هواه وهدم بها دورا من دور القوم ومضى إلى مكة فقتل نفرا من آل أبي لهب ثم أتى السراة فقتل من بها من أصحابه وأتى نجران فقتل عبد الله بن عبد المدان الحارثي وابنه وكانا من أصهار بني\nالعباس ثم أتى اليمن وعليها عبيد الله بن العباس عاملا لعلي بن أبي طالب وكان غائبا وقيل بل هرب لما بلغه خبر بسر فلم يصادفه بسر ووجد ابنين له صبيين فأخذهما بسر لعنه الله وذبحهما بيده بمدية كانت معه ثم انكفأ راجعا إلى معاوية وفعل مثل ذلك سائر من بعث به فقصد الغامدي إلى الأنبار فقتل ابن حسان البكري وقتل رجالا ونساء من الشيعة","topic":"أخبار ربيعة الرقي ونسبه","topicNo":207,"sp":4,"spl":"سبب هجائه ليزيد بن أسيد — ذكر الخبر في مقتل ابني عبيد الله بن العباس بن عبد المطلب"},
{"id":"b207-7","bab":"الجزء 16","sec":"خطبة الجهاد لعلي","page":"ج16 ص286","text":"فحدثني العباس بن علي بن العباس النسائي قال حدثنا محمد بن حسان الأزرق قال حدثنا شبابة بن سوار قال حدثنا قيس بن الربيع عن عمرو بن قيس عن أبي صادق قال أغارت خيل لمعاوية على الأنبار فقتلوا عاملا لعلي عليه السلام يقال له حسان بن حسان وقتلوا رجالا كثيرا ونساء فبلغ ذلك علي بن أبي طالب صلوات الله عليه فخرج حتى أتى المنبر فرقيه فحمد الله وأثنى عليه وصلى على النبي ثم قال إن الجهاد باب من أبواب الجنة فمن تركه ألبسه الله ثوب الذلة وشمله البلاء وديث بالصغار وسيم الخسف وقد قلت لكم اغزوهم قبل أن\nيغزوكم فإنه لم يغز قوم قط في عقر دارهم إلا ذلوا فتواكلتم وتخاذلتم وتركتم قولي وراءكم ظهريا حتى شنت عليكم الغارات هذا أخو غامد قد جاء الأنبار فقتل عاملي عليها حسان بن حسان وقتل رجالا كثيرا ونساء والله لقد بلغني أنه كان يأتي المرأة المسلمة والأخرى المعاهدة فينزع حجلها ورعاثها ثم ينصرفون موفورين لم يكلم أحد منهم كلما فلو أن امرأ مسلما مات من دون هذا أسفا لم يكن عليه ملوما بل كان به جديرا يا عجبا عجبا يميت القلب ويشعل الأحزان من اجتماع هؤلاء القوم على ضلالتهم وباطلهم وفشلكم عن حقكم حتى صرتم غرضا ترمون ولا ترمون وتغزون ولا تغزون ويعصى الله وترضون إذا قلت لكم اغزوهم في الحر قلتم هذه حمارة القيظ فأمهلنا وإذا قلت لكم اغزوهم في البرد قلتم هذا أوان قر وصر فأمهلنا فإذا كنتم من الحر والبرد تفرون فأنتم والله من السيف أشد فرارا يا أشباه الرجال ولا رجال ويا طغام الأحلام وعقول ربات الحجال وددت والله أني لم أعرفكم بل وددت أني لم أركم معرفة والله جرعت بلاء وندما وملأتم جوفي غيظا بالعصيان والخذلان حتى لقد قالت قريش إن ابن أبي طالب رجل شجاع ولكن لا علم له بالحرب ويحهم هل فيهم أشد مراسا لها\nمني والله لقد دخلت فيها وأنا ابن عشرين وأنا الآن قد نيفت على الستين ولكن لا رأي لمن لا يطاع فقام إليه رجل فقال يا أمير المؤمنين أنا كما قال الله تعالى ( لا أملك إلا نفسي وأخي\nفمرنا بأمرك فوالله لنطيعنك ولو حال بيننا وبينك جمر الغضى وشوك القتاد قال وأين تبلغان مما أريد هذا أو نحوه ثم نزل","topic":"أخبار ربيعة الرقي ونسبه","topicNo":207,"sp":5,"spl":"خطبة الجهاد لعلي"},
{"id":"b207-8","bab":"الجزء 16","sec":"رسائل بين علي وأخيه عقيل","page":"ج16 ص288","text":"حدثنا محمد بن العباس اليزيدي قال حدثني عمي عبيد الله بن محمد قال حدثني جعفر بن بشير قال حدثني صالح بن يزيد الخراساني عن أبي مخنف عن سليمان بن أبي راشد عن ابن أبي الكنود عبد الرحمن بن عبيد قال كتب عقيل بن أبي طالب إلى أخيه علي بن أبي طالب عليه السلام أما بعد فإن الله عز و جل جارك من كل سوء وعاصمك من المكروه إني خرجت معتمرا فلقيت عبد الله بن أبي سرح في نحو من أربعين شابا من أبناء الطلقاء فقلت لهم وعرفت المنكر في وجوههم يا أبناء الطلقاء العداوة والله لنا منكم غير مستنكرة قديما تريدون بها إطفاء نور الله وتغيير أمره فأسمعني القوم وأسمعتهم ثم قدمت مكة وأهلها يتحدثون أن الضحاك بن قيس أغار على الحيرة فاحتمل من أموال أهلها ما شاء ثم انكفأ راجعا فأف لحياة\nفي دهر جرأ عليك الضحاك وما الضحاك وهل هو إلا فقع بقرقرة وقد ظننت وبلغني أن أنصارك قد خذلوك فاكتب إلي يابن أم برأيك فإن كنت الموت تريد تحملت إليك ببني أبيك وولد أخيك فعشنا ما عشت ومتنا معك فوالله ما أحب أن أبقى بعدك فواقا وأقسم بالله الأعز الأجل أن عيشا أعيشه في هذه الدنيا بعدك لعيش غير هنيء ولا مريء ولا نجيع والسلام فأجابه علي بن أبي طالب عليه السلام بسم الله الرحمن الرحيم أما بعد كلأنا الله وإياك كلاءة من يخشاه بالغيب إنه حميد مجيد فقد قدم علي عبد الرحمن بن عبيد الأزدي بكتابك تذكر فيه أنك لقيت ابن أبي سرح مقبلا من قديد في نحو من أربعين شابا من أبناء الطلقاء وإن بني أبي سرح طال ما كاد الله ورسوله وكتابه وصد عن سبيله وبغاها عوجا فدع بني أبي سرح عنك ودع قريشا وتركاضهم في الضلالة وتجوالهم في الشقاق فإن قريشا قد أجمعت على حرب أخيك إجماعها على حرب رسول الله قبل اليوم فأصبحوا قد جهلوا حقه وجحدوا فضله وبادوه بالعداوة ونصبوا له الحرب وجهدوا عليه كل الجهد وساقوا إليه جيش الأمرين اللهم فاجز عني قريشا الجوازي فقد قطعت رحمي وتظاهرت علي والحمد لله على كل حال وأما ما ذكرت من غارة الضحاك بن قيس على الحيرة فهو أقل وأذل من أن يقرب الحيرة ولكنه جاء في خيل جريدة فلزم الظهر وأخذ على\nالسماوة فمر بواقصة وشراف وما والى ذلك الصقع فسرحت إليه جيشا كثيفا من المسلمين فلما بلغه ذلك جاز هاربا فاتبعوه فلحقوه ببعض الطريق وقد أمعن في السير وقد طفلت الشمس للإياب فاقتتلوا شيئا كلا ولا فولى ولم يصبر وقتل من أصحابه بضعة عشر رجلا ونجا جريضا بعد ما أخذ منه بالمخنق فلأيا بلأي ما نجا وأما ما سألت عنه أن أكتب إليك فيه برأيي فإن رأيي قتال المحلين حتى ألقى الله لا يزيدني كثرة الناس حولي عزة ولا نفرقهم عني وحشة لأني محق والله مع الحق وأهله وما أكره الموت على الحق وما الخير كله إلا بعد الموت لمن كان محقا وأما ما عرضته علي من مسيرك إلي ببنيك وبني أبيك فلا حاجة لي في ذلك فأقم راشدا مهديا فوالله ما أحب أن تهلكوا معي إن هلكت ولا تحسبن ابن أبيك لو أسلمه الزمان والناس متضرعا متخشعا لكني أقول كما قال أخو بني سليم\n(فإن تسأليني كيف أنت فإنني ... صبور على ريب الزمان صليب)\n(يعز علي أن ترى بي كآبة ... فيشمت عاد أو يساء حبيب)\nوالسلام","topic":"أخبار ربيعة الرقي ونسبه","topicNo":207,"sp":6,"spl":"رسائل بين علي وأخيه عقيل"},
{"id":"b207-9","bab":"الجزء 16","sec":"رجع الخبر إلى سياقة مقتل الصبيين","page":"ج16 ص291","text":"ثم إن بسر بن أرطأة كر راجعا وانتهى خبره إلى علي عليه السلام أنه قتل عبد الرحمن وقثم ابني عبيد الله بن العباس فسرح حارثة بن قدامة السعدي في طلبه وأمره أن يغذ السير فخرج مسرعا فلما وصل إلى المدينة وانتهى إليه قتل علي بن أبي طالب عليه السلام وبيعة الحسن رضي الله تعالى عنه ركب في السلاح ودعا أهل المدينة إلى البيعة للحسن فامتنعوا فقال والله لتبايعن ولو بأستاهكم فلما رأى أهل المدينة الجد منه بايعوا للحسن وكر راجعا إلى الكوفة فأصاب أم حكيم بنت قارظ ولهى على ابنيها فكانت لا تعقل ولا تصغي إلى قول من أعلمها أنهما قد قتلا ولا تزال تطوف في المواسم تنشد الناس ابنيها بهذه الأبيات\n(يا من أحس بنيي اللذين هما ... كالدرتين تشظى عنهما الصدف)\n(يا من أحس بنيي اللذين هما ... سمعي وقلبي فقلبي اليوم مختطف)\n(يا من أحس بنيي اللذين هما ... مخ العظام فمخي اليوم مزدهف)\n(نبئت بسرا وما صدقت ما زعموا ... من قولهم ومن الإفك الذي اقترفوا)\n(أنحى على ودجي ابني مرهفة ... مشحوذة وكذاك الإثم يقترف)\n(حتى لقيت رجالا من أرومته ... شم الأنوف لهم في قومهم شرف)\n(فالآن ألعن بسرا حق لعنته ... هذا لعمر أبي بسر هو السرف)\n(من دل والهة حرى مدلهة ... على صبيين ضلا إذ هوى السلف)\nلغناء لأبي سعيد مولى فائد - ثقيل - أول بالوسطى عن عمرو وفيه - خفيف ثقيل - يقال إنه له أيضا وفيه لعريب - رمل - نشيد قالوا ولما بلغ علي بن أبي طالب عليه السلام قتل بسر الصبيين جزع لذلك جزعا شديدا ودعا على بسر لعنه الله فقال اللهم اسلبه دينه ولا تخرجه من الدنيا حتى تسلبه عقله فأصابه ذلك وفقد عقله فكان يهذي بالسيف ويطلبه فيؤتى بسيف من خشب ويجعل بين يديه زق منفوخ فلا يزال يضربه حتى يسأم ثم مات لعنه الله ولما كانت الجماعة واستقر الأمر على معاوية دخل عليه عبيد الله بن العباس وعنده بسر بن أرطأة فقال له عبيد الله أأنت قاتل الصبيين أيها الشيخ قال بسر نعم أنا قاتلهما فقال عبيد الله أما والله لوددت أن الأرض كانت أنبتتني عندك فقال بسر فقد أنبتتك الآن عندي فقال عبيد الله إلى السيف فقال له بسر هاك سيفي فلما أهوى عبيد الله إلى السيف ليتناوله أخذه معاوية ثم قال لبسر أخزاك الله شيخا قد كبرت وذهب عقلك تعمد إلى رجل من بني هاشم قد وترته وقتلت ابنيه تدفع إليه سيفك إنك لغافل عن قلوب بني هاشم والله لو تمكن منه لبدأ بي قبلك فقال عبيد الله أجل والله ثم إذن لثنيت به\nأخبرني أحمد بن عبيد الله بن عمار قال أخبرني محمد بن مسروق قال قال الأصمعي سمع رجل من أهل اليمن وقد قدم مكة امرأة عبيد الله بن العباس بن عبد المطلب تندب ابنيها اللذين قتلهما بسر بن أرطأة بقولها\n(يا من أحس ببنيي اللذين هما ... كالدرتين تشظى عنهما الصدف)\nرق لها فاتصل ببسر حتى وثق به ثم احتال لقتل ابنيه فخرج بهما إلى وادي أوطاس فقتلهما وهرب وقال\n(يا بسر بسر بني أرطاة ما طلعت ... شمس النهار ولا غابت على ناس)\n(خير من الهاشميين الذين هم ... عين الهدى وسمام الأشوس القاسي)\n(ماذا أردت إلى طفلي مدلهة ... تبكي وتندب من أثكلت في الناس)\n(إما قتلتهما ظلما فقد شرقت ... في صاحبيك قناتي يوم أوطاس)\n(فاشرب بكأسهما ثكلا كما شربت ... أم الصبيين أو ذاق ابن عباس)\nوت\n(ألا فاسقياني من شرابكما الوردي ... وإن كنت قد أنفدت فاسترهنا بردي)\n(سواري ودملوجي وما ملكت يدي ... مباح لكم نهب فلا تقطعوا وردي)\nروضه من - الطويل - والشعر لأم حكيم بنت يحيى بن الحكم بن أبي العاصي بن أمية بن عبد شمس والغناء لإبراهيم الموصلي - رمل - بالوسطى من رواية عمرو بن بانة","topic":"أخبار ربيعة الرقي ونسبه","topicNo":207,"sp":7,"spl":"رجع الخبر إلى سياقة مقتل الصبيين","song":1},
{"id":"b208-1","bab":"الجزء 16","sec":"ذكر أم حكيم وأخبارها","page":"ج16 ص294","text":"قد مضى ذكر نسبها وأمها زينب بنت عبد الرحمن بن الحارث بن هشام وكانت هي وأمها من أجمل نساء قريش فكانت قريش تقول لأم حكيم الواصلة بنت الواصلة وقيل الموصلة بنت الموصلة لأنهما وصلتا الجمال بالكمال وأم زينب بنت عبد الرحمن بن الحارث بن هشام سعدى بنت عوف بن خارجة بن سنان بن أبي خارجة بن عوف بن أبي حارثة بن لأم الطائي وكانت سعدى بنت عوف عند عبد الله بن الوليد بن المغيرة فولدت له سلمة وريطة ثم توفي عنها فخلف عليها طلحة بن عبيد الله فولدت له يحيى وعيسى ثم قتل عنها فخطبها عبد الرحمن بن الحارث بن هشام فتكلم بنوها وكرهوا أن تتزوج وقد صاروا رجالا فقالت إنه قد بقي في رحم أمكم فضلة شريفة لا بد من خروجها فتزوجها فولدت له المغيرة بن عبد الرحمن الفقيه وزينب وهي أم حكيم وكان المغيرة أحد أجواد قريش والمطعمين منهم وقد قدم الكوفة على عبد الملك بن بشر بن مروان وكان صديقه وبها جماعة يطعمون الناس من قريش وغيرهم فلما قدم تغيبوا فلم يظهر أحد منهم حتى خرج وبث المغيرة\nالجفان في السكك والقبائل يطعم الناس فقال فيه شاعر من أهل الكوفة\n(أتاك البحر طم على قريش ... مغيري فقد راغ ابن بشر)\nال مصعب الزبيري هو - يعني المغيرة - مطعم الجيش بمنى وهو إلى الآن يطعم عنه قال وكانت أخته زينب أحسن الناس وجها وقدا وكأن أعلاها قضيب وأسفلها كثيب فكانت تسمى الموصلة وسميت بنتها أم حكيم بذلك لأنها أشبهتها","topic":"ذكر أم حكيم وأخبارها","topicNo":208,"sp":0,"spl":"ذكر أم حكيم وأخبارها — زواجها من يحيى بن الحكم"},
{"id":"b208-2","bab":"الجزء 16","sec":"زواجها من يحيى بن الحكم","page":"ج16 ص295","text":"أخبرني عمي قال حدثني ابن أبي سعد قال حدثني علي بن محمد بن يحيى الكناني عن أبيه قال كانت زينب بنت عبد الرحمن من لين جسدها يقال لها الموصلة قال مصعب فتزوج زينب أبان بن مروان بن الحكم فولدت له عبد العزيز بن أبان ثم مات عنها فخطبها يحيى بن الحكم وعبد الملك بن مروان فمالوا إلى عبد الملك فأرسل يحيى إلى المغيرة بن عبد الرحمن كم الذي تأمل من عبد الملك والله لا يزيدها على ألف دينار ولا يزيدك على خمس مئة دينار ولها عندي خمسون ألف دينار ولك عندي عشرة آلاف دينار إن زوجتنيها فزوجه إياها على ذلك فغضب عليه عبد الملك وقال دخل علي في خطبتي والله لا يخطب على منبر ما دمت حيا ولا رأى مني ما يحب فأسقطه فقال يحيى لا أبالي كعكتان وزينب\nقال ابن أبي سعد وأخبرت عن محمد بن إسحاق المسيبي قال حدثني عبد الملك بن إبراهيم الطلحي أنها لما خطبت قالت لا أتزوج والله أبدا إلا من يغني أخي المغيرة فأرسل إليها يحيى بن الحكم أيغنيه خمسون ألف دينار قالت نعم قال فهي له ولك مثلها فقالت ما بعد هذا شيء أرسل إلى أهلك شيئا من طيب وشيئا من كسوة قال ويقال إن عبد الملك لما تزوجها يحيى قال لقد تزوجت أفوه غليظ الشفتين فقالت زينب هو خير من أبي الذبان فما فما له يعيبه بفمه وقال يحيى قولوا له أقبح من فمي ما كرهت من فمك أخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثني أبو غسان عن عبد العزيز بن أبي ثابت عن عمه محمد بن عبد العزيز أن عبد الملك خطب زينب إلى المغيرة أخيها وكتب إليه أن يلحق به وكان بفلسطين أو بالأردن فعرض له يحيى بن الحكم فقال له أين تريد قال أريد أمير المؤمنين قال وما تصنع به فوالله لا يزيدك على ألف دينار يكرمك بها وأربع مئة دينار لزينب ولك عندي ثلاثون ألف دينار سوى صداق زينب فقال المغيرة أو تنقل إلي المال قبل عقد النكاح قال نعم فنقل إليه المال فتجهز المغيرة وسير ثقله ثم دخل على يحيى فزوجه وخرج إلى المدينة فجعل عبد الملك ينتظر المغيرة فلما أبطأ عليه قيل له يا أمير المؤمنين إنه زوج يحيى بن الحكم زينب بنت عبد الرحمن بثلاثين ألف دينار وأعطاه إياها ورجع إلى منزله فغضب على يحيى وخلعه عن ماله وعزله عن عمله فجعل يحيى يقول\n(ألا لا أبالي اليوم ما فعل الدهر ... إذا بقيت لي كعكتان وزينب)","topic":"ذكر أم حكيم وأخبارها","topicNo":208,"sp":0,"spl":"ذكر أم حكيم وأخبارها — زواجها من يحيى بن الحكم"},
{"id":"b208-3","bab":"الجزء 16","sec":"زواج أم حكيم من عبد العزيز بن الوليد","page":"ج16 ص297","text":"قال وكانت زينب تسمى الموصلة من حسن جسدها وكانت أم حكيم تحت عبد العزيز بن الوليد بن عبد الملك تزوجها في حياة جده عبد الملك ولما عقد النكاح بينهما عقد في مجلس عبد الملك وأمر بإدخال الشعراء ليهنئوهم بالعقد ويقولوا في ذلك أشعارا كثيرة يرويها الناس فاختير منهم جرير وعدي بن الرقاع فدخلا وبدأ عدي لموضعه منهم فقال\n(قمر السماء وشمسها اجتمعا ... بالسعد ما غابا وما طلعا)\n(ما وارت الأستار مثلهما ... من ذا رأى هذا ومن سمعا)\n(دام السرور له بها ولها ... وتهنيا طول الحياة معا)\nقال جرير\n(جمع الأمير إليه أكرم حرة ... في كل ما حال من الأحوال)\n(حكمية علت الروابي كلها ... بمفاخر الأعمام والأخوال)\n(وإذا النساء تفاخرت ببعولة ... فخرتهم بالسيد المفضال)\n(عبد العزيز ومن يكلف نفسه ... أخلاقه يلبث بأكسف بال)\n(هنأتكم بمودة ونصيحة ... وصدقت في نفسي لكم ومقالي)\n(فلتهنك النعم التي خولتها ... يا خير مأمول وأفضل وال)\nأمر له عبد الملك بعشرة آلاف درهم ولعدي بن الرقاع بمثلها وقضى\nلأهله ومواليه يومئذ مئة حاجة وأمر لجميع من حضر من الحرس والكتاب بعشرة دنانير عشرة دنانير فلم تزل أم حكيم عند عبد العزيز مدة ثم تزوج ميمونة بنت عبد الرحمن بن أبي بكر فملكته وأحبها وذهبت بقلبه كل مذهب فلم ترض منه إلا بطلاق أم حكيم فطلقها فتزوجها هشام بن عبد الملك ثم مات عبد العزيز فتزوج هشام ميمونة أيضا وكان شديد المحبة لأم حكيم فطلق لها ميمونة اقتصاصا لها منها فيما فعلته بها في اجتماعهما عند عبد العزيز وقال لها هل أرضيتك منها فقالت نعم فولدت أم حكيم من هشام ابنه يزيد بن هشام وكان من رجالات بني أمية وكان أحد من يطعن على الوليد بن يزيد بن عبد الملك ويغري الناس به","topic":"ذكر أم حكيم وأخبارها","topicNo":208,"sp":1,"spl":"زواج أم حكيم من عبد العزيز بن الوليد"},
{"id":"b208-4","bab":"الجزء 16","sec":"كأس أم حكيم","page":"ج16 ص298","text":"قد وكانت أم حكيم منهومة بالشراب مدمنة عليه لا تكاد تفارقه وكأسها الذي كانت تشرب فيه مشهور عند الناس إلى اليوم وهو في خزائن الخلفاء حتى الآن وفيه يقول الوليد بن يزيد\n(عللاني بعاتقات الكروم ... واسقياني بكأس أم حكيم)\n(إنها تشرب المدامة صرفا ... في إناء من الزجاج عظيم)\n(جنبوني أذاة كل لئيم ... إنه ما علمت شر نديم)\n(ثم إن كان في الندامى كريم ... فأذيقوه مس بعض النعيم)\n(ليت حظي من النساء سليمى ... ان سلماي جنتي ونعيمي)\n(فدعوني من الملامة فيها ... إن من لامني لغير حليم)\nروضه من - الخفيف - غناء عمر الوادي من رواية يونس وفي رواية\nإسحاق غناه الغزيل أبو كامل خفيف رمل بالسبابة في مجرى البنصر فيقال إن هذا الشعر بلغ هشاما فقال لأم حكيم أتفعلين ما ذكره الوليد فقالت أو تصدقه الفاسق في شيء فتصدقه في هذا قال لا قالت فهو كبعض كذبه أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال كان يزيد بن هشام هجا الوليد بن يزيد بن عبد الملك فقال\n(فحسب أبي العباس كأس وقينة ... وزق إذا دارت به في الذوائب)\n(ومن جلساء الناس مثل ابن مالك ... ومثل ابن جزء والغلام ابن غالب)\nقال الوليد يهجوه ويعيره بشرب أمه الشراب\n(إن كأس العجوز كأس رواء ... ليس كأس ككأس أم حكيم)\n(إنها تشرب الرساطون صرفا ... في إناء من الزجاج عظيم)\n(لو به يشرب البعير أو الفيل ... لظلا في سكرة وغموم)\n(ولدته سكرى فلم تحسن الطلق ... فوافى لذاك غير حليم)\nكان لهشام منها ابن يقال له مسلمة ويكنى أبا شاكر وكان هشام ينوه باسمه وأراد أن يوليه العهد بعده وولاه الحج فحج بالناس وفيه يقول عروة بن أذينة - لما وفد على هشام - وفرق في الحجاز على أهلها مالا كثيرا\nوأحبه الناس ومدحوه\n(أتينا نمت بأرحامنا ... وجئنا بأمر أبي شاكر)\nفيه يقول الوليد بن يزيد بن عبد الملك في حياة أبيه وأشاع ذلك وغنى فيه وأراد أن يعيره بذلك\n(يا أيها السائل عن ديننا ... نحن على دين أبي شاكر)\n(نشربها صرفا وممزوجة ... بالسخن أحيانا وبالفاتر)\nقال بعض شعراء أهل الحجاز يجيبه\n(يا أيها السائل عن ديننا ... نحن على دين أبي شاكر)\n(الواهب البزل بأرسانها ... ليس بزنديق ولا كافر)\nذكر أحمد بن الحارث عن المدائني أن هشاما لما أراد أن يوليه العهد كتب بذلك إلى خالد بن عبد الله القسري فقال خالد أنا بريء من خليفة يكنى أبا شاكر فبلغ قوله هشاما فكان سبب إيقاعه به أخبرني علي بن سليمان الأخفش قال حدثني محمد بن موسى قمطر\nعن إسماعيل بن مجمع قال كنا نخرج ما في خزائن المأمون من الذهب والفضة فنزكي عنه فكان فيما يزكى عنه قائم كأس أم حكيم وكان فيه من الذهب ثمانون مثقالا قال محمد بن موسى سألت إسماعيل بن مجمع عن صفته فقال كأس كبير من زجاج أخضر مقبضه من ذهب هكذا ذكر إسماعيل وقد حدثني علي بن صالح بن الهيثم بمثله قال حدثنا إبراهيم بن أحمد المادرائي قال لما أخرج المعتمد ما في الخزائن ليباع في أيام ظهور الناجم بالبصرة أخرج إلينا كأس أم حكيم فكان كأسا مدورا على هيئة القحف يسع ثلاثة أرطال فقوم بأربعة دراهم فعجبنا من حصول مثله في الخزانة مع خساسة قدره فسألنا الخازن عنه فقال هذا كأس أم حكيم فرددناه إلى الخزانة ولعل الذهب الذي كان عليه أخذ منه حينئذ ثم أخرج ليباع قال محمد بن موسى وذكر لي عبيد الله بن محمد عن أبي الأغر قال كنا مع محمد بن الجنيد الختلي أيام الرشيد فشرب ذات ليلة فكان صوته\n(عللاني بعاتقات الكروم ... واسقياني بكأس أم حكيم)\nلم يزل يقترحه ويشرب عليه حتى السحر فوافاه كتاب خليفته في دار الرشيد إن الخليفة على الركوب وكان محمد أحد أصحاب الرشيد ومن يقدم دابته فقال ويحكم كيف أعمل والرشيد لا يقبل لي عذرا وأنا سكران فقالوا لا بد من الركوب فركب على تلك الحال فلما قدم إلى الرشيد دابته قال له يا","topic":"ذكر أم حكيم وأخبارها","topicNo":208,"sp":2,"spl":"كأس أم حكيم","song":2},
{"id":"b208-5","bab":"الجزء 16","sec":"كأس أم حكيم","page":"ج16 ص298","text":"محمد ما هذه الحال التي أراك عليها قال لم أعلم برأي أمير المؤمنين في الركوب فشربت ليلي أجمع قال فما كان صوتك فأخبره فقال له عد إلى منزلك فلا فضل فيك فرجع إلينا وخبرنا بما جرى وقال خذوا بنا في شأننا فجلسنا على سطح فلما متع النهار إذا خادم من خدم أمير المؤمنين قد أقبل إلينا على برذون في يده شيء مغطى بمنديل قد كاد ينال الأرض فصعد إلينا وقال لمحمد أمير المؤمنين يقرأ عليك السلام ويقول لك قد بعثنا إليك بكأس أم حكيم لتشرب فيه وبألف دينار تنفقها في صبوحك فقام محمد فأخذ الكأس من يد الخادم وقبلها وصب فيها ثلاثة أرطال وشربها قائما وسقانا مثل ذلك ووهب للخادم مئتي دينار وغسل الكأس وردها إلى موضعها وجعل يفرق علينا تلك الدنانير حتى بقي معه أقلها\n(علقم ما أنت إلى عامر ... الناقض الأوتار والواتر)\n(إن تسد الحوص فلم تعدهم ... وعامر ساد بني عامر)\n(عهدي بها في الحي قد درعت ... صفراء مثل المهرة الضامر)\n(قد حجم الثدي على صدرها ... في مشرق ذي بهجة ناضر)\n(لو أسندت ميتا إلى نحرها ... عاش ولم يحمل إلى قابر)\n(حتى يقول الناس مما رأوا ... يا عجبا للميت الناشر)\nروضه من - السريع - والشعر للأعشى أعشى بني قيس بن ثعلبة يمدح عامر بن الطفيل ويهجو علقمة بن علاثة والغناء لمعبد في الثالث وما بعده خفيف ثقيل الأول بالبنصر وفي الأبيات لحنين - ثقيل - أول مطلق في مجرى البنصر عن إسحاق وفيها أيضا لحن آخر ذكره في المجرد ولم يجنسه ولم ينسبه إلى أحد","topic":"ذكر أم حكيم وأخبارها","topicNo":208,"sp":3,"spl":"كأس أم حكيم — الخبر في هذه القصة وسبب منافرة عامر وعلقمة وخبر الأعشى وعلقمة وغيره","song":1},
{"id":"b208-6","bab":"الجزء 16","sec":"الخبر في هذه القصة وسبب منافرة عامر وعلقمة وخبر الأعشى وعلقمة وغيره","page":"ج16 ص303","text":"معهما فيها أخبرني بذلك محمد بن الحسين بن دريد إجازة عن أبي حاتم عن أبي عبيدة ونسخت من روايات ابن الكلبي عن أبيه ومن رواية دماذ والأثرم عن أبي عبيدة والأصمعي ومن رواية ابن حبيب عن ابن الأعرابي عن المفضل ومن رواية أبي عمرو الشيباني عن أصحابه فجمعت رواياتهم ولكل امرىء منهم زيادة على صاحبه ونقصان عنه واللفظ مشترك في الروايات إلا ما حكيته مفردا قال ابن الكلبي حدثني أبي ومحرز بن جعفر وجعفر بن كلاب الجعفري عن بشر بن عبد الله بن حبان بن سلمى بن مالك بن جعفر عن أبيه عن أشياخه وذكر بعضه أبو مسكين قالوا","topic":"ذكر أم حكيم وأخبارها","topicNo":208,"sp":3,"spl":"كأس أم حكيم — الخبر في هذه القصة وسبب منافرة عامر وعلقمة وخبر الأعشى وعلقمة وغيره"},
{"id":"b208-7","bab":"الجزء 16","sec":"سبب المنافرة بين عامر وعلقمة","page":"ج16 ص304","text":"أول ما هاج النفار بين عامر بن الطفيل بن مالك بن جعفر وبين علقمة بن علاثة بن عوف بن الأحوص وأم عامر كبشة بنت عروة الرحال بن عتبة بن جعفر وأمها أم الظباء بنت معاوية فارس الهرار ابن عبادة بن عقيل بن كعب بن ربيعة وأمها خالدة بنت جعفر بن كلاب وأمها فاطمة بنت عبد شمس بن عبد مناف وأم\nأبيه الطفيل أم البنين بنت ربيعة بن عمرو بن عامر بن صعصعة قال أبو الحسن الأثرم وكانت أم علقمة ليلى بنت أبي سفيان بن هلال بن النخع سبية وأم أبيه ماوية بنت عبد الله بن الشيطان بن بكر بن عوف بن النخع مهيرة أن علقمة كان قاعدا ذات يوم يبول فبصر به عامر فقال لم أر كاليوم عورة رجل أقبح فقال علقمة أما والله ما تثب على جاراتها ولا تنازل كناتها يعرض بعامر فقال عامر وما أنت والقروم والله لفرس أبي حنوة أذكر من أبيك ولفحل أبي غيهب أعظم ذكرا منك في نجد قال وكان فرسه فرسا جوادا نجا عليه يوم بني مرة بن عوف بن سعد بن ذبيان وكان فحله فحلا لبني حرملة بن الأشعر بن صرمة بن مرة بن عوف بن سعد بن ذبيان قال الأثرم وأخبرني رجل من جهينة بدمشق قال هو الأشعر بن صرمة قال الأثرم سمي صرمة غيهب لسواده قال ابن الكلبي فاستعاره منهم يستطرقه فغلبهم عليه فقال علقمة أما فرسكم فعارة وأما فحلكم فغدرة ولكن إن شئت نافرتك فقال قد شئت\nفقال عامر والله أنا أكرم منك حسبا وأثبت منك نسبا وأطول منك قصبا فقال علقمة لأنا خير منك ليلا ونهارا فقال عامر لأنا أحب إلى نسائك أن أصبح فيهن منك فقال علقمة على ماذا تنافرني يا عامر فقال عامر أنافرك على أني أنحر منك للقاح وخير منك في الصباح وأطعم منك في السنة الشياح فقال علقمة أنت رجل تقاتل والناس يزعمون أني جبان ولأن تلقى العدو وأنا أمامك أعز لك من أن تلقاهم وأنا خلفك وأنت جواد والناس يزعمون أني بخيل ولست كذلك ولكن أنافرك أني خير منك أثرا وأحد منك بصرا وأعز منك نفرا وأسرح منك ذكرا فقال عامر ليس لبني الأحوص فضل على بني مالك في العدد وبصري ناقص وبصرك صحيح ولكني أنافرك على أني أنشر منك أمة وأطول منك قمة وأحسن منك لمة وأجعد منك جمة وأبعد منك همة\nقال علقمة أنت رجل جسيم وأنا رجل قضيف وأنت جميل وأنا قبيح ولكني أنافرك بآبائي وأعمامي فقال عامر آباؤك أعمامي ولم أكن لأنافرك بهم ولكني أنافرك أني خير منك عقبا وأطعم منك جدبا قال علقمة قد علمت أن لك عقبا في العشيرة وقد أطعمت طيبا إذ سارت ولكني أنافرك أني خير منك وأولى بالخيرات منك وقد أكثرنا المراجعة منذ اليوم قال فخرجت أم عامر وكانت تسمع كلامهما فقالت يا عامر نافره أيكما أولى بالخيرات قال أبو المنذر قال أبو مسكين قال عامر في مراجعته والله لأنا أركب منك في الحماة وأقتل منك للكماة وخير منك للمولى والمولاة فقال له علقمة والله إني أعز منك إني لبر وإنك لفاجر وإني لوفي وإنك لغادر ففيم تفاخرني يا عامر فقال عامر والله إني لأنزل منك للقفرة وأنحر منك للبكرة وأطعم منك للهبرة وأطعن منك للثغرة فقال علقمة والله إنك لكليل البصر نكد النظر وثاب على جاراتك بالسحر فقال بنو خالد بن جعفر وكانوا يدا مع بني الأحوص على بني مالك بن\nجعفر لن تطيق عامرا ولكن قل له أنافرك بخيرنا وأقربنا إلى الخيرات وخذ عليه بالكبر فقال له علقمة هذا القول فقال عامر عنز وتيس وتيس وعنز فذهبت مثلا نعم على مئة من الإبل إلى مئة من الإبل يعطاها الحكم أينا نفر عليه صاحبه أخرجها ففعلوا ذلك ووضعوا بها رهنا من أبنائهم على يدي رجل من بني الوحيد فسمي الضمين إلى الساعة وهو الكفيل قال وخرج علقمة ومن معه من بني خالد وخرج عامر فيمن معه من بني مالك وقد أتى عامر بن الطفيل عمه عامر بن مالك وهو أبو براء فقال يا عماه أعني فقال يابن أخي سبني فقال لا أسبك وأنت عمي قال فسب الأحوص فقال عامر ولا أسب والله الأحوص وهو عمي فقال فكيف إذن أعينك ولكن دونك نعلي فإني قد ربعت فيها أربعين مرباعا فاستعن بها في نفارك وجعلا منافرتهما إلى أبي سفيان بن حرب بن أمية فلم يقل بينهما شيئا وكره ذلك لحالهما وحال عشيرتهما وقال أنتما كركبتي البعير الأدرم تقعان بالأرض قالا فأينا اليمين فقال كلاكما اليمين وأبى أن يقضي بينهما فانطلقا إلى أبي جهل بن هشام فأبى أن يحكم بينهما فوثب مروان بن سراقة ابن قتادة بن عمرو بن الأحوص بن جعفر فقال","topic":"ذكر أم حكيم وأخبارها","topicNo":208,"sp":4,"spl":"سبب المنافرة بين عامر وعلقمة"},
{"id":"b208-8","bab":"الجزء 16","sec":"سبب المنافرة بين عامر وعلقمة","page":"ج16 ص304","text":"(يال قريش بينوا الكلاما ... إنا رضينا منكم الأحكاما)\n(فبينوا إن كنتم حكاما ... كان أبونا لهم إماما)\n(وعبد عمرو منع الفئاما ... في يوم فخر معلم إعلاما)\n(ودعلج أقدمه إقداما ... لولا الذي أجشمهم إجشاما)\n(لا تخذتهم مذحج نعاما ... )\nال فأبوا أن يقولوا بينهما شيئا وقد كانت العرب تحاكم إلى قريش فأتيا عيينة بن حصن بن حذيفة فأبى أن يقول بينهما شيئا فأتيا غيلان بن سلمة بن معتب الثقفي فردهما إلى حرملة بن الأشعر المري فردهما إلى هرم بن قطبة بن سنان بن عمرو الفزاري فانطلقا حتى نزلا به","topic":"ذكر أم حكيم وأخبارها","topicNo":208,"sp":5,"spl":"سبب المنافرة بين عامر وعلقمة","partial":1},
{"id":"b208-9","bab":"الجزء 16","sec":"هرم بن قطبة يحكم بينهما","page":"ج16 ص309","text":"وقال بشر بن عبد الله بن حبان بن سلمى إنهما ساقا الإبل معهما حتى أشتت وأربعت لا يأتيان أحدا إلا هاب أن يقضي بينهما فقال هرم لعمري لأحكمن بينكما ثم لأفصلن ثم لست أثق بواحد منكما فأعطياني موثقا\nأطمئن إليه أن ترضيا بما أقول وتسلما لما قضيت بينكما وأمرهما بالانصراف ووعدهما ذلك اليوم من قابل فانصرفا حتى إذا بلغ الأجل من قابل خرجا إليه فخرج علقمة ببني الأحوص فلم يتخلف منهم أحد معهم القباب والجزر والقدور ينحرون في كل منزل ويطعمون وجمع عامر بني مالك فقال إنما تخاطرون عن أحسابكم فأجابوه وساروا معه ولم ينهض أبو براء معهم وقال لعامر والله لا تطلع ثنية إلا وجدت الأحوص منيخا بها وكره أبو براء ما كان من أمرهما فقال عامر فيما كره من منافرتهما ودعاء عامر إياه أن يسير معه\n(أأومر أن أسب أبا شريح ... ولا والله أفعل ما حييت)\n(ولا أهدي إلى هرم لقاحا ... فيحيي بعد ذلك أو يميت)\n(أكلف سعي لقمان بن عاد ... فيال أبي شريح ما لقيت)\nال وأبو شريح هو الأحوص فكره كل واحد من البطنين ما كان بينهما وقال عبد عمرو بن شريح بن الأحوص\n(لحى الله وفدينا وما ارتحلا به ... من السوءة الباقي عليهم وبالها)\n(ألا إنما بردي صفاق متينة ... أبى الضيم أعلاها وأثبت حالها)\nفقال فسار عامر وبنو عامر على الخيل مجنبي الإبل وعليهم السلاح قال رجل من غني يا عامر ما صنعت أخرجت بني مالك تنافر بني الأحوص\nومعهم القباب والجزر وليس معك شيء تطعمه الناس ما أسوأ ما صنعت فقال عامر لرجلين من بني عمه أحصيا كل شيء مع علقمة من قبة أو قدر أو لقحة ففعلا فقال عامر يا بني مالك إنها المقارعة عن أحسابكم فاشخصوا بمثل ما شخصوا به ففعلوا وثار مع عامر لبيد بن ربيعة والأعشى ومع علقمة الحطيئة وفتيان من بني الأحوص منهم السندري بن يزيد بن شريح ومروان بن سراقة بن قتادة بن عمرو بن الأحوص وهم يرتجزون فقال لبيد\n(يا هرما وأنت أهل عدل ... إن نفر الأحوص يوما قبلي)\n(ليذهبن أهله بأهلي ... لا تجمعن شكلهم وشكلي)\n(ونسل آبائهم ونسلي ... )\nقال أيضا\n(إني امرؤ من مالك بن جعفر ... علقم قد نافرت غير منفر)\n(نافرت سقبا من سقاب العرعر ... )\nقال قحافة بن عوف بن الأحوص\n(نهنه إليك الشعر يا لبيد ... واصدد فقد ينفعك الصدود)\n(ساد أبونا قبل أن تسودوا ... سؤددكم مطرف زهيد)\nوقال أيضا\n(إني إذا ما نسي الحياء ... وضاع يوم المشهد اللواء)\n(أنمى وقد حق لي النماء ... إلى ذكور ذكرها سناء)\n(إذ لا تزال جلدة كوماء ... مبقورة لسقبها دعاء)\n(لم ينهنا عن نحرها الصفاء ... لنا عليكم سورة ولاء)\n(المجد والسؤدد والعطاء ... )\nقال أيضا\n(أنتم هزلتم عامر بن مالك ... في شتوات مضر الهوالك)\n(يا شر أحياء وشر هالك ... )\nال وأنشدها السندري يومئذ ورفع صوته فقيل من هذا فقال\n(أنا لمن أنكر صوتي السندري ... أنا الفتى الجعد الطويل الجعفري)\n(من ولد الأحوص أخوالي غني ... )\nفقال عامر أجب يا لبيد فرغب لبيد عن إجابته وذلك لأن السندري كانت جدته أمة اسمها عيساء فقال\n(لما دعاني عامر لأسبهم ... أبيت وإن كان ابن عيساء ظالما)\n(لكيما يكون السندري نديدتي ... وأشتم أعماما عموما عماعما)\n(وأنشر من تحت القبور أبوة ... كراما هم شدوا علي التمائما)\n(لعبت على أكتافهم وحجورهم ... وليدا وسموني مفيدا وعاصما)\n(ألا أينا ما كان شرا لمالك ... فلا زال في الدنيا ملوما ولائما)\nال ووثب الحطيئة فقال\n(ما يحبس الحكام بالفصل بعدما ... بدا سابق ذو غرة وحجول)\nقال أيضا\n(يا عام قد كنت ذا باع ومكرمة ... لو أن مسعاة من جاريته أمم)\n(جاريت قرما أجاد الأحوصان به ... سمح اليدين وفي عرنينه شمم)\n(لا يصعب الأمر إلا ريث يركبه ... ولا يبيت على مال له قسم)\n(هابت بنو مالك مجدا ومكرمة ... وغاية كان فيها الموت لو قدموا)\n(وما أساؤوا فرارا عن مجلحة ... لا كاهن يمتري فيها ولا حكم)","topic":"ذكر أم حكيم وأخبارها","topicNo":208,"sp":6,"spl":"هرم بن قطبة يحكم بينهما","partial":1},
{"id":"b208-10","bab":"الجزء 16","sec":"دهاء هرم بن قطبة وذكاؤه","page":"ج16 ص313","text":"قال وأقام القوم عنده أياما وأرسل إلى عامر فأتاه سرا لا يعلم به علقمة فقال يا عامر قد كنت أرى لك رأيا وأن فيك خيرا وما حبستك هذه الأيام إلا لتنصرف عن صاحبك أتنافر رجلا لا تفخر أنت وقومك إلا بآبائه فما الذي أنت به خير منه قال عامر أنشدك الله والرحم أن لا تفضل علي علقمة فوالله لئن فعلت لا أفلح بعدها أبدا هذه ناصيتي فاجززها واحتكم في مالي فإن كنت لا بد فاعلا فسو بيني وبينه قال انصرف فسوف أرى رأيي فخرج عامر وهو لا يشك أنه ينفره عليه\nثم أرسل إلى علقمة سرا لا يعلم به عامر فأتاه فقال يا علقمة والله إن كنت لأحسب فيك خيرا وأن لك رأيا وما حسبتك هذه الأيام إلا لتنصرف عن صاحبك أتفاخر رجلا هو ابن عمك في النسب وأبوه أبوك وهو مع هذا أعظم قومك غناء وأحمدهم لقاء فما الذي أنت به خير منه عشرا علقمة أنشدك الله والرحم ألا تنفر علي عامرا اجزز ناصيتي واحتكم في مالي وإن كنت لا بد أن تفعل فسو بيني وبينه فقال انصرف فسوف أرى رأيي فخرج وهو لا يشك أنه سيفضل عليه عامرا قال أبي وسمعت أن هرما قال لعامر حين دعاه يا عامر كيف تفاضل علقمة فقال عامر ولم يا هرم قال لأنه أنجل منك عينا في النساء وأكثر منك نفيرا عند ثورة الدعاء قال عامر هل غير هذا قال نعم هو أكثر منك نائلا في الثراء وأعظم منك حقيقة عند الدعاء ثم قال لعلقمة كيف تفاضل عامرا قال ولم يا هرم قال هو أنفذ منك لسانا وأمضى منك سنانا قال علقمة فهل غير هذا قال نعم هو أقتل منك للكماة وأفك منك للعناة قال ثم إن هرما أرسل إلى بنيه وبني أبيه إني قائل غدا بين هذين الرجلين مقالة فإذا فعلت فليطرد بعضكم عشر جزائر فلينحرها عن علقمة ويطرد بعضكم عشر جزائر فلينحرها عن عامر وفرقوا بين الناس لا تكون لهم جماعة وأصبح هرم فجلس مجلسه وأقبل الناس وأقبل علقمة وعامر حتى جلسا فقام لبيد فقال\n(يا هرم ابن الأكرمين منصبا ... إنك قد وليت حكما معجبا)\n(فاحكم وصوب رأس من تصوبا ... إن الذي يعلو علينا ترتبا)\n(لخيرنا عما وأما وأبا ... وعامر خيرهما مركبا)\n(وعامر أدنى لقيس نسبا ... )\nقام هرم فقال يا بني جعفر قد تحاكمتما عندي وأنتما كركبتي البعير الأدرم تقعان إلى الأرض معا وليس فيكما أحد إلا وفيه ما ليس في صاحبه وكلاكما سيد كريم وعمد بنو هرم وبنو أخيه إلى تلك الجزر فنحروها حيث أمرهم هرم عن علقمة عشرا وعن عامر عشرا وفرقوا الناس فلم يفضل هرم واحدا منهما على صاحبه وكره أن يفعل وهما ابنا عم فيجلب عداوة ويوقع بين الحيين شرا قال وكان الأعشى حين رجع من عند قيس بن معد يكرب بما أعطاه طلب الجوار والخفرة من علقمة فلم يكن عنده ما طلب وأجاره وخفره عامر حتى إذا أداه وماله إلى أهله قال\n(علقم ما أنت إلى عامر ... الناقض الأوتار والواتر)\nثم أتمها بعد النفار فلما بلغ علقمة ما قال الأعشى وأشاع في العرب أن هرما قد فضل عامرا توعد الأعشى فقال الأعشى\n(لعمري لئن أمسي من الحي شاخصا ... )\nال ابن الكلبي حدثني أبي قال فعاش هرم حتى ادرك سلطان عمر بن الخطاب رضي الله عنه فسأله عمر فقال يا هرم أي الرجلين كنت مفضلا لو فضلت فقال لو قلت ذاك يا أمير المؤمنين لعادت جذعة ولبلغت شعاف هجر فقال عمر نعم مستودع السر ومسند الأمر إليه أنت يا هرم مثل هذا\nفليسد العشيرة وقال إلى مثلك فليستبضع القوم أحكامهم","topic":"ذكر أم حكيم وأخبارها","topicNo":208,"sp":7,"spl":"دهاء هرم بن قطبة وذكاؤه","partial":1},
{"id":"b208-11","bab":"الجزء 16","sec":"إسلام علقمة","page":"ج16 ص316","text":"قال مؤلف الكتاب وقد أدرك علقمة بن علاثة الإسلام فأسلم ثم ارتد فيمن ارتد من العرب فلما وجه أبو بكر خالد بن الوليد المخزومي إلى بني كلاب ليوقع بهم وعلقمة يومئذ رئيسهم هرب وأسلم ثم أتى أبا بكر رضي الله عنه فأعلمه أنه قد نزع عما كان عليه فقبل إسلامه وأمنه هكذا ذكر المدائني وأما سيف بن عمر فإنه روى عن الكوفيين غير ذلك حدثنا محمد بن جرير الطبري قال حدثنا السري بن يحيى قال حدثنا شعيب بن إبراهيم عن سيف بن عمر عن سهل بن يوسف قال كان علقمة بن علاثة على كلاب ومن لافها وقد كان علقمة أسلم ثم ارتد في حياة النبي ثم خرج بعد فتح الطائف حتى لحق بالشام مرتدا فلما توفي النبي أقبل مسرعا حتى عسكر في بني كعب مقدما رجلا ومؤخرا أخرى وبلغ ذلك أبا بكر رضي الله عنه فبعث إليه سرية وأمر عليها القعقاع بن عمرو وقال يا قعقاع سر حتى تغير على علقمة بن علاثة لعلك تأخذه لي أو تقتله واعلم أن شفاء النفس الحوص فاصنع ما عندك فخرج في تلك السرية حتى أغار على الماء الذي عليه علقمة وكان لا يبرح أن\nيكون على رحل فسابقهم على فرسه مراكضة وأسلم أهله وولده واستبى القعقاع امرأة علقمة وبناته ونساءه ومن أقام من الرجال فاتقوه بالإسلام فقدم بهم على أبي بكر رضي الله عنه فجحدت زوجته وولده أن يكونوا مالؤوا علقمة على أمره وكانوا مقيمين في الدار ولم يكن بلغه عنهم غير ذلك وقالوا لأبي بكر ما ذنبنا نحن فيما صنع علقمة فأرسلهم ثم أسلم علقمة فقبل ذلك منه أخبرنا الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثنا عمرو بن عثمان قال كان رسول الله ربما حدث أصحابه وربما تركهم يتحدثون ويصغي إليهم ويتبسم فبينا هم يوما على ذلك يتذاكرون الشعر وأيام العرب إذ سمع حسان بن ثابت ينشد هجاء أعشى بن قيس بن ثعلبة علقمة بن علاثة ومديحه عامر بن الطفيل\n(علقم ما أنت إلى عامر ... الناقض الأوتار والواتر)\n(إن تسد الحوص فلم تعدهم ... وعامر ساد بني عامر)\n(ساد وألفى رهطه سادة ... وكابرا سادوك عن كابر)\nقال رسول الله كف عن ذكره يا حسان فإن أبا سفيان لما شعث مني عند هرقل رد عليه علقمة فقال حسان بن ثابت بأبي أنت وأمي يا رسول الله من نالتك يده فقد وجب علينا شكره","topic":"ذكر أم حكيم وأخبارها","topicNo":208,"sp":8,"spl":"إسلام علقمة"},
{"id":"b208-12","bab":"الجزء 16","sec":"علقمة يموت قبل وصول الحطيئة إليه","page":"ج16 ص317","text":"أخبرني الحسن بن علي قال حدثنا أحمد بن الحارث الخراز قال حدثنا المدائني عن أبي بكر الهذلي قال لما أطلق عمر بن الخطاب رضي الله عنه الحطيئة من حبسه قال له\nيا أمير المؤمنين اكتب لي كتابا إلى علقمة بن علاثة لأقصده به فقد منعتني التكسب بشعري فقال لا أفعل فقيل له يا أمير المؤمنين وما عليك من ذلك إن علقمة ليس بعاملك فتخشى أن تأثم وإنما هو رجل من المسلمين تشفع له إليه فكتب له بما أراد فمضى الحطيئة بالكتاب فصادف علقمة قد مات والناس منصرفون عن قبره فوقف عليه ثم أنشد قوله\n(لعمري لنعم المرء من آل جعفر ... بحوران أمسى أعلقته الحبائل)\n(فإن تحي لا أملل حياتي وإن تمت ... فما في حياة بعد موتك طائل)\n(وما كان بيني لو لقيتك سالما ... وبين الغنى إلا ليال قلائل)\nقال له ابنه يا حطيئة كم ظننت أن علقمة يعطيك قال مئة ناقة قال فلك مئة ناقة يتبعها مئة من أولادها فأعطاه إياها أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عمر بن أبي بكر قال حدثنا عبد الرحمن بن أبي الزناد والضحاك بن عثمان قالا لما قدم علقمة بن علاثة المدينة وكان قد ارتد عن الإسلام وكان لخالد بن الوليد صديقا لقيه عمر بن الخطاب رضي الله عنه في المسجد في جوف الليل وكان عمر يشبه بخالد وذلك أن أمه حنتمة بنت هاشم بن المغيرة بن عبد الله بن عمر بن مخزوم فسلم عليه وظن أنه خالد فقال أعزلك قال كان ذلك قال والله ما هو إلا نفاسة عليك وحسد لك\nفقال له عمر فما عندك معونة على ذلك قال معاذ الله إن لعمر علينا سمعا وطاعة وما نخرج إلى خلافه فلما أصبح عمر رضي الله عنه أذن للناس فدخل خالد وعلقمة فجلس علقمة إلى جنب خالد فالتفت عمر إلى علقمة فقال إيه يا علقمة أأنت القائل لخالد ما قلت فالتفت علقمة إلى خالد فقال يا أبا سليمان أفعلتها قال ويحك والله ما لقيتك قبل ما ترى وإني لأراك لقيت الرجل قال أراه والله ثم التفت إلى عمر فقال يا أمير المؤمنين ما سمعت إلا خيرا قال أجل فهل لك أن أوليك حوران قال نعم فولاه إياها فمات بها فقال الحطيئة يرثيه\n(لعمري لنعم الحي من آل جعفر ... بحوران أمسى أقصدته الحبائل)\n(لقد أقصدت جودا ومجدا وسؤددا ... وحلما أصيلا خالفته المجاهل)\n(فإن تحي لا أملل حياتي وإن تمت ... فما في حياة بعد موتك طائل)\nفي أول هذه القصيدة التي رثى بها الحطيئة علقمة غناء نسبته\n(أرى العيس تخدي بين قو فضارج ... كما لاح في الصبح الأشاء الحوامل)\n(فأتبعتهم عيني حتى تفرقت ... مع الليل عن ساق الفريد الجمائل)\n(فلأيا قصرت الطرف عنهم بجسرة ... أمون إذا واكلتها لا تواكل)\nغنى في هذه الأبيات سائب خاثر ثاني - ثقيل - بالوسطى من رواية حماد بن إسحاق والهشامي\n(ليت شعري أفاح رائحة المسك ... وما إن إخال بالخيف إنسي)\n(حين غابت بنو أمية عنه ... والبهاليل من بني عبد شمس)\n(خطباء على المنابر فرسان ... عليها وقالة غير خرس)\nخال أظن خلت كذا وكذا فأنا إخاله إذا ظننته وخال علي الشيء يخيل إذا شككت فيه وليت شعري كلمة تقولها العرب عند الشيء تحب علمه وتسأل عنه وأخبرني حبيب بن نصر المهلبي قال حدثني عمر بن شبة قال سأل رجل أبا عبيدة ما أصل ليت شعري فقال كأنه قال ليتني شعرت بكذا وكذا ليتني علمت حقيقته الشعر لأبي العباس الأعمى والغناء لابن سريج - رمل - بالبنصر في مجراها","topic":"ذكر أم حكيم وأخبارها","topicNo":208,"sp":9,"spl":"علقمة يموت قبل وصول الحطيئة إليه","song":2},
{"id":"b208-13","bab":"الجزء 16","sec":"أخبار أبي العباس الأعمى","page":"ج16 ص321","text":"هو السائب بن فروخ مولى بني ليث وقيل إنه مولى بني الديل وهذا القول هو الصحيح ذكر محمد بن معاوية الأسدي عن المدائني والواقدي أن أبا العباس الأعمى الذي يروي عنه حبيب بن أبي ثابت مولى جذيمة بن علي بن الديل بن بكر بن عبد مناة وكان من شعراء بني أمية المعدودين المقدمين في مدحهم والتشيع لهم وانصباب الهوى إليهم وهو الذي يقول في أبي الطفيل عامر بن واثلة صاحب علي بن أبي طالب عليه السلام\n(لعمرك إنني وأبا طفيل ... لمختلفان والله الشهيد)\n(أرى عثمان مهتديا ويأبى ... متابعتي وآبى ما يريد)\nخبرني بذلك وكيع عن حماد بن إسحاق عن أبيه عن أبيه عن عبد الله بن أبي سعد وقد روى أبو العباس الأعمى عن صدر من الصحابة الحديث وروى عنه عطاء وعمرو بن دينار وحبيب بن أبي ثابت أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال\nحدثنا أبو عاصم عن ابن جريج عن عطاء عن أبي العباس الأعمى الشاعر عن عبد الله بن عمر قال إنما جمع منزل تدلج منه إذا شئت قال حدثنا أحمد بن محمد بن دلان الخيشي قال حدثنا أحمد بن إسماعيل قال حدثنا أبو ضمرة قال حدثني أبو الحارث بن عبد الرحمن عن أبي ذئب عن أبي العباس عن سعيد بن المسيب قال قال علي بن أبي طالب قال رسول الله إسباغ الوضوء على المكاره وإعمال الأقدام إلى المساجد وانتظار الصلاة بعد الصلاة يغسل الخطايا غسلا حدثني أحمد بن محمد بن سعيد الكوفي قال حدثنا أبو قلابة قال حدثنا بشر بن عمر قال حدثنا شعبة عن حبيب بن أبي ثابت قال سمعت أبا العباس السائب بن فروخ الأعمى الشاعر يحدث عن عبد الله بن عمر قال جاء رجل إلى النبي يستأذنه في الجهاد فقال أحي والداك قال نعم قال فيهما فجاهد أخبرني أحمد بن عبيد الله بن عمار قال حدثني يعقوب بن إسرائيل مولى المنصور قال حدثنا الفضل بن عبد الله الخلنجي بجرجان قال حدثني مسلم بن الوليد الأنصاري قال سمعت يزيد بن مزيد يقول سمعت هارون\nالرشيد يقول سمعت المهدي يقول سمعت المنصور يقول خرجت أريد الشأم أيام مروان بن محمد فصحبني في الطريق رجل ضرير فسألته عن مقصده فأخبرني أنه يريد مروان بشعر امتدحه به فاستنشدته إياه فأنشدني\n(ليت شعري أفاح رائحة المسك ... وما إن إخال بالخيف إنسي)\n(حين غابت بنو أمية عنه ... والبهاليل من بني عبد شمس)\n(خطباء على المنابر فرسان ... عليها وقالة غير خرس)\n(لا يعابون صامتين وإن قالوا ... أصابوا ولم يقولوا بلبس)\n(بحلوم إذا الحلوم تقضت ... ووجوه مثل الدنانير ملس)\nيروى مكان تقضت اضمحلت قال فوالله ما فرغ من إنشاده حتى توهمت أن العمى قد أدركني وافترقنا فلما أفضت الخلافة إلي خرجت حاجا فنزلت أمشي بجبلي زرود فبصرت بالضرير ففرقت من كان معي ثم\nدنوت منه فقلت أتعرفني قال لا فقلت أنا رفيقك وأنت تريد الشام أيام مروان فقال أوه\n(آمت نساء بني أمية منهم ... وبناتهم بمضيعة أيتام)\n(نامت جدودهم وأسقط نجمهم ... والنجم يسقط والجدود تنام)\n(خلت المنابر والأسرة منهم ... فعليهم حتى الممات سلام)\nقلت وكم كان مروان أعطاك بأبي أنت قال أغناني أن أسأل أحدا بعده فهممت بقتله ثم ذكرت حق الاسترسال والصحبة فأمسكت عنه وغاب عن عيني فبدا لي فيه فأمرت بطلبه فكأنما البيداء بادت به أخبرني أحمد بن عبد العزيز الجوهري قال حدثني عمر بن شبة قال قال أبو عبيدة هوي أبو العباس الأعمى امرأة ذات بعل فراسلها فأعلمت زوجها فقال أطمعيه فأطمعته ثم قال أرسلي إليه فليأتك فأرسلت إليه فأتاها وجلس زوجها إلى جانبها فقال لها أبو العباس إنك قد وصفت لنا وما نراك فألمسينا فأخذت يده فوضعتها على أيرها فنفر وعلم أن قد كيد فنهض من عندها وقال\n(علي ألية ما دمت حيا ... أمسك طائعا إلا بعود)\n(ولا أهدي لأرض أنت فيها ... سلام الله إلا من بعيد)\n(رجوت غنيمة فوضعت كفي ... على أير أشد من الحديد)\n(فخير منك من لا خير فيه ... وخير من زيارتكم قعودي)\nقرأت هذه الحكاية مروية عن الأصمعي غير مذكور راويها عنه وزعم أن بشارا صاحب القصة وأنه كان له مجلس يسميه البردان يجتمع إليه فيه\nالنساء فعشق هذه المرأة وقد سمع كلامها ثم ذكر الخبر بطوله وقال فيه فلما وصل إليها أنشأ يقول\n(مليكة قد وصفت لنا بحسن ... وإنا لا نراك فألمسينا)","topic":"ذكر أم حكيم وأخبارها","topicNo":208,"sp":10,"spl":"أخبار أبي العباس الأعمى","song":1},
{"id":"b208-14","bab":"الجزء 16","sec":"أخبار أبي العباس الأعمى","page":"ج16 ص321","text":"أخذ زوجها يده فوضعها على أيره ذكر إسحاق أن في البيتين الأولين والرابع من هذه الأبيات لحنا من خفيف الثقيل بالسبابة في مجرى الوسطى ولم ينسبه إلى أحد ووجدته في غناء عمرو بن بانة في هذه الطريقة منسوبا إليه فلا أدري هو ذلك اللحن أو غيره أخبرنا أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثني أيوب بن عمر أبو سلمة قال قال أبو العباس الأعمى مولى بني الديل بن بكر يحض بني أمية على عبد الله بن الزبير\n(أبني أمية لا أرى لكم ... شبها إذا ما التفت الشيع)\n(سعة وأحلاما إذا نزعت ... أهل الحلوم فضرها النزع)\n(وحفيظة في كل نائبة ... شهباء لا ينهى لها الربع)\n(الله أعطاكم وإن رغمت ... من ذاك أنف معاشر رتعوا)\n(أبني أمية غير أنكم ... والناس فيما أطمعوا طمعوا)\n(أطمعتم فيكم عدوكم ... فسما بهم في ذاكم الطمع)\n(فلو انكم كنتم لقولكم ... مثل الذي كانوا لكم رجعوا)\n(عما كرهتم أو لردهم ... حذر العقوبة إنها تزع)\nوله أشعار كثيرة في مدائح بني أمية وهجاء آل الزبير وأكثرها في هجاء عمرو بن الزبير ليس ذكرها مما قصدنا له","topic":"ذكر أم حكيم وأخبارها","topicNo":208,"sp":11,"spl":"أخبار أبي العباس الأعمى"},
{"id":"b208-15","bab":"الجزء 16","sec":"أبو العباس يهجو ابن الزبير والمجاشعي","page":"ج16 ص326","text":"ونسخت من كتاب قعنب بن المحرز قال حدثنا المدائني عن جويرية بن أسماء أن ابن الزبير رأى رجلا من حلفاء بني أسد بن عبد العزى في حالة رثة فكساه ثوبين وأمر له ببر وتمر فقال أبو العباس الأعمى في ذلك\n(كست أسد إخوانها ولو انني ... ببلدة إخواني إذا لكسيت)\n(فلم تر عيني مثل حي تحملوا ... إلى الشأم مظلومين منذ بريت)\nنى في هذين البيتين دحمان - ثقيل - أول بالبنصر من رواية ابن المكي ورأيت في بعض الكتب لزرزور غلام المارقي فيهما صنعة أيضا وقال محمد بن معاوية حدثني المدائني قال قدم البعيث المجاشعي مكة وكان أبو العباس الأعمى الشاعر لا يكاد\nيفارقها وكانت جوائز أمية تأتيه من الشام وكانت قريش كلها تبره للسانه وتقربا إلى بني أمية ببره قال فصلى البعيث مع الناس وسأل في حمالة كانت عليه وكان سؤولا ملحا شديد الطمع وكان الرجل من قريش يأتيه بالشيء يتحمله عنه فيقول لا أقبله إلا أن تجيء معي إلى الصراف حتى ينقده ويزنه فإن لم يفعل ذمه وهجاه فشكوه إلى أبي العباس الأعمى فقال قودوني إليه ففعلوا فلما عرف مجلسه رفع عصاه فضرب بها رأسه ثم قال له\n(فهل أنت إلا ملصق في مجاشع ... نفاك جرير فاضطررت إلى نجد)\n(نفاك جرير بالهجاء إلى نجد ... )\nيروى\n(تظل إذا أعطيت شيئا سألته ... تطالب من أعطاك بالوزن والنقد)\n(فلا تطمعن من بعد ذا في عطية ... وثق بقبيح المنع والدفع والرد)\n(فلست بمبق في قريش خزاية ... تذم ولو أبعدت فيه مدى الجهد)\nال فتضاحك به من حضر واستحيا ولم يحر جوابا فلما جن الليل عليه هرب من مكة وقال قعنب بن المحرز حدثني المدائني قال قال عبد الملك بن مروان لأبي العباس الأعمى مولى بني الديل أنشدني مديحك مصعبا فاستعفاه فقال يا أمير المؤمنين إنما رثيته بذلك لأنه كان صديقي وقد علمت أن هواي أموي قال صدقت ولكن أنشدني ما قلته فأنشده\n(يرحم الله مصعبا فلقد مات ... كريما ورام أمرا جسيما)\nقال عبد الملك أجل لقد مات كريما ثم تمثل\n(ولكنه رام التي لا يرومها ... من الناس إلا كل خرق معمم)\nخبرنا محمد بن خلف بن المرزبان قال حدثني إسحاق بن محمد الأموي قال لما حج عبد الملك بن مروان جلس للناس بمكة فدخلوا إليه على مراتبهم وقامت الشعراء والخطباء فتكلموا ودخل أبو العباس الأعمى فلما رآه عبد الملك قال مرحبا بك يا أبا العباس أخبرني بخبر الملحد المحل حيث كسا أشياعه ولم يكسك وأنشدني ما قلت في ذلك فأخبره بخبر ابن الزبير وأنه كسا بني أسد وأحلافها ولم يكسه وأنشده الأبيات فقال عبد الملك أقسم على كل من حضرني من بني أمية وأحلافهم ومواليهم ثم على كل من حضرني من أوليائي وشيعتي على دعوتهم إلا كسا أبا العباس فخلعت والله حلل الوشي والخز والقوهي وجعلت ترمى عليه حتى إذا غطته نهض فجلس فوق ما اجتمع منها وطرح عليه قال حتى رأيت في الدار من الثياب ما ستر عني عبد الملك وجلساءه وأمر له عبد الملك بمئة ألف درهم\nأخبرني أحمد بن عبيد الله بن عمار قال حدثني علي بن محمد بن سليمان النوفلي قال حدثني أبي وأهلي أن عبد الله بن الزبير لما غلب على الحجاز جعل يتتبع شيعة بني مروان فينفيهم عن المدينة ومكة حتى لم يبق بهما أحد منهم ثم بلغه عن أبي العباس الأعمى الشاعر نبذ من كلام وأنه يكاتب بني مروان بعوراته ويمدح عبد الملك وتجيئه جوائزه وصلاته فدعا به ثم أغلظ له وهم به ثم كلم فيه وقيل له رجل مضرور فعفا عنه ونفاه إلى الطائف فأنشأ يقول يهجوه ويهجو آل الزبير\n(بني أسد لا تذكروا الفخر إنكم ... متى تذكروه تكذبوا وتحمقوا)\n(بعيدات بين خيركم لصديقكم ... وشركم يغدو عليه ويطرق)\n(متى تسألوا فضلا تضنوا وتبخلوا ... ونيرانكم بالشر فيها تحرق)\n(إذا استبقت يوما قريش خرجتم ... بني أسد سكتا وذو المجد يسبق)\n(تجيئون خلف القوم سودا وجوهكم ... إذا ما قريش للأضاميم أصفقوا)\n(وما ذاك إلا أن للؤم طابعا ... يلوح عليكم وسمه ليس يخلق)","topic":"ذكر أم حكيم وأخبارها","topicNo":208,"sp":12,"spl":"أبو العباس يهجو ابن الزبير والمجاشعي","song":1,"partial":1},
{"id":"b208-16","bab":"الجزء 16","sec":"أبو العباس وعمر بن أبي ربيعة","page":"ج16 ص329","text":"أخبرني الحرمي بن أبي العلاء قال حدثني عمي مصعب قال قال عمر بن أبي ربيعة لأبي العباس الأعمى الشاعر مولى بني الديل بن بكر\n(أفتني إن كنت ثقفا شاعرا ... عن فتى أعرج أعمى مختلف)\n(سيىء السحنة كاب لونه ... مثل عود الخروع البالي القصف)\nقال أبو العباس يرد عليه\n(أنت الفتى وابن الفتى وأخو الفتى ... وسيدنا لولا خلائق أربع)\n(نكولك في الهيجا وتقوالك الخنا ... وشتمك للمولى وأنك تبع)\nال الزبير يقال رجل تبع نساء وتبع نساء إذا كان كلفا بهن أخبرني الحرمي قال حدثنا الزبير قال حدثني عمي قال حدثني المكيون أن عمر بن أبي ربيعة كان يرامي جارية لأبي العباس الأعمى ببنادق الغالية فبلغ ذلك أبا العباس فقال لقائده قفني على باب بني مخزوم فإذا مر عمر بن أبي ربيعة فضع يدي عليه فلما مر عمر وضع يده عليه فأخذ بحجزته وقال\n(ألا من يشتري جارا نؤوما ... بجار لا ينام ولا ينيم)\n(ويلبس بالنهار ثياب ناس ... وشطر الليل شيطان رجيم)\nنهضت إليه بنو مخزوم فأمسكوا فمه وضمنوا له عن عمر أن لا يعاود ما يكرهه\n(ألا حي من أجل الحبيب المغانيا ... لبسن البلى لما لبسن اللياليا)\n(إذا ما تقاضى المرء يوم وليلة ... تقاضاه شيء لا يمل التقاضيا)\nلشعر لأبي حية النميري والغناء لأحمد بن يحيى المكي - خفيف رمل - بالبنصر عن الهشامي","topic":"ذكر أم حكيم وأخبارها","topicNo":208,"sp":13,"spl":"أبو العباس وعمر بن أبي ربيعة","song":1},
{"id":"b209-1","bab":"الجزء 16","sec":"أخبار أبي حية النميري ونسبه","page":"ج16 ص330","text":"أبو حية الهيثم بن الربيع بن زرارة بن كثير بن جناب بن كعب بن مالك بن عامر بن نمير بن عامر بن صعصعة بن معاوية بن بكر بن هوازن بن منصور بن عكرمة بن خصفة بن قيس بن عيلان بن مضر بن نزار وكان يقال لمالك الأصقع وقال قوم إن الأصقع هو الأصم بن مالك بن جناب بن كعب وأبو حية شاعر مجيد مقدم من مخضرمي الدولتين الأموية والعباسية وقد مدح الخلفاء فيهما جميعا وكان فصيحا مقصدا راجزا من ساكني البصرة وكان أهوج جبانا بخيلا كذابا معروفا بذلك أجمع وكان أبو عمرو بن العلاء يقدمه وقيل إنه كان يصرع","topic":"أخبار أبي حية النميري ونسبه","topicNo":209,"sp":0,"spl":"أخبار أبي حية النميري ونسبه"},
{"id":"b209-2","bab":"الجزء 16","sec":"طرائف من أخباره","page":"ج16 ص331","text":"أخبرني الحسن بن علي قال حدثنا أحمد بن زهير قال حدثني محمد بن سلام الجمحي وأخبرني علي بن سليمان الأخفش قال حدثنا محمد بن يزيد وأخبرني إبراهيم بن أيوب عن ابن قتيبة قالوا كان لأبي حية سيف يسميه لعاب المنية ليس بينه وبين الخشبة فرق وكان من أجبن الناس قال فحدثني جار له قال دخل ليلة إلى بيته كلب فظنه لصا فأشرفت\nعليه وقد انتضى سيفه لعاب المنية وهو واقف في وسط الدار وهو يقول أيها المغتر بنا والمجترئ علينا بئس والله ما اخترت لنفسك خير قليل وسيف صقيل لعاب المنية الذي سمعت به مشهورة ضربته لا تخاف نبوته اخرج بالعفو عنك قبل أن أدخل بالعقوبة عليك إني والله إن أدع قيسا إليك لا تقم لها وما قيس تملأ والله الفضاء خيلا ورجلا سبحان الله ما أكثرها وأطيبها فبينا هو كذلك إذ خرج الكلب فقال الحمد لله الذي مسخك كلبا وكفاني حربا أخبرني محمد بن خلف وكيع قال حدثني محمد بن علي بن حمزة قال حدثني أبو عثمان المازني قال حدثني سعيد بن مسعدة الأخفش قال قال أبو حية النميري أتدري ما يقول القدريون قلت لا قال يقولون الله لا يكلف العباد ما لا يطيقون ولا يسالهم ما لا يجدون وصدق والله القدريون ولكني لا أقول كما يقولون قال محمد بن علي بن حمزة وحدثني أبو عثمان قال قال سلمة بن عياش لأبي حية النميري أتدري ما يقول الناس قال وما يقولون قال يقولون إني اشعر منك قال إنا لله هلك والله الناس قال وكان أبو حية النميري مجنونا يصرع وقد أدرك هشام بن عبد الملك\nأخبرني محمد بن الحسن بن دريد قال حدثنا عبد الرحمن ابن أخي الأصمعي قال سمعت عمي يقول أبو حية في الشعراء كالرجل الربعة لا يعد طويلا ولا قصيرا قال وسمعت أبا عمرو يقول هو أشعر في عظم الشعر من الراعي أخبرني الحسن بن علي وعلي بن سليمان الأخفش قالا حدثنا محمد بن يزيد المبرد قال حدثني عبد الصمد بن المعذل وأخبرنا إبراهيم بن محمد بن أيوب قال حدثنا عبد الله بن مسلم قالوا كان ابو حية النميري من أكذب الناس فحدث يوما أنه يخرج إلى الصحراء فيدعو الغربان فتقع حوله فيأخذ منها ما شاء فقيل له يا أبا حية ارأيت إن أخرجناك إلى الصحراء فدعوتها فلم تأتك فما نصنع بك قال أبعدها الله إذن قال وحدثنا يوما قال عن لي ظبي يوما فرميته فراغ عن سهمي فعارضه السهم ثم راغ فعارضه السهم فما زال والله يروغ ويعارضه حتى صرعه ببعض الجبانات قال وقال يوما رميت والله ظبية فلما نفذ سهمي عن القوس ذكرت بالظبية حبيبة لي فعدوت خلف السهم حتى قبضت على قذذه قبل أن يدركها وذكر يحيى بن علي عن الحسن بن عليل العنزي قال قال الرياشي عن الأصمعي قال وفد أبو حية النميري على المنصور وقد امتدحه وهجا بني حسن\nبقصيدته التي أولها\n(عوجا نحي ديار الحي بالسند ... وهل بتلك الديار اليوم من أحد)\nقول فيها\n(أحين شيم فلم يترك لهم ترة ... سيف تقلده الرئبال ذو اللبد)\n(سللتموه عليكم يا بني حسن ... ما إن لكم من فلاح آخر الأبد)\n(قد أصبحت لبني العباس صافية ... لجدع آناف أهل البغي والحسد)\n(وأصبحت كلهاة الليث في فمه ... ومن يحاول شيئا في فم الأسد)\nوصله أبو جعفر بشيء دون ما كان يؤمل فاحتجن لعياله أكثره وصار إلى الحيرة فشرب عند خمارة بها فأعجبه الشرب فكره إنفاد ما معه وأحب أن يدوم له ما كان فيه فسأل الخمارة أن تبيعه بنسيئة وأعلمها أنه مدح الخليفة وجماعة من القواد ففعلت وشرهت إلى فضل النسيئة وكان لأبي حية أير كعنق الظليم فأبرز لها عنه فتدلهت وكانت كلما سقته خطت في الحائط فأنشأ أبو حية يقول\n(إذا أسقيتني كوزا بخط ... فخطي ما بدا لك في الجدار)\n(فإن أعطيتني عينا بدين ... فهاتي العين وانتظري ضماري)\n(خرقت مقدما من جنب ثوبي ... حيال مكان ذاك من الإزار)\n(فقالت ويلها رجل ويمشي ... بما يمشي به عجر الحمار)\n(وقالت ما تريد فقلت خيرا ... نسيئة ما علي إلى يساري)\n(فصدت بعدما نظرت إليه ... وقد ألمحتها عنق الحوار)\nخبرني إبراهيم بن أيوب عن عبد الله بن مسلم قال لقي ابن مناذر أبا حية فقال له أنشدني بعض شعرك فأنشده\n(ألا حي من أجل الحبيب المغانيا ... )","topic":"أخبار أبي حية النميري ونسبه","topicNo":209,"sp":1,"spl":"طرائف من أخباره — طرائف من أخباره","partialRef":{"sid":"b208-16","gi":3,"vi":0,"side":0},"partial":1},
{"id":"b209-3","bab":"الجزء 16","sec":"طرائف من أخباره","page":"ج16 ص331","text":"قال له ابن مناذر وهذا شعر فقال أبو حية ما في شعري عيب هو شر من أنك تسمعه ثم أنشده ابن مناذر شيئا من شعره فقال له أبو حية قد عرفتك ما قصتك وهذه القصيدة يفخر فيها أبو حية ويذكر يوم النشاش وهو يوم لبني نمير","topic":"أخبار أبي حية النميري ونسبه","topicNo":209,"sp":1,"spl":"طرائف من أخباره — طرائف من أخباره"},
{"id":"b209-4","bab":"الجزء 16","sec":"أخبار أحمد بن يحيى المكي","page":"ج16 ص336","text":"أحمد بن يحيى بن مرزوق المكي ويكنى أبا جعفر وكان يلقب ظنينا وقد تقدم ذكر أبيه وأخباره وهو أحد المحسنين المبرزين الرواة للغناء المحكمي الصنعة وكان إسحاق يقدمه ويؤثره ويشيد بذكره ويجهر بتفضيله وكتابه المجرد في الأغاني ونسبها أصل من الأصول المعمول عليها وما أعرف كتابا بعد كتاب إسحاق الذي ألفه لشبحا يقارب كتابه ولا يقاس به وكان مع جودة غنائه وحسن صنعته أحد الضراب الموصوفين المتقدمين أخبرني عمي قال حدثني أبو عبد الله الهشامي عن محمد بن أحمد المكي أن أباه جمع لمحمد بن عبد الله بن طاهر ديوانا للغناء ونسبه وجنسه فكان محتويا على أربعة عشر ألف صوت أخبرني جحظة قال حدثني علي بن يحيى ونسخت من بعض الكتب حدثني محمد بن أحمد المكي قال حدثني علي بن يحيى قال قلت لإسحاق بن إبراهيم الموصلي وقد جرى ذكر أحمد بن يحيى المكي يا أبا محمد لو كان أبو جعفر أحمد بن يحيى المكي مملوكا كم كان يساوي فقال أخبرك عن ذلك انصرفت ليلة من دار الواثق فاجتزت بدار الحسن بن وهب فدخلت\nإليه فإذا أحمد عنده فلما قام لصلاة العشاء الآخرة قال لي الحسن بن وهب كم يساوي أحمد لو كان مملوكا قلت يساوي عشرين ألف دينار قال ثم رجع فغنى صوتا فقال لي الحسن بن وهب يا أبا محمد أضعفها قال ثم تغني صوتا آخر فقلت للحسن يا أبا علي أضعفها ثم أردت الانصراف فقلت لأحمد غنني\n(لولا الحياء وأن الستر من خلقي ... إذن قعدت إليك الدهر لم أقم)\n(أليس عندك شكر للتي جعلت ... ما ابيض من قادمات الرأس كالحمم)\nلغناء فيه لمعبد خفيف ثقيل أول في مجرى البنصر عن إسحاق وذكر عمرو بن بانة أنه لمالك وليس كما قال لحن مالك ثقيل أول ذكره الهشامي ودنانير وغيرهما قال فغناه أحمد بن يحيى المكي فأحسن فيه كل الإحسان فلما قمت للانصراف قلت للحسن يا أبا علي أضعف الجميع فقال له أحمد ما هذا الذي أسمعكما تقولانه ولست أدري ما معناه قال نحن نبيعك ونشتريك منذ الليلة وأنت لا تدري وأخبرنا بهذا الخبر يحيى بن علي بن يحيى عن أخيه أحمد بن علي\nعن عافية بن شبيب عن أبي حاتم قال كان إسحاق عندنا في منزل أبي علي الحسن بن وهب وعندنا ظنين بن المكي وذكر الحديث مثله وقال فيه إنه قومه مئة ألف درهم وذكر أن الصوت الذي غناه آخرا\n(أمن دمن وخيم باليات ... وسفع كالحمائم جاثمات)\n(أرقت لهن شطر الليل حتى ... طلعن من المناقب منجدات)\nأن إسحاق لما سمعه قال كم كنت قومته قال مئة ألف درهم قال أضعفوا القيمة قيمته مئتا ألف درهم في هذين البيتين لحن من القدر الأوسط من - الثقيل - الأول بالسبابة في مجرى الوسطى ينسب إلى ابن مسجح وإلى ابن محرز وفيه لابن سريج ثاني - ثقيل - بالوسطى عن عمرو وللغريض - خفيف ثقيل - عن الهشامي","topic":"أخبار أبي حية النميري ونسبه","topicNo":209,"sp":2,"spl":"أخبار أحمد بن يحيى المكي","song":2},
{"id":"b209-5","bab":"الجزء 16","sec":"مناظرته للمغنين","page":"ج16 ص338","text":"أخبرني جحظة قال حدثني محمد بن أحمد المكي قال ناظر أبي بعض المغنين ذات ليلة بين يدي المعتصم وطال تلاحيهما في الغناء فقال أبي للمعتصم يا أمير المؤمنين من شاء منهم فليغن عشرة أصوات لا أعرف منها ثلاثة وأنا أغني عشرة وعشرة وعشرة لا يعرف أحد منهم صوتا منها فقال إسحاق صدق يا أمير المؤمنين واتبعه ابن بسختر وعلويه\nفقالا صدق يا أمير المؤمنين إسحاق فيما يقوله فأمر له بعشرين ألف درهم قال محمد ثم عاد ذلك الرجل إلى مماظته يوما فقال له قد دعوتك إلى النصفة فلم تقبل وأنا أدعوك وأبدأ بما دعوتك إليه فاندفع فغنى عشرة أصوات فلم يعرف أحد منهم منها صوتا واحدا كلها من الغناء القديم والغناء اللاحق به من صنعة المكيين الحذاق الخاملي الذكر فاستحسن المعتصم منها صوتا وأسكت المغنين له واستعاده مرات عدة ولم يزل يشرب عليه سحابة يومه وأمر ألا يراجع أحدا من المغنين كلاما ولا يعارضه أحد منهم إذ كان قد أبر عليهم وأوضح الحجة في انقطاعهم وإدحاض حججهم كان الصوت الذي اختاره المعتصم عليه وأمر له لما سمعه بألفي دينار\n(لعن الله من يلوم محبا ... ولحى الله من يحب فيابى)\n(رب إلفين أضمرا الحب دهرا ... فعفا الله عنهما حين تابا)\nلغناء ليحيى المكي - رمل - قال محمد قال أبي وكان المعتصم قد خلع علينا في ذلك اليوم مماطر لها شأن من ألوان\nشتى فسألني عبد الوهاب بن علي أن أرد عليه هذا الصوت وجعل لي ممطره فغنيته إياه فلما خرجنا للانصراف إلى منازلنا أمر غلمانه بدفع الممطر إلى غلماني فسلموه إليهم أخبرني عبد الله بن الربيع عن أبيه قال حدثني محمد بن عبد الله بن مالك قال سألني إسحاق بن إبراهيم الموصلي يوما من بقي من المغنين قلت وجه القرعة محمد بن عيسى مولى عيسى بن جعفر فقال صالح كيس ومن أيضا قلت أحمد بن يحيى المكي قال بخ بخ ذاك المحسن المجمل الضارب المغني القائم بمجلسه لا يحوج أهل المجلس إلى غيره ومن بأبي أنت قلت ابن مقامرة قال لا والله ما سمعت بهذا قط فمن مقامرة هذه زامرة أم نائحة أم مغنية قلت لا ولكنها من الناس وليست من أهل صناعته قال ومن أيضا بأبي أنت قلت يحيى بن القاسم ابن أخي سلمة قال الذي كان له أخ يغني مرتجلا قلت نعم قال لم يحسن ذاك ولا أبوه شيئا قط ولا أشك أن هذا كذلك لأنهما مؤدباه وذكر ابن المكي عن أبيه قال قال المعتصم يوما لجلسائه ونحن عنده خلعت اليوم على فتى شريف ظريف نظيف حسن الوجه شجاع القلب ووليته المصيصة ونواحيها\nفقلنا من هذا يا أمير المؤمنين فقال خالد بن يزيد بن مزيد فقال علويه يا أحمد غن أمير المؤمنين صوتك في مدح خالد فأمسكت عنه فقال المعتصم مالك لا تجيبه فقلت يا أمير المؤمنين ليس هو مما يغنى بحضرة الخليفة فقال ما من أن تغنيه بد قال فغنيته صنعة لي في هذا الشعر\n(علم الناس خالد بن يزيد ... كل حلم وكل بأس وجود)\n(فترى الناس هيبة حين يبدو ... من قيام وركع وسجود)\nقال المعتصم يا سمانة خذ أحمد بإلقاء هذا الصوت على الجواري في غد وأمر لي بعشرة آلاف درهم قال وغنى أبي يوما محمدا الأمين\n(فعش عمر نوح في سرور وغبطة ... وفي خفض عيش ليس في طوله إثم)\n(تساعدك الأقدار فيه وتنثني ... إليك وترعى فضلك العرب والعجم)\nأمر له بخمس مئة دينار وتوفي أحمد بن يحيى المكي في خلافة المستعين في أولها\nأخبرني بذلك جحظة البرمكي عن محمد بن أحمد بن يحيى المكي أن أباه توفي في هذا الوقت انقضت أخباره\n(إن الذين غدوا بلبك غادروا ... وشلا بعينك ما يزال معينا)\n(غيضن من عبراتهن وقلن لي ... ماذا لقيت من الهوى ولقينا)\nادروا تركوا والوشل الماء القليل والمعين الماء الصافي الجاري وغيضن من عبراتهن أي كففنها ومسحنها حتى تغيض الشعر لجرير والغناء لإسحاق - رمل - بالوسطى عن عمرو وهو من طريف أرمال إسحاق وعيونها وفيه لابن سريج ثقيل أول بالبنصر عن الهشامي وعمرو وذكر علي بن يحيى أن فيه لابن سريج رملا آخر وذكر عيسى أن الثقيل الأول لإبراهيم وأن فيه للهذلي ثاني - ثقيل - بالوسطى ولإبراهيم أيضا ماخوري بالبنصر","topic":"أخبار أبي حية النميري ونسبه","topicNo":209,"sp":3,"spl":"مناظرته للمغنين","song":4},
{"id":"b209-6","bab":"الجزء 16","sec":"من غزل جرير","page":"ج16 ص343","text":"وقد أخبرني إبراهيم بن محمد بن أيوب الصائغ قال حدثنا عبد الله بن مسلم بن قتيبة أن هذين البيتين للمعلوط وأن جريرا سرقهما منه وأدخلهما في شعره أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عمي وغيره قالوا غدا عبد الله بن مسلم ابن جندب الهذلي على أبي السائب المخزومي في منزله فلما خرج إليه أبو السائب أنشده قول جرير\n(إن الذين غدوا بلبك غادروا ... وشلا بعينك لا يزال معينا)\nالبيتين فحلف أبو السائب ألا يرد على أحد سلاما ولا يكلمه إلا بهذين البيتين حتى يرجع إلى منزله فخرجا فلقيهما عبد العزيز بن المطلب وهو قاض وكانا يدعيان القرينين لملازمتهما فلما رآهما قال كيف أصبح القرينان فغمز أبو السائب ابن جندب أن أخبره بالقصة وابن جندب يتغافل فقال لابن جندب ما لأبي السائب فجعل أبو السائب يغمزه أي أخبره بيميني قال ابن جندب أحمد الله إليك ما زلت منكرا لفعله منذ خرجنا فانصرف ابن المطلب إلى منزله والخصوم ينتظرونه فصرفهم ودخل منزله مغتما فلما أتى أبو السائب منزله وبرت يمينه خرج إلى ابن جندب فقال اذهب بنا إلى ابن المطلب فإني أخاف أن يرد شهادتي فاستأذنا عليه فأذن\nلهما فقال له أبو السائب قد علمت - أعزك الله - غرامي بالشعر وإن هذا الضال جاءني حين خرجت من منزلي فأنشدني بيتين فحلفت ألا أرد على أحد سلاما ولا أكلمه إلا بهما حتى أرجع إلى منزلي فقال ابن المطلب اللهم غفرا ألا تترك المجون يا أبا السائب أخبرني الحرمي قال حدثنا الزبير بن بكار قال حدثني عبد المطلب بن عبد العزيز قال أنشدت أبا السائب قول جرير\n(غيضن من عبراتهن وقلن لي ... ماذا لقيت من الهوى ولقينا)\nقال يابن أخي أتدري ما التغييض قلت لا قال هكذا وأشار بأصبعه إلى جفنه كأنه يأخذ الدمع ثم ينضحه أخبرني الحرمي قال حدثنا الزبير بن بكار قال حدثنا المدائني وأخبرنا محمد بن العباس اليزيدي عن أحمد بن زهير عن الزبير بن بكار قال عن المدائني قال شهد رجل عند قاض بشهادة فقيل له من يعرفك قال ابن أبي عتيق فبعث إليه يسأله عنه فقال عدل رضا فقيل له أكنت تعرفه قبل اليوم قال لا ولكني سمعته ينشد\n(غيضن من عبراتهن وقلن لي ... ماذا لقيت من الهوى ولقينا)\nعلمت أن هذا لا يرسخ إلا في قلب مؤمن فشهدت له بالعدالة أخبرني الحرمي قال حدثنا الزبير قال حدثنا محمد بن الحسن ومحمد بن الضحاك قالا كان أبو السائب المخزومي واقفا على رأس بئر فأنشده ابن جندب\n(إن الذين غدوا بلبك غادروا ... وشلا بعينك لا يزال معينا)\nرمى بنفسه في البئر بثيابه فبعد لأي ما أخرجوه أخبرني محمد بن خلف وكيع قال حدثنا محمد بن الحسن الزرقي قال حدثنا العلاء بن عمرو الزبيري من ولد عمرو بن الزبير قال حدثنا يحيى بن أبي قتيلة قال حدثني إسماعيل بن جعفر بن محمد بن علي بن الحسن بن علي عليهم السلام عن أشعب قال جاءني فتية من قريش فقالوا لي نحب أن تسمع سالم بن عبد الله بن عمر صوتا من الغناء وتعلمنا ما يقول لك وجعلوا لي في ذلك جعلا فدخلت عليه فقلت يا أبا عمرو لي مجالسة وحرمة ومودة وسن وأنا مولع بالترنم قال وما الترنم قلت الغناء قال وفي أي وقت قلت في الخلوة ومع الإخوان في الخارج وأحب أن أسمعك فإن كرهته أمسكت عنه ثم غنيته فقال ما أرى بأسا فخرجت إليهم فأعلمتهم فقالوا وما غنيته فقلت غنيته\n(قربا مربط النعامة مني ... لقحت حرب وائل عن حيال)\nالوا هذا بارد لا حركة فيه ولسنا نرضى فلما رأيت دفعهم إياي وخفت ذهاب ما جعلوا لي رجعت إليه فقلت يا أبا عمرو آخر قال ما لي ولك ولم أملكه أمره حتى غنيت فقال ما أرى بأسا فخرجت إليهم فأعلمتهم قالوا وما غنيته قلت\n(لم يطيقوا أن ينزلوا ونزلنا ... وأخو الحرب من أطاق النزولا)\nالوا وليس هذا بشيء فرجعت إليه فقلت آخر فاستكفني فلم\nأملكه القول حتى غنيته\n(غيضن من عبراتهن وقلن لي ... ماذا لقيت من الهوى ولقينا)","topic":"أخبار أبي حية النميري ونسبه","topicNo":209,"sp":4,"spl":"من غزل جرير"},
{"id":"b209-7","bab":"الجزء 16","sec":"من غزل جرير","page":"ج16 ص343","text":"قال مهلا مهلا قلت لا والله إلا بذاك الذي فيه تمر عجوة من صدقة عمر فقال هو لك فخرجت عليهم به وأنا أخطر فقالوا مه فقلت أطربت الشيخ حتى أعطاني هذا وقال مرة أخرى حتى فرض لي هذا قال ووالله ما فعل وإنما كان فدية لأصمت وأخذت منهم الجعل أخبرني يحيى بن علي بن يحيى المنجم قال حدثت عن حماد بن إسحاق قال حدثني علويه الأعسر قال أتيت أباك في داره هذه يوما وقد بنى إيوانها وسائرها خراب فجلسنا على تل من تراب فغناني لحنه في\n(غيضن من عبراتهن وقلن لي ... ماذا لقيت من الهوى ولقينا)\nسألته أن يعيده علي ففعل وأتانا رسول أبيه بطبق رطب فقال للرسول قل له سأرسل إليك برطب أطيب من الرطب الذي بعثت به إلي فأبلغه الرسول ذلك فقال له ومن عنده فأخبره أنني عنده فقال ما أخلقه أن يكون قد أتاني بآبدة أتانا رسوله بعد ساعة فقال ما آن لرطبكم أن يأتينا فأرسلني إليه وقد أخذت الصوت فغنيته إياه فقال أجاد والله أألام على هذا وحبه والله لو لم يكن بيني وبينه قرابة لأحببته فكيف وهو ابني\n(ألست ترى يا ضب بالله أنني ... مصاحبة نحو المدينة اركبا)\n(إذا قطعوا حزنا تخب ركابهم ... كما حركت ريح يراعا مثقبا)\nروضه من - الطويل - والشعر لنائلة بنت الفرافصة والغناء لابن عائشة ولحنه من الثقيل الأول بالوسطى ووجدت في كتاب بخط عبيد الله بن عبد الله بن طاهر أنه مما نحله يحيى المكي لابن عائشة","topic":"أخبار أبي حية النميري ونسبه","topicNo":209,"sp":5,"spl":"من غزل جرير","song":1},
{"id":"b210-1","bab":"الجزء 16","sec":"أخبار نائلة بنت الفرافصة ونسبها","page":"ج16 ص348","text":"هي نائلة بنت الفرافصة بن الأحوص بن عمرو وقيل ابن عفر بن ثعلبة وقيل عمرو بن ثعلبة بن الحارث بن حصن بن ضمضم بن عدي بن جناب الكلبية زوجة عثمان بن عفان رضي الله عنه تقوله لأخيها لما نقلها إلى عثمان أخبرني بخبره وخبرها أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثنا عبد الله بن محمد بن حكيم عن خالد بن سعيد عن أبيه قال تزوج سعيد بن العاص وهو على الكوفة هند بنت الفرافصة بن الأحوص بن عمرو بن ثعلبة فبلغ ذلك عثمان فكتب إليه بسم الله الرحمن الرحيم أما بعد فإنه قد بلغني أنك تزوجت امرأة من كلب فاكتب إلي بنسبها وجمالها فكتب إليه أما بعد فإن نسبها أنها بنت الفرافصة بن الأحوص وجمالها أنها بيضاء مديدة القامة فكتب إليه إن كانت لها أخت فزوجنيها فبعث سعيد إلى الفرافصة يخطب إحدى بناته على عثمان فأمر\nالفرافصة ابنه ضبا فزوجها إياه وكان ضب مسلما وكان الفرافصة نصرانيا فلما أرادوا حملها إليه قال لها أبوها يا بنية إنك تقدمين على نساء من نساء قريش هن أقدر على الطيب منك فاحفظي عني خصلتين تكحلي وتطيبي بالماء حتى يكون ريحك ريح شن أصابه مطر فلما حملت كرهت الغربة وحزنت لفراق أهلها فأنشأت تقول\n(ألست ترى يا ضب بالله أنني ... مصاحبة نحو المدينة أركبا)\n(إذا قطعوا حزنا تخب ركابهم ... كما حركت ريح يراعا مثقبا)\n(لقد كان في أبناء حصن بن ضمضم ... لك الويل ما يغني الخباء المطنبا)\nلما قدمت على عثمان رضي الله عنه قعد على سريره ووضع لها سريرا حياله فجلست عليه فوضع عثمان قلنسيته فبدا الصلع فقال يا بنة الفرافصة لا يهولنك ما ترين من صلعي فإن وراءه ما تحبين فسكتت فقال إما أن تقومي إلي وإما أن أقوم إليك فقالت أما ما ذكرت من الصلع فإني من نساء أحب بعولتهن إليهن السادة الصلع وأما قولك إما أن تقومي إلي وإما أن أقوم إليك فوالله ما تجشمت من جنبات السماوة أبعد مما بيني وبينك بل أقوم إليك فقامت فجلست إلى جنبه فمسح رأسها ودعا لها بالبركة ثم قال لها اطرحي عنك رداءك فطرحته ثم قال لها اطرحي خمارك فطرحته ثم قال لها انزعي درعك فنزعته ثم قال حلي إزارك فقالت ذاك إليك فحل إزارها فكانت من أحظى نساءه عنده أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال\n(إذا قطعوا حزنا تخب ركابهم ... كما حركت ريح يراعا مثقبا)\nروضه من - الطويل - والشعر لنائلة بنت الفرافصة والغناء لابن عائشة ولحنه من الثقيل الأول بالوسطى ووجدت في كتاب بخط عبيد الله بن عبد الله بن طاهر أنه مما نحله يحيى المكي لابن عائشة","topic":"أخبار نائلة بنت الفرافصة ونسبها","topicNo":210,"sp":0,"spl":"أخبار نائلة بنت الفرافصة ونسبها"},
{"id":"b210-2","bab":"الجزء 16","sec":"كتاب نائلة إلى معاوية","page":"ج16 ص351","text":"أخبرني أحمد قال حدثني عمر قال حدثنا علي بن محمد عن أبي مخنف عن نمير بن وعلة عن الشعبي ومسلمة بن محارب عن حرب بن خالد بن يزيد بن معاوية أن نائلة بنت الفرافصة كتبت إلى معاوية بن أبي سفيان وبعثت بقميص عثمان مع النعمان بن بشير أو عبد الرحمن بن حاطب بن أبي بلتعة من نائلة بنت الفرافصة إلى معاوية بن أبي سفيان أما بعد فإني أذكركم بالله الذي أنعم عليكم وعلمكم الإسلام وهداكم من الضلالة وأنقذكم من الكفر ونصركم على العدو وأسبغ النعمة وأنشدكم بالله وأذكركم حقه وحق خليفته الذي لم تنصروه وبعزمة الله عليكم فإنه عز و جل يقول ( وإن طائفتان من المؤمنين اقتتلوا فأصلحوا بينهما فإن بغت إحداهما على الأخرى فقاتلوا التي تبغي حتى تفيء إلى أمر الله\nوإن أمير المؤمنين بغي عليه ولو لم يكن له عليكم حق إلا حق الولاية ثم أتي بما أتي لحق على كل مسلم يرجو أيام الله أن ينصره لقدمه في الإسلام وحسن بلائه وأنه أجاب داعي الله وصدق كتابه والله أعلم به إذ انتجبه فأعطاه شرف الدنيا وشرف الآخرة وإني أقص عليكم خبره لأني كنت مشاهدة أمره كله حتى أفضي إليه وإن أهل المدينة حصروه في داره يحرسونه ليلهم ونهارهم قيام على أبوابه بسلاحهم يمنعونه كل شيء قدروا عليه حتى منعوه الماء يحضرونه\nالأذى ويقولون له الإفك فمكث هو ومن معه خمسين ليلة وأهل مصر قد أسندوا أمرهم إلى محمد بن أبي بكر وعمار بن ياسر وكان علي مع المحرضين من أهل المدينة ولم يقاتل مع أمير المؤمنين ولم ينصره ولم يأمر بالعدل الذي أمر الله تبارك وتعالى به فظلت تقاتل خزاعة وسعد بن بكر وهذيل وطوائف من مزينة وجهينة وأنباط يثرب ولا أرى سائرهم ولكني سميت لكم الذين كانوا أشد الناس عليه في أول أمره وآخره ثم إنه رمي بالنبل والحجارة فقتل ممن كان في الدار ثلاثة نفر فأتوه يصرخون إليه ليأذن لهم في القتال فنهاهم عنه وأمرهم أن يردوا عليهم نبلهم فردوها إليهم فلم يزدهم ذلك على القتال إلا جراءة وفي الأمر إلا إغراء ثم أحرقوا باب الدار فجاءه ثلاثة نفر من أصحابه فقالوا إن في المسجد ناسا يريدون أن يأخذوا أمر الناس بالعدل فأخرج إلى المسجد حتى يأتوك فانطلق فجلس فيه ساعة وأسلحة القوم مطلة عليه من كل ناحية وما أرى أحدا يعدل فدخل الدار وقد كان نفر من قريش على عامتهم السلاح فلبس درعه وقال لأصحابه لولا أنتم ما لبست درعا فوثب عليه القوم فكلمهم ابن الزبير وأخذ عليهم ميثاقا في صحيفة بعث بها إلى عثمان إن عليكم عهد الله وميثاقه ألا تعروه بشيء فكلموه وتحرجوا فوضع السلاح فلم يكن إلا وضعه حتى دخل عليه القوم يقدمهم ابن أبي بكر حتى أخذوا بلحيته ودعوه باللقب فقال أنا عبد الله وخليفته فضربوه على رأسه ثلاث ضربات وطعنوه في صدره ثلاث طعنات\nوضربوه على مقدم الجبين فوق الأنف ضربة أسرعت في العظم فسقطت عليه وقد أثخنوه وبه حياة وهم يريدون قطع رأسه ليذهبوا به فأتتني بنت شيبة بن ربيعة فألقت نفسها معي عليه فوطئنا وطئا شديدا وعرينا من ثيابنا وحرمة أمير المؤمنين أعظم فقتلوه رحمة الله عليه في بيته وعلى فراشه وقد أرسلت إليكم بثوبه وعليه دمه وإنه والله لئن كان أثم من قتله لما يسلم من خذله فانظروا أين أنتم من الله جل وعز فإنا نشكي ما مسنا إليه ونستنصر وليه وصالح عباده ورحمة الله على عثمان ولعن الله من قتله وصرعهم في الدنيا مصارع الخزي والمذلة وشفى منهم الصدور فحلف رجال من أهل الشام ألا يطأوا النساء حتى يقتلوا قتلته أو تذهب أرواحهم\n(فيا راكبا إما عرضت فبلغن ... نداماي من نجران أن لا تلاقيا)\n(أبا كرب والأيهمين كليهما ... وقيسا بأعلى حضرموت اليمانيا)\n(وتضحك مني شيخة عبشمية ... كأن لم ترا قبلي أسيرا يمانيا)\n(أقول وقد شدوا لساني بنسعة ... أمعشر تيم أطلقوا عن لسانيا)\nالشعر لعبد يغوث بن صلاءة الحارثي والغناء لإسحاق - ثقيل - أول","topic":"أخبار نائلة بنت الفرافصة ونسبها","topicNo":210,"sp":1,"spl":"كتاب نائلة إلى معاوية","song":1},
{"id":"b211-1","bab":"الجزء 16","sec":"أخبار عبد يغوث ونسبه","page":"ج16 ص354","text":"هو عبد يغوث بن صلاءة وقيل بل هو عبد يغوث بن الحارث بن وقاص بن صلاءة - وهو قول ابن الكلبي - بن المغفل واسم المغفل ربيعة بن كعب الأرت بن ربيعة بن كعب بن الحارث بن كعب بن عمرو بن علة بن خالد بن مالك بن أدد بن زيد بن يشجب بن عريب بن زيد بن كهلان بن سبأ بن يشجب بن يعرب بن قحطان قال ابن الكلبي قحطان بن عابر بن شالخ بن أرفخشذ بن سام بن نوح قال وكان يقال ليعرب المرعف وكان عبد يغوث بن صلاءة شاعرا من شعراء الجاهلية فارسا سيدا لقومه من بني الحارث بن كعب وهو كان قائدهم في يوم الكلاب الثاني إلى بني تميم وفي ذلك اليوم أسر فقتل وعبد يغوث من أهل بيت شعر معرق لهم في الجاهلية والإسلام منهم اللجلاج الحارثي وهو طفيل بن يزيد بن عبد يغوث بن صلاءة وأخوه مسهر فارس شاعر وهو الذي طعن عامر بن الطفيل في عينه يوم فيف الريح ومنهم ممن أدرك الإسلام جعفر بن علبة بن\nربيعة بن الحارث بن عبد يغوث بن الحارث بن معاوية بن صلاءة وكان فارسا شاعرا صعلوكا أخذ في دم فحبس بالمدينة ثم قتل صبرا وخبره يذكر منفردا لأن له شعرا فيه غناء والشعر المذكور في هذا الموضع لعبد يغوث بن صلاءة يقوله في يوم الكلاب الثاني وهو اليوم الذي جمع فيه قومه وغزا بني تميم فظفرت به بنو تميم وأسروه وقتل يومئذ","topic":"أخبار عبد يغوث ونسبه","topicNo":211,"sp":0,"spl":"أخبار عبد يغوث ونسبه"},
{"id":"b211-2","bab":"الجزء 16","sec":"حديث يوم الكلاب","page":"ج16 ص355","text":"وكان من حديث هذا اليوم فيما ذكر أبو عبيدة عن أبي عمرو بن العلاء وهشام بن الكلبي عن أبيه والمفضل بن محمد الضبي وإسحاق بن الجصاص عن العنبري قالوا لما أوقع كسرى ببني تميم يوم الصفا بالمشقر فقتل المقاتلة وبقيت الأموال والذراري بلغ ذلك مذحجا فمشى بعضهم إلى بعض وقالوا اغتنموا بني تميم ثم بعثوا الرسل في قبائل اليمن وأحلافها من قضاعة فقالت مذحج للمأمور الحارثي وهو كاهن ما ترى فقال لهم لا تغزوا بني تميم\nفإنهم يسيرون أغبابا ويردون مياها جبابا فتكون غنيمتكم ترابا قال أبو عبيدة فذكر أنه اجتمع من مذحج ولفها اثنا عشر ألفا وكان رئيس مذحج عبد يغوث بن صلاءة ورئيس همدان يقال له مسرح ورئيس كندة البراء بن قيس بن الحارث فأقبلوا إلى تميم فبلغ ذلك سعدا والرباب فانطلق ناس من أشرافهم إلى أكثم بن صيفي وهو قاضي العرب يومئذ فاستشاروه فقال لهم أقلوا الخلاف على أمرائكم واعلموا أن كثرة الصياح من الفشل والمرء يعجز لا محالة يا قوم تثبتوا فإن أحزم الفريقين الركين ورب عجلة تهب ريثا واتزروا للحرب وادرعوا الليل فإنه أخفى للويل ولا جماعة لمن اختلف فلما انصرفوا من عند أكثم تهيؤوا واستعدوا للحرب وأقبل أهل اليمن من بني الحارث من أشرافهم يزيد بن عبد المدان ويزيد بن مخرم ويزيد بن الطيثم بن المأمور ويزيد بن هوبر حتى إذا كانوا\nبتيمن نزلوا قريبا من الكلاب ورجل من بني زيد بن رياح بن يربوع يقال له مشمت بن زنباع في إبل له عند خال له من بني سعد يقال له زهير بن بو فلما أبصرهم المشمت قال لزهير دونك الإبل وتنح عن طريقهم حتى آتي الحي فأنذرهم قال فركب المشمت ناقة ثم سار حتى أتى سعدا والرباب وهم على الكلاب فأنذرهم فأعدوا للقوم وصبحوهم فأغاروا على النعم فطردوها وجعل رجل من أهل اليمن يرتجز ويقول\n(في كل عام نعم ننتابه ... على الكلاب غيبا أربابه)\nال فأجابه غلام من بني سعد كان في النعم على فرس له فقال\n(عما قليل سترى أربابه ... صلب القناة حازما شبابه)\n(على جياد ضمر عيابه ... )\nال فأقبلت سعد والرباب ورئيس الرباب النعمان بن جساس ورئيس بني سعد قيس بن عاصم المنقري قال أبو عبيدة اجتمع العلماء على أن الرئيس كان يومئذ قيس بن عاصم فقال ضبي حين دنا من القوم\n(في كل عام نعم تحوونه ... يلقحه قوم وتنتجونه)\n(أربابه نوكى فلا يحمونه ... ولا يلاقون طعانا دونه)\n(أنعم الأبناء تحسبونه ... هيهات هيهات لما ترجونه)\nقال ضمرة بن لبيد الحماسي انظروا إذا سقتم النعم فإن أتتكم الخيل عصبا عصبا وثبتت الأولى للأخرى حتى تلحق فإن أمر القوم هين وإن لحق بكم القوم فلم ينظروا إليكم حتى يردوا وجوه النعم ولا ينتظر بعضهم بعضا فإن أمر القوم شديد وتقدمت سعد والرباب فالتقوا في أوائل الناس فلم يلتفتوا إليهم واستقبلوا النعم من قبل وجوهها فجعلوا يصرفونها بأرماحهم واختلط القوم فاقتتلوا قتالا شديدا يومهم حتى إذا كان من آخر النهار قتل النعمان بن جساس قتله رجل من أهل اليمن كانت أمه من بني حنظلة يقال له عبد الله بن كعب وهو الذي رماه فقال للنعمان حين رماه خذها وأنا ابن الحنظلية فقال النعمان ثكلتك أمك رب حنظلية قد غاظتني فذهبت مثلا وظن أهل اليمن أن بني تميم سيهدهم قتل النعمان فلم يزدهم ذلك إلا جراءة عليهم فاقتتلوا حتى حجز بينهم الليل فباتوا يحرس بعضهم بعضا فلما أصبحوا غدوا على القتال فنادى قيس بن عاصم يال سعد ونادى عبد يغوث يال سعد قيس بن عاصم يدعو سعد بن زيد مناة بن تميم وعبد يغوث يدعو سعد العشيرة فلما سمع ذلك قيس نادى يال كعب فنادى عبد يغوث يال كعب قيس يدعو كعب بن سعد وعبد يغوث يدعو كعب بن عمرو فلما رأى ذلك قيس من صنيع عبد يغوث قال ما لهم أخزاهم الله ما ندعو بشعار إلا دعوا بمثله فنادى قيس يال مقاعس يعني بني الحارث بن عمرو بن كعب وكان يلقب مقاعسا فلما سمع وعلة بن عبد الله الجرمي الصوت وكان صاحب اللواء يومئذ طرحه وكان أول من انهزم من اليمن وحملت عليهم بنو سعد والرباب فهزموهم أفظع هزيمة وجعل رجل منهم يقول\n(يا قوم لا يفلتكم اليزيدان ... مخرما أعني به والديان)\nوجعل قيس بن عاصم ينادي يال تميم لا تقتلوا إلا فارسا فإن الرجالة لكم وجعل يرتجز ويقول\n(لما تولوا عصبا شوازبا ... أقسمت لا أطعن إلا راكبا)\n(إني وجدت الطعن فيهم صائبا ... )","topic":"أخبار عبد يغوث ونسبه","topicNo":211,"sp":1,"spl":"حديث يوم الكلاب","partial":1},
{"id":"b211-3","bab":"الجزء 16","sec":"حديث يوم الكلاب","page":"ج16 ص355","text":"جعل يأخذ الأسارى فإذا أخذ أسيرا قال له ممن أنت فيقول من بني زعبل وهو زعبل بن كعب أخو الحارث بن كعب وهم أنذال فكأن الأسارى يريدون بذلك رخص الفداء فجعل قيس إذا أخذ أسيرا منهم دفعه إلى من يليه من بني تميم ويقول أمسك حتى أصطاد لك زعبلة أخرى فذهبت مثلا فما زالوا في آثارهم يقتلون ويأسرون حتى أسر عبد يغوث أسره فتى من بني عمير بن عبد شمس وقتل يومئذ علقمة بن سباع القريعي وهو فارس هبود وهبود فرس عمرو بن الجعيد المرادي وكان علقمة قتل عمرا وأخذ فرسه من تحته وأسر الأهتم واسمه سنان بن سمي بن خالد بن منقر ويومئذ سمي الأهتم - رئيس كندة البراء بن قيس وقتلت التيم الأوبر الحارثي وآخر من بني الحارث يقال له معاوية قتلهما النعمان بن جساس وقتل يومئذ من أشرافهم خمسة وقتلت بنو ضبة ضمرة بن لبيد الحماسي الكاهن قتله قبيصة بن ضرار بن عمرو الضبي وأما عبد يغوث فانطلق به العبشمي إلى أهله وكان العبشمي أهوج فقالت له أمه - ورأت عبد يغوث عظيما جميلا جسيما - من أنت قال أنا سيد القوم فضحكت وقالت قبحك الله من سيد قوم حين أسرك هذا الأهوج فقال عبد يغوث\n(وتضحك مني شيخة عبشمية ... كأن لم ترا قبلي أسيرا يمانيا)\nثم قال لها أيتها الحرة هل لك إلى خير قالت وما ذاك قال أعطى ابنك مئة من الإبل وينطلق بي إلى الأهتم فإني أتخوف أن تنتزعني سعد والرباب منه فضمن له مئة من الإبل وأرسل إلى بني الحارث فوجهوا بها إليه فقبضها العبشمي فانطلق به إلى الأهتم وأنشأ عبد يغوث يقول\n(أأهتم يا خير البرية والدا ... ورهطا إذا ما الناس عدوا المساعيا)\n(تدارك أسيرا عانيا في بلادكم ... ولا تثقفني التيم ألقى الدواهيا)\nمشت سعد والرباب فيه فقالت الرباب يا بني سعد قتل فارسنا ولم يقتل لكم فارس مذكور فدفعه الأهتم إليهم فأخذه عصمة بن أبير التيمي فانطلق به إلى منزله فقال عبد يغوث يا بني تيم اقتلوني قتلة كريمة فقال له عصمة وما تلك القتلة قال اسقوني الخمر ودعوني أنح على نفسي فقال له عصمة نعم فسقاه الخمر ثم قطع له عرقا يقال له الأكحل وتركه ينزف ومضى عنه عصمة وترك معه ابنين له فقالا جمعت أهل اليمن وجئت لتصطلمنا فكيف رأيت الله صنع بك فقال عبد يغوث في ذلك\n(ألا لا تلوماني كفى اللوم ما بيا ... فما لكما في اللوم نفع ولا ليا)\n(ألم تعلما أن الملامة نفعها ... قليل وما لومي أخي من شماليا)\n(فيا راكبا إما عرضت فبلغن ... نداماي من نجران أن لا تلاقيا)\n(أبا كرب والأيهمين كليهما ... وقيسا بأعلى حضرموت اليمانيا)\n(جزى الله قومي بالكلاب ملامة ... صريحهم والآخرين المواليا)\n(ولو شئت نجتني من الخيل نهدة ... ترى خلفها الحو الجياد تواليا)\n(ولكنني أحمي ذمار أبيكم ... وكان الرماح يختطفن المحاميا)\n(وتضحك مني شيخة عبشمية ... كأن لم ترا قبلي أسيرا يمانيا)\n(وقد علمت عرسي مليكة أنني ... أنا الليث معدوا عليه وعاديا)\n(أقول وقد شدوا لساني بنسعة ... أمعشر تيم أطلقوا لي لسانيا)\n(أمعشر تيم قد ملكتم فأسجحوا ... فإن أخاكم لم يكن من بوائيا)\n(فإن تقتلوني تقتلوا بي سيدا ... وإن تطلقوني تحربوني بما ليا)\n(أحقا عباد الله أن لست سامعا ... نشيد الرعاء المعزبين المتاليا)\n(وقد كنت نحار الجزور ومعمل المطي ... وأمضى حيث لا حي ماضيا)\n(وأنحر للشرب الكرام مطيتي ... وأصدع بين القينتين ردائيا)\n(وعادية سوم الجراد وزعتها ... بكفي وقد أنحوا إلي العواليا)\n(كأني لم أركب جوادا ولم أقل ... لخيلي كري نفسي عن رجاليا)\n(ولم أسبأ الزق الروي ولم أقل ... لأيسار صدق أعظموا ضوء ناريا)\nال فضحكت العبشمية وهم آسروه وذلك لما أسروه شدوا لسانه بنسعة لئلا يهجوهم وأبوا إلا قتله فقتلوه بالنعمان بن جساس فقالت صفية بنت الخرع ترثي النعمان\n(نطاقه هندواني وجبته ... فضفاضة كأضاة النهي موضونه)\n(لقد أخذنا شفاء النفس لو شفيت ... وما قتلنا به إلا امرأ دونه)\nقال علقمة بن سباع لعمرو بن الجعيد\n(لما رأيت الأمر مخلوجة ... أكرهت فيه ذابلا مارنا)\n(قلت له خذها فإني امرؤ ... يعرف رمحي الرجل الكاهنا)","topic":"أخبار عبد يغوث ونسبه","topicNo":211,"sp":2,"spl":"حديث يوم الكلاب"},
{"id":"b211-4","bab":"الجزء 16","sec":"حديث يوم الكلاب","page":"ج16 ص355","text":"وله يعرف رمحي الرجل الكاهنا يريد أن عمرو بن الجعيد كان كاهنا وهو أحد بني عامر بن الديل بن شن بن أفصى بن عبد القيس ولم يزل ذلك في ولده ومنهم الرباب بن البراء كان يتكهن ثم طلب خلاف أهل الجاهلية فصار على دين المسيح عليه السلام فذكر أبو اليقظان أن الناس سمعوا في زمانه مناديا ينادي في الليل وذلك قبل مبعث النبي خير أهل\nالأرض رباب الشني وبحيرا الراهب وآخر لم يأت بعد قال وكان لا يموت أحد من ولد الرباب إلا رأوا على قبره طشا ومن ولده مخربة وهو أحد أجواد العرب وإنما سمي مخربة لأن السلاح خربه لكثرة لبسه إياه وقد أدرك النبي فأسلم فأرسله إلى ابن الجلندى العماني وابنه المثنى بن مخربة أحد وجوه أصحاب المختار وكان قد وجهه إلى البصرة ليأخذها فحاربه عباد بن الحصين فهزمه وكان ابنه بلج بن المثنى جوادا وفيه يقول بعض شعراء عبد القيس\n(ألا يا بلج بلج بني المثنى ... وأنت لكل مكرمة كفاء)\n(ألومك طائعا ما دمت حيا ... علي إذن من الله العفاء)\n(كفى قوما مكارم ضيعوها ... وأحسن حين أبصرهم أساؤوا)","topic":"أخبار عبد يغوث ونسبه","topicNo":211,"sp":3,"spl":"حديث يوم الكلاب"},
{"id":"b211-5","bab":"الجزء 16","sec":"رجع الخبر إلى سياقة حديث عبد يغوث والوقعة","page":"ج16 ص363","text":"قال فأما وعلة بن عبد الله الجرمي فإنه لحقه رجل من بني سعد فعقر به فنزل وجعل يحضر على رجليه فلحق رجلا من بني نهد يقال له سليط بن قتب من بني رفاعة فقال له لما لحقه أردفني فأبى فطرحه عن فرسه وركب عليها وأدركت الخيل النهدي فقتلوه فقال وعلة في ذلك\n(ولما سمعت الخيل تدعوا مقاعسا ... علمت بأن اليوم أغبر فاجر)\n(نجوت نجاء ليس فيه وتيرة ... كأني عقاب دون تيمن كاسر)\n(خدارية صقعاء لبد ريشها ... بطخفة يوم ذو أهاضيب ماطر)\n(وقد قلت للنهدي هل أنت مردفي ... وكيف رداف الفل أمك عاثر)\n(فإن أستطع لا تبتئس بي مقاعس ... ولا يرني باديهم والحواضر)\n(فدى لكما رجلي أمي وخالتي ... غداة الكلاب إذ تحز الحناجر)\n(فمن كان يرجو في تميم هوادة ... فليست لجرم في تميم أواصر)\nقالت نائحة عمرو بن الجعيد\n(أشاب قذال الرأس مصرع سيد ... وفارس هبود أشاب النواصيا)\nوقال محرز بن مكعبر الضبي\n(فدى لقومي ما جمعت من نشب ... إذ ساقت الحرب أقواما لأقوام)\n(قد حدثت مذحج عنا وقد كذبت ... أن لا يورع عن نسواننا حام)\n(دارت رحاهم قليلا ثم واجههم ... ضرب يصبح منهم مسكن الهام)\n(ساروا إلينا وهم صيد رؤوسهم ... فقد جعلنا لهم يوما كأيام)\n(ظلت ضباع مجيرات يعدنهم ... وألحموهن منهم أي إلحام)\n(ظلت تدوس بني كعب بكلكلها ... وهم يوم بني نهد بإظلام)\nقال أوس بن مغراء\n(وفي يوم الكلاب إذ اعترتنا ... قبائل أقبلوا متناسبينا)\n(قبائل مذحج اجتمعت وجرم ... وهمدان وكندة أجمعينا)\n(وحمير ثم ساروا في لهام ... على جرد جميعا قادرينا)\n(فلما أن أتونا لم نكذب ... ولم نسألهم أن يمهلونا)\n(قتلنا منهم قتلى وولى ... شريدهم شعاعا هاربينا)\n(وفاظت منهم فينا أسارى ... لدينا منهم متخشعينا)\nقال ذو الرمة غيلان بن عقبة في ذلك\n(وعمي الذي قاد الرباب جماعة ... وسعدهم الرأس الرئيس المؤمر)\n(عشية أعطتنا أزمة أمرها ... ضرار بنو القرم الأغر ومنقر)\n(وعبد يغوث تحجل الطير حوله ... قد احتز عرشيه الحسام المذكر)\nلعرشان عرقان في العنق\n(عشية فر الحارثيون بعدما ... قضى نحبه في معرك الخيل هوبر)\n(وقال أخو جرم ألا لا هوادة ... ولا وزر إلا النجاء المشمر)\n(أبى الله إلا أننا آل خندف ... بنا يسمع الصوت الأنام ويبصر)\n(إذا ما تمضرنا فلا ناس غيرنا ... ونضعف أحيانا ولا نتمضر)\nقال أيضا\n(فما شهدت خيل امرىء القيس غارة ... بثهلان تحمي عن ثغور الحقائق)\n(أثرنا به نقع الكلاب وأنتم ... تثيرون نقع الملتقى بالمعازق)\n(أدرنا على جرم وأفناء مذحج ... رحى الموت فوق العاملات الخوافق)\n(صدمناهم دون الأماني صدمة ... عماسا بأطواد طوال شواهق)\n(إذا نطحت شهباء شهباء بينها ... شعاع القنا والمشرفي البوارق)\nقال البراء بن قيس الكندي\n(قتلتنا تميم يوما جديدا ... قتل عاد وذاك يوم الكلاب)\n(يوم جئنا يسوقنا الحين سوقا ... نحو قوم كأنهم أسد غاب)\n(سرت في الأزد والمذاحج طرا ... بين صل وكاشر الأنياب)\n(وبني كندة الملوك ولخم ... وجذام وحمير الأرباب)\n(ومراد وخثعم وزبيد ... وبني الحارث الطوال الرغاب)\n(وحشدنا الصميم نرجو نهابا ... فلقينا البوار دون النهاب)\n(لقيتنا أسود سعد وسعد ... خلقت في الحروب سوط عذاب)\n(تركوني مسهدا في وثاق ... أرقب النجم ما أسيغ شرابي)\n(خائفا للردى ولولا دفاعي ... بمئين عن مهجتي كالهضاب)\n(لسقيت الردى وكنت كقومي ... في ضريح مغيبا في التراب)\n(تذرف الدمع بالعويل نسائي ... كنساء بكت قتيل الرباب)\n(فلعيني على اللألى فارقوني ... درر من دموعها بانسكاب)\n(كيف أبغي الحياة بعد رجال ... قتلوا كالأسود قتل الكلاب)\n(منهم الحارثي عبد يغوث ... ويزيد الفتيان وابن شهاب)\n(في مئين نعدها ومئين ... بعد ألف منوا بقوم غضاب)\n(برجال من العرانين شم ... أسد حرب ممحوضة الأنساب)\nقال وعلة بن عبد الله الجرمي\n(عذلتني نهد فقلت لنهد ... حين حاست على الكلاب أخاها)\n(يوم كنا عليهم طير ماء ... وتميم صقورها وبزاها)\n(لا تلوموا على الفرار فسعد ... يال نهد يخافها من يراها)\n(إنما همها الطعان إذا ما ... كره الطعن والضراب سواها)\n(تركوا مذحجا حديثا مشاعا ... مثل طسم وحمير وصداها)\n(يال قحطان وادعوا حي سعد ... وابتغوا سلمها وفضل نداها)\n(إن سعد السعود أسد غياض ... باسل بأسها شديد قواها)\n(فضحت بالكلاب حار بن كعب ... وبنو كندة الملوك أباها)","topic":"أخبار عبد يغوث ونسبه","topicNo":211,"sp":4,"spl":"رجع الخبر إلى سياقة حديث عبد يغوث والوقعة"},
{"id":"b211-6","bab":"الجزء 16","sec":"رجع الخبر إلى سياقة حديث عبد يغوث والوقعة","page":"ج16 ص363","text":"(أسلموا للمنون عبد يغوث ... ولعض الكبول حولا يراها)\n(بعد ألف سقوا المنية صرفا ... فأصابت في ذاك سعد مناها)\n(ليت نهدا وجرمها ومرادا ... والمذاحيج ذو أناة نهاها)\n(عن تميم فلم تكن فقع قاع ... تبتدرها ربابها ومناها)\n(قل لبكر العراق تستر عمرا ... عمرو قيس فرأي عمرو قراها)\n(عن تميم ولو غزتها لكانت ... مثل قطحان مستباحا حماها)\n\n(ما بال شمس أبي الخطاب قد حجبت ... أظن يا صاحبي الساعة اقتربت)\n(أولا فما بال ريح كنت آنسها ... عادت علي بصر بعدما جنبت)\n(أشكو إليك أبا الخطاب جارية ... غريرة بفؤادي اليوم قد لعبت)\n(وأنت قيمها فانظر لعاشقها ... يا ليت قد قربت مني وما بعدت)\nروضه من - البسيط - الشعر والغناء لإبراهيم الموصلي - رمل - بالبنصر عن الهشامي وعلي بن يحيى وذكر محمد بن الحارث بن بسخنز أن فيه هزجا بالبنصر لإبراهيم بن المهدي وذكر عمرو بن بانة أنه لإبراهيم الموصلي أيضا وأبو الخطاب الذي عناه إبراهيم في شعره هذا رجل نخاس يعرف بقرين مولى العباسة بنت المهدي وكان إبراهيم يهوى جارية له يقال لها خنث وكانت من أجمل النساء وأكملهن وكان لها خال فوق شفتها العليا وكانت تعرف بذات الخال ولإبراهيم ولغيره فيها أشعار كثيرة نذكر منها كل ما كان فيه غناء بعد خبرها إن شاء الله","topic":"أخبار عبد يغوث ونسبه","topicNo":211,"sp":5,"spl":"رجع الخبر إلى سياقة حديث عبد يغوث والوقعة — أخبار ذات الخال","song":1},
{"id":"b211-7","bab":"الجزء 16","sec":"أخبار ذات الخال","page":"ج16 ص369","text":"أخبرني بخبرها الحسين بن يحيى قال حدثنا حماد بن إسحاق قال حدثني أبي أن جدي كان يتعشق جارية لقرين المكنى بأبي الخطاب النخاس وكان يقول فيها الشعر ويغني فيه فشهرها بشعره وغنائه وبلغ الرشيد خبرها فاشتراها بسبعين ألف درهم فقال لها ذات يوم أسألك عن شيء فإن صدقتني وإلا صدقني غيرك وكذبتك قالت له بل أصدقك قال هل كان بينك وبين إبراهيم الموصلي شيء قط وأنا أحلفه أن يصدقني قال فتلكأت ساعة ثم قالت نعم مرة واحدة فأبغضها وقال يوما في مجلسه أيكم لا يبالي أن يكون كشخانا حتى أهب له ذات الخال فبدر حمويه الوصيف فقال أنا فوهبها له وفيها يقول إبراهيم\n(أتحسب ذات الخال راجية ربا ... وقد فتنت قلبا يهيم بها حبا)\n(وما عذرها نفسي فداها ولم تدع ... على أعظمي لحما ولم تبق لي لبا)\nلشعر والغناء لإبراهيم خفيف رمل بالسبابة في مجرى الوسطى وذكر أحمد بن أبي طاهر أن الرشيد اشتراها بسبعين ألف درهم وذكر قصة حمويه كما ذكرها حماد وقال في خبره فاشتاقها الرشيد يوما بعدما وهبها لحمويه فقال له\nويلك يا حمويه وهبنا لك الجارية على أن تسمع غناءها وحدك فقال يا أمير المؤمنين مر فيها بأمرك قال نحن عندك غدا فمضى فاستعد لذلك واستأجر لها من بعض الجوهريين بدنة وعقودا ثمنها اثنا عشر ألف دينار فأخرجها إلى الرشيد وهو عليها فلما رآها أنكره وقال ويلك يا حمويه من أين لك هذا وما وليتك عملا تكسب فيه مثله ولا وصل إليك مني هذا القدر فصدقه عن أمره فبعث الرشيد إلى أصحاب الجوهر فأحضرهم واشترى الجوهر منهم ووهبه لها ثم حلف ألا تسأله يومه ذلك شيئا إلا أعطاها ولا حاجة إلا قضاها فسألته أن يولي حمويه الحرب والخراج بفارس سبع سنين ففعل ذلك وكتب له عهده به وشرط على ولي العهد بعده أن يتمها له إن لم تتم في حياته","topic":"أخبار عبد يغوث ونسبه","topicNo":211,"sp":5,"spl":"رجع الخبر إلى سياقة حديث عبد يغوث والوقعة — أخبار ذات الخال"},
{"id":"b211-8","bab":"الجزء 16","sec":"قصة خالها","page":"ج16 ص370","text":"حدثني محمد بن يحيى الصولي قال حدثني محمد بن عبد الله العاصمي قال حدثني أحمد بن عبد الله طماس عن عبد الله وإبراهيم ابني العباس الصولي قالا كانت للرشيد جارية تعرف بذات الخال فدعته يوما فوعدها أن يصير إليها وخرج يريدها فاعترضته جارية فسألته أن يدخل إليها فدخل وأقام عندها فشق ذلك على ذات الخال وقالت والله لأطلبن له شيئا أغيظه به وكانت أحسن الناس وجها ولها خال على خدها لم ير الناس أحسن منه في موضعه فدعت بمقراض فقصت الخال الذي كان في خدها وبلغ ذلك\nالرشيد فشق عليه وبلغ منه فخرج من موضعه وقال للفضل بن الربيع انظر من بالباب من الشعراء فقال الساعة رأيت العباس بن الأحنف فقال أدخله فأدخله فعرفه الرشيد القصة وقال اعمل في هذا شيئا على معنى رسمه له فقال\n(تخلصت ممن لم يكن ذا حفيظة ... وملت إلى من لا يغيره حال)\n(فإن كان قطع الخال لما تطلعت ... الى غيرها نفسي فقد ظلم الخال)\nناه إبراهيم فنهض الرشيد إلى ذات الخال مسرعا مسترضيا لها وجعل هذين البيتين سببا وأمر للعباس بألفي دينار وأمر إبراهيم الموصلي فغناه في هذا الشعر أخبرني محمد بن يحيى الصولي قال حدثني محمد بن الفضل قال كان محمد بن موسى المنجم يعجبه التقسيم في الشعر ويشغف بجيد الأشعار فكان مما يعجبه قول نصيب\n(أيا بعل ليلى كيف تجمع سلمها ... وحربي وفيما بيننا شبت الحرب)\n(لها مثل ذنبي اليوم إن كنت مذنبا ... ولا ذنب لي إن كان ليس لها ذنب)\nروضه من - الطويل - والشعر لنصيب ويروى للمجنون ويروى\nلكعب بن مالك الخثعمي والغناء لمالك ثاني - ثقيل - بالوسطى عن عمرو قال وكان محمد بن موسى ينشد كثيرا للعباس بن الأحنف\n(ألا ليت ذات الخال تلقى من الهوى ... عشير الذي ألقى فيلتئم الشعب)\n(إذا رضيت لم يهنني ذلك الرضا ... لعلمي به أن سوف يتبعه العتب)\n(وأبكي إذا ما أذنبت خوف صدها ... وأسألها مرضاتها ولها الذنب)\n(وصالكم صرم وحبكم قلى ... وعطفكم صد وسلمكم حرب)\nيقول ما أحسن ما قسم حتى جعل بإزاء كل شيء ضده والله إن هذا لأحسن من تقسيمات إقليدس الغناء في هذه الأبيات الأربعة لإبراهيم الموصلي ثاني ثقيل بالوسطى عن الهشامي وكانت ذات الخال إحدى الثلاث الجواري اللواتي كان الرشيد يهواهن ويقول الشعر فيهن وهن سحر وضياء وخنث وفيهن يقول الرشيد\n(إن سحرا وضياء وخنث ... هن سحر وضياء وخنث)\n(أخذت سحر ولا ذنب لها ... ثلثي قلبي وترباها الثلث)\nدثني محمد بن يحيى الصولي قال حدثنا أحمد بن محمد الأسدي قال حدثنا أحمد بن عبد الله بن علي بن سويد بن منجوف السدوسي قال حدثني محمد بن إسماعيل بن صبيح قال وجه الرشيد إلى جاريته سحر لتصير إليه فاعتلت عليه ذلك اليوم بعلة\nثم جاءته من الغد فقال الرشيد\n(أيا من رد ودي أمس ... لا أعطيكه اليوما)\n(ولا والله لا أعطيك ... إلا الصد واللوما)\n(وإن كان بقلبي منك ... حب يمنع النوما)\n(أيا من سمته الوصل ... فأغلى المهر والسوما)\nال وفيهن يقول وقد قيل إن العباس بن الأحنف قالها على لسانه\n(ملك الثلاث الآنسات عناني ... وحللن من قلبي بكل مكان)\n(ما لي تطاوعني البرية كلها ... وأطيعهن وهن في عصياني)\n(ما ذاك إلا أن سلطان الهوى ... وبه عززن أعز من سلطاني)\nنته عريب - خفيف ثقيل - الأول بالوسطى","topic":"أخبار عبد يغوث ونسبه","topicNo":211,"sp":6,"spl":"قصة خالها","song":4},
{"id":"b211-9","bab":"الجزء 16","sec":"الرشيد وذات الخال","page":"ج16 ص373","text":"وروى أحمد بن أبي طاهر عن إسحاق قال وجه الرشيد إلى ذات الخال ليلة وقد مضى شطر الليل فحضرت فأخرج إلي جارية كأنها المهاة فأجلسها في حجره ثم قال غنني فغنته\n(جئن من الروم وقاليقلا ... يرفلن في المرط ولين الملا)\n(مقرطقات بصنوف الحلى ... يا حبذا البيض وتلك الحلى)\nاستحسنه وشرب عليه ثم استؤذن للفضل بن الربيع فأذن له فلما دخل قال ما وراءك في هذا الوقت قال كل خير يا أمير المؤمنين ولكن جرى الساعة لي سبب لم يجز لي كتمانه أمير المؤمنين قال وما ذاك قال أخرج إلي في هذا الوقت ثلاث جوار لي مكية ومدينية وعراقية فقبضت المدينية على ذكري فلما أنعظت وثبت المكية فقعدت عليه فقالت لها المدينية ما هذا التعدي ألم تعلمي أن مالكا حدثنا عن الزهري عن عبد الله بن ظالم عن سعيد بن زيد أن النبي قال من أحيا أرضا ميتة فهي له فقالت الأخرى أو لم تعلمي أن سفيان حدثنا عن أبي الزناد عن الأعرج عن أبي هريرة أن النبي قال الصيد لمن صاده لا لمن أثاره فدفعتهما العراقية عنه ووثبت عليه وقالت هذا لي وفي يدي حتى تصطلحا فضحك الرشيد وأمره بحملهن إليه ففعل وحظين عنده وفيهن يقول\n(ملك الثلاث الآنسات عناني ... وحللن من قلبي بكل مكان)\nدثنا محمد بن يحيى قال حدثنا الغلابي قال حدثني مهدي بن سابق قال حججنا مع الرشيد آخر حجة فكان الناس يتناشدون له في جواريه\n(ثلاث قد حللن حمى فؤادي ... ويعطين الرغائب من ودادي)\n(نظمت قلوبهن بخيط قلبي ... فهن قرابتي حتى التنادي)\n(فمن يك حل من قلب محلا ... فهن مع النواظر والسواد)\nومما قاله إبراهيم وغيره في ذات الخال وغنى فيه\n(أذات الخال أقصيت ... محبا بكم صبا)\n(فلا أنسى حياتي ما ... عبدت الدهر لي ربا)\n(وقد قلت أنيليني ... فقالت أفرق الذنبا)\nالشعر والغناء لإبراهيم - هزج - بالوسطى عن عمرو ومنها\n(أذات الخال قد طال ... بمن أسقمته الوجع)\n(وليس إلى سواكم في اللذي ... يلقى له فزع)\n(أما يمنعك الإسلام ... من قتلي ولا الورع)\n(وما ينفك لي فيك ... هوى تغتره خدع)\nلشعر والغناء لإبراهيم - هزج - بالوسطى عن عمرو ومنها\n(ثعلب يا هذا الكثير العبث ... بالله لما قلت لي عن خنث)\n(عن ظبية تميس في مشيتها ... أحسن من أبصرته في شعث)\n(فقال قالت قل له أنت امرؤ ... موكل فيما ترى بالعبث)\n(والله لولا خصلة أرقبها ... لقل في الدنيا لما بي لبثي)\nلشعر لإبراهيم وله فيه لحنان أحدهما - ثقيل - الأول عن أبي العنبس والآخر هزج بالبنصر عن عمرو وفيه لعريب - ثقيل - أول آخر وذكر حبش أن فيه لابن جامع هزجا آخر بالوسطى وذكر هارون بن الزيات أن حماد بن إسحاق حدثه عن أبيه\nأن ثعلبا هذا كان مملوكا لإبراهيم فقال هذه الأبيات في خنث جارية جزء بن مغول الموصلي وكانت مغنية محسنة وخاطب ثعلبا فيها مستخبرا له وذكر هارون بن محمد بن عبد الملك أن حماد بن إسحاق حدثه عن أبيه أنه قال في خنث جارية جزء بن مغول الموصلي وخاطب في شعره غلاما يقال له ثعلب وكانت خنث مغنية محسنة وكانت تعرف بذات الخال\n(ثعلب يا هذا الكثير الخبث ... بالله إلا قلت لي عن خنث)\nذكر الأبيات قال وقال له أيضا\n(أبد لذات الخال يا ثعلب ... قول امرىء في الحب لا يكذب)\n(إني أقول الحق فاستيقني ... كل امرىء في حبه يلعب)\nلشعر والغناء لإبراهيم له فيه لحنان - رمل - وخفيف ثقيل - عن ابن المكي ومنها\n(جزى الله خيرا من كلفت بحبه ... وليس به إلا المموه من حبي)\n(وقالوا قلوب العاشقين رقيقة ... فما بال ذات الخال قاسية القلب)\n(وقالوا لها هذا محبك معرضا ... فقالت أرى إعراضه أيسر الخطب)\n(فما هو إلا نظرة بتبسم ... فتنشب رجلاه ويسقط للجنب)\nمنها\n\n(إذا لم يكن حب ذات الخال عناني ... إذن فحولت في مسك ابن زيدان)\n(فإن هذي يمين ما حلفت بها ... إلا على الحق في سري وإعلاني)\nلشعر والغناء لإبراهيم - هزج - بالبنصر ومنها\n(لقد أخلو بذات الخال ... والحراس قد هجعوا)\n(فمن يبصر أبا الخطاب ... يطلبها ويتبع)\n(ألا لم تر محزونا ... تسنم صبره الجزع)\n(وقارعني ففزت بها ... وحازتها لي القرع)\nناه إبراهيم من رواية بذل عنه ولم تذكر طريقته","topic":"أخبار عبد يغوث ونسبه","topicNo":211,"sp":7,"spl":"الرشيد وذات الخال","song":8},
{"id":"b211-10","bab":"الجزء 16","sec":"إبراهيم الموصلي وذات الخال","page":"ج16 ص377","text":"قال علي بن محمد الهشامي حدثني جدي يعني ابن حمدون قال حدثني مخارق قال كنت عند إبراهيم الموصلي ومعي ابن زيدان صاحب البرامكة وإبراهيم يلاعبه بالشطرنج فدخل علينا إسحاق فقال له أبوه ما أفدت اليوم فقال أعظم فائدة سألني رجل ما أفخم كلمة في الفم فقلت لا إله إلا الله فقال له أبوه إبراهيم أخطأت هلا قلت دنيا ودينا فأخذ ابن زيدان الشاه فضرب به رأس إبراهيم وقال له يا زنديق أتكفر بحضرتي فأمر إبراهيم غلمانه فضربوا ابن زيدان ضربا شديدا فانصرف من ساعته إلى جعفر بن يحيى\nفحدثه بخبره قال وعلم إبراهيم أنه قد أخطأ وجنى فركب إلى الفضل بن يحيى فاستجار به فاستوهبه الفضل من جعفر فوهبه له فانصرف وهو يقول\n(إن لم يكن حب ذات الخال عناني ... إذا فحولت في مسك ابن زيدان)\n(فإن هذي يمين ما حلفت بها ... إلا على الصدق في سري وإعلاني)\nال وله في هذين البيتين صنعة وهي - هزج - منها\n(من يرحم محزونا ... بذات الخال مفتونا)\n(أبى فيها فما يسلو ... وكل الناس يسلونا)\n(فقد أودى به السقم ... وقد أصبح مجنونا)\n(فإن دام على هذا ... ثوى في اللحد مدفونا)\nلشعر والغناء لإبراهيم - خفيف ثقيل - عن الهشامي ومنها\n(لذات الخال أرقني ... خيال بات يلثمني)\n(بكى وجرى له دمع ... لما بالقلب من حزن)\n(فلا أنساه أو أنسى ... إذا أدرجت في كفني)\nلشعر والغناء لإبراهيم - خفيف رمل - بالوسطى عن الهشامي ومنها\n\n(هل علمت اليوم يا عاصم ... يا خير خدين)\n(أن ذات الخال تأتيني ... على رغم قرين)\n(لا تلمني إن ذات الخال ... دنياي وديني)\n(وإلى حفص خليلي ... ووزيري وأميني)\n(بحت لا أكتمه شيئا ... من الداء الدفين)\n(إن بي من حب ذات الخال ... شيئا كالجنون)\nيه لإبراهيم - هزج - بالوسطى عن ابن المكي ومنها\n(تقول ذات الخال ... لي يا خلي البال)\n(فقلت حاشاك من أن ... يكون حالك حالي)\n(أعرضت عني لما ... أوقعتني في الحبال)\n(إن الخلي هو الغافل ... الذي لا يبالي)\nإبراهيم من كتابه عن حبش فيه لحن وذكر ابن المكي أنه - رمل - ومنها\n(أما تعلم ذات الخال ... فوق الشفة العليا)\n(بأني لست أهوى غير ... هاشيئا من الدنيا)\n(وأني عن جميع الناس ... إلا عنهم أعمى)\n(وأني لو سقيت الده ... من ريقك لا أروى)\nالشعر والغناء لإبراهيم رمل بالوسطى عن عمرو وابن المكي وغيرهما\nوقد روي أما تعلم يا ذا الخال وهذا هو الصحيح ومنها\n(يا ليت شعري كيف ذات الخال ... أم أين تحسب حالها من حالي)\n(هل أنسين منها وضمت مرة ... رأسي إليها ثم قالت مالي)\n(ألزلة أقصيتني نفسي الفدا ... لك أم أطعت مقالة العذال)\n(والله ما استحسنت شيئا مونقا ... ألتذه إلا خطرت ببالي)\nلشعر والغناء لإبراهيم وله فيه لحنان هزج بالأصابع كلها عن ابن المكي - وثقيل - أول بالوسطى عن حبش ومنها\n(يا ليت شعري والنساء غوادر ... خلف العدات وفاؤهن قليل)\n(هل وصل ذات الخال يوما عائد ... فتزول لوعاتي وحر غليلي)\n(أم قد تناست عهدنا وأحالها ... عن ذاك ملك حال دون خليل)\nالشعر والغناء لإبراهيم من كتابه - ثقيل - أول بالبنصر عن إسحاق بن إبراهيم وابن المكي والهشامي انقضت أخبارها\n(إن من غره النساء بشيء ... بعد هند لجاهل مغرور)\n(حلوة القول واللسان ومر ... كل شيء أجن منها الضمير)\n(كل أنثى وإن بدا لك منها ... آية الحب حبها خيتعور)\nلشعر لحجر بن عمرو آكل المرار والغناء لحنين ثاني - ثقيل - بالبنصر عن الهشامي وفيه لنبيه - ثقيل - أول بالوسطى عن حبش وفيه - رمل - له","topic":"أخبار عبد يغوث ونسبه","topicNo":211,"sp":8,"spl":"إبراهيم الموصلي وذات الخال — نسب حجر بن عمرو والسبب الذي من أجله قال هذا الشعر","song":9},
{"id":"b211-11","bab":"الجزء 16","sec":"نسب حجر بن عمرو والسبب الذي من أجله قال هذا الشعر","page":"ج16 ص381","text":"هو حجر بن عمرو بن معاوية بن الحارث بن معاوية بن ثور بن مرتع واسمه عمرو بن ثور وقيل ابن معاوية بن ثور وهو كندة بن عفير بن عدي بن الحارث بن مرة بن ادد بن زيد بن يشجب بن عريب بن زيد بن كهلان بن سبأ بن يشجب بن يعرب بن قحطان","topic":"أخبار عبد يغوث ونسبه","topicNo":211,"sp":8,"spl":"إبراهيم الموصلي وذات الخال — نسب حجر بن عمرو والسبب الذي من أجله قال هذا الشعر"},
{"id":"b211-12","bab":"الجزء 16","sec":"حجر وزياد بن الهبولة","page":"ج16 ص382","text":"أخبرني بخبره محمد بن الحسن بن دريد إجازة قال حدثني عمي عن ابن الكلبي عن أبيه عن الشرقي بن القطامي قال أقبل تبع أيام سار إلى العراق فنزل بأرض معد فاستعمل عليهم حجر بن عمرو وهو آكل المرار فلم يزل ملكا حتى خرف وله من الولد عمرو ومعاوية وهو الجون ثم إن زياد بن الهبولة بن عمرو بن عوف بن ضجعم بن حماطة بن سعد بن سليح القضاعي أغار عليه وهو ملك في ربيعة بن نزار ومنزله بغمر ذي كندة وكان قد غزا بربيعة البحرين فبلغ زيادا غزاته فأقبل حتى أغار في مملكة حجر فأخذ مالا كثيرا وسبى امرأة حجر وهي هند ابنة ظالم بن وهب بن الحارث بن معاوية وأخذ نسوة من نساء بكر بن وائل فلما بلغ حجرا وبكر بن وائل مغاره وما أخذ أقبلوا معه ومعه يومئذ أشراف بكر بن وائل منهم عوف بن محلم بن ذهل بن شيبان وصليع بن عبد\nغنم بن ذهل بن شيبان وسدوس بن شيبان بن ذهل وضبيعة بن قيس بن ثعلبة وعامر بن مالك بن تيم الله بن ثعلبة فتعجل عمرو بن معاوية وعوف بن محلم قالا لحجر إنا متعجلان إلى الرجل لعلنا نأخذ منه بعض ما أصاب منا فلقياه دون عين أباغ فكلمه عوف بن محلم وقال يا خير الفتيان اردد علي ما أخذته مني فأعطاه إياه وكلمه عمرو بن معاوية في فحل إبله فقال خذه فأخذه عمرو وكان قويا فجعل الفحل ينزع إلى الإبل فاعتقله عمرو فصرعه فقال له ابن الهبولة أما والله يا بني شيبان لو كنتم تعتقلون الرجال كما تعتقلون الإبل لكنتم أنتم أنتم فقال عمرو أما والله لقد وهبت قليلا وشتمت جليلا ولقد جررت على نفسك شرا ولتجدني عند ما ساءك ثم ركض حتى صار إلى حجر فأخبره الخبر فأقبل حجر في أصحابه حتى إذا كان بمكان يقال له الحفير بالبر وهو دون عين أباغ بعث سدوسا وصليعا يتجسسان له الخبر ويعلمان له علم العسكر فخرجا حتى هجما على عسكره وقد أوقد نارا ونادى مناد له من جاء بحزمة من حطب فله فدرة من تمر وكان ابن الهبولة قد أصاب في عسكر حجر تمرا كثيرا فضرب قبابه وأجج ناره ونثر التمر بين يديه فمن جاء بحطب أعطاه تمرا فاحتطب سدوس وصليع ثم أتيا به ابن الهبولة فطرحاه بين يديه فناولهما من التمر وجلسا قريبا من القبة فأما صليع فقال هذه آية وعلم ما يريد فانصرف إلى حجر فأعلمه بعسكره وأراه التمر وأما سدوس فقال لا أبرح حتى آتيه بأمر جلي فلما ذهب هزيع من الليل أقبل ناس من أصحابه يحرسونه وقد تفرق أهل العسكر في كل ناحية فضرب سدوس\nبيده إلى جليس له فقال له من أنت مخافة أن يستنكر فقال أنا فلان ابن فلان قال نعم ودنا سدوس من القبة فكان حيث يسمع الكلام فدنا ابن الهبولة من هند امرأة حجر فقبلها وداعبها ثم قال لها فيما يقول ما ظنك الآن بحجر لو علم بمكاني منك قالت ظني به والله أنه لن يدع طلبك حتى يطالع القصور الحمر وكأني أنظر إليه في فوارس من بني شيبان يذمرهم ويذمرونه وهو شديد الكلب سريع الطلب يزبد شدقاه كأنه بعير آكل مرار فسمي حجر آكل المرار يومئذ قال فرفع يده فلطمها ثم قال ما قلت هذا إلا من عجبك به وحبك له فقالت والله ما أبغضت ذا نسمة قط بغضي له ولا رأيت رجلا قط أحزم منه نائما ومستيقظا إن كان لتنام عيناه وبعض أعضائه حي لا ينام وكان إذا أراد النوم أمرني أن أجعل عنده عسا مملوءا لبنا فبينا هو ذات ليلة نائم وأنا قريبة منه أنظر إليه إذ أقبل أسود سالخ إلى رأسه فنحى رأسه فمال إلى يديه وإحداهما مقبوضة والأخرى مبسوطة فأهوى إليها فقبضها فمال إلى رجليه وقد قبض واحدة وبسط الأخرى فأهوى إليها فقبضها فمال إلى العس شربه ثم مجه فقلت يستيقظ فيشرب فيموت فأستريح منه فانتبه من نومه فقال علي بالإناء فناولته فشمه فاضطربت يداه حتى سقط الإناء فأهريق وذلك كله بأذن سدوس فلما نامت الأحراس خرج يسري ليلته حتى صبح حجرا فقال\n(أتاك المرجفون برجم غيب ... على دهش وجئتك باليقين)\n(فمن يك قد أتاك بأمر لبس ... فقد آتي بأمر مستبين)","topic":"أخبار عبد يغوث ونسبه","topicNo":211,"sp":9,"spl":"حجر وزياد بن الهبولة"},
{"id":"b211-13","bab":"الجزء 16","sec":"حجر وزياد بن الهبولة","page":"ج16 ص382","text":"م قص عليه جميع ما سمع فأسف ونادى في الناس الرحيل فساروا حتى انتهوا إلى عسكر ابن الهبولة فاقتتلوا قتالا شديدا فانهزم أصحاب ابن الهبولة وعرفه سدوس فحمل عليه فاعتنقه وصرعه فقتله وبصر به عمرو بن معاوية فشد عليه فأخذ رأسه منه وأخذ سدوس سلبه وأخذ حجر هندا فربطها بين فرسين ثم ركضا بها حتى قطعاها قطعا هذه رواية ابن الكلبي وأما أبو عبيدة فإنه ذكر أن ابن الهبولة لما غنم عسكر حجر غنم مع ذلك زوجته هند بنت ظالم وأم أناس بنت عوف بن محلم الشيباني وهي أم الحارث بن حجر وهند بنت حجر ولابنها الحارث ابن يقال له عمرو وله يقول بشر بن أبي خازم\n(فإلى ابن أم أناس أعمل ناقتي ... عمرو فتنجح حاجتي أم ترجف)\n(ملك إذا نزل الوفود ببابه ... غرفوا غوارب مزبد ما ينزف)\nقال وبنتها هند هي التي تزوجها المنذر بن ماء السماء اللخمي قال وكان ابن الهبولة بعد أن غنم يسوق ما معه من السبايا والنعم ويتصيد في\nالمسير ولا يمر بواد إلا أقام به يوما أو يومين حتى أتى على ضرية فوجدها معشبة فأعجبته فأقام بها أياما وقالت له أم أناس إني لأرى ذات ودك وسوء درك كأني قد نظرت إلى رجل أسود أدلم كأن مشافره مشافر بعير آكل مرار قد أخذ برقبته فسمي حجر آكل المرار بذلك وذكر باقي القصة نحو ما مضى وقال في خبر ابن الهبولة إن سدوسا أسره وإن عمرو بن معاوية لما رآه معه حسده فطعنه فقتله فغضب سدوس لذلك وقال قتلت أسيري وديته دية الملوك وتحاكما إلى حجر فحكم لسدوس على عمرو وقومه بدية ملك وأعانهم في ذلك بماله وقال سدوس في ذلك يعاتب بني شيبان\n(ما بعدكم عيش ولا معكم ... عيش لذي أنف ولا حسب)\n(لولا بنو ذهل وجمع بني ... قيس وما جمعت من نشب)\n(ما سمتموني خطة غبنا ... وعلى ضرية رمتم غلبي)\nال وقد روي أن حجرا ليس بآكل المرار وإنما أبوه الحارث آكل المرار وروي أيضا أنه إنما سمي آكل المرار لأن سدوسا لما أتاه بخبر ابن الهبولة ومداعبته لهند وأن رأسه كان في حجرها وحدثه بقولها وقوله فجعل يسمع ذلك وهو يعبث بالمرار وهو نبت شديد المرارة وكان جالسا في موضع فيه منه شيء كثير فجعل يأكل من ذلك المرار غضبا وهو يسمع من سدوس ولا يعلم أنه يأكله من شدة الغضب حتى انتهى سدوس إلى آخر الحديث فعلم حينئذ بذلك ووجد طعمه فسمي يومئذ آكل المرار قال ابن الكلبي وقال حجر في هند\n(لمن النار أوقدت بحفير ... لم تنم عند مصطل مقرور)\n(أوقدتها إحدى الهنود وقالت ... أنت ذا موثق وثاق الأسير)\n(ان من غره النساء بشيء ... بعد هند لجاهل مغرور)\nبعده باقي الأبيات المذكورة متقدما وفيها الغناء\n(طرب الفؤاد وعاودت أحزانه ... وتفرقت فرقا به أشجانه)\n(وبدا له من بعد ما اندمل الهوى ... برق تألق موهنا لمعانه)\n(يبدو كحاشية الرداء ودونه ... صعب الذرى متمنع أركانه)\n(فالنار ما اشتملت عليه ضلوعه ... والماء ما جادت به أجفانه)\nلشعر لمحمد بن صالح العلوي والغناء لرذاذ ويقال إنه لبنان خفيف ثقيل وفيه ثقيل أول يقال إنه لأبي العنبس ويقال إنه للقاسم بن زرزور وفيه لعمرو الميداني - رمل - طنبوري وهو لحن مشهور","topic":"أخبار عبد يغوث ونسبه","topicNo":211,"sp":10,"spl":"حجر وزياد بن الهبولة","song":1},
{"id":"b212-1","bab":"الجزء 16","sec":"أخبار محمد بن صالح العلوي ونسبه","page":"ج16 ص388","text":"هو محمد بن صالح بن عبد الله بن موسى بن عبد الله بن حسن بن حسن بن علي بن أبي طالب ويكنى أبا عبد الله شاعر حجازي ظريف صالح الشعر من شعراء أهل بيته المتقدمين وكان جده موسى بن عبد الله أخا محمد وإبراهيم بن عبد الله بن حسن بن حسن الحجازيين الخارجين في أيام المنصور أمهم جميعا هند بنت أبي عبيدة أخبرني الحرمي بن أبي العلاء والطوسي قالا حدثنا الزبير بن بكار وأخبرني أحمد بن محمد بن سعيد الهمداني قال حدثنا يحيى بن الحسن العلوي قال حدثني الزبير بن بكار أن هندا حملت بموسى بن عبد الله ولها ستون سنة قال ولا تحمل لستين إلا قرشية ولا تحمل لخمسين إلا عربية قال وكان موسى آدم شديد الأدمة وله تقول أمه هند\n(إنك أن تكون جونا أنزعا ... أجدر أن تضرهم وتنفعا)\n(وتسلك العيش طريقا مهيعا ... فردا من الأصحاب أو مشيعا)\nكان موسى استتر بعد قتل أخويه زمانا ثم ظفر به أبو جعفر فضربه\nبالسوط وحبسه مدة ثم عفا عنه وأطلقه وله أخبار كثيرة ليس هذا موضعها","topic":"أخبار محمد بن صالح العلوي ونسبه","topicNo":212,"sp":0,"spl":"أخبار محمد بن صالح العلوي ونسبه — خروج محمد بن صالح على المتوكل"},
{"id":"b212-2","bab":"الجزء 16","sec":"خروج محمد بن صالح على المتوكل","page":"ج16 ص389","text":"وكان محمد بن صالح خرج على المتوكل مع من بيض في تلك السنة فظفر به وبجماعة من أهل بيته أبو الساج فأخذهم وقيدهم وقتل بعضهم وأخرب سويقة وهي منزل للحسنيين ومن جملة صدقات أمير المؤمنين علي بن أبي طالب صلوات الله عليه وقعر بها نخلا كثيرا وحرق منازل لهم بها وأثر فيهم آثارا قبيحة وحمل محمد بن صالح فيمن حمل منهم إلى سر من رأى فحبس ثلاث سنين ثم مدح المتوكل فأنشده الفتح قصيدته بعد أن غني في شعره المذكور فطرب وسأل عن قائله فعرفه وتلا ذلك إنشاد الفتح قصيدته فأمر بإطلاقه وأخبرني محمد بن خلف وكيع قال حدثني أحمد بن أبي خيثمة قال أنكر موسى بن عبد الله بن موسى على ابن أخيه محمد بن صالح بن عبد الله بن موسى بعض ما ينكره العمومة على بني أخيهم في شيء من أمور السلطان وكان محمد بن صالح قد خرج بسويقة فصار أبو الساج إلى سويقة فأسلمه عمه موسى وبنوه بعد أن أعطاه أبو الساج الأمان فطرح سلاحه ونزل إليه فقيده وحمله إلى سر من رأى فلم يزل محبوسا بها ثلاث سنين ثم أطلق وأقام بها إلى أن مات وكان سبب موته أنه جدر فمات في الجدري وهو الذي يقول في الحبس\n(طرب الفؤاد وعاودت أحزانه ... وتشعبت شعبا به أشجانه)\n(وبدا له من بعد ما اندمل الهوى ... برق تألق موهنا لمعانه)\n(يبدو كحاشية الرداء ودونه ... صعب الذرا متمنع أركانه)\n(فدنا لينظر كيف لاح فلم يطق ... نظرا إليه ورده سجانه)\n(فالنار ما اشتملت عليه ضلوعه ... والماء ما سحت به أجفانه)\n(ثم استعاذ من القبيح ورده ... نحو العزاء عن الصبا إيقانه)\n(وبدا له أن الذي قد ناله ... ما كان قدره له ديانه)\n(حتى اطمأن ضميره وكأنما ... هتك العلائق عامل وسنانه)\n(يا قلب لا يذهب بحلمك باخل ... بالنيل باذل تافه منانه)\n(يعد القضاء وليس ينجز موعدا ... ويكون قبل قضائه ليانه)\n(خدل الشوى حسن القوام مخصر ... عذب لماه طيب أردانه)\n(واقنع بما قسم الإله فأمره ... ما لا يزال على الفتى إتيانه)\n(والبؤس ماض ما يدوم كما مضى ... عصر النعيم وزال عنك أوانه)\nخبرني عمي قال حدثني أحمد بن أبي طاهر قال كنت مع أبي عبد الله محمد بن صالح في منزل بعض إخواننا فأقمنا إلى أن انتصف الليل وأنا أرى أنه يبيت فإذا هو قد قام فتقلد سيفه وخرج فأشفقت عليه من خروجه في ذلك الوقت وسألته المقام والمبيت وأعلمته خوفي عليه فالتفت إلي متبسما وقال\n(إذا ما اشتملت السيف والليل لم أهل ... لشيء ولم تقرع فؤادي القوارع)\nخبرني الحسين بن القاسم الكوكبي قال حدثني أحمد بن أبي طاهر قال مر محمد بن صالح بقبر لبعض ولد المتوكل فرأى الجواري يلطمن عنده فأنشدني لنفسه\n(رأيت بسامرا صبيحة جمعة ... عيونا يروق الناظرين فتورها)\n(تزور العظام الباليات لدى الثرى ... تجاوز عن تلك العظام غفورها)\n(فلولا قضاء الله أن تعمر الثرى ... الى أن ينادى يوم ينفخ صورها)\n(لقلت عساها أن تعيش وأنها ... ستنشر من جرا عيون تزورها)\n(أسيلات مجرى الدمع إما تهللت ... شؤون المآقي ثم سح مطيرها)\n(بوبل كأتوام الجمان يفيضه ... على نحرها أنفاسها وزفيرها)\n(فيا رحمة ما قد رحمت بواكيا ... ثقالا تواليها لطافا خصورها)","topic":"أخبار محمد بن صالح العلوي ونسبه","topicNo":212,"sp":0,"spl":"أخبار محمد بن صالح العلوي ونسبه — خروج محمد بن صالح على المتوكل"},
{"id":"b212-3","bab":"الجزء 16","sec":"أخبار زوجته حمدونة","page":"ج16 ص391","text":"أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني إبراهيم بن المدبر قال جاءني محمد بن صالح الحسني فسألني أن أخطب عليه بنت عيسى بن موسى بن أبي خالد الحري أو أخته حمدونة ففعلت ذلك وصرت إلى عيسى فسألته أن يجيبه فأبى وقال لي لا أكذبك والله ما أرده لأني لا أعرف أشرف وأشهر منه لمن يصاهره ولكني أخاف المتوكل وولده بعده على نعمتي ونفسي فرجعت إليه فأخبرته بذلك فأضرب عن ذلك مدة ثم عاودني بعد\nذلك وسألني معاودته فعاودته ورفقت به حتى أجاب فزوجه أخته فأنشدني بعد ذلك محمد\n(خطبت إلى عيسى بن موسى فردني ... فلله والي حرة وعليقها)\n(لقد ردني عيسى ويعلم أنني ... سليل بنات المصطفى وعريقها)\n(وإن لنا بعد الولادة نبعة ... نبي الإله صنوها وشقيقها)\n(فلما أبى بخلا بها وتمنعا ... وصيرني ذا خلة لا يطيقها)\n(تداركني المرء الذي لم يزل له ... من المكرمات رحبها وطليقها)\n(سمي خليل الله وابن وليه ... وحمال أعباء العلا وطريقها)\n(وزوجها والمن عندي لغيره ... فيا بيعة وقتني الربح سوقها)\n(ويا نعمة لابن المدبر عندنا ... يجد على كر الزمان أنيقها)\nال ابن مهرويه قال لي إبراهيم بن المدبر فلما نقلت حمدونة إليه شغف بها وكانت امرأة جميلة عاقلة فأنشدني لنفسه فيها\n(لعمر حمدونة إني بها ... لمغرم القلب طويل السقام)\n(مجاوز للقدر في حبها ... مباين فيها لأهل الملام)\n(مطرح للعذل ماض على ... مخافة النفس وهول المقام)\n(مشايعي قلب يخاف الخنا ... وصارم يقطع صم العظام)\n(جشمني ذلك وجدي بها ... وفضلها بين النساء الوسام)\n(ممكورة الساق ردينية ... مع الشوى الخدل وحسن القوام)\n(صامتة الحجل خفوق الحشا ... مائرة الساق ثقال القيام)\n(ساجية الطرف نؤوم الضحى ... منيرة الوجه كبرق الغمام)\n(زينها الله وما شانها ... وأعطيت منيتها من تمام)\n(تلك التي لولا غرامي بها ... كنت بسامرا قليل المقام)\nهكذا روى ابن مهرويه عن ابن المدبر في خبر محمد بن صالح وتزويجه حمدونة وحدثني عمي عن أبي جعفر بن الدهقانة النديم قال حدثني إبراهيم بن المدبر قال جاءني يوما محمد بن صالح الحسني العلوي بعد أن أطلق من الحبس فقال لي إني أريد المقام عندك اليوم على خلوة لأبثك من أمري شيئا لا يصلح أن يسمعه غيرنا فقلت أفعل فصرفت من كان بحضرتي وخلوت معه وأمرت برد دابته وأخذ ثيابه فلما اطمأن وأكلنا واضطجعنا قال لي أعلمك أني خرجت في سنة كذا وكذا ومعي أصحابي على القافلة الفلانية فقاتلنا من كان فيها فهزمناهم وملكنا القافلة فبينا أنا أحوزها وأنيخ الجمال إذ طلعت علي امرأة من العمارية ما رأيت قط أحسن منها وجها ولا أحلى منطقا فقالت يا فتى إن رأيت أن تدعو لي بالشريف المتولي أمر هذا الجيش فقلت وقد رأيته وسمع كلامك فقالت سألتك بحق الله وحق رسوله أنت هو فقلت نعم وحق الله وحق رسوله إني لهو فقالت أنا حمدونة بنت عيسى بن موسى بن أبي خالد الحري ولأبي محل من سلطانه ولنا نعمة إن كنت ممن سمع بها فقد كفاك ما سمعت وإن كنت لم تسمع بها فسل عنها غيري ووالله لا استأثرت عنك بشيء أملكه ولك بذلك عهد الله وميثاقه علي وما أسألك إلا أن تصونني وتسترني وهذه ألف دينار معي لنفقتي فخذها حلالا وهذا حلي علي من خمس مئة دينار فخذه وضمني ما شئت بعده","topic":"أخبار محمد بن صالح العلوي ونسبه","topicNo":212,"sp":1,"spl":"أخبار زوجته حمدونة"},
{"id":"b212-4","bab":"الجزء 16","sec":"أخبار زوجته حمدونة","page":"ج16 ص391","text":"خذه لك من تجار المدينة أو مكة أو أهل الموسم فليس منهم أحد يمنعني شيئا أطلبه وادفع عني واحمني من أصحابك ومن عار يلحقني فوقع قولها من قلبي موقعا عظيما فقلت لها قد وهب الله لك مالك وجاهك وحالك ووهب لك القافلة بجميع ما فيها ثم خرجت فناديت في أصحابي فاجتمعوا فناديت فيهم إني قد أجرت هذه القافلة وأهلها وخفرتها وحميتها ولها ذمة الله وذمة رسوله وذمتي فمن أخذ منها خيطا أو عقالا فقد آذنته بحرب فانصرفوا معي وانصرفت فلما أخذت وحبست بينا أنا ذات يوم في محبسي إذ جاءني السجان وقال لي إن بالباب امرأتين تزعمان أنهما من أهلك وقد حظر علي أن يدخل عليك أحد إلا أنهما أعطتاني دملج ذهب وجعلتاه لي إن أوصلتهما إليك وقد أذنت لهما وهما في الدهليز فاخرج إليهما إن شئت ففكرت فيمن يجيئني في هذا البلد وأنا به غريب لا أعرف أحدا ثم قلت لعلهما من ولد أبي أو بعض نساء أهلي فخرجت إليهما فإذا بصاحبتي فلما رأتني بكت لما رأت من تغير خلقي وثقل حديدي فأقبلت عليها الأخرى فقالت أهو هو فقالت إي والله إنه لهو هو ثم أقبلت علي فقالت فداك أبي وأمي والله لو استطعت أن أقيك مما أنت فيه بنفسي وأهلي لفعلت وكنت بذلك مني حقيقا ووالله لا تركت المعاونة لك والسعي في حاجتك وخلاصك بكل حيلة ومال وشفاعة وهذه دنانير وثياب وطيب فاستعن بها على موضعك ورسولي يأتيك في كل يوم بما يصلحك حتى يفرج الله عنك ثم أخرجت إلي كسوة وطيبا ومائتي دينار وكان رسولها يأتيني في كل يوم بطعام نظيف وتواصل برها بالسجان فلا يمتنع من كل شيء أريده فمن الله بخلاصي ثم راسلتها فخطبتها فقالت أما من جهتي فأنا لك متابعة مطيعة والأمر إلى أبي فأتيته فخطبتها إليه فردني وقال ما كنت لأحقق عليها ما قد شاع في الناس عنك في أمرها وقد صيرتها فضيحة فقمت\nمن عنده منكسا مستحيا وقلت له في ذلك\n(رموني وإياها بشنعاء هم بها ... أحق أدال الله منهم فعجلا)\n(بأمر تركناه ورب محمد ... عيانا فإما عفة أو تجملا)\nقلت له إن عيسى صنيعة أخي وهو لي مطيع وأنا أكفيك أمره فلما كان من الغد لقيت عيسى في منزله وقلت له قد جئتك في حاجة لي فقال مقضية ولو كنت استعملت ما أحبه لأمرتني فجئتك وكان أسر إلي فقلت له قد جئتك خاطبا إليك ابنتك فقال هي لك أمة وأنا لك عبد وقد أجبتك فقلت إني خطبتها على من هو خير مني أبا وأما وأشرف لك صهرا ومتصلا محمد بن صالح العلوي فقال لي يا سيدي هذا رجل قد لحقتنا بسببه ظنه وقيلت فينا أقوال فقلت أفليست باطلة قال بلى والحمد لله قلت فكأنها لم تقل وإذا وقع النكاح زال كل قول وتشنيع ولم أزل أرفق به حتى أجاب وبعثت إلى محمد بن صالح فأحضرته وما برحت حتى زوجته وسقت الصداق عنه","topic":"أخبار محمد بن صالح العلوي ونسبه","topicNo":212,"sp":2,"spl":"أخبار زوجته حمدونة"},
{"id":"b212-5","bab":"الجزء 16","sec":"مدحه إبراهيم بن المدبر","page":"ج16 ص395","text":"قال أبو الفرج الأصبهاني وقد مدح محمد بن صالح إبراهيم بن المدبر مدائح كثيرة لما أولاه من هذا الفعل ولصداقة كانت بينهما فمن جيد ما قاله فيه قوله\n(أتخبر عنهم الدمن الدثور ... وقد ينبي إذا سئل الخبير)\n(وكيف تبين الأنباء دار ... تعاقبها الشمائل والدبور)\nقول فيها في مدحه\n(فهلا في الذي أولاك عرفا ... تسدي من مقالك ما تنير)\n(ثناء غير مختلق ومدحا ... مع الركبان ينجد أو يغور)\n(أخ واساك في كلب الليالي ... وقد خذل الأقارب والنصير)\n(حفاظا حين أسلمك الموالي ... وضن بنفسه الرجل الصبور)\n(فإن تشكر فقد أولى جميلا ... وإن تكفر فإنك للكفور)\n(وما في آل خاقان اعتصام ... إذا ما عمم الخطب الكبير)\n(لئام الناس إثراء وفقرا ... وأعجزهم إذا حمي القتير)\n(قويم لا يزوجهم كريم ... ولا تسنى لنسوتهم مهور)\nإنما ذكر آل خاقان ههنا لأن عبيد الله بن يحيى قصر به وتحامل عليه وكان يقول ما يكره ويؤكد ما يوجب حبسه وكان فيه وفي ولده نصب شديد ولمحمد بن صالح في آل المدبر مدائح كثيرة لا معنى لذكرها في هذا الكتاب أخبرني علي بن العباس بن أبي طلحة الكاتب قال حدثني عبد الله بن طالب الكاتب قال كان محمد بن صالح العلوي حلو اللسان ظريفا أديبا فكان بسر من رأى مخالطا لسراة الناس ووجوه أهل البلد وكان لا يكاد يفارق سعيد بن\nحميد وكانا يتقارضان الأشعار ويتكاتبان بها وفي سعيد يقول محمد بن صالح العلوي\n(أصاحب من صاحبت ثمت أنثني ... إليك أبا عثمان عطشان صاديا)\n(أبى القلب أن يروى بهم وهو حائم ... إليك وإن كانوا الفروع العواليا)\n(ولكن إذا جئناك لم نبغ مشربا ... سواك وروينا العظام الصواديا)\nال عبد الله بن طالب وكان بعض بني هاشم دعاه فمضى إليه وكتب سعيد إليه يسأله المصير إليه فأخبر بموضعه عند الهاشمي فلما عاد عرف خبر سعيد وإرساله إليه فكتب إليه بهذه الأبيات قال عبد الله وشرب يوما هو وسعيد بن حميد فسكر محمد بن صالح قبله فقام لينصرف والتفت إلى سعيد وقال له\n(لعمرك إنني لما افترقنا ... أخو ضن بخلصاني سعيد)\n(تبقته المدام وأزعجتني ... إلى رحلي بتعجيل الورود)","topic":"أخبار محمد بن صالح العلوي ونسبه","topicNo":212,"sp":3,"spl":"مدحه إبراهيم بن المدبر — سعيد بن حميد يرثي صديقه محمد بن صالح"},
{"id":"b212-6","bab":"الجزء 16","sec":"سعيد بن حميد يرثي صديقه محمد بن صالح","page":"ج16 ص397","text":"قال وتوفي محمد بن صالح بسر من رأى وكان يجهد في أن يؤذن له في الرجوع إلى الحجاز فلا يجاب إلى ذلك فقال سعيد يرثيه\n(بأي يد أسطو على الدهر بعدما ... أبان يدي عضب الذبابين قاضب)\n(وهاض جناحي حادث جل خطبه ... وسدت عن الصبر الجميل المذاهب)\n(ومن عادة الأيام أن صروفها ... إذا سر منها جانب ساء جانب)\n(لعمري لقد غال التجلد أننا ... فقدناك فقد الغيث والعام جادب)\n(فما أعرف الأيام إلا ذميمة ... ولا الدهر إلا وهو بالثأر طالب)\n(ولا لي من الإخوان إلا مكاشر ... فوجه له راض ووجه مغاضب)\n(فقدت فتى قد كان للأرض زينة ... كما زينت وجه السماء الكواكب)\n(لعمري لئن كان الردى بك فاتني ... وكل امرىء يوما إلى الله ذاهب)\n(لقد أخذت مني النوائب حكمها ... فما تركت حقا علي النوائب)\n(ولا تركتني أرهب الدهر بعده ... لقد كل عني نابه والمخالب)\n(سقى جدثا أمسى الكريم ابن صالح ... يحل به دان من المزن ساكب)\n(إذا بشر الرواد بالغيث برقه ... مرته الصبا واستحلبته الجنائب)\n(فغادر باقي الدهر تأثير صوبه ... ربيعا زهت منه الربا والمذائب)\nخبرني أحمد بن جعفر جحظة قال حدثني المبرد قال لم يزل محمد بن صالح محبوسا حتى توصل بنان له بأن غنى بين يدي المتوكل في شعره\n(وبدا له من بعد ما اندمل الهوى ... برق تألق موهنا لمعانه)\nاستحسن المتوكل الشعر واللحن وسأل عن قائله فأخبر به وكلم في أمره وأحسنت الجماعة رفده وقام الفتح بأمره قياما تاما فأمر بإطلاقه من حبسه على أن يكون عند الفتح وفي يده حتى يقيم كفيلا بنفسه ألا يبرح من سر من رأى فأطلق وأخذ عليه الفتح الأيمان الموثقة ألا يبرح من سر من رأى إلا بإذنه ثم أطلقه","topic":"أخبار محمد بن صالح العلوي ونسبه","topicNo":212,"sp":3,"spl":"مدحه إبراهيم بن المدبر — سعيد بن حميد يرثي صديقه محمد بن صالح"},
{"id":"b212-7","bab":"الجزء 16","sec":"مدحه المتوكل والمنتصر وهجاؤه أبا الساج","page":"ج16 ص399","text":"ولمحمد بن صالح في المتوكل والمنتصر مدائح جياد كثيرة منها قوله في المتوكل\n(ألف التقى ووفى بنذر الناذر ... وأبى الوقوف على المحل الداثر)\n(ولقد تهيج له الديار صبابة ... حينا وتكلف بالخليط السائر)\n(فرأى الهداية أن أناب وأنه ... قصر المديح على الإمام العاشر)\n(يابن الخلائف والذين بهديهم ... ظهر الوفاء وبان غدر الغادر)\n(وابن الذين حووا تراث محمد ... دون الأقارب بالنصيب الوافر)\n(نطق الكتاب لكم بذاك مصدقا ... ومضت به سنن النبي الطاهر)\n(ووصلت أسباب الخلافة بالهدى ... إذ نلتها وأنمت عين الساهر)\n(أحييت سنة من مضى فتجددت ... وأبنت بدعة ذي الضلال الخاسر)\n(فافخر بنفسك أو بجدك معلنا ... أو دع فقد جاوزت فخر الفاخر)\n(ما للمكارم غيركم من أول ... بعد النبي وما لها من آخر)\n(إني دعوتك فاستجبت لدعوتي ... والموت مني قيد شبر الشابر)\n(فانتشتني من قعر موردة الردى ... أمنا ولم تسمع مقالة زاجر)\n(وفككت أسري والبلاء موكل ... وجبرت كسرا ما له من جابر)\n(وعطفت بالرحم التي ترجو بها ... قرب المحل من المليك القادر)\n(وأنا أعوذ بفضل عفوك أن أرى ... غرضا ببابك للملم الفاقر)\n(أو أن أضيع بعدما أنقذتني ... من ريب مهلكة وجد عاثر)\n(ولقد مننت فكنت غير مكدر ... ولقد نهضت بها نهوض الشاكر)\nأخبرني أحمد بن عبيد الله بن عمار ومحمد بن خلف بن وكيع قالا حدثنا الفضل بن سعيد بن أبي حرب قال حدثني أبو عبد الله الجهني قال\nدخلت على محمد بن صالح الحسني في حبس المتوكل فأنشدني لنفسه يهجو أبا الساج\n(ألم يحزنك يا ذلفاء أني ... سكنت مساكن الأموات حيا)\n(وأن حمائلي ونجاد سيفي ... علون مجدعا أشروسنيا)\n(فقصرهن لما طلن حتى أستوين ... عليه لا أمسى سويا)\n(أما والراقصات بذات عرق ... تريد البيت تحسبها قسيا)\n(لو أمكنني غداتئذ جلاد ... لألفوني به سمحا سخيا)\nقال ابن عمار وأنشدني عبيد الله بن طاهر أبو محمد لمحمد بن صالح أيضا\n(نظرت ودوني ماء دجلة موهنا ... بمطروفة الإنسان محسورة جدا)\n(لتؤنس لي نارا بليل توقدت ... وتالله ما كلفتها نظرا قصدا)\n(فلو أنها منها لقلت كأنني ... أرى النار قد أمست تضيء لنا هندا)\n(تضيء لنا منها جبينا ومحجرا ... ومبتسما عذبا وذا غدر جعدا)\nنقضت أخباره\n(يا عديا لقلبك المهتاج ... أن عفا رسم منزل بالنباج)\n(غيرته الصبا وكل ملث ... دائم الودق ذي أهاضيب داج)\n(وحملنا غلامنا ثم قلنا ... هاجر العيس ليس منك بناج)\n(فانتحى مثل ما انتحى باز دجن ... جوعته القناص للدراج)\nلشعر لأبي دواد الإيادي والغناء لحنين ثاني - ثقيل - بالبنصر في مجراها عن إسحاق وذكر عمرو بن بانة أنه لابن عائشة وفيه لعريب - هزج - وفيه - ثقيل - أول ينسب إلى يزيد الحذاء وإلى أحمد النصيبي","topic":"أخبار محمد بن صالح العلوي ونسبه","topicNo":212,"sp":4,"spl":"مدحه المتوكل والمنتصر وهجاؤه أبا الساج","song":1},
{"id":"b213-1","bab":"الجزء 16","sec":"ذكر أخبار أبي دواد الإيادي ونسبه","page":"ج16 ص402","text":"هو فيما ذكر يعقوب بن السكيت جارية بن الحجاج وكان الحجاج يلقب حمران بن بحر بن عصام بن منبه بن حذاقة بن زهير بن إياد بن نزار بن معد وقال ابن حبيب هو جارية بن الحجاج أحد بني برد بن دعمي بن إياد بن نزار شاعر قديم من شعراء الجاهلية وكان وصافا للخيل وأكثر أشعاره في وصفها وله في غير وصفها تصرف بين مدح وفخر وغير ذلك إلا أن شعره في وصف الفرس أكثر أخبرني الحسين بن يحيى عن حماد عن أبيه قال حدثني الهيثم بن عدي وابن الكلبي عن أبيه والشرقي أن أبا دواد الإيادي مدح الحارث بن همام بن مرة بن ذهل بن شيبان فأعطاه عطايا كثيرة ثم مات ابن لأبي دواد وهو في جواره فوداه فمدحه أبو دواد فحلف له الحارث أنه لا يموت له ولد إلا وداه ولا يذهب له مال إلا أخلفه فضربت العرب المثل بجار أبي دواد وفيه يقول قيس بن زهير\n(أطوف ما أطوف ثم آوي ... إلى جار كجار أبي دواد)\nذه رواية هؤلاء وأبو عبيدة يخالف ذلك أخبرني ابن دريد قال أخبرني أبو حاتم عن أبي عبيدة قال جاور أبو دواد الإيادي كعب بن مامة الإيادي فكان إذا هلك له بعير أو شاة أخلفها\nوفيه يقول طرفة يمدح عمرو بن هند\n(جار كجار الحذاقي الذي انتصفا ... )\nكان لأبي دواد ابن يقال له دواد شاعر وهو الذي يقول يرثي أباه\n(فبات فينا وأمسى تحت هائرة ... ما بعد يومك من ممسى وإصباح)\n(لا يدفع السقم إلا أن نفديه ... ولو ملكنا مسكنا السقم بالراح)\nخبرني عمي قال حدثنا عبد الله بن أبي سعد قال حدثني علي بن الصباح قال أخبرنا أبو المنذر عن أبيه قال تزوج أبو دواد امرأة من قومه فولدت له دوادا ثم ماتت ثم تزوج أخرى فأولعت بدواد وأمرت أباه أن يجفوه ويبعده وكان يحبها فلما أكثرت عليه قالت أخرجه عني فخرج به وقد أردفه خلفه إلى أن انتهى إلى أرض جرداء ليس فيها شيء فألقى سوطه متعمدا وقال أي دواد انزل فناولني سوطي فنزل فدفع بعيره وناداه\n(أدواد إن الأمر أصبح ما ترى ... فانظر دواد لأي أرض تعمد)\nقال له دواد على رسلك فوقف له فناداه\n(وبأي ظنك أن أقيم ببلدة ... جرداء ليس بغيرها متلدد)\nفرجع إليه وقال له أنت والله ابني حقا ثم رده إلى منزله وطلق امرأته\nأخبرني الحسين بن يحيى عن حماد عن أبيه عن أبي عمرو الشيباني قال كانت لأبي دواد امرأة يقال لها أم حبتر وفيها يقول\n(في ثلاثين ذعذعتها حقوق ... أصبحت أم حبتر تشكوني)\n(زعمت لي بأنني أفسد المال ... وأزويه عن قضاء ديوني)\n(أملت أن أكون عبدا لمالي ... وتهنا بنافع المال دوني)\nهي طويلة قال ولها يقول وقد عاتبته على سماحته بماله فلم يعتبها فصرمته\n(حاولت حين صرمتني ... والمرء يعجز لا محاله)\n(والدهر يلعب بالفتى ... والدهر أروغ من ثعاله)\n(والمرء يكسب ماله ... والشح يورثه الكلاله)\n(والعبد يقرع بالعصا ... والحر تكفيه المقاله)\n(والسكت خير للفتى ... فالحين من بعض المقاله)","topic":"ذكر أخبار أبي دواد الإيادي ونسبه","topicNo":213,"sp":0,"spl":"ذكر أخبار أبي دواد الإيادي ونسبه","partial":1},
{"id":"b213-2","bab":"الجزء 16","sec":"أبو دواد شاعر الخيل","page":"ج16 ص404","text":"أخبرني يحيى بن علي بن يحيى قال حدثني أبي عن إسحاق عن الأصمعي قال ثلاثة كانوا يصفون الخيل لا يقاربهم أحد طفيل وأبو دواد\nوالجعدي فأما أبو دواد فإنه كان على خيل المنذر بن النعمان بن المنذر وأما طفيل فإنه كان يركبها وهو أغرل إلى أن كبر وأما الجعدي فإنه سمع ذكرها من أشعار الشعراء فأخذ عنهم أخبرني محمد بن الحسن بن دريد قال حدثني أبو حاتم عن أبي عبيدة قال أبو دواد أوصف الناس للفرس في الجاهلية والإسلام وبعده طفيل الغنوي والنابغة الجعدي أخبرني محمد بن العباس اليزيدي قال حدثنا أحمد بن الحارث الخراز عن ابن الأعرابي قال لم يصف أحد قط الخيل إلا احتاج إلى أبي دواد ولا وصف الخمر إلا احتاج إلى أوس بن حجر ولا وصف أحد نعامة إلا احتاج إلى علقمة بن\nعبدة ولا اعتذر أحد في شعره إلا احتاج إلى النابغة الذبياني أخبرني عمي قال حدثني جعفر بن محمد العاصمي قال حدثنا عيينة بن المنهال قال حدثنا شداد بن عبيد الله قال حدثني عبيد الله بن الحر العنزي القاضي عن أبي عرادة قال كان علي صلوات الله عليه يفطر الناس في شهر رمضان فإذا فرغ من العشاء تكلم فأقل وأوجز فأبلغ فاختصم الناس ليلة حتى ارتفعت أصواتهم في أشعر الناس فقال علي عليه السلام لأبي الأسود الدؤلي قل يا أبا الأسود فقال أبو الأسود وكان يتعصب لأبي دواد الإيادي أشعرهم الذي يقول\n(ولقد أغتدي يدافع ركني ... أحوزي ذو ميعة إضريج)\n(مخلط مزيل مكر مفر ... منفح مطرح سبوح خروج)\n(سلهب شرجب كأن رماحا ... حملته وفي السراة دموج)\nكان لأبي الأسود رأي في أبي دواد فأقبل علي على الناس فقال كل شعرائكم محسن ولو جمعهم زمان واحد وغاية واحدة ومذهب واحد في\nالقول لعلمنا أيهم أسبق إلى ذلك وكلهم قد أصاب الذي أراد وأحسن فيه وإن يكن أحد فضلهم فالذي لم يقل رغبة ولا رهبة امرؤ القيس بن حجر فإنه كان أصحهم بادرة وأجودهم نادرة","topic":"ذكر أخبار أبي دواد الإيادي ونسبه","topicNo":213,"sp":1,"spl":"أبو دواد شاعر الخيل — أبو دواد يخالف مذاهب الشعراء"},
{"id":"b213-3","bab":"الجزء 16","sec":"أبو دواد يخالف مذاهب الشعراء","page":"ج16 ص407","text":"أخبرنا يحيى بن علي بن يحيى عن أبيه عن إسحاق عن الأصمعي قال كانت الرواة لا تروي شعر أبي دواد ولا عدي بن زيد لمخالفتهما مذاهب الشعراء قال وكان أبو دواد على خيل المنذر بن ماء السماء فأكثر وصفه للخيل أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثنا عبد الله بن أبي سعد قال حدثني ابن أبي الهيذام قال اسم أبي دواد الإيادي جويرية بن الحجاج وكانت له ناقة يقال لها الزباء فكانت بنو إياد يتبركون بها فلما أصابتهم السنة تفرقوا ثلاث فرق فرقة سلكت في البحر فهلكت وفرقة قصدت اليمن فسلمت وفرقة قصدت أرض بكر بن وائل فنزلوا على الحارث بن همام\nوكان السبب في ذلك أنهم أرسلوا الزباء وقالوا إنها ناقة ميمونة فخلوها فحيث توجهت فاتبعوها وكذلك كانوا يفعلون إذا أرادوا نجعة فخرجت تخوض العرب حتى بركت بفناء الحارث بن همام وكان أكرم الناس جوارا وهو جار أبي دواد المضروب به المثل فقال أبو دواد يمدح الحارث ويذكر ناقته الزباء\n(فإلى ابن همام بن مرة اصعدت ... ظعن الخليط بهم فقل زيالها)\n(أنعمت نعمة ماجد ذي منة ... نصبت عليه من العلا أظلالها)\n(وجعلتنا دون الولي فأصبحت ... زباء منقطعا إليك عقالها)\nخبرني أحمد بن عبيد الله بن عمار قال حدثنا سليمان بن أبي شيخ قال حدثنا يحيى بن سعيد قال كانت إياد تفخر على العرب تقول منا أجود الناس كعب بن مامة ومنا أشعر الناس أبو دواد ومنا أنكح الناس ابن ألغز أخبرني محمد بن العباس اليزيدي قال حدثنا عيسى بن إسماعيل تينة قال حدثني القحذمي قال كان ابن ألغز أيرا فكان إذا أنعظ احتكت الفصال بأيره قال وكان في إياد امرأة تستصغر أيور الرجال فجامعها ابن ألغز فقالت يا معشر إياد\nأبالركب تجامعون النساء قال فضرب بيده على أليتها وقال ما هذا فقالت وهي لا تعقل ما تقول هذا القمر فضرب العرب بها المثل أريها استها وتريني القمر وأنشد وقد كان الحجاج منع من لحوم البقر خوفا من قلة العمارة في السواد فقيل فيه\n(شكونا إليه خراب السواد ... فحرم فينا لحوم البقر)\n(فكنا كمن قال من قبلنا ... أريها استها وتريني القمر)","topic":"ذكر أخبار أبي دواد الإيادي ونسبه","topicNo":213,"sp":1,"spl":"أبو دواد شاعر الخيل — أبو دواد يخالف مذاهب الشعراء"},
{"id":"b213-4","bab":"الجزء 16","sec":"رأي الحطيئة في أبي دواد","page":"ج16 ص409","text":"أخبرني عمي عن الكراني عن العمري عن الهيثم بن عدي بنحوه وأخبرني عمي قال حدثنا محمد بن سعد الكراني قال حدثني العمري عن لقيط قال أخبرني التوزي عن أبي عبيدة قال كان الحطيئة عند سعيد بن العاص ليلة فتذاكروا الشعراء وفضلوا بعضهم على بعض وهو ساكت فقال له يا أبا مليكة ما تقول فقال ما ذكرتم والله أشعر الشعراء ولا أنشدتم أجود الشعر فقالوا فمن أشعر الناس فقال الذي يقول\n(لا أعد الإقتار عدما ولكن ... فقد من قد رزئته الإعدام)\nالشعر لأبي دواد الإيادي قالوا ثم من قال ثم عبيد بن الأبرص\nقالوا ثم من قال كفاكم والله بي إذا أخذتني رغبة أو رهبة ثم عويت في إثر القوافي عواء الفصيل في إثر أمه أخبرني محمد بن الحسن بن دريد قال حدثنا عبد الرحمن ابن أخي الأصمعي قال حدثنا عمي وأخبرنا أبو حاتم قال أخبرنا الأصمعي عن أبي عمرو بن العلاء عن هجاس بن مرير الإيادي عن أبيه وكان قد أدرك الجاهلية قال بينا أبو دواد وزوجته وابنه وابنته على ربوة وإياد إذ ذاك بالسواد إذ خرج ثور من أجمة فقال أبو دواد\n(وبدت له أذن توجس ... حرة وأحم وارد)\n(وقوائم عوج لها ... من خلفها زمع زوائد)\n(كمقاعد الرقباء للضرباء ... أيديهم نواهد)\nم قال أنفذي يا أم دواد فقالت\n(وبدت له أذن توجس ... حرة وأحم مولق)\n(وقوائم عوج لها ... من خلفها زمع معلق)\n(كمقاعد الرقباء ... للضرباء أيديهم تألق)\nم قال أنفذ يا دواد فقال\n(وبدت له أذن توجس ... حرة وأحم مرهف)\n(وقوائم عوج لها ... من خلفها زمع ملفف)\n(كمقاعد الرقباء للضرباء ... أيديهم تلقف)\nثم قال أنفذي يا دوادة قالت وما أقول مع من أخطأ قالوا ومن أين أخطأناه قالت جعلتم له قرنا واحدا وله قرنان قالوا فقولي قالت\n(وبدت له أذن توجس ... حرة وأحمتان)\n(وقوائم عوج لها ... من خلفها زمع ثمان)\n(كمقاعد الرقباء للضرباء ... أيديهم دوان)\nخبرني محمد بن الحسن بن دريد قال أخبرني عمي عن العباس بن هشام عن أبيه قال كان أبو دواد الإيادي الشاعر جارا للمنذر بن ماء السماء وإن أبا دواد نازع رجلا بالحيرة من بهراء يقال له رقبة بن عامر بن كعب بن عمرو فقال له رقبة صالحني وحالفني فقال أبو دواد فمن أين تعيش إياد إذا فوالله لولا ما تصيب من بهراء لهلكت وانصرفا على تلك الحال ثم إن أبا دواد أخرج بنين له ثلاثة في تجارة إلى الشام فبلغ ذلك رقبة البهراني فبعث إلى قومه فأخبرهم بما قال له أبو دواد عند المنذر وأخبرهم أن القوم ولد أبي دواد فخرجوا إلى الشام فلقوهم فقتلوهم وبعثوا برؤوسهم إلى رقبة فلما أتته الرؤوس صنع طعاما كثيرا ثم أتى المنذر فقال له قد اصطنعت لك طعاما كثيرا فأنا أحب أن تتغدى عندي فأتاه المنذر وأبو دواد معه فبينا الجفان ترفع وتوضع إذا جاءته جفنة عليها بعض رؤوس بني أبي دواد فوثب وقال أبيت اللعن إني جارك وقد ترى ما صنع بي وكان رقبة أيضا جارا للمنذر فوقع المنذر منهما في سوءة وأمر برقبة فحبس وقال لأبي دواد أما يرضيك توجيهي بكتيبتي الشهباء والدوسر إليهم قال بلى قال قد فعلت فوجه إليهم بالكتيبتين\nفلما بلغ ذلك رقبة قال لامرأته ويحك الحقي بقومك فأنذريهم فعمدت إلى بعض إبل زوجها فركبته ثم خرجت حتى أتت قومها فلما قربت منهم تعرت من ثيابها وصاحت وقالت أنا النذير العريان فأرسلتها مثلا فعرف القوم ما تريد فصعدوا إلى أعالي الشأم وأقبلت الكتيبتان فلم تصيبا منهم أحدا فقال المنذر لأبي دواد قد رأيت ما كان منهم وأنا أدي كل ابن لك بمئتي بعير فأمر له بست مئة بعير فرضي بذلك فقال فيه قيس بن زهير العبسي\n(سأفعل ما بدا لي ثم آوي ... الى جار كجار أبي دواد)\n\n(وركب كأطراف الأسنة عرسوا ... على مثلها والليل داج غياهبه)\n(لأمر عليهم أن تتم صدوره ... وليس عليهم أن تتم عواقبه)\nالشعر لأبي تمام الطائي والغناء للقاسم بن زرزور ثاني - ثقيل - بالوسطى في مجرى البنصر وفيه لجعفر بن رفعة خفيف ثقيل أخبرني إبراهيم بن القاسم بن زرزور عن أبيه وحدثني المظفر بن كيغلغ عن القاسم أيضا\nأن المكتفي بالله أخرج إليهم هذين البيتين بالرقة في رقعة وهو أمير وأمر أن يصنع فيهما لحن فصنع القاسم هذا اللحن وصنع جعفر خفيف الثقيل","topic":"ذكر أخبار أبي دواد الإيادي ونسبه","topicNo":213,"sp":2,"spl":"رأي الحطيئة في أبي دواد","song":1},
{"id":"b214-1","bab":"الجزء 16","sec":"أخبار أبي تمام ونسبه","page":"ج16 ص414","text":"أبو تمام حبيب بن أوس الطائي من نفس طيىء صليبة مولده ومنشؤه منبج بقرية منها يقال لها جاسم شاعر مطبوع لطيف الفطنة دقيق المعاني غواص على ما يستصعب منها ويعسر متناوله على غيره وله مذهب في المطابق هو كالسابق إليه جميع الشعراء وإن كانوا قد فتحوه قبله وقالوا القليل منه فإن له فضل الإكثار فيه والسلوك في جميع طرقه والسليم من شعره النادر شيء لا يتعلق به أحد وله أشياء متوسطة ورديئة رذلة جدا وفي عصرنا هذا من يتعصب له فيفرط حتى يفضله على كل سالف وخالف وأقوام يتعمدون الرديء من شعره فينشرونه ويطوون محاسنه ويستعملون القحة والمكابرة في ذلك ليقول الجاهل بهم إنهم لم يبلغوا علم هذا وتمييزه إلا بأدب فاضل وعلم ثاقب وهذا مما يتكسب به كثير من أهل هذا الدهر ويجعلونه وما جرى مجراه من ثلب الناس وطلب معايبهم سببا للترفع وطلبا للرياسة وليست إساءة من أساء في القليل وأحسن في الكثير مسقطة إحسانه ولو كثرت إساءته أيضا ثم أحسن لم يقل له عند الإحسان أسأت ولا عند الصواب أخطأت والتوسط في كل شيء أجمل والحق أحق أن يتبع وقد روي عن بعض الشعراء أن أبا تمام أنشده قصيدة له أحسن في\nجميعها إلا في بيت واحد فقال له يا أبا تمام لو ألقيت هذا البيت ما كان في قصيدتك عيب فقال له أنا والله أعلم منه مثل ما تعلم ولكن مثل شعر الرجل عنده مثل أولاده فيهم الجميل والقبيح والرشيد والساقط وكلهم حلو في نفسه فهو وإن أحب الفاضل لم يبغض الناقص وإن هوي بقاء المتقدم لم يهو موت المتأخر واعتذاره بهذا ضد لما وصف به نفسه في مدحه الواثق حيث يقول\n(جاءتك من نظم اللسان قلادة ... سمطان فيها اللؤلؤ المكنون)\n(أحذاكها صنع اللسان يمده ... جفر إذا نضب الكلام معين)\n(ويسيء بالإحسان ظنا لا كمن ... هو بابنه وبشعره مفتون)\nفلو كان يسيء بالإساءة ظنا ولا يفتتن بشعره كنا في غنى عن الاعتذار له وقد فضل أبا تمام من الرؤساء والكبراء والشعراء من لا يشق الطاعنون عليه غباره ولا يدركون - وإن جدوا - آثاره وما رأى الناس بعده إلى حيث انتهوا له في جيده نظيرا ولا شكلا ولولا أن الرواة قد أكثروا في الاحتجاج له وعليه وأكثر متعصبوه الشرح لجيد شعره وأفرط معادوه في التسطير لرديئه والتنبيه على رذله ودنيئه لذكرت منه طرفا ولكن قد أتى من ذلك ما لا مزيد عليه","topic":"أخبار أبي تمام ونسبه","topicNo":214,"sp":0,"spl":"أخبار أبي تمام ونسبه"},
{"id":"b214-2","bab":"الجزء 16","sec":"المعجبون بشعره كثيرون","page":"ج16 ص415","text":"أخبرني عمي قال حدثني أبي قال سمعت محمد بن عبد الملك الزيات يقول أشعر الناس طرا الذي يقول\n(وما أبالي وخير القول أصدقه ... حقنت لي ماء وجهي أو حقنت دمي)\nأحببت أن أستثبت إبراهيم بن العباس وكان في نفسي أعلم من\nمحمد وآدب فجلست إليه وكنت أجرى عنده مجرى الولد فقلت له من أشعر أهل زماننا هذا فقال الذي يقول\n(مطر أبوك أبو أهلة وائل ... ملأ البسيطة عدة وعديدا)\n(نسب كأن عليه من شمس الضحى ... نورا ومن فلق الصباح عمودا)\n(ورثوا الأبوة والحظوظ فأصبحوا ... جمعوا جدودا في العلا وجدودا)\nاتفقا على أن أبا تمام أشعر أهل زمانه أخبرني محمد بن يحيى الصولي وعلي بن سليمان الأخفش قالا حدثنا محمد بن يزيد النحوي قال قدم عمارة بن عقيل بغداد فاجتمع الناس إليه فكتبوا شعره وشعر أبيه وعرضوا عليه الأشعار فقال بعضهم ها هنا شاعر يزعم قوم أنه أشعر الناس طرا ويزعم غيرهم ضد ذلك فقال أنشدوني قوله فأنشدوه\n(غدت تستجير الدمع خوف نوى غد ... وعاد قتادا عندها كل مرقد)\n(وأنقذها من غمرة الموت أنه ... صدود فراق لا صدود تعمد)\n(فأجرى لها الإشفاق دمعا موردا ... من الدم يجري فوق خد مورد)\n(هي البدر يغنيها تودد وجهها ... الى كل من لاقت وإن لم تودد)\nثم قطع المنشد فقال له عمارة زدنا من هذا فوصل نشيده وقال\n(ولكنني لم أحو وفرا مجمعا ... ففزت به إلا بشمل مبدد)\n(ولم تعطني الأيام نوما مسكنا ... ألذ به إلا بنوم مشرد)\nقال عمارة لله دره لقد تقدم في هذا المعنى من سبقه إليه على كثرة القول فيه حتى لقد حبب إلي الاغتراب هيه فأنشده\n(وطول مقام المرء في الحي مخلق ... لديباجتيه فاغترب تتجدد)\n(فإني رأيت الشمس زيدت محبة ... الى الناس أن ليست عليهم بسرمد)\nقال عمارة كمل والله لئن كان الشعر بجودة اللفظ وحسن المعاني واطراد المراد واتساق الكلام فإن صاحبكم هذا أشعر الناس أخبرني محمد بن يحيى الصولي قال حدثني محمد بن موسى بن حماد قال سمعت علي بن الجهم يصف أبا تمام ويفضله فقال له رجل والله لو كان أبو تمام أخاك ما زدت على مدحك هذا فقال إن لم يكن أخا بالنسب فإنه أخ بالأدب والمودة أما سمعت ما خاطبني به حيث يقول\n(إن يكد مطرف الإخاء فإننا ... نغدو ونسري في إخاء تالد)\n(أو يختلف ماء الوصال فماؤنا ... عذب تحدر من غمام واحد)\n(أو يفترق نسب يؤلف بيننا ... أدب أقمناه مقام الوالد)\nأخبرني محمد قال حدثني هارون بن عبد الله المهلبي قال كنا في حلقة دعبل فجرى ذكر أبي تمام فقال دعبل كان يتتبع معاني فيأخذها فقال له رجل في مجلسه وأي شيء من ذلك أعزك الله قال قولي\n(وإن امرأ أسدى إلي بشافع ... إليه ويرجو الشكر مني لأحمق)\n(شفيعك فاشكر في الحوائج إنه ... يصونك عن مكروهها وهو يخلق)\nقال الرجل فكيف قال أبو تمام فقال قال\n(فلقيت بين يديك حلو عطائه ... ولقيت بين يدي مر سؤاله)\n(وإذا امرؤ أسدى إليك صنيعة ... من جاهه فكأنها من ماله)\nقال له الرجل أحسن والله فقال كذبت قبحك الله فقال والله لئن كان أخذه منك لقد أجاد فصار أولى به منك وإن كنت أخذته منه فما بلغت مبلغه فغضب دعبل وانصرف أخبرني الحسن بن علي قال حدثني ابن مهرويه قال حدثني عبد الله بن محمد بن جرير قال سمعت محمد بن حازم الباهلي يقدم أبا تمام ويفضله ويقول لو لم يقل إلا مرثيته التي أولها\n(أصم بك الناعي وإن كان أسمعا ... )\nوقوله\n(لو يقدرون مشوا على وجناتهم ... وجباههم فضلا عن الأقدام)\nكفتاه أخبرني عمي قال حدثني عبيد الله بن عبد الله بن طاهر قال كان عمارة بن عقيل عندنا يوما فسمع مؤدبا كان لولد أخي يرويهم قصيدة أبي تمام\n(الحق أبلج والسيوف عوار ... )\nفلما بلغ إلى قوله\n(سود اللباس كأنما نسجت لهم ... أيدي السموم مدارعا من قار)\n(بكروا وأسروا في متون ضوامر ... قيدت لهم من مربط النجار)\n(لا يبرحون ومن رآهم خالهم ... أبدا على سفر من الأسفار)\nقال عمارة لله دره ما يعتمد معنى إلا أصاب أحسنه كأنه موقوف عليه أخبرني محمد بن يحيى الصولي قال حدثني أبو ذكوان قال قال لي إبراهيم بن العباس ما اتكلت في مكاتبتي قط إلا على ما جاش به صدري وجلبه خاطري إلا أني قد استحسنت قول أبي تمام\n(فإن باشر الإصحار فالبيض والقنا ... قراه وأحواض المنايا مناهله)\n(وإن يبن حيطانا عليه فإنما ... أولئك عقالاته لا معاقله)","topic":"أخبار أبي تمام ونسبه","topicNo":214,"sp":1,"spl":"المعجبون بشعره كثيرون","partial":1},
{"id":"b214-3","bab":"الجزء 16","sec":"المعجبون بشعره كثيرون","page":"ج16 ص415","text":"(وإلا فأعلمه بأنك ساخط ... عليه فإن الخوف لا شك قاتله)\nأخذت هذا المعنى في بعض رسائلي فقلت فصار ما كان يحرزهم يبرزهم وما كان يعقلهم يعتقلهم قال ثم قال لي إبراهيم إن أبا تمام اخترم وما استمتع بخاطره ولا نزح ركي فكره حتى انقطع رشاء عمره أخبرني محمد قال حدثني أبو الحسين بن السخي قال حدثني الحسين بن عبد الله قال سمعت عمي إبراهيم بن العباس يقول لأبي تمام وقد أنشد شعرا له في المعتصم يا أبا تمام أمراء الكلام رعية لإحسانك أخبرني محمد قال حدثني هارون بن عبد الله قال لي محمد بن جابر الأزدي وكان يتعصب لأبي تمام أنشدت دعبل بن علي شعرا لأبي تمام ولم أعلمه أنه له ثم قلت له كيف تراه قال أحسن من عافية بعد يأس فقلت إنه لأبي تمام فقال لعله سرقه","topic":"أخبار أبي تمام ونسبه","topicNo":214,"sp":2,"spl":"المعجبون بشعره كثيرون — مات أبو تمام فاقتسم الشعراء ما كان يأخذه"},
{"id":"b214-4","bab":"الجزء 16","sec":"مات أبو تمام فاقتسم الشعراء ما كان يأخذه","page":"ج16 ص420","text":"أخبرني محمد قال حدثني أحمد بن يزيد المهلبي عن أبيه قال ما كان أحد من الشعراء يقدر على أن يأخذ درهما بالشعر في حياة أبي\nتمام فلما مات اقتسم الشعراء ما كان يأخذه أخبرني عمي والحسن بن علي ومحمد بن يحيى وجماعة من أصحابنا وأظن أيضا جحظة حدثنا به قالوا حدثنا عبيد الله بن عبد الله بن طاهر قال لما قدم أبو تمام إلى خراسان اجتمع الشعراء إليه وسألوه أن ينشدهم فقال قد وعدني الأمير أن أنشده غدا وستسمعوني فلما دخل على عبد الله أنشده\n(هن عوادي يوسف وصواحبه ... فعزما فقدما أدرك السؤل طالبه)\nلما بلغ إلى قوله\n(وقلقل نأي من خراسان جأشها ... فقلت اطمئني أنضر الروض عازبه)\n(وركب كأطراف الأسنة عرسوا ... على مثلها والليل تسطو غياهبه)\n(لأمر عليهم أن تتم صدوره ... وليس عليهم أن تتم عواقبه)\nصاح الشعراء بالأمير أبي العباس ما يستحق مثل هذا الشعر غير الأمير أعزه الله وقال شاعر منهم يعرف بالرياحي لي عنده أعزه الله جائزة وعدني بها وقد جعلتها لهذا الرجل جزاء عن قوله للأمير فقال له بل نضعفها لك ونقوم له بما يجب له علينا فلما فرغ من القصيدة نثر عليه ألف دينار فلقطها الغلمان ولم يمس منها شيئا فوجد عليه عبد الله وقال يترفع عن بري ويتهاون بما أكرمته به فلم يبلغ ما أراده منه بعد ذلك أخبرني أبو مسلم محمد بن بحر الكاتب وعمي عن الحزنبل عن سعيد بن جابر الكرخي عن أبيه\nأنه حضر أبا دلف القاسم بن عيسى وعنده أبو تمام الطائي وقد أنشده قصيدته\n(على مثلها من أربع وملاعب ... أذيلت مصونات الدموع السواكب)\nفلما بلغ إلى قوله\n(إذا افتخرت يوما تميم بقوسها ... وزادت على ما وطدت من مناقب)\n(فأنتم بذي قار أمالت سيوفكم ... عروش الذين استرهنوا قوس حاجب)\n(محاسن من مجد متى تقرنوا بها ... محاسن أقوام تكن كالمعايب)\nقال أبو دلف يا معشر ربيعة ما مدحتم بمثل هذا الشعر قط فما عندكم لقائله فبادروه بمطارفهم يرمون بها إليه فقال أبو دلف قد قبلها وأعاركم لبسها وسأنوب عنكم في ثوابه تمم القصيدة يا أبا تمام فتممها فأمر له بخمسين ألف درهم وقال والله ما هي بإزاء استحقاقك وقدرك فاعذرنا فشكره وقام ليقبل يده فحلف ألا يفعل ثم قال له أنشدني قولك في محمد بن حميد\n(وما مات حتى مات مضرب سيفه ... من الضرب واعتلت عليه القنا السمر)\n(وقد كان فوت الموت سهلا فرده ... إليه الحفاظ المر والخلق الوعر)\n(فأثبت في مستنقع الموت رجله ... وقال لها من تحت أخمصك الحشر)\n(غدا غدوة والحمد نسج ردائه ... فلم ينصرف إلا وأكفانه الأجر)\n(كأن بني نبهان يوم مصابه ... نجوم سماء خر من بينها البدر)\n(يعزون عن ثاو يعزى به العلى ... ويبكي عليه البأس والجود والشعر)\nأنشده إياها فقال والله لوددت أنها في فقال بل أفدي الأمير بنفسي\nوأهلي وأكون المقدم فقال إنه لم يمت من رثي بهذا الشعر أو مثله","topic":"أخبار أبي تمام ونسبه","topicNo":214,"sp":2,"spl":"المعجبون بشعره كثيرون — مات أبو تمام فاقتسم الشعراء ما كان يأخذه"},
{"id":"b214-5","bab":"الجزء 16","sec":"الواثق وابن أبي دواد وخالد الشيباني يمدحونه","page":"ج16 ص423","text":"أخبرني أبو الحسن الأسدي قال حدثنا الحسن بن عليل العنزي قال حدثني إسحاق بن يحيى الكاتب قال قال الواثق لأحمد بن أبي دواد بلغني أنك أعطيت أبا تمام الطائي في قصيدة مدحك بها ألف دينار قال لم أفعل ذلك يا أمير المؤمنين ولكني أعطيته خمس مئة دينار رعاية للذي قاله للمعتصم\n(فاشدد بهارون الخلافة إنه ... سكن لوحشتها ودار قرار)\n(ولقد علمت بأن ذلك معصم ... ما كنت تتركه بغير سوار)\nابتسم وقال إنه لحقيق بذلك أخبرني علي بن سليمان قال حدثنا محمد بن يزيد النحوي قال خرج أبو تمام إلى خالد بن يزيد بن مزيد وهو بأرمينية فامتدحه فأعطاه عشرة آلاف درهم ونفقة لسفره وقال تكون العشرة الآلاف موفورة فإن أردت الشخوص فاعجل وإن أردت المقام عندنا فلك الحباء والبر قال بل أشخص فودعه ومضت أيام وركب خالد يتصيد فرآه تحت شجرة وبين يديه زكرة فيها شراب وغلام يغنيه بالطنبور فقال أبو تمام قال خادمك وعبدك قال ما فعل المال فقال\n(علمني جودك السماح فما ... أبقيت شيئا لدي من صلتك)\n(ما مر شهر حتى سمحت به ... كأن لي قدرة كمقدرتك)\n(تنفق في اليوم بالهبات وفي الساعة ... ما تجتنيه في سنتك)\n(فلست أدري من أين تنفق لولا ... أن ربي يمد في هبتك)\nأمر له بعشرة أخرى فأخذها وخرج أخبرني محمد بن يحيى الصولي قال حدثنا عون بن محمد الكندي قال حدثنا محمد بن سعد أبو عبد الله الرقي وكان يكتب للحسن بن رجاء قال قدم أبو تمام مادحا للحسن بن رجاء فرأيت منه رجلا عقله وعلمه فوق شعره فاستنشده الحسن ونحن على نبيذ قصيدته اللامية التي امتدحه بها فلما انتهى إلى قوله\n(أنا من عرفت فإن عرتك جهالة ... فأنا المقيم قيامة العذال)\n(عادت له أيامه مسودة ... حتى توهم أنهن ليال)\nقال الحسن والله لا تسود عليك بعد اليوم فلما قال\n(لا تنكري عطل الكريم من الغنى ... فالسيل حرب للمكان العالي)\n(وتنظري حيث الركاب ينصها ... محيي القريض إلى مميت المال)\nقام الحسن بن رجاء على رجليه وقال والله لا أتممتها إلا وأنا قائم فقام أبو تمام لقيامه وقال\n(لما بلغنا ساحة الحسن انقضى ... عنا تملك دولة الإمحال)\n(بسط الرجاء لنا برغم نوائب ... كثرت بهن مصارع الآمال)\n(أغلى عذارى الشعر إن مهورها ... عند الكرام وإن رخصن غوال)\n(ترد الظنون بنا على تصديقها ... ويحكم الآمال في الأموال)\n(أضحى سمي أبيك فيك مصدقا ... بأجل فائدة وأيمن فال)\n(ورأيتني فسألت نفسك سيبها ... لي ثم جدت وما انتظرت سؤالي)\n(كالغيث ليس له - أريد غمامه ... أو لم يرد - بد من التهطال)\nتعانقا وجلسا وقال له الحسن ما أحسن ما جلوت هذه العروس فقال والله لو كانت من الحور العين لكان قيامك لها أوفى مهورها قال محمد بن سعد وأقام شهرين فأخذ على يدي عشرة آلاف درهم وأخذ غير ذلك مما لم أعلم به على بخل كان في الحسن بن رجاء أخبرني الصولي قال حدثني عون بن محمد قال شهدت دعبلا عند الحسن بن رجاء وهو يضع من أبي تمام فاعترضه عصابة الجرجرائي فقال يا أبا علي اسمع مني ما قاله فإن أنت رضيته فذاك وإلا وافقتك على ما تذمه منه وأعوذ بالله فيك من ألا ترضاه ثم أنشده قوله\n(أما إنه لولا الخليط المودع ... ومغنى عفا منه مصيف ومربع)\nفلما بلغ قوله\n(هو السيل إن واجهته انقدت طوعه ... وتقتاده من جانبيه فيتبع)\n(ولم أر نفعا عند من ليس ضائرا ... ولم أر ضرا عند من ليس ينفع)\n(معاد الورى بعد الممات وسيبه ... معاد لنا قبل الممات ومرجع)\nقال له دعبل لم ندفع فضل هذا الرجل ولكنكم ترفعونه فوق قدره\nوتقدمونه على من يتقدمه وتنسبون إليه ما قد سرقه فقال له عصابة إحسانه صيرك له عائبا وعليه عاتبا أخبرني الصولي قال حدثنا الحسن بن وداع كاتب الحسن بن رجاء قال حضرت أبا الحسين محمد بن الهيثم بالجبل وأبو تمام ينشده\n(أسقى ديارهم أجش هزيم ... وغدت عليهم نضرة ونعيم)\nال فلما فرغ أمر له بألف دينار وخلع عليه خلعة حسنة وأقمنا عنده يومنا فلما كان من غد كتب إليه أبو تمام\n(قد كسانا من كسوة الصيف خرق ... مكتس من مكارم ومساع)\n(حلة سابرية ورداء ... كسحا القيض أو رداء الشجاع)\n(كالسراب الرقراق في الحسن إلا ... أنه ليس مثله في الخداع)\n(قصبيا تسترجف الريح متنيه ... بأمر من الهبوب مطاع)\n(رجفانا كأنه الدهر منه ... كبد الضب أو حشا المرتاع)","topic":"أخبار أبي تمام ونسبه","topicNo":214,"sp":3,"spl":"الواثق وابن أبي دواد وخالد الشيباني يمدحونه"},
{"id":"b214-6","bab":"الجزء 16","sec":"الواثق وابن أبي دواد وخالد الشيباني يمدحونه","page":"ج16 ص423","text":"(لازما ما يليه تحسبه جزءا ... من المتنتين والأضلاع)\n(يطرد اليوم ذا الهجير ولو شبه ... في حره بيوم الوداع)\n(خلعة من أغر أروع رحب الصدر ... رحب الفؤاد رحب الذراع)\n(سوف أكسوك ما يعفي عليها ... من ثناء كالبرد برد الصناع)\n(حسن هاتيك في العيون وهذا ... حسنه في القلوب والأسماع)\nقال محمد بن الهيثم ومن لا يعطي على هذا ملكه والله لا بقي في داري ثوب إلا دفعته إلى أبي تمام فأمر له بكل ثوب كان يملكه في ذلك الوقت أخبرنا محمد بن العباس اليزيدي قال حدثني عمي الفضل قال لما شخص أبو تمام إلى عبد الله بن طاهر وهو بخراسان أقبل الشتاء وهو هناك فاستثقل البلد وقد كان عبد الله وجد عليه وأبطأ بجائزته لأنه نثر عليه ألف دينار فلم يمسسها بيده ترفعا عنها فأغضبه وقال يحتقر فعلي ويترفع علي فكان يبعث إليه بالشيء بعد الشيء كالقوت فقال أبو تمام\n(لم يبق للصيف لا رسم ولا طلل ... ولا قشيب فيستكسى ولا سمل)\n(عدل من الدمع أن يبكى المصيف كما ... يبكى الشباب ويبكى اللهو والغزل)\n(يمنى الزمان انقضى معروفها وغدت ... يسراه وهي لنا من بعدها بدل)\nبلغت الأبيات أبا العميثل شاعر آل عبد الله بن طاهر فأتى أبا تمام واعتذر إليه لعبد الله بن طاهر وعاتبه على ما عتب عليه من أجله وتضمن له ما يحبه ثم دخل إلى عبد الله فقال أيها الأمير أتتهاون بمثل أبي تمام وتجفوه فوالله لو لم يكن له ماله من النباهة في قدره والإحسان في شعره والشائع من ذكره لكان الخوف من شره والتوقي لذمه يوجب على مثلك رعايته ومراقبته فكيف وله بنزوعه إليك من الوطن وفراقه السكن وقد قصدك عاقدا بك أمله\nمعملا إليك ركابه متعبا فيك فكره وجسمه وفي ذلك ما يلزمك قضاء حقه حتى ينصرف راضيا ولو لم يأت بفائدة ولا سمع فيك منه ما سمع إلا قوله\n(تقول في قومس صحبي وقد أخذت ... منا السرى وخطا المهرية القود)\n(أمطلع الشمس تبغي أن تؤم بنا ... فقلت كلا ولكن مطلع الجود)\nقال له عبد الله لقد نبهت فأحسنت وشفعت فلطفت وعاتبت فأوجعت ولك ولأبي تمام العتبى ادعه يا غلام فدعاه فنادمه يومه وأمر له بألفي دينار وما يحمله من الظهر وخلع عليه خلعة تامة من ثيابه وأمر ببذرقته إلى آخر عمله","topic":"أخبار أبي تمام ونسبه","topicNo":214,"sp":4,"spl":"الواثق وابن أبي دواد وخالد الشيباني يمدحونه"},
{"id":"b214-7","bab":"الجزء 16","sec":"حديث المعاني وسرقة القصائد","page":"ج16 ص428","text":"أخبرني جحظة قال حدثني ميمون بن هارون قال مر أبو تمام بمخنث يقول لآخر جئتك أمس فاحتجبت عني فقال له السماء إذا احتجبت بالغيم رجي خيرها فتبينت في وجه أبي تمام أنه قد أخذ المعنى ليضمنه في شعره فما لبثنا إلا أياما حتى أنشدت قوله\n(ليس الحجاب بمقص عنك لي أملا ... إن السماء ترجى حين تحتجب)\nخبرني أبو العباس أحمد بن وصيف وأبو عبد الله أحمد بن الحسن بن محمد الأصبهاني ابن عمي قال حدثنا محمد بن موسى بن حماد قال كنا عند دعبل أنا والقاسم في سنة خمس وثلاثين ومئتين بعد قدومه من الشام فذكرنا أبا تمام فثلبه وقال هو سروق للشعر ثم قال لغلامه يا\nثقيف هات تلك المخلاة فجاء بمخلاة فيها دفاتر فجعل يمرها على يده حتى أخرج منها دفترا فقال اقرأوا هذا فنظرنا فيه فإذا فيه قال مكنف أبو سلمى من ولد زهير بن أبي سلمى وكان هجا ذفافة العبسي بأبيات منها\n(إن الضراط به تصاعد جدكم ... فتعاظموا ضرطا بني القعقاع)\nال ثم مات ذفافة بعد ذلك فرثاه فقال\n(أبعد أبي العباس يستعذب الدهر ... فما بعده للدهر حسن ولا عذر)\n(ألا أيها الناعي ذفافة والندى ... تعست وشلت من أناملك العشر)\n(أتنعى لنا من قيس عيلان صخرة ... تفلق عنها من جبال العدا الصخر)\n(إذا ما أبو العباس خلى مكانه ... فلا حملت أنثى ولا نالها طهر)\n(ولا أمطرت أرضا سماء ولا جرت ... نجوم ولا لذت لشاربها الخمر)\n(كأن بني القعقاع يوم مصابه ... نجوم سماء خر من بينها البدر)\n(توفيت الآمال يوم وفاته ... وأصبح في شغل عن السفر السفر)\nم قال سرق أبو تمام أكثر هذه القصيدة فأدخلها في قصيدته\n(كذا فليجل الخطب وليفدح الأمر ... وليس لعين لم يفض ماؤها عذر)\nخبرني الصولي قال حدثني محمد بن موسى قال كان أبو تمام يعشق غلاما خزريا للحسن بن وهب وكان الحسن يتعشق غلاما روميا لأبي تمام فرآه أبو تمام يوما يعبث بغلامه فقال له والله لئن أعنقت إلى الروم لنركضن إلى الخزر فقال له الحسن لو شئت\nحكمتنا واحتكمت فقال أبو تمام أنا أشبهك بداود عليه السلام وأشبه نفسي بخصمه فقال الحسن لو كان هذا منظوما خفناه فأما وهو منثور فلا لأنه عارض لا حقيقة له فقال أبو تمام\n(أبا علي لصرف الدهر والغير ... وللحوادث والأيام والعبر)\n(أذكرتني أمر داود وكنت فتى ... مصرف القلب في الأهواء والفكر)\n(أعندك الشمس لم يحظ المغيب بها ... وأنت مضطرب الأحشاء للقمر)\n(إن أنت لم تترك السير الحثيث إلى ... جآذر الروم أعنقنا إلى الخزر)\n(إن القطوب له مني محل هوى ... يحل مني محل السمع والبصر)\n(ورب أمنع منه جانبا وحمى ... أمسى وتكته مني على خطر)\n(جردت فيه جنود العزم فانكشفت ... منه غيابتها عن نيكة هدر)\n(سبحان من سبحته كل جارحة ... ما فيك من طمحان الأير والنظر)\n(أنت المقيم فما تغدو رواحله ... وأيره أبدا منه على سفر)\nخبرني الصولي قال حدثني عبد الله بن الحسين قال حدثني وهب بن سعيد قال جاء دعبل إلى الحسن بن وهب في حاجة بعد موت أبي تمام فقال له رجل في المجلس يا أبا علي أنت الذي تطعن علي من يقول\n(شهدت لقد أقوت مغانيكم بعدي ... ومحت كما محت وشائع من برد)\n(وأنجدتم من بعد إتهام داركم ... فيا دمع أنجدني على ساكني نجد)\nفصاح دعبل أحسن والله وجعل يردد فيا دمع أنجدني على ساكني نجد ثم قال رحمه الله لو كان ترك لي شيئا من شعره لقلت إنه أشعر الناس أخبرني علي بن سليمان ومحمد بن يحيى قالا حدثنا محمد بن يزيد قال مات لعبد الله بن طاهر ابنان صغيران في يوم واحد فدخل عليه أبو تمام فأنشده\n(ما زالت الأيام تخبر سائلا ... أن سوف تفجع مسهلا أو عاقلا)\n(مجد تأوب طارقا حتى إذا ... قلنا أقام الدهر أصبح راحلا)\n(نجمان شاء الله ألا يطلعا ... إلا ارتداد الطرف حتى يأفلا)\n(إن الفجيعة بالرياض نواضرا ... لأجل منها بالرياض ذوابلا)\n(لو ينسبان لكان هذا غاربا ... للمكرمات وكان هذا كاهلا)\n(لهفي على تلك المخايل منهما ... لو أمهلت حتى تكون شمائلا)\n(لغدا سكونهما حجى وصباهما ... حلما وتلك الأريحية نائلا)\n(إن الهلال إذا رأيت نموه ... أيقنت أن سيكون بدرا كاملا)\n\n(بالله قل يا طلل ... أهلك ماذا فعلوا)\n(فإن قلبي حذر ... من أن يبينوا وجل)\nروضه من - الرجز - الشعر لأبي الشيص والغناء لأحمد بن يحيى المكي - خفيف ثقيل - بالوسطى من نسخة عمرو بن بانة الثانية ومن رواية الهشامي","topic":"أخبار أبي تمام ونسبه","topicNo":214,"sp":5,"spl":"حديث المعاني وسرقة القصائد","song":1},
{"id":"b215-1","bab":"الجزء 16","sec":"أخبار أبي الشيص ونسبه","page":"ج16 ص432","text":"اسمه محمد بن رزين بن سليمان بن تميم بن نهشل وقيل ابن بهيش - ابن خراش بن خالد بن عبد بن دعبل بن أنس بن خزيمة بن سلامان بن أسلم بن أفصى بن حارثة بن عمرو مزيقيا ابن عامر بن ثعلبة وكان أبو الشيص لقبا غلب عليه وكنيته أبو جعفر وهو ابن عم دعبل بن علي بن رزين لحا وكان أبو الشيص من شعراء عصره متوسط المحل فيهم غير نبيه الذكر لوقوعه بين مسلم بن الوليد وأشجع وأبي نواس فخمل وانقطع إلى عقبة بن جعفر بن الأشعث الخزاعي وكان أميرا على الرقة فمدحه بأكثر شعره فقلما يروى له في غيره وكان عقبة جوادا فأغناه عن غيره ولأبي الشيص ابن يقال له عبد الله شاعر أيضا صالح الشعر وكان منقطعا إلى محمد بن طالب فأخذ منه جامع شعر أبيه ومن جهته خرج إلى الناس وعمي أبو الشيص في آخر عمره وله مراث في عينيه قبل ذهابهما وبعده نذكر منها مختارها مع أخباره وكان سريع الهاجس جدا فيما ذكر عنه فحكى عبد الله بن المعتز أن أبا\nخالد العامري قال له من أخبرك أنه كان في الدنيا أشعر من أبي الشيص فكذبه والله لكان الشعر عليه أهون من شرب الماء على العطشان وكان من أوصف الناس للشراب وأمدحهم للملوك وهكذا ذكر ابن المعتز وليس توجد هذه الصفات كما ذكر في ديوان شعره ولا هو بساقط ولكن هذا سرف شديد أخبرني عمي قال حدثنا الكراني عن النضر بن عمر قال قال لي أبو الشيص لما مدحت عقبة بن جعفر بقصيدتي التي أولها\n(لا تنكري صدي ولا إعراضي ... ليس المقل عن الزمان براض)\nمر بأن تعد وأعطاني لكل بيت ألف درهم أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال أنشدت إبراهيم بن المهدي أبيات أبي يعقوب الخريمي التي يرثي بها عينه يقول فيها\n(إذا ما مات بعضك فابك بعضا ... فإن البعض من بعض قريب)\nأنشدني لأبي الشيص يبكي عينيه\n(يا نفس بكي بأدمع هتن ... وواكف كالجمان في سنن)\n(على دليلي وقائدي ويدي ... ونور وجهي وسائس البدن)\n(أبكي عليها بها مخافة أن ... تقرنني والظلام في قرن)\nقال أبو هفان حدثني دعبل أن امرأة لقيت أبا الشيص فقالت يا أبا الشيص عميت بعدي فقال قبحك الله دعوتني باللقب وعيرتني بالضرر","topic":"أخبار أبي الشيص ونسبه","topicNo":215,"sp":0,"spl":"أخبار أبي الشيص ونسبه"},
{"id":"b215-2","bab":"الجزء 16","sec":"مجالس شعرية","page":"ج16 ص434","text":"أخبرني محمد بن القاسم الأنباري قال حدثني أبي عن أحمد بن عبيد قال اجتمع مسلم بن الوليد وأبو نواس وأبو الشيص ودعبل في مجلس فقالوا لينشد كل واحد منكم أجود ما قاله من الشعر فاندفع رجل كان معهم فقال اسمعوا مني أخبركم بما ينشد كل واحد منكم قبل أن ينشد قالوا هات فقال لمسلم أما أنت يا أبا الوليد فكأني بك قد أنشدت\n(إذا ما علت منا ذؤابة واحد ... وإن كان ذا حلم دعته إلى الجهل)\n(هل العيش إلا أن تروح مع الصبا ... وتغدو صريع الكأس والأعين النجل)\nال وبهذا البيت لقب صريع الغواني لقبه به الرشيد فقال له مسلم صدقت ثم أقبل على أبي نواس فقال له كأني بك يا أبا علي قد أنشدت\n(لا تبك ليلى ولا تطرب إلى هند ... واشرب على الورد من حمراء كالورد)\n(تسقيك من عينها خمرا ومن يدها ... خمرا فما لك من سكرين من بد)\nقال له صدقت ثم أقبل على دعبل فقال له وأنت يا أبا علي فكأني بك تنشد قولك\n(أين الشباب وأية سلكا ... لا أين يطلب ضل بل هلكا)\n(لا تعجبي يا سلم من رجل ... ضحك المشيب برأسه فبكى)\nقال صدقت ثم أقبل على أبي الشيص فقال له وأنت يا أبا جعفر فكأني بك وقد أنشدت قولك\n(لا تنكري صدي ولا إعراضي ... ليس المقل عن الزمان براض)\nفقال له لا ما هذا أردت أن أنشد ولا هذا بأجود شيء قلته قالوا فأنشدنا ما بدا له فأنشدهم قوله\n(وقف الهوى بي حيث أنت فليس لي ... متأخر عنه ولا متقدم)\n(أجد الملامة في هواك لذيذة ... حبا لذكرك فليلمني اللوم)\n(أشبهت أعدائي فصرت أحبهم ... إذ كان حظي منك حظي منهم)\n(وأهنتني فأهنت نفسي صاغرا ... ما من يهون عليك ممن يكرم)\nلعريب في هذا الشعر لحنان ثقيل أول ورمل قال فقال أبو نواس أحسنت والله جودت وحياتك لأسرقن هذا المعنى منك ثم لأغلبنك عليه فيشتهر ما أقول ويموت ما قلت قال فسرق قوله\n(وقف الهوى بي حيث أنت فليس لي ... متأخر عنه ولا متقدم)\nرقا خفيا فقال في الخصيب\n(فما جازه جود ولا حل دونه ... ولكن يسير الجود حيث يسير)\nسار بيت أبي نواس وسقط بيت أبي الشيص نسخت من كتاب جدي لأمي يحيى بن محمد بن ثوابة بخطه حدثني الحسن بن سعد قال حدثني رزين بن علي الخزاعي أخو دعبل قال كنا عند أبي نواس أنا ودعبل وأبو الشيص ومسلم بن الوليد الأنصاري فقال أبو نواس لأبي الشيص أنشدني قصيدتك المخزية قال وما هي قال الضادية فما خطر بخلدي قولك\n(ليس المقل عن الزمان براض ... )\nلا أخزيتك استحسانا لها فإن الأعشى كان إذا قال القصيدة عرضها على ابنته وقد كان ثقفها وعلمها ما بلغت به استحقاق التحكيم الإختيار لجيد الكلام ثم يقول لها عدي لي المخزيات فتعد قوله\n(أغر أروع يستسقى الغمام به ... لو قارع الناس عن أحسابهم قرعا)\nما أشبهها من شعره قال أبو الشيص لا أفعل إنها ليست عندي عقد در مفصل ولكني أكاثر بغيرها ثم أنشده قوله\n(وقف الهوى بي حيث أنت فليس لي ... متأخر عنه ولا متقدم)\nلأبيات المذكورة فقال له أبو نواس قد أردت صرفك عنها فأبيت أن تخلى عن سلبك أو تدرك في هربك قال بل أقول في طلبي فكيف رأيت هذا الطراز قال أرى نمطا خسروانيا مذهبا حسنا فكيف تركت\n(في رداء من الصفيح صقيل ... وقميص من الحديد مذال)\nقال تركته كما ترك مختار الدرتين إحداهما بما سبق في ألحاظه وزين في ناظره أخبرني الحسن بن علي قال حدثني ابن مهرويه قال حدثني أبي قال حدثني من قال لأبي نواس من أشعر طبقات المحدثين قال الذي يقول\n(يطوف علينا بها أحور ... يداه من الكأس مخضوبتان)\nالشعر لأبي الشيص\nأخبرني الحسين بن القاسم الكوكبي قال حدثني الفضل بن موسى بن معروف الأصبهاني قال حدثني أبي قال دخل أبو الشيص على أبي دلف وهو يلاعب خادما له بالشطرنج فقيل له يا أبا الشيص سل هذا الخادم أن يحل أزرار قميصه فقال أبو الشيص الأمير أعزه الله أحق بمسألته قال قد سألته فزعم أنه يخاف العين على صدره فقل فيه شيئا فقال\n(وشادن كالبدر يجلو الدجى ... في الفرق منه المسك مذرور)\n(يحاذر العين على صدره ... فالجيب منه الدهر مزرور)","topic":"أخبار أبي الشيص ونسبه","topicNo":215,"sp":1,"spl":"مجالس شعرية","song":1,"partialRef":{"sid":"b215-1","gi":0,"vi":0,"side":1},"partial":1},
{"id":"b215-3","bab":"الجزء 16","sec":"مجالس شعرية","page":"ج16 ص434","text":"قال أبو دلف وحياتي لقد أحسنت وأمر له بخمسة آلاف درهم فقال الخادم قد والله أحسن كما قلت ولكنك أنت ما أحسنت فضحك وأمر له بخمسة آلاف أخرى أخبرني محمد بن عمران الصيرفي قال حدثنا الحسن بن عليل العنزي قال حدثني علي بن سعد بن إياس الشيباني قال تعشق أبو الشيص محمد بن رزين قينة لرجل من أهل بغداد فكان يختلف إليها وينفق عليها في منزل الرجل حتى أتلف مالا كثيرا فلما كف بصره وأخفق جعل إذا جاء إلى مولى الجارية حجبه ومنعه من الدخول فجاءني أبو الشيص فشكا إلي وجده بالجارية واستخفاف مولاها به وسألني المضي معه إليه فمضيت معه فاستؤذن لنا عليه فأذن فدخلت أنا وأبو الشيص فعاتبته في أمره وعظمت عليه حقه وخوفته من لسانه ومن إخوانه فجعل له يوما في الجمعة يزورها فيه فكان يأكل في بيته ويحمل معه نبيذه ونقله فمضيت معه ذات يوم إليها فلما وقفنا على بابهم سمعنا صراخا شديدا\nمن الدار فقال لي ما لها تصرخ أتراه قد مات لعنه الله فما زلنا ندق الباب حتى فتح لنا فإذا هو قد حسر كميه وبيده سوط وقال لنا ادخلا فدخلنا وإنما حمله على الإذن لنا الفرق مني فدخلنا وعاد الرجل إلى داخل يضربها فاستمعنا عليه وأطلعنا فإذا هي مشدودة على سلم وهو يضربها أشد ضرب وهي تصرخ وهو يقول وأنت أيضا فاسرقي الخبز فاندفع أبو الشيص على المكان يقول في ذلك\n(يقول والسوط على كفه ... قد حز في جلدتها حزا)\n(وهي على السلم مشدودة ... وأنت أيضا فاسرقي الخبزا)\nال وجعل أبو الشيص يرددهما فسمعهما الرجل فخرج إلينا مبادرا وقال له أنشدني البيتين اللذين قلتهما فدافعه فحلف أنه لا بد من إنشادهما فأنشده إياهما فقال لي يا أبا الحسن أنت كنت شفيع هذا وقد أسعفتك بما تحب فإن شاع هذان البيتان فضحتني فقل له يقطع هذا ولا يسمعهما وله علي يومان في الجمعة ففعلت ذلك ووافقته عليه فلم يزل يتردد إليه يومين في الجمعة حتى مات أخبرني محمد بن خلف بن المرزبان قال حدثني أحمد بن عبد الرحمن الكاتب عن أبيه قال كانت لأبي الشيص جارية سوداء اسمها تبر وكان يتعشقها وفيها يقول\n(لم تنصفي يا سمية الذهب ... تتلف نفسي وأنت في لعب)\n(يابنة عم المسك الذكي ومن ... لولاك لم يتخذ ولم يطب)\n(ناسبك المسك في السواد وفي الريح ... فأكرم بذاك من نسب)\nخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثنا علي بن محمد النوفلي عن عمه قال كان أبو الشيص صديقا لمحمد بن إسحاق بن سليمان الهاشمي وهما\nحينئذ مملقان فنال محمد بن إسحاق مرتبة عند سلطانه واستغنى فجفا أبا الشيص وتغير له فكتب إليه\n(الحمد لله رب العالمين على ... قربي وبعدك مني يابن إسحاق)\n(يا ليت شعري متى تجدي علي وقد ... أصبحت رب دنانير وأوراق)\n(تجدي علي إذا ما قيل من راق ... والتفت الساق عند الموت بالساق)\n(يوم لعمري تهم الناس أنفسهم ... وليس ينفع فيه رقية الراقي)\nدثني محمد بن العباس اليزيدي قال حدثنا أبو العباس بن الفرات قال كنت أسير مع عبيد الله بن سليمان فاستقبله جعفر بن حفص على دابة هزيل وخلفه غلام له وشيخ على بغل له هرم وما فيهم إلا نضو فأقبل علي عبيد الله بن سليمان فقال كأنهم والله صفة أبي الشيص حيث يقول\n(أكل الوجيف لحومها ولحومهم ... فأتوك أنقاضا على أنقاض)","topic":"أخبار أبي الشيص ونسبه","topicNo":215,"sp":2,"spl":"مجالس شعرية"},
{"id":"b215-4","bab":"الجزء 16","sec":"مقتل أبي الشيص","page":"ج16 ص439","text":"وقال عبد الله بن المعتز حدثني أبو مالك عبد الله قال قال لي عبد الله بن الأعمش كان أبو الشيص عند عقبة بن جعفر بن الأشعث الخزاعي يشرب فلما ثمل نام عنده ثم انتبه في بعض الليل فذهب يدب إلى خادم له فوجأه بسكين فقال له ويحك قتلتني والله وما أحب والله أن أفتضح أني قتلت في مثل هذا ولا تفضح أنت بي ولكن خذ دستيجة فاكسرها ولوثها بدمي\nواجعل زجاجها في الجرح فإذا سئلت عن خبري فقل إني سقطت في سكري على الدستيجة فانكسرت فقتلتني ومات من ساعته ففعل الخادم ما أمره به ودفن أبو الشيص وجزع عقبة عليه جزعا شديدا فلما كان بعد أيام سكر الخادم فصدق عقبة عن خبره وأنه هو قتله فلم يلبثه أن قام إليه بسيفه فلم يزل يضربه حتى قتله\n(هلا سألت معالم الأطلال ... والرسم بعد تقادم الأحوال)\n(دمنا تهيج رسومها بعد البلى ... طربا وكيف سؤال أعجم بال)\n(يمشين مشي قطا البطاح تأودا ... قب البطون رواجح الأكفال)\n(من كل آنسة الحديث حيية ... ليست بفاحشة ولا متفال)\n(أقصى مذاهبها إذا لاقيتها ... في الشهر بين أسرة وحجال)\n(وتكون ريقتها إذا نبهتها ... كالشهد أو كسلافة الجريال)\nلمتفال المنتنة الريح والجريال فيما قيل اسم للون الخمر وقيل بل هو من أسمائها والدليل على أنه لونها قول الأعشى\n(وسلافة مما تعتق بابل ... كدم الذبيح سلبتها جريالها)\nال سماك بن حرب حدثني يحنس بن متى الحيري راوية الأعشى أنه سأله عن هذا البيت فقال شربتها حمراء وبلتها بيضاء\nالشعر في هذا الغناء المذكور للكميت بن زيد والغناء لابن سريج ثقيل أول بالبنصر عن عمرو بن بانة وذكر المكي أنه لابن محرز وفيه لعطرد - خفيف ثقيل - وهذا الشعر من قصيدة للكميت يمدح بها مخلد بن يزيد بن المهلب يقول فيها\n(قاد الجيوش لخمس عشرة حجة ... ولداته عن ذاك في أشغال)\n(قعدت بهم هماتهم وسمت به ... همم الملوك وسورة الأبطال)\n(فكأنما عاش المهلب بينهم ... بأغر قاس مثاله بمثال)\n(في كفه قصبات كل مقلد ... يوم الرهان وفوز كل نصال)\n(ومتى أزنك بمعشر وأزنهم ... بك ألف وزنك أرجح الأثقال)\nم الجزء السادس عشر من كتاب الأغاني","topic":"أخبار أبي الشيص ونسبه","topicNo":215,"sp":3,"spl":"مقتل أبي الشيص","song":1}]);